window.SG_BOOK = {"chapters":[{"id":"c01","ja":"情報セキュリティ","zh":"信息安全","count":164,"syllabus":"シラバス4.1"},{"id":"c02","ja":"情報セキュリティ管理","zh":"信息安全管理","count":129,"syllabus":"シラバス4.1"},{"id":"c03","ja":"セキュリティ技術評価","zh":"安全技术评估","count":3,"syllabus":"シラバス4.1"},{"id":"c04","ja":"情報セキュリティ対策","zh":"信息安全对策","count":75,"syllabus":"シラバス4.1"},{"id":"c05","ja":"セキュリティ実装技術","zh":"安全实施技术","count":32,"syllabus":"シラバス4.1"},{"id":"c06","ja":"知的財産権","zh":"知识产权","count":4,"syllabus":"シラバス4.1"},{"id":"c07","ja":"セキュリティ関連法規","zh":"信息安全相关法规","count":32,"syllabus":"シラバス4.1"},{"id":"c08","ja":"労働関連・取引関連法規","zh":"劳动与交易相关法规","count":14,"syllabus":"シラバス4.1"},{"id":"c09","ja":"その他の法律・ガイドライン・技術者倫理","zh":"其他法律、指南与技术人员伦理","count":13,"syllabus":"シラバス4.1"},{"id":"c10","ja":"標準化関連","zh":"标准化相关","count":6,"syllabus":"シラバス4.1"},{"id":"c11","ja":"システムの構成","zh":"系统构成","count":35,"syllabus":"シラバス4.1"},{"id":"c12","ja":"システムの評価指標","zh":"系统评价指标","count":7,"syllabus":"シラバス4.1"},{"id":"c13","ja":"データベース方式","zh":"数据库方式","count":2,"syllabus":"シラバス4.1"},{"id":"c14","ja":"データベース設計","zh":"数据库设计","count":3,"syllabus":"シラバス4.1"},{"id":"c15","ja":"データ操作","zh":"数据操作","count":1,"syllabus":"シラバス4.1"},{"id":"c16","ja":"トランザクション処理","zh":"事务处理","count":6,"syllabus":"シラバス4.1"},{"id":"c17","ja":"データベース応用","zh":"数据库应用","count":3,"syllabus":"シラバス4.1"},{"id":"c18","ja":"ネットワーク方式","zh":"网络方式","count":20,"syllabus":"シラバス4.1"},{"id":"c19","ja":"データ通信と制御","zh":"数据通信与控制","count":14,"syllabus":"シラバス4.1"},{"id":"c20","ja":"通信プロトコル","zh":"通信协议","count":21,"syllabus":"シラバス4.1"},{"id":"c21","ja":"ネットワーク管理","zh":"网络管理","count":4,"syllabus":"シラバス4.1"},{"id":"c22","ja":"ネットワーク応用","zh":"网络应用","count":48,"syllabus":"シラバス4.1"},{"id":"c23","ja":"プロジェクトマネジメント","zh":"项目管理","count":8,"syllabus":"シラバス4.1"},{"id":"c24","ja":"プロジェクトの統合","zh":"项目整合","count":5,"syllabus":"シラバス4.1"},{"id":"c25","ja":"プロジェクトのステークホルダ","zh":"项目干系人","count":2,"syllabus":"シラバス4.1"},{"id":"c26","ja":"プロジェクトのスコープ","zh":"项目范围","count":4,"syllabus":"シラバス4.1"},{"id":"c27","ja":"プロジェクトの資源","zh":"项目资源","count":1,"syllabus":"シラバス4.1"},{"id":"c28","ja":"プロジェクトの時間","zh":"项目进度与时间","count":5,"syllabus":"シラバス4.1"},{"id":"c29","ja":"プロジェクトのコスト","zh":"项目成本","count":2,"syllabus":"シラバス4.1"},{"id":"c30","ja":"プロジェクトのリスク","zh":"项目风险","count":2,"syllabus":"シラバス4.1"},{"id":"c31","ja":"プロジェクトの品質","zh":"项目质量","count":2,"syllabus":"シラバス4.1"},{"id":"c32","ja":"プロジェクトの調達","zh":"项目采购","count":1,"syllabus":"シラバス4.1"},{"id":"c33","ja":"プロジェクトのコミュニケーション","zh":"项目沟通","count":7,"syllabus":"シラバス4.1"},{"id":"c34","ja":"サービスマネジメント","zh":"服务管理","count":6,"syllabus":"シラバス4.1"},{"id":"c35","ja":"サービスマネジメントシステムの計画及び運用","zh":"服务管理体系的策划与运行","count":62,"syllabus":"シラバス4.1"},{"id":"c36","ja":"パフォーマンス評価及び改善","zh":"绩效评价与改进","count":6,"syllabus":"シラバス4.1"},{"id":"c37","ja":"サービスの運用","zh":"服务运营","count":3,"syllabus":"シラバス4.1"},{"id":"c38","ja":"ファシリティマネジメント","zh":"设施管理","count":4,"syllabus":"シラバス4.1"},{"id":"c39","ja":"システム監査","zh":"系统审计","count":16,"syllabus":"シラバス4.1"},{"id":"c40","ja":"内部統制","zh":"内部控制","count":13,"syllabus":"シラバス4.1"},{"id":"c41","ja":"情報システム戦略","zh":"信息系统战略","count":2,"syllabus":"シラバス4.1"},{"id":"c42","ja":"業務プロセス","zh":"业务流程","count":11,"syllabus":"シラバス4.1"},{"id":"c43","ja":"ソリューションビジネス","zh":"解决方案业务","count":6,"syllabus":"シラバス4.1"},{"id":"c44","ja":"システム活用促進・評価","zh":"信息系统应用促进与评价","count":15,"syllabus":"シラバス4.1"},{"id":"c45","ja":"システム化計画","zh":"信息化计划","count":9,"syllabus":"シラバス4.1"},{"id":"c46","ja":"要件定義","zh":"需求定义","count":14,"syllabus":"シラバス4.1"},{"id":"c47","ja":"調達計画・実施","zh":"采购计划与实施","count":30,"syllabus":"シラバス4.1"},{"id":"c48","ja":"経営・組織論","zh":"经营与组织理论","count":17,"syllabus":"シラバス4.1"},{"id":"c49","ja":"業務分析・データ利活用","zh":"业务分析与数据利用","count":30,"syllabus":"シラバス4.1"},{"id":"c50","ja":"会計・財務","zh":"会计与财务","count":16,"syllabus":"シラバス4.1"}],"entries":[{"id":"t0001","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"情報セキュリティの概念","termZh":"信息安全概念","english":"Information Security Concept","reading":"じょうほうせきゅりてぃのがいねん","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報を保護するための基本的な考え方のことである。具体的には、情報の機密性、完全性、可用性を維持することを目的としている。機密性は情報が不正にアクセスされないようにすることを意味し、完全性は情報が未承認で変更されないことを確保することである。そして、可用性は必要なときに情報にアクセスできることを指す。これらの要素は、企業や組織が情報を安全に管理し、外部からの脅威や内部のリスクから守るために不可欠である。情報セキュリティは、技術的な対策だけでなく、教育やポリシーの策定も含む広範な概念であり、デジタル社会においてますます重要になっている。","explanationZh":"指保护信息的基本思想，其核心目标是维持信息的机密性、完整性和可用性。机密性要求信息只能由获授权人员访问；完整性确保信息不会被未经授权地修改；可用性则保证在需要时能够访问和使用信息。这些要素是企业和组织安全管理信息、抵御外部威胁和内部风险的基础。信息安全不仅包括技术措施，也涵盖人员教育、制度与安全策略的制定，是数字社会中的重要基础。"},{"id":"t0002","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"機密性","termZh":"机密性","english":"Confidentiality","reading":"きみつせい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報が許可された者だけにアクセスできることを保証するセキュリティの目的である。つまり、機密性が確保されている情報は、未承認の第三者から保護され、秘密が守られる仕組みを持つ。この概念は、顧客情報や機密文書、企業の知的財産などにおいて特に重要である。実現するためには、パスワードや暗号技術、アクセス制御などの技術が用いられ、データの漏洩や不正アクセスを防ぐための対策が講じられる。結果として、機密性が維持されることで、信頼性の高い情報管理が可能となる。","explanationZh":"信息安全的基本目标之一，指确保信息仅能被获得授权的人员、实体或过程访问。具备机密性的信息应受到保护，防止未经授权的第三方获取或泄露。客户信息、机密文件和企业知识产权等尤其需要保障机密性。常见措施包括密码、加密技术和访问控制等，以防止数据泄露和未授权访问，从而实现可信的信息管理。"},{"id":"t0003","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"完全性","termZh":"完整性","english":"Integrity","reading":"かんぜんせい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"データが正確であり、完全で変わらない状態を保つことを指す情報セキュリティの概念である。データの完全性が保証されている場合、情報が不正に改ざんされたり、消失したりすることがない。例えば、金融機関のデータは、正確な取引情報が必要であり、変更が行われた場合は、その記録がすぐに確認できる仕組みが必要とされる。これにより、法的な問題や信頼性の低下を防ぐことができる。情報システムが適切に機能するための基本的な要素であり、データを守るために暗号化やアクセス制御などの技術が用いられることが多い。","explanationZh":"指数据保持准确、完整且未被未经授权修改的安全属性。完整性得到保证时，信息不会被非法篡改、破坏或丢失。例如金融机构必须确保交易数据准确，并能对发生的变更进行记录和核验，以避免法律问题和可信度下降。完整性是信息系统正常运行的基本要素，通常通过访问控制、校验、数字签名等措施加以保障。"},{"id":"t0004","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"可用性","termZh":"可用性","english":"Availability","reading":"かようせい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報システムやサービスが必要な時に利用できる状態を維持することを指す概念である。情報セキュリティにおいては、システムがダウンしたりアクセスが制限されたりしないよう、様々な対策を講じることが求められる。具体的には、サーバの冗長化やバックアップ、障害復旧の計画などが含まれる。可用性が確保されていれば、ユーザーは情報やサービスにアクセスできるため、業務や日常的な活動が円滑に行われる。逆に、可用性が低下すると、信頼性や顧客満足度に影響を及ぼす可能性があるため、十分な配慮が必要である。","explanationZh":"指信息系统、服务或信息资源在需要时能够被授权用户正常访问和使用的状态。为保证可用性，需要避免系统宕机或访问受阻，并采取服务器冗余、备份、故障恢复和灾难恢复计划等措施。可用性良好可确保业务连续运行；可用性下降则可能影响系统可靠性、业务运营和客户满意度。"},{"id":"t0005","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"真正性","termZh":"真实性","english":"Authenticity","reading":"しんせいせい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報やデータが本物であること、またはその出所が信頼できることを保証する特性である。情報セキュリティの文脈において、真正性は非常に重要であり、データが改ざんされていないことや、発信者が信頼できる人物であることを確認できることを指す。例えば、電子署名はデジタル文書の真正性を保証するために使われ、受け取った文書が真の発信者からのものであることを確認する役割を果たしている。これにより、フィッシングや詐欺といったリスクを軽減し、信頼性のある情報交換が可能となる。","explanationZh":"指能够确认信息、数据或其来源确实真实可信的安全属性。在信息安全中，真实性用于确认数据未被伪造，发送者或通信对象的身份可信。例如数字签名可用于验证电子文档确由声称的发送者发出，并辅助确认内容未被篡改。保障真实性有助于降低钓鱼、诈骗和身份冒充等风险，实现可信的信息交换。"},{"id":"t0006","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"責任追跡性","termZh":"可追责性（责任可追溯性）","english":"Accountability","reading":"せきにんついせきせい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報セキュリティの分野において、誰がどの行動を行ったのかを明確にし、その結果に対して責任を持つことを指す概念である。具体的には、ユーザーの操作やシステムの変更について、ログを記録し、追跡することで、意図しない行動や不正アクセスが発生した際に、その原因を特定することが可能になる。これにより、組織はセキュリティの向上やトラブル発生時の迅速な対応ができるようになる。信頼の構築や法規制の遵守にも重要な要素となり、より安全な情報環境を実現するために欠かせない。","explanationZh":"指能够明确识别“谁在何时执行了什么操作”，并使相关主体对其行为及结果承担责任的能力。通常通过记录用户操作、系统变更和安全日志来实现，以便发生误操作或未授权访问时能够追踪原因和责任主体。可追责性有助于提升安全管理水平、加快事件调查与响应，并支持审计、合规和组织信任建设。"},{"id":"t0007","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"否認防止","termZh":"不可否认性","english":"Non-Repudiation","reading":"ひにんぼうし","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報の送信者や受信者が、その行為を否定できないようにする仕組みを指すものである。この概念は主に電子取引や通信において重要であり、相手に届いた証拠を提供することで、信頼性を確保する役割を果たす。例えば、インターネットでの契約や取引では、双方が合意した内容が記録されるデジタル署名やタイムスタンプが用いられる。これにより、後になってその内容を「知らなかった」や「行っていない」と主張することができなくなるため、トラブルを防ぐ効果がある。情報セキュリティの基本的な目的の一つとして、データの整合性と信頼性を高めることに寄与している。","explanationZh":"指通过技术或管理机制，使信息发送方或接收方事后不能否认其已经实施的发送、接收、签署或交易行为。该属性在电子交易和网络通信中尤为重要，通常通过数字签名、时间戳和可信记录等提供证据。例如在线合同的签署记录可以证明双方曾对特定内容达成一致，从而降低事后否认和纠纷风险，并提升交易的完整性与可信度。"},{"id":"t0008","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"信頼性","termZh":"可靠性","english":"Reliability","reading":"しんらいせい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"システムやサービスが期待通りの機能を持ち、安定して動作する能力を指す概念である。この特性は、特に情報セキュリティにおいて重要であり、ユーザーが安心してシステムを使用できることを保証する。例えば、オンラインバンキングやクラウドストレージのサービスでは、信頼性が高いことで利用者のデータが安全に保存され、不正アクセスやデータ損失のリスクが低減される。信頼性を確保するためには、定期的なメンテナンスや監査、効果的なバックアップシステムの実装が求められる。これにより、システムの可用性や性能が向上し、結果として利用者の信頼を得ることができる。","explanationZh":"指系统或服务能够按照预期功能持续、稳定地运行并提供正确结果的能力。可靠性较高的系统能够降低数据丢失、异常中断和故障带来的风险，使用户可以安心使用。在线银行、云存储等服务通常通过定期维护、监控、审计、冗余和有效备份来提高可靠性，从而提升系统可用性、性能和用户信任。"},{"id":"t0009","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"多層防御","termZh":"纵深防御","english":"Defense in Depth","reading":"たそうぼうぎょ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報セキュリティにおける防御策の一つである。この考え方は、単一の防御に依存するのではなく、複数の防御層を駆使して、より高いセキュリティを実現することを目的としている。具体的には、ネットワークのファイアウォールやウイルス対策ソフトウェア、アクセス制御、ユーザー教育など、さまざまな手段を組み合わせて使用する。これにより、一つの防御層が破られても次の層が防御機能を果たすことができ、全体としてのセキュリティが向上する。企業や組織がサイバー攻撃から身を守るために非常に有効な手法である。","explanationZh":"一种不依赖单一安全措施、而是部署多层相互补充防护机制的安全思想。常见防护层包括网络防火墙、反恶意软件、身份认证与访问控制、终端防护、日志监控以及用户安全教育等。即使某一层被突破，后续防护层仍可继续发挥作用，从而降低整体被攻破的概率，是组织抵御网络攻击的重要方法。"},{"id":"t0010","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"セキュリティバイデザイン","termZh":"安全设计（Security by Design）","english":"Security by Design","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報システムやソフトウェアの開発において、最初からセキュリティを考慮に入れるアプローチである。この考え方は、後からセキュリティ対策を追加するのではなく、設計段階から脅威やリスクを予測し、それらに対処する仕組みを組み込むことを目的としている。具体的には、ユーザー認証やデータ暗号化などの機能を初めから設定し、システム全体の安全性を高めることができる。これにより、開発コストの削減や、運用中のセキュリティ事故を防ぐ効果が期待できる。デジタル社会において、信頼性の高いシステム構築に不可欠な考え方である。","explanationZh":"指在信息系统或软件的规划、需求和设计阶段就将安全要求纳入体系，而不是在开发完成后再追加安全措施。其核心是提前识别威胁和风险，并在架构中内置身份认证、访问控制、数据加密等安全机制。这样可以提高系统整体安全性，并减少后期整改成本和运行阶段发生安全事故的概率，是构建可信系统的重要理念。"},{"id":"t0011","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"プライバシーバイデザイン","termZh":"隐私保护设计（Privacy by Design）","english":"Privacy by Design","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報システムやサービスの設計段階から個人情報の保護を組み込む考え方である。このアプローチは、データ収集や処理の過程で個人のプライバシーを最優先することを目指しており、開発者は初めからプライバシーの保護を意識して設計を行う。例えば、新しいアプリを開発する際には、ユーザーの同意を得る仕組みや、必要最低限の情報だけを収集するルールを設定することが重要である。これにより、利用者の信頼性を高めると同時に、法的な問題を回避する効果もある。","explanationZh":"指从信息系统或服务的设计阶段开始，就把个人信息和隐私保护要求内置到产品与业务流程中。开发者应在数据收集、处理、保存和共享的全过程优先考虑隐私，例如建立用户同意机制、遵循数据最小化原则，只收集实现目的所必需的信息。该方法有助于提高用户信任并降低隐私侵害和合规风险。"},{"id":"t0012","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"情報資産","termZh":"信息资产","english":"Information Asset","reading":"じょうほうしさん","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"企業や組織が保持する情報のことであり、重要な資源として扱われる。これには、データベース内の顧客情報、財務情報、知的財産などが含まれ、これらは組織の運営や競争力に直結する重要な要素である。例えば、企業が持つ顧客データは、マーケティング戦略の決定において重要な役割を果たす。このため、その価値を保護するための情報セキュリティ対策が不可欠であり、適切な管理や権限設定、暗号化などが求められる。その結果、情報漏洩や不正アクセスから資産を守ることが、組織の持続可能性や信頼性を高めることに繋がる。","explanationZh":"指企业或组织所拥有、管理或使用并具有业务价值的信息及相关资源，例如客户数据、财务信息、技术资料和知识产权等。信息资产直接关系到组织运营和竞争力，因此需要根据其价值和敏感程度实施适当保护，包括分类管理、访问权限控制、加密和备份等。有效保护信息资产能够降低泄露和未授权访问风险，并增强组织的持续经营能力和可信度。"},{"id":"t0013","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"脅威","termZh":"威胁","english":"Threat","reading":"きょうい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報セキュリティにおいて、情報資産に対して損害を与える可能性のある存在や状況を指す。具体的には、ハッカーによる攻撃や、ウイルス、マルウェアなどが脅威となる。例えば、企業の顧客データがハッカーに侵入されて盗まれたり、システムがウイルスによって破壊されるリスクがある。脅威は常に進化しており、新たな手法が登場することでセキュリティ対策も強化が求められる。そのため、脅威を特定し、適切な対策を講じることが情報セキュリティの重要な要素となっている。","explanationZh":"指可能对信息资产造成损害的主体、事件、行为或环境因素。例如攻击者、计算机病毒、恶意软件、自然灾害和内部人员违规等都可能成为威胁。威胁会随着技术和攻击手法不断变化，因此信息安全管理需要持续识别和评估威胁，并采取相应的预防、检测和响应措施。"},{"id":"t0014","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"脆弱性","termZh":"脆弱性","english":"Vulnerability","reading":"ぜいじゃくせい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"システムやアプリケーションに存在する弱点や欠陥のことである。これらの脆弱性が悪用されると、攻撃者が不正にアクセスしたり、データを盗んだりする原因となる。例えば、ソフトウェアにバグが含まれている場合、そのバグを悪用されることで、サイバー攻撃が実行されることがある。このように、脆弱性を適切に管理し修正することは、情報セキュリティを維持するために非常に重要である。定期的なソフトウェアのアップデートや、セキュリティ対策の導入により、脆弱性を軽減し、システムをより安全に保つ努力が求められる。","explanationZh":"指系统、应用程序、设备、配置或管理流程中可被威胁利用的弱点或缺陷。攻击者一旦利用脆弱性，可能导致未授权访问、数据泄露或系统被控制。例如软件缺陷可能形成可被利用的安全漏洞。为了降低风险，应持续开展漏洞管理，及时更新和修补软件，并配置适当的安全控制措施。"},{"id":"t0015","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"サイバー攻撃","termZh":"网络攻击","english":"Cyber Attack","reading":"さいばーこうげき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"コンピュータやネットワークに対して不正にアクセスし、データを盗んだり、システムを妨害したりする行為である。この攻撃は、個人や企業、さらには国家に対しても行われる可能性がある。具体的な例には、ウイルスを使ってシステムを破壊する攻撃や、フィッシングと呼ばれる手法で個人情報を盗むものがある。サイバー攻撃が増加する背景には、情報技術の進化やインターネットの普及があるため、情報セキュリティの強化が非常に重要である。企業は、適切な対策を講じることで、これらの攻撃から自らを守る必要がある。","explanationZh":"指通过计算机、网络或数字系统实施的恶意行为，例如非法侵入系统、窃取数据、破坏系统或干扰服务。攻击对象可能是个人、企业、政府或关键基础设施，常见形式包括恶意软件攻击、网络钓鱼、拒绝服务攻击等。随着信息技术和互联网普及，组织需要持续强化安全防护、检测和响应能力以降低攻击风险。"},{"id":"t0016","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"事故","termZh":"事故（安全事件）","english":"Incident","reading":"じこ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報システムやネットワークにおいて発生する予期しない事象のことである。これには、データの漏洩や改ざん、サービスの停止などが含まれ、企業や個人に深刻な影響を及ぼす可能性がある。例えば、ハッカーによる不正アクセスがあった場合、これを事故として扱い、迅速な対応が求められる。リスク管理やセキュリティ対策を強化するための重要な要素となり、発生後の調査や対策を通じて、再発防止につなげることが重要である。","explanationZh":"指信息系统或网络中发生的非预期事件，可能导致数据泄露、篡改、丢失或服务中断等后果。例如遭受攻击者的未授权访问后，需要将其作为安全事故进行调查和处置。对事故进行快速响应、原因分析和改进措施落实，有助于强化风险管理并防止同类问题再次发生。"},{"id":"t0017","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"災害","termZh":"灾害","english":"Disaster","reading":"さいがい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"自然や人為的な原因により、社会や環境に深刻な影響を与える事象である。これには地震、洪水、台風などの自然災害や、火災や爆発といった人為的災害が含まれる。例えば、地震が発生すると建物が崩れ、多くの人命や財産が失われる危険がある。地域社会に大きな混乱を引き起こすため、事前の対策や災害応急処置が重要視される。そのため、自治体や政府は災害対策の計画を立て、教育や訓練を通じて市民が備えることを促進している。","explanationZh":"指由自然因素或人为因素引起、并可能对社会、人员、设施和环境造成严重影响的事件，包括地震、洪水、台风、火灾和爆炸等。灾害可能导致人员伤亡、财产损失和业务中断，因此需要事先制定防灾、应急响应和恢复计划，并通过教育和演练提高应对能力。"},{"id":"t0018","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"故障","termZh":"故障","english":"Failure","reading":"こしょう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"システムや機器が正常に機能しなくなる状態を指す。これにより、データの損失や業務の中断が発生する可能性があるため、特に情報技術の分野では重要な問題である。例えば、サーバが故障することで、Webサイトが閲覧できなくなったり、データベースにアクセスできなくなったりすることがある。このようなハードウェアの劣化やソフトウェアのバグ、または外部要因による影響で発生することが多い。そのため、企業は故障を未然に防ぐための監視や保守を行い、システムの信頼性を維持する努力を行っている。","explanationZh":"指系统、设备或软件无法按照预期正常工作的状态，可能造成数据丢失、服务中断或业务停滞。例如服务器硬件故障可能导致网站无法访问或数据库不可用。故障常由硬件老化、软件缺陷或外部环境因素引起，因此组织应通过监控、维护、冗余和备份等措施提高系统可靠性。"},{"id":"t0019","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"破壊","termZh":"破坏","english":"Destruction","reading":"はかい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"システムやデータに対して意図的に損害を与える行為である。情報セキュリティの分野では、ハッカーや悪意のあるソフトウェアによる攻撃の一形態とされ、重要なデータを消去したり、ハードウェアを使用不能にしたりすることが含まれる。例えば、ランサムウェアに感染した場合、データが暗号化され、元に戻せない状態になることがある。このように、破壊は情報資産に対する深刻な脅威であり、その対策が求められている。","explanationZh":"指有意对系统、设备或数据造成损害，使其被删除、损毁或无法正常使用的行为。在信息安全领域，攻击者或恶意软件可能删除重要数据、破坏硬件或使系统失效。例如勒索软件可能加密数据并使其无法使用。破坏会严重损害信息资产，因此需要采取预防、备份、恢复和访问控制等措施。"},{"id":"t0020","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"盗難","termZh":"盗窃","english":"Theft","reading":"とうなん","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"他人の物を無断で奪う行為を指す。情報技術の分野では、特にデジタルデータや資産に関連する盗難が重要な脅威として扱われる。例えば、パソコンやスマートフォンの中に保存された個人情報や企業秘密が盗まれるケースがある。これにより、個人のプライバシーが侵害されたり、企業の競争力が損なわれることがある。また、盗難対策として、データの暗号化やアクセス制限が導入されることが一般的であり、安全な管理が求められている。","explanationZh":"指未经许可夺取他人财物或资产的行为。在 IT 环境中，既包括计算机、手机等设备的实物盗窃，也包括其中保存的个人信息、商业秘密等数字资产被窃取。盗窃可能导致隐私侵害和企业竞争力受损，因此除了物理安全管理外，还应采取数据加密、访问控制和设备管理等安全措施。"},{"id":"t0021","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"侵入","termZh":"入侵","english":"Intrusion","reading":"しんにゅう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"許可されていない者がシステムやネットワークに無断でアクセスする行為を指す。この行為は、情報漏洩やデータの改ざん、サービス妨害などの二次的な被害を引き起こす可能性がある。たとえば、悪意のある攻撃者が企業のネットワークに侵入し、機密情報を盗むことが考えられる。侵入防止策としては、ファイアウォールや侵入検知システムを利用し、外部からの不正アクセスを監視・遮断することが一般的である。このように、侵入のリスクを理解し、対策を講じることは、情報セキュリティにおいて非常に重要である。","explanationZh":"指未经授权进入系统或网络的行为。入侵可能进一步造成信息泄露、数据篡改、恶意程序植入或服务中断等后果。例如攻击者进入企业内部网络后可能窃取机密信息。常见防护措施包括防火墙、入侵检测/防御系统、身份认证和日志监控等，以及时发现并阻断异常访问。"},{"id":"t0022","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"不正アクセス","termZh":"未授权访问","english":"Unauthorized Access","reading":"ふせいあくせす","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"許可を得ずにコンピュータやネットワークに侵入する行為である。この行為は、個人情報や機密データを盗む目的で行われることが多く、特に企業や組織にとって重大な脅威である。例えば、ハッカーがパスワードを不正に入手し、システムにアクセスすることで、重要な情報を流出させる場合がある。また、サイバー攻撃の一環として行われることが多く、企業の信頼性を失い、経済的損失を引き起こす可能性がある。このため、企業では、ファイアウォールや暗号化技術を用いた防御策が重要である。","explanationZh":"指未获得合法许可而访问计算机、网络、账户或数据的行为。攻击者可能通过窃取密码等方式进入系统并获取机密信息，从而引发数据泄露、经济损失和信誉受损。组织通常通过强身份认证、访问控制、防火墙、加密和日志监控等措施降低未授权访问风险。"},{"id":"t0023","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"盗聴","termZh":"窃听","english":"Eavesdropping","reading":"とうちょう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"許可なく他人の通信を傍受する行為である。この種の脅威は、電話やインターネット通信、無線通信などを対象にすることが多い。例えば、悪意のある第三者が通信の内容を盗み聞きすることで、個人情報や機密情報を不正に取得する可能性がある。盗聴を防ぐためには、暗号化やセキュアな通信手段を用いることが重要であり、これにより通信内容が悪用されるリスクを減少させることができる。したがって、企業や個人は通信の安全性を確保するために、適切な対策を講じることが求められる。","explanationZh":"指未经授权截获、监听或读取他人的通信内容。电话、互联网通信和无线通信等都可能成为窃听对象，攻击者可借此获取个人信息、密码或机密数据。防范窃听的关键措施是使用适当的通信加密和安全协议，并确保在可信网络环境中传输敏感信息。"},{"id":"t0024","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"なりすまし","termZh":"冒充／欺骗（Spoofing）","english":"Spoofing","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"他人の名前やIDを使って不正に行動する行為を指す。これは、コンピュータやネットワークの安全を脅かす脅威の一種であり、攻撃者が信頼される相手になりすますことで、個人情報を盗んだり、悪意のある活動を行ったりすることがある。例えば、電子メールで友人からのメッセージを装って不正なリンクを送信することが一般的な手法である。このような手口に対抗するためには、受信したメッセージやリンクの信頼性を確認し、セキュリティ対策を講じることが重要である。","explanationZh":"指攻击者伪装成可信的个人、账户、设备或通信主体，以获得信任并实施未授权操作。例如伪造朋友或组织的邮件身份发送恶意链接，诱导用户泄露信息。防范此类攻击需要核实消息来源和身份真实性，并结合多因素认证、数字签名及反钓鱼等措施。"},{"id":"t0025","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"改ざん","termZh":"篡改","english":"Tampering","reading":"かいざん","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"データや情報が不正に変更されることを意味する。この行為は、情報の正確性を損なうため、特に重要なデータを扱うシステムにおいて大きな脅威となる。例えば、金融機関で顧客情報が改ざんされると、詐欺や不正引き出しの原因になることがある。また、改ざんが行われたデータは、信用を失わせるだけでなく、法的な問題を引き起こす可能性もある。このように、改ざんは情報の信頼性を脅かすため、セキュリティ対策が非常に重要である。","explanationZh":"指未经授权对数据或信息进行修改、替换或伪造的行为，会破坏信息的准确性和完整性。例如金融系统中的客户或交易数据被篡改，可能引发欺诈、非法转账和法律责任。应通过访问控制、完整性校验、数字签名、日志审计等措施检测和防止篡改。"},{"id":"t0026","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"エラー","termZh":"错误","english":"Error","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"システムやプログラムが正しく機能しない状態を指す用語である。これは、ソフトウェアのバグや誤ったデータ処理、ハードウェアの故障など、さまざまな要因によって発生する。たとえば、アプリケーションの操作中にエラーメッセージが表示されることがあるが、これはプログラムが期待するデータを受け取れなかった際に起こる。システムの信頼性やセキュリティに影響を与える可能性があり、特に重要なシステムでは早期の対処が求められる。ユーザーはエラーを防ぐために、定期的なメンテナンスやアップデートを行うことが推奨される。","explanationZh":"指系统、程序或设备未按预期正确运行的状态或结果，可由软件缺陷、数据处理错误、配置问题或硬件故障等多种原因造成。例如应用程序收到不符合预期的数据时可能显示错误信息。错误可能影响系统可靠性和安全性，因此需要及时检测、修复并通过维护和更新降低发生概率。"},{"id":"t0027","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"クラッキング","termZh":"破解（Cracking）","english":"Cracking","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"他人のコンピュータシステムやネットワークに不正にアクセスし、情報を盗んだり、システムを破壊したりする行為である。この行為は、個人のデータを狙う場合や、企業の秘密を暴露することを目的とすることが多い。例えば、ログインパスワードを解除したり、セキュリティシステムを無効にするための技術を駆使する場合がある。また、クラッキングは法的に禁止されており、発見されると厳しい罰則が科されることがある。情報セキュリティの観点からは、クラッキングの脅威を理解し、対策を講じることが重要である。","explanationZh":"指未经授权绕过或破坏计算机系统、网络或软件的安全保护，以获取信息、解除限制或实施破坏的行为。例如破解登录密码、绕过认证或使安全机制失效。此类行为通常具有非法性，并可能造成数据泄露和系统损害。防护重点包括强化认证、及时修补漏洞和监控异常行为。"},{"id":"t0028","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ビジネスメール詐欺","termZh":"商务邮件诈骗（BEC）","english":"Business Email Compromise","reading":"びじねすめーるさぎ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"詐欺師が企業の信頼できるメールアカウントを悪用して、不正な金銭や機密情報を得ようとする手法である。このタイプの詐欺は、通常、被害者に向けた偽のメールを送り、正当な要求を装うことで行われる。例えば、経理担当者に対し、上司を名乗る詐欺師が「急ぎの支払いを行ってほしい」と指示するメールが送信される。このようにして、実際には不正な指示が行われ、企業は経済的損失を被ることがある。BECは巧妙な手口であるため、注意と教育が重要である。","explanationZh":"一种利用企业邮件身份或被攻陷邮箱实施的定向诈骗。攻击者通常冒充企业高管、供应商或可信合作方，以“紧急付款”“变更收款账户”等理由诱导财务人员转账或提交敏感信息。由于邮件内容往往高度仿真，BEC 需要通过员工安全教育、付款复核、多渠道确认和邮件安全技术共同防范。"},{"id":"t0029","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"誤操作","termZh":"误操作（人为错误）","english":"Human Error","reading":"ごそうさ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"主にコンピュータや機器の操作において、不注意や誤解により意図しない操作を行ってしまうことを指す。これにより情報の削除や変更、誤った設定などが発生し、システムやデータに悪影響を及ぼす可能性がある。たとえば、誤ってファイルを削除してしまったり、設定を間違えてシステムが正常に動作しなくなるといったケースが考えられる。このように、誤操作は技術の進化とともに重要な脅威とされており、対策としては操作手順のマニュアル化や教育が求められる。","explanationZh":"指人员由于疏忽、误解或操作失误而执行了非预期操作，例如误删文件、错误修改数据或配置不当，进而对系统和数据造成影响。人为错误是常见安全风险之一，可通过明确操作流程、双人复核、权限最小化、培训和自动化控制等方式降低发生概率。"},{"id":"t0030","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"アクセス権の誤設定","termZh":"访问权限配置错误","english":"Access Control Misconfiguration","reading":"あくせすけんのごせってい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"システムやデータに対するアクセス権限が不適切に設定されることを指す。これにより、本来アクセスできないはずのユーザーが情報にアクセスできてしまう場合がある。この問題は、特にWebアプリケーションやクラウドサービスにおいて多く見られる。例えば、ユーザーが公開設定のデータベースに仮に本来権限を持たない状況でアクセスできると、機密情報が漏洩する危険がある。したがって、アクセス権を適切に管理し、誤設定を防ぐことが情報セキュリティの基本となる。","explanationZh":"指系统或数据的访问权限设置不当，使不应获得权限的用户能够访问资源，或合法用户获得了超过业务需要的权限。该问题在 Web 应用和云服务中较常见，例如数据库误设为公开访问导致敏感信息泄露。应通过最小权限原则、配置审查、定期权限复核和自动化检测来防止此类错误。"},{"id":"t0031","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"紛失","termZh":"丢失","english":"Loss","reading":"ふんしつ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"物や情報が予期せずに失われることを指す。特にITの分野では、データや機器の紛失がセキュリティリスクとなる。例えば、パソコンやスマートフォンを紛失すると、保存されていた重要な情報が外部に漏れる可能性がある。このような状況は、個人情報の流出や不正アクセスの危険を引き起こすため、企業や個人は適切な管理や対策を講じることが必要である。紛失を防ぐためには、物理的な管理だけでなく、データの暗号化やリモートワイプ機能などの技術的対策も重要である。","explanationZh":"指设备、介质、文件或信息非预期地遗失。在 IT 场景中，笔记本电脑、智能手机或存储介质丢失可能导致其中保存的敏感信息外泄，并增加未授权访问风险。防范措施包括加强实物管理、启用设备加密、远程锁定/擦除功能以及做好数据备份。"},{"id":"t0032","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"破損","termZh":"数据损坏","english":"Data Corruption","reading":"はそん","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"データが正しく読めない状態や、価値のある情報が失われた状態を指す。データハードウェアの故障、ソフトウェアの不具合、人為的なミス、またはウイルス攻撃など、さまざまな原因によって発生する。その結果、ファイルが開けなくなったり、データが不正確になったりすることがある。例えば、重要な文書が破損してしまうと、内容を復元できなくなる恐れがあるため、定期的なバックアップが重要である。データの整合性を維持するためには、予防策を講じることが欠かせない。","explanationZh":"指数据因介质故障、软件异常、人为错误或恶意软件等原因发生破坏，导致文件无法读取、内容不完整或数据不准确。数据损坏会影响信息完整性，严重时可能无法恢复重要资料。因此应通过可靠存储、完整性校验、定期备份和恢复演练降低风险。"},{"id":"t0033","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"盗み見","termZh":"肩窥（Shoulder Surfing）","english":"Shoulder Surfing","reading":"ぬすみみ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"他人の個人情報やデータを不正に取得する行為の一つである。具体的には、人がパソコンや携帯電話の画面を操作している際に、その背後から視界に入り込むことで、パスワードや個人情報を盗み取ることである。多くの場合、公共の場や混雑した場所で行われ、注意が必要である。この行為を防ぐためには、画面を隠すためのフィルターを使用したり、周囲に注意を払ったりすることが重要である。また、セキュリティ意識を高め、環境に応じた対策を講じることで、情報漏洩のリスクを軽減することができる。","explanationZh":"指攻击者通过从他人身后或附近偷看屏幕、键盘等方式，窃取密码、个人信息或其他敏感数据。此行为常发生在公共场所或人员密集环境。防范措施包括使用防窥屏、遮挡输入、避免在公共区域处理敏感信息，并提高对周围环境的警觉性。"},{"id":"t0034","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"不正利用","termZh":"未授权使用","english":"Unauthorized Use","reading":"ふせいりよう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"許可されていない方法で情報資源やシステムを使用する行為である。これは、個人や組織が正当な理由なく他人のアカウントやデータにアクセスすることを含む。例えば、他社のソフトウェアを無断で使ったり、他人のデータを盗んだりすることが不正利用に該当する。また、サイバー攻撃としては、フィッシングやマルウェアを利用して情報を不正に取得する行為も含まれる。個人のプライバシーを侵害し、企業にとっては重大な損失をもたらす可能性があるため、セキュリティ対策の強化が重要である。","explanationZh":"指未获得许可而使用信息资源、系统、账户、软件或数据的行为，包括擅自使用他人账户、访问数据或将软件用于未获授权的用途。未授权使用可能造成隐私侵害、信息泄露和经济损失，因此应通过身份认证、访问控制、授权管理和日志审计等措施进行防范。"},{"id":"t0035","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ソーシャルエンジニアリング","termZh":"社会工程","english":"Social Engineering","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"人間の心理や行動を利用して、情報を不正に取得する手法である。主にサイバー攻撃の一環として用いられ、電話やメール、Face-to-Faceなど様々な手段で行われる。例えば、攻撃者が被害者になりすまし、受け取った情報を使ってパスワードの変更やアカウントへの不正ログインを試みることが一般的である。また、フィッシング詐欺がその一例として知られ、信頼できる組織からの連絡を装ったメールが送信されることがある。このような手法に対抗するには、情報の扱いに対する意識の向上が重要である。","explanationZh":"指攻击者利用人的心理、信任和行为习惯，而非单纯依靠技术漏洞，诱骗目标泄露信息或执行危险操作的攻击手法。常见渠道包括电话、邮件、面对面交流、社交媒体等，网络钓鱼是典型形式。防范社会工程的关键在于安全意识教育、身份核验和对异常请求保持警惕。"},{"id":"t0036","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"情報漏えい","termZh":"信息泄露","english":"Information Leakage","reading":"じょうほうろうえい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"機密情報や個人データが許可されていない第三者に流出する現象である。これにより、企業の機密情報や個人のプライバシーが侵害される可能性があるため、非常に深刻な問題である。ハッキングや不適切なデータ管理、内部の人的ミスなど、さまざまな要因によって引き起こされることがある。例えば、社員が誤って機密ファイルを公開したり、悪意のある攻撃者がシステムに侵入して情報を盗み出す場合がある。企業は情報漏えいを防ぐために、セキュリティ対策や従業員教育を強化し、情報管理を徹底することが求められる。","explanationZh":"指机密信息、个人数据或其他敏感信息被未经授权的第三方获取、公开或传出组织控制范围。成因可能包括攻击入侵、配置错误、管理不当和内部人员失误等。例如员工误将机密文件公开，或攻击者窃取数据库。组织应通过访问控制、加密、监控、员工教育和完善的信息管理制度降低泄露风险。"},{"id":"t0037","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"故意","termZh":"故意行为","english":"Intentional","reading":"こい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"特定の目的を持って行う行動や行為のことである。特に情報セキュリティの分野では、故意の脅威は悪意を持ったユーザーや攻撃者によって引き起こされるもので、データの盗難やシステムの破壊などが含まれる。例えば、フィッシング攻撃やマルウェアの配布は、故意に他者を損害を与える行為として知られている。また、これらの脅威は、組織に重大な影響を及ぼす可能性があるため、対策やセキュリティ対策が不可欠である。故意の行動は、計画的であり、予測可能なリスクを伴うため、特に注意が必要である。","explanationZh":"指行为人带有明确目的而主动实施的行为。在信息安全领域，故意威胁通常来自具有恶意意图的内部人员或外部攻击者，例如窃取数据、破坏系统、实施钓鱼或传播恶意软件。由于此类行为往往具有计划性，组织需要通过预防、检测、审计和响应等多层安全措施进行防范。"},{"id":"t0038","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"過失","termZh":"过失","english":"Negligence","reading":"かしつ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"意図せずに他者に損害や影響を与える行為を指す。特に脅威の種類としては、情報セキュリティの分野で重要な概念である。適切な注意や配慮を欠くことから生じ、多くの場合、故意ではないが、その結果として重大な影響を及ぼす可能性がある。例えば、企業が機密情報を適切に保護せず、結果的にデータ漏洩が発生した場合、その対応が不十分だったことが過失とみなされる。このような事件は、信頼性の低下や法的責任を引き起こすため、企業や個人は十分な注意を払い、過失を避けることが重要である。","explanationZh":"指由于未尽到应有注意义务而在无主观恶意的情况下造成损害或风险的行为。在信息安全中，例如组织未妥善保护机密数据，最终导致数据泄露，就可能被视为管理或操作上的过失。过失可能造成信誉下降、经济损失和法律责任，因此需要通过制度、培训和监督减少发生。"},{"id":"t0039","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"誤謬","termZh":"谬误／错误判断","english":"Fallacy","reading":"ごびゅう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報や論理の欠陥によって生じる誤った結論や判断のことである。脅威の種類においては、誤謬が情報セキュリティに関連する誤った信念や理解のことを指す。例えば、あるデータが無害であると誤解し、そのデータを安心して使用することがあるが、実際にはそれがマルウェアを含んでいる場合などが考えられる。こうした誤謬により、ユーザーが危険な行動を取ることがあり、セキュリティ侵害につながることもある。そのため、正しい情報を基にした判断が重要であり、常にリスクを評価する必要がある。","explanationZh":"指由于信息、认知或逻辑存在缺陷而形成的错误结论或判断。在信息安全场景中，例如误以为某个文件无害而执行，实际其中包含恶意软件，就可能因此导致安全事件。减少此类风险需要以可靠信息为依据进行判断，并持续开展风险识别和安全意识教育。"},{"id":"t0040","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"内部不正","termZh":"内部违规（内部不正）","english":"Internal Abuse","reading":"ないぶふせい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"組織内部の人間が自らの権限や職務を悪用し、情報や資産に対して不正行為を行うことを指す。これは、従業員や協力者など、組織の内部に存在する者によって引き起こされる脅威であり、外部からの攻撃とは異なる特性を持つ。例えば、機密情報を無断で持ち出す、システム設定を改ざんする、または不正に資金を流用することなどが含まれる。信頼関係が成立しているために気づかれにくいことが多く、組織にとって重大なリスクとなる。対策としては、監視体制の強化や権限の適切な管理が重要である。","explanationZh":"指组织内部人员利用其职位、权限或对内部环境的了解实施不当或违法行为，例如擅自带走机密信息、篡改系统设置或挪用资金。由于行为人本身具有合法访问权限，内部违规往往更难发现并可能造成重大损失。常见对策包括最小权限、职责分离、行为监控、日志审计和定期权限复核。"},{"id":"t0041","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"妨害行為","termZh":"服务妨碍行为（拒绝服务攻击）","english":"Denial of Service Attack","reading":"ぼうがいこうい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"コンピュータやネットワークの正常な機能を阻害する行為を指す。特に、他のユーザーがサービスを利用できないようにすることを目的とする攻撃が多く見られる。例えば、特定のWebサイトに大量のトラフィックを送りつけてサーバを過負荷にしてしまう「サービス妨害攻撃（DoS攻撃）」がその一例である。このような攻撃は、対象となるサービスの提供を一時的に停止させ、ビジネスに重大な影響を与える可能性がある。悪意を持った個人や団体によって行われることが多く、サイバーセキュリティの分野において非常に大きな脅威となっている。","explanationZh":"指故意阻碍计算机或网络正常运行，使合法用户无法使用服务的行为。典型例子是向目标网站或服务器发送大量流量，使其资源耗尽并造成服务不可用，即 DoS 攻击。此类攻击可能导致业务中断和重大损失，通常由具有恶意目的的个人或团体实施，是网络安全中的重要威胁。"},{"id":"t0042","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"SNSの悪用","termZh":"社交网络服务（SNS）滥用","english":"Abuse of Social Networking Services","reading":"えすえぬえすのあくよう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ソーシャルネットワーキングサービス（SNS）を不適切または違法に利用する行為である。この悪用の形態には、個人情報の盗用や偽情報の拡散、詐欺行為、誹謗中傷などが含まれる。例えば、誰かのアカウントをハッキングしてその人になりすましたり、悪意のあるリンクを他人に送って情報を盗むことが挙げられる。SNSの特性上、情報は急速に広がるため、悪用が生じると多くの人々に影響を与える可能性がある。こうした問題に対処するためには、利用者が個人情報を守り、信頼できる情報源を選ぶことが重要である。","explanationZh":"指以不当或违法方式利用社交网络服务，例如盗用个人信息、传播虚假信息、实施诈骗、诽谤或骚扰等。攻击者还可能接管他人账户冒充本人，或发送恶意链接窃取信息。由于 SNS 信息传播速度快、影响范围广，用户需要谨慎保护个人信息并核实信息来源。"},{"id":"t0043","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"踏み台","termZh":"跳板／跳板主机","english":"Jump Host","reading":"ふみだい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"主にネットワークやシステムのセキュリティを侵害した攻撃者が、他の機器やデータにアクセスするために利用する中継点である。攻撃者は、最初に簡単に侵入できるデバイスやサーバに攻撃を行い、そのデバイスを踏み台として、より重要なシステムやネットワークへ進入することが多い。このような手法は、セキュリティ対策が不十分なデバイスを狙うことで成功しやすく、施された対策が十分でない場合、情報漏洩や不正アクセスを引き起こす可能性が高まる。踏み台として使われるデバイスは、しばしば企業の内部ネットワークにあり、その特性から企業に深刻な影響を及ぼす危険性がある。","explanationZh":"指攻击者在攻陷某台设备或服务器后，将其作为中继点继续访问或攻击其他系统的做法或被利用的主机。攻击者常先入侵防护较弱的设备，再借其向更重要的内部系统横向移动。若企业内部设备成为跳板，可能进一步导致信息泄露、未授权访问和更大范围的入侵。"},{"id":"t0044","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"迷惑メール","termZh":"垃圾邮件（Spam）","english":"Spam","reading":"めいわくめーる","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"受信者の同意なく大量に送信される電子メールのことを指す。スパムメールとも呼ばれる。通常、商業目的や広告が多く含まれており、受信者にとって無益な内容が大半である。受信ボックスを圧迫し、重要なメールを見逃す原因となるため、非常に厄介な存在とされる。スパムメールは、特定のビジネスや製品を宣伝するだけでなく、フィッシング詐欺やマルウェアを配布する手段としても利用されることがある。これらのメールを適切にフィルタリングするための技術や対策が多くのメールサービスに実装されており、ユーザーはスパムを避けることができる。","explanationZh":"指未经收件人同意而大量发送的电子邮件，通常包含广告或与收件人无关的内容。垃圾邮件会占用邮箱资源、干扰正常通信，还常被用于网络钓鱼、诈骗和恶意软件传播。邮件服务通常通过反垃圾邮件过滤、信誉分析等技术减少此类邮件。"},{"id":"t0045","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"AIに対する脅威","termZh":"针对 AI 的威胁","english":"Threats to AI","reading":"えーあいにたいするきょうい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"人工知能（AI）システムやそのデータ、運用に対して危害を及ぼす可能性のある要素や行動のことである。この脅威は、悪意のある攻撃者によるサイバー攻撃、データの不正アクセスや改ざん、さらには機械学習モデルの不正な操作を含む。例えば、攻撃者がAIの学習データに悪意のあるデータを追加することで、AIの判断を誤らせたり、意図的に誤った結果を生成させたりすることがある。また、AIが人間の判断を補助する場面において、その信頼性が損なわれると、多くの社会的な問題を引き起こす可能性もある。このため、安全なAIシステムの設計と運用が重要とされている。","explanationZh":"指可能危害人工智能系统、训练数据、模型或运行过程的行为和因素，包括网络攻击、未授权访问、数据篡改以及对模型的恶意操纵。例如攻击者向训练数据中注入恶意样本，使 AI 作出错误判断或输出错误结果。AI 被用于辅助重要决策时，一旦可信度受损，可能引发广泛影响，因此需要在设计、训练和运行阶段实施安全控制。"},{"id":"t0046","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"コンピュータウイルス","termZh":"计算机病毒","english":"Computer Virus","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"他のプログラムやファイルに寄生する形で自分を複製し、コンピュータやネットワークに被害を与える悪意あるソフトウェアである。このウイルスは、主にユーザーがファイルを開いたり、プログラムを実行したときに活動し、システムの動作を妨げたり、データの消失を引き起こすことがある。例えば、メールの添付ファイルやインターネットからダウンロードしたソフトウェアを通じて感染することが多い。このため、ウイルス対策ソフトウェアを使用して、感染を防ぐことが重要である。また、コンピュータウイルスの中には、データを暗号化して利用不可にするランサムウェアや、遠隔で操作を行うバックドアウイルスなど、さまざまな種類が存在する。","explanationZh":"一种能够寄生于其他程序或文件并复制自身的恶意软件，通常在用户打开文件或执行程序时被触发，可能干扰系统运行、破坏或删除数据。病毒常通过邮件附件、下载文件等途径传播。防护措施包括使用反恶意软件、及时更新系统和谨慎处理来源不明的文件。广义恶意软件还包括勒索软件、后门等多种类型。"},{"id":"t0047","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"マクロウイルス","termZh":"宏病毒","english":"Macro Virus","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"主にデータファイルの自動処理機能である「マクロ」を悪用して感染するウイルスである。このウイルスは、文書作成ソフトやスプレッドシートソフトに多く見られるもので、特定の操作が行われた際に自動的に実行される設定がなされている。例えば、ユーザーが感染した文書を開くと、マクロウイルスが自身を複製し、他の文書やプログラムに感染を広げる仕組みになっている。代表的なアプリケーションとしては、Microsoft WordやExcelが挙げられる。マクロウイルスはその隠れた性質から気付かれにくく、広範囲に感染する可能性があるため、適切なセキュリティ対策が重要である。","explanationZh":"一种利用文档或电子表格中的“宏”自动执行功能传播的计算机病毒。用户打开感染的 Word、Excel 等文档时，恶意宏可能自动执行、复制自身并继续感染其他文件或系统。由于宏代码隐藏在正常文档中，往往不易察觉，因此需要限制不可信宏、使用安全软件并对文档来源进行验证。"},{"id":"t0048","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ワーム","termZh":"蠕虫（Worm）","english":"Worm","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"自己複製することができる悪意あるプログラムの一種である。通常、ネットワークを介して他のコンピュータに感染し、感染先のシステムに被害を与えたり、リソースを占有したりする。ワームはしばしば、メールの添付ファイルやファイル共有サービスを通じて広がる。そのため、感染が広がる速度は非常に速い。例えば、特定の脆弱性を利用して自動的にネットワーク内の他のデバイスに感染し、データを盗んだり、システムをダウンさせたりすることがある。また、ワームはしばしば他のマルウェアと組み合わさり、さらに深刻な被害を引き起こすこともあるため、適切なセキュリティ対策が重要である。","explanationZh":"一种能够自行复制并通过网络自动传播的恶意程序。蠕虫可利用系统漏洞感染其他设备，占用网络和计算资源，甚至窃取数据或造成系统宕机。与需要依附文件传播的病毒不同，蠕虫往往能快速自动扩散，并可能携带其他恶意载荷，因此及时修补漏洞和实施网络防护十分重要。"},{"id":"t0049","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ボット","termZh":"机器人程序（Bot）","english":"Bot","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"特定のタスクを自動的に実行するプログラムである。通常は、インターネットを通じて動作し、ユーザーの代わりに様々な作業を行う。例えば、チャットボットは顧客サポートの一環として、自動で質問に答えたり予約を管理したりする機能を持つ。しかし、悪意のあるボット、いわゆるマルウェアとしてのサイバー攻撃に利用されることが多い。これらの悪質な感染したコンピュータを遠隔操作するために使われ、スパムの送信やデータの盗難、DDoS攻撃など様々な悪影響を及ぼす。したがって、ボットの利用には適切な管理と注意が必要である。","explanationZh":"指自动执行特定任务的软件程序，正常用途包括聊天机器人等。在网络攻击场景中，Bot 常指被恶意软件控制的程序或受感染设备，可在攻击者指令下发送垃圾邮件、窃取数据或参与 DDoS 攻击。因此，应根据用途对 Bot 进行适当管理，并防止设备被恶意控制。"},{"id":"t0050","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ボットネット","termZh":"僵尸网络（Botnet）","english":"Botnet","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"感染したコンピュータの集まりを指し、マルウェアによって遠隔操作されるネットワークである。このようなコンピュータは「ボット」と呼ばれ、それぞれがユーザーの意図に反して動作することができる。例えば、悪意のある攻撃者がボットネットを使って、特定のサーバに対して大規模な攻撃を行ったり、スパムメールを一斉に送信したりすることがある。ボットネットは自動的に数千台以上のコンピュータを利用し、通常の業務やサービスに甚大な影響を及ぼす。そのため、ユーザーは常にセキュリティ対策を講じ、感染を防ぐことが重要である。また、ボットネットの一部は、暗号通貨のマイニングに利用されるなど、経済的利益を追求する目的でも使われる。","explanationZh":"指由大量被恶意软件感染并受攻击者远程控制的计算机或设备组成的网络，其中每个受控设备通常称为“Bot”或“僵尸主机”。攻击者可利用僵尸网络集中发起 DDoS 攻击、群发垃圾邮件、窃取数据或进行非法挖矿。由于规模可达数千甚至更多设备，其破坏力较大，因此终端防护和及时清除感染十分重要。"},{"id":"t0051","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"RAT","termZh":"远程访问木马（RAT）","english":"Remote Access Trojan","reading":"らっと","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"リモートでコンピュータにアクセスするための悪意のあるソフトウェアである。通常、ユーザーが意図しない形でインストールされ、攻撃者は対象のコンピュータに対して様々な操作を行うことが可能となる。例えば、ファイルの取得、マイクやカメラの制御、キーボードの入力監視などが行えるため、個人情報の盗取や不正アクセスの手段として悪用される。フィッシングメールや不正なソフトウェアのインストールを通じて広まることが多く、ユーザーに対する注意が必要である。また、防御方法としては、最新のアンチウイルスソフトの使用や、不明なメールの添付ファイルを開かないことが推奨される。これにより、RATによる被害を未然に防ぐことができる。","explanationZh":"一种使攻击者能够远程控制受害计算机的恶意软件，通常在用户不知情的情况下被安装。RAT 可用于读取或下载文件、控制摄像头和麦克风、监控键盘输入等，从而窃取个人信息或实施进一步攻击。其常通过钓鱼邮件和恶意软件传播，应通过安全软件、系统更新和避免打开可疑附件等方式防范。"},{"id":"t0052","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"C&Cサーバ","termZh":"命令与控制服务器（C&C／C2 服务器）","english":"Command and Control Server","reading":"しーあんどしーさーば","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"マルウェアや不正プログラムが外部から指示を受けたりデータを送信したりするためのサーバである。このサーバは、感染したコンピュータやデバイスを遠隔から操作するための中枢として機能し、攻撃者が指示を出す一つの拠点となる。具体的には、スパムメールや攻撃命令を送信し、感染したシステムから収集した情報を受け取る役割を持つ。例えば、ボットネットと呼ばれる大量の感染デバイスを操る攻撃者は、C&Cサーバを使用して、特定のタスクやデータ盗取の指示を一斉に送ることができる。このように、C&Cサーバはサイバー攻撃において重要なインフラであり、セキュリティ対策としての対策が求められる。","explanationZh":"指恶意软件或受感染设备用于接收攻击者指令、上传窃取数据的控制服务器。它是远程操控僵尸主机或恶意程序的核心基础设施，可下发攻击、群发垃圾邮件、数据窃取等命令，并接收被控终端回传的信息。检测并阻断与 C&C 服务器的通信是恶意软件处置的重要措施。"},{"id":"t0053","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"トロイの木馬","termZh":"特洛伊木马","english":"Trojan Horse","reading":"とろいのもくば","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"マルウェアの一種であり、ユーザーを騙して無害なアプリケーションやファイルに見せかけた悪意のあるプログラムである。これにより、ユーザーが意図せずにインストールしてしまうことが多い。パソコンやネットワークへの不正アクセス、情報の盗難、さらには別のマルウェアのインストールなど、様々な悪影響を及ぼす可能性がある。例えば、ゲームや無料ソフトウェアとして配布されることが多く、ユーザーがそれを選んでインストールすることで、後に悪意のある活動が行われることとなる。このように、トロイの木馬は利用者の注意を引かずにゆっくりと悪事を行うため、特に危険な存在である。","explanationZh":"一种伪装成正常或无害应用、文件以诱骗用户安装的恶意软件。安装后可能建立未授权访问通道、窃取信息、下载其他恶意软件或执行破坏行为。特洛伊木马常借助免费软件、游戏或伪装文件传播，其危险性在于表面正常而在后台执行恶意活动。"},{"id":"t0054","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"スパイウェア","termZh":"间谍软件（Spyware）","english":"Spyware","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ユーザーの同意なしにコンピュータやデバイスにインストールされ、個人情報を収集する不正なソフトウェアである。このソフトウェアは、キーボード入力や閲覧履歴、アプリケーションの使用状況などを監視し、収集した情報を外部に送信することが一般的である。例えば、特定のWebサイトを訪れた際に、知らぬ間にインストールされることがある。広告表示や詐欺に加担することもあり、ユーザーのプライバシーを侵害するため対策が重要である。アンチウイルスソフトやファイアウォールを用いることで、スパイウェアの感染を防ぐことができる。","explanationZh":"指在未经用户同意的情况下安装并监控用户活动、收集个人信息的软件。它可能记录键盘输入、浏览历史和应用使用情况，并将数据发送给外部攻击者，也可能用于强制广告或诈骗。应通过反恶意软件、防火墙、系统更新和谨慎安装软件来降低感染风险。"},{"id":"t0055","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ランサムウェア","termZh":"勒索软件（Ransomware）","english":"Ransomware","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"コンピュータやネットワーク内のデータを暗号化し、元に戻すための金銭を要求する悪意のあるソフトウェアである。主に、ユーザーが重要なファイルにアクセスできなくなるように仕組まれ、攻撃者は復元のために身代金を要求する。たとえば、特定のファイルやシステム全体が暗号化され、その状態を解除するにはビットコインなどのデジタル通貨で支払うように指示されることが多い。このような攻撃は、個人だけでなく企業や政府機関をも狙うため、対策としては定期的なバックアップやアンチウイルスソフトの使用が推奨される。ランサムウェアへの感染を防ぐためには、メールの添付ファイルや不審なリンクをクリックしないことが重要である。","explanationZh":"一种通过加密文件或系统、阻止用户访问数据，并以恢复访问为条件索取赎金的恶意软件。攻击者常要求以加密货币支付。勒索软件可针对个人、企业和政府机构，常见防护包括保持离线或不可篡改备份、更新系统、使用终端安全软件，并避免打开可疑附件和链接。"},{"id":"t0056","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"キーロガー","termZh":"键盘记录器（Keylogger）","english":"Keylogger","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ユーザーのキーボード入力を記録する悪意のあるソフトウェアの一種である。このソフトウェアは、個人情報やパスワードなど、ユーザーが入力するデータを盗む目的で使用される。しばしば不正にインストールされ、気づかれずに動作することが多いため、特に危険である。例えば、オンラインバンキングやメールアカウントの情報を不正に取得するために利用されることがある。キーロガーから身を守るためには、信頼できるセキュリティソフトを使用したり、不審なソフトウェアのインストールを避けたりすることが重要である。また、定期的なソフトウェアの更新や、疑わしいリンクをクリックしないことも防止策の一部である。","explanationZh":"指记录用户键盘输入的软件或设备，在恶意场景中用于窃取密码、银行账号和其他敏感数据。键盘记录器可能被秘密安装并长期运行，因此不易察觉。防护措施包括使用可信安全软件、避免安装来源不明的软件、及时更新系统，并警惕可疑链接和附件。"},{"id":"t0057","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ルートキット","termZh":"Rootkit（隐匿型特权控制工具）","english":"Rootkit","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"コンピュータシステムに不正に侵入し、特権を持つユーザー（ルート）になりすますためのマルウェアである。このソフトウェアは、システムの監視やコントロールを密かに行うことができ、ユーザーが気づかないうちに機能するのが特徴である。ルートキットは通常、他のマルウェアと組み合わされて使用され、情報を盗むためや、遠隔操作を行うための手段として利用されることが多い。例えば、不正にアクセスされたシステムでは、攻撃者が様々な操作を行うため、ルートキットが存在することでその痕跡を隠すことが可能になる。このように、ルートキットはシステムのセキュリティを脅かす深刻な脅威となる。","explanationZh":"一种用于在系统中获得高权限并隐藏攻击者活动或恶意程序痕迹的恶意软件技术。Rootkit 可秘密监控和控制系统，常与其他恶意软件配合，用于窃取信息、远程控制以及规避检测。由于其可能隐藏进程、文件或日志，检测和清除难度较高，是严重的系统安全威胁。"},{"id":"t0058","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"バックドア","termZh":"后门（Backdoor）","english":"Backdoor","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"システムやプログラムに不正にアクセスするための隠れた入り口である。これにより、悪意のある第三者がシステムに侵入し、データの盗難や破壊、他の悪意ある行為を行うことが可能になる。例えば、特定のソフトウェアにトロイの木馬が含まれている場合、そのソフトウェアをインストールすることで、ユーザーは知らないうちにバックドアを開いてしまうことがある。外部からのアクセスを容易にし、通常のセキュリティ対策を回避するため、特に危険な存在とされる。対策としては、定期的なセキュリティスキャンや不審なソフトウェアのインストールを避けることが重要である。","explanationZh":"指系统或程序中绕过正常认证和安全控制的隐蔽访问入口。攻击者可借此持续进入系统、窃取或破坏数据，甚至安装其他恶意软件。后门可能由木马等恶意程序建立，也可能来自不安全的预留机制。应通过安全扫描、完整性检查、补丁管理和限制不可信软件等方式防范。"},{"id":"t0059","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ファイルレスマルウェア","termZh":"无文件恶意软件（Fileless Malware）","english":"Fileless Malware","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"従来のマルウェアとは異なり、ハードディスクにファイルを保存せずに動作する不正プログラムである。通常、システムのメモリ内で直接実行され、アンチウイルスソフトウェアに検出されにくい特性を持つ。このマルウェアは、一般的なソフトウェアやシステムのプロセスを利用して侵入し、そこから悪意のある行動を行うことが多い。例えば、PowerShellやJavaScriptなどのスクリプト言語を利用して攻撃することが一般的で、これによりシステムへの影響を最小限に抑えつつ、情報の盗み取りや他のマルウェアのダウンロードを行うことができる。新たな脅威としてセキュリティ対策の重要性を一層高めている。","explanationZh":"指主要在内存中运行、不依赖将传统恶意可执行文件写入磁盘的攻击代码。它常滥用 PowerShell、JavaScript 或系统内置工具执行恶意操作，因此较难被仅依赖文件特征的传统杀毒软件发现。攻击者可借此窃取信息、下载其他恶意程序或维持访问，需要结合行为监控、脚本控制和终端检测响应等措施防御。"},{"id":"t0060","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"バグ","termZh":"软件缺陷（Bug）","english":"Bug","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ソフトウェアやシステムに存在する欠陥や誤りのことである。この用語はプログラミングの過程で発生する不具合を指し、その結果、プログラムが期待どおりに動作しないことを意味する。コードの記述ミス、論理的な誤り、または設計上の問題から生じることが多い。具体的には、入力したデータに対して正しく計算されない、画面表示が崩れる、あるいはアプリケーションが強制終了するといった例がある。バグは時にセキュリティの脆弱性の原因となることもあり、悪用されるとデータ漏洩や不正アクセスにつながることもあるため、早期の修正が重要である。","explanationZh":"指软件或系统中的程序错误、逻辑缺陷或设计问题，可能导致计算结果错误、显示异常、应用崩溃等非预期行为。Bug 有时还会形成可被攻击者利用的安全脆弱性，造成数据泄露或未授权访问。因此，及时测试、修复和发布安全补丁非常重要。"},{"id":"t0061","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"セキュリティホール","termZh":"安全漏洞（Security Hole）","english":"Security Hole","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"コンピュータシステムやソフトウェアに存在する脆弱性の一つである。この弱点を悪用することで、外部から不正アクセスやデータの盗難、システムの破壊が可能となる。例えば、特定の操作をすることで、意図しない情報にアクセスされることがある。プログラムの設計ミスや、適切なアップデートが行われなかった結果として現れることが多い。対策としては、定期的なソフトウェアの更新や、セキュリティ対策を施すことが重要である。これにより、悪意ある攻撃からシステムを守ることができる。","explanationZh":"指计算机系统或软件中可被攻击者利用的安全弱点。攻击者可能借此绕过访问控制、窃取数据或破坏系统。安全漏洞常源于设计缺陷、编程错误、配置不当或未及时更新。应通过定期漏洞扫描、补丁更新和安全加固来降低被利用风险。"},{"id":"t0062","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"人的脆弱性","termZh":"人为脆弱性","english":"Human Vulnerability","reading":"じんてきぜいじゃくせい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"人間の行動や判断に起因するセキュリティ上の弱点を指す。情報システムにおいては、ユーザーがパスワードを簡単に設定したり、不審なメールに対して警戒心を欠くことが具体例である。このような行動が原因で、攻撃者はシステムへの不正アクセスや情報漏洩を容易に行える。人的脆弱性は技術的な対策だけでは防ぎきれず、教育やトレーニングを通じて意識を高めることが重要である。そのため、企業や組織では定期的なセキュリティ教育が推奨されている。","explanationZh":"指由人的认知、判断或行为习惯导致的安全弱点，例如设置弱密码、轻信可疑邮件、错误处理敏感信息等。攻击者常利用这些弱点实施社会工程或未授权访问。技术措施无法完全消除人为风险，因此组织需要持续开展安全意识教育、培训和演练。"},{"id":"t0063","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"内部統制の不備","termZh":"内部控制缺陷","english":"Internal Control Deficiencies","reading":"ないぶとうせいのふび","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"企業や組織内で情報の正確性や安全性を確保するための仕組みが十分でない状態を指す。この不備により、不正行為や誤った情報の流通が起こる可能性が高まり、組織全体の信頼性が損なわれることがある。例えば、適切な監視や報告手続きが欠如している場合、資金の不正使用や帳簿の誤記載が発生する可能性がある。また、内部統制が強化されれば、これらのリスクを軽減し、業務の効率や透明性を向上させることが可能である。したがって、内部統制の見直しと強化は、組織運営において重要な課題である。","explanationZh":"指组织用于保障信息准确性、安全性、业务合规性和资产保护的内部控制机制不足或失效。缺乏适当监督、审批或报告流程可能导致舞弊、账务错误或信息失真。通过审查和强化内部控制，可降低风险并提高业务透明度和运营效率。"},{"id":"t0064","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"シャドーIT","termZh":"影子 IT（Shadow IT）","english":"Shadow IT","reading":"しゃどーあいてぃー","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"企業や組織が公式に承認していない、従業員によって使用されるITリソースやアプリケーションのことである。このようなリソースは、個人のデバイスやクラウドサービスなど、組織のセキュリティポリシーに則っていない場合が多い。シャドーITは利便性を提供する一方で、データの漏洩やサイバー攻撃のリスクを高める可能性があるため、企業は注意が必要である。また、従業員が利用する未承認のツールやサービスを把握し、適切な管理策を講じることが、情報セキュリティを維持する上で重要な課題となっている。","explanationZh":"指员工在未获得组织正式批准的情况下使用的 IT 设备、应用、云服务或其他技术资源。影子 IT 虽可能提高便利性，但往往未纳入组织安全策略和管理范围，容易造成数据泄露、合规问题和攻击风险。组织应识别未授权工具并建立合理的审批和治理机制。"},{"id":"t0065","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"不正のトライアングル","termZh":"舞弊三角（Fraud Triangle）","english":"Fraud Triangle","reading":"ふせいのとらいあんぐる","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"不正行為が発生する要因を示すモデルである。このトライアングルは、主に三つの要素、すなわち機会、動機、正当化から構成されている。機会は不正を行うための条件や状況であり、把握しやすい環境が整っていると不正が起こりやすい。また、動機は不正を行う人の心理的理由、例えば金銭的困窮やストレスなどである。最後に、正当化は、自分の行動を正当化するための理由を考えることで、人が倫理的な決断を下す際の障害となる。これら三つの要素が揃うことで不正行為が発生しやすくなるため、組織はこのメカニズムを理解し対策を講じる必要がある。","explanationZh":"解释舞弊行为发生条件的模型，由“机会、动机（压力）和合理化”三个要素构成。机会是实施舞弊的环境和条件；动机是促使行为人实施舞弊的原因，如经济压力；合理化是行为人为自己的不当行为寻找正当理由。当三个要素同时存在时，舞弊发生概率上升，组织应针对各要素设计内部控制和预防措施。"},{"id":"t0066","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"状況的犯罪予防","termZh":"情境犯罪预防","english":"Situational Crime Prevention","reading":"じょうきょうてきはんざいよぼう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"犯罪を未然に防ぐための手法であり、具体的には犯行を行うことを難しくしたり、捕まるリスクを高めたりすることを目的としている。また、犯行によって得られる見返りを減少させたり、犯行の誘因を減らすことも含まれる。この手法では、犯罪を正当化する理由を排除することにも力点が置かれている。例えば、街の照明を明るくすることで、可視性を高め、犯罪をしづらくすることが挙げられる。また、金品を容易に盗まれないようにするためのセキュリティ対策も、状況的犯罪予防の一部である。これにより、犯罪者は犯罪を行うことに対して躊躇しやすくなる。","explanationZh":"通过改变环境和条件来降低犯罪机会的预防方法，包括提高实施犯罪的难度和被发现的概率、减少犯罪收益、降低诱因并削弱行为人的自我合理化。例如改善照明以提高可见性，或加强财物保护使盗窃更困难。其目标是使潜在犯罪者更难实施或更不愿实施违法行为。"},{"id":"t0067","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"割れ窓理論","termZh":"破窗理论","english":"Broken Windows Theory","reading":"われまどりろん","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"社会環境における小さな問題や放置が、より大きな犯罪や問題を引き起こす可能性があるという考え方である。この理論は、例えば、壊れた窓が放置されると、その周囲の人々が無秩序と認識し、やがては他の犯罪も引き起こされることを示唆している。具体的には、公共の場での軽微な違法行為や不安定な状態が、やがて大規模な犯罪を誘発する連鎖反応を起こすことがある。したがって、街の美化や秩序を保つことが犯罪防止に繋がるという考え方が広まり、治安維持や社会のルールを守る重要性が強調されている。","explanationZh":"一种认为环境中轻微的无序、破坏若长期放任，可能进一步诱发更严重违法犯罪的理论。例如破损窗户无人修复可能被视为缺乏管理，从而增加其他破坏或违法行为。该理论强调及时维护公共秩序和环境，以减少进一步恶化的可能性。"},{"id":"t0068","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"防犯環境設計","termZh":"通过环境设计预防犯罪（CPTED）","english":"Crime Prevention Through Environmental Design","reading":"ぼうはんかんきょうせっけい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"犯罪を未然に防ぐために周囲の環境や設計を工夫する手法である。このアプローチは、公共の場所や建物の配置、照明、視界の確保などに重点を置き、人々が安全に利用できる空間を作り出すことを目的としている。たとえば、明るく開けた道や、目の届く範囲のベンチなどが設置されることで、犯罪者が狙いにくい状況を作り出す。また、この設計理念は地域社会全体の防犯意識を高める効果もあるため、安全な生活環境の構築に寄与する重要な考え方である。","explanationZh":"指通过建筑、公共空间和周边环境的规划设计降低犯罪机会的方法，例如改善照明、确保视线通透、合理设置出入口和活动区域等。良好的环境设计可提高自然监视能力，使潜在犯罪者更难选择目标，同时也有助于提升社区整体防范意识。"},{"id":"t0069","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"スクリプトキディ","termZh":"脚本小子（Script Kiddie）","english":"Script Kiddie","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"セキュリティ攻撃に使うツールやスクリプトを理解しないまま利用する人を指す用語である。これらの攻撃者は、他人が作成したプログラムやコードを使ってコンピュータシステムに不正アクセスを試みるが、専門的な知識や技術が乏しいことが特徴である。例えば、特定の攻撃方法を実行するスクリプトをダウンロードし、それをただ実行することで攻撃を行う場合が多い。このような行為は、他の高度な攻撃者が行うシスケットやマルウェアを利用した攻撃とは異なり、個人のスキルや知識によらず簡単に実行可能である。結果として、スクリプトキディは社会全体に対するリスクを増大させる要因となることがある。","explanationZh":"指缺乏深入技术知识、主要直接使用他人编写的攻击工具或脚本实施攻击的人。他们可能下载现成程序并按说明执行，以尝试入侵系统。虽然技术水平有限，但由于攻击工具易获取，仍可能造成实际安全风险并增加整体攻击面。"},{"id":"t0070","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ボットハーダー","termZh":"僵尸网络操控者（Bot Herder）","english":"Bot Herders","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"複数の感染したコンピュータやデバイスを遠隔で操る攻撃者のことである。これらの感染した機器は「ボット」と呼ばれ、共にネットワークを形成する。マルウェアを使用してデバイスを感染させ、その後、指示を送ることで攻撃を行う。具体的には、DDoS攻撃やスパムメールの送信、データの窃盗などが含まれる。ボットネットと呼ばれる巨大なネットワークを通じて、規模の大きな攻撃を実行することが可能となるため、サイバーセキュリティの重大な脅威となっている。このため、防御策としては、ウイルス対策ソフトやファイアウォールを導入することが重要である。","explanationZh":"指创建、管理或远程控制大量受感染设备组成的僵尸网络的攻击者。其通常通过恶意软件感染设备，再集中下发指令，实施 DDoS、垃圾邮件发送、数据窃取等攻击。由于可同时控制大量主机，Bot Herder 能发动大规模攻击，是网络安全的重要威胁主体。"},{"id":"t0071","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"内部犯","termZh":"内部威胁人员（Insider Threat）","english":"Insider Threat","reading":"ないぶはん","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"組織内部に所属する者が、悪意を持って情報や資産を侵害する行為を指す。これには、従業員や契約者など、組織に密接に関与している人物が含まれ、故意にデータを漏洩させたり、システムを破壊したりすることがある。他の攻撃者と異なり、内部犯は組織の内部構造やセキュリティ体制を理解しているため、外部からの攻撃よりも高いリスクをもたらすことが多い。これに対抗するためには、適切なアクセス管理や監視システムを整備し、従業員教育を行うことが重要である。","explanationZh":"指组织内部员工、承包商等具有合法关系和一定权限的人员，对信息或资产造成恶意或非恶意危害的威胁。在本文语境中特指恶意内部人员，例如故意泄露数据或破坏系统。由于其熟悉内部结构和安全机制，风险往往较高，应通过权限管理、监控、审计和人员教育进行防范。"},{"id":"t0072","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"愉快犯","termZh":"以取乐为目的的攻击者（Joyrider）","english":"Joyrider","reading":"ゆかいはん","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"他者を困らせることや楽しむことを目的にした攻撃者のことを指す。彼らは犯罪行為を犯すことで、自己満足や快感を得る主な動機を持っている。例えば、愉快犯はネット上で無意味な攻撃を行ったり、他人のアカウントに不正アクセスしていたずらを仕掛けたりすることが多い。このような行為は、ターゲットに対する直接的な利益を目的としていないため、その悪影響は計り知れない。愉快犯の存在は、サイバーセキュリティの分野で新たな課題を生むこととなり、企業や個人はその対策に頭を悩ませている。","explanationZh":"指主要出于好奇、取乐、炫耀或寻求刺激而实施攻击的人，其目的通常不是直接获取经济利益。例如无意义地攻击网站、非法登录他人账户进行恶作剧等。即使动机并非获利，此类行为仍可能造成严重的系统和数据损害。"},{"id":"t0073","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"詐欺犯","termZh":"诈骗者（Fraudster）","english":"Fraudster","reading":"さぎはん","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"他人から不正に金銭や物品を得る目的で、虚偽の情報を提供したり、誤解を招くような行動をする者を指す。金融取引やオンラインサービスなどさまざまな場面で活動することが多く、その動機は金銭的利益であることが一般的である。例えば、偽の投資話や賞金詐欺などが詐欺の一例であり、ターゲットとなる人々を騙すことによって、彼らから資金を手に入れる手法を用いる。このような行為は、法律により厳重に罰せられることがあるため、注意が必要である。詐欺犯の手口を理解することは、被害を避けるために重要である。","explanationZh":"指通过虚假陈述、欺骗或误导他人以非法获得金钱、物品或其他利益的人。其常活跃于金融交易和在线服务领域，例如实施虚假投资、中奖诈骗等。了解常见诈骗手法并核实交易和身份信息，是降低受骗风险的重要措施。"},{"id":"t0074","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"故意犯","termZh":"故意犯罪者","english":"Intentional Offender","reading":"こいはん","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"犯罪行為を行う際に、その結果を意図的に追求する者のことを指す。つまり、故意犯は自らの行動が犯罪であることを理解し、それを実行することで目的を果たそうとする。具体的には、窃盗や詐欺、傷害といった行為がこれに該当する。故意犯の動機は様々で、金銭的な利益を得るためや、他者に対して意図的に害を及ぼす行為が多い。こうした犯罪行為は、計画的に行われることが多いため、他の攻撃者の種類と比較して特に危険度が高いことが特徴である。","explanationZh":"指明知自身行为具有违法或有害性质，仍主动实施并追求相应结果的人。其动机可能包括经济获利、报复或故意伤害他人，常见行为包括盗窃、诈骗和蓄意破坏等。由于此类行为通常具有明确目的和一定计划性，往往具有较高风险。"},{"id":"t0075","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ダークウェブ","termZh":"暗网（Dark Web）","english":"Dark Web","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"通常の検索エンジンでは見つけることができないインターネットの一部である。この空間は、匿名性を重視するために、特別なソフトウェアを使用してアクセスする必要がある。ダークWebでは、情報やサービスが自由にシェアされる一方で、違法な取引や犯罪行為が行われることも多い。これにより、攻撃者は自らの身元を隠し、悪意のある活動に従事することが容易になるため、セキュリティや法執行機関にとって大きな脅威となっている。犯罪者の中には、ハッキングサービスや個人情報の売買を行う者もおり、これがダークWebの特異性を際立たせている。","explanationZh":"指无法通过普通搜索引擎直接索引、通常需要特定软件或网络机制访问的一部分互联网空间。暗网强调匿名性，既可能用于合法的隐私保护和信息交流，也常被用于非法交易、黑客服务和被盗信息买卖等犯罪活动，因此给安全管理和执法带来较大挑战。"},{"id":"t0076","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"二重脅迫","termZh":"双重勒索","english":"Double Extortion","reading":"にじゅうきょうはく","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"サイバー攻撃の一手法で、攻撃者が被害者のデータを暗号化または盗んだ後、データの復元や公開を阻止するために、同時に身代金を要求する手法である。この手法の特徴は、単なるデータの暗号化だけでなく、データを公開する脅迫も行う点である。例えば、企業の重要な情報が盗まれた場合、攻撃者はその情報を公開すると脅し、被害者に対して金銭を要求する。このようにして、被害者に対してより強いプレッシャーをかけ、身代金を支払わせる狙いがある。近年、様々な業界でこの手法が増加しており、企業や個人にとって深刻な脅威となっている。","explanationZh":"勒索软件攻击中的一种方式：攻击者不仅加密受害者数据，还会先窃取数据，并以公开泄露这些数据相威胁，迫使受害者支付赎金。相比单纯加密，双重勒索同时利用“业务无法恢复”和“敏感信息泄露”两种压力，因而对组织造成更大的运营、法律和声誉风险。"},{"id":"t0077","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"金銭奪取","termZh":"资金窃取","english":"Monetary Theft","reading":"きんせんだっしゅ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"他人の財産である金銭を不正に取得する行為を指す。この行為は、詐欺や窃盗などさまざまな手段を用いて行われる。例えば、フィッシング詐欺では、攻撃者が信頼できる企業を装って個人情報を不正に取得し、それを利用して金銭を盗むことがある。また、ランサムウェア攻撃では、データを暗号化し、復元のために金銭を要求する手法が用いられる。金銭的利益を目的とした違法行為であり、被害者には深刻な経済的損失をもたらす。","explanationZh":"指以非法手段取得他人的金钱或财产利益，可能通过诈骗、盗窃、网络钓鱼或勒索软件等方式实施。例如攻击者通过钓鱼获取银行信息后盗取资金，或通过加密数据索取赎金。其核心动机是经济利益，可能给受害者造成严重财务损失。"},{"id":"t0078","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ハクティビズム","termZh":"黑客行动主义（Hacktivism）","english":"Hacktivism","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"政治的、社会的な目的のためにハッキングを行う行為を指す。具体的には、特定のメッセージや目的を持った個人やグループが、コンピュータシステムやWebサイトに対して攻撃を行い、その結果として情報の公開や組織への抗議をすることが一般的である。例えば、企業や政府に対する透明性を求める活動として、Webサイトを一時的に利用不可能にする攻撃や、データの流出を引き起こすことがある。また、賛同者を募るための手段としても用いられ、特定の社会問題に対する意識を高める役割を果たす。これは、従来の抗議活動とデジタル技術が結びついた新しい形態である。","explanationZh":"指为了政治、社会或意识形态目标而使用黑客技术实施的行动。个人或团体可能攻击网站、泄露数据或使服务暂时不可用，以表达抗议、推动议题或传播立场。这是一种将传统社会运动与数字技术结合的行为形式，但其攻击行为仍可能造成违法和安全风险。"},{"id":"t0079","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"サイバーテロリズム","termZh":"网络恐怖主义","english":"Cyber Terrorism","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報通信技術を利用して、特定の団体や国家に対して恐怖を与えることや、社会的混乱を引き起こすことを目的とした攻撃行為である。これは、ハッキングやウイルスの使用、システムの破壊など多様な手法を含む。サイバーテロリズムの動機は、政治的な目的や宗教的な信念、社会変革を目指すことが一般的で、サイバー空間における脅威とされる。最近では、重要なインフラストラクチャーや企業のデータを狙った攻撃が増加しており、これに対する防御策の重要性が増している。","explanationZh":"指利用信息通信技术实施攻击，以制造恐惧、造成社会混乱或实现政治、宗教等目的的行为，可能包括入侵、恶意软件传播和破坏信息系统等。若攻击针对关键基础设施或重要企业数据，可能造成严重社会影响，因此需要高度重视其防护和应急响应。"},{"id":"t0080","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"リークサイト","termZh":"泄密网站（Leak Site）","english":"Leak Site","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"秘密情報や個人データを漏洩させる目的で設けられたWebサイトのことである。これらのサイトは、不正に入手された情報を公にする場として利用されることが多く、ハッキングや内部告発によって流出したデータが掲載される。企業や政府機関に対して攻撃の一環として活用されることがあり、情報漏洩の脅威を引き起こす要因となる。これにより、情報の信頼性が損なわれたり、個人のプライバシーが侵害されるリスクが高まるため、サイバーセキュリティの重要な課題となっている。","explanationZh":"指用于公开泄露机密信息或个人数据的网站，常发布通过攻击、内部泄露等方式非法获得的数据。在勒索软件等攻击中，攻击者也可能利用泄密网站公布受害组织数据，以施加支付压力。此类网站会带来隐私、声誉和信息安全风险。"},{"id":"t0081","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"サイバーキルチェーン","termZh":"网络攻击杀伤链（Cyber Kill Chain）","english":"Cyber Kill Chain","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"サイバー攻撃の一連の段階を示すモデルである。これは攻撃者が目標を攻撃する過程を分解したもので、通常、偵察、侵入、展開、実行、目標達成、維持、隠蔽の7つのステージに分けられる。このプロセスにより、攻撃の各段階でどのような対策が必要かを理解しやすくし、企業や組織が防御策を強化する手助けとなる。例えば、初期段階での偵察を防ぐことで、攻撃者が情報を収集する機会を減らすことができ、結果的に攻撃成功の可能性を低下させることができる。このように、サイバーキルチェーンはセキュリティ対策を立てる上での重要なフレームワークとなっている。","explanationZh":"一种将网络攻击过程划分为多个阶段的分析模型，用于理解攻击者从前期侦察到实现目标、维持访问和隐藏痕迹的全过程。通过识别每一阶段的攻击行为，组织可以在不同节点部署侦测和阻断措施，尽可能在早期打断攻击链，从而降低攻击成功概率。"},{"id":"t0082","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"辞書攻撃","termZh":"字典攻击","english":"Dictionary Attack","reading":"じしょこうげき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"主にパスワードを解読するための攻撃手法である。この手法は、一般的に使用される単語やフレーズが含まれた辞書リストを用いて、ターゲットのアカウントへログインを試みるものである。攻撃者は、辞書にある単語を一つずつ試すことで、簡単なパスワードを持つアカウントを狙い撃ちする。特に、ユーザーが容易に推測可能なパスワードを選ぶ場合、この攻撃は非常に効果的である。そのため、強力なパスワードを設定したり、二要素認証を導入したりすることで、こうした攻撃から自身を守ることが重要である。","explanationZh":"一种密码破解方法，攻击者使用包含常见单词、短语和常用密码的字典列表，逐一尝试登录目标账户。若用户使用容易猜测的密码，字典攻击成功率会较高。防护措施包括使用长且独特的强密码、限制登录尝试并启用多因素认证。"},{"id":"t0083","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"総当たり攻撃","termZh":"暴力破解攻击（Brute Force）","english":"Brute Force Attack","reading":"そうあたりこうげき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報セキュリティの分野において、暗号やパスワードを解読するために、考えうる全ての組み合わせを試す攻撃手法である。この方法は、シンプルで実行が容易だが、試行回数が膨大になるため、時間がかかることが多い。例えば、自分のアカウントのパスワードが「1234」である場合、攻撃者は「0000」から「9999」までのすべての数字の組み合わせを試すことになる。これに対抗するためには、長く複雑なパスワードの設定や、アカウントのロックアウト機能、二段階認証の利用が非常に効果的である。特にパスワードが簡単な場合や、組み合わせが少ない場合に有効な手法であるため、十分な対策が必要である。","explanationZh":"指为了破解密码或密钥，对所有可能的组合进行穷举尝试的攻击方法。方法简单但可能需要大量计算和时间；密码越短、字符空间越小，攻击越容易成功。可通过增加密码长度和复杂度、启用账户锁定/速率限制以及多因素认证来降低风险。"},{"id":"t0084","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"リバースブルートフォース攻撃","termZh":"反向暴力破解攻击","english":"Reverse Brute Force Attack","reading":"りばーすぶるーとふぉーすこうげき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"特定のパスワードを大量のユーザー名に対して試すサイバー攻撃の手法である。この攻撃では、攻撃者が既知のパスワードを使用し、サーバやWebサービスに登録されている様々なユーザー名を対象にしてログインを試みる。たとえば、一般的なパスワードである「password123」を多くのアカウントに対して試すことで、成功するアカウントを探し出す。これは、ユーザーが弱いパスワードを使っている場合に効果的であり、特に組織において同じパスワードを異なるアカウントで使用しているケースが多い。したがって、強固なパスワードの管理と二段階認証の導入が、この攻撃を防ぐために重要である。","explanationZh":"指攻击者固定一个已知或常见密码，然后对大量不同用户名或账户逐一尝试登录。与传统暴力破解针对一个账户尝试大量密码相反，该方法利用用户普遍使用弱密码的特点。防护重点包括禁止常见弱密码、实施登录限速和多因素认证。"},{"id":"t0085","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"パスワードリスト攻撃","termZh":"密码列表攻击／凭据填充（Credential Stuffing）","english":"Password List Attack","reading":"ぱすわーどりすとこうげき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"多数のアカウントに対して事前に収集したユーザー名とパスワードの組み合わせを使用して不正にログインを試みる攻撃手法である。クレデンシャルスタッフィングとも呼ばれる。この手法は、過去に漏洩したデータベースから得た情報を活用するため、ユーザーが異なるサービスで同じパスワードを使い回すことが原因で成功することが多い。たとえば、あるWebサイトでパスワードが流出した場合、その同じ情報を使って他のサイトにもアクセスしようとする攻撃者がいる。このため、ユーザーは異なるサービスで異なる強力なパスワードを使用することが重要であり、二段階認証などの追加のセキュリティ対策を講じることが推奨される。","explanationZh":"指攻击者使用已从其他网站泄露的“用户名＋密码”组合，在大量不同服务上尝试登录。该攻击利用用户跨站点重复使用密码的习惯。防范措施包括不同服务使用不同密码、启用多因素认证、监测异常登录并在凭据泄露后及时更换密码。"},{"id":"t0086","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"クロスサイトスクリプティング","termZh":"跨站脚本攻击（XSS）","english":"Cross-Site Scripting","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"Webアプリケーションに対する攻撃手法の一つである。この攻撃は、悪意のあるスクリプトを安全なサイトに挿入することで、訪問者の情報を盗んだり、偽の操作を行わせたりすることを目的としている。例えば、特定のサイトに書き込まれたスクリプトが他のユーザーのブラウザで実行され、そのユーザーのセッション情報やクッキーが盗まれるといった形で悪用される。適切な入力検証やエスケープ処理を行うことで防ぐことができるため、Web開発においては特に注意が必要である。","explanationZh":"一种针对 Web 应用的攻击，攻击者将恶意脚本注入网页，使其在其他用户浏览器中执行，从而窃取 Cookie、会话信息或执行未授权操作。防御重点包括对输入进行适当验证，对输出进行上下文相关的转义/编码，并采用内容安全策略等安全编码措施。"},{"id":"t0087","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"クロスサイトリクエストフォージェリ","termZh":"跨站请求伪造（CSRF）","english":"Cross-Site Request Forgery","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"悪意のある攻撃者がユーザーの意図しないリクエストを別のサイトに送信させる手法である。この攻撃は、ユーザーが不正なサイトにアクセスした際に、既に認証済みのサイトに対してリクエストを偽装することで発生する。例えば、ユーザーがオンラインバンキングのサイトにログインした状態で、悪意のあるリンクをクリックすると、無断で資金移動が行われる可能性がある。そのため、WebサイトはCSRFトークンなどの対策を導入し、不正なリクエストを防ぐ必要がある。これは、利用者の安全を守るために欠かせない重要な措置である。","explanationZh":"指攻击者诱导已登录某网站的用户，在不知情的情况下向该网站发送其并未真实意图执行的请求。例如用户保持网银登录状态时点击恶意链接，可能被利用发起转账操作。常见防护包括使用 CSRF Token、SameSite Cookie、重新认证和校验请求来源等。"},{"id":"t0088","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"クリックジャッキング","termZh":"点击劫持（Clickjacking）","english":"Clickjacking","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ユーザーが意図しない操作を行うように誘導する攻撃手法である。この手法は、透明なレイヤーを用いて、ユーザーのクリックを隠し、その裏で別のコンテンツを操作させる形で行われる。例えば、悪意のあるWebページが、別のサイトの「ボタン」を隠し、その上に重ねられた透明なボタンをクリックさせることで、意図した行動（例：設定の変更や購入など）をさせる。これにより、ユーザーのプライバシーやセキュリティが侵害される危険性があるため、Webサイトの管理者は対策を講じることが重要である。","explanationZh":"指通过透明或伪装界面将用户的点击导向其看不见或未意识到的真实控件，使其执行非预期操作的攻击。例如把另一个网站的按钮隐藏在透明层下，诱导用户点击并修改设置或完成交易。防护可使用 frame-ancestors、X-Frame-Options 等机制限制页面被恶意嵌入。"},{"id":"t0089","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ドライブバイダウンロード","termZh":"路过式下载攻击（Drive-by Download）","english":"Drive-by Download","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ユーザーが意図せずにマルウェアや不正なソフトウェアをダウンロードしてしまう攻撃手法である。この手法では、悪意のあるWebサイトにアクセスした際、特別な操作をしなくても自動的にファイルがダウンロードされることがある。例えば、信頼できるサイトを装ったフィッシングサイトや、広告をクリックした際に発生するポップアップがこの仕組みを利用することがある。自分のセキュリティを意識せずにインターネットを利用しているユーザーを狙っており、そのためセキュリティ対策を講じていることが重要である。","explanationZh":"指用户仅访问恶意或被攻陷的网站，就在缺乏明确知情和操作的情况下下载或执行恶意软件的攻击方式。攻击可能利用浏览器、插件漏洞或恶意广告实现。防护措施包括及时更新浏览器和系统、限制插件、使用安全软件并避免访问不可信网站。"},{"id":"t0090","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"SQLインジェクション","termZh":"SQL 注入","english":"SQL Injection","reading":"えすきゅーえるいんじぇくしょん","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"データベースと対話するためのSQL（Structured Query Language）を悪用した攻撃手法である。この攻撃は、ユーザーが入力するデータに悪意のあるSQLコードを挿入することによって、データベースに対して不正な操作を行うものである。例えば、Webアプリケーションのログインフォームに特別なコードを入力すると、攻撃者は不正に他のユーザーの情報にアクセスしたり、データを削除したりすることができてしまう。これにより、個人情報の漏洩やシステムの破壊が引き起こされる可能性があり、セキュリティ上の重大な脅威となる。防御策としては、ユーザー入力の検証やエスケープ処理を徹底し、セキュアなコーディングを行うことが重要である。","explanationZh":"指攻击者将恶意 SQL 语句嵌入应用输入，利用程序未正确处理输入的缺陷，让数据库执行非预期查询或操作。可能导致绕过登录、读取或修改敏感数据、删除数据等严重后果。主要防护方式是使用参数化查询/预编译语句、严格输入处理和最小数据库权限，而不是仅依赖简单字符转义。"},{"id":"t0091","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"OSコマンドインジェクション","termZh":"OS 命令注入","english":"Operating System Command Injection","reading":"おーえすこまんどいんじぇくしょん","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"攻撃者がアプリケーションの脆弱性を利用して、意図しないOSコマンドを実行させる攻撃手法である。この攻撃は、特にユーザーからの入力を適切に検証せずにOSコマンドを呼び出すWebアプリケーションでよく見られる。例えば、ユーザーの入力をそのままシステムに渡すプログラムがある場合、攻撃者は追加のコマンドを挿入することで、システムに対して不正な操作を実行できてしまう。これにより、機密情報の漏洩やシステムの制御を奪われるリスクが生じるため、適切な入力検証やエスケープ処理が重要である。また、侵入検知システムやファイアウォールを導入することで、このような攻撃に対する防御を強化することが推奨される。","explanationZh":"指攻击者利用应用程序对外部输入处理不当的漏洞，将额外的操作系统命令注入并使服务器执行。成功后可能读取敏感信息、修改文件或取得系统控制权。应避免将未经处理的输入直接拼接到命令中，采用安全 API、严格白名单校验和最小权限，并辅以检测与隔离措施。"},{"id":"t0092","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ディレクトリトラバーサル","termZh":"目录遍历攻击","english":"Directory Traversal","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"Webアプリケーションに対する攻撃手法の一つである。この攻撃は、不正なファイルアクセスを可能にする目的で、アプリケーションのディレクトリ構造を意図的に変更することで行われる。具体的には、攻撃者がパラメータに特定のコマンドや記号（例：「../」）を入力することで、通常アクセスできないディレクトリやファイルにアクセスしようとする。これにより、機密情報や設定ファイルが漏洩する危険性があるため、開発者は適切な入力検証やアクセス制御を実施することが重要である。ディレクトリトラバーサルの脅威に対抗するためには、システム全体のセキュリティを強化し、未然に攻撃を防ぐ対策を講じるべきである。","explanationZh":"指攻击者通过在文件路径参数中插入“../”等路径控制字符，尝试跳出应用允许访问的目录，从而读取本不应访问的文件或目录。可能泄露配置文件、密钥和其他敏感信息。防护包括路径规范化、使用白名单、限制文件系统权限，并避免直接使用用户提供的路径。"},{"id":"t0093","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"バッファオーバーフロー","termZh":"缓冲区溢出","english":"Buffer Overflow","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"プログラムのメモリ内で用意された領域（バッファ）に対して、想定以上のデータが入力されることで発生する問題である。これにより、隣接するメモリ領域が上書きされるため、プログラムが予期しない動作を引き起こすことがある。サイバー攻撃では、攻撃者がこの脆弱性を利用して悪意のあるコードを実行することができ、システムの制御を奪うことが可能である。バッファオーバーフローを防ぐためには、入力データの長さをチェックしたり、メモリ管理を適切に行うことが重要である。このような対策を講じることで、安全なソフトウェアの開発が促進される。","explanationZh":"指向程序预先分配的缓冲区写入超过其容量的数据，导致相邻内存被覆盖的错误。攻击者可能利用该缺陷改变程序执行流程并执行恶意代码，甚至取得系统控制权。防护措施包括严格检查输入长度、使用内存安全语言和编译器保护机制，以及及时修补相关漏洞。"},{"id":"t0094","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"中間者攻撃","termZh":"中间人攻击（MITM）","english":"Man-in-the-Middle Attack","reading":"ちゅうかんしゃこうげき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"通信を行っている二者の間に第三者が介入し、情報を盗聴したり改ざんしたりする攻撃手法である。この攻撃は通常、ネットワーク上で発生し、例えば公衆Wi-Fiを利用している際に見られることが多い。攻撃者は、ユーザーとサーバの間に介入し、両者の通信を傍受することができるため、パスワードや個人情報が漏洩する危険性がある。このような攻撃を防ぐためには、SSL/TLSによる暗号化通信や二要素認証などの安全対策を導入することが重要であり、また信頼できるネットワーク環境での通信を心がける必要がある。","explanationZh":"指攻击者插入通信双方之间，秘密窃听、转发甚至篡改通信内容的攻击。公共 Wi‑Fi 等不可信网络环境可能增加风险，攻击者可借此窃取密码和个人信息。防护重点包括正确使用 TLS/HTTPS 并验证证书、避免不可信网络、采用强身份认证等。"},{"id":"t0095","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"MITB攻撃","termZh":"浏览器中间人攻击（MITB）","english":"Man-in-the-Browser Attack","reading":"えむあいてぃびーこうげき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ユーザーのブラウザ内で行われる攻撃手法の一つである。この攻撃は、マルウェアによってブラウザが乗っ取られ、ユーザーの操作に基づいて悪意のある行動が実行されることを特徴とする。具体的には、金融取引やパスワード入力時に、正規のページに見せかけた偽情報を注入することで、ユーザーを騙す手法が使われる。例えば、オンラインバンキングを利用しているユーザーが、本物と見分けがつかない偽の画面に誘導され、個人情報や口座情報を盗まれることがある。これにより、被害者は自らの意思で情報を提供してしまうため、非常に危険な攻撃手法とされている。対策としては、セキュリティソフトの導入や、ブラウザの最新のパッチを適用することが推奨される。","explanationZh":"指恶意软件在用户浏览器内部劫持或修改交互过程的攻击。攻击者可在用户访问真实网银等页面时插入或替换显示内容、窃取输入，甚至修改交易参数，因此即使通信本身采用 HTTPS 也可能受影响。应通过终端安全防护、及时修补浏览器和系统、交易确认等措施降低风险。"},{"id":"t0096","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"第三者中継","termZh":"第三方中继／开放邮件中继（Open Relay）","english":"Third-Party Relay","reading":"だいさんしゃちゅうけい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"電子メールを中継するサーバが、送信者や受信者の認証を行わずにメールを転送する方式を指す。オープンリレーとも呼ばれる。これにより、誰でもそのサーバを通じてメールを送信できるため、スパムメールの配信や悪意のある攻撃に利用されやすくなる。具体例としては、攻撃者がオープンリレーを使用して大量のスパムメールを送信し、正規の送信者になりすますことがある。このため、オープンリレーはメールサーバのセキュリティ上の脅威となっており、現代の電子メールシステムでは、適切な認証やフィルタリングが必要とされる。管理者は、そのような中継サーバを構築しないように設定を行うことが重要である。","explanationZh":"指邮件服务器在不验证发件人或收件人资格的情况下，为任意第三方转发邮件的配置。攻击者可借此批量发送垃圾邮件、隐藏真实来源或冒充合法发送者。现代邮件系统应要求适当认证、限制允许中继的来源，并部署反垃圾邮件过滤，避免开放中继。"},{"id":"t0097","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"IPスプーフィング","termZh":"IP 欺骗（IP Spoofing）","english":"IP Spoofing","reading":"あいぴーすぷーふぃんぐ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ネットワーク上で送信元のIPアドレスを偽装する攻撃手法の一つである。これにより、攻撃者は本来の通信相手を装って不正アクセスやデータの盗聴といった悪意のある行為を行うことが可能になる。例えば、攻撃者が他のユーザーのIPアドレスを利用してパケットを送信すると、受信側はその通信が本物であると信じ込むことがある。これにより、攻撃者はセキュリティを回避し、直接的なアクセスができない情報に対しても攻撃を仕掛けることができる。このような手法は、特にDDoS攻撃（分散サービス妨害攻撃）において効果的に利用されるため、ネットワークのセキュリティ対策が非常に重要である。","explanationZh":"指伪造网络数据包的源 IP 地址，使接收方误以为数据来自其他主机。该技术可用于隐藏攻击源、绕过基于地址的简单信任机制，也常用于反射/放大型 DDoS 攻击。网络应采用入口/出口过滤、认证协议和异常流量检测等措施降低风险。"},{"id":"t0098","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"DNSキャッシュポイズニング","termZh":"DNS 缓存投毒","english":"DNS Cache Poisoning","reading":"でぃーえぬえすきゃっしゅぽいずにんぐ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"DNS（ドメインネームシステム）のキャッシュに不正な情報を挿入する攻撃手法である。この攻撃により、正しいドメイン名に対応するIPアドレスが改ざんされ、利用者が攻撃者の用意した悪意のあるサイトに誘導される可能性がある。例えば、ユーザーが「example.com」を訪問しようとする際、DNSサーバが誤ったIPアドレスを返すことで、ユーザーはフィッシングサイトやマルウェア配布サイトにアクセスしてしまう。この攻撃を防ぐためには、DNSサーバのセキュリティ強化や、DNSSEC（DNS Security Extensions）のような技術を利用して正当性を検証することが重要である。","explanationZh":"指向 DNS 解析器缓存中注入伪造的域名解析记录，使用户访问正确域名时被解析到攻击者控制的错误 IP 地址，从而进入钓鱼或恶意软件网站。防护包括及时修补和安全配置 DNS 服务、随机化查询参数，以及使用 DNSSEC 验证 DNS 数据的真实性与完整性。"},{"id":"t0099","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"フィッシング","termZh":"网络钓鱼（Phishing）","english":"Phishing","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"インターネットを利用して個人情報や機密データを不正に取得しようとする詐欺行為の一つである。攻撃者は、偽のWebサイトやメールを利用して、ユーザーに自分の情報を入力させる手口を用いる。例えば、銀行やショッピングサイトを装ったメールが送られ、リンクをクリックすることで偽サイトに誘導される場合が多い。この手法はスミッシングという携帯電話を利用したフィッシング手法を含むこともある。具体的には、SMSで送られるメッセージに偽のリンクが含まれ、ユーザーが個人情報を入力するように仕向けられる。こうした手口から身を守るためには、疑わしいリンクをクリックしないことや、公式サイトから直接アクセスすることが重要である。","explanationZh":"指攻击者通过伪造邮件、短信或网站，冒充银行、购物网站等可信机构，诱导用户输入账号、密码等敏感信息的诈骗方式。通过短信实施的钓鱼常称为 Smishing。防范时应避免点击可疑链接，核对发件人和域名，并优先通过官方入口直接访问服务。"},{"id":"t0100","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"セッションハイジャック","termZh":"会话劫持（Session Hijacking）","english":"Session Hijacking","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"インターネット上でユーザーのセッションを不正に乗っ取る攻撃手法である。これにより、攻撃者はユーザーの認証情報や個人データにアクセスし、悪用することが可能となる。例えば、オンラインバンキングやSNSなど、ユーザーがログインしている状態のセッションを標的にし、クッキー情報を盗むことで実行されることが多い。被害を防ぐためには、安全な通信経路（HTTPSの利用）や、セッションタイムアウト機能の実装、二段階認証の導入などが有効である。また、ユーザー自身も不審なネットワークに接続しないことや、セキュリティソフトの更新を行うことが重要である。","explanationZh":"指攻击者窃取或利用用户的会话标识（如 Cookie），接管其已认证的登录会话，从而以用户身份访问服务或数据。常见防护包括使用 HTTPS、安全 Cookie 属性、会话超时与重新认证、会话标识轮换以及多因素认证，同时避免在不可信网络环境中使用敏感服务。"},{"id":"t0101","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"リプレイ攻撃","termZh":"重放攻击（Replay Attack）","english":"Replay Attack","reading":"りぷれいこうげき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ネットワーク上で盗まれたデータを利用して不正に通信を再送信する攻撃手法である。この手法では、攻撃者が以前のセッションから送信されたメッセージをキャプチャし、そのメッセージを再利用して本来の目的を果たそうとする。たとえば、オンラインバンキングにおいて、正規のユーザーの認証情報を再送信することで、攻撃者が不正に金銭を移動させる可能性がある。このため、リプレイ攻撃に対抗するための対策として、タイムスタンプや一回限りのトークンを用いた認証手法が広く採用されており、これにより再送信を防ぐことができる。これらの対策は、セキュリティを高めるために重要である。","explanationZh":"指攻击者截获合法通信中的认证数据、消息或交易请求，并在之后原样或经过处理后重新发送，以冒充合法操作。攻击者可能利用此前捕获的认证报文重复发起交易。常见防护包括随机数（Nonce）、时间戳、序列号和一次性令牌，使旧报文无法再次被接受。"},{"id":"t0102","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"DoS攻撃","termZh":"拒绝服务攻击（DoS）","english":"Denial-of-Service Attack","reading":"でぃーおーえすこうげき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"特定のサービスやシステムを利用できなくすることを目的とした攻撃手法である。これは、サーバやネットワークに対して大量のリクエストを送り込むことで、リソースを消耗させ、正常なユーザーがサービスを受けられない状態を引き起こす。例えば、あるWebサイトに対して過剰なアクセスを集中させると、そのWebサイトがダウンしてしまい、正規の利用者がアクセスできなくなる。こうした攻撃は商業サイトやオンラインサービスに甚大な影響を与えることがあり、企業では予防策や対応策を講じる必要がある。また、最近ではIoT機器を利用した大規模な攻撃も報告されており、注目が集まっている。","explanationZh":"指通过消耗目标服务器、网络或应用的计算、连接、带宽等资源，使合法用户无法正常使用服务的攻击。攻击者可能向网站发送大量请求导致过载、响应极慢或完全不可用。组织应通过流量过滤、限速、容量冗余和专用抗 DoS 服务等手段进行预防和缓解。"},{"id":"t0103","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"DDoS攻撃","termZh":"分布式拒绝服务攻击（DDoS）","english":"Distributed Denial of Service Attack","reading":"でぃーどすこうげき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"複数のコンピュータを利用して特定のサーバやネットワークを攻撃し、正常なユーザーがそのサービスを利用できなくする手法である。攻撃者は、通常悪意のあるマルウェアによって感染させた多数のコンピュータをネットワークに組織し、大量のトラフィックを一斉に送り込むことで、ターゲットのサーバを圧倒する。たとえば、大人気のWebサイトがDDoS攻撃を受けると、本来のアクセスを処理できなくなり、一般ユーザーはページが表示されない、または極めて遅くなるという状況に陥る。このような攻撃は、フィッシングやデータ盗難とは異なり、主な目的はサービスの停止であり、企業や組織の信頼性や操業に重大な影響を及ぼすことがある。","explanationZh":"指利用大量分散的计算机或设备同时向目标发送流量或请求，使服务器或网络资源被耗尽并导致服务不可用的攻击。攻击设备常来自僵尸网络。DDoS 的主要目标通常是破坏可用性，可造成业务中断、声誉和经济损失，需要通过流量清洗、分布式防护和异常检测等措施应对。"},{"id":"t0104","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"標的型攻撃","termZh":"定向攻击／针对性攻击","english":"Targeted Attack","reading":"ひょうてきがたこうげき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"特定の個人や組織を狙ったサイバー攻撃の手法である。この攻撃は、対象に関する情報を事前に収集し、その弱点を突いて侵入を試みることが特徴である。具体的には、フィッシングメールやマルウェアを使用し、被害者が信じた内容でアクセスを促すことで、機密情報を盗み取ることが目的となる。たとえば、企業の幹部を狙った攻撃では、偽のメールを使って正規のログインページに誘導し、パスワードを取得することがある。こうした攻撃は、一般的なウイルス対策ソフトウェアでは防ぎにくく、企業や個人はセキュリティ対策を強化する必要がある。","explanationZh":"指针对特定个人、部门或组织进行信息收集并量身实施的网络攻击。攻击者会根据目标的身份、工作关系和弱点设计钓鱼邮件、恶意附件或伪造登录页面，以获取凭据、机密信息或建立持续访问。此类攻击针对性强，需要结合人员教育、邮件防护、终端检测和持续监控进行防御。"},{"id":"t0105","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"APT","termZh":"高级持续性威胁（APT）","english":"Advanced Persistent Threat","reading":"えーぴーてぃー","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"特定のターゲットに対して長期間にわたって巧妙に攻撃を仕掛ける手法を指す。この攻撃の特徴は、一度侵入した後も、システムに密かに留まって情報を収集し続ける点にある。APTは主に、国家や大企業など、高度なセキュリティ対策が施されている相手を狙うことが多い。例えば、サイバー犯罪者が不正なソフトウェアを用いてネットワークに侵入し、数か月またはそれ以上にわたりデータを盗み出すケースが挙げられる。これにより、機密情報が漏洩したり、企業の運営に重大な影響を与えたりするリスクが高まるため、適切な防御策と意識向上が求められる。","explanationZh":"指具有较高资源和技术能力的攻击者，针对特定目标长期、隐蔽地实施入侵和持续控制的威胁活动。攻击者在进入网络后会尽量保持潜伏，逐步扩大权限并持续收集或窃取敏感信息。APT 常针对政府、关键基础设施和大型组织，需要长期的监测、威胁情报、分层防御和事件响应能力。"},{"id":"t0106","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"水飲み場型攻撃","termZh":"水坑攻击（Watering Hole Attack）","english":"Watering Hole Attack","reading":"みずのみばがたこうげき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"特定のターゲットが訪れるであろうWebサイトを攻撃者が狙う手法である。この攻撃では、攻撃者がターゲットがよく利用するサイトにマルウェアを仕込むことで、訪問者が知らず知らずのうちに悪意のあるソフトウェアをダウンロードしてしまうことを目的とする。例えば、企業の社員が業務用の情報サイトを訪れる際、そのサイトが改ざんされていると、従業員は無防備でマルウェアに感染する可能性が高まる。このように、水飲み場的攻撃は特に組織を狙った高度なサイバー攻撃として知られ、ターゲットの行動パターンを理解している攻撃者によって実行される。そのため、セキュリティ対策として、信頼できるサイトのみを利用することや、最新のセキュリティソフトを導入することが重要である。","explanationZh":"指定向攻击者先识别目标群体经常访问的网站，再入侵或篡改这些网站并植入恶意内容，等待目标访问时感染其设备。由于受害者访问的是平时信任的网站，攻击具有较强隐蔽性。防护包括及时修补终端和浏览器漏洞、使用 Web 防护、隔离高风险内容并监控异常下载行为。"},{"id":"t0107","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"やり取り型攻撃","termZh":"交互式攻击","english":"Interactive Attack","reading":"やりとりがたこうげき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"攻撃者が被害者とリアルタイムでやり取りを行いながら情報を盗んだり、システムに侵入したりする攻撃手法である。この手法では、例えば、フィッシングメールを使用して被害者を騙し、偽のWebサイトに誘導することで、ユーザー名やパスワードを取得することがある。さらに、攻撃者はSNSやチャットアプリを通じて被害者と直接やり取りし、信頼関係を築いてから個人情報を引き出すこともある。このような攻撃は、被害者が信頼する人物と関わっていると感じるため、気付かずに協力してしまうことが多く、特に注意が必要である。また、これに対応するためには、不審なリンクや要求には注意を払い、常に疑問を持つ姿勢が重要である。","explanationZh":"指攻击者在攻击过程中与受害者或已入侵系统进行实时互动，根据对方反应动态调整欺骗、信息获取或入侵步骤。例如通过聊天、社交媒体或钓鱼页面与目标建立信任，再诱导其提供账号、密码或执行操作。防范此类攻击需要核验身份、警惕异常请求，并避免在未经确认的情况下提供敏感信息。"},{"id":"t0108","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"SEOポイズニング","termZh":"SEO 投毒／搜索引擎优化投毒","english":"Search Engine Optimization Poisoning","reading":"えすいーおーぽいずにんぐ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"悪意のある手法を用いて検索エンジンの結果ページにおいて自サイトや特定のコンテンツを上位に表示させる攻撃手法である。この手法は、通常は正当でない方法を通じて行われ、ユーザーを欺くことを目的とする。例えば、サイバー犯罪者が自サイトに悪意のあるソフトウェアやフィッシング詐欺のリンクを貼り、これらのリンクが検索結果の上位に浮上するように仕向けることがある。ユーザーは興味を引かれるタイトルや内容に誘導され、結果として危険なサイトにアクセスしてしまう可能性がある。これにより、個人情報の盗難やデバイスへのマルウェアの感染が生じるリスクが高まるため、注意が必要である。対策としては、信頼できるサイト以外からのリンクを避けることや、セキュリティソフトウェアを導入することが推奨される。","explanationZh":"指攻击者操纵搜索引擎优化手段，使恶意网站、钓鱼页面或恶意软件下载链接出现在较高的搜索结果位置，从而诱导用户访问。用户可能因标题和排名看似可信而进入危险站点。防护重点是核对网站域名和来源、使用浏览器与终端安全防护，并避免仅依据搜索排名判断可信度。"},{"id":"t0109","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ゼロデイ攻撃","termZh":"零日攻击（Zero-Day Attack）","english":"Zero-Day Attack","reading":"ぜろでいこうげき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ソフトウェアやシステムの脆弱性が発見された直後、その脆弱性を利用して行われる攻撃を指す。このような攻撃は、開発元がその脆弱性を認識する前に実行されるため、「ゼロデイ」という名称が付いている。具体的には、悪意のあるハッカーが未修正の状況を利用し、不正にデータを盗んだり、システムに侵入したりする。例えば、新しいソフトウェアがリリースされた直後に、このソフトウェアの脆弱性を狙った攻撃が行われることがある。特に対策が打たれていない初期段階で行われるため、防御が非常に難しく、システムの安全性を大きく脅かすリスクが存在する。","explanationZh":"指利用尚无可用补丁或防护措施的未知/新发现漏洞实施的攻击。由于厂商和防守方往往尚未完成修复，攻击在初期较难被传统特征检测阻断。应通过纵深防御、最小权限、行为检测、攻击面缩减和快速补丁响应降低零日漏洞被利用后的影响。"},{"id":"t0110","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"サービス及びソフトウェアの機能の悪用","termZh":"服务及软件功能滥用","english":"Abuse of Service and Software Functionality","reading":"さーびすおよびそふとうぇあのきのうのあくよう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"提供されているサービスまたはソフトウェアが想定している使い方とは異なる方法で悪意を持って利用される行為である。具体的には、システムの脆弱性を突いて機密情報を不正に取得したり、サービスを妨害したりすることが含まれる。例えば、特定の条件を利用して無料のトライアル版を複数回使用したり、リソースを無限に消費することで他のユーザーに影響を及ぼすような攻撃が考えられる。このような悪用は、システムの信頼性を低下させたり、開発者やユーザーに経済的損害を与えることがあるため、対策が重要である。","explanationZh":"指攻击者并不一定利用传统漏洞，而是以超出设计目的或违反使用规则的方式滥用合法功能，例如反复利用试用机制、自动化调用接口消耗资源、借正常功能获取不应获得的信息等。应通过业务规则校验、配额和速率限制、异常行为监控及反滥用机制进行控制。"},{"id":"t0111","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"AIを悪用した攻撃","termZh":"AI 驱动的网络攻击","english":"AI-Powered Cyber Attacks","reading":"えーあいをあくようしたこうげき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"人工知能を利用して行われるサイバー攻撃のことである。この攻撃手法には、標的型攻撃やフィッシング、なりすましの巧妙化が含まれる。具体的には、AIを用いて特定の対象者を狙い撃ちする攻撃が行われ、個人情報の取得や企業の機密情報の漏洩を目的とする。また、マルウェアの亜種生成では、AIが自動で新たなマルウェアを生み出し、検知を回避する技術が進化している。さらに、システムの脆弱性発見もAIによって迅速かつ効率的に行われるようになり、攻撃者にとって有利な状況が生まれる。これらの手法に対抗するためには、サイバーセキュリティ対策の強化が不可欠である。","explanationZh":"指攻击者利用人工智能提高网络攻击的自动化、规模或欺骗能力，例如生成更具针对性的钓鱼内容和冒充材料、辅助发现漏洞、变异恶意代码或优化攻击路径。AI 可降低部分攻击活动的成本和门槛，因此防守方需要强化身份验证、内容与行为检测、漏洞管理和安全运营能力。"},{"id":"t0112","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ディープフェイク","termZh":"深度伪造（Deepfake）","english":"Deepfake","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"人工知能（AI）を活用して作成された偽の映像や音声のことを指す。この技術は、特定の人物の顔や声を他の映像や音声に合成することで、リアルに見える不正なコンテンツを生成する。例えば、有名な俳優の顔を使って別の人が話しているように見せる映像がこれに該当する。ディープフェイクはエンターテインメントの分野で新しい表現方法として使用される一方で、偽情報の拡散や名誉毀損といった悪用のリスクも抱えているため、倫理的な問題も含んでいる。安全性や信頼性が問われるため、法律や技術の面で適切な対策が求められている。","explanationZh":"指利用人工智能生成或合成高度逼真的虚假图像、视频或语音，使某人看似说过或做过实际上没有发生的事情。该技术可用于娱乐和创作，也可能被用于诈骗、冒充、虚假信息传播和名誉侵害。防范需要结合内容溯源、身份复核、检测技术以及法律和组织治理措施。"},{"id":"t0113","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"敵対的サンプル","termZh":"对抗样本（Adversarial Sample）","english":"Adversarial Sample","reading":"てきたいてきさんぷる","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"機械学習や人工知能のシステムを攻撃するために意図的に設計された入力データのことである。これは、モデルが誤った判断をするように導くものであり、例えば、画像認識モデルに対して特定のノイズを加えた画像を送り込むことによって、モデルが誤ったクラスに分類するように仕向けることがある。この手法は、深層学習モデルの脆弱性を示すものであり、セキュリティの観点から非常に重要である。敵対的サンプルに対抗するための手法も研究されており、頑健性を高めるための様々なアプローチが検討されている。これにより、システムの信頼性を向上させることが可能である。","explanationZh":"指为了诱导机器学习模型产生错误判断而特意构造或扰动的输入数据。例如对图像加入人眼难以察觉的细微扰动，使分类模型把对象识别为错误类别。对抗样本揭示了模型的鲁棒性风险，可通过对抗训练、输入检测、模型加固和多重验证等方法提高系统可靠性。"},{"id":"t0114","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"プロンプトインジェクション攻撃","termZh":"提示词注入攻击（Prompt Injection）","english":"Prompt Injection Attack","reading":"ぷろんぷといんじぇくしょんこうげき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"主に人工知能や対話型システムに対して、悪意のある入力を行うことで、不正な操作を引き起こそうとする攻撃手法である。この攻撃では、攻撃者が特定の命令や情報を入力し、システムがそれに基づいて誤った応答を生成するよう仕向ける。例えば、ユーザーがAIに対して不適切な発言を促したり、システムの内部構造を探るための情報を引き出すことが考えられる。このような攻撃が成功すると、システムの信頼性が損なわれるだけでなく、ユーザーの情報が危険にさらされるリスクもあるため、対策として入力の検証やフィルタリングが重要である。","explanationZh":"指针对生成式 AI 或其他基于提示词运行的系统，通过恶意输入操纵模型指令优先级或上下文，使其偏离预期规则、泄露不应输出的信息或调用不当工具。防护不能仅依赖简单文本过滤，还需要进行指令与数据隔离、最小权限、工具调用授权、输出验证及不可信内容标记等多层控制。"},{"id":"t0115","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"フットプリンティング","termZh":"足迹收集（Footprinting）","english":"Footprinting","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報セキュリティの分野において、対象となるシステムやネットワークの情報を収集する手法である。このプロセスは、攻撃者が特定の組織やサイトについての詳細な知識を得るための第一歩として重要で、多くの場合、攻撃の計画を立てるために使用される。具体的には、ドメイン情報、IPアドレス、サーバの公開情報やネットワーク構成図が収集される。例えば、企業のWebサイトから得られる情報や、WHOISデータベースから取得できるドメインの登録情報は、フットプリンティングでよく使用される。このデータをもとに、攻撃者は防御の弱点を突くための計画を立てることが可能であり、セキュリティ対策を講じる上で重要な警戒情報となる。","explanationZh":"指在攻击或安全评估前收集目标组织、系统和网络公开信息的侦察过程。可能涉及域名、IP 地址、公开服务器信息、员工资料、技术栈和 WHOIS 等数据。攻击者利用这些信息识别潜在攻击面；防守方也可通过资产暴露面管理了解外部可见信息并减少不必要的信息泄露。"},{"id":"t0116","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ポートスキャン","termZh":"端口扫描（Port Scan）","english":"Port Scan","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ネットワーク上のコンピュータやサーバの特定のポートが開いているかどうかを調べる手法である。ポートとは、データ通信の際に特定のサービスを提供するための入口であり、例えばWebサーバでは通常ポート80を使用する。攻撃者はこの手法を用いて、脆弱性があるサービスを見つけるためにターゲットのネットワークをスキャンすることがある。具体的には、ポートスキャンを行うことで、どのサービスが稼働しているかを把握し、攻撃のターゲットを絞り込むことが可能になる。そのため、この手法はサイバー攻撃の準備段階として重要な位置を占めているが、企業や組織ではネットワークセキュリティの強化にも利用されることが多い。正当な目的で行う場合は、ネットワークの監査や脆弱性評価などに役立つ。","explanationZh":"指探测目标主机或网络上哪些 TCP/UDP 端口处于开放或可访问状态，以判断正在运行的服务。攻击者可借此发现潜在攻击入口；管理员也会在获授权的安全测试中用于资产识别和漏洞评估。未经授权扫描他人系统可能违反政策或法律，因此应在明确授权范围内进行。"},{"id":"t0117","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"RaaS","termZh":"勒索软件即服务（RaaS）","english":"Ransomware as a Service","reading":"らーす","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ランサムウェア・アズ・サービスの略で、悪意のあるソフトウェアであるランサムウェアを他者が利用できる形で提供するサービスである。RaaSを通じて、テクニカルスキルが乏しい犯罪者でも簡単にサイバー攻撃を行うことができる環境が整えられている。例えば、悪意のある人物がサブスクリプション料金を支払ってRaaSを利用すれば、他人のデータを暗号化し、その解読を条件に身代金を要求することが可能になる。これにより、犯罪がより手軽になり、新たな脅威が増加しているため、企業や個人は十分なセキュリティ対策を講じる必要がある。","explanationZh":"指由恶意软件开发者或犯罪团伙以服务化方式向其他攻击者提供勒索软件、控制面板、支付和受害者管理等工具的犯罪商业模式。即使技术能力较低的参与者也能借此实施勒索攻击，收益通常按订阅或分成模式分配。这种模式降低了攻击门槛并扩大了勒索软件生态。"},{"id":"t0118","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ラテラルムーブメント","termZh":"横向移动（Lateral Movement）","english":"Lateral Movement","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"サイバー攻撃における手法の一つである。この手法は、攻撃者が最初に侵入したシステムから他のシステムへと移動し、ネットワーク内での権限を拡大する過程を指す。例えば、マルウェアによって最初の端末が攻撃されると、攻撃者はその端末を拠点にしてネットワーク内の別のデバイスにアクセスしようとする。この様に、ラテラルムーブメントによって攻撃者は重要なデータや管理権限を奪取する可能性が高まる。そのため、企業や組織では、内部のネットワークのセキュリティを強化し、異常な動きを監視することが重要である。","explanationZh":"指攻击者在取得某一主机或账户的初始访问权后，利用凭据、信任关系或漏洞在内部网络中继续访问其他主机，并逐步扩大权限和接近高价值资产的过程。防护重点包括网络分段、最小权限、凭据保护、东西向流量监控以及检测异常远程登录行为。"},{"id":"t0119","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"CRYPTREC暗号リスト","termZh":"CRYPTREC 密码算法清单","english":"CRYPTREC Cryptographic Algorithm List","reading":"くりぷとれっくあんごうりすと","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"日本における暗号技術の利用促進と安全性向上を目的とした、推奨される暗号アルゴリズムの一覧である。このリストは、信頼性や安全性が評価された暗号技術を整理しており、これに基づいて業界や政府機関などが暗号の選定や実装を行うことが求められる。具体的には、電子政府や企業間取引で使用される暗号プロトコルに対して、どの暗号が適当であるかを示すもので、情報漏洩や不正アクセスを防止するための重要な指針である。また、CRYPTRECは、技術の進展や新たな脅威に応じて、リストの更新やアルゴリズムの評価を定期的に実施し、常に最新の情報を提供する役割も果たしている。","explanationZh":"日本 CRYPTREC 体系对密码算法进行安全性和适用性评估后发布的算法清单，用于为日本政府信息系统以及相关组织选用密码技术提供参考。清单会根据密码分析研究、技术发展和威胁变化进行评估和更新，是日本密码技术政策与安全选型的重要依据。"},{"id":"t0120","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"共通鍵暗号方式","termZh":"对称密钥加密","english":"Symmetric Key Encryption","reading":"きょうつうかぎあんごうほうしき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"データを暗号化する際に使用する鍵が送信者と受信者の両者で共通である暗号技術である。この方式では、同じ鍵を用いてデータを暗号化することと復号することが可能であり、鍵を安全に共有することが重要となる。例えば、家庭内でセキュリティを強化するWi-Fiルーターでは、共通鍵が利用されることが多い。この仕組みにより、特定のネットワーク内のデバイスのみがデータにアクセスできるため、プライバシーを保護することができる。しかし、鍵が漏洩すると全てのデータが危険にさらされるため、鍵の管理が非常に重要である。処理速度が速く、大量のデータを効率的に扱えるため、実務において広く利用されている。","explanationZh":"指加密和解密使用同一把秘密密钥（或可直接相互推导的秘密密钥）的密码方式。其运算速度快，适合加密大量数据，但通信双方必须以安全方式共享和保护密钥；一旦密钥泄露，相关数据的机密性就可能受到影响。AES 是典型的对称加密算法。"},{"id":"t0121","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"公開鍵暗号方式","termZh":"公钥密码体制／非对称加密","english":"Public Key Cryptography","reading":"こうかいかぎあんごうほうしき","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"公開鍵暗号方式は、公開鍵と秘密鍵という一対の異なる鍵を使う暗号方式である。秘密通信で最重要なのは「誰の鍵を使うか」である。AさんがBさんへ秘密のメッセージを送る場合、AさんはBさんの公開鍵で暗号化し、Bさんは自分だけが持つBさんの秘密鍵で復号する。したがって、途中で暗号文を盗まれてもBさんの秘密鍵がなければ復号できない。\n\n【暗号化・復号の基本フロー】\nA（送信者）→ Bの公開鍵で暗号化 → 暗号文 → B（受信者）→ Bの秘密鍵で復号 → 平文\n\n公開鍵は配布してよいが、秘密鍵は所有者だけが厳重に管理する。公開鍵暗号は共通鍵暗号より計算負荷が大きいため、実際の通信ではデータ本体を共通鍵で暗号化し、その共通鍵を公開鍵暗号で保護するハイブリッド暗号が広く用いられる。\n\n【試験ポイント】「機密性のための暗号化」は『相手の公開鍵で暗号化 → 相手の秘密鍵で復号』と覚える。デジタル署名とは鍵の使い方が逆になる。","explanationZh":"公钥密码体制使用一对相互关联但不同的密钥：公钥和私钥。用于“保密通信”时，考试最重要的是判断“使用谁的密钥”。如果A要把秘密消息发给B，A使用B的公钥加密，只有B持有的B私钥能够解密。即使密文在传输途中被截获，没有B的私钥也无法正常还原明文。\n\n【加密/解密基本流程】\nA（发送者）→ 使用B的公钥加密 → 密文 → B（接收者）→ 使用B自己的私钥解密 → 明文\n\n公钥可以公开分发，私钥必须由所有者严密保管。由于公钥密码计算开销通常高于对称加密，实际系统往往使用“混合加密”：数据正文用高速的对称密钥加密，再用公钥密码保护/传递会话密钥。\n\n【考试速记】为了“保密”：用“对方的公钥”加密，用“对方自己的私钥”解密。数字签名的密钥使用方向不同。"},{"id":"t0918","chapterId":"c01","termJa":"公開鍵暗号とデジタル署名の使い分け","termZh":"公钥加密与数字签名的区别","english":"Public-Key Encryption vs Digital Signature","reading":"こうかいかぎあんごうとでじたるしょめいのつかいわけ","breadcrumb":"SG補足｜暗号・認証の試験対策","explanationJa":"公開鍵暗号とデジタル署名は同じ「公開鍵・秘密鍵」の組を使うが、目的と鍵の使い方が異なる。\n\n【機密性（秘密に送る）】\n送信者A → 受信者Bの公開鍵で暗号化 → BがBの秘密鍵で復号\n目的：第三者に内容を読ませない。\n\n【デジタル署名（本人性・完全性を確認）】\n送信者A → Aの秘密鍵で署名 → 受信者BがAの公開鍵で検証\n目的：Aが署名したこと、署名後に改ざんされていないことを確認する。\n\n【覚え方】\n秘密にしたい → 「相手」の公開鍵。\n自分が署名した証拠を作る → 「自分」の秘密鍵。\n\n両方が必要な場合は、署名と暗号化を組み合わせる。","explanationZh":"公钥加密和数字签名都使用“公钥＋私钥”密钥对，但目的和使用哪一方的密钥完全不同。\n\n【为了机密性——秘密发送】\n发送者A → 用接收者B的公钥加密 → B用B自己的私钥解密\n目的：防止第三方读取内容。\n\n【为了签名——确认身份与完整性】\n发送者A → 用A自己的私钥签名 → 接收者B用A的公钥验证\n目的：确认由A对应私钥生成签名，并确认签名后的内容未被篡改。\n\n【记忆口诀】\n想让“别人看不到” → 用“对方的公钥”。\n想证明“这是我签的” → 用“自己的私钥”。\n\n如果既要保密又要验证发送者，可以组合数字签名和加密。","chapterJa":"情報セキュリティ","chapterZh":"信息安全"},{"id":"t0122","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"AES","termZh":"AES 高级加密标准","english":"Advanced Encryption Standard","reading":"えーいーえす","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"データを暗号化するための標準的な方式である。これは、機密情報を保護するために設計されており、電子データを安全に送受信する際に用いられる。128ビット、192ビット、256ビットといった異なる鍵の長さを持ち、これにより暗号の強度を調整することができる。例えば、AES-128は一般的な用途に使われ、非常に速く処理できるため、広く採用されている。一方で、AES-256はより高いセキュリティが求められる場合に使用される。AESはその効率性と強固なセキュリティにより、インターネットバンキングや政府機関でのデータ保護において重要な役割を果たしている。","explanationZh":"一种广泛使用的对称分组加密标准，支持 128、192 和 256 位密钥。AES 具有较高的安全性和运算效率，被广泛用于网络通信、存储加密、金融和政府信息系统等场景。密钥长度越长通常提供更大的穷举安全裕量，但实际安全性还取决于工作模式、密钥管理和正确实现。"},{"id":"t0123","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"RSA暗号","termZh":"RSA 密码算法","english":"RSA Encryption","reading":"あーるえすえーあんごう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"安全なデータの通信を実現するための公開鍵暗号技術である。RSAは、Rivest-Shamir-Adlemanという3人の研究者の名前に由来している。公開鍵暗号の代表的な方式であり、インターネット上での安全な通信や電子商取引に広く利用されており、個人情報や機密情報を保護する手段として欠かせない技術である。RSA暗号の安全性は、大きな素数の積を素因数分解することが非常に難しいことに基づいている。","explanationZh":"一种经典的公钥密码算法，以 Rivest、Shamir 和 Adleman 三位研究者的姓氏命名。其安全性主要建立在大整数因数分解问题的计算困难性上。RSA 可用于密钥封装和数字签名等，但实际系统应使用经过标准化的安全填充方案，并选择符合当前安全要求的密钥长度。"},{"id":"t0124","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ハイブリッド暗号","termZh":"混合加密","english":"Hybrid Cryptography","reading":"はいぶりっどあんごう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ハイブリッド暗号は、共通鍵暗号の高速性と公開鍵暗号の安全な鍵配送という長所を組み合わせる方式である。大量データそのものを公開鍵暗号で処理するのではなく、まずランダムな共通鍵（セッション鍵）を生成して本文をAESなどで暗号化し、そのセッション鍵だけを受信者の公開鍵で暗号化する。受信者は自分の秘密鍵でセッション鍵を取り出し、その鍵で本文を復号する。\n\n【流れ】\n① 送信者：セッション鍵Kを生成\n② 本文をK（共通鍵）で高速に暗号化\n③ Kを受信者の公開鍵で暗号化\n④ 「暗号化本文＋暗号化K」を送信\n⑤ 受信者：自分の秘密鍵でKを復号\n⑥ Kで本文を復号\n\nTLSや暗号化メールなど多くの実用システムは、この「データは共通鍵、鍵の配送・共有は公開鍵系」という考え方を利用する。","explanationZh":"混合加密把“对称加密速度快”和“公钥密码便于安全交换密钥”两个优点结合起来。实际系统通常不会用公钥密码直接加密大量正文，而是先生成随机会话密钥，用AES等对称算法加密正文，再仅使用接收方公钥加密会话密钥。接收方用自己的私钥恢复会话密钥，再用该会话密钥解密正文。\n\n【基本流程】\n① 发送方生成随机会话密钥K\n② 用K（对称密钥）高速加密正文\n③ 用接收方公钥加密K\n④ 发送“加密后的正文＋加密后的K”\n⑤ 接收方用自己的私钥解密K\n⑥ 用K解密正文\n\nTLS、加密邮件等很多实际系统都采用“数据用对称密钥加密，密钥交换/保护使用公钥密码机制”的思想。"},{"id":"t0125","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ハッシュ関数","termZh":"哈希函数","english":"Hash Function","reading":"はっしゅかんすう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"任意の長さのデータから固定長の値（ハッシュ値）を生成する関数である。SHA-256はその一例で、SHA-2ファミリーに属する暗号学的ハッシュ関数である。この関数は、元のデータがわずかに変わるだけでも、全く異なるハッシュ値を生成する特性を備えており、データの整合性を確認する手段として利用される。具体的には、デジタル署名やデータの改ざん検知において重要な役割を果たしている。SHA-256は、256ビットのハッシュ値を出力し、セキュリティ性能が非常に高いため、暗号通貨やセキュリティプロトコルでも広く使用されている。また、ハッシュ関数は高速に計算できる上、元のデータを復元することは極めて困難であるため、データ保護の観点からも重宝されている。","explanationZh":"指把任意长度输入映射为固定长度摘要值的函数。密码学哈希函数应具有抗原像、抗第二原像和抗碰撞等性质，并具有输入微小变化导致输出显著变化的特征。SHA-256 会输出 256 位摘要，常用于完整性校验、数字签名和多种安全协议。哈希是单向摘要，不等同于可解密的加密。"},{"id":"t0126","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"鍵管理","termZh":"密钥管理","english":"Key Management","reading":"かぎかんり","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"暗号技術において、機密情報を保護するために使用される鍵を作成、配布、保管、使用、破棄する一連のプロセスである。鍵は、データの暗号化や復号化に必要不可欠な要素であり、適切に管理しなければ情報の安全性が損なわれる。具体的には、企業や組織では、鍵の生成から始まり、どのユーザーがどの鍵を扱えるかを管理するアクセス制御、鍵が必要なくなった際の適切な破棄方法などが含まれる。さらに、鍵管理システムを導入することで、自動的に鍵の更新や監査が行えるため、高いセキュリティを維持することが可能となる。このように、鍵管理は情報セキュリティにおいて非常に重要な役割を果たす。","explanationZh":"指对密码密钥从生成、分发、存储、使用、轮换、备份、恢复到吊销和销毁的全生命周期管理。密钥安全直接决定加密系统的实际安全性，因此需要限制访问权限、采用安全存储（如 HSM）、建立轮换和审计机制，并在密钥泄露或失效时及时处置。"},{"id":"t0127","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ストレージ暗号化","termZh":"存储加密","english":"Storage Encryption","reading":"すとれーじあんごうか","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"データが保存されているディスクやストレージデバイス上の情報を保護するための技術である。この手法では、データが元の形式ではなく、暗号化された形式で保存され、許可されたユーザーだけがそのデータにアクセスできるようにする。具体的には、ハードディスクやクラウドストレージ内のファイルが暗号化されることで、不正アクセスや盗難に対する防御を強化する役割を果たす。例えば、企業が顧客の個人情報を管理する際にストレージ暗号化を用いることで、情報漏洩リスクを軽減し、セキュリティを向上させることができる。このように、重要なデータを守るための基本的な手段となっている。","explanationZh":"指对磁盘、卷、数据库或云存储中的静态数据进行加密，使未获得密钥的主体即使取得存储介质也难以读取内容。可采用全盘加密、卷加密或云端透明加密等方式。其能够降低设备失窃和存储介质泄露带来的风险，但仍需要可靠的密钥管理和访问控制。"},{"id":"t0128","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ファイル暗号化","termZh":"文件加密","english":"File Encryption","reading":"ふぁいるあんごうか","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"デジタル情報を不正アクセスから保護するための技術である。具体的には、ファイルの内容を特定のアルゴリズムを用いて変換し、読み取れない形式に変える過程を指す。この変換作業により、元のデータは暗号化された状態となり、許可されたユーザーだけが暗号を解読して内容を確認できるようになる。例えば、個人情報や機密情報を扱う企業で、ファイル暗号化を行うことでデータ漏えいのリスクを低減することができる。また、ストレージデバイスやクラウドサービスのセキュリティを強化するためにも重要な手段とされる。","explanationZh":"指对单个文件或一组文件的内容使用密码算法转换为不可直接读取的密文，只有具有相应密钥和权限的用户才能解密访问。文件加密适合保护个人信息、机密文档及需在不同介质或云服务中传输/保存的数据，是降低数据泄露风险的常见措施。"},{"id":"t0129","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"危殆化","termZh":"安全性受损／失陷（Compromise）","english":"Compromise","reading":"きたいか","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報やデータが外部に漏洩したり、不正にアクセスされたりすることで、そのセキュリティが損なわれる状態を指す。特に暗号技術の文脈では、暗号化されたデータが解読されるリスクを含む。このような状態が発生すると、情報の機密性が失われ、悪用される可能性があるため、企業や組織はセキュリティ対策を強化する必要がある。例えば、過去にある企業のデータベースが危殆化した場合、その情報がサイバー攻撃者によって利用されることで、顧客情報や機密データが悪用される恐れがあるため、迅速な対処が求められる。","explanationZh":"指系统、账户、密钥或数据的安全属性已被破坏，例如未经授权访问、密钥泄露、数据泄露或控制权被攻击者取得。在密码学场景中，“密钥被攻破/泄露”意味着不能再假定相关加密保护有效。发生失陷后应迅速隔离、吊销凭据或密钥、调查影响范围并执行恢复。"},{"id":"t0130","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"デジタル署名","termZh":"数字签名","english":"Digital Signature","reading":"でじたるしょめい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"デジタル署名は、送信者の真正性、データの完全性、否認防止を確認するための仕組みである。暗号化による機密性とは目的が異なり、デジタル署名そのものは本文を秘密にする機能ではない。\n\n【署名の生成】\n① 送信者がメッセージにハッシュ関数を適用してメッセージダイジェストを作る。\n② 送信者が「自分の秘密鍵」を使って署名値を生成する。\n③ メッセージとデジタル署名を受信者へ送る。\n\n【署名の検証】\n④ 受信者は受け取ったメッセージから同じハッシュ値を計算する。\n⑤ 「送信者の公開鍵」で署名を検証する。\n⑥ 検証結果が一致すれば、署名後に内容が改ざんされていないことと、対応する秘密鍵の所有者による署名であることを確認できる。\n\n【試験ポイント】署名＝『自分の秘密鍵で署名 → 相手が自分の公開鍵で検証』。暗号化＝『相手の公開鍵で暗号化 → 相手の秘密鍵で復号』。","explanationZh":"数字签名用于确认发送者身份真实性、数据完整性，并支持不可否认性。它与“加密保密”的目的不同：数字签名本身并不会把正文变成秘密内容。\n\n【生成签名】\n① 发送方先对消息计算哈希，得到消息摘要。\n② 发送方使用“自己的私钥”生成数字签名。\n③ 将消息和数字签名一起发送。\n\n【验证签名】\n④ 接收方对收到的消息重新计算哈希。\n⑤ 使用“发送方的公钥”验证数字签名。\n⑥ 验证成功时，可以确认签名后的内容未被篡改，并确认签名由对应私钥持有者生成。\n\n【考试速记】签名＝“自己的私钥签名 → 对方用自己的公钥验证”；保密加密＝“对方的公钥加密 → 对方的私钥解密”。"},{"id":"t0919","chapterId":"c01","termJa":"暗号化メールとデジタル署名の流れ","termZh":"加密邮件与数字签名流程","english":"Encrypted and Signed Email Flow","reading":"あんごうかめーるとでじたるしょめいのながれ","breadcrumb":"SG補足｜暗号・電子メール","explanationJa":"メールで「機密性」と「真正性・完全性」の両方を実現する典型的な考え方は、デジタル署名と暗号化を組み合わせることである。試験では次の流れで整理すると分かりやすい。\n\n【送信者A】\n① 本文のハッシュ値を計算\n② Aの秘密鍵でデジタル署名を生成\n③ 本文＋署名をまとめる\n④ ランダムな共通鍵Kで本文＋署名を暗号化\n⑤ Kを受信者Bの公開鍵で暗号化\n⑥ 暗号化データを送信\n\n【受信者B】\n⑦ Bの秘密鍵でKを復号\n⑧ Kで本文＋署名を復号\n⑨ Aの公開鍵で署名を検証\n⑩ 本文のハッシュを比較し、改ざんがないか確認\n\nこのように、暗号化は機密性、デジタル署名は真正性・完全性・否認防止を主に担当する。実際のS/MIME等では証明書を使って公開鍵と本人を結び付ける。","explanationZh":"电子邮件如果既要求“保密”，又要求“确认发送者和内容未被篡改”，通常会组合数字签名与加密。考试中可以按下面的典型流程理解：\n\n【发送方A】\n① 对正文计算哈希\n② 用A自己的私钥生成数字签名\n③ 把正文和签名组合起来\n④ 生成随机对称会话密钥K，用K加密正文＋签名\n⑤ 用接收方B的公钥加密K\n⑥ 发送密文\n\n【接收方B】\n⑦ 用B自己的私钥解密K\n⑧ 用K解密正文＋签名\n⑨ 用A的公钥验证数字签名\n⑩ 对正文重新计算哈希并比较，确认未被篡改\n\n因此：加密主要负责机密性；数字签名主要负责真实性、完整性和不可否认性。S/MIME等实际系统还会通过数字证书把公钥与身份绑定。","chapterJa":"情報セキュリティ","chapterZh":"信息安全"},{"id":"t0131","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"タイムスタンプ","termZh":"时间戳","english":"Timestamp","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"データやメッセージに特定の時刻を付加して、その正当性を証明する仕組みである。これは、情報がいつ作成または送信されたかを示し、改ざんの防止や信頼性の向上に寄与する。具体的には、電子メールやデジタル署名、ブロックチェーン技術などに利用されており、情報の整合性を保持するために重要な役割を果たす。例えば、契約書のデジタル署名では、タイムスタンプが付与されることで、その契約が特定の時間に締結されたことが証明され、法的効力を持つことが可能になる。このように、タイムスタンプはセキュリティと信頼性を高めるための重要な技術である。","explanationZh":"指将可信时间信息与数据摘要等绑定，用来证明某份电子数据在特定时间已经存在且之后未被改变的机制。可信时间戳常由时间戳机构（TSA）签发，可与数字签名配合用于电子合同、长期证据保存等场景，提高电子数据的可验证性和可信度。"},{"id":"t0132","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"メッセージダイジェスト","termZh":"消息摘要（Message Digest）","english":"Message Digest","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"データの内容を要約し、一意の短いハッシュ値に変換する技術である。この値は、元のデータが変更されていないか確認する手段として使われる。具体的には、一定の長さの数値列が生成され、少しの変更でもハッシュ値が大きく変わる特性を持つため、データの整合性を確保するのに役立つ。例えば、ファイルが正しくダウンロードされたか確認する際に、ダウンロード元が提供するハッシュ値と比較することで、データが改ざんされていないかを検証できる。これにより、認証やデジタル署名といったセキュリティ機能と密接に関連している。","explanationZh":"指对消息或文件计算得到的固定长度哈希值，可作为数据内容的“指纹”用于完整性校验。若原始数据发生变化，其摘要通常也会改变。下载文件时可将计算出的摘要与发布方提供的值比较，以发现传输错误或篡改。消息摘要也是数字签名等机制中的基础组成部分。"},{"id":"t0133","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"メッセージ認証","termZh":"消息认证","english":"Message Authentication","reading":"めっせーじにんしょう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"デジタル通信においてメッセージの内容が改ざんされていないことを確認するための技術である。これにより、受信者はメッセージが信頼できる送信者からのものであり、偽造や変更が行われていないことを保証される。一般的には、ハッシュ関数や暗号技術を使用してメッセージに付加される認証コードを生成し、受信時にそのコードを確認することで認証が行われる。この技術は、電子メールやオンライン取引など、多様なデジタル通信において広く利用されており、情報の整合性と真実性を確保するために重要な役割を果たしている。","explanationZh":"指验证消息来源真实性和内容完整性的技术，使接收方能够确认消息由持有相应认证凭据的一方生成，并且在传输过程中未被篡改。常通过消息认证码（MAC）、数字签名等机制实现，广泛用于网络协议和在线交易。"},{"id":"t0134","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"MAC","termZh":"消息认证码（MAC）","english":"Message Authentication Code","reading":"まっく","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"データの整合性と認証を確保するために使用される技術である。具体的には、送信者が特定のメッセージに対して生成した短いコードで、受信者はそのコードを使ってメッセージが改ざんされていないかを確認することができる。このコードは、メッセージ本体と秘密鍵を組み合わせて作成されるため、正しい鍵を持たない者が同じコードを再現することは極めて困難である。このため、MACは安全な通信を実現する重要な要素として、オンラインバンキングや電子メールの認証に広く利用されている。","explanationZh":"由消息和共享秘密密钥计算得到的固定长度认证值，用于验证消息完整性和来源认证。只有持有秘密密钥的双方才能生成和验证有效 MAC，因此攻击者即使修改消息，也难以生成匹配的认证码。HMAC 是常见的 MAC 构造方式。"},{"id":"t0135","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"チャレンジレスポンス認証","termZh":"挑战—响应认证","english":"Challenge-Response Authentication","reading":"ちゃれんじれすぽんすにんしょう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ユーザーの身元を確認するための認証方式の一つである。この仕組みでは、サーバがクライアントに対して「チャレンジ」と呼ばれるランダムなデータを送信する。クライアントはそのデータを元に「レスポンス」を生成し、サーバに返す。サーバは受け取ったレスポンスを検証することで、正しいユーザーであることを確認する。これにより、パスワードを送信することなく、ネットワークを介した認証が可能となり、盗聴などの攻撃からの防御にも効果的である。セキュリティが重視されるシステムで幅広く利用されている。","explanationZh":"一种不直接发送长期秘密的认证方式。验证方先发送随机“挑战值”，被验证方利用共享秘密或私钥计算响应并返回，验证方检查响应是否正确。由于每次挑战通常不同，截获旧响应也难以直接重用，可降低窃听和重放攻击风险。"},{"id":"t0136","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"リスクベース認証","termZh":"基于风险的认证（RBA）","english":"Risk-Based Authentication","reading":"りすくべーすにんしょう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ユーザーのログイン試行に対し、リスクの高い行動を識別して認証の厳格さを調整する技術である。この認証方式では、ユーザーのアクセス状況や行動履歴、デバイスの安定性などを考慮し、不審な点があれば追加の認証手続きを要求する。例えば、普段は自宅からのみアクセスするユーザーが海外からログインを試みた場合、リスクが高いと判断され、SMS認証やセキュリティ質問の入力を求めることがある。このように、ユーザーごとのリスクを考慮することで、安全性を向上させると同時に、通常のログインではスムーズに利用できる利点もあり、バランスの取れたセキュリティ対策として有効である。","explanationZh":"指根据登录的上下文和风险水平动态决定认证强度的机制。系统可综合用户历史行为、设备、地理位置、网络环境和异常特征等信息；若检测到高风险登录，则要求额外验证或阻止访问，而正常低风险访问可保持较顺畅的体验。"},{"id":"t0137","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ログイン","termZh":"登录（Login）","english":"Login","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"コンピュータシステムやオンラインサービスにアクセスするための認証手続きである。これは、利用者が自身の識別情報である利用者IDと秘密鍵であるパスワードを入力することにより行われる。ログインの目的は、システムがその利用者が正当な権利を持っているか確認することであり、安全に情報や機能を利用できるようにすることである。例えば、メールサービスや銀行のオンラインバンキングでは、利用者が自分のアカウントにアクセスするためにログインが不可欠であり、不正アクセスを防ぐためにパスワードは強固であるべきとされる。これにより、データや個人情報の保護が図られる。","explanationZh":"指用户通过提供身份标识和认证凭据进入计算机系统或在线服务的过程。常见方式包括用户名加密码，也可结合安全密钥、生物特征或多因素认证。登录的目的在于确认访问者身份并根据授权规则提供相应资源，而密码本身属于认证秘密，并不是“私钥”。"},{"id":"t0138","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"アクセス管理","termZh":"访问控制","english":"Access Control","reading":"あくせすかんり","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"情報システムやネットワークにおいて、誰がどのリソースにアクセスできるかを制御する仕組みである。これは、ユーザーの認証情報に基づいて、特定のデータや機能へのアクセスを許可または拒否する機能を含む。具体的な方法としては、ユーザー名やパスワードを用いてログインし、ユーザーの権限に応じてアクセスを決定することである。情報漏洩や不正利用を防ぐために極めて重要であり、企業や組織で広く利用される。また、役割ベースのアクセス制御や、条件付きアクセスといった手法を用いることで、より細かい制御が可能となり、セキュリティを強化することができる。","explanationZh":"指根据主体身份、角色、属性和策略，决定谁可以对哪些信息或系统资源执行哪些操作的安全机制。通常包括身份认证、授权和权限执行，可采用基于角色的访问控制（RBAC）、基于属性的访问控制（ABAC）等方式。适当的访问控制是防止信息泄露和未授权使用的基础。"},{"id":"t0139","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ICカード","termZh":"IC 卡／集成电路卡","english":"Integrated Circuit Card","reading":"あいしーかーど","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"集積回路（IC）が内蔵されたカードである。このカードは、電子的な情報を安全に保存し、認証や支払いなど多様な用途に使用される。例えば、交通系駅の改札口での自動改札や、電子マネーとして店舗での支払いに利用される。読み取り機にかざすだけで情報を読み取れるため、使いやすさが特徴である。また、暗号化されたデータを持つため、不正利用を防ぐセキュリティ機能も備えている。そのため、IDカードや健康保険証、銀行カードなど、さまざまな分野で広く利用されている。","explanationZh":"指内置集成电路芯片、能够安全存储和处理数据的卡片，可用于身份认证、支付、交通票证等场景。部分 IC 卡具备密码运算和防篡改能力，可比普通磁条卡提供更强的安全保护，常见于身份卡、银行卡和各种智能卡应用。"},{"id":"t0140","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"PINコード","termZh":"个人识别码（PIN）","english":"Personal Identification Number","reading":"ぴんこーど","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"利用者が自分を特定するために使用する暗証番号である。通常、4桁から6桁の数字で構成されており、ATMやオンラインサービス、スマートフォンのロック解除などで広く用いられる。ユーザーが設定した秘密の番号であり、他者が知ってはいけないものである。正しいPINを入力することで、ユーザーは自分のアカウントやサービスにアクセスできるようになるため、強固なセキュリティ手段とされる。安全性を高めるためには、他の人と共有せず、定期的に変更することが推奨される。これは、情報漏洩や不正アクセスを防ぐために非常に重要である。","explanationZh":"一种仅由用户掌握的短数字口令，常用于银行卡、智能卡、手机解锁或其他认证场景。PIN 通常与特定设备或持有物结合使用。为提高安全性，应避免使用易猜数字、与他人共享或在不可信环境中输入，并结合尝试次数限制等机制防止暴力猜测。"},{"id":"t0141","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ワンタイムパスワード","termZh":"一次性密码（OTP）","english":"One-Time Password","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"一度限りの利用が可能なパスワードである。通常のパスワードに比べて、よりセキュリティが高く、特にオンラインサービスへのログイン時に多く使われる。ユーザーは、ログイン時に自分のアカウントにアクセスするための通常のパスワードとともに、追加の認証としてこのワンタイムパスワードを使用する。多くの場合、スマートフォンのアプリやSMSなどを通じて生成され、ユーザーがリアルタイムで受け取る仕組みになっている。これにより、万が一通常のパスワードが漏洩した場合でも、不正アクセスを防ぐ効果が期待できる。二要素認証の一部として利用され、オンラインでの安全な取引をサポートする重要な技術である。","explanationZh":"指仅在一次认证或短时间内有效的动态密码，常由认证器应用、硬件令牌或短信等方式提供。由于旧的 OTP 不能再次使用，它能降低长期密码被窃取后的部分风险，通常作为多因素认证的一个要素使用。基于应用或安全令牌的 OTP 通常比短信更能抵御号码劫持等风险。"},{"id":"t0142","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"多要素認証","termZh":"多因素认证（MFA）","english":"Multi-Factor Authentication","reading":"たようそにんしょう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"利用者が自分の身元を確認するために複数の異なる方法を用いる認証方式である。この方式は、通常、記憶情報（パスワード）、所有情報（スマートフォンやトークン）、生体情報（指紋や顔認証）の三つの要素から構成される。例えば、オンラインバンキングにおいては、まずパスワードを入力し、その後にスマートフォンに送信された確認コードを入力することが求められる。このように複数の認証要素を組み合わせることで、不正アクセスを防ぎ、セキュリティを強化することができるため、現在多くのサービスで導入されている。特に、重要な情報を扱うサイトやサービスにおいては、利用者が安全にアクセスできるようにするために欠かせない手段である。","explanationZh":"指使用两个或更多来自不同类别的认证因素验证用户身份，例如“所知因素”（密码/PIN）、“所持因素”（手机/安全密钥）和“固有因素”（指纹/人脸）。即使一种因素泄露，攻击者仍需要其他独立因素，因此能够显著降低账户被接管风险。"},{"id":"t0143","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"多段階認証","termZh":"多步骤认证（Multi-Step Authentication）","english":"Multi-Step Authentication","reading":"ただんかいにんしょう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ユーザーの本人確認を強化するためのセキュリティ手法である。通常、一つの認証手段だけでは不十分と考えられており、二つ以上の異なる認証要素を組み合わせることで、より安全に利用者を認証する。例えば、パスワード（知識要素）に加え、スマートフォンに送られる確認コード（所持要素）や指紋認証（生体要素）などが用いられる。また、多段階認証は不正アクセスのリスクを大幅に軽減し、データやアカウントの安全性を確保する手段として、多くのオンラインサービスで採用されている。これにより、単純なパスワードに依存することなく、より高いレベルのセキュリティを実現することができる。","explanationZh":"指把身份验证分为两个或多个连续步骤完成的认证流程。各步骤可以使用不同因素，也可能重复使用同一类别的凭据；因此“多步骤”不必然等同于“多因素”。若多个步骤确实来自不同认证因素类别，则也可以同时构成 MFA。"},{"id":"t0144","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"パスワードレス認証","termZh":"无密码认证（Passwordless Authentication）","english":"Passwordless Authentication","reading":"ぱすわーどれすにんしょう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ユーザーがパスワードを使用せずに自分を確認するための方法である。これにより、パスワードを入力する手間を省きつつ、セキュリティを強化することが可能になる。具体的には、顔認証や指紋認証、セキュリティキーなどの方法を用いてユーザーの身元を確認する。FIDOUAFやFIDOU2F、FIDO2、WebAuthnなどの技術がこれに該当し、これらはWebサービスやアプリケーションにおいて安全な認証手段を提供する。パスワードが不要なため、フィッシングや情報漏洩のリスクが低減するほか、ユーザーにとってもより快適な利用体験をもたらす。これが普及することで、オンラインセキュリティの向上が期待されている。","explanationZh":"指用户无需输入传统共享密码即可完成身份验证的方式，例如使用生物识别配合设备密钥、FIDO2 安全密钥或 WebAuthn。FIDO UAF、U2F/FIDO2 等技术通过公钥密码降低服务器保存密码和钓鱼窃密带来的风险，并改善用户体验。"},{"id":"t0145","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"EMV3-Dセキュア","termZh":"EMV 3-D Secure（3DS2）","english":"EMV 3-D Secure","reading":"いーえむぶいすりーでぃーせきゅあ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"オンライン決済における利用者認証のためのセキュリティ技術の一つである。この技術は、クレジットカードやデビットカードなどのトランザクションを保護する目的で開発された。従来の3-Dセキュアよりもさらに進化しており、ユーザーの認証プロセスを簡素化するために、機械学習を用いたリスク評価を行うことができる。例えば、購入者がオンラインで商品を購入する際に、EMV3-Dセキュアはリアルタイムで購入者の行動を分析し、取引が安全であることを確認する。このプロセスにより、ユーザーが不正アクセスの脅威から守られると同時に、スムーズな取引を実現し、カートの放棄を減少させる効果もある。以上のように、EMV3-Dセキュアは利用者の安全を守る重要な技術である。","explanationZh":"一种用于银行卡在线无卡支付的持卡人认证协议。它可在交易过程中传递设备、交易和行为等风险信息，由发卡方进行风险评估；低风险交易可减少额外验证，高风险交易则可能要求挑战认证。其目标是在降低欺诈的同时改善支付体验。"},{"id":"t0146","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"セキュリティトークン","termZh":"安全令牌（Security Token）","english":"Security Token","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"利用者の認証を行うために使用されるデジタルな情報の一種である。このトークンは、特定のユーザーに対するアクセス権限を示し、安全な通信やデータ保護を実現するために重要な役割を果たしている。例えば、オンラインバンキングやクラウドサービスでは、ユーザーがログインする際に、パスワードだけでなく、セキュリティトークンによって二重の認証が行われることが一般的である。このトークンは、時間制限がある場合や特定のデバイスに紐付けられることが多く、セキュリティを強化するための手段として効果的である。さらに、ハードウェアトークンやソフトウェアトークンなど、さまざまな形態が存在し、利用される環境によって選択されることが多い。","explanationZh":"指用于证明用户身份或授权状态的硬件、软件或数字凭据。在认证场景中可表现为一次性密码令牌、硬件安全密钥、软件认证器或访问令牌等。令牌可能具有有效期、与设备绑定或受密码学保护，用于加强账户和系统访问安全。"},{"id":"t0147","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"シングルサインオン","termZh":"单点登录（SSO）","english":"Single Sign-On","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"複数のサービスやアプリケーションに対して、ユーザーが一度のログインでアクセスできるようにする仕組みである。このシステムを利用することで、ユーザーは各サービスごとにパスワードを管理する必要がなくなり、使い勝手が向上する。例えば、ある企業の社内システムにおいて、メール、カレンダー、文書共有サービスなど、異なるアプリケーションにログインする際に、最初の一度だけログインすれば、その後は自動的に他のサービスにもアクセスできる。このように、シングルサインオンはユーザーの負担を軽減し、安全性を高める効果が期待される。ただし、システムが一つのアカウントに依存するため、セキュリティ対策が重要である。","explanationZh":"指用户完成一次身份认证后，即可访问多个相互信任的应用或服务，而无需分别重复登录。SSO 能减少密码数量、改善用户体验并集中身份管理，但身份提供方或主账户一旦失陷可能影响多个系统，因此应配合强认证、会话保护和集中审计。"},{"id":"t0148","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"CAPTCHA","termZh":"验证码／CAPTCHA","english":"Completely Automated Public Turing test to tell Computers and Humans Apart","reading":"きゃぷちゃ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"コンピュータと人間を区別するためのテストである。主にWebサイトやオンラインサービスで利用者が自動プログラムでないことを確認する目的で使われる。例えば、歪んだ文字や数字の画像を表示し、ユーザーにその内容を入力させる形式が一般的である。これにより、自動的に操作を行うボットからの不正アクセスを防ぐことができる。さらに、最近では、画像認識を利用した形式や、チェックボックスをクリックするだけの簡単な方法なども導入されており、ユーザーの利便性を向上させながらセキュリティを確保する工夫が行われている。ユーザーにとっては、手間に感じることもあるが、サイトの安全性を保つために重要な役割を果たしている。","explanationZh":"一种自动化测试，用于区分真人用户与自动程序或机器人，常见形式包括字符识别、图片选择或基于行为风险的验证。CAPTCHA 可减少自动注册、撞库、刷票等滥用，但并非完整的身份认证机制，应与限速、风控等措施配合使用。"},{"id":"t0149","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"パスワードリマインダ","termZh":"密码找回／密码重置提示机制","english":"Password Reminder","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ユーザーが忘れた際にパスワードを思い出させるための仕組みや機能である。通常、アカウントの設定段階でユーザーは、秘密の質問やメールアドレスを登録することが求められる。この情報を利用して、パスワードを再設定する手助けを行う。例えば、あるサービスにおいて、ユーザーが「好きな色は何ですか？」という質問に答えることで、本来のパスワードを再確認することが可能となる。これにより、他人が無断でアカウントにアクセスするリスクを低減し、利用者のセキュリティを向上させる役割を果たしている。","explanationZh":"指帮助用户在忘记密码时恢复账户访问的机制。现代安全实践通常通过验证注册邮箱、手机、恢复码或其他身份因素后“重置”密码，而不应向用户显示原密码。传统安全问题容易被猜测或通过公开信息获取，因此应谨慎使用并配合更强的恢复认证措施。"},{"id":"t0150","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"eKYC","termZh":"电子化客户身份识别（eKYC）","english":"Electronic Know Your Customer","reading":"いーけーわいしー","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"顧客確認のプロセスを電子的に行う手法である。この仕組みは、金融機関やサービスプロバイダーが顧客の身元を確認する際に、書類の提出や対面による確認を必要とせず、オンライン上で迅速かつ安全に行うことを可能にする。例えば、スマートフォンのカメラを使用して本人確認書類を撮影し、その情報を自動的に取得・照合することにより、短時間での登録が実現される。このように利用者の利便性を高めつつ、セキュリティにも配慮した手法であり、特にオンラインサービスの普及が進む中で重要性が増している。","explanationZh":"指通过电子方式完成 Know Your Customer（了解你的客户）和本人身份核验流程。金融机构或在线服务可通过拍摄身份证件、读取芯片、活体检测、影像比对等方式远程验证身份，从而减少线下面对面办理。eKYC 需要同时满足身份真实性、防欺诈、隐私和法规合规要求。"},{"id":"t0151","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"身体的特徴","termZh":"生物特征（身体特征）","english":"Biometric Characteristics","reading":"しんたいてきとくちょう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"人間の身体に固有の特徴を指し、生体認証技術で使用されるものである。例えば、静脈パターン認証は、手のひらや指の静脈の配置を利用して個人を特定する手法で、通常の指紋よりも高い精度で認識が行える。虹彩認証は、目の虹彩の模様を使って認識する方法で、個々の虹彩は非常に多様であるため、セキュリティが高いとされる。顔認証は、顔の形や特徴を分析して本人確認を行う技術で、スマートフォンなどにも広く利用されている。さらに、網膜認証は網膜の血管パターンを用いる方式で、これも非常に高い認識精度を誇る。これらの技術は、セキュリティ向上だけではなく、生産性の向上にも寄与している。","explanationZh":"指可用于识别个人的相对独特的生理特征，例如指纹、脸部特征、虹膜、视网膜和静脉纹理等。生物识别系统通过采集并比较这些特征完成身份验证。不同生物特征在准确率、可用性、隐私和抗伪造能力上各有差异，需要根据场景选择并保护生物模板数据。"},{"id":"t0152","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"行動的特徴","termZh":"行为生物特征","english":"Behavioral Characteristics","reading":"こうどうてきとくちょう","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"個人の特性を元にした生体認証の一手法である。この技術は、声や署名、タイピングのパターンなど、人が行う特定の行動に基づいて本人を識別することを目的としている。例えば、声紋認証では、個人の声の特徴を記録し、それを利用して本人確認を行う。一方、署名認証では、サインの形状や書き方、速度などが分析され、正当な持ち主かどうかを判断する。これらの方法は、一般的なパスワードやID に比べて、より個別性が高いため、セキュリティが向上する。さらに、これらの時間とともに変化することが少ないため、安定性のある認証手段として評価されている。","explanationZh":"指基于个人行为模式进行身份识别或连续认证的特征，例如语音特征、签名动态、击键节奏、鼠标或触屏操作习惯等。与静态密码相比，这些特征更难直接复制，但会受环境、状态和时间变化影响，因此通常结合统计模型和其他认证因素使用。"},{"id":"t0153","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"本人拒否率","termZh":"错误拒绝率（FRR）","english":"False Rejection Rate","reading":"ほんにんきょひりつ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"生体認証システムにおける指標の一つである。この率は、正当なユーザーがシステムによって本人でないと判断される確率を示すものである。例えば、指紋認証や顔認証などのシステムで、正しい指紋や顔を入力しても認証が通らないケースが該当する。本人拒否率が高いと、ユーザーは何度も認証を試みなければならず、快適さや利便性が低下するため、システムの使いやすさが損なわれることになる。逆に、本人拒否率が低いことは、スムーズなアクセスを保証するため、システムの信頼性を示す重要な要素となる。このため、技術者は一般的に、本人拒否率を意識してシステムの調整や改良を行う。","explanationZh":"生物识别系统将合法本人错误判定为“不匹配”并拒绝认证的比例。FRR 越高，合法用户越容易遇到认证失败，影响可用性和用户体验。调节匹配阈值通常会同时影响 FRR 和 FAR，因此系统需要根据安全性与便利性的要求进行平衡。"},{"id":"t0154","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"他人受入率","termZh":"错误接受率（FAR）","english":"False Acceptance Rate","reading":"たにんうけいれりつ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"生体認証技術において、誤って他人を本人と認識してしまう割合を示す指標である。この値が高い場合、セキュリティ上のリスクが増大するため、信頼性の低い認証システムと見なされる。具体的には、例えば指紋リーダーを使用する場合、他人の指紋が誤って登録された指紋と一致してしまうケースの割合を示す。生体認証の性能を評価する際には、この他人受入率と、本人のみが認証されるべき割合（False Rejection Rate）とのバランスが重要で、理想的なシステムは、両者の値が低く抑えられることが求められる。これにより、安全で使いやすい生体認証が実現されるのである。","explanationZh":"生物识别系统将非本人错误判定为本人并允许通过认证的比例。FAR 越高，未授权人员被错误接受的风险越大，因此是衡量生物识别安全性的重要指标。FAR 与 FRR 通常存在阈值上的权衡，需要结合业务风险选择合适的工作点。"},{"id":"t0155","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"PKI","termZh":"公钥基础设施（PKI）","english":"Public Key Infrastructure","reading":"ぴーけーあい","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"デジタル通信における安全性を確保するための仕組みである。具体的には、公開鍵と秘密鍵を用いて情報の暗号化やデジタル署名を行うための技術とその関連サポートを指す。ユーザーやデバイス間での安全な認証を提供し、信頼性の高い通信を実現する。例えば、オンラインバンキングや電子メールの暗号化において、PKIによって取引の安全性が保たれている。デジタル証明書を発行する認証局（CA）が中心となり、各ユーザーや機関の信頼性を保証することで、悪意のある攻撃から情報を守ることができる。また、社内システムからインターネット上の広範囲なアプリケーションまで幅広く使用されており、安全なデジタルコミュニケーションの基盤を形成している。","explanationZh":"由证书、认证机构（CA）、注册与验证流程、密钥管理、证书状态服务及相关策略组成的信任体系，用于把实体身份与公钥建立可信绑定。PKI 支持 TLS、数字签名、设备和用户认证等场景，是大规模公钥信任管理的重要基础设施。"},{"id":"t0156","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"デジタル証明書","termZh":"数字证书／公钥证书","english":"Digital Certificate","reading":"でじたるしょうめいしょ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"インターネット上で安全に通信を行うための電子的な証明書である。公開鍵証明書とも呼ばれる。この証明書は、特定の公開鍵とその持ち主の情報を結びつけ、正当性を保証する役割を果たしている。たとえば、Webサイトがデジタル証明書を持つことで、そのサイトが本物であることを訪問者に証明でき、情報の盗聴や改ざんを防ぐことができる。また、証明書は信頼された第三者機関（CA：Certification Authority）によって発行され、その信頼性が担保されるため、インターネット上の取引やコミュニケーションにおいて重要な役割を果たす。デジタル証明書を用いることで、安全にデータをやりとりしやすくなる。","explanationZh":"一种由可信签发机构签名的电子凭证，用于把某个公钥与主体身份、域名或设备等信息绑定。客户端可以验证证书签名、有效期、名称和吊销状态，从而判断所使用公钥是否可信。TLS 服务器证书是常见应用。"},{"id":"t0157","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"ルート証明書","termZh":"根证书","english":"Root Certificate","reading":"るーとしょうめいしょ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"公開鍵基盤（PKI）において、信頼の最上位に位置する証明書である。この証明書は、他の証明書に対して「信頼できる」と証明する役割を果たし、通常は認証局（CA）によって発行される。システムやアプリケーションがインターネット上の通信の安全性を確保するために不可欠であり、WebサイトのSSL/TLS証明書の信頼性を確認する際に使用される。たとえば、あるWebサイトがHTTPSで保護されている場合、その背後にはルート証明書が存在し、ブラウザはこのルート証明書を基にそのWebサイトが正当であることを確認する。一般的にオペレーティングシステムやブラウザに標準で組み込まれており、セキュリティを強化するための重要な要素である。","explanationZh":"位于 PKI 信任链顶端的证书，通常为根 CA 的自签名证书。操作系统、浏览器或应用会预置信任的根证书作为信任基础，并通过其公钥验证下级中间 CA 及终端证书形成的证书链。根私钥一旦失陷影响极大，因此需要严格保护。"},{"id":"t0158","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"トラストアンカー","termZh":"信任锚（Trust Anchor）","english":"Trust Anchor","reading":"","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"公開鍵基盤において信頼の基点となる要素である。具体的には、デジタル証明書の信頼性を判断するために使用される公開鍵のことを指す。信頼できる認証機関（CA）によって発行され、多くのシステムやアプリケーションがその情報に基づいて安全な通信を行う。例えば、WebサイトがSSL証明書を使用する際、その証明書の信頼性はトラストアンカーに依存している。このため、トラストアンカーが適切に管理されていることは、インターネット上でのセキュリティの確保において非常に重要である。信頼の基点を正しく設定することで、利用者は安心して情報をやり取りすることができる。","explanationZh":"指验证证书链或其他安全声明时预先被系统信任的起点，通常是根 CA 的公钥及相关身份信息。验证过程最终必须链到一个本地信任的信任锚，才能建立信任。信任锚的配置和维护直接影响整个证书信任体系的安全性。"},{"id":"t0159","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"中間CA証明書","termZh":"中间 CA 证书","english":"Intermediate Certificate Authority","reading":"ちゅうかんしーえーしょうめいしょ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"公開鍵基盤における証明書の一種である。この証明書は、信頼されたルートCA（認証局）から発行され、さらに下位のエンドエンティティ証明書を発行する役割を持つ。中間CA証明書を用いることで、公開鍵の発行と管理が階層的に行われ、セキュリティが向上する。具体的には、WebサイトのSSL/TLS証明書の発行プロセスにおいて、中間CAがユーザーや企業に発行した証明書が、ブラウザやデバイスで認証される際に、ルートCAに依存しない形で信頼性を確保できる。これにより、信頼関係を築いた複数の認証局が存在し、全体のインフラがより堅牢になる。","explanationZh":"指由根 CA 或上级 CA 签发、并具有继续签发下级证书能力的 CA 证书。实际 PKI 通常让中间 CA 负责日常签发服务器、客户端等终端证书，从而减少根私钥在线使用的风险。客户端通过中间 CA 构建到受信任根证书的完整证书链。"},{"id":"t0160","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"サーバ証明書","termZh":"服务器证书","english":"Server Certificate","reading":"さーばしょうめいしょ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"サーバの正当性を証明するためのデジタル証明書である。この証明書は、主にインターネット上での通信において、ユーザーがアクセスするWebサイトが信頼できるものであることを確認する役割を持っている。例えば、HTTPSプロトコルを使用するWebサイトでは、サーバ証明書がサーバとクライアント間の通信を暗号化している。これにより、第三者によるデータの盗聴や改ざんから保護される。認証局という第三者機関によって発行されるため、その信頼性が担保されている。実際の利用では、企業のWebサイトやオンラインバンキングなど、多くの場面で重要な役割を果たしており、安全なインターネット環境を支えている。","explanationZh":"用于证明服务器身份并提供其公钥的数字证书，最常见于 HTTPS/TLS。客户端验证证书中的域名、签发链、有效期和状态后，可与服务器建立经过认证的加密连接。证书本身负责身份与公钥绑定，实际通信加密由 TLS 协议协商的密码套件完成。"},{"id":"t0161","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"クライアント証明書","termZh":"客户端证书","english":"Client Certificate","reading":"くらいあんとしょうめいしょ","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"ユーザーやデバイスの身元を確認するために使用されるデジタル証明書である。この証明書は、公開鍵基盤（PKI）を利用して発行され、通信相手が真正であることを保証する役割を果たす。具体的には、Webサイトがクライアント証明書を要求することで、通信を行うクライアントが信頼できる者であるかどうかを確認できる。たとえば、企業内のシステムにアクセスする際に、従業員がクライアント証明書を持っていることで、システムからのアクセスが許可される。この仕組みにより、不正アクセスを防ぐことができ、特に金融や医療などの重要なデータを扱う場面で効果的である。高いセキュリティを必要とする環境において、重要な役割を果たしている。","explanationZh":"用于证明用户、设备或客户端身份的数字证书，通常由 PKI 中的认证机构签发。在双向 TLS 或企业内部系统中，服务器可以要求客户端提交证书，并验证其证书链、有效期和身份属性后决定是否允许访问。客户端证书可提供比仅使用密码更强的设备/主体认证能力。"},{"id":"t0162","chapterId":"c01","chapterJa":"情報セキュリティ","chapterZh":"信息安全","termJa":"CRL","termZh":"证书吊销列表（CRL）","english":"Certificate Revocation List","reading":"しーあーるえる","breadcrumb":"1 セキュリティ1-1 情報セキュリティ","explanationJa":"無効になったデジタル証明書の一覧である。証明書失効リストともいう。デジタル証明書は、インターネット上での通信の安全性を保証するために使用されるが、特定の理由でその有効性が失われることがある。このリストは、例えば、証明書が不正使用されたり、発行者が信頼できなくなった場合に更新される。証明書失効リストは、クライアントがサーバと安全に通信する際に、相手の証明書が有効かどうかを確認する手段となり、これにより不正なアクセスを防ぐ役割を果たす。これを利用することで、情報セキュリティを高め、安全な通信環境を維持することが可能となる。","explanationZh":"由证书颁发机构发布的已吊销证书清单，列出在原有效期结束前因私钥泄露、误签发或主体资格变化等原因而不再可信的证书。客户端可在验证证书时检查 CRL，以确认该证书是否已被吊销。实际系统也常结合 OCSP 等在线状态查询机制。"},{"id":"t0163","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティポリシーに基づく情報の管理","termZh":"基于信息安全策略的信息管理","english":"Information Security Policy-Based Information Management","reading":"じょうほうせきゅりてぃぽりしーにもとづくじょうほうのかんり","breadcrumb":"","explanationJa":"組織が情報を安全に管理するための原則やルールを定めたものである。このポリシーは、情報の取り扱いに関するガイドラインを提供し、データの機密性、完全性、可用性を確保することを目的としている。例えば、企業が顧客情報を扱う際に、このポリシーに基づいてアクセス権を制限したり、情報の暗号化を実施したりすることが具体的な実践となる。また、従業員に対して定期的な教育や訓練を行うことで、情報漏洩やサイバー攻撃から組織を守る意識を高めることができる。つまり、情報セキュリティポリシーは、組織の情報資産を守るために必要不可欠な管理手法である。","explanationZh":"指组织依据既定的信息安全方针、规则和程序，对信息的收集、使用、保存、共享和销毁进行管理，以保障机密性、完整性和可用性。具体措施可包括访问权限控制、数据加密、分类分级、备份，以及对员工开展持续的安全教育和培训，使组织的信息资产在统一规则下得到保护。"},{"id":"t0164","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報資産","termZh":"信息资产","english":"Information Assets","reading":"じょうほうしさん","breadcrumb":"","explanationJa":"組織が持つ情報やデータ、システム、知識など、価値を持つ資源のことを指す。これらは、業務の運営や意思決定において重要な役割を果たすため、適切な管理と保護が求められる。例えば、顧客情報や販売データ、技術文書などは、組織の競争力を左右する重要な情報資産である。情報資産を守るためには、情報セキュリティ管理が不可欠であり、アクセス制限、暗号化、バックアップなどの対策を講じることが重要である。また、情報資産の評価やリスク管理を行うことで、情報の漏洩や不正アクセスから組織を守る体制が醸成される。これは、信頼性の向上やビジネスの継続性を確保するために極めて重要な要素である。","explanationZh":"指对组织具有价值的信息、数据、系统、软件、设备、知识和相关服务等资源。客户资料、销售数据、技术文档等都可能属于信息资产。组织需要识别其所有者、价值和敏感程度，并通过访问控制、加密、备份和风险管理等措施实施适当保护，以支持业务连续性和组织目标。"},{"id":"t0165","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスクマネジメント","termZh":"风险管理","english":"Risk Management","reading":"","breadcrumb":"","explanationJa":"潜在的なリスクを特定し、それに対処するための計画を立てるプロセスである。特に情報セキュリティ管理においては、システムやデータに対して直面する脅威を理解し、評価することが重要である。具体的には、リスクを計測し、影響や発生確率を考慮して、リスクに対する対策を講じる。例えば、サイバー攻撃のリスクを評価し、必要に応じてセキュリティ強化やバックアップ体制を整えることで、損失を最小限に抑えることが可能となる。JIS Q 31000は、リスクマネジメントの国際的な基準を示しており、体系的かつ効果的なリスクマネジメントの導入を推進することを目指している。そのため、企業や組織はリスクを管理するためのフレームワークを整え、持続可能な運営を確保することが求められる。","explanationZh":"指系统地识别、分析、评价和处置风险，并持续监视和沟通风险的过程。信息安全风险管理需要了解资产、威胁、脆弱性、发生可能性和影响，然后选择适当的规避、降低、共享或接受措施。JIS Q 31000/ISO 31000 提供了通用风险管理原则和框架，帮助组织以一致方式管理风险。"},{"id":"t0166","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"監視","termZh":"监控（Monitoring）","english":"Monitoring","reading":"かんし","breadcrumb":"","explanationJa":"情報セキュリティ管理において、システムやネットワークの状態、動作、または使用状況を継続的に観察し、問題や異常を検知するプロセスを指す。特に、サイバー攻撃や不正アクセスの兆候を早期に発見するために重要な手段である。例えば、企業がネットワークトラフィックを監視して通常と異なるアクセスパターンを発見することで、攻撃をすばやく特定し対策を講じることができる。また、監視システムはログの収集や分析を自動化することができるため、人的ミスの削減や迅速な対応を実現する。これにより、全体的な情報セキュリティの強化につながる。","explanationZh":"指持续观察系统、网络、应用和用户活动，收集日志、流量和状态信息，以发现异常、故障或攻击迹象的过程。有效监控有助于尽早识别未授权访问和安全事件，并支持快速响应、取证和趋势分析。自动化日志集中与分析可降低人工遗漏并提升检测效率。"},{"id":"t0167","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティ事象","termZh":"信息安全事态／安全事件（Security Event）","english":"Information Security Incident","reading":"じょうほうせきゅりてぃじしょう","breadcrumb":"","explanationJa":"情報の機密性、完全性、可用性が脅かされる事象を指す。このような事象は、サイバー攻撃や内部不正アクセス、データ漏洩など多岐にわたる。例えば、企業がサイバー攻撃を受けて顧客情報が盗まれた場合、それは情報セキュリティ事象の一例である。また、誤って重要なデータを削除してしまった場合も、セキュリティ事象と見なされることがある。企業や組織は、これらの事象を迅速に特定し、対応するためのプロセスを整備することが求められる。適切な対策や教育を行うことで、再発防止を図ることが重要である。","explanationZh":"指表明可能违反安全策略、控制失效或出现与安全相关异常的可观察事件，例如异常登录、恶意代码告警或敏感数据误删除。严格来说，“安全事态（event）”不一定已经造成损害；当一个或多个事态很可能损害业务或信息安全时，才通常升级为“信息安全事件（incident）”。"},{"id":"t0168","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティインシデント","termZh":"信息安全事件（Incident）","english":"Information Security Incident","reading":"じょうほうせきゅりてぃいんしでんと","breadcrumb":"","explanationJa":"情報資産やシステムに対して発生した、セキュリティに関する問題や脅威のことである。具体的には、データの漏洩、不正アクセス、ウイルス感染などが含まれ、これらの事象が発生すると、企業や個人の情報が危険にさらされることになる。例えば、企業の顧客データベースに不正アクセスがあった場合、個人情報が盗まれる恐れがあるため、速やかに対策を講じる必要がある。このようなインシデントは、企業の信頼性を損なうだけでなく、法的な責任を伴うこともあるため、事前に対策を講じ、発生時には迅速に対応することが求められる。情報セキュリティの強化や、インシデント発生時の対応手順の整備は、重要な活動となっている。","explanationZh":"指已经或很可能对信息资产、业务或机密性、完整性、可用性造成不利影响的安全事件，例如数据泄露、未授权访问、恶意软件感染等。组织应建立事件报告、分级、遏制、根除、恢复和复盘流程，以降低损失并防止再次发生。"},{"id":"t0169","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"アカウント管理","termZh":"账户管理","english":"Account Management","reading":"あかうんとかんり","breadcrumb":"","explanationJa":"システムやアプリケーションにアクセスするためのユーザーアカウントを適切に管理するプロセスである。これには、アカウントの作成、削除、権限の設定、パスワードの管理などが含まれる。例えば、企業内の従業員が必要な情報にアクセスできるようにする一方で、役職が変わったり退職した際にはアクセス権を適切に変更または削除することが求められる。また、アカウント管理を強化するために、多要素認証などのセキュリティ対策を導入することが重要であり、これにより不正アクセスを防ぐことが可能となる。情報セキュリティ管理において、効果的な企業の安全性を向上させる基盤となる。","explanationZh":"指对用户和服务账户的整个生命周期进行管理，包括申请、创建、身份绑定、权限授予、密码/认证因素维护、定期复核、角色变更以及停用和删除。员工调岗或离职时必须及时调整或撤销权限，并可结合多因素认证和异常账户监控降低账户滥用风险。"},{"id":"t0170","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"最小権限の原則","termZh":"最小权限原则／按需知悉（Need-to-Know）","english":"need-to-know","reading":"さいしょうけんげんのげんそく","breadcrumb":"","explanationJa":"情報システムにおいて、各利用者が持つアクセス権を適切に設定し、管理することを指す。特に「need-to-know（最小権限）の原則」を採用することで、利用者は、自身の業務遂行に必要な情報のみにアクセスできるように制限される。この原則は、情報漏洩や不正アクセスを防ぐために重要である。例えば、ある社員が顧客の個人情報にアクセスする必要がない場合、そのアクセス権を与えないことで、より安全なデータ管理が実現する。また、アクセス権は利用者の役割や業務の変化に応じて、定期的に見直しが行われることが推奨される。このようにすることで、組織全体の情報セキュリティを強化し、リスクの低減を図ることができる。","explanationZh":"指用户、程序或系统只被授予完成其职责所必需的最少权限和信息访问范围。对没有业务需要的敏感数据不应授予访问权，并应随着岗位和业务变化定期复核权限。严格来说，“最小权限”与“need-to-know”含义相近但不完全相同：前者强调权限最少，后者强调仅访问业务需要知悉的信息。"},{"id":"t0171","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"クラウドサービスの責任共有モデル","termZh":"云服务责任共担模型","english":"Cloud Service Responsibility Model","reading":"くらうどさーびすのせきにんきょうゆうもでる","breadcrumb":"","explanationJa":"クラウドコンピューティング環境において、サービス提供者とユーザーの間でセキュリティやデータ管理の責任を明確に分ける仕組みである。具体的には、クラウドサービスの提供者はインフラストラクチャやプラットフォームのセキュリティを担う一方で、ユーザーはアプリケーションやデータの管理、アクセス制御などを行うことが求められる。たとえば、IaaS（Infrastructure as a Service）やPaaS（Platform as a Service）の利用においては、ユーザーがオペレーティングシステムやソフトウェアのセキュリティを管理する責任がある。これにより、セキュリティリスクを低減しつつ、利便性を向上させることができる。責任の範囲を理解し、それに基づいた適切な対策を講じることが、クラウドサービスを安全に利用する上で重要である。","explanationZh":"指云服务提供商与客户之间按照服务模式划分安全责任的原则。云厂商通常负责“云本身”的基础设施安全，客户负责自身数据、身份、权限和配置等；在 IaaS、PaaS、SaaS 中双方责任边界不同。例如 IaaS 客户通常还需负责操作系统和应用安全，而 SaaS 中更多底层责任由服务商承担。理解边界是安全使用云服务的前提。"},{"id":"t0172","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"外部委託やクラウドサービスの利用時における情報セキュリティ","termZh":"外包及使用云服务时的信息安全","english":"Outsourcing and Cloud Services Security","reading":"がいぶいたくやくらうどさーびすのりようじにおけるじょうほうせきゅりてぃ","breadcrumb":"","explanationJa":"外部のサービスを利用する際に、情報やデータを安全に管理するための対策を指す。企業が外部の会社に業務を委託したり、クラウド上でデータを保存したりすることで、効率的な運営が可能となるが、それに伴いデータ流出や不正アクセスのリスクが増大する。従って、契約段階でセキュリティに関する条件を盛り込み、サービスプロバイダーの信頼性を確認することが重要である。また、暗号化技術やアクセス管理を導入し、定期的なセキュリティ監査を行うことで、リスクを最小限に抑えることが求められる。これにより、外部委託の利点を享受しながら、情報の安全性を確保できるようになる。","explanationZh":"指组织在委托第三方处理业务或使用云服务时，对数据、系统和供应商风险实施管理。应在采购和合同阶段明确安全要求、责任、审计权、事件通报和数据返还/销毁等条款，并对供应商安全能力进行评估。使用过程中还需实施身份与访问管理、加密、持续监控和定期审查，以降低外部依赖带来的风险。"},{"id":"t0173","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"サイバーハイジーン","termZh":"网络卫生／网络安全基本卫生（Cyber Hygiene）","english":"Cyber Hygiene","reading":"","breadcrumb":"","explanationJa":"情報セキュリティを維持するための基本的な習慣や手法を指す概念である。これは、個人や組織がデジタル環境で安全に生活や業務を行うために行う日常的な対策を含む。具体的には、パスワードの管理、ソフトウェアの定期的な更新、フィッシングメールへの注意、アンチウイルスソフトの使用などがある。サイバーハイジーンを実践することで、不正アクセスやデータの漏洩を防ぎ、オンラインの安全性を高めることができるため、特に企業においては重要な取り組みとされる。これは、サイバー攻撃からの防御を強化し、信頼できるデジタル環境を構築するために欠かせない要素である。","explanationZh":"指个人和组织日常持续执行的一组基础安全习惯，例如使用独特强密码和 MFA、及时更新软件、备份数据、识别钓鱼邮件、运行终端防护和移除不必要服务等。良好的 Cyber Hygiene 能减少常见攻击面，是比单次安全项目更强调“持续习惯”的基础防护理念。"},{"id":"t0174","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報資産の調査","termZh":"信息资产盘点","english":"Information Asset Inventory","reading":"じょうほうしさんのちょうさ","breadcrumb":"","explanationJa":"企業や組織が保有する情報資産を把握し、その価値やリスクを評価するプロセスである。この調査により、どの情報がどれだけ重要で、どのように管理されているかを明らかにすることができる。例えば、顧客データや内部文書、知的財産などが情報資産として考えられ、それぞれの資産の機密性や重要性に応じた対策を講じることが求められる。また、情報資産の調査を通じて、リスクを識別し、適切なセキュリティ対策を強化することにより、情報漏洩やサイバー攻撃への備えを強化することが可能となる。","explanationZh":"指系统识别和登记组织所拥有、处理或依赖的信息资产，并记录其所有者、位置、用途、敏感性和重要程度的过程。盘点能帮助组织发现未知资产、明确保护优先级，并为风险评估、访问控制、生命周期管理和合规工作提供基础。"},{"id":"t0175","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報資産の重要性による分類と管理","termZh":"按重要性对信息资产分类与管理","english":"Classification and Management of Information Assets by Importance","reading":"じょうほうしさんのじゅうようせいによるぶんるいとかんり","breadcrumb":"","explanationJa":"企業や組織が保有する情報資産を、その価値やリスクに基づいて評価し、適切に分類するプロセスを指す。このプロセスは、情報の流出や紛失を防ぐために不可欠であり、重要な情報を特定することで、必要なセキュリティ対策を講じることが可能となる。たとえば、機密情報、個人情報、公開情報などのカテゴリに分けることで、各情報資産に対する保護レベルを明確にする。また、情報資産の重要性に応じて管理手法を変えることで、リスクを最小化し、業務の継続性を確保することができる。このように、適切な分類と管理は、情報セキュリティの強化と組織全体の信頼性向上に寄与する。","explanationZh":"指根据资产的业务价值、敏感性、法律要求和泄露/破坏后的影响，对信息进行分类分级，并为不同级别规定相应的处理、存储、共享、访问和销毁规则。例如可区分公开、内部、机密和高度机密信息，使安全控制与实际风险相匹配。"},{"id":"t0176","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報資産台帳","termZh":"信息资产台账","english":"Information Asset Ledger","reading":"じょうほうしさんだいちょう","breadcrumb":"","explanationJa":"組織が所有する情報資産を一覧化し、その重要性や管理状態を把握するための記録簿である。この台帳には、データやシステム、ソフトウェア、ハードウェアといった様々な情報資産が含まれ、それぞれの資産に対するアクセス権や利用状況、セキュリティ対策が記載されることが一般的である。たとえば、顧客データベースや開発中のソフトウェアの情報を管理している場合、それらの重要性によって分類し、適切な保護措置を講じることが求められる。資産管理やリスク評価、コンプライアンスの監視において重要な役割を果たし、組織の情報セキュリティを向上させるための基盤として機能する。","explanationZh":"用于集中记录信息资产及其管理属性的清单或登记簿，通常包含资产名称、类型、所有者、保管位置、重要性、分类级别、访问权限、使用状态和安全控制等信息。资产台账是开展风险评估、配置管理、合规审查和资产生命周期管理的重要基础。"},{"id":"t0177","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"財産損失","termZh":"财产损失","english":"Asset Loss","reading":"ざいさんそんしつ","breadcrumb":"","explanationJa":"物理的な資産や財務的な資産が減少することを指す。具体的には、機器の破損や盗難、経済的な損失が含まれ、企業や個人の財務状況に直接的な影響を及ぼす可能性がある。例えば、火事によって工場が焼失した場合、その工場にある機械や在庫が損失となり、企業は復旧に多額の費用を要することになる。また、財産損失は保険によって一部カバーされることがあり、適切なリスク管理を行うことが重要である。リスクの種類としては、予測不可能な偶然によるものや、管理不行き届きによるものなどがあり、事前に対策を講じることが望まれる。","explanationZh":"指实物资产或财务资产因损坏、毁损、盗窃等原因造成的经济价值减少。例如火灾导致设备和库存损毁，会产生资产重置和业务恢复费用。此类风险可通过物理保护、预防性维护、保险和业务连续性措施进行管理。"},{"id":"t0178","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"責任損失","termZh":"责任损失","english":"Liability Loss","reading":"せきにんそんしつ","breadcrumb":"","explanationJa":"企業や個人が起こした損害に対する法的責任に起因する損失を指す。具体的には、他者に対して何らかの損害を与えた場合、その賠償金や訴訟費用、及びその結果としての収入の減少などが含まれる。例えば、製品の欠陥によって顧客がけがをした場合、企業はその損害を補償する責任を負うことになる。このような責任を軽減するためには、保険を利用したり、リスク管理策を講じたりすることが重要である。ビジネスにとって深刻な影響を及ぼす可能性があるため、事前に対策を立てることが求められる。","explanationZh":"指个人或组织因对第三方造成损害而承担法律责任所产生的经济损失，包括赔偿、诉讼费、律师费、和解费用以及由此引发的收入损失等。例如缺陷产品导致客户受伤时，企业可能承担赔偿责任。风险管理和责任保险可用于减轻相关财务影响。"},{"id":"t0179","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"純収益の喪失","termZh":"纯收益损失／预期利润损失","english":"Loss of Pure Profit","reading":"じゅんしゅうえきのそうしつ","breadcrumb":"","explanationJa":"企業が予想していた利益を失うリスクの一つである。これは、製品の売上が減少したり、市場の需要が変動したりすることで、計画的な利益が得られなくなる状況を指す。たとえば、新製品の開発に大きなコストをかけたにもかかわらず、期待した売上が得られなかった場合、純収益の喪失が生じる。このリスクは、経済の不況や競争の激化など、外的要因によっても影響を受けることが多い。企業はこのリスクを管理するために、市場調査や価格戦略の見直し、リスクヘッジ手段の導入などを行う必要がある。これにより、潜在的な損失を最小限に抑えることが可能となる。","explanationZh":"指由于销售下降、市场变化、业务中断或其他原因，使组织未能获得原本预期的利润。此类损失并不一定伴随实物资产损坏，但会影响经营成果。组织可通过市场分析、成本与价格策略、业务连续性和适当的风险转移措施降低影响。"},{"id":"t0180","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"人的損失","termZh":"人员损失","english":"Human Loss","reading":"じんてきそんしつ","breadcrumb":"","explanationJa":"組織やプロジェクトにおいて発生する人間に関連する損失のことである。具体的には、従業員の死亡や病気、事故による離脱など、労働力の喪失を指す。例えば、工事現場での事故によって作業員が重傷を負った場合、その瞬間に必要だった人手が失われ、業務の進行が妨げられる可能性がある。また、優れた技術や経験を持つ従業員が退職することも人的損失であり、企業にとっては知識や技術の流出という大きなリスクともなる。このような企業の生産性や利益に直接的な影響を与え、長期的な戦略においても重要な要素とされる。適切なリスク管理や安全対策が求められるのはそのためである。","explanationZh":"指由于死亡、疾病、事故、离职或关键人员流失等造成的劳动力、经验和知识损失。除直接影响业务执行外，核心人员离职还可能造成专业知识和隐性经验流失。组织应通过安全健康管理、接班人计划、知识管理和人员冗余降低这种风险。"},{"id":"t0181","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"オペレーショナルリスク","termZh":"操作风险（Operational Risk）","english":"Operational Risk","reading":"","breadcrumb":"","explanationJa":"企業が日常的な業務を行う中で発生するリスクの一つである。このリスクは、内部のプロセス、従業員の行動、システムの故障、あるいは外部からの影響によって引き起こされる可能性がある。例えば、ITシステムのダウンや従業員のミス、誤った手続きが原因で、業務が滞ることが考えられる。経済的損失を直接的に引き起こすだけでなく、企業の信頼性にも影響を及ぼすため、適切な管理が重要である。このリスクを理解し対策を講じることで、企業は業務の安定性を高めることができる。","explanationZh":"指由于内部流程不完善、人员失误、系统故障或外部事件等导致损失的风险。例如 IT 系统宕机、错误操作、流程执行不当或外部灾害都可能造成业务中断。有效管理需要完善流程、职责分离、培训、系统韧性和持续监控。"},{"id":"t0182","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"サプライチェーンリスク","termZh":"供应链风险","english":"Supply Chain Risk","reading":"","breadcrumb":"","explanationJa":"製品やサービスの供給過程において発生する潜在的な問題や脅威のことである。これは、原材料の調達から製品の販売までの一連の過程に関わるすべてのリスクを含む。例えば、自然災害や供給業者の破産、政治的な不安定さなどがサプライチェーンリスクとなる。これらのリスクが現実化すると、商品の供給が滞り、企業の業績に大きな影響を及ぼすことがある。そのため、企業はリスクを分析し、対策を講じることが重要であり、バランスの取れたサプライチェーンの構築を目指すことが求められる。","explanationZh":"指从原材料、零部件、软件、服务供应商到物流和销售等供应链环节中，可能影响产品、服务、信息安全或业务连续性的风险。来源包括供应商破产、自然灾害、地缘政治、恶意植入、第三方漏洞等。组织应评估关键依赖、实施供应商管理并建立替代和恢复方案。"},{"id":"t0183","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"外部サービス利用のリスク","termZh":"使用外部服务的风险","english":"External Service Utilization Risk","reading":"がいぶさーびすりようのりすく","breadcrumb":"","explanationJa":"他の企業やサービスから提供される機能やデータを自社のシステムで利用する際に生じる潜在的な危険性である。このリスクには、セキュリティの脆弱性やデータの漏洩、サービスの停止、そして信頼性の低下などが含まれる。例えば、オンラインストレージサービスを利用する場合、保存したデータが不正アクセスを受けたり、サービス自体が突然停止したりする可能性がある。このため、自社の業務やデータに大きな影響を与えることが考えられる。外部サービスを利用する際には、リスクを評価し、適切なセキュリティ対策や契約条件を確認することが重要である。これにより、外部サービスの利点を享受しつつ、リスクを最小限に抑えることができる。","explanationZh":"指依赖第三方服务、平台或数据所带来的安全、可用性、合规和持续经营风险，例如供应商漏洞、数据泄露、服务中断、锁定效应或服务商停止运营。使用前应进行风险和合同评估，使用中应持续监控，并为关键服务准备退出、备份和替代方案。"},{"id":"t0184","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"SNSによる情報発信のリスク","termZh":"通过 SNS 发布信息的风险","english":"Risks of Information Dissemination via SNS","reading":"えすえぬえすによるじょうほうはっしんのりすく","breadcrumb":"","explanationJa":"ソーシャルネットワーキングサービスを通じて情報を発信する際に生じる危険性のことである。SNSでは、個人や企業が簡単に情報を発信できる一方で、不正確な情報の拡散やプライバシーの侵害が発生しやすい。例えば、誤解を招く内容が投稿されると、それが瞬時に広まり、信頼性を損ねる可能性がある。また、個人情報が漏洩するリスクもあり、悪意のある第三者に利用される恐れがある。これらのリスクは、特に信頼性が求められる場面において、十分な注意が必要となるため、SNSを利用する際には情報管理や発信内容の慎重な確認が求められる。","explanationZh":"指个人或组织在社交媒体发布内容时面临的隐私泄露、错误信息扩散、声誉损害、账号接管和社会工程等风险。SNS 内容传播速度快且难以彻底撤回，因此在发布前应确认信息真实性、敏感性和授权范围，并对官方账号实施强认证和发布审批。"},{"id":"t0185","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"地政学的リスク","termZh":"地缘政治风险","english":"Geopolitical Risk","reading":"ちせいがくてきりすく","breadcrumb":"","explanationJa":"国や地域の政治的な状況が経済やビジネスに及ぼす影響を指すものである。具体的には、国家間の緊張や紛争、政治制度の変化、貿易制限などが、企業の運営や市場の安定性に影響を与える可能性がある。例えば、ある国で政権が変わった場合、外国企業の投資環境が不安定になることがあり、このような状況が地政学的リスクとされる。企業はこれらのリスクを評価し、適切に対策を講じることが重要であり、国際市場での競争力を維持するためにもこの理解は欠かせない。グローバル経済において特に重要な要因となっている。","explanationZh":"指国家间关系、战争冲突、制裁、政策变化、贸易限制和政治不稳定等因素对企业经营、供应链、投资和信息安全造成影响的风险。跨国组织应评估业务和供应商的地区暴露度，并准备替代供应、数据和运营方案。"},{"id":"t0186","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"モラルハザード","termZh":"道德风险（Moral Hazard）","english":"Moral Hazard","reading":"","breadcrumb":"","explanationJa":"リスクを負う側がそのリスクを軽視した行動を取ることを指す。具体的には、保険や契約の存在によって、当人が本来の行動基準を緩めたり、過度なリスクをとったりすることがある。例えば、自動車保険に加入している人が、保険が効くと安心して運転中に注意を怠った場合、事故を起こす可能性が高まることがある。このように、リスクの分配が不均等になることで、社会的にも経済的にも問題を引き起こす要因となる。企業や組織においては、リスク管理や内部統制の重要性が増し、モラルハザードを防ぐための適切な対策が求められる。","explanationZh":"指由于风险损失由他人部分或全部承担，使行为人降低谨慎程度或采取更高风险行为的现象。例如拥有充分保险后可能减少预防投入。组织可通过合理的责任分担、内部控制、激励约束和监督机制，减少因风险承担不对称而产生的不当行为。"},{"id":"t0187","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"年間予想損失額","termZh":"年度预期损失（Annual Expected Loss）","english":"Annual Expected Loss","reading":"ねんかんよそうそんしつがく","breadcrumb":"","explanationJa":"特定のリスクが発生した場合に、1年間において予想される金銭的な損失の額である。この指標は、企業や団体がリスク管理を行う際に重要な要素となる。たとえば、自然災害や事故による損失、システム障害など、様々なリスクの影響を定量的に評価するために使用される。過去のデータや統計を基に計算されることが一般的であり、これにより企業は予想される損失に対する対策を講じたり、保険を選択したりする際の参考となる。リスクの把握が進むことで、企業は戦略的な計画を立て、持続可能な運営を行うための基盤を整えることができる。","explanationZh":"指某类风险在一年内预期造成的平均经济损失，可用于比较风险和判断安全投资。在常见量化方法中，可根据单次损失金额与年度发生频率/概率估算年度预期值。该指标有助于进行风险优先级排序、预算规划和保险决策。"},{"id":"t0188","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"得点法","termZh":"评分法","english":"Scoring Method","reading":"とくてんほう","breadcrumb":"","explanationJa":"リスク評価においてリスクを数値化する手法である。この方法では、リスクの発生確率と影響度を数値で表し、それらの得点を組み合わせることで、リスクの総合評価を行う。たとえば、あるプロジェクトでのリスクの発生確率を「低」「中」「高」に分類し、各カテゴリに得点を設定することで、リスクが実現した場合の影響度も同様に評価できる。このように得点化することで、複数のリスクを比較しやすくなり、優先順位を決めやすくなる。また、定量的なデータが得られるため、客観的な判断が可能になり、リスクマネジメントの向上に寄与する。","explanationZh":"一种把风险因素按照预先定义的等级或分值进行评分，并综合形成风险等级的方法。常将发生可能性和影响程度分别按“低、中、高”或数字评分，再组合得到总体分值。它便于比较多个风险和确定优先级，属于常见的定性或半定量评估方法。"},{"id":"t0189","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"コスト要因","termZh":"成本因素","english":"Cost Factor","reading":"こすとよういん","breadcrumb":"","explanationJa":"プロジェクトやビジネス活動における費用の発生に影響を与える要素のことである。この要因は、財務計画や予算管理において特に重要であり、予算超過やコスト削減計画の策定に役立つ。具体的には、原材料費、人件費、設備費、運営コストなどがコスト要因に該当する。例えば、新商品の開発において、必要な部品の価格や製造過程にかかる労働力のコストは、全体の費用に大きく影響を及ぼす。また、コスト要因の分析を通じて、プロジェクトの実行可能性やリスクを評価し、経営判断を行うための重要な資料を提供する。これにより、より効果的な予算管理が実現する。","explanationZh":"指影响项目或业务活动成本水平的要素，例如原材料、人工、设备、许可、运营和维护费用等。分析成本因素有助于预算编制、可行性评估和成本控制，也可用于比较不同风险应对方案的投入与预期收益。"},{"id":"t0190","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスク基準","termZh":"风险准则（Risk Criteria）","english":"Risk Criteria","reading":"りすくきじゅん","breadcrumb":"","explanationJa":"情報セキュリティリスクアセスメントを実施する際の評価基準である。特定のリスクが受け入れ可能かどうかを判断するための指針を提供する。具体的には、組織が許容できるリスクのレベルを定義し、その基準に基づいてリスクを評価・管理する。たとえば、ある企業ではデータ漏洩のリスクが高いと判断されても、システムの重要性や業務への影響を考慮し、一定のリスクを受け入れることがある。そのため、リスクマネジメントのプロセスにおいて重要な役割を果たし、組織が資源を最適に配分できるようサポートする。リスク基準を明確にすることで、効果的な対策を講じ、潜在的な脅威に対抗するための準備が整うのである。","explanationZh":"指组织用于评价风险重要性和可接受性的标准，包括风险容忍度、影响等级、可能性尺度、法律要求和业务目标等。风险准则应在风险评估前明确，以便不同风险能够采用一致标准评价，并决定哪些风险需要进一步处置、哪些可以接受。"},{"id":"t0191","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスクレベル","termZh":"风险等级","english":"Risk Level","reading":"","breadcrumb":"","explanationJa":"特定の脅威や脆弱性がもたらす潜在的な影響の度合いを評価するための指標である。情報セキュリティにおいては、重要なデータやシステムがどれだけ危険にさらされているかを判断する際に使用される。例えば、機密情報を扱うシステムがハッキングされるリスクが高い場合、そのリスクレベルは「高」と評価される。また、リスクレベルは通常、影響の重大性と発生する可能性を組み合わせて評価されるため、具体的には「高」「中」「低」といったカテゴリで表現される。この評価に基づいて、適切なセキュリティ対策を講じることが重要であり、リスクレベルの理解はセキュリティ戦略の策定に欠かせない要素となる。","explanationZh":"指根据风险的发生可能性和后果/影响程度综合得到的风险严重程度，常以“高、中、低”或数值等级表示。风险等级用于确定处置优先级和资源投入，但具体分级阈值应由组织依据风险准则制定。"},{"id":"t0192","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスクマトリックス","termZh":"风险矩阵","english":"Risk Matrix","reading":"","breadcrumb":"","explanationJa":"リスクを評価するための視覚的なツールであり、リスクの発生確率と影響度を視覚的に示す枠組みである。このマトリックスは、行と列で構成され、通常、行はリスクの発生確率、列はその影響度を表す。たとえば、発生確率が「低」「中」「高」、影響度が「小」「中」「大」となる場合、どのようなリスクがどの程度の影響を及ぼすかを簡単に把握できる。リスクマトリックスを使用することで、組織はより重要なリスクを特定し、対策を優先的に行うことができる。これにより、情報セキュリティの向上につながり、リスク管理プロセスが効率的になる。","explanationZh":"一种将“发生可能性”和“影响程度”两个维度交叉展示的风险评价工具。通过把风险落在矩阵对应单元格中，可直观区分高、中、低等优先级并支持风险沟通。风险矩阵简单易用，但评分尺度和边界具有主观性，应结合专业判断使用。"},{"id":"t0193","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスク所有者","termZh":"风险所有者（Risk Owner）","english":"Risk Owner","reading":"りすくしょゆうしゃ","breadcrumb":"","explanationJa":"特定のリスクに対して責任を持つ個人または組織のことを指す。そのリスクが発生した場合の影響を理解し、適切な管理策を講じる役割を担う。例えば、企業内でのデータ漏洩リスクに対しては、情報システム部門の責任者がリスク所有者となり、その防止策や対策を実施する責任を持つ。このように自分の担当する範囲内でリスクを把握し、適切な対処を行うことで、組織全体の安全性を高める重要な位置付けにいる。ただし、リスク所有者の責任には限界があるため、他の関係者と緊密に連携しながらリスク管理を行う必要がある。","explanationZh":"指被赋予权限并对某一特定风险的管理承担责任的个人或岗位。风险所有者需要理解风险、批准或推动处置方案、监控残余风险并向相关管理层报告。风险所有者不一定亲自实施所有控制措施，但应确保风险被适当管理。"},{"id":"t0194","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスク源","termZh":"风险源","english":"Risk Source","reading":"りすくげん","breadcrumb":"","explanationJa":"情報セキュリティにおける脅威や危険が発生する原因を指す。具体的には、悪意のある攻撃者、技術的な脆弱性、人的なミス、自然災害などがリスク源として挙げられる。例えば、サイバー攻撃を仕掛けるハッカーは、特定のシステムに対して不正アクセスを試みるリスク源となる。また、古いソフトウェアが持つ未修正のバグや脆弱性も、情報漏洩やシステムダウンのリスクを引き起こす可能性がある。リスク源を特定し評価することは、情報セキュリティリスクアセスメントの重要なプロセスであり、組織が適切な対策を講じるための第一歩となる。これにより、リスクを最小限に抑え、安全な情報環境を維持することが求められる。","explanationZh":"指单独或与其他因素共同具有产生风险潜力的因素或来源，例如攻击者、技术脆弱性、人员失误、供应商问题或自然灾害等。识别风险源是风险识别的重要环节，有助于进一步分析其可能触发的事件、影响资产和后果。"},{"id":"t0195","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスクアセスメントのプロセス","termZh":"风险评估过程","english":"Risk Assessment Process","reading":"","breadcrumb":"","explanationJa":"情報セキュリティにおけるリスクを特定し、分析し、評価する一連の手順を指す。このプロセスは、組織が直面する潜在的な脅威や脆弱性を明らかにし、それによってどの程度の影響を受けるかを判断するために行われる。まず、リスク特定の段階では、情報資産に対するリスクを明確にし、どのようなリスクが存在するのかを洗い出す。その後、リスク分析に進み、特定されたリスクの発生確率や影響度を定量的または定性的に評価する。最後に、リスク評価により、リスクの重要度や受容可能性を決定し、対策を講じるかどうかを判断する。この一連のプロセスは、情報セキュリティの強化やリスク管理のために不可欠である。","explanationZh":"指识别、分析和评价风险的一系列步骤。首先识别资产、事件、威胁和脆弱性等风险要素；随后分析发生可能性和影响；最后依据风险准则判断风险是否可接受并确定优先级。风险评估结果为选择风险处置措施和资源配置提供依据。"},{"id":"t0196","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスク忌避","termZh":"风险规避","english":"Risk Avoidance","reading":"りすくきひ","breadcrumb":"","explanationJa":"特定のリスクを回避するために行動や選択を変えることを指す。これは、情報セキュリティのリスクアセスメントにおいて重要な手法であり、潜在的な危険が生じる状況を避けることで、組織や個人の安全を確保することが目的である。例えば、特定の危険なソフトウェアの使用を控えることで、システムへの侵入リスクを減少させることができる。また、リスク評価の結果を基に計画的な対策を講じることで、事前に問題を防ぐ手段として非常に有効であり、組織の情報資産を守るための基本的な戦略の一つである。","explanationZh":"指通过停止、取消或改变会导致风险的活动，从源头上避免该风险。例如不使用无法满足安全要求的软件，或不保存没有业务必要的高敏感数据。风险规避与“降低风险”不同：前者消除导致该风险的活动，后者是在继续活动的同时降低概率或影响。"},{"id":"t0197","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスク選好","termZh":"风险偏好（Risk Appetite/Preference）","english":"Risk Preference","reading":"りすくせんこう","breadcrumb":"","explanationJa":"個人や組織がリスクを受け入れる度合いを表す概念である。具体的には、ある選択肢がもたらす利益に対して、どれだけのリスクを許容できるかを示すものである。例えば、高いリターンを望む投資家はリスク選好が高いとされ、逆に安定性を重視する人はリスク選好が低いと見なされる。この考え方は、情報セキュリティリスクアセスメントにおいても重要で、組織がセキュリティ対策を講じる際に、どの程度のリスクを受け入れるかを決定するための指針となる。リスク選好を理解することで、より適切なリスク管理が可能になる。","explanationZh":"指个人或组织为了实现目标愿意承担的风险类型和总体程度。风险偏好较高时，可能接受更大的不确定性以获取更高收益；较低时则更强调稳定和保护。信息安全治理需要使具体风险容忍度和安全投入与组织整体风险偏好保持一致。"},{"id":"t0198","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスクの定性的分析","termZh":"定性风险分析","english":"Qualitative Risk Analysis","reading":"りすくのていせいてきぶんせき","breadcrumb":"","explanationJa":"情報セキュリティリスクに関する評価手法の一つである。この分析は、リスクを数値やデータに基づいて定量的に評価するのではなく、事故や脅威が発生した際の影響や可能性を主観的な判断で評価することに重点を置く。たとえば、ある脅威が発生する可能性が高いとされる場合、そのリスクの影響度を高、中、低などのカテゴリに分けて評価することが一般的である。この手法は、理解しやすく迅速な判断が可能なため、企業や組織が初期段階のリスク評価を行う際に非常に効果的である。また、定性的分析は、リスクを可視化し、経営層や関係者とのコミュニケーションを円滑にするためにも役立つ。","explanationZh":"指使用描述性等级和专业判断评价风险发生可能性与影响的方法，例如将风险评为高、中、低。其优点是快速、易理解，适合数据不足或初步筛选阶段，也便于管理层沟通；缺点是主观性较强，因此需要明确一致的评分标准。"},{"id":"t0199","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスクの定量的分析","termZh":"定量风险分析","english":"Quantitative Risk Analysis","reading":"りすくのていりょうてきぶんせき","breadcrumb":"","explanationJa":"情報セキュリティにおけるリスクを数値で表現し、評価する手法である。この手法では、リスクの発生確率や影響度を定量的に計算し、具体的な数値を用いてリスクを分析する。例えば、特定の攻撃が年間に5%の確率で発生し、その結果によって企業が50万円の損失を被ると仮定した場合、リスクの年間期待値は2万5千円となる。このように、数値を用いることでリスクの優先順位を明確にし、経営戦略や資源の配分に役立てることができる。また、定量的分析は、リスク軽減策の効果を評価する際にも利用されるため、企業にとって非常に重要な手法である。","explanationZh":"指使用概率、金额、频率等数值对风险进行计算和评价的方法。例如某攻击每年发生概率为 5%，单次损失为 50 万日元，则简单期望损失为 2.5 万日元/年。定量分析便于成本效益比较和资源配置，但需要相对可靠的数据和模型假设。"},{"id":"t0200","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスクコントロール","termZh":"风险控制","english":"Risk Control","reading":"","breadcrumb":"","explanationJa":"情報セキュリティにおけるリスクを管理し、安全な環境を維持するための手法である。具体的には、特定のリスクを評価し、そのリスクが引き起こす可能性や影響度を考慮した上で、リスクを軽減するための対策を講じることを指す。例えば、企業がデータ漏洩のリスクを評価した場合、パスワード管理の強化やアクセス制御の導入などの方法を採用することで、そのリスクを低減させることができる。さらに、リスクのモニタリングや定期的な見直しを行うことも含まれ、状況に応じた柔軟な対応を可能にする。このように、リスクコントロールは情報セキュリティの重要な要素であり、企業や組織が安全性を確保するために不可欠である。","explanationZh":"指通过技术、管理或物理控制措施，降低风险发生的可能性或后果，并持续监控控制效果的过程。例如加强身份认证、实施访问控制、加密和补丁管理等。风险控制需要根据风险变化和控制有效性定期复核和调整。"},{"id":"t0201","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスクヘッジ","termZh":"风险对冲／风险缓释","english":"Risk Hedge","reading":"","breadcrumb":"","explanationJa":"不測の事態やリスクに対して備えを行う手法である。特に情報セキュリティの分野においては、システムやデータに対する脅威を軽減するための戦略を指す。具体的には、リスクを特定し、その影響を分析した上で、適切な対策を講じることで、潜在的な損失を最小限に抑えることを目的としている。例えば、大事なデータをバックアップすることや、セキュリティソフトを導入してサイバー攻撃から守ることがリスクヘッジに当たる。また、リスクヘッジは予算や資源の配分にも関係しており、適切な投資を行うことで、企業全体の情報セキュリティを強化することが可能である。このように安全な運営を実現するために欠かせない重要な要素である。","explanationZh":"广义上指通过采取备份、冗余、安全控制、分散依赖或其他措施，降低不确定事件造成的损失。信息安全中更常使用“风险降低/风险缓释（risk mitigation）”描述通过控制措施降低风险，而“hedge”在财务领域更常指利用相反头寸等方式对冲市场风险。"},{"id":"t0202","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスクファイナンシング","termZh":"风险融资","english":"Risk Financing","reading":"","breadcrumb":"","explanationJa":"企業や組織が情報セキュリティリスクに対する財務的な対策を講じることを指す。この手法では、リスクが実際に発生した場合の影響を軽減するために、資金を準備することが重視される。具体的には、保険の購入や自己資本の準備、予備費の設定などが含まれ、リスクが現実化した際に対応できるようにする。例えば、サイバー攻撃によるデータ流出のリスクがある場合、事前に保険に加入することで、発生した損失を保険金でカバーできる。このように、組織が予測不可能な事態に備え、財務的な安定性を維持するための重要な手段である。","explanationZh":"指为风险实际发生后的经济损失预先安排资金来源的做法，例如购买保险、建立准备金或自保基金。它不直接降低事件发生概率，而是提高组织承担和恢复损失的财务能力，是风险处置中的财务安排手段。"},{"id":"t0203","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"サイバー保険","termZh":"网络保险（Cyber Insurance）","english":"Cyber Insurance","reading":"さいばーほけん","breadcrumb":"","explanationJa":"情報セキュリティに関連するリスクをカバーするための保険である。この保険は、企業がサイバー攻撃やデータ漏洩による損失を軽減するために設計されている。具体的には、サイバー攻撃が発生した際の損害賠償、法律費用、および復旧作業にかかる費用を補償する場合が多い。たとえば、データがハッキングされ、顧客情報が流出した場合には、法律的な対応や顧客への通知に要する経費が発生する。このようなリスクに対してサイバー保険に加入することで、企業は経済的な負担を軽減し、より安心してビジネスを行うことができる。さらに、保険会社はリスク評価を通じて、企業に対しセキュリティ対策の改善を提案することもある。","explanationZh":"用于覆盖特定网络安全事件造成经济损失的保险产品，保障范围可能包括事件响应与取证费用、业务中断、数据恢复、第三方责任、法律费用和通知成本等。实际承保范围和除外责任因保单而异，保险不能替代安全控制，而是风险转移/融资的一部分。"},{"id":"t0204","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスク回避","termZh":"风险回避","english":"Risk Avoidance","reading":"りすくかいひ","breadcrumb":"","explanationJa":"リスクが生じる可能性のある状況を事前に回避する戦略である。具体的には、潜在的な脅威や危険を評価し、それらを回避するために行動を変更することを指す。例えば、企業がデータ漏洩のリスクを減らすために、特定のデータを保存しない決定をすることが挙げられる。情報セキュリティ分野において非常に重要であり、脆弱性を特定し、それに対する対策を講じることで、安全な環境を構築する。この方法は、リスクが発生する前にその原因を取り除くことを目的とし、潜在的な損失を防ぐための効果的な手段となる。","explanationZh":"指通过不开展、终止或改变某项活动，避免暴露于相应风险。例如为了避免敏感数据泄露，决定不收集或不保存没有必要的数据。它属于风险处置方式之一，适用于风险明显超过组织可接受水平且无法经济有效降低的情况。"},{"id":"t0205","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスク共有","termZh":"风险共享","english":"Risk Sharing","reading":"りすくきょうゆう","breadcrumb":"","explanationJa":"リスクを複数の関係者やシステムで分け合う仕組みを指す。情報セキュリティにおいては、企業や組織がリスクを一方的に負うのではなく、他者と協力してリスク管理を行うことが重要である。例えば、保険を通じてリスクを移転することや、異なるプロジェクトに投資を分散させることでリスクを減少させるリスク分散がある。これにより、万が一の事態が発生した際の影響を軽減し、より安定した運営を実現することができる。特に、情報漏えいやサイバー攻撃のリスクが高まる現代において、リスク共有は効果的な対策の一つとされている。","explanationZh":"指通过合同、合作、保险或其他安排，使风险后果或责任由多个主体共同承担或转移一部分给第三方。例如购买保险可以将部分经济损失转移给保险机构。风险共享并不会消除风险，组织仍需要明确自身保留的责任和残余风险。"},{"id":"t0206","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスク保有","termZh":"风险保留／风险接受","english":"Risk Retention","reading":"りすくほゆう","breadcrumb":"","explanationJa":"特定のリスクを管理するために、そのリスクを受容して自社の資源でリスクの影響を負担する戦略を指す。これは、リスクに対する対策を講じずに、その影響を自身で受け入れることを意味する。たとえば、企業がサイバー攻撃のリスクを認識しつつも、コストやリソースの観点から特別なセキュリティ対策を行わない場合、リスクを自社で保有することになる。この戦略は、リスクの発生確率が低いと判断した場合や、発生した際の影響が軽微であると考えられる場合に選択されることが多い。ただし、リスク保有には、リスクが現実化した場合に備える準備が重要であり、適切な管理が求められる。","explanationZh":"指组织在了解风险水平后，决定自行承担风险及其可能损失。通常适用于风险低于可接受标准，或进一步降低风险的成本高于预期收益的情况。风险保留并不等于“什么都不做”，仍应记录接受决定、明确责任并准备必要的应急资金或恢复措施。"},{"id":"t0207","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスク集約","termZh":"风险聚合","english":"Risk Aggregation","reading":"りすくしゅうやく","breadcrumb":"","explanationJa":"複数のリスクを一つの枠組みでまとめて評価または管理する手法である。この手法は、情報セキュリティの分野において特に重要であり、個別のリスクを基に全体のリスク状況を把握するために使用される。例えば、企業が異なる部門やプロジェクトに潜在する複数のリスクを集約することで、全体像を把握できるようになり、リソースをどのように配分すべきかの判断材料となる。また、リスク集約を行うことで、ある部門のリスクが他の部門にどのように影響を与えるかを理解し、より効果的なリスク対応策を考えることが可能となる。このようにして、企業全体のリスク管理を効率化し、セキュリティ対策を強化することが期待される。","explanationZh":"指把多个部门、资产、业务或风险类别的单项风险汇总分析，以了解组织总体风险暴露和风险之间的相关性。聚合有助于发现单独看似较小、但累积后可能显著的风险，并支持管理层进行资源分配和整体风险决策。"},{"id":"t0208","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"残留リスク","termZh":"剩余风险（Residual Risk）","english":"Residual Risk","reading":"ざんりゅうりすく","breadcrumb":"","explanationJa":"情報セキュリティ対策を講じた後も残るリスクのことである。具体的には、対策によって一定程度リスクは低減されるが、完全にゼロにはできないことを意味する。例えば、ウイルス対策ソフトウェアを導入したとしても、新たな脅威が出現したり、ソフトウェアの更新を怠ったりすることで、発生し得るリスクが残る。この企業が防御策を実装した後に評価され、必要に応じて追加の対策を講じたり、リスクを受け入れたりする判断材料となる。また、リスクマネジメントにおいては、この残留リスクの管理が重要であり、それによって組織全体のセキュリティが強化される。","explanationZh":"指实施风险处置和安全控制后仍然存在的风险。任何控制都可能存在失效、绕过或新威胁，因此风险通常无法完全降为零。组织应重新评估剩余风险，并根据风险准则决定继续降低、转移或正式接受。"},{"id":"t0209","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスク対応計画","termZh":"风险应对计划","english":"Risk Response Plan","reading":"りすくたいおうけいかく","breadcrumb":"","explanationJa":"特定されたリスクに対してどのように対応するかを明確に示した文書である。この計画は、リスクが発生した場合の影響を最小限に抑えるための戦略や具体的な行動を定義するものである。具体的には、リスクを回避する、軽減する、受容する、または転換するなどの方法が含まれる。例えば、サイバー攻撃のリスクに対しては、セキュリティソフトの導入や定期的なシステム更新を行うことで軽減策を講じることが考えられる。さらに、企業や組織が適切に準備を行い、可能な限り迅速にリスクに対処できる体制を整えるために不可欠な要素であり、リスク管理の一環として重要である。","explanationZh":"指针对已识别风险，明确所选处置策略、具体措施、责任人、资源、时间表和预期目标的计划。常见处置包括规避、降低、共享/转移和接受。计划还应规定如何监控实施进度和剩余风险，以确保措施真正落地。"},{"id":"t0210","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスク登録簿","termZh":"风险登记册（Risk Register）","english":"Risk Register","reading":"りすくとうろくぼ","breadcrumb":"","explanationJa":"情報セキュリティ管理において、識別されたリスクを記録し、管理するための文書である。この文書には、リスクの特定、評価、対応策、責任者といった情報が整理されており、リスクマネジメントのプロセスで重要な役割を果たす。たとえば、ネットワークの脆弱性やデータ漏洩の可能性など、さまざまなリスクを列挙し、それぞれのリスクに対して優先順位を付けることで、取るべき対策を明確にすることができる。リスクの状況を可視化し、関係者が共通の理解を持つための基盤として機能するため、組織全体での情報セキュリティ対策を強化することに繋がる。","explanationZh":"用于集中记录和跟踪已识别风险的管理文档或系统。通常包含风险描述、来源、影响资产、可能性、影响、风险等级、控制措施、风险所有者、处置计划、剩余风险和状态等。它是风险沟通、责任落实和持续跟踪的重要基础。"},{"id":"t0211","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リスクコミュニケーション","termZh":"风险沟通","english":"Risk Communication","reading":"","breadcrumb":"","explanationJa":"情報セキュリティ分野において、リスクに関する情報を関係者間で効果的に伝達するプロセスを指す。このコミュニケーションは、リスクの認識を共有し、適切な対策を講じるために重要である。例えば、企業がサイバー攻撃の可能性について従業員に通知する際、明確で具体的な情報を提供することで、従業員は自分の行動を見直し、安全対策を講じることができる。さらに、リスクについての信頼性の高い情報を提供することで、誤解や混乱を避け、組織全体のセキュリティ意識を高めることにも寄与する。単に情報を伝えるだけでなく、相互理解を深め、適切な行動を促す手段でもある。","explanationZh":"指风险信息在决策者、业务部门、技术人员、员工、供应商等相关方之间进行双向交流的过程。其目的不仅是“通知”，还包括形成共同理解、解释不确定性、收集反馈并推动适当行动。清晰、可信和及时的风险沟通能够减少误解并提升安全意识。"},{"id":"t0212","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"緊急事態の区分","termZh":"紧急状态分级","english":"Classification of Emergency Situations","reading":"きんきゅうじたいのくぶん","breadcrumb":"","explanationJa":"情報セキュリティにおいて、異常事態や脅威が発生した際に、その深刻度や影響を分析し、適切に対応するための分類方法である。これにより、組織は迅速に状況を把握し、適切な対策を講じることが可能になる。例えば、情報漏洩やシステムダウンなど、緊急度によって分類されることで、優先度の高い問題から解決を進めることができる。また、各区分に応じた対応マニュアルや連絡体制が事前に整備されることで、混乱を防ぎ、効果的な危機管理が行えるようになる。組織の安全確保と業務の継続性を維持する上で重要な要素である。","explanationZh":"指根据安全事件或异常情况的严重程度、影响范围、业务中断程度等对紧急状态进行分类，以确定响应优先级、升级路径和资源投入。组织应预先定义各等级的判断标准、通知对象和处置流程，以便事件发生时快速统一行动。"},{"id":"t0213","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"緊急時対応計画","termZh":"应急计划（Contingency Plan）","english":"Contingency Plan","reading":"きんきゅうじたいおうけいかく","breadcrumb":"","explanationJa":"予期せぬ事態や災害が発生した際に、組織が迅速に対応し、業務を継続するための計画を指す。この計画は、リスク評価や影響分析を基に、発生しうる危機に対する具体的な手順や役割分担を定めるものである。例えば、サーバダウンや自然災害などの事例では、データのバックアップや代替の通信手段が挙げられる。また、関係者への通知手順や情報共有の方法も含まれる。緊急時対応計画が整備されていることで、企業は被害を最小限に抑え、業務の復旧を迅速に進めることが可能となる。これは、企業の信頼性向上にも寄与する重要な要素である。","explanationZh":"指为预期外故障、灾害或其他中断情形预先制定的替代方案和响应步骤，用于保障关键业务能够继续或尽快恢复。计划通常包括角色职责、通信和通知、备份与替代设施、资源调用和恢复步骤，并应定期测试和更新。"},{"id":"t0214","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"復旧計画","termZh":"灾难恢复计划（DRP）","english":"Disaster Recovery Plan","reading":"ふっきゅうけいかく","breadcrumb":"","explanationJa":"情報システムの障害や災害が発生した際に、業務を迅速に再開するための手順や方針を定めた文書である。この計画は、システムの重要性や運用環境に応じて策定され、データのバックアップ、システムの復元方法、および関係者の役割分担が含まれる。例えば、サーバダウンや自然災害によるシステム停止時に、復旧計画に従って迅速に対応することで、業務の中断を最小限に抑えることが可能である。また、定期的に計画の見直しや訓練を行うことが重要で、これにより実際の事態においてもスムーズに対処できるようにすることが求められる。","explanationZh":"指在严重故障或灾害导致信息系统不可用时，用于恢复 IT 系统、数据和关键技术服务的具体计划。通常包含恢复优先级、备份和恢复方法、备用环境、责任分工、RTO/RPO 等目标以及测试安排，是业务连续性管理的重要组成部分。"},{"id":"t0215","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"災害復旧","termZh":"灾难恢复（Disaster Recovery）","english":"Disaster Recovery","reading":"さいがいふっきゅう","breadcrumb":"","explanationJa":"情報システムやデータが自然災害や人為的な事故によって損傷を受けた際、その復旧を目指す計画やプロセスを指す。データのバックアップやシステムの冗長化を通じて、事業の継続性を確保するために重要である。例えば、企業が地震や火災などでサーバが壊れた場合、事前に用意したバックアップからデータを復元し、システムを迅速に再稼働させることができる。また、復旧計画には、リスク評価や訓練、必要な施設や機器の準備が含まれ、実際の災害発生時にスムーズな対応が可能となる。これにより、業務の中断を最小限に抑え、顧客や関係者への影響を軽減することが目的である。","explanationZh":"指在自然灾害、重大事故、网络攻击等造成信息系统严重中断后，恢复数据、基础设施和 IT 服务的组织能力与过程。常用手段包括异地/云备份、冗余、备用站点和恢复演练，目标是在预定时间和数据损失范围内恢复关键业务支持能力。"},{"id":"t0216","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"障害復旧","termZh":"故障恢复","english":"Disaster Recovery","reading":"しょうがいふっきゅう","breadcrumb":"","explanationJa":"システムやサービスが障害により停止した際に、迅速に元の状態に戻すためのプロセスである。このプロセスは、情報システムやデータベースが影響を受けた場合に重要で、業務の継続性を確保するために欠かせない。たとえば、自然災害やサイバー攻撃によるダウンタイムを最小限に抑えるための計画や手順が含まれる。障害復旧の一環として、バックアップの作成や復元手順の策定、テストが行われ、これにより、万が一の事態に備えることができる。また、企業や組織においては、障害復旧計画が従業員と顧客の信頼を維持するための重要な要素となる。","explanationZh":"指系统或服务因硬件、软件、网络或其他故障停止后，按照预定程序恢复到可正常运行状态的过程。其范围可以比“灾难恢复”更日常和局部，通常涉及故障检测、切换、备份还原、验证和恢复服务等步骤。"},{"id":"t0217","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"バックアップによる対策","termZh":"备份措施","english":"Backup Measures","reading":"ばっくあっぷによるたいさく","breadcrumb":"","explanationJa":"データの損失や破損に備える手段を指す。データが消失した場合に備え、重要な情報やシステムのコピーを定期的に作成することで、災害やエラーによる影響を最小限に抑えることができる。例えば、企業では顧客データや業務データを定期的に外部ストレージやクラウドサービスにバックアップすることが一般的である。このような施策により、万が一データが失われた場合でも迅速に復旧が可能となり、業務の継続性を確保することができる。また、バックアップを行う際には、データの暗号化やアクセス制限を行うことで、セキュリティ面でも強化が図れる。","explanationZh":"指为防止原始数据因删除、损坏、勒索软件或灾害而丢失，定期创建并安全保存可恢复副本。有效备份应考虑备份频率、保留周期、异地/离线或不可变副本、加密和访问控制，并定期进行恢复测试；只有能够成功恢复的备份才真正有效。"},{"id":"t0218","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"被害状況の調査手法","termZh":"损害评估方法","english":"Damage Assessment Method","reading":"ひがいじょうきょうのちょうさしゅほう","breadcrumb":"","explanationJa":"情報セキュリティにおいて、サイバー攻撃やインシデントが発生した際に、その影響を評価し、どの程度の損害が生じたかを明らかにするための方法である。この手法は、被害の範囲や具体的な内容を把握し、必要な対策を立案するための重要なステップである。例えば、データの漏えいやシステムのダウン状況を調査し、被害の全体像を把握することが求められる。また、実施後は、調査結果をもとに再発防止策を検討することで、今後のリスクを軽減させる効果がある。このように、情報セキュリティの維持向上に不可欠なプロセスである。","explanationZh":"指安全事件发生后，通过日志、系统状态、受影响资产、泄露数据、业务中断等证据，确定事件范围、影响程度和实际损失的方法。评估结果用于决定事件优先级、恢复措施、对外通报和后续整改，并为根因分析和防止复发提供依据。"},{"id":"t0219","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティポリシーに従った組織運営","termZh":"依据信息安全策略开展组织运营","english":"Organization Operation Based on Information Security Policy","reading":"じょうほうせきゅりてぃぽりしーにしたがったそしきうんえい","breadcrumb":"","explanationJa":"組織の情報資産を守るために定められた方針やルールに基づいて行動することを指す。このポリシーは、情報の機密性、完全性、可用性を確保するための基本的な枠組みを提供し、組織全体が共通の理解を持つよう助ける。例えば、社員がデータにアクセスする際には、適切な認証を求めたり、情報漏洩を防ぐための教育を実施したりすることが具体例である。このように、情報セキュリティポリシーに従うことで、組織はリスクを軽減し、安全な運営を維持することができる。","explanationZh":"指把组织批准的信息安全方针、标准和程序落实到日常业务与 IT 运营中，使访问、数据处理、人员行为和事件响应均遵循统一规则。通过角色职责、培训、控制措施、监督和审计，可以将安全要求从“文件”转化为持续执行的管理实践。"},{"id":"t0220","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティ方針","termZh":"信息安全方针／信息安全策略","english":"Information Security Policy","reading":"じょうほうせきゅりてぃほうしん","breadcrumb":"","explanationJa":"組織内での情報の保護に関する基本的な方針を定めた文書である。この方針は、組織がどのように情報を管理し、保護するかに関する指針を提供し、情報セキュリティの目的や目標を明確にするために作成される。具体的には、機密情報の取り扱いやアクセス制限、事故や脅威への対応策などが含まれる。例えば、企業が顧客の個人情報を守るために、情報セキュリティ方針を策定し、全社員がその方針に従うことで、データ漏洩や不正アクセスを防ぐことができる。このように、情報セキュリティ方針は組織の情報資産を守るための重要な基盤となる。","explanationZh":"指由组织管理层批准的、关于保护信息及实现信息安全目标的总体方向和原则。它应与组织目标和风险环境相一致，并为下级标准、程序和控制措施提供依据。通常包括安全目标、职责、合规要求、访问控制、事件管理等原则，是信息安全管理体系的基础性文件。"},{"id":"t0221","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティ目的","termZh":"信息安全目标","english":"Information Security Objectives","reading":"じょうほうせきゅりてぃもくてき","breadcrumb":"","explanationJa":"組織が情報を保護するために設定する具体的な目標や方針を指す。これらの目的は、情報が持つ機密性、完全性、可用性を確保するために必要な指針となる。例えば、顧客情報や知的財産を盗まれないようにするための施策や、データが不正に改ざんされないようにするための対策が含まれる。組織はこれらの目的を明確にすることで、従業員が情報セキュリティの重要性を理解し、遵守しやすくなる。また、情報セキュリティポリシーと呼ばれる文書でこれらの目的を正式に定め、全体のセキュリティ対策を統一することが求められる。この目的に沿った施策を実施することで、組織の情報資産を効果的に保護することができる。","explanationZh":"组织为保护信息而设定的具体目标，是信息安全管理活动的方向和衡量依据。目标通常围绕机密性、完整性和可用性等要求制定，例如降低信息泄露风险、防止未经授权的篡改、确保关键系统持续可用。组织应将目标与信息安全方针保持一致，明确责任、指标和实施措施，并通过定期评审确认其达成情况。"},{"id":"t0222","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティ対策基準","termZh":"信息安全控制标准","english":"Information Security Control Standards","reading":"じょうほうせきゅりてぃたいさくきじゅん","breadcrumb":"","explanationJa":"情報資産を保護するための具体的な対策やルールを定めた基準である。これにより、組織内の情報を安全に管理し、不正アクセスやデータ漏洩などのリスクを軽減することが目的となっている。具体的な対策には、アクセス制限、データ暗号化、定期的な監査などが含まれる。例えば、特定の情報に対してはパスワードや生体認証を用いることで不正アクセスを防ぎ、データが盗まれるリスクを低減する。また、基準は組織の規模や業種によって異なり、各々の状況に応じた適切なセキュリティ対策が求められる。このような基準の策定は、情報セキュリティポリシーに基づき、組織が一貫した対策を講じるために重要である。","explanationZh":"为保护信息资产而规定具体安全控制措施和实施要求的标准。内容通常包括访问控制、身份认证、加密、日志记录、备份、监控和审计等，用于把上位的信息安全方针落实为可执行的规则。组织应根据业务特点、风险水平和法律法规要求选择并持续维护适当的控制措施。"},{"id":"t0223","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報管理規程","termZh":"信息管理规定","english":"Information Management Regulations","reading":"じょうほうかんりきてい","breadcrumb":"","explanationJa":"企業や組織内で取り扱う情報の管理方法やルールを定めた文書である。この規程には、情報の収集、保管、利用、廃棄に関する具体的な方針が含まれ、情報セキュリティを確保するための指針となる。情報管理規程には、機密情報や個人情報の取り扱いや、不正アクセスを防ぐためのセキュリティ対策が明記されることが一般的である。また、情報管理規程を遵守することで、組織は法令遵守を図り、内部からの情報漏洩やサイバー攻撃に対する備えを強化できる。こうした規程は、情報資産の保護を目的とし、組織全体の情報文化を高める役割も果たしている。","explanationZh":"规定组织内部信息在收集、创建、使用、保存、传输、共享和销毁等全生命周期中的管理原则、责任和操作要求的制度文件。通常还包括信息分类分级、访问权限、个人信息与机密信息保护以及异常情况处理等内容，用于减少泄露、误用和丢失风险，并支持合规管理。"},{"id":"t0224","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"秘密情報管理規程","termZh":"机密信息管理规定","english":"Confidential Information Management Regulations","reading":"ひみつじょうほうかんりきてい","breadcrumb":"","explanationJa":"組織内で取り扱う秘密情報の保護と管理を目的としたルールや手続きのことを指す。この規程は、どのような情報が秘密に該当するか、情報の取り扱い方法やアクセス権限について詳細に定めているため、社員や関係者が情報漏洩を防ぐための指針となる。例えば、顧客の個人情報や企業の機密事項などが含まれ、適切な管理のもとで運用されることが求められる。また、この規程に従うことで、法律や規制にも対応し、組織の信頼性を向上させることができる。具体的には、情報の暗号化やアクセスログの記録、社内教育の実施などが含まれる。","explanationZh":"针对组织所持有的机密信息规定识别、分类、访问、保存、传输、复制、带出和销毁等管理要求的制度。其目的在于明确哪些信息属于秘密、谁可以接触以及应采用何种保护措施。常见措施包括最小权限、加密、访问日志、保密义务和员工培训等，以降低泄密和违规使用的风险。"},{"id":"t0225","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"文書管理規程","termZh":"文档管理规定","english":"Document Management Regulation","reading":"ぶんしょかんりきてい","breadcrumb":"","explanationJa":"組織内において文書を適切に管理するためのルールや手続きを定めたものである。これには、文書の作成、保存、変更、廃棄に関する方針が含まれ、情報セキュリティを確保するために重要な役割を果たす。例えば、機密情報を含む文書については、アクセス制限や暗号化のルールが定められていることが一般的である。また、文書の保存期間や廃棄方法についても具体的な指針が示されており、法律や規制の遵守をサポートする。これにより、組織は情報漏洩のリスクを低減し、業務の効率化を図ることが可能となる。情報の流れを整頓し、責任の明確化を促進するために欠かせないものである。","explanationZh":"规定组织中文档从创建、审批、发布、修改、保存到废弃的管理规则和程序。对含有机密或个人信息的文档，通常还会规定访问限制、加密、版本管理、保存期限和安全销毁方式。规范的文档管理有助于保证信息的完整性、可追溯性和合规性，并减少信息泄露及误用。"},{"id":"t0226","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティインシデント対応規程","termZh":"信息安全事件响应规定","english":"Information Security Incident Response Regulations","reading":"じょうほうせきゅりてぃいんしでんとたいおうきてい","breadcrumb":"","explanationJa":"組織がセキュリティ上の事故や問題、特にマルウェア感染などのインシデントに直面した際の対応手順やルールを定めたものである。この規程は、インシデントの検出、分析、対処、報告までの一連のプロセスを明確にし、迅速かつ効果的な対応を可能にする。例えば、マルウェア感染が発生した際には、まずシステムを隔離し、その後感染の範囲を調査・分析することが求められる。また、対応後には再発防止策の策定や関係者への報告が行われる。これにより、情報資産を保護し、信頼性の高い運用を維持することが目的である。","explanationZh":"规定发生信息安全事件时的发现、报告、分级、分析、遏制、根除、恢复和事后复盘等处理流程及责任分工。发生恶意软件感染等事件时，应迅速隔离受影响系统、确认影响范围、保存证据并实施恢复，同时按规定向相关人员和机构报告。其目的在于控制损害、尽快恢复业务并防止同类事件再次发生。"},{"id":"t0227","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティ教育の規程","termZh":"信息安全教育规定","english":"Information Security Education Regulations","reading":"じょうほうせきゅりてぃきょういくのきてい","breadcrumb":"","explanationJa":"組織内での情報セキュリティに関する知識と意識を向上させるための教育方針や手順を定めたものである。この規程は、業務に従事する全ての従業員に対して、情報セキュリティの重要性を認識させ、適切な対応を促すことを目的としている。具体的には、定期的なトレーニングや研修、評価基準の設定、教育内容の見直しなどが含まれる。例えば、新入社員に対しては、セキュリティの基本的な知識や実践方法を学ぶ研修が実施される。また、既存の社員には、最新の脅威や対策についての情報を提供することで、常に最新の知識を持ち続けるように努める。これにより、組織全体の情報セキュリティの強化が図られる。","explanationZh":"规定组织开展信息安全教育、培训和意识提升活动的方针、对象、频次、内容、评价及记录要求。新员工通常需要接受基础安全培训，现有员工则应定期学习最新威胁、内部规则和应对方法。持续教育能够减少人为错误，提高员工识别钓鱼、违规操作等风险的能力。"},{"id":"t0228","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"プライバシーポリシー","termZh":"隐私政策","english":"Privacy Policy","reading":"","breadcrumb":"","explanationJa":"個人情報を収集・利用する際の方針を明示した文書である。企業や団体がどのような情報を収集し、どのように保護するかを利用者に伝えることが目的である。具体的には、収集する情報の種類、利用目的、情報の第三者への提供、保管期間、利用者の権利などが含まれる。例えば、オンラインサービスでは、ユーザーが入力した氏名やメールアドレスなどの個人情報をどのように扱うかを説明することで、信頼性を築くことができる。また、プライバシーポリシーは法的な要件でもあり、適切な対応が求められるため、企業やWebサイトはこれを遵守することが重要である。","explanationZh":"组织向个人说明其如何收集、使用、保存、共享和保护个人信息的公开政策。通常包含收集的信息种类、处理目的、第三方提供、保存期限、安全措施以及个人所享有的查询、更正、删除等权利。隐私政策既是透明度和信任建设的重要手段，也是满足个人信息保护相关法律法规要求的重要文件。"},{"id":"t0229","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"職務規程","termZh":"岗位职责规定","english":"Job Regulations","reading":"しょくむきてい","breadcrumb":"","explanationJa":"組織における役割や責任、業務遂行のルールを定めた文書である。この規程は、特に情報セキュリティの観点から重要視され、従業員が守るべき具体的な行動指針を示す。例えば、機密情報の取り扱いや、アクセス権の管理、情報システムの利用方法が含まれる。これにより、情報漏洩や不正アクセスを防ぐための基盤が形成され、組織全体のセキュリティレベルを向上させる役割を果たす。また、職務規程は法令や業界基準に基づき制定されることが多く、定期的な見直しが行われることで、常に最新のリスクに対応した内容が維持される。","explanationZh":"规定组织内各岗位的职责、权限、业务规则和应遵守事项的制度文件。在信息安全方面，通常会明确机密信息处理、系统使用、访问权限、职责分离和报告义务等要求。通过明确责任边界，可以减少权限滥用、操作错误和责任不清带来的风险。"},{"id":"t0230","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"罰則の規程","termZh":"处罚规定","english":"Penalty Regulations","reading":"ばっそくのきてい","breadcrumb":"","explanationJa":"情報セキュリティに関連するルールやポリシーを守らなかった場合に適用される罰則を定めた文書である。これにより、組織内での情報セキュリティの遵守を促進し、違反行為が発生した際の対処方法が明確になる。具体的には、情報漏洩や不適切なシステム利用などの行為に対する罰則が規定されており、従業員はその内容を理解し遵守することが求められる。罰則は警告から始まり、重い場合は解雇などの厳しい対応が含まれることもある。このような規程は、組織の情報資産を保護し、セキュリティリスクを低減するための重要な要素である。","explanationZh":"规定违反信息安全方针、规章或操作要求时所适用的纪律处分和处理程序。处罚对象可能包括信息泄露、违规使用系统、擅自共享账号等行为，措施可从警告、教育整改到严重情况下的纪律处分。明确且一致执行处罚规则有助于提高制度约束力，但应与劳动法规和组织内部程序相一致。"},{"id":"t0231","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"対外説明の規程","termZh":"对外说明规定","english":"External Explanation Regulations","reading":"たいがいせつめいのきてい","breadcrumb":"","explanationJa":"組織が外部に向けて情報を提供する際のルールやガイドラインである。この規程は、機密情報や個人情報が不適切に公開されるのを防ぐために設けられており、情報公開の基準や手続きを明確に定めている。例えば、広報部門がプレスリリースを作成する際には、事前に内容を確認するプロセスが含まれることが多い。また、情報の公開範囲やタイミングについても規定されており、必要に応じて特定の情報を隠すことが求められる場合がある。これにより、組織はリスクを軽減し、信頼性を向上させることができる。情報セキュリティの観点からも、外部への情報発信は慎重に行うべきであるため、この規程は非常に重要である。","explanationZh":"规定组织向媒体、客户、合作伙伴、监管机构等外部主体发布或说明信息时的审批流程、责任人、内容范围和时机。其目的是防止机密信息、个人信息或未经确认的信息被不当公开。发生安全事件时，该规定也可用于统一对外口径，降低声誉、法律和信息泄露风险。"},{"id":"t0232","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"例外の規程","termZh":"例外管理规定","english":"Exception Policy","reading":"れいがいのきてい","breadcrumb":"","explanationJa":"情報セキュリティポリシーにおいて、特定の状況や条件下で標準的なセキュリティ対策に対して例外を認めるルールである。通常、情報セキュリティポリシーは組織が保護すべき情報やリソースに対して適用されるが、特別な事情により通常のルールが適用できない場合に、この規程が用いられる。例えば、特定の業務上の必要から特定のデバイスへのアクセスが許可される場合や、旧式のシステムに対する一時的なアクセスを認める場合がある。このような例外が発生した際には、リスク評価や適切な監視が必要で、例外許可を得るための手続きが明確に定められていることが重要である。これにより、セキュリティリスクを最小限に抑えつつ、業務の柔軟性も確保される。","explanationZh":"规定在特殊业务条件下无法完全遵守标准安全要求时，如何申请、评估、批准、记录和定期复审例外。例外不等于免除管理责任，通常需要开展风险评估，并采取补偿性控制、限定期限和加强监控。通过正式的例外流程，可在业务灵活性与安全风险之间取得可控平衡。"},{"id":"t0233","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"規則更新の規程","termZh":"规章更新规定","english":"Regulation on Rule Revision","reading":"きそくこうしんのきてい","breadcrumb":"","explanationJa":"組織内で設定された規則やポリシーを適切に見直し、更新するためのルールを明文化したものである。この規程は、情報セキュリティに関連する規則が時代や技術の変化に応じて適切であるかを確認するために必要である。具体的には、定期的な見直しのスケジュールや、更新の手続き、改善点の評価方法等が含まれる。たとえば、サイバー攻撃の手法が進化する中、新たな脅威に対応するために定期的に業務規範を見直すことは、組織全体のセキュリティ対策を強化する重要な手段となる。このように、組織が持続的に安全性を保つための基盤を提供するものである。","explanationZh":"规定组织对信息安全相关规章、标准和程序进行定期或触发式审查、修订、审批和发布的流程。技术环境、业务模式、法律法规或威胁发生变化时，应及时确认现有规则是否仍然有效。持续更新制度能够避免安全要求与实际风险脱节，并保持管理体系的适宜性。"},{"id":"t0234","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"規程の承認手続","termZh":"规章审批程序","english":"Approval Procedures for Regulations","reading":"きていのしょうにんてつづき","breadcrumb":"","explanationJa":"組織内での情報セキュリティに関するルールやポリシーを制定・改訂する際に必要な手続きのことである。これは、情報セキュリティポリシーを含む各種規程が適切に運用されるための基盤を提供する。具体的には、策定された規程が各関係者によって確認され、承認を得る過程が含まれる。この手続きは、責任を明確にし、組織全体の運用方針に沿った形で承認されることで、一貫性が保たれる。例えば、新しいセキュリティポリシーが提案された場合、業務部門やIT部門などの関係者からの意見を集め、最終的に管理者が承認することが求められる。このような手続きにより、規程の有用性や適切性が保証され、情報セキュリティの確保が図られる。","explanationZh":"组织制定或修订规章制度时，用于审查、协调和正式批准的程序。通常由相关业务、法务、信息安全、IT等部门进行确认，再由具有授权的管理者批准发布。规范的审批流程能够明确责任，保证制度与组织方针、法律法规及实际业务需求保持一致。"},{"id":"t0235","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"ソーシャルメディアガイドライン","termZh":"社交媒体使用指南","english":"Social Media Guidelines","reading":"","breadcrumb":"","explanationJa":"組織がSNSを利用する際のルールや基準を定めたものである。このガイドラインは、従業員がSNS上で発信する情報が、組織のイメージや信頼性にどのように影響するかを考慮し、安全性や倫理を重視している。具体的には、個人情報の取り扱いや、会社に関する情報の公開範囲、また是正すべき行動や禁止事項を明示する。例えば、従業員が不適切な内容を投稿することを防ぐことで、企業の reputational（評判）リスクを軽減することが可能である。このように、企業のブランディングやリスク管理を支援する重要な役割を果たしている。","explanationZh":"组织针对员工或官方账号使用社交媒体制定的行为准则。内容通常包括禁止泄露机密和个人信息、发布公司相关内容的审批范围、账号安全、著作权与言论规范以及发生问题时的报告方式。其目的在于降低信息泄露、声誉受损、冒充账号和错误信息传播等风险。"},{"id":"t0236","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"ISMS適用範囲","termZh":"ISMS适用范围","english":"ISMS Scope","reading":"あいえすえむえすてきようはんい","breadcrumb":"","explanationJa":"情報セキュリティマネジメントシステム（ISMS）が適用される組織の範囲を定義するものである。具体的には、どの部門やプロセス、情報資産がISMSの管理対象となるかを明確にする。この範囲設定は、情報の保護に必要なリスク評価や管理策を効果的に行うために重要である。例えば、企業が新しい製品を開発する際、その開発部門と関連する情報をISMSの適用範囲に含めることができる。このようにすることで、関係するすべての情報が適切に守られる。しかし、適用範囲を広げすぎるとリソースが分散し、管理が難しくなるため、適切な範囲を設定することが求められる。","explanationZh":"信息安全管理体系（ISMS）所覆盖的组织边界和业务范围，包括相关部门、地点、业务流程、信息资产、系统及接口。适用范围应考虑组织环境、相关方要求以及与外部组织的依赖关系，并形成明确的范围说明。范围划定过窄可能遗漏关键风险，过宽则会增加管理复杂度，因此应与实际业务和风险相匹配。"},{"id":"t0237","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"リーダーシップ","termZh":"领导作用","english":"Leadership","reading":"","breadcrumb":"","explanationJa":"特定の目標に向かって人々を導く能力や行動のことである。特に情報セキュリティマネジメントシステム（ISMS）においては、効果的なリーダーシップが組織のセキュリティ文化を形成し、維持するために重要である。良好な組織内の従業員に対してセキュリティの重要性を認識させ、リスクを軽減するための対策を講じるよう促す役割を果たす。例えば、組織のトップがセキュリティポリシーを積極的に推進することで、全員がその重要性を理解し、協力してセキュリティを強化することができる。リーダーシップがしっかりしていると、従業員の意識向上や行動変容が促され、組織全体のセキュリティ体制が向上する。","explanationZh":"在ISMS中，最高管理层通过确立方针、分配责任和资源、推动安全文化并监督管理体系有效性，对信息安全承担领导责任。管理层的明确承诺能够使信息安全目标与业务战略保持一致，并促使员工理解和履行安全职责。领导作用是ISMS有效运行的重要前提。"},{"id":"t0238","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"計画","termZh":"策划","english":"Planning","reading":"けいかく","breadcrumb":"","explanationJa":"目標を達成するために必要な行動を事前に策定するプロセスである。情報セキュリティマネジメントシステム（ISMS）においては、リスクを評価し、適切な対策を講じるための計画を立てることが求められる。この計画には、セキュリティポリシーの策定、リスクの特定、対策の優先順位付けが含まれる。具体的には、重要な情報資産を守るために、セキュリティ対策をどのように実施するかを決定し、実行計画として文書化することで、組織全体がセキュリティに対する意識を高める役割を果たす。また、計画は定期的に見直され、変化する脅威に対応するための柔軟性を持たせることが重要である。","explanationZh":"为实现ISMS目标而事先确定风险应对、信息安全目标、实施措施、责任和资源的过程。策划应以组织环境和风险评估为基础，明确需要做什么、由谁负责、何时完成以及如何评价结果。还应根据新的威胁、业务变化和评估结果持续调整计划。"},{"id":"t0239","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"運用","termZh":"运行","english":"Operation","reading":"うんよう","breadcrumb":"","explanationJa":"情報セキュリティマネジメントシステム（ISMS）において、セキュリティポリシーや手順を実際に実行し、維持管理するプロセスを指す。具体的には、情報資産を適切に保護するための施策を日常的に行い、リスクを管理することが含まれる。たとえば、定期的なセキュリティチェックや社員への教育・訓練が運用の一環であり、これにより組織の情報セキュリティを強化することが可能となる。また、運用は継続的改善のサイクルとも関連しており、実施した施策の効果を評価し、それに基づいて改善策を講じることも重要である。これにより、常に最新のリスクに対応できる状態を維持することが目指されている。","explanationZh":"按照既定方针、程序和计划实际执行并控制ISMS相关活动的过程。包括实施风险处置计划、安全控制、日常监控、教育培训以及变更管理等，并保存必要的运行证据。运行过程中发现偏差或环境变化时，应及时采取措施，以保持风险处于可接受水平。"},{"id":"t0240","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"パフォーマンス評価","termZh":"绩效评价","english":"Performance Evaluation","reading":"ぱふぉーまんすひょうか","breadcrumb":"","explanationJa":"組織の情報セキュリティマネジメントシステム（ISMS）における効果や適切性を評価するプロセスである。この評価は、内部監査やマネジメントレビューなどの手法を通じて実施される。内部監査では、実際の運用が規定された方針や手順に従って行われているかを確認し、その結果を基に改善点を洗い出すことが目的である。一方、マネジメントレビューは、組織の上層部が実施し、全体的なパフォーマンスを評価し、リソースの適正利用やリスクの分析を行う。このように、組織が情報セキュリティの向上を図り、リスクを管理するための重要な活動である。","explanationZh":"对ISMS是否适宜、充分和有效进行监视、测量、分析和评价的活动。典型手段包括安全指标监测、内部审核以及管理评审。通过绩效评价可以确认控制措施是否按预期发挥作用、目标是否达成，并识别需要改进的事项。"},{"id":"t0241","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"改善","termZh":"改进","english":"Improvement","reading":"かいぜん","breadcrumb":"","explanationJa":"不適合や問題点を見つけ出し、それに対する是正措置を講じることや、事業やシステムの質を継続的に向上させるプロセスである。特に情報セキュリティマネジメントシステム（ISMS）においては、組織がセキュリティリスクを常に監視し、評価し、必要に応じて対策を更新することで、情報資産を保護することを目的とする。不適合が見つかれば、その原因を分析し、再発防止策を実施することが求められる。また、継続的改善はPDCAサイクル（計画・実行・評価・改善）を基に進められ、組織全体のセキュリティ体制を向上させることで、より安全な環境の構築を目指す。このように、改善は組織の持続的な成長に欠かせない要素である。","explanationZh":"针对不符合项、问题和变化持续提升ISMS适宜性、充分性与有效性的过程。发现不符合时应处理其后果、分析原因、实施纠正措施并验证效果，同时根据监测、审核和管理评审结果持续改进。其核心是形成可持续的闭环管理，而不是一次性整改。"},{"id":"t0242","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"管理目的","termZh":"控制目标","english":"Management Objectives","reading":"かんりもくてき","breadcrumb":"","explanationJa":"組織が情報セキュリティを維持・向上するために設定する具体的な目標や意図のことである。これは、情報セキュリティマネジメントシステム（ISMS）を効果的に機能させるための指針となる。例えば、機密情報の保護や情報漏洩の防止、法令遵守を達成することが目指される。リスク評価を通じて明確にされ、具体的なアクションプランや指標を基に定期的に評価される。これにより、組織は情報セキュリティの状況を把握し、適切な対策を講じることで、業務の継続性や信頼性を高めることができる。このように、管理目的は情報セキュリティの運用において中心的な役割を果たしている。","explanationZh":"组织希望通过信息安全控制措施达到的安全状态或结果，例如防止未经授权访问、保护机密信息、满足法律法规要求等。控制目标应与风险处置和信息安全目标相联系，并通过具体控制措施实现。评价控制有效性时，应确认这些目标是否实际达成。"},{"id":"t0243","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティ管理策","termZh":"信息安全控制措施","english":"Information Security Management Measures","reading":"じょうほうせきゅりてぃかんりさく","breadcrumb":"","explanationJa":"組織の情報資産を守るために実施される一連の方策を指す。これらは、情報セキュリティマネジメントシステム（ISMS）の中心的な要素であり、効果的なセキュリティ対策の実施を支える。主に四つの種類に分類される。組織的管理策は、組織全体の方針や体制を整備するものであり、セキュリティ文化の確立が含まれる。人的管理策は、従業員の教育や意識向上を図るもので、ヒューマンエラーを防ぐために重要である。物理的管理策は、ハードウェアや施設の安全を確保する対策を指し、アクセス制限や監視カメラの設置が例として挙げられる。そして、技術的管理策は、ファイアウォールや暗号化技術など、情報を保護するための技術的手段を含む。これらの全てが相互に連携することで、情報セキュリティの確保が目指される。","explanationZh":"为降低信息安全风险、保护信息资产而实施的组织性、人员性、物理性和技术性措施。组织性控制包括制度和治理，人员控制包括培训与职责管理，物理控制包括门禁和设施保护，技术控制包括身份认证、加密、防火墙等。各种控制应根据风险组合使用，并持续评价其有效性。"},{"id":"t0244","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"管理策タイプ","termZh":"控制措施类型","english":"Management Control Types","reading":"かんりさくたいぷ","breadcrumb":"","explanationJa":"リスクを管理するための手法のカテゴリーであり、予防、検知、是正がある。予防策は、問題が発生する前にリスクを未然に防ぐことを目指す具体的な対策を指す。例えば、アクセス権を制限することや、セキュリティポリシーの遵守を促進するトレーニングが挙げられる。検知策は、異常や侵入の兆候を早期に発見するための手段で、監視システムやログの分析がこれに含まれる。是正策は、問題が発生した後に、それを修正するための活動を指し、インシデント対応やデータのリカバリが該当する。これらの組織のセキュリティを強化するために互いに連携し、効果的な情報管理を実現する。","explanationZh":"按作用时点或目的对安全控制进行分类的方式，常见包括预防性、检测性和纠正性控制。预防性控制用于阻止事件发生，如访问限制；检测性控制用于尽早发现异常，如日志监控和入侵检测；纠正性控制用于事件发生后消除影响并恢复，如补丁、恢复和事件响应。多种类型协同使用可形成更完整的防护体系。"},{"id":"t0245","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"サイバーセキュリティ概念","termZh":"网络安全核心功能","english":"Cybersecurity Concepts","reading":"さいばーせきゅりてぃがいねん","breadcrumb":"","explanationJa":"情報資産を安全に守るための基本的な枠組みを指すものである。これには、識別、防御、検知、対応、復旧の5つの要素が含まれる。まず、識別では、資産やリスクを把握し、保護すべき対象を明確にする。次に、防御は、攻撃からシステムを守るための対策を講じることである。検知は、異常や攻撃を早期に見つけ出すプロセスであり、迅速な対応が求められる。対応では、発生したインシデントに対して適切にアクションを取ることが重要である。最後に、復旧は、被害を最小限に抑え、迅速に正常な状態に戻すための取り組みである。これらの要素が統合されて初めて、効果的なサイバーセキュリティが実現される。","explanationZh":"用于系统化管理网络安全风险的一组核心活动，通常可概括为识别、保护、检测、响应和恢复。识别用于了解资产与风险；保护用于实施防护措施；检测用于及时发现异常；响应用于遏制和处置事件；恢复用于恢复业务并提高韧性。将这些功能作为闭环管理，可以提升组织整体网络安全能力。"},{"id":"t0246","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"有効性","termZh":"有效性","english":"Effectiveness","reading":"ゆうこうせい","breadcrumb":"","explanationJa":"特定の目的や目標に対して、どれだけ効果的に機能しているかを示す指標である。情報セキュリティマネジメントシステム（ISMS）においては、セキュリティ対策が情報資産を保護するためにどれだけ適切に機能しているかを評価するために使われる。たとえば、特定のセキュリティポリシーが企業のデータを守るためにどの程度成功しているかを測定することが、有効性の確認となる。これにより、企業は必要な改善や強化策を導入し、より安全な情報環境を築くことができる。","explanationZh":"某项措施、过程或管理体系达到预定目标和产生预期结果的程度。在ISMS中，重点是确认安全控制是否真正降低风险、保护信息资产并支持信息安全目标，而不只是确认是否“已经实施”。组织通常通过指标、测试、监控、审核和事件数据来评价其有效性。"},{"id":"t0247","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"ISMS適合性評価制度","termZh":"ISMS符合性评价制度","english":"ISMS Certification Scheme","reading":"あいえすえむえすてきごうせいひょうかせいど","breadcrumb":"","explanationJa":"情報セキュリティに関する管理体制が一定の基準を満たしているかを評価する仕組みである。この制度は、組織が情報セキュリティのリスクを適切に管理し、保護するためのフレームワークを提供する。具体的には、ISO/IEC 27001という国際規格に基づいて評価が行われ、その結果、適合していると認められた組織はISMS認証を取得できる。これは、顧客や取引先に対する信頼性を高めるだけでなく、情報漏洩のリスクを低減させる効果もあるため、現代の企業活動において必要不可欠な制度となっている。この評価制度を通じて、組織は情報セキュリティへの取り組みを継続的に改善し、重要な情報を守るための基盤を強化することができる。","explanationZh":"依据ISO/IEC 27001等要求，由独立第三方评价组织的信息安全管理体系是否符合规定标准的认证框架。通过审查管理体系文件和实际运行情况，确认风险管理、控制措施、内部审核和持续改进机制等是否有效建立。通过认证可以向客户和合作方证明组织具备系统化的信息安全管理能力。"},{"id":"t0248","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"ISMS認証","termZh":"ISMS认证","english":"ISMS Certification","reading":"あいえすえむえすにんしょう","breadcrumb":"","explanationJa":"情報セキュリティマネジメントシステムが、国際標準に基づいて適切に運用されていることを第三者が評価し、認証を与える制度である。具体的には、組織が情報の機密性、完全性、可用性を確保するためのルールや手順を整備し、実際にそれを実行しているかどうかが審査される。このような認証を取得することで、企業や組織は情報セキュリティに対する取り組みの透明性や信頼性を示すことができ、顧客や取引先からの信頼を得やすくなる。さらに、ISMS認証の取得は、法的な責任や事故に対するリスク管理を強化する手段としても重要であり、競争優位を獲得する一環としても利用されている。","explanationZh":"由第三方认证机构依据ISO/IEC 27001等标准，对组织的ISMS进行审核并确认其符合要求后授予的认证。审核不仅查看制度文件，还会确认风险评估、控制措施、运行记录、内部审核和管理评审等是否实际有效。取得认证有助于提高外部信任，但并不意味着组织绝对不会发生安全事件。"},{"id":"t0249","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"JIS Q 27001","termZh":"JIS Q 27001","english":"JIS Q 27001","reading":"じすきゅー27001","breadcrumb":"","explanationJa":"情報セキュリティマネジメントシステム（ISMS）の国際標準であるISO/IEC 27001に基づいた日本規格である。この規格は、組織が情報のセキュリティを確保するための枠組みを提供し、機密性、完全性、可用性を守ることを目的としている。具体的には、リスク評価やリスクマネジメントを行い、セキュリティ対策を実施するための手順が示されている。たとえば、データ漏洩を防ぐための対策や、システム障害への対応計画などが含まれる。JIS Q 27001の認証を取得することで、企業は顧客や取引先に対して情報セキュリティへの取り組みを示すことができ、信頼性を向上させることが期待される。これは、特にデジタル社会の中でますます重要視されている。","explanationZh":"日本依据ISO/IEC 27001制定的信息安全管理体系（ISMS）国家标准。该标准规定了建立、实施、维护和持续改进ISMS的要求，包括组织环境、领导作用、风险评估与处置、运行、绩效评价和改进等。组织可以依据该标准接受第三方认证，以证明其信息安全管理体系符合要求。"},{"id":"t0250","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"JIS Q 27002","termZh":"JIS Q 27002","english":"JIS Q 27002","reading":"じすきゅー27002","breadcrumb":"","explanationJa":"情報セキュリティマネジメントシステム（ISMS）に関連する規格である。具体的には、情報セキュリティを確保するためのベストプラクティスや管理策を定めたもので、企業や組織が情報を守るためのガイドラインとなる。この規格は、ISO/IEC 27002に基づいており、さまざまなセキュリティ対策やリスク管理の手法を含んでいる。たとえば、アクセス制御、情報の保護、脅威の監視など、実践的な例が挙げられ、組織が効果的にセキュリティを向上させるための支援を提供する。これにより、情報漏洩やサイバー攻撃からの防御が強化され、信頼性のある情報管理が実現される。","explanationZh":"日本依据ISO/IEC 27002制定的信息安全控制实践指南，为组织选择和实施信息安全控制提供参考。内容涵盖组织、人员、物理和技术等多个方面，例如访问控制、资产保护、日志监控和安全事件管理。它主要作为控制措施实施指南使用，本身通常不是ISMS认证标准。"},{"id":"t0251","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティガバナンス","termZh":"信息安全治理","english":"Information Security Governance","reading":"じょうほうせきゅりてぃがばなんす","breadcrumb":"","explanationJa":"組織における情報セキュリティの管理を統括する枠組みである。具体的には、情報資産を保護するための方針やプロセスを策定し、業務戦略と連携させることを目的とする。JIS Q 27014やISO/IEC 27014は、情報セキュリティガバナンスを実践するための国際的な規格であり、組織が効果的なセキュリティ対策を実施できるようにするための指導原則を提供する。これにより、リスクの管理やコンプライアンスの遵守が容易になり、全体的な情報セキュリティの向上に寄与する。情報セキュリティガバナンスを強化することで、信頼性の高いビジネス環境を整えることが可能となる。","explanationZh":"由组织治理层和最高管理层对信息安全进行指导、监督和问责，使信息安全与业务目标、风险管理和合规要求保持一致的治理框架。其内容包括明确决策权和责任、设定方向、监督绩效、评价风险并确保资源投入。良好的信息安全治理有助于将安全从单纯技术问题提升为组织级管理议题。"},{"id":"t0252","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"インシデントハンドリング","termZh":"安全事件处理","english":"Incident Handling","reading":"","breadcrumb":"","explanationJa":"情報セキュリティにおける不正アクセスやデータ漏洩などのインシデントに対処するプロセスである。このプロセスは、まずインシデントの検知と連絡受付から始まり、報告された問題の重要度を評価するトリアージを行う。その後、適切なインシデントレスポンスを実施し、問題の解決に向けた対応を行う。最後に、発生したインシデントの報告や情報公開を行い、今後の対応策を考えるためのデータを蓄積する。この一連のプロセスは、組織の情報セキュリティを強化するために不可欠であり、継続的な改善を促進する役割も果たす。","explanationZh":"对信息安全事件从发现到结束进行系统管理的全过程，通常包括受理与检测、分类和分级、分析、遏制、根除、恢复、报告以及事后复盘。通过明确流程和责任，可以减少响应时间和损失，并把事件中的经验转化为改进措施。事件处理通常由CSIRT等组织协调实施。"},{"id":"t0253","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"テイクダウン","termZh":"下架／清除（Takedown）","english":"Takedown","reading":"","breadcrumb":"","explanationJa":"情報セキュリティにおけるインシデント管理の一環として、不正なコンテンツや脅威を排除するプロセスを指す。この手法は、サイバー攻撃や違法な情報の拡散を防ぐために迅速に行われる。例えば、フィッシングサイトやマルウェアを配布しているサーバを特定し、その運営者と連携してコンテンツを削除することが一般的である。セキュリティの向上やユーザーの保護を目的とし、インシデント対応の重要なステップであり、組織が信頼性のある安全な環境を提供するために欠かせない活動となっている。","explanationZh":"在安全事件处置中，通过与网站运营者、托管商、域名注册相关机构等协调，使钓鱼网站、恶意内容或恶意基础设施停止提供服务或被删除的措施。其目的是迅速降低攻击持续造成的危害。执行时通常需要保存证据、确认合法程序，并与相关机构协作。"},{"id":"t0254","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティ委員会","termZh":"信息安全委员会","english":"Information Security Committee","reading":"じょうほうせきゅりてぃいいんかい","breadcrumb":"","explanationJa":"組織内で情報セキュリティに関する方針や対策を策定し、実施するための専門的なグループである。この委員会は、情報資産を保護するためにリスクを評価し、適切な管理策を講じることが求められる。例えば、定期的なセキュリティ評価や、従業員に対するセキュリティ教育の実施が含まれ、これにより組織全体のセキュリティ意識を高めることができる。また、セキュリティインシデントが発生した際の対応手順を定めることも重要な役割であり、持続的な改善を追求するための活動を行っている。","explanationZh":"组织内部负责审议、协调和监督信息安全重要事项的管理机构。通常由业务、IT、法务、风险管理和管理层等相关人员组成，负责方针和重大控制措施的决策、风险与事件报告审议、资源协调以及改进监督。通过跨部门机制，可使信息安全决策与组织整体经营保持一致。"},{"id":"t0255","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"CSIRT","termZh":"计算机安全事件响应团队（CSIRT）","english":"Computer Security Incident Response Team","reading":"しーさーと","breadcrumb":"","explanationJa":"コンピュータセキュリティに関連するインシデント（事故や攻撃）に対応する専門組織である。不正アクセスやウイルス感染などのセキュリティインシデントが発生した際に、迅速に対応し、被害を最小限に抑える役割を担っている。具体的には、インシデントの検知、分析、対応策の実施、そして再発防止策の提案を行う。例えば、企業や大学に設置された内部ネットワークでの異常な活動を監視し、問題が発生した場合には必要な対策を講じることで、情報資産の保護に寄与する。また、CSIRTは関係機関との連携を強化し、最新の脅威情報を共有することで、より高度な防御体制を構築する重要な存在である。","explanationZh":"专门负责协调和处置计算机与网络安全事件的团队。其职责可包括事件接收、分析、分级、响应协调、技术支援、证据保全、对外联络、威胁信息共享和事后复盘。CSIRT可以设在单一组织内部，也可以作为行业或地区性的协调机构运行。"},{"id":"t0256","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"PSIRT","termZh":"产品安全事件响应团队（PSIRT）","english":"Product Security Incident Response Team","reading":"ぴーさーと","breadcrumb":"","explanationJa":"製品のセキュリティに関する問題やインシデントに対応する専門チームである。このチームは、脆弱性や攻撃に関する情報を収集し、分析し、適切な対策を講じることを主な目的としている。例えば、特定のソフトウェアに深刻な脆弱性が発見されると、PSIRTはその情報をもとに、影響を受ける全てのユーザーに向けて警告を発し、修正パッチや利用方法を提供する。これにより、ユーザーは迅速に対策を講じることができ、セキュリティリスクを低減できる。製品の信頼性向上や顧客の安全を守るために非常に重要な役割を果たしている。また、各種ベンダーや組織がPSIRTを設置することで、セキュリティの強化が図られている。","explanationZh":"由产品或服务提供者设置，专门处理其产品安全漏洞和安全事件的团队。PSIRT负责接收漏洞报告、验证和评估影响、协调研发修复、发布补丁与安全公告，并与研究人员、客户及相关机构沟通。其目标是建立可重复的产品漏洞响应流程，降低客户暴露于已知风险的时间。"},{"id":"t0257","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"SOC","termZh":"安全运营中心（SOC）","english":"Security Operation Center","reading":"そっく","breadcrumb":"","explanationJa":"情報システムやネットワークのセキュリティを監視・管理する専門的な組織である。リアルタイムで脅威を検出し、対応する役割を担っており、サイバー攻撃や不正アクセスを防ぐための防御ラインとなっている。例えば、企業のセキュリティイベントを監視し、異常が発生した際には自動的にアラートを生成し、適切な対策を講じることが求められる。また、SOCはセキュリティインシデントの対応や分析のための専門知識を持ったスタッフが常駐しているため、迅速な対応が可能であり、組織全体の情報セキュリティの向上に寄与している。これにより、企業はサイバー脅威から重要な資産を守るための強力な手段を持つことになる。","explanationZh":"集中负责安全监控、检测、分析和初步响应的专业运营中心。SOC通常持续收集日志、网络流量和终端安全事件，利用SIEM、EDR等工具发现可疑活动，并根据流程进行告警研判和升级。它与CSIRT等团队协作，可提高组织对网络威胁的持续可视性和响应速度。"},{"id":"t0258","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"エシカルハッカー","termZh":"道德黑客／白帽黑客","english":"Ethical Hacker","reading":"","breadcrumb":"","explanationJa":"情報システムのセキュリティを向上させるために、合法的にハッキング行為を行う専門家のことである。彼らは、企業や組織のネットワークやアプリケーションに存在する脆弱性を特定し、修正策を提案する役割を担っている。具体的には、サイバー攻撃を模倣してセキュリティの弱点を発見し、これを利用して実際の悪意ある攻撃から組織を守る手助けを行う。法律を遵守し、依頼を受けた範囲内で活動するため、企業内の安全対策を強化する重要な存在である。","explanationZh":"在获得合法授权和明确范围的前提下，通过模拟攻击、渗透测试等方式发现系统或应用安全弱点的安全专业人员。其活动必须遵守法律、合同和测试范围，并在发现问题后向授权方报告风险和修复建议。目的在于帮助组织在恶意攻击者利用漏洞之前改进防护。"},{"id":"t0259","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"サイバーセキュリティ戦略本部","termZh":"网络安全战略本部","english":"Cybersecurity Strategy Headquarters","reading":"さいばーせきゅりてぃせんりゃくほんぶ","breadcrumb":"","explanationJa":"国家や組織においてサイバーセキュリティに関する方針を策定し、実施するための機関である。この本部は、サイバー攻撃に対する防御策を整え、国民や企業の情報を守ることを目的としている。具体的には、脅威の分析やリスク評価を行い、必要な対策を講じる。また、関係機関との連携や情報共有を図ることで、サイバーセキュリティの向上を進める役割も担っている。これにより、国全体の安全性を高め、経済活動を支える基盤を形成することが期待されている。","explanationZh":"日本国家层面用于统筹网络安全战略和重要政策的组织名称。其作用在于协调政府相关机构、研究重大网络安全方针和措施，并推动国家整体防护能力建设。作为日本特有机构名称，复习时应同时记住其日文原名及其在国家网络安全治理中的统筹定位。"},{"id":"t0260","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"国家サイバー統括室","termZh":"国家网络安全统括室","english":"National Cybersecurity Office","reading":"こっかさいばーとうかつしつ","breadcrumb":"","explanationJa":"国の情報セキュリティを統括し、サイバー攻撃からの防御や対策を行うための機関である。この機関は、政府機関や民間企業との連携を図り、サイバーセキュリティの強化や情報共有を行う役割を持つ。また、サイバー攻撃の予兆を監視し、迅速に対応するための体制を整えている。国内のサイバーセキュリティ政策の策定だけでなく、実際のサイバーインシデントの調査や対策の指導も担当することから、国全体のセキュリティ強化に寄与する重要な機関である。","explanationZh":"日本国家层面负责网络安全政策统筹、政府机构协调和相关安全工作的组织名称。其职能包括推动国家网络安全政策、协调政府与相关主体并加强安全治理。属于日本制度性专有名词，考试中应以日文正式名称和职责定位为重点掌握。"},{"id":"t0261","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"IPAセキュリティセンター","termZh":"IPA安全中心","english":"IPA Security Center","reading":"あいぴーえーせきゅりてぃせんたー","breadcrumb":"","explanationJa":"情報処理推進機構（IPA）が運営する情報セキュリティに関する専門機関である。このセンターは、国内外の情報セキュリティに関する調査・分析を行い、脆弱性情報やセキュリティ対策に関する情報を提供している。具体的には、セキュリティインシデントに関する対応ガイドや、教育・啓発活動を通じて、企業や個人がネットワークやシステムを安全に運用できるよう支援している。さらに、攻撃手法やマルウェアの最新情報をまとめたリポートを発行し、セキュリティ意識の向上に努めている。","explanationZh":"日本信息处理推进机构（IPA）开展信息安全相关调查、分析、信息发布、指南制定和宣传教育等工作的专业部门。其面向企业和个人提供漏洞、攻击、事件应对以及安全实践等信息，是日本信息安全领域的重要公共支援机构之一。"},{"id":"t0262","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"CRYPTREC","termZh":"CRYPTREC（密码研究与评估委员会体系）","english":"CRYPTREC","reading":"くりぷとれっく","breadcrumb":"","explanationJa":"日本における暗号技術の研究と評価を行うためのプロジェクトである。正式には「暗号技術の評価に関する研究開発プロジェクト」と称され、情報セキュリティの向上を目的としている。このプロジェクトでは、さまざまな暗号アルゴリズムの安全性を評価し、有効な暗号方式を推奨することで、政府や民間企業に対し安全なシステムの構築を支援している。特に、国内の情報システムに適した暗号技術の選定を行い、標準化を促進する役割も果たしているため、情報セキュリティの基盤となる重要なものとなっている。","explanationZh":"日本用于评估密码技术安全性并推动适当采用密码算法的政府相关项目／机制。其工作包括对密码算法进行安全性和实现性评估，并发布面向电子政府等用途的推荐密码清单。CRYPTREC的结果可作为选择密码算法和制定密码政策的重要参考。"},{"id":"t0263","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"JPCERTコーディネーションセンター","termZh":"JPCERT协调中心（JPCERT/CC）","english":"JPCERT Coordination Center","reading":"じぇいぴーさーとこーでぃねーしょんせんたー","breadcrumb":"","explanationJa":"日本におけるコンピュータセキュリティインシデント対応の中核を担う組織である。このセンターは、サイバー攻撃や情報漏洩といったセキュリティインシデントの発生時に、事故の調査や対応策の支援を行うことを目的として設立された。具体的には、インターネット上の脅威に対する情報提供や、関連する機関との連携を図るなど、国内外のセキュリティの向上に寄与している。また、JPCERTは教育や啓発活動も行い、企業や個人がセキュリティ対策を強化するためのガイダンスを提供している。これにより、安全なインターネット環境の実現に向けた重要な役割を果たしている。","explanationZh":"日本的计算机安全事件协调机构，负责接收和协调安全事件、分析互联网威胁、发布预警和技术信息，并与国内外CSIRT及相关机构开展协作。其主要作用不是替组织直接承担所有响应，而是通过协调、信息共享和支援提高整体事件应对能力。"},{"id":"t0264","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"J-CSIP","termZh":"J-CSIP（网络安全信息共享伙伴关系）","english":"J-Cyber Security Information Sharing Initiative","reading":"じぇいしっぷ","breadcrumb":"","explanationJa":"日本におけるサイバーセキュリティの向上を目的とした情報共有の仕組みである。正式名称は「サイバー情報共有イニシアティブ」。企業や組織がサイバー攻撃に関する情報を共有し、相互に防御力を高めることを目指している。具体的には、攻撃手法やその対策、脆弱性情報などを共有することで、早期の発見や対処が可能となる。J-CSIPには、政府機関や民間企業が参加しており、情報交換を通じて全体のセキュリティ強化を図ることが重要な役割である。この取り組みは、サイバーリスクの軽減に寄与し、安心・安全なインターネット環境の実現を目指している。","explanationZh":"由日本相关机构推动的网络攻击信息共享机制，旨在让参与企业和组织共享定向攻击等威胁信息、攻击手法和应对经验。通过对敏感信息进行适当处理后共享，可帮助参与者更早发现类似攻击并强化防护。"},{"id":"t0265","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"JVN","termZh":"JVN（日本脆弱性信息门户）","english":"Japan Vulnerability Notes","reading":"じぇいぶいえぬ","breadcrumb":"","explanationJa":"日本における脆弱性情報を提供するためのサイトである。ソフトウェアやシステムの安全性を高めるために、開発者や利用者に向けて脆弱性の情報を迅速に提供する役割を果たしている。具体的には、新たに発見された脆弱性の詳細や対策方法を公表し、利用者が適切な対策を講じられるよう支援している。また、JVNは国や企業などの情報セキュリティ機関と連携し、統一された情報を提供することで、広範囲にわたる安全対策の推進を図っている。このような取り組みにより、社会全体の情報セキュリティを強化することが期待されている。","explanationZh":"日本用于公开软件和产品漏洞信息及相应对策的脆弱性信息门户。它向开发者、管理员和用户提供漏洞概要、受影响产品、修复或规避措施等信息，并与日本的漏洞协调和披露机制相配合。利用JVN可及时掌握已知漏洞并采取更新或缓解措施。"},{"id":"t0266","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"TrustedWeb推進協議会","termZh":"Trusted Web推进协议会","english":"Trusted Web Advancement Council","reading":"とらすてっどうぇぶすいしんきょうぎかい","breadcrumb":"","explanationJa":"インターネット上での信頼性と安全性を向上させるための活動を行う組織である。この協議会は、Web技術の普及や標準化を進めることを目的としており、主に信頼できるコンテンツの提供やユーザーのプライバシー保護に焦点を当てている。具体的には、Webサイトが安全に運営されるためのガイドラインやベストプラクティスを策定し、広く普及させることで、悪意ある攻撃からユーザーを守る役割を果たしている。また、協議会には、企業や開発者が参加しており、最新の技術的な課題に対する対応策を共有し、信頼性の高いWeb環境の実現を目指している。","explanationZh":"日本推动Trusted Web相关理念、技术和社会实施的组织性机制名称。其关注在数字社会中提高身份、数据和交易信息的可验证性与信任，同时兼顾隐私和数据治理。属于日本特有项目名称，复习时宜保留原文并理解其“构建可信数字空间”的目标。"},{"id":"t0267","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"コンピュータ不正アクセス届出制度","termZh":"计算机未授权访问报告制度","english":"Computer Unauthorized Access Reporting System","reading":"こんぴゅーたふせいあくせすとどけでせいど","breadcrumb":"","explanationJa":"情報セキュリティを強化するために設けられた制度である。この制度では、コンピュータシステムへの不正なアクセスが発覚した際、その旨を関連する機関に届け出ることが義務付けられている。具体的には、企業や組織は不正アクセスを検知した場合、所定の手続きに従い、法に基づいて報告を行うことで、被害の拡大を防ぎ、情報の保護を図ることができる。この制度は、利用者や顧客の信頼を維持し、社会全体の情報セキュリティ意識を高めるためにも重要な役割を果たしている。","explanationZh":"日本针对计算机不正访问相关事件设置的报告／届出机制，用于收集事件情况、分析趋势并推动预防和再发防止。组织发现相关事件时，可按照规定向指定机构提交信息。复习时要注意其属于日本制度性术语，具体是否构成法定义务应以相应制度规定为准。"},{"id":"t0268","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"コンピュータウイルス届出制度","termZh":"计算机病毒报告制度","english":"Computer Virus Notification System","reading":"こんぴゅーたういるすとどけでせいど","breadcrumb":"","explanationJa":"情報セキュリティの向上を目的として、コンピュータウイルスに感染した場合やウイルスを発見した際に、その情報を正式に報告するための制度である。この制度により、ウイルスの踏査や解析が行われ、被害の拡大を防ぐための対策が迅速に講じられることが可能となる。例えば、企業や組織がウイルスに感染した場合、専門機関に届け出ることで、その情報が共有され、他の組織も同様の被害に遭うことを避けることができる。また、この制度は我が国の情報セキュリティ対策強化の一環として推進されており、ユーザーやシステム管理者にとって重要な役割を果たしている。","explanationZh":"日本用于收集计算机病毒发现、感染和受害情况的届出机制。通过集中接收和分析报告，可以掌握恶意软件趋势、发布警示并向社会提供防范信息。企业和系统管理员可借此共享经验，帮助降低同类感染的扩散风险。"},{"id":"t0269","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"ソフトウェア等の脆弱性関連情報に関する届出制度","termZh":"软件等脆弱性相关信息届出制度","english":"Vulnerability Disclosure System for Software","reading":"そふとうぇあとうのぜいじゃくせいかんれんじょうほうにかんするとどけでせいど","breadcrumb":"","explanationJa":"ソフトウェアやシステムに存在する弱点や欠陥を迅速に報告し、適切な対策を講じるための仕組みである。この制度は、発見された脆弱性を開発者や運営者が適切に対処できるようにするため、報告方法や手順を明確に定めている。具体的には、脆弱性を発見した研究者やユーザーが、関係者に安全に情報を通知し、その後の修正や改善に役立てることができる。この取り組みによって、セキュリティ上のリスクを軽減し、より安全なソフトウェア環境の構築が促進されることを目的としている。","explanationZh":"日本用于安全接收和协调软件、网站等漏洞信息的报告制度。发现者按照规定提交漏洞后，由相关协调机构与产品开发者或网站运营者沟通确认、修复和适当披露，以在公开漏洞细节与保护用户之间取得平衡。该机制是协调漏洞披露的重要组成部分。"},{"id":"t0270","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティサービス基準","termZh":"信息安全服务标准","english":"Information Security Service Standards","reading":"じょうほうせきゅりてぃさーびすきじゅん","breadcrumb":"","explanationJa":"情報の保護に関するガイドラインや要求事項をまとめたものである。これらの基準は、情報の機密性、整合性、可用性を維持するために設定されており、企業や組織が情報セキュリティを管理する上での指針となる。例えば、データの保存や通信の際に適用される暗号化技術やアクセス制御のルールが含まれる。また、これらの基準を遵守することで、情報漏洩やサイバー攻撃に対して対策を講じることができ、信頼性の高いサービスの提供が可能となる。安全な情報環境の確保に不可欠な要素である。","explanationZh":"日本用于评价特定信息安全服务质量和可靠性的标准框架，对服务提供者的技术能力、管理体制和服务实施等提出要求。其目的是帮助用户选择具备一定能力和可信度的安全服务，并推动安全服务市场规范化。"},{"id":"t0271","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティサービス審査登録制度","termZh":"信息安全服务审查登记制度","english":"Information Security Service Auditing and Registration System","reading":"じょうほうせきゅりてぃさーびすしんさとうろくせいど","breadcrumb":"","explanationJa":"情報セキュリティに関するサービスを提供する企業や組織を対象とした、品質や信頼性を保証するための制度である。この制度では、サービスの運営状況やリスク管理の体制が審査され、一定の基準を満たすことで公式に登録される。例えば、データセンターやクラウドサービスを運営する企業が、この制度によって審査を受けることで、顧客に対して自身のサービスの安全性を証明することができる。これは、情報漏えいやサイバー攻撃のリスクを軽減し、ユーザーの安心感を高めるために非常に重要である。","explanationZh":"日本针对符合信息安全服务相关标准的服务开展审查并进行登记的制度。服务提供者接受规定的审查，满足要求后可被登记，从而向用户表明其服务在人员、技术、管理和运营等方面达到相应基准。该制度用于提高安全服务选择的透明度和可信度。"},{"id":"t0272","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティサービス基準適合サービスリスト","termZh":"信息安全服务标准符合服务清单","english":"Information Security Service Compliance List","reading":"じょうほうせきゅりてぃさーびすきじゅんてきごうさーびすりすと","breadcrumb":"","explanationJa":"特定の情報セキュリティ基準に準拠したサービスをまとめたリストである。このリストには、各サービスがどのようなセキュリティ基準を満たしているかが示され、利用者が信頼できるサービスを選定するための参考となる。例えば、クラウドサービスやデータ保護サービスが含まれることが多く、これらのサービスが特定の基準に適合していることを証明する役割を果たす。このリストを活用することで、企業は自らの情報セキュリティ対策を強化し、顧客や取引先からの信頼を得ることができる。","explanationZh":"汇总已被确认符合日本信息安全服务相关基准的服务名单。用户可以通过该清单了解哪些服务经过相应审查或确认，并作为采购和选择安全服务时的参考。列入清单并不意味着不存在任何风险，仍应结合自身需求和风险进行评估。"},{"id":"t0273","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"ISMAP","termZh":"ISMAP（政府信息系统云服务安全评估制度）","english":"Information System Security Management and Assessment Program","reading":"いずまっぷ","breadcrumb":"","explanationJa":"情報システムのセキュリティ管理と評価プログラムを指す。これは、情報セキュリティの適切な管理と評価を行うための枠組みであり、組織がどのようにセキュリティ対策を講じるべきかの指針を提供するものである。ISMAPを活用することで、リスクの特定や脅威の分析が行われ、効果的な対策を導入することが促進される。特に、組織の業務における情報の保護を強化するために重要であり、国や地域によっては法的な要件としても位置付けられることがある。こうした管理プログラムは、情報の安全性を高め、インシデントの発生を未然に防ぐ役割を果たしている。","explanationZh":"日本政府用于评估和登记政府信息系统所使用云服务安全性的制度。它依据规定的安全要求对云服务提供者的管理措施进行评估，并形成可供政府机关选择的服务清单。其目的在于统一政府采用云服务时的安全评价框架并降低采购风险。"},{"id":"t0274","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティ早期警戒パートナーシップ","termZh":"信息安全早期预警伙伴关系","english":"Information Security Early Warning Partnership","reading":"じょうほうせきゅりてぃそうきけいかいぱーとなーしっぷ","breadcrumb":"","explanationJa":"組織や団体が協力してサイバー攻撃や情報漏洩などのリスクを早期に発見し、対応策を講じるための枠組みである。このパートナーシップは、情報共有や技術支援を通じて、参加者間での知見を高め、より効果的なセキュリティ対策を講じることを目的としている。例えば、セキュリティインシデントの情報をリアルタイムで共有することで、各組織が迅速に対応できるようになる。このように、協力体制を築くことで、全体のセキュリティが向上し、個々の組織だけでは難しい対策も可能になる。","explanationZh":"日本用于协调软件和网站漏洞发现、报告、修复与披露的协作框架。漏洞发现者、协调机构、产品开发者和网站运营者按照既定流程共享必要信息，在降低被恶意利用风险的同时推动尽快修复。该机制是日本协调漏洞披露体系的重要组成部分。"},{"id":"t0275","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"J-CRAT","termZh":"J-CRAT（网络救援队）","english":"Cyber Rescue and Advice Team against targeted attack of Japan","reading":"じぇいしーらっと","breadcrumb":"","explanationJa":"日本におけるサイバー攻撃からの救済とアドバイスを提供する専門的な情報セキュリティ組織である。主に、企業や政府機関に対して、サイバー攻撃に対する防御策や被害対応を支援し、セキュリティ意識の向上を図ることを目的としている。具体的には、発生したサイバー攻撃の分析や、攻撃者の手口に関する情報提供、必要な対策の策定を行う。また、定期的に研修やセミナーを開催し、参加者が最新のセキュリティ脅威に対する知識を身につけられるようサポートしている。このような活動を通じて、J-CRATはサイバーセキュリティの強化と安全なデジタル社会の実現に寄与している。","explanationZh":"日本面向遭受定向网络攻击等组织提供分析、处置建议和技术支援的专业支援机制。其工作可包括确认入侵情况、分析恶意软件和攻击路径、提出隔离与恢复建议，并帮助受害组织提高后续防御能力。重点在于对严重攻击受害组织实施现场或专项支援。"},{"id":"t0276","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"NOTICE","termZh":"NOTICE（IoT设备调查与注意提醒计划）","english":"National Operation Towards IoT Clean Environment","reading":"のーてぃす","breadcrumb":"","explanationJa":"IoT（モノのインターネット）環境の安全性と清浄性を向上させることを目的とした国家的な取り組みを表す組織である。主に、IoT機器のセキュリティ強化や、データの保護を推進するための活動を行っている。この組織は、さまざまな業界の関係者と連携し、最新の脅威やリスクについての情報を共有することを重視している。例えば、IoTデバイスに対するサイバー攻撃の監視や、セキュリティ対策の普及活動を通じて、より安全なネットワーク環境の構築を目指している。これにより、利用者が安心してIoT技術を活用できる社会の実現を促進することが期待されている。","explanationZh":"日本针对存在弱口令等安全风险的IoT设备开展调查并推动用户采取安全措施的国家级项目名称。通过识别可能被恶意软件利用的设备并经由互联网服务提供商等渠道提醒使用者，可减少IoT设备被纳入僵尸网络的风险。应将其理解为日本IoT安全治理措施，而不是一般意义上的组织名称。"},{"id":"t0277","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"SECURITY ACTION","termZh":"SECURITY ACTION","english":"SECURITY ACTION","reading":"せきゅりてぃあくしょん","breadcrumb":"","explanationJa":"中小企業が自ら情報セキュリティの対策に取り組むことを宣言する制度である。この取り組みは、情報処理推進機構（IPA）によって推進されており、企業が安全な運営を行うために必要なセキュリティ対策を実施していることを示すものである。企業がこの宣言を行うことで、顧客や取引先に対して信頼性をアピールし、情報漏洩やサイバー攻撃のリスクを低減することが期待される。具体的には、企業はセキュリティポリシーの策定や教育・訓練の実施、システムの保護などの取り組みを行う必要がある。このように、SELF-DECLARATION SYSTEMは、情報セキュリティの向上と中小企業の競争力強化を目指している。","explanationZh":"日本IPA推动的中小企业信息安全自我宣言制度。企业根据规定的安全实践开展自我检查和改进，并通过不同阶段的宣言表明其主动采取信息安全措施。该制度旨在降低中小企业开始安全管理的门槛，并提升供应链整体安全意识。"},{"id":"t0278","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"ISAC","termZh":"信息共享与分析中心（ISAC）","english":"Information Sharing and Analysis Center","reading":"あいざっく","breadcrumb":"","explanationJa":"情報セキュリティに関わる組織であり、サイバーセキュリティに関する情報を共有し、分析するためのセンターである。特定の業界や分野に属する企業や機関が集まり、脅威情報や攻撃の兆候を共有することで、より強固なセキュリティ体制を構築することを目的としている。具体的には、サイバー攻撃の事例や防御手法を共有することにより、参加者全体のリスクを低減し、迅速な対応が可能となる。また、政府機関や他のセキュリティ関連組織とも連携し、広範な情報共有を促進する役割を果たしている。","explanationZh":"按行业或领域组织起来的网络安全信息共享和分析机构。参与成员交换威胁情报、攻击迹象、漏洞和应对经验，并通过联合分析提高整个行业的预警和防御能力。ISAC通常还会与政府、CSIRT和其他安全组织建立协作关系。"},{"id":"t0279","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"再発防止のための提言","termZh":"防止再发的建议","english":"Recommendations for Preventing Recurrence","reading":"さいはつぼうしのためのていげん","breadcrumb":"","explanationJa":"情報セキュリティに関連する問題が再び起きないようにするための対策や方針を示すものである。この提言は、過去のインシデントや問題を分析し、それに基づいて改善策を策定することが求められる。例えば、セキュリティ侵害が発生した場合、原因を明らかにし、その経験をもとにセキュリティポリシーの見直しや社員教育の強化を行うことが一般的である。また、定期的なレビューや監査を行うことで、提言した対策が実施されているかを確認し、継続的な改善を図ることが重要である。このように、組織のセキュリティレベルを向上させるための重要なステップである。","explanationZh":"在安全事件或问题调查结束后，根据根因、影响和处置过程提出的再发防止措施。内容可包括制度修订、技术控制强化、流程改进、培训、监控和责任调整等，并应指定负责人、期限和验证方法。后续通过审计或复查确认措施是否有效，形成持续改进闭环。"},{"id":"t0280","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"情報セキュリティに関する啓発活動","termZh":"信息安全宣传与意识提升活动","english":"Information Security Awareness Activities","reading":"じょうほうせきゅりてぃにかんするけいはつかつどう","breadcrumb":"","explanationJa":"企業や組織が情報の安全を守るために、従業員や一般の人々に対して行う教育や訓練のことを指す。例えば、フィッシング詐欺やウイルスの危険性についての講習会を実施し、正しい対処方法や安全なインターネットの利用法を伝えることで、情報セキュリティの意識を高めることが目的である。このような活動は、サイバー攻撃が増加する中で特に重要となり、従業員一人ひとりが情報を守る意識を持つことで、組織全体のセキュリティを強化することに寄与する。また、定期的なワークショップや情報誌の配布を通じて、最新の脅威情報や対策を共有することも行われている。","explanationZh":"面向员工、客户或公众开展的信息安全教育、宣传和演练活动，目的是提高识别风险和采取正确行为的能力。形式可包括钓鱼演练、培训课程、宣传材料、讲座和定期安全提醒。持续的意识提升能够减少人为错误和社会工程攻击成功率，并支持组织安全文化建设。"},{"id":"t0281","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"コンピュータウイルス対策基準","termZh":"计算机病毒防范标准","english":"Computer Virus Protection Standards","reading":"こんぴゅーたういるすたいさくきじゅん","breadcrumb":"","explanationJa":"ウイルスからコンピュータシステムを保護するためのガイドラインや基準を指す。これらの基準は、効果的なウイルス対策ソフトウェアの導入や運用方法に関する具体的な指針を提供することを目的としている。例えば、定期的なウイルススキャンや、最新のウイルス定義ファイルの更新、セキュリティパッチの適用が含まれる。これにより、システムの脆弱性を低減させ、重要なデータを守ることが可能となる。特に、企業や組織ではこれらの基準を遵守することで、セキュリティリスクを減少させ、業務の継続性を確保することが期待されている。","explanationZh":"规定组织预防、发现和处置计算机病毒等恶意软件时应采取的基本措施和管理要求。通常包括防病毒软件部署、更新、扫描、感染报告、隔离、恢复和用户教育等内容，用于降低病毒感染及扩散造成的损害。"},{"id":"t0282","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"コンピュータ不正アクセス対策基準","termZh":"计算机非法访问对策标准","english":"Computer Security Incident Handling Standards","reading":"こんぴゅーたふせいあくせすたいさくきじゅん","breadcrumb":"","explanationJa":"情報システムへの不正アクセスを防ぐための指針やルールを定めたものである。この基準は、情報セキュリティを確保するために組織が採用すべき手段やプロセスを提供する。具体的には、不正アクセスの検知、対応、調査の方法や、セキュリティ対策の実施に関連する手順が含まれている。これにより、情報システムを守り、データの漏洩や損失を防ぐことが可能になるため、企業や組織にとって重要な基準となっている。また、最新の脅威や攻撃手法に対応できるよう、定期的な見直しや更新が求められる。","explanationZh":"针对未授权访问等安全事件规定预防、检测、报告和处置要求的标准。通过身份认证、访问控制、日志监控、事件响应和再发防止等措施，降低系统被非法侵入和滥用的风险。"},{"id":"t0283","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"ソフトウェア製品等の脆弱性関連情報に関する取扱規程","termZh":"软件产品等脆弱性相关信息处理规定","english":"Regulations on Handling Vulnerability Information Related to Software Products","reading":"そふとうえあせいひんとうのぜいじゃくせいかんれんじょうほうにかんするとりあつかいきてい","breadcrumb":"","explanationJa":"ソフトウエア製品等の脆弱性関連情報に関する取扱規程とは、ソフトウエアに存在するセキュリティ上の欠陥や脆弱性についての情報をどのように管理し、共有すべきかを定めたガイドラインである。この規程は、脆弱性が悪用されるリスクを減少させるために重要であり、企業や開発者が迅速かつ適切に対応するための基準を提供する。具体的には、情報の収集、分析、評価、公開のプロセスについて詳細に規定されており、関係者間での情報共有の促進を図ることが目的である。これは、ソフトウエアの安全性を高め、顧客の信頼を守るために欠かせない手順といえる。","explanationZh":"规定软件或网站漏洞信息在发现、报告、接收、协调、修复和披露过程中的处理规则。其目的在于避免漏洞细节被过早公开而遭利用，同时推动开发者及时修复并向用户提供安全信息。"},{"id":"t0284","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"政府機関等の情報セキュリティ対策のための統一基準群","termZh":"政府机关等信息安全对策统一标准体系","english":"Unified Standards for Information Security Measures of Government Agencies","reading":"せいふきかんとうのじょうほうせきゅりてぃたいさくのためのとういつきじゅんぐん","breadcrumb":"","explanationJa":"政府や公的機関が情報を安全に管理・保護するために定められた基準のことである。この基準群は、情報漏洩やサイバー攻撃から重要なデータを守るために設計されている。具体的には、アクセス管理やデータ暗号化、インシデント対応の手順などが含まれ、不正アクセスや情報の改ざんを防止するための指針を提供する。統一基準に従うことで、全国の政府機関が一定のセキュリティレベルを維持し、国民の信頼を得ることが目的である。","explanationZh":"日本政府为各政府机关和相关机构制定的统一信息安全要求体系。它从治理、人员、信息资产、系统、网络和事件应对等方面规定基准，以统一政府信息系统的安全管理水平。"},{"id":"t0285","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"サイバーセキュリティ経営ガイドライン","termZh":"网络安全经营指南","english":"Cybersecurity Management Guidelines","reading":"さいばーせきゅりてぃけいえいがいどらいん","breadcrumb":"","explanationJa":"企業や組織が情報セキュリティを適切に管理するための指針である。このガイドラインは、サイバー攻撃や情報漏洩からの保護を目的として、リスクの評価や対策の実施方法を示している。例えば、社員の教育や技術的対策の導入によって、セキュリティ意識を高めることが求められる。また、ガイドラインは、企業が自らの状況に応じてセキュリティ対策を強化するためのフレームワークを提供し、持続的な改善を促進する役割も果たしている。これにより、組織は外部の脅威に対抗する力を向上させることが可能となる。","explanationZh":"面向企业经营层的网络安全管理指南，强调管理者应把网络安全作为经营风险进行治理。内容通常包括领导责任、风险识别、资源投入、供应链安全、事件响应和持续改进等，帮助企业将安全纳入经营战略。"},{"id":"t0286","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"中小企業の情報セキュリティ対策ガイドライン","termZh":"中小企业信息安全对策指南","english":"Guidelines for Information Security Measures in Small and Medium-sized Enterprises","reading":"ちゅうしょうきぎょうのじょうほうせきゅりてぃたいさくがいどらいん","breadcrumb":"","explanationJa":"中小企業が情報セキュリティを効果的に管理するための指針である。このガイドラインには、企業が直面する特有のリスクや脅威を考慮し、実践的なセキュリティ対策の導入方法が示されている。具体的な内容には、パスワード管理やデータの暗号化、従業員の教育などが含まれ、安全なネットワーク環境を維持するための手法が提案されている。また、これらの対策を実施することで、情報漏洩やサイバー攻撃から企業資産を守ることが目的であり、信頼性の向上にも寄与している。","explanationZh":"面向中小企业提供的实用信息安全指南，帮助资源有限的组织识别重要资产和主要威胁，并逐步落实基本安全措施。内容通常涵盖账号、终端、备份、恶意软件、员工教育和事故应对等。"},{"id":"t0287","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"IoTセキュリティガイドライン","termZh":"IoT安全指南","english":"IoT Security Guidelines","reading":"あいおーてぃーせきゅりてぃがいどらいん","breadcrumb":"","explanationJa":"インターネットに接続されるデバイス（IoT機器）の安全性を確保するための指針である。これらのガイドラインは、デバイスの設計や運用において、脆弱性を減少させ、データの保護を強化することを目的としている。具体的には、強固なパスワードの使用、ソフトウェアの定期的な更新、デバイスのアクセス管理の徹底などが推奨されている。これにより、IoTデバイスが悪意のある攻撃から守られ、利用者のプライバシーや機密情報を安全に保つことが可能となる。IoTの普及が進む中で、このガイドラインの重要性はますます高まっている。","explanationZh":"针对IoT设备和服务在设计、开发、部署、运行和废弃阶段的安全风险提出管理和技术要求。重点包括默认口令、更新机制、通信保护、身份认证、漏洞管理以及数据和隐私保护。"},{"id":"t0288","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"サイバー・フィジカル・セキュリティ対策フレームワーク","termZh":"网络物理安全对策框架","english":"Cyber-Physical Security Countermeasures Framework","reading":"さいばー・ふぃじかる・せきゅりてぃたいさくふれーむわーく","breadcrumb":"","explanationJa":"物理的なシステムとサイバー空間が連携している環境において、セキュリティを強化するための枠組みである。このフレームワークは、情報システムと物理的インフラストラクチャーをいかに保護するかを体系的に示す。具体的には、セキュリティリスクの評価、脅威分析、対策導入のプロセスが含まれ、組織がサイバー攻撃や物理的侵入から資産を守るための指針となる。たとえば、自動車産業においては、車両の電子制御と物理的な部分が連携していることから、サイバー・フィジカル・セキュリティの重要性が増している。このフレームワークを適切に活用することで、リスク管理が強化され、より安全な運用が可能になる。","explanationZh":"面向网络空间与现实物理空间高度融合的产业和供应链安全框架。它从组织、人员、设备、数据和供应链等多层面识别风险并设置控制，以防止网络攻击对生产、物流和社会基础设施造成现实影响。"},{"id":"t0289","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"金融機関等コンピュータシステムの安全対策基準・解説書","termZh":"金融机构等计算机系统安全对策标准及解说","english":"Safety Standards for Computer Systems in Financial Institutions","reading":"きんゆうきかんとうこんぴゅーたしすてむのあんぜんたいさくきじゅん・かいせつしょ","breadcrumb":"","explanationJa":"金融機関が情報システムを安全に運用するための指針や基準をまとめた文書である。これらの基準は、不正アクセスやデータの漏洩を防ぐために必要な措置を具体的に示しており、各機関が遵守すべき要求事項が含まれている。たとえば、システムの脆弱性を特定して対策を講じることや、情報セキュリティ教育を従業員に実施することが推奨される。また、これにより信頼性や安全性の向上を図り、利用者の情報を守る重要な役割を果たす。このような基準を遵守することで、金融機関は顧客に安心してサービスを提供できるようになる。","explanationZh":"面向金融机构信息系统的安全与可靠性要求及实施说明。通常涵盖系统规划、开发、运行、灾备、访问控制、网络安全和外包管理等，是金融系统风险管理的重要参考。"},{"id":"t0290","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"PCI DSS","termZh":"支付卡行业数据安全标准（PCI DSS）","english":"Payment Card Industry Data Security Standard","reading":"ぴーしーあいでぃーえすえす","breadcrumb":"","explanationJa":"クレジットカード情報を取り扱う企業が守るべきセキュリティ基準のことである。この基準は、カード情報の漏洩を防ぎ、顧客の個人情報を安全に保護することを目的としている。具体的には、データの暗号化、アクセス管理、定期的なセキュリティテストなどが含まれ、これを遵守することで悪意のある攻撃から情報を守ることができる。多くの企業は、PCI DSSに準拠することで顧客からの信頼を得やすく、セキュリティリスクを低減することができるため、重要な基準として広く認識されている。","explanationZh":"支付卡行业为保护持卡人数据制定的安全标准。适用于存储、处理或传输支付卡数据的组织，要求实施网络防护、访问控制、加密、漏洞管理、日志监控和安全测试等措施，以降低支付数据泄露风险。"},{"id":"t0291","chapterId":"c02","chapterJa":"情報セキュリティ管理","chapterZh":"信息安全管理","termJa":"サイバーセキュリティフレームワーク","termZh":"网络安全框架","english":"Cybersecurity Framework","reading":"","breadcrumb":"","explanationJa":"組織がサイバーセキュリティを効果的に管理し、リスクを特定・軽減するためのガイドラインである。このフレームワークは、リスク管理のベストプラクティスを提供し、組織が自らのセキュリティ状況を評価し、改善するための基準を示すものである。たとえば、フレームワークは検出、対応、回復などの機能を含み、組織のニーズに応じた対策を実施することができる。特に情報セキュリティに関する国際的な基準を基にしており、企業や政府機関など幅広い組織で採用され、サイバー攻撃からの防御力を高めることを目的としている。","explanationZh":"用于组织识别、评估和管理网络安全风险的结构化框架。通常通过一组核心功能、类别和实践，把资产识别、防护、检测、响应、恢复以及治理等活动整合起来，便于组织按风险持续改进。"},{"id":"t0292","chapterId":"c03","chapterJa":"セキュリティ技術評価","chapterZh":"安全技术评估","termJa":"CVSS","termZh":"通用漏洞评分系统（CVSS）","english":"Common Vulnerability Scoring System","reading":"しーぶいえすえす","breadcrumb":"","explanationJa":"ソフトウェアやシステムに存在する脆弱性を評価し、リスクの度合いを数値で示すための基準である。この基準により、脆弱性の深刻度を一貫して評価し、比較することが可能となる。0から10までのスコアを用いて、脆弱性の影響や悪用の難易度を示す。たとえば、高いスコアが付与された脆弱性は、迅速な対処が必要であることを示す。これにより、組織は限られたリソースの中で、最も重要な脆弱性の修正や対策を優先することができる。セキュリティチームが評価や報告を行う際に利用され、情報の共有や意思決定を助ける役割も果たしている。","explanationZh":"CVSS（通用漏洞评分系统）是一个用于评估信息系统漏洞严重程度的通用框架。它采用独立于特定供应商的统一评价方法，因此可以在相同标准下对不同漏洞的严重程度进行定量比较。CVSS从三个评价指标组对漏洞进行评估，最终以0.0～10.0的分数表示漏洞严重程度，分数越高表示漏洞越严重，并可根据计算出的分数对严重程度进行分类。\n\n• 基本评估标准（基础指标）\n用于评估漏洞固有严重程度的指标。它根据对机密性、完整性和可用性的影响，以及实施攻击所需的条件等因素计算。该指标本身不会随着时间推移或不同用户环境而改变，通常由漏洞披露方、产品供应商等用于表示漏洞本身的固有严重程度。\n\n• 当前状态评估标准（时间指标）\n用于评估漏洞在当前时点严重程度的指标。它会考虑漏洞被实际利用的可能性、可用的修复或缓解措施以及随时间变化的状态等因素，因此其评分可能随着漏洞利用状况和应对措施的变化而变化。该指标可用于表示漏洞当前的风险状态。\n\n• 环境指标\n用于结合具体用户或组织环境，评估漏洞最终严重程度的指标。它会考虑该漏洞在实际环境中的影响范围、潜在的二次损害以及组织自身安全需求等因素，因此不同用户得到的评价可能不同。环境指标可作为用户确定漏洞处置优先级和制定应对措施的重要依据。"},{"id":"t0293","chapterId":"c03","chapterJa":"セキュリティ技術評価","chapterZh":"安全技术评估","termJa":"脆弱性診断","termZh":"脆弱性评估／漏洞扫描","english":"Vulnerability Assessment","reading":"ぜいじゃくせいしんだん","breadcrumb":"","explanationJa":"情報システムやネットワークに存在するセキュリティ上の脆弱性を特定し、評価するプロセスである。この診断により、悪意のある攻撃者が利用する可能性のある弱点を洗い出し、適切な対策を講じるための基礎情報を提供する。具体的には、システムの設定ミスや未修正のソフトウェア、パスワードの強度不足などが対象となる。脆弱性診断は定期的に実施することが推奨されており、これにより企業や組織はセキュリティリスクを低減させ、生産性の向上を図ることができる。また、診断結果に基づいて、適切な修正や対策を行うことで、情報資産の保護と信頼性の向上が期待される。","explanationZh":"通过自动化工具和人工分析检查系统、网络或应用中已知漏洞、错误配置和薄弱点的活动。其目的在于发现风险并提出修复建议，通常不以实际突破系统为主要目标。"},{"id":"t0294","chapterId":"c03","chapterJa":"セキュリティ技術評価","chapterZh":"安全技术评估","termJa":"ペネトレーションテスト","termZh":"渗透测试","english":"Penetration Testing","reading":"","breadcrumb":"","explanationJa":"システムやネットワークのセキュリティを評価するための手法である。このテストでは、実際の攻撃者の視点から侵入を試みることで、脆弱性や弱点を発見し、それに対する対策を検討する。例えば、企業のWebサイトに対するペネトレーションテストでは、ハッカーが不正にアクセスできるかどうかを確認し、もし問題があればその修正方法を提案する。これにより、情報漏洩やサービス停止といったリスクを低減することが可能である。定期的に実施することが望まれ、サイバー攻撃に対する防御力を高める重要な手段となっている。","explanationZh":"在授权范围内模拟攻击者手法，实际验证系统、网络或应用是否能被利用并评估潜在影响的安全测试。相比一般漏洞扫描，渗透测试更强调漏洞利用链和真实攻击路径，但必须严格控制范围和风险。"},{"id":"t0295","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"組織における内部不正防止ガイドライン","termZh":"组织内部不正防止指南","english":"Internal Fraud Prevention Guidelines by IPA","reading":"そしきにおけるないぶふせいぼうしがいどらいん","breadcrumb":"","explanationJa":"組織における内部不正防止ガイドライン（IPA策定）とは、情報処理推進機構（IPA）が策定した、企業や団体が内部の不正行為を防ぐために必要な指針である。このガイドラインは、人的セキュリティ対策の一環として、従業員による不正行為を識別し、未然に防ぐための具体的な手法や取り組みを示している。具体的には、組織内の権限管理、監査体制の強化、従業員教育の充実などが含まれ、これにより不正のリスクを軽減することを目的としている。また、定期的な見直しや改善も重要であり、組織の状況に応じて柔軟に対応することが求められる。これにより、信頼性の高い業務環境を実現し、各種トラブルを防止することができる。","explanationZh":"用于帮助组织预防员工、委托人员等内部人员实施信息窃取、滥用权限和破坏行为的管理指南。通常从治理、权限、日志、物理管理、人员管理和离职管理等方面提出措施，以降低内部威胁。"},{"id":"t0296","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"情報セキュリティ啓発","termZh":"信息安全意识提升","english":"Information Security Awareness","reading":"じょうほうせきゅりてぃけいはつ","breadcrumb":"","explanationJa":"組織や個人が情報セキュリティに対する認識を高めるための活動である。この活動には、教育プログラムの実施や関係資料の配布、メディアを活用した情報提供が含まれる。具体的には、セキュリティリスクや対策に関する講習会を開いたり、注意喚起のポスターを掲示したりすることが考えられる。こうした取り組みは、情報漏えいやサイバー攻撃から自身や組織を守るために非常に重要である。適切な知識を持つことで、従業員は日常的に発生する脅威に対する理解を深め、無意識のうちに情報を守る行動を取れるようになる。情報セキュリティの向上は、組織全体の安全性を確保するためにも欠かせない要素である。","explanationZh":"通过宣传、教育和持续提醒，使人员理解信息安全风险、组织规则和自身责任的活动。其目标是促使员工形成安全行为习惯，例如识别钓鱼、保护密码、及时报告异常，而不仅是掌握知识。"},{"id":"t0297","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"情報セキュリティ訓練","termZh":"信息安全训练","english":"Information Security Training","reading":"じょうほうせきゅりてぃくんれん","breadcrumb":"","explanationJa":"組織内の従業員に対して情報セキュリティに関する知識や対処法を教育するプロセスである。この訓練は、特に標的型メール攻撃への対策として重要であり、従業員は、疑わしいメールの識別や適切な対処方法を学ぶことになる。また、レッドチーム演習もこの訓練に含まれ、シミュレーションを通じて実際の攻撃に対する準備を整えることを目的としている。これにより、従業員は攻撃に対する脆弱性を理解し、実際に遭遇した際の対応力を高めることができる。人的セキュリティ対策は、技術的対策と合わせて、組織の全体的なセキュリティレベルを向上させるために不可欠である。","explanationZh":"通过演练和实践提高人员应对具体安全情景能力的活动。可包括钓鱼邮件演练、事件响应桌面推演、灾备演练等，用于验证流程、发现问题并提升实际处置能力。"},{"id":"t0298","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"認証情報の割当て及び管理","termZh":"认证信息的分配与管理","english":"Assignment and Management of Authentication Information","reading":"にんしょうじょうほうのわりあておよびかんり","breadcrumb":"","explanationJa":"システムやネットワークにアクセスする際の本人確認のための情報を適切に配布し、管理するプロセスである。この認証情報には、パスワードやユーザー名、生体情報などが含まれ、これらを安全に管理することによって不正アクセスを防ぐことができる。例えば、企業の情報システムでは、各社員に固有の認証情報が割り当てられ、その管理は厳格に行われるべきである。管理が不十分な場合、第三者が容易に不正にアクセスする恐れがあり、情報漏洩やデータ改ざんなどのリスクが高まる。そのため、定期的な見直しや更新、安全な保管方法を徹底することが重要である。","explanationZh":"对用户ID、密码、密钥、令牌等认证信息进行申请、分配、变更、保管、使用和废止的管理过程。应确保唯一性、保密性、及时回收和定期复核，防止共享账号、遗留账号和凭据泄露。"},{"id":"t0299","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"セキュリティクリアランス","termZh":"安全许可／安全审查（Security Clearance）","english":"Security Clearance","reading":"","breadcrumb":"","explanationJa":"特定の情報や場所にアクセスするために必要な許可を示すものである。主に政府機関や軍事関連の組織で使用され、個人が機密情報に触れることができるかどうかを判断するための基準となる。セキュリティクリアランスを得るためには、バックグラウンドチェックや信用調査が行われ、その結果に基づいて許可が与えられる。たとえば、軍事機密に関わる仕事に就く場合、その人物が過去に問題を起こしていないか、信頼できるかを評価するためのプロセスが必要であり、それがセキュリティクリアランスの目的である。このようにして、機密情報を守るためのセキュリティ対策が講じられる。","explanationZh":"依据人员背景、岗位需要和信息敏感程度，对个人是否可以接触特定秘密或敏感信息进行审查和授权的机制。其核心是“按需知悉”和适当授权，并配合持续管理与保密义务。"},{"id":"t0300","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"秘密保持契約・誓約書","termZh":"保密协议／保密承诺书","english":"Non-Disclosure Agreement","reading":"ひみつほじけいやく・せいやくしょ","breadcrumb":"","explanationJa":"当事者間で特定の情報を第三者に漏らさないことを約束する法的な契約である。この契約により、業務上知り得た機密情報や技術、ビジネスプランなどが保護される。例えば、企業が新製品の開発を行う際に、外部の専門家やパートナーと情報を共有する場合、秘密保持契約を結ぶことで、お互いの情報を守ることができる。この契約があることで、悪用や漏洩のリスクを軽減し、ビジネス活動の安全性が高まる。人材の流出や不正競争を防ぐために、広く用いられている重要な文書である。","explanationZh":"通过合同或书面承诺明确当事人对秘密信息负有保密、限定使用和防止泄露的义务。通常规定秘密范围、使用目的、保密期限、返还或销毁以及违约责任等，用于降低信息被擅自披露的风险。"},{"id":"t0301","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"クラッキング対策","termZh":"防破解措施","english":"Cracking Protection","reading":"くらっきんぐたいさく","breadcrumb":"","explanationJa":"不正アクセスやデータ盗取を防ぐために行うセキュリティ対策の一つである。クラッキングは、システムの脆弱性を悪用して無断でデータにアクセスする行為を指し、その対策には様々な手法が含まれる。具体的には、強力なパスワードの使用や、二段階認証の導入、定期的なソフトウェアのアップデート、侵入検知システムの設置などが挙げられる。これらの対策を講じることで、システムのセキュリティを強化し、重要な情報を保護することができる。特に、企業や個人が重要なデータを扱う場合には、クラッキング対策が不可欠であり、適切な対策を講じることで被害を未然に防ぐ効果が期待される。","explanationZh":"防止攻击者非法突破系统、绕过保护或获取敏感信息的综合措施。包括及时修补漏洞、强化认证、最小权限、网络隔离、日志监控和安全测试等，核心是减少可被利用的攻击面。"},{"id":"t0302","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"不正アクセス対策","termZh":"非法访问防范措施","english":"Unauthorized Access Prevention","reading":"ふせいあくせすたいさく","breadcrumb":"","explanationJa":"許可されていないユーザーがシステムやデータにアクセスすることを防ぐための手段や対策である。この対策は、企業や組織の情報を保護するために非常に重要で、情報漏洩やデータの改ざんを防止する役割を果たす。具体的な手段には、パスワード管理、アクセス制御、ファイアウォールの導入、侵入検知システムの利用が含まれる。これらの技術は、特定のユーザーにのみアクセスを許可し、不正なアクセス試行を監視・記録することで、セキュリティを強化する。また、セキュリティポリシーの設定や従業員教育も重要で、組織全体での意識向上が求められる。","explanationZh":"为防止未经授权人员登录或使用系统而实施的控制。典型措施包括多因素认证、强密码、访问权限最小化、账号锁定、网络访问控制、日志审计和异常检测等。"},{"id":"t0303","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"情報漏えい対策","termZh":"信息泄露防范措施","english":"Information Leakage Countermeasures","reading":"じょうほうろうえいたいさく","breadcrumb":"","explanationJa":"外部に漏れる可能性のある情報を守るために講じるすべての施策や対策を指す。情報漏えいは、企業や個人のプライバシーに重大な影響を与えるため、その防止が重要である。この対策には、データの暗号化やアクセス制御、不正アクセスの監視、従業員教育などが含まれる。例えば、機密データを外部に送信する際に暗号化を行うことで、万が一データが漏洩しても内容を保護することができる。また、定期的なセキュリティチェックや従業員への意識向上のための教育は、情報漏えいのリスクを大幅に軽減する。これらの対策を統合的に実施することで、情報を安全に管理し、信頼性を高めることが可能となる。","explanationZh":"用于防止机密、个人或其他敏感信息被意外或恶意泄露的管理和技术措施。可包括信息分类、最小权限、加密、DLP、外发审批、日志监控、介质管理和员工教育等。"},{"id":"t0304","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"マルウェア対策","termZh":"恶意软件防护","english":"Malware Protection","reading":"まるうぇあたいさく","breadcrumb":"","explanationJa":"コンピュータやネットワークを不正なソフトウェア、つまりマルウェアから守るための手段や方法である。具体的には、マルウェア対策ソフトを導入することや、定期的にマルウェア定義ファイルを更新することが含まれる。マルウェアはウイルスやワーム、トロイの木馬といった悪意あるソフトウェアを指し、これらはユーザーのデータを盗んだり、システムを破壊したりする可能性がある。対策ソフトは、これらの脅威を検知し、排除する機能を持っており、セキュリティ確保において非常に重要である。また、定義ファイルの更新は新たなマルウェアに対処するために欠かせず、常に最新の脅威に備えるために重要な作業となる。これにより、安全なデジタル環境を維持することが可能となる。","explanationZh":"用于预防、检测、隔离和清除病毒、蠕虫、木马、勒索软件等恶意程序的措施。通常结合终端防护、补丁管理、邮件与Web过滤、应用控制、备份以及用户教育形成多层防御。"},{"id":"t0305","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"ランサムウェア対策","termZh":"勒索软件防范措施","english":"Ransomware Countermeasures","reading":"らんさむうぇあたいさく","breadcrumb":"","explanationJa":"悪意のあるソフトウェアによってデータが暗号化されたり、システムがロックされたりした場合に、それを防止または対処するための方法やプロセスを指す。ランサムウェアは、ユーザーのデータを人質に取り、復旧のために金銭を要求するため、特に企業や個人にとって大きな脅威となる。対策としては、定期的なデータバックアップ、最新のセキュリティソフトの導入、メールやWebサイトの危険なリンクを避ける教育が挙げられる。また、ネットワークの監視や侵入検知システムを導入することで、異常な動きを早期に発見し、被害を最小限に抑えることが可能となる。このように、総合的なランサムウェア対策を実施することが重要である。","explanationZh":"针对勒索软件入侵、横向移动、数据加密和数据窃取实施的综合防护。关键措施包括及时修补、MFA、最小权限、网络分段、EDR、离线或不可变备份、钓鱼防范以及事件响应演练。"},{"id":"t0306","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"3-2-1ルール","termZh":"3-2-1备份规则","english":"3-2-1 Rule","reading":"さんにいちるーる","breadcrumb":"","explanationJa":"データのバックアップを効果的に管理するための原則である。このルールは、データを保護するために「3つのコピー」、すなわちオリジナルのデータとそのバックアップを2つ持つことを推奨する。その際、これらのコピーを異なる場所、つまり「2つの異なるメディア」に保存し、さらに「1つはオフサイト」で管理することが重要とされる。たとえば、自宅のハードドライブにデータを保存し、そのバックアップを外付けハードドライブに取り、さらにクラウドストレージに1つ保存するといった方法が挙げられる。このアプローチにより、災害やデバイスの故障によるデータ損失から比較的安全に守ることができるため、情報セキュリティの向上が図られる。","explanationZh":"一种常用备份原则：至少保留3份数据副本，使用2种不同介质，其中1份存放在异地或与生产环境隔离的位置。其目的在于避免单一设备故障、灾害或勒索软件同时破坏全部副本。"},{"id":"t0307","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"WORM","termZh":"一次写入多次读取（WORM）","english":"Write Once Read Many","reading":"わーむ","breadcrumb":"","explanationJa":"一度書き込んだデータを変更できず、何度でも読み取ることができるストレージの特性を指す。これは、主にデータの改ざんを防ぐために使用される技術である。例えば、金融機関や医療機関において、重要なトランザクションや記録を安全に保管する必要がある場合、WORMメディアが利用される。データが一度書かれると、削除や上書きができないため、情報の信頼性が高まり、法的な証拠としても有効である。また、WORMストレージはバックアップやアーカイブの目的でも重宝され、長期間にわたってデータの保存が求められる場面で特に効果を発揮する。","explanationZh":"数据一经写入后不能被修改或删除、只能多次读取的存储特性或介质。它可用于保护日志、备份和合规记录免受篡改，在勒索软件防护和证据保存中也有价值。"},{"id":"t0308","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"パターンマッチング法","termZh":"特征码匹配法","english":"Pattern Matching Method","reading":"ぱたーんまっちんぐほう","breadcrumb":"","explanationJa":"特定のデータや情報の中から、事前に定義されたパターンや特徴を見つけ出す手法のことである。この技術は、主にセキュリティ分野で使用され、マルウェアや不正アクセスの検出に役立つ。例えば、コンピュータシステムに侵入するウイルスは、特定のコードパターンを持っていることが多く、そのパターンをあらかじめデータベースに登録しておくことで、新たな感染を防ぐことができる。また、テキスト解析や画像認識など、さまざまな領域にも適用されており、データの効率的な処理や分析を可能にする。","explanationZh":"通过把文件或数据中的模式与已知恶意软件特征库进行比对来检测威胁的方法。对已知恶意软件准确且高效，但对新型、变种或经过混淆的恶意软件可能难以及时识别，因此需要持续更新特征库。"},{"id":"t0309","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"ビヘイビア法","termZh":"行为检测法","english":"Behavioral Detection Method","reading":"びへいびあほう","breadcrumb":"","explanationJa":"コンピュータやネットワーク上の異常な動作を監視・検出するための手法である。この方法は、通常の動作パターンを学習し、それに基づいて異常や不審な行動を特定する。例えば、通常は数時間ごとにログインするユーザーが、突然短時間に何度もログインを試みる場合、それが不正アクセスの試みである可能性が高く、ビヘイビア法によって警告が発令される。また、この手法はウイルスの感染なども早期に察知することができ、セキュリティ対策の一環として非常に重要な役割を果たしている。データの挙動を分析することで常に新たな脅威に対応できる柔軟性を持ち、従来の定義ベースの検知方法よりも高い効果を期待できる。","explanationZh":"通过监视程序或系统运行时的行为，识别异常或具有恶意特征的活动。即使没有已知特征码，也可根据文件加密、进程注入、异常通信等行为发现未知威胁，但需要控制误报。"},{"id":"t0310","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"ヒューリスティック法","termZh":"启发式检测法","english":"Heuristic Method","reading":"ひゅーりすてぃっくほう","breadcrumb":"","explanationJa":"問題解決や意思決定において経験則や直感を基にしたアプローチである。この手法は、最適解を求めることが難しい場合でも、素早く十分な解決策を見つけるために使用される。例えば、サイバーセキュリティの分野では、未知のウイルスやマルウェアを検出する際に、既知の脅威の特徴をもとに判断を行うことができる。これにより、新たな脅威に対しても迅速に対応することが可能となり、防御体制を強化できる。また、データが少ない状況でも機能するため、特に変化の激しい環境において有用な戦略である。","explanationZh":"基于规则、代码结构和可疑特征推断程序是否可能具有恶意性的检测方法。它能够发现部分未知或变种恶意软件，但判断具有概率性，因此可能出现误报和漏报。"},{"id":"t0311","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"未知マルウェア検出手法","termZh":"未知恶意软件检测技术","english":"Unknown Malware Detection Technique","reading":"みちまるうぇあけんしゅつしゅほう","breadcrumb":"","explanationJa":"まだ知られていない悪意のあるソフトウェアを特定するための技術である。この手法は、既知のマルウェアのパターンを用いる従来の方法とは異なり、未知の脅威に対応するための適応的なアプローチを取る。例えば、動作解析や異常検知を利用して、通常とは異なる挙動を示すプログラムを見つけ出すことができる。これにより、従来のウイルス定義ファイルに依存せず、新たに出現した攻撃からの防御を強化することが可能となる。IoTデバイスや企業ネットワークなど、さまざまな環境で重要な役割を果たし、サイバーセキュリティの向上に寄与している。","explanationZh":"用于发现尚无已知特征码的新型恶意软件的技术集合。可结合行为分析、启发式分析、沙箱、机器学习和异常检测等方法，通过运行特征和上下文识别潜在恶意行为。"},{"id":"t0312","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"秘匿化","termZh":"隐匿化／混淆","english":"Obfuscation","reading":"ひとくか","breadcrumb":"","explanationJa":"データや情報の内容を第三者に理解されにくくする技術や手法である。主に機密情報を守るために使用され、具体的にはデータの形式や構造を変更したり、意味を隠すための技術が含まれる。例えば、個人情報を格納する際に、実際の値を暗号化し、第三者が直接その内容を把握できないようにする。これはソフトウェア開発においても用いられ、コードの可読性を下げることによって、知的財産権の保護や逆コンパイルからの防御機能を果たすことができる。このように、秘匿化は技術的なセキュリティ対策の一環として重要な役割を担っている。","explanationZh":"通过改变数据、代码或标识的表现形式，使其真实内容或逻辑不易被直接识别的处理。安全上可用于保护敏感信息或增加逆向分析难度，但恶意软件也常用代码混淆逃避检测；混淆本身不等同于加密。"},{"id":"t0313","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"匿名化の手法","termZh":"匿名化方法","english":"Anonymization Techniques","reading":"とくめいかのしゅほう","breadcrumb":"","explanationJa":"個人情報やデータを特定できない形に変換するための方法である。これにより、データを利用しながらもプライバシーを保護することができる。具体的には、項目削除やレコード削除、セル削除といった手法がある。項目削除は特定の情報をデータから取り除く方法であり、レコード削除は特定のデータセット全体を削除することを意味する。セル削除は、データ表の特定の値を匿名化する手法である。また、トップコーディングやボトムコーディングは、特定の閾値以上または以下のデータを同一の値に置き換える手法で、k-匿名化は、同じ値を持つレコードの数をk以上にすることにより、個人識別を困難にする方式である。これらの手法により、データ利用のリスクを軽減しながら、分析や研究が可能になる。","explanationZh":"通过删除、泛化、扰动、聚合等技术，使数据难以再与特定个人关联的处理方法。有效匿名化需要考虑与其他数据组合后的再识别风险，并根据用途和法律要求选择适当强度。"},{"id":"t0314","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"アクセス制御","termZh":"访问控制","english":"Access Control","reading":"あくせすせいぎょ","breadcrumb":"","explanationJa":"情報資源へのアクセスを制限し、許可されたユーザーのみが特定の情報やシステムにアクセスできるようにするセキュリティ対策である。この制御は、ユーザーの認証や権限管理によって実施され、誰がどの情報にアクセスできるかを明確に定義する。例えば、企業のデータベースにおいて、管理者はそのデータベースへのフルアクセス権を持つ一方で、一般社員は閲覧のみを許可されることがある。機密情報の保護やコンプライアンスの遵守に不可欠であり、役割ベースのアクセス制御（RBAC）や属性ベースのアクセス制御（ABAC）など、さまざまなモデルが利用されている。これにより、セキュリティの強化とインシデントの防止が図られる。","explanationZh":"根据主体身份、角色、属性和策略，决定其是否可以访问特定资源以及可以执行哪些操作的安全机制。通常包含认证、授权、权限执行和审计，目标是落实最小权限并防止未授权访问。"},{"id":"t0315","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"特権的アクセス権の管理","termZh":"特权访问管理（PAM）","english":"Privileged Access Management","reading":"とっけんてきあくせすけんのかんり","breadcrumb":"","explanationJa":"情報システムやネットワークにおいて、特別な権限を持つユーザーやプロセスのアクセスを制御する仕組みを指す。特権的アクセス権を持つユーザーは、通常のユーザーには実行できない操作を行うことができるため、セキュリティにおいて非常に重要な要素である。例えば、システム管理者はサーバの設定変更や、データベースへの全権限アクセスが可能であるが、これが不正に利用されると大きなリスクにつながる。そのため、特権的アクセス権の管理が必要であり、ログの記録やアクセスの制限、定期的な権限評価が含まれる。これらにより、不正アクセスやデータ漏洩を防ぐことができる。","explanationZh":"对管理员、root等高权限账号及其访问行为进行严格管理的机制。典型措施包括特权账号集中保管、审批、临时授权、会话记录、密码轮换和最小权限，以降低高权限被滥用或被攻击者利用的风险。"},{"id":"t0316","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"ログ管理","termZh":"日志管理","english":"Log Management","reading":"ろぐかんり","breadcrumb":"","explanationJa":"システムやアプリケーションが生成するログデータを収集、保存、分析するプロセスを指す。ログデータは、トラブルシューティングやセキュリティ侵害の検出、パフォーマンス監視において重要な情報を提供する。たとえば、サーバがアクセスされた際の情報やエラー発生時の詳細が含まれる。これにより、管理者は問題の原因を特定したり、不正アクセスの痕跡を追跡したりすることができる。適切なログ管理を行うことで、システムの安定性やセキュリティレベルを向上させることが可能となり、企業にとって不可欠な要素と言える。","explanationZh":"对系统、网络、应用和安全设备日志进行生成、收集、传输、保存、保护、分析和销毁的全过程管理。日志应保证时间一致性、完整性和访问限制，并支持异常检测、事件调查、审计和合规要求。"},{"id":"t0317","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"脆弱性管理","termZh":"漏洞管理","english":"Vulnerability Management","reading":"ぜいじゃくせいかんり","breadcrumb":"","explanationJa":"システムやソフトウェアに存在する脆弱性を特定、評価、修正するプロセスである。これにより、セキュリティリスクを最小限に抑えることが目指される。具体的には、OSアップデートや脆弱性修正プログラム（セキュリティパッチ）の適用が含まれ、これにより最新の状態を保つことが重要になる。特に、外部からの攻撃者が利用する可能性のある脆弱性を早期に修正することで、情報漏洩やデータ損失などのリスクを減少させることができる。この管理プロセスは、定期的な点検や監視を行い、安全なシステム運用を支えるために欠かせないものである。","explanationZh":"持续识别、评估、确定优先级、修复和验证漏洞的管理过程。它通常包括资产盘点、漏洞扫描、威胁和业务影响评估、补丁或缓解措施实施以及修复跟踪，避免漏洞长期暴露。"},{"id":"t0318","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"SBOM","termZh":"软件物料清单（SBOM）","english":"Software Bill of Materials","reading":"えすぼむ","breadcrumb":"","explanationJa":"ソフトウェアの構成要素や依存関係を詳細に記載したリストである。これは、ソフトウェアの透明性やセキュリティを向上させるために重要であり、どのライブラリやパッケージが含まれているかを把握することができる。たとえば、企業が商用ソフトウェアを利用する際、そのソフトウェアがどのようなオープンソースライブラリに依存しているかを確認することで、脆弱性やライセンス問題を把握しやすくなる。セキュリティの観点からも重要であり、攻撃者が狙う可能性がある脆弱な部分を特定する手助けとなる。また、法令遵守やソフトウェアのメンテナンスにも寄与し、ソフトウェアの信頼性を高める役割を果たす。","explanationZh":"列出软件产品所包含组件、库、版本和依赖关系的清单。通过掌握软件供应链组成，组织能够在某组件出现漏洞或许可证问题时快速判断受影响范围，并支持漏洞管理和供应链风险管理。"},{"id":"t0319","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"ネットワーク監視","termZh":"网络监控","english":"Network Monitoring","reading":"ねっとわーくかんし","breadcrumb":"","explanationJa":"コンピュータネットワークの状態を常時チェックし、パフォーマンスやセキュリティの問題を早期に発見するための手法である。これにより、ネットワークのトラフィックや接続状況が監視され、異常が発生した場合に即座に対応が可能となる。例えば、企業が自社のサーバやコンピュータの接続状態を監視することで、不正アクセスやシステム障害の兆候を見逃さず、迅速な対策を講じることができる。また、ネットワーク監視ツールは、データの流れを可視化する機能を持ち、どの部分で問題が発生しているかを特定しやすくするため、業務の安定性向上にも寄与する。","explanationZh":"持续观察网络流量、设备状态和通信行为，以发现故障、性能问题和安全异常的活动。安全监控可通过流量分析、日志、IDS/IPS等识别扫描、入侵、异常外联和数据泄露迹象。"},{"id":"t0320","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"アクセス権の設定","termZh":"访问权限设置","english":"Access Rights Configuration","reading":"あくせすけんのせってい","breadcrumb":"","explanationJa":"情報システムにおけるデータやリソースへのアクセスを制御するための仕組みである。これにより、どのユーザーがどの情報にアクセスできるかを明確にし、情報漏洩や不正使用を防ぐ役割を果たす。例えば、企業のファイルサーバでは、社員が部署ごとに異なるフォルダにアクセスできるよう設定されることが一般的である。これにより、機密情報や重要なデータはアクセスが許可されたユーザーのみに制限され、情報の保護が強化される。また、定期的に見直すことが求められる。これにより、退職した社員の権限を削除するなど、常に適切な管理状態を維持することが重要である。","explanationZh":"根据用户岗位和业务需要，为系统、文件、数据库等资源配置读取、写入、执行和管理等权限的过程。应遵循最小权限和职责分离原则，并在入职、调岗、离职及定期复核时及时调整。"},{"id":"t0321","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"侵入検知","termZh":"入侵检测","english":"Intrusion Detection","reading":"しんにゅうけんち","breadcrumb":"","explanationJa":"ネットワークやシステムに対する不正アクセスや攻撃を監視し、検出するための技術や手法である。これは、コンピュータやネットワークのセキュリティを強化し、未然に問題を防ぐことを目的としている。例えば、侵入検知システム（IDS）は、ネットワークトラフィックを分析し、異常な動きや既知の攻撃パターンを検出する。これにより、攻撃が発生する前に警告を発したり、迅速な対応が可能となる。また、企業の重要なデータを守るために欠かせない要素であり、セキュリティインシデントの発生を減少させる役割を果たす。","explanationZh":"监视网络或主机活动并识别攻击、违规或异常行为的过程。检测系统通常发出告警供人员调查，但一般不主动阻断流量；其效果取决于规则、行为模型和监控范围。"},{"id":"t0322","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"侵入防止","termZh":"入侵防御","english":"Intrusion Prevention","reading":"しんにゅうぼうし","breadcrumb":"","explanationJa":"ネットワークやシステムへの不正アクセスを検知し、それを阻止するための技術や手法である。この対策は、サイバー攻撃やウイルス感染から情報を守るために非常に重要である。具体的には、侵入防止システム（IPS）がリアルタイムでトラフィックを監視し、異常な動きや知られている攻撃のパターンを検出することで、即座に攻撃を遮断する。たとえば、外部からの不正なログイン試行を察知した場合、その接続を自動的に切断することで、システムを守ることができる。これにより、企業や個人のデータの安全性が高まり、セキュリティリスクを軽減することが可能となる。","explanationZh":"在检测到恶意或异常活动后自动采取阻断、丢弃或隔离等措施的机制。相比只告警的入侵检测，它能够实时干预攻击，但需要合理配置以避免误阻正常业务。"},{"id":"t0323","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"DMZ","termZh":"非军事区（DMZ）","english":"Demilitarized Zone","reading":"でぃーえむぜっと","breadcrumb":"","explanationJa":"ネットワークセキュリティにおいて、内部ネットワークと外部ネットワーク（通常はインターネット）の間に配置される中立的な領域である。この領域には、Webサーバやメールサーバなど、外部からアクセスされる必要のあるサービスが設置されることが一般的である。外部からの侵入を防ぎつつ、内部ネットワークへのアクセスを制限するための重要なセキュリティ対策である。たとえば、企業が自社のWebサイトを運営する際、DMZにWebサーバを置くことで、外部からの攻撃が内部ネットワークに直接影響を及ぼすリスクを減少させることができる。このように、DMZは情報セキュリティの層を一つ追加する役割を果たしている。","explanationZh":"位于互联网与内部网络之间的隔离网络区域，通常放置Web、邮件等需要对外提供服务的服务器。通过防火墙限制DMZ与内网之间的通信，即使对外服务器被攻陷，也可降低攻击进一步进入内部网络的风险。"},{"id":"t0324","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"検疫ネットワーク","termZh":"隔离／检疫网络","english":"Quarantine Network","reading":"けんえきねっとわーく","breadcrumb":"","explanationJa":"サイバーセキュリティにおいて、感染の疑いがあるデバイスやネットワークの一部を隔離するために使用されるセグメントである。このネットワークにアクセスすることで、潜在的な脅威が自社の重要な情報やシステムに広がるのを防ぐことができる。例えば、ウイルスやマルウェアが疑われるデバイスを一時的に切り離して、その影響を評価し、適切な対策を講じるためのスペースとして機能する。企業が外部からの攻撃や内部の脆弱性に対して防御を強化するために、必須のセキュリティ対策となっている。これは、特に感染症が広がるリスクを軽減するため、企業のIT環境を保護する上で重要である。","explanationZh":"把不满足安全要求或状态可疑的终端先放入受限网络区域进行检查和修复的机制。终端通过补丁、杀毒、配置等合规检查后才能进入正式网络，可减少受感染设备传播威胁。"},{"id":"t0325","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"URLフィルタリング","termZh":"URL过滤","english":"URL Filtering","reading":"ゆーあーるえるふぃるたりんぐ","breadcrumb":"","explanationJa":"Webサイトへのアクセスを制御するための技術である。この技術は、特定のWebサイトやコンテンツをブロックすることで、企業や教育機関などにおいて不適切な情報や危険なサイトへのアクセスを防ぐことを目的としている。例えば、学校では生徒が不適切なコンテンツにアクセスできないように設定されている。この技術は、WebサイトのURLをデータベースに基づいて評価し、適切とされるサイトにのみアクセスを許可する仕組みを持つ。また、セキュリティ対策の一環としても重要であり、マルウェアやフィッシングサイトからユーザーを保護する役割も果たしている。これにより、安全にインターネットを利用できる環境を提供することができる。","explanationZh":"根据网址、域名、类别、信誉或策略允许或阻止访问特定Web资源的安全控制。可用于限制恶意网站、钓鱼网站和不适当内容，并支持组织的互联网使用政策。"},{"id":"t0326","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"コンテンツフィルタリング","termZh":"内容过滤","english":"Content Filtering","reading":"","breadcrumb":"","explanationJa":"特定の情報やデータを自動的に選別し、表示またはアクセスを制御する技術のことである。この技術は、インターネットやネットワーク上での不適切な内容、スパム、ウイルスなどをフィルタリングするために使用される。例えば、学校や企業のネットワークでは、生徒や社員が閲覧できるWebサイトを制限し、不適切な情報へのアクセスを防ぐ役割を果たしている。コンテンツフィルタリングを導入することで、利用者は安全な環境でインターネットを利用でき、情報セキュリティの向上にも寄与する。また、個人のデバイスにもフィルタリング機能が備わっていることがあり、ユーザーが自ら設定することで自衛策を講じることも可能である。","explanationZh":"对邮件、Web、文件或网络传输内容进行检查，并依据类型、关键词、恶意代码或策略进行允许、阻断或隔离。它可用于恶意软件防护、垃圾邮件过滤和信息泄露防范。"},{"id":"t0327","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"携帯端末のセキュリティ","termZh":"移动终端安全","english":"Mobile Device Security","reading":"けいたいたんまつのせきゅりてぃ","breadcrumb":"","explanationJa":"携帯電話、スマートフォン、タブレット端末などのデバイスを守るための技術的な対策を指す。これには、不正アクセスを防ぐためのパスコードや生体認証の設定、ウイルス対策ソフトの導入、データの暗号化などが含まれる。例えば、スマートフォンには指紋認証や顔認証など、ユーザーの身元を確認するための機能が備わっており、不正に機器を操作されるリスクを軽減する。また、重要なデータを適切にバックアップし、紛失時にはリモートでデータを消去する機能もあり、これによって情報漏洩を防ぐことができる。携帯端末のセキュリティ対策は、個人情報を守るために欠かせない要素である。","explanationZh":"针对智能手机、平板等移动设备实施的安全管理。包括设备加密、屏幕锁、MFA、应用控制、补丁更新、远程锁定或擦除、MDM和安全通信等，以应对丢失、盗窃和恶意应用风险。"},{"id":"t0328","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"データマスキング","termZh":"数据掩码","english":"Data Masking","reading":"","breadcrumb":"","explanationJa":"機密情報を保護するために、その内容を変換して見えなくする技術である。これにより、情報が漏洩した場合でも、実際のデータが悪用されるリスクを減少させる。具体例としては、顧客の名前や住所などの個人情報を、無関係な文字列や数字に置き換えることが挙げられる。例えば、「山田太郎」を「XXXXXX」に変換することで、元の情報が分からなくなる。この技術は、テスト環境や研修用データで実際のデータを使用する際に特に有用であり、データのプライバシーを確保し、法規制にも対応するために広く利用されている。情報セキュリティの重要な手段の一つである。","explanationZh":"通过替换、遮盖或变形敏感字段，使非授权人员无法看到真实数据，但仍可保持数据格式或部分业务可用性的技术。常用于测试、客服和报表场景，以降低真实个人信息或账号数据暴露风险。"},{"id":"t0329","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"暗号化消去","termZh":"密码学擦除","english":"Cryptographic Erase","reading":"あんごうかしょうきょ","breadcrumb":"","explanationJa":"暗号化されたデータの復号鍵を消去することによって、データが再利用できなくなる技術である。具体的には、データが安全に暗号化されている状態で、その復号鍵を削除することで、データを読み取れなくする。これにより、ディスクやストレージデバイスが廃棄される際に、セキュリティが確保される。たとえば、個人情報や機密データが保存されたストレージを処分する場合、単にデータを削除するのではなく、復号鍵を消去することで、データが未だに存在する可能性を排除できる。この方法は、データの保護において非常に効果的であり、特に企業などで機密情報を扱う際に有用である。","explanationZh":"通过安全删除或销毁用于加密数据的密钥，使加密后的数据在实际意义上无法再解密的销毁方法。适用于加密存储介质和云环境，但前提是加密实现可靠且所有密钥副本均得到妥善销毁。"},{"id":"t0330","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"クラウドサービスのセキュリティ","termZh":"云服务安全","english":"Cloud Service Security","reading":"","breadcrumb":"","explanationJa":"クラウド環境で提供されるサービスやデータを保護するための管理や技術のことを指す。クラウドサービスでは、データがインターネット上のサーバに保存されるため、外部からの侵入や情報漏洩のリスクが伴う。このため、暗号化やアクセス制御、ファイアウォールなどの技術が必須となる。例えば、データを暗号化することで、万が一情報が盗まれた場合でも、内容を解読されにくくすることができる。また、ユーザーに認証プロセスを設けることで、不正アクセスを防ぐ手段も重要である。これらのセキュリティ対策を組み合わせることで、クラウドサービスの安全性を高め、信頼性のあるデータ保護を実現できる。","explanationZh":"在使用IaaS、PaaS、SaaS等云服务时保护账号、数据、配置和业务连续性的管理与技术措施。应理解责任共担模型，重点关注身份权限、配置、加密、日志、备份、供应商风险和合规要求。"},{"id":"t0331","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"IoTのセキュリティ","termZh":"IoT安全","english":"IoT Security","reading":"あいおーてぃーのせきゅりてぃ","breadcrumb":"","explanationJa":"インターネットに接続されたデバイスやセンサーを保護するための対策である。IoTは、生活や産業の様々な場面で利用され、機器同士が相互にデータを交換する仕組みを持つ。例えば、スマートホームのデバイスが連携してエネルギーを効率よく管理する場合、セキュリティが不十分だと外部からの攻撃によって危険が生じる可能性がある。具体的な対策には、データ暗号化、強力な認証手続き、ネットワークの監視が含まれる。これらの対策は、個人情報や重要なデータの漏洩を防ぎ、IoTデバイスの安全な運用を実現するために不可欠である。","explanationZh":"保护联网设备、通信、平台和所处理数据免受攻击与滥用的安全实践。由于IoT设备常具有资源受限、寿命长和部署分散等特点，应特别重视安全默认配置、唯一凭据、更新机制、网络隔离和设备生命周期管理。"},{"id":"t0332","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"電子透かし","termZh":"数字水印","english":"Digital Watermarking","reading":"でんしすかし","breadcrumb":"","explanationJa":"画像や音声、動画などのデジタルデータに目に見えない形で情報を埋め込む技術である。これにより、著作権や所有権の保護が可能になる。例えば、写真にクリエイターの名前やロゴを隠した形で埋め込むことができ、その写真が無断で使用された場合でも、著作権を主張する根拠とすることができる。この技術は、オリジナルのデータとは異なり、改変や削除に耐性を持つよう設計されているため、不正利用の検出にも役立つ。また、不正コピーの防止やトレーサビリティの向上など、デジタルコンテンツの安全性を高める重要な手段として広く利用されている。","explanationZh":"把难以察觉或可识别的标记嵌入图像、音频、视频或文档中的技术，用于证明版权、追踪来源或检测篡改。水印可设计为可见或不可见，但其目的与加密不同，通常不用于隐藏内容本身。"},{"id":"t0333","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"デジタルフォレンジックス","termZh":"数字取证","english":"Digital Forensics","reading":"","breadcrumb":"","explanationJa":"デジタルデータに関する証拠を収集、保存、分析するプロセスである。この技術は主にサイバー犯罪や違法行為の調査に使用され、デジタル機器からの重要な情報を確保することを目的とする。例えば、コンピュータやスマートフォンから削除されたファイルを復元したり、過去の通信記録を解析したりすることで、真実を解明する手助けを行う。証拠の合法性や信頼性を保つために詳細な手順が求められ、適切に実施されることで法的な手続きにも利用される。この分野は、セキュリティ対策を強化する上で重要な役割を果たしており、高度な技術と専門知識が必要である。","explanationZh":"按照可验证、可重复和符合法律程序的方式，对计算机、网络和移动设备中的数字证据进行识别、保全、采集、分析和报告。关键是维持证据完整性和保管链，以支持事件调查、内部调查或司法程序。"},{"id":"t0334","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"AIを使ったセキュリティ技術","termZh":"利用AI的安全技术","english":"AI for Security","reading":"えーあいをつかったせきゅりてぃぎじゅつ","breadcrumb":"","explanationJa":"人工知能（AI）を活用し、情報システムやネットワークの安全性を高めるための技術である。これにより、サイバー攻撃の検知や防御を自動化し、迅速に対応することが可能になる。例えば、AIは異常なトラフィックをリアルタイムで分析し、新たな攻撃パターンを学習することで、従来の手法では見逃されがちな脅威を早期に察知できる。また、フィッシングメールの検出やマルウェアの分析にも利用され、従来のルールベースの検知システムよりも高い精度を発揮することが期待されている。これにより、企業はより効率的にセキュリティを強化し、安心して業務を行うための基盤を築くことができる。","explanationZh":"利用机器学习、生成式AI等技术提升威胁检测、日志分析、异常识别、恶意软件分析和响应效率的安全应用。AI可提高处理海量数据的能力，但其输出仍需验证，并应防范误报、偏差和被攻击者规避。"},{"id":"t0335","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"AIそのものを守るセキュリティ技術","termZh":"保护AI本身的安全技术","english":"Security for AI","reading":"えーあいそのものをまもるせきゅりてぃぎじゅつ","breadcrumb":"","explanationJa":"人工知能（AI）システムを外部からの攻撃や不正な改ざんから保護するための技術である。これには、AIモデルのトレーニングデータの保護、システムへのアクセス制御、データのプライバシー確保などが含まれる。例えば、AIが学習するために使用されるデータが不正に変更されると、AIの予測や推論に悪影響を及ぼす可能性がある。そのため、攻撃者がデータセットにアクセスしたり、不正にAIシステムに介入することを防ぐ対策が必要である。さらに、AIモデル自体が悪用されないように、セキュリティプロトコルや監視システムを導入することも重要で、これによりAIの信頼性が向上し、業務の安全性を保つことができる。","explanationZh":"用于保护AI模型、训练数据、推理接口和相关基础设施免受投毒、对抗样本、模型窃取、提示词注入和数据泄露等攻击的技术与管理措施。重点是保证AI系统的机密性、完整性、可用性和可靠性。"},{"id":"t0336","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"マルウェア対策ソフト","termZh":"恶意软件防护软件","english":"Malware Protection Software","reading":"まるうぇあたいさくそふと","breadcrumb":"","explanationJa":"悪意のあるソフトウェア（マルウェア）からコンピュータやネットワークを保護するためのソフトウェアである。マルウェアはウイルス、ワーム、スパイウェア、ランサムウェアなど、多種多様な形態を持ち、システムに損害を与えたり、データを盗んだりする恐れがある。これらの脅威を検出・排除する機能を持ち、リアルタイムでの監視や定期的なウイルススキャンを行う。また、新たに発見された脅威に対するアップデートを提供することで、常に安全な環境を保つ役割も果たす。したがって、日常的なネットワーク利用やビジネス活動において不可欠なツールである。","explanationZh":"用于检测、阻止、隔离和清除恶意软件的安全软件，包括传统防病毒以及具备行为分析、云信誉和实时防护功能的产品。应保持引擎和规则更新，并与补丁、权限和备份等其他控制配合使用。"},{"id":"t0337","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"EDR","termZh":"终端检测与响应（EDR）","english":"Endpoint Detection and Response","reading":"いーでぃーあーる","breadcrumb":"","explanationJa":"エンドポイント（コンピュータやスマートフォンなどの端末）におけるサイバーセキュリティ対策の一つである。端末内での不正アクセスやマルウェアの活動をリアルタイムで監視し、異常が発生した際には迅速に対応する仕組みを持っている。具体的には、例えば不審なファイルが実行された場合、その動作を記録し、管理者に警告を発することで、迅速な対処を可能にする。これにより、組織全体のセキュリティを強化し、データの損失や情報漏洩を防ぐことができる。従来のウイルス対策ソフトウェアに比べてより高度な監視機能を提供し、積極的に脅威に対処する重要な技術である。","explanationZh":"持续收集终端行为和安全遥测，检测可疑活动并支持调查、隔离和响应的安全技术。EDR能够追踪进程、文件、网络连接等上下文，适合发现传统特征码防病毒难以识别的高级攻击。"},{"id":"t0338","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"DLP","termZh":"数据防泄漏（DLP）","english":"Data Loss Prevention","reading":"でぃーえるぴー","breadcrumb":"","explanationJa":"データ損失防止の取り組みを指す。特に企業や組織において、機密情報や重要なデータが不正に外部に漏えいしないようにするための技術やポリシーを含む。たとえば、DLPツールは、メールやファイル転送時に重要な情報を検出し、無許可の送信を防ぐためのルールを適用する。このように、適切なセキュリティ対策を設けることで、データ漏洩や情報流出のリスクを軽減し、コンプライアンスにも寄与する。また、DLPは社内のデータ管理を強化し、情報保護に対する意識を高める役割も果たす。","explanationZh":"识别敏感数据并监控其在终端、网络和云中的存储、使用和传输，根据策略进行告警、阻断、加密或审批的技术与管理体系。它用于降低员工误发、违规外传和恶意窃取数据的风险。"},{"id":"t0339","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"SIEM","termZh":"安全信息与事件管理（SIEM）","english":"Security Information and Event Management","reading":"しーむ","breadcrumb":"","explanationJa":"セキュリティ情報およびイベント管理の略称であり、企業や組織の情報システムにおけるセキュリティイベントを収集・分析・管理するためのソリューションである。異なるデータソースからのログ情報を集約し、リアルタイムでの脅威の検出や、不正アクセスの監視を行う。例えば、社内のサーバやアプリケーションのログを一元的に解析することで、不審なアクティビティを迅速に発見できる。これにより、サイバー攻撃からの防御を強化し、インシデント発生時には迅速な対応が可能となる。組織のセキュリティポリシーに基づいた運用が求められ、リスクマネジメントの一環として広く利用されている。","explanationZh":"集中收集和关联分析来自系统、网络、应用及安全设备的日志和安全事件的平台。SIEM通过规则、关联分析和告警帮助发现跨系统攻击活动，并为SOC监控、事件调查和合规审计提供数据基础。"},{"id":"t0340","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"ファイアウォール","termZh":"防火墙","english":"Firewall","reading":"","breadcrumb":"","explanationJa":"ネットワークを外部の脅威から守るためのセキュリティ機器またはソフトウェアである。特定の通信を監視し、許可されたトラフィックのみを通過させ、悪意のあるデータや攻撃からシステムを保護する役割を果たす。企業や個人のネットワークでよく使用され、内部と外部のネットワーク間のバリアを形成する。例えば、インターネットからの不正アクセスを防ぐために、特定のポートを閉じる設定を行うことができる。また、ファイアウォールには、パケットフィルタリング型、ステートフル型、次世代型など様々な種類があり、それぞれを用いることで異なる運用ニーズに応じたセキュリティを実現することが可能である。","explanationZh":"依据安全策略对不同网络区域之间的通信进行允许或阻断的安全设备或软件。它通常根据IP地址、端口、协议、连接状态或应用特征过滤流量，是网络边界和分区防护的重要组成部分。"},{"id":"t0341","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"WAF","termZh":"Web应用防火墙（WAF）","english":"Web Application Firewall","reading":"わふ","breadcrumb":"","explanationJa":"Webアプリケーションを保護するためのセキュリティ製品である。主に、悪意のある攻撃からWebサイトやアプリケーションを守る役割を果たす。例えば、SQLインジェクションやクロスサイトスクリプティングといった攻撃を防ぐために、トラフィックを監視し、不正なリクエストをブロックすることができる。ユーザーがWebアプリケーションに接続する際、データの送受信を詳細に分析することで、特定のパターンや異常を検出し、セキュリティを強化する。また、企業の機密情報やユーザーのプライバシーを保護するために重要な役割を果たしており、データ漏えいや侵害からの防御に欠かせない存在である。","explanationZh":"专门分析HTTP/HTTPS请求与响应、保护Web应用免受SQL注入、XSS等应用层攻击的安全设备或服务。WAF通过规则和行为分析拦截恶意请求，但不能替代安全编码和漏洞修复。"},{"id":"t0342","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"IDS","termZh":"入侵检测系统（IDS）","english":"Intrusion Detection System","reading":"あいでぃーえす","breadcrumb":"","explanationJa":"ネットワークやコンピュータシステムへの不正アクセスや攻撃を監視し、検知するためのシステムである。これにより、システム管理者は潜在的な脅威を早期に発見し、迅速な対応が可能になる。IDSは大きく分けて、ネットワークベースとホストベースに分類され、前者はネットワークトラフィック全体を監視し、後者は特定のデバイス内の動作を監視する。例えば、IDSが不正ログインの試行を検知した場合、アラートを発生させて管理者に通知することができる。このように、IDSはサイバー攻撃からシステムを守るための重要な役割を果たしている。","explanationZh":"监控网络或主机活动并识别已知攻击和异常行为的系统。检测到可疑事件时主要生成告警供分析，通常不直接阻断通信，因此需要与响应流程或其他防护设备配合。"},{"id":"t0343","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"IPS","termZh":"入侵防御系统（IPS）","english":"Intrusion Prevention System","reading":"あいぴーえす","breadcrumb":"","explanationJa":"ネットワーク上で不正アクセスや攻撃を検知し、それを阻止するためのシステムである。これは、侵入検知システム（IDS）とは異なり、単に警告を出すのではなく、リアルタイムで攻撃を防ぎ、システムを守る役割を果たす。具体的には、送信されるデータのパターンを分析し、既知の攻撃手法に基づいて異常を検出する。例えば、不正なデータパケットが送られてきた場合、そのパケットをブロックすることで攻撃を未然に防ぐことができる。また、IPSはファイアウォールと連携して動作することが多く、セキュリティの強化に寄与している。これにより、企業や組織は情報漏洩やシステム停止のリスクを低減できるため、重要なセキュリティ対策の一つとなっている。","explanationZh":"在网络或主机上实时检测攻击并主动阻断恶意流量或行为的系统。IPS可丢弃数据包、重置连接或隔离来源，但策略配置不当可能误阻正常业务，需要持续调优。"},{"id":"t0344","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"UTM","termZh":"统一威胁管理（UTM）","english":"Unified Threat Management","reading":"ゆーてぃーえむ","breadcrumb":"","explanationJa":"ネットワークのセキュリティを一元管理するためのシステムである。ファイアウォール、ウイルス対策、侵入検知システム、スパムフィルタリングなど、複数のセキュリティ機能を統合して提供する。これにより、企業や組織は複数のセキュリティソリューションを個別に運用する必要がなくなり、管理の手間を大幅に軽減できる。たとえば、中小企業では専任のITセキュリティスタッフが少ない場合が多いため、UTMを導入することで、効率的かつ効果的に脅威からネットワークを保護できる。さらに、UTMはリアルタイムでの監視やレポート機能も備えており、脅威に対して迅速に対応することが可能である。これは、サイバー攻撃が増加する中で、企業の重要な防御策となっている。","explanationZh":"在一台设备或统一平台中集成防火墙、入侵防御、防病毒、Web过滤、VPN等多种安全功能的方案。它简化中小规模环境的安全运维，但设备本身可能成为性能或可用性的集中点。"},{"id":"t0345","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"許可リスト","termZh":"允许列表","english":"Allow List","reading":"きょかりすと","breadcrumb":"","explanationJa":"特定のユーザーやデバイス、アプリケーションなど、ネットワークやシステムに対してアクセスを許可するためのリストである。パスリストやホワイトリストとも呼ばれる。これにより、セキュリティを強化し、不正なアクセスや悪意のある攻撃からシステムを守る役割がある。例えば、社内のネットワークに接続できるデバイスを管理者が事前に登録した場合、その登録されたデバイスだけがアクセスを許可される。この仕組みは、重要なデータやシステムを保護するために非常に効果的であり、特に企業のセキュリティ対策において重要な役割を果たす。許可リストを利用することで、未許可のデバイスやアプリケーションからの攻撃リスクを大幅に低減することが可能である。","explanationZh":"明确列出被允许的用户、程序、地址、域名或行为，仅允许列表中的对象通过或执行的控制方式。相比默认允许再阻断的模式，允许列表通常更严格，但需要持续维护以避免影响业务。"},{"id":"t0346","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"拒否リスト","termZh":"阻止列表／拒绝列表","english":"Block List","reading":"きょひりすと","breadcrumb":"","explanationJa":"特定のユーザーやIPアドレス、ドメインなどを排除するためのリストである。ブロックリストとも呼ばれる。このリストに含まれる対象は、アクセスを遮断されたり、特定のサービスから除外されたりすることになる。例えば、悪意のある攻撃者やスパム送信者をブロックするために、ネットワーク管理者やセキュリティソフトウェアにより利用される。セキュリティ対策の一環として重要であり、許可リストと組み合わせて使用することも多い。これにより、信頼できる対象だけがアクセスを許可される仕組みを作ることができ、より安全な環境を構築することが可能である。","explanationZh":"列出已知恶意或禁止的对象并对其进行阻断，而其他未列出的对象默认允许的控制方式。它易于部署，但无法覆盖未知威胁，因此通常需要与行为检测等手段结合。"},{"id":"t0347","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"フォールスネガティブ","termZh":"假阴性／漏报","english":"False Negative","reading":"","breadcrumb":"","explanationJa":"セキュリティの分野において、脅威や攻撃を見逃す誤判定のことを指す。具体的には、ウイルス対策ソフトウェアや侵入検知システムが、実際には攻撃であるにもかかわらずそれを未検知として「安全」と判断してしまう場合を指す。たとえば、悪意のあるファイルがシステムに侵入しても、対策ソフトがそれを安全なファイルと認識することになる。このような誤判定は、システムやデータの安全性を脅かす可能性があり、企業や個人にとって深刻なリスクとなる。フォールスネガティブを減らすためには、定期的なソフトウェアのアップデートや、脅威情報の共有が重要な対策である。","explanationZh":"实际存在威胁或异常，但检测系统错误地判断为正常的情况。漏报会使真实攻击未被发现，因此安全系统需要在漏报率与误报率之间进行合理平衡。"},{"id":"t0348","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"フォールスポジティブ","termZh":"假阳性／误报","english":"False Positive","reading":"","breadcrumb":"","explanationJa":"セキュリティ関連の処理において、実際には問題がないのに警告や誤検知が発生することを指す。たとえば、ウイルス対策ソフトが無害なファイルを誤ってウイルスと判断する場合がこれに該当する。この結果、ユーザーは不必要な警告を受けることになり、場合によっては信頼性が低下することもある。運用上の効率を損ない、エンジニアやユーザーにとって時間と労力を浪費させる原因となる。そのため、セキュリティ製品やサービスは、誤検知の確率を減少させるための工夫が求められる。","explanationZh":"实际正常的活动被检测系统错误判断为威胁或异常的情况。过多误报会消耗分析资源并造成告警疲劳，因此需要通过规则优化、上下文和基线分析降低误报。"},{"id":"t0349","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"SSL/TLSアクセラレーター","termZh":"SSL/TLS加速器","english":"SSL/TLS Accelerator","reading":"えすえすえる/てぃーえるえすあくせられーたー","breadcrumb":"","explanationJa":"データの暗号化と復号化を専門に行うハードウェアやソフトウェアの装置である。これにより、Webサーバやアプリケーションサーバの負荷を軽減し、通信の安全性を向上させることができる。具体的には、インターネット上で情報を安全にやり取りするためのSSL（Secure Sockets Layer）やTLS（Transport Layer Security）プロトコルを用いた通信を高速化する役割を果たす。この技術により、特にトラフィックが多いサイトでもスムーズな表示が可能となり、ユーザー体験を向上させることができる。また、SSL/TLSアクセラレーターを活用することで、デジタル証明書の管理や更新が効率化され、安全性を確保したまま接続の品質を高めることが可能となる。","explanationZh":"专门处理TLS握手、加解密等计算密集操作的设备或功能，用于减轻Web服务器负载并提升HTTPS处理能力。部署时必须安全管理私钥和证书，并考虑解密位置对端到端安全边界的影响。"},{"id":"t0350","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"MDM","termZh":"移动设备管理（MDM）","english":"Mobile Device Management","reading":"えむでぃーえむ","breadcrumb":"","explanationJa":"企業や組織が従業員のモバイルデバイスを一元的に管理するためのシステムである。MDMを使用することで、スマートフォンやタブレットの設定やアプリのインストール、デバイスのセキュリティポリシーの適用を行うことができる。たとえば、企業が提供する携帯電話に対して、必要な業務アプリやVPN設定を自動で配布する一方、デバイスの紛失や盗難に備えてリモートワイプ機能を提供することで、データの漏洩防止に寄与する。また、MDMはデバイスの状態や利用状況を把握するための監視機能も持ち合わせており、組織全体のセキュリティを強化する役割を果たしている。これは、BYOD（Bring Your Own Device）環境においても重要で、安全に業務を支援するための不可欠なツールである。","explanationZh":"集中注册、配置、监控和控制组织移动设备的管理平台。可强制密码和加密策略、分发应用、限制功能、检查合规状态以及在设备丢失时远程锁定或擦除数据。"},{"id":"t0351","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"Webアイソレーション","termZh":"Web隔离","english":"Web Isolation","reading":"うぇぶあいそれーしょん","breadcrumb":"","explanationJa":"Webブラウジングにおけるセキュリティ対策の一つである。この技術は、悪意のあるWebサイトやコンテンツがデバイスに直接影響を与えないように、ユーザーの環境を隔離する仕組みである。具体的には、ブラウザが表示するコンテンツを仮想環境やコンテナと呼ばれる安全な領域内で動作させ、これにより、感染や情報漏洩のリスクを軽減する。たとえば、企業内で従業員がインターネットにアクセスする際、Webアイソレーションを利用することで、外部からの脅威を内部ネットワークに侵入させないようにすることが可能になる。この技術は、特にフィッシング攻撃やマルウェアからの防護に役立ち、企業や個人にとって重要なセキュリティ対策である。","explanationZh":"把用户浏览器与互联网内容的实际执行环境隔离开，使网页代码在远程或沙箱环境中运行，仅把安全呈现结果传给用户。这样可降低恶意网页、脚本和下载直接攻击终端的风险。"},{"id":"t0352","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"RASIS","termZh":"RASIS","english":"Reliability, Availability, Serviceability, Integrity, Security","reading":"れいしす","breadcrumb":"","explanationJa":"情報システムやサービスの品質を評価するための重要な指標群である。信頼性（Reliability）、可用性（Availability）、保守性（Serviceability）、完全性（Integrity）、安全性（Security）を示す各要素で構成されている。信頼性は、システムが故障せずに機能し続ける能力を指す。可用性は、必要なときにサービスが使用可能であるかどうかを表す。保守性は、システムの点検や修理の容易さを示し、完全性はデータが正確で改ざんされていない状態を保持することを意味する。安全性は、情報の機密を守り、外部からの脅威に対する防御を示す。これらの指標は、セキュリティ製品やサービスの選定、運用、評価に欠かせない要素であり、高いRASISを持つシステムは、より安定したサービスを提供することができる。","explanationZh":"用于评价信息系统质量的重要特性集合，通常包括可靠性、可用性、可维护性、完整性和安全性。通过综合考虑这些属性，可从持续运行、故障恢复、数据正确性和安全保护等角度评价系统。"},{"id":"t0353","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"RAS技術","termZh":"远程访问安全技术","english":"Remote Access Security Technology","reading":"らすぎじゅつ","breadcrumb":"","explanationJa":"遠隔からのアクセスに関する安全性を確保するための技術である。この技術は、物理的なセキュリティ対策として、内部ネットワークへの不正アクセスを防ぐために重要である。具体的には、ユーザーが遠隔地からシステムに接続する際に、認証や暗号化を行うことで、データの盗聴や改ざんを防ぐ役割を果たす。たとえば、VPN（バーチャルプライベートネットワーク）を使用すると、インターネット上で安全な通信トンネルを作成し、外部からの脅威を低減することができる。このように、リモートワークや外部委託業務が増加する現代において、ますます重要性が高まっている。","explanationZh":"用于保护从外部网络远程访问组织系统的技术和管理措施。通常包括VPN、MFA、设备合规检查、加密通信、访问控制和日志监控，以降低凭据泄露和不受控终端带来的风险。"},{"id":"t0354","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"耐震耐火設備","termZh":"抗震防火设施","english":"Seismic and Fire Resistance Equipment","reading":"たいしんたいかせつび","breadcrumb":"","explanationJa":"建物や施設が地震や火災に対して安全性を確保するために導入される装置やシステムのことを指す。これらの設備は、建物の構造を強化し、発生する可能性のある災害から人々の生命や財産を守る役割を果たす。たとえば、地震の揺れを吸収するための免震装置や、火災の際に煙を排出するための換気システムなどが含まれる。安全な環境を提供するために非常に重要であり、特に高層ビルや公共施設ではこれらの設備が法律で求められることもある。これにより、万が一の事態に備えて、より安全な社会を実現しようとする取り組みが行われている。","explanationZh":"通过建筑结构、防火分区、灭火设备、耐火材料等方式保护机房和设备免受地震、火灾等物理灾害影响的设施措施。它是信息系统物理安全和业务连续性的重要基础。"},{"id":"t0355","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"UPS","termZh":"不间断电源（UPS）","english":"Uninterruptible Power Supply","reading":"ゆーぴーえす","breadcrumb":"","explanationJa":"無停電電源装置のことである。主に電力供給の中断を防ぐために使用される装置であり、電力が故障した場合や停電時に一時的に電源を供給する役割を果たす。例えば、サーバや重要な電子機器が電力を失った際に、UPSが備えたバッテリーが自動的に作動し、数分から数時間の間、機器に電力を供給することで、データの損失やシステムのダウンを防ぐことができる。また、UPSは電力の急激な変動を抑制する機能も備えており、電圧の安定を図ることができるため、特にビジネス環境やデータセンターで重宝される。","explanationZh":"在市电中断或异常时短时间持续向设备供电，并可进行稳压或触发安全关机的电源装置。UPS主要应对短时停电和电源质量问题，长时间供电通常还需配合发电机。"},{"id":"t0356","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"多重化技術","termZh":"多重化技术","english":"Multiplexing Technology","reading":"たじゅうかぎじゅつ","breadcrumb":"","explanationJa":"複数の信号やデータを一つの通信路を使って同時に送信する方法である。この技術を用いることで、通信の効率が向上し、帯域幅を最大限に活用できる。例えば、音声通話とデータ通信を同時に行う際に、各信号を適切に分けて一つの回線で送ることができる。このように、通信インフラの最適化やコスト削減につながるため、企業のネットワークやセキュリティ製品においても利用される。複数の通信を効率的に管理することで、より多くのトラフィックを処理でき、セキュリティを保ちながら快適な通信環境を提供することが可能になる。","explanationZh":"通过设置多个相同或可替代的设备、线路或处理资源，使单一组件故障时仍能继续提供服务的技术。它通过消除单点故障提高系统可用性和容错能力。"},{"id":"t0357","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"ストレージのミラーリング","termZh":"存储镜像","english":"Storage Mirroring","reading":"","breadcrumb":"","explanationJa":"データの冗長性を確保するための技術である。ミラーリングは、同じデータを複数のストレージデバイスに同時に保存するプロセスを指す。この方式により、あるデバイスに障害が発生しても、他のデバイスに保存されているデータを利用することで、情報の損失を防ぐことが可能となる。例えば、企業が重要なデータを持つサーバを運用する際、ミラーリングを利用することで、データの可用性を高め、ビジネスの連続性を保証することができる。また、ミラーリングはバックアップ手法の一部としても機能し、データの安全性を確保する助けとなる。","explanationZh":"把相同数据同时写入两个或多个存储设备，保持实时或近实时副本的冗余技术。一个设备故障时可由镜像副本继续提供数据，但镜像不能替代独立备份，因为逻辑删除或勒索加密也可能同步复制。"},{"id":"t0358","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"セキュリティゾーニング","termZh":"安全分区／安全区域划分","english":"Security Zoning","reading":"","breadcrumb":"","explanationJa":"物理的なセキュリティ対策の一つで、特定の区域を安全性に応じて分ける方法である。これにより、情報や資産へのアクセスを制限し、リスクを軽減することができる。具体的には、異なるゾーンには異なるレベルのアクセス権が設定されることが多く、一番厳重なゾーンには重要なデータや資産が保管され、一般のアクセスが制限される。一方、低リスクのゾーンにはより多くの人が自由に出入りできる。このように、物理的なアクセス制御をゾーンごとに明確に分けて管理することは、効果的なセキュリティ戦略の一部であり、潜在的な脅威から資産を保護する手段として機能する。","explanationZh":"根据资产敏感度、业务功能和信任级别把网络或物理环境划分为不同安全区域，并对区域之间的通信实施严格控制。分区可减少攻击面并限制入侵后的横向移动。"},{"id":"t0359","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"監視カメラ","termZh":"监控摄像机","english":"Surveillance Camera","reading":"かんしかめら","breadcrumb":"","explanationJa":"特定の場所を見守るために設置されるカメラである。これにより、リアルタイムで映像を記録したり、監視したりすることが可能で、安全性を高める役割を果たす。例えば、商業施設や公共の場、家庭において、侵入者の確認や不審者の監視に利用されることが多い。映像データを保存するだけでなく、動体検知や顔認識といった機能を備えているものもあり、異常を即座に通知する仕組みを持つ製品も存在する。これにより、セキュリティの向上が図られ、人や物の安全を守るのに効果的である。","explanationZh":"用于记录和监视设施出入口、机房等区域活动的物理安全设备。它可起到威慑、异常发现和事后取证作用，但应同时考虑拍摄范围、录像保存、访问权限和隐私保护。"},{"id":"t0360","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"インターロック","termZh":"互锁门禁（Interlock）","english":"Interlock","reading":"","breadcrumb":"","explanationJa":"物理的セキュリティ対策の一つであり、複数のシステムや装置が相互に作用し合うことで、特定の操作を防止または制限する仕組みである。例えば、監視カメラや入退室管理システムが連携し、無断での立ち入りを阻止することができる。インターロックが適用される場面では、許可された手順を踏まなければ次のステップに進まない仕組みを持つことが一般的で、これによってセキュリティ事故や不正アクセスのリスクを低減することができる。たとえば、化学プラントにおいては、危険な操作を行うためには特定の手順を満たす必要があり、その手順が守られない限り機器が動作しないようにすることが考えられる。これにより、安全が確保されるのである。","explanationZh":"一种通过两道或多道门相互联动，防止同时开启并限制尾随进入的物理访问控制机制。常用于高安全区域，可在人员通过一扇门后完成确认再开启下一扇门。"},{"id":"t0361","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"施錠管理","termZh":"锁具管理","english":"Lock Management","reading":"せじょうかんり","breadcrumb":"","explanationJa":"物理的またはデジタルな空間においてアクセスを制御するための手法やシステムのことを指す。特定の場所や情報に対する不正アクセスを防ぐために、鍵や電子ロック、アクセス制御システムを用いる。例えば、オフィスの入り口に設置された電子ロックでは、特定のカードや暗証番号を使用してのみ入室を許可することができる。このような施策は、企業の財産やデータを保護するために非常に重要であり、特に重要な情報や機密文書が扱われる場所での導入が求められる。物理的セキュリティとデジタルセキュリティの両方に関連し、適切に実施することで、リスクを大幅に軽減することが可能である。","explanationZh":"对钥匙、门锁、电子锁和开锁权限进行分配、保管、登记、回收和定期检查的管理。其目的在于确保只有授权人员能够进入受保护区域，并在人员变动或钥匙遗失时及时取消权限。"},{"id":"t0362","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"入退室管理","termZh":"出入管理","english":"Access Control Management","reading":"にゅうたいしつかんり","breadcrumb":"","explanationJa":"特定の場所への立ち入りや退出を監視し、制御するためのシステムである。この管理は、主に企業や施設において、セキュリティを強化する目的で導入される。たとえば、社員証やカードを用いて、許可された人物だけが特定のエリアに入れるようにすることで、不正アクセスを防止する。さらに、入退室の履歴を記録することで、後からの追跡や分析が可能となり、セキュリティ上のリスクを低減することに寄与する。また、顔認識技術や指紋認証といったバイオメトリクス技術を組み合わせることで、より厳密な管理が実現できる。これにより、企業の安全性が向上し、従業員や顧客にとっても安心できる環境が提供される。","explanationZh":"对人员进入和离开受控区域进行身份确认、授权、记录和监控的管理。可使用门禁卡、生物识别、访客登记和陪同制度等，以防止未授权人员进入机房等重要场所。"},{"id":"t0363","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"クリアデスク","termZh":"清洁桌面（Clear Desk）","english":"Clear Desk","reading":"","breadcrumb":"","explanationJa":"オフィスや作業環境において、重要な情報や資料が外部から見える状態を避けるために、作業が終わった後にデスク上を整理し、不要なものを排除する手法である。この取り組みは、情報漏洩や不正アクセスを防ぐ目的で行われ、機密情報を扱う企業や組織において特に重要視される。具体的には、パソコンの画面ロックや書類のシュレッダー処理、デスク上に個人情報や機密文書を置かないことなどが含まれる。クリアデスクを実践することで、職場のセキュリティが向上し、リスクを低減させることが可能となる。これにより、従業員が安心して業務に集中できる環境を整えることができる。","explanationZh":"要求员工离开座位或下班时，不在桌面暴露机密文件、认证信息和可移动介质的管理规则。敏感资料应收纳到上锁位置，以降低被查看、拍摄、盗取或误丢的风险。"},{"id":"t0364","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"クリアスクリーン","termZh":"清洁屏幕（Clear Screen）","english":"Clear Screen","reading":"","breadcrumb":"","explanationJa":"情報システムにおける物理的セキュリティ対策の一つであり、使用しないコンピュータや端末の画面をロックすることを指す。これは、他人が無断で情報を閲覧できないようにするための重要な手段である。離席時や業務終了時にパソコンを放置せず、必ず画面をロックしておくことによって、盗み見や不正操作を防ぐことができる。このように、クリアスクリーンは情報漏洩を防止するために欠かせない対策とされており、組織全体でのセキュリティ意識の向上にも寄与する。","explanationZh":"要求无人使用终端时锁定屏幕，并避免在显示器上长期暴露敏感信息的管理规则。可配合自动锁屏、隐私屏和适当的工位布局，防止他人未经授权查看或操作系统。"},{"id":"t0365","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"遠隔バックアップ","termZh":"异地备份","english":"Remote Backup","reading":"えんかくばっくあっぷ","breadcrumb":"","explanationJa":"データを別の場所に保存する手法の一つである。この手法では、ネットワークを介して自宅やオフィスのデータを遠く離れたサーバやクラウドサービスに自動的にコピーする。例えば、事務所で作成した文書や画像ファイルを、インターネットを通じて安全な遠隔地のサーバにバックアップすることで、万一のデータ損失から保護される。ハードウェアの故障や自然災害に対する備えとして非常に重要であり、データの安全性を向上させるために多くの企業や個人が利用している。さらに、リストアが簡単に行えるため、迅速なデータ復旧が可能となり、業務の継続性が保たれる。","explanationZh":"把备份副本存放在与生产系统物理或逻辑隔离的远程地点，以避免同一火灾、洪水、勒索软件或场地事故同时破坏生产数据和备份。应定期验证备份可恢复性和传输、存储安全。"},{"id":"t0366","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"USBキー","termZh":"USB安全密钥","english":"USB Key","reading":"ゆーえすびーきー","breadcrumb":"","explanationJa":"セキュリティを強化するためのデバイスの一つである。物理的にコンピュータのUSBポートに接続することで認証を行うシステムで、特に重要なデータやシステムへのアクセスを制限する目的で使用される。例えば、特定のUSBキーを持つユーザーのみが機密情報にアクセスできるため、パスワードだけでは防ぎきれないリスクを軽減する効果がある。このデバイスは、オンラインバンキングや企業のネットワークアクセスなど、セキュリティが重視される場面で利用されることが多い。また、USBキーは持ち運びが容易で、使用する際にはソフトウェアとの連携が必要な場合もあるため、安全で便利な方法といえる。","explanationZh":"通过USB接口连接、用于身份认证、密钥保存或访问控制的硬件设备。若作为硬件安全密钥使用，可配合公钥认证降低钓鱼风险；同时应做好设备丢失、登记和备用方案管理。"},{"id":"t0367","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"セキュリティケーブル","termZh":"安全钢缆锁","english":"Security Cable","reading":"","breadcrumb":"","explanationJa":"主にコンピュータや周辺機器を盗難から防ぐための製品である。これらのケーブルは、特別なロック機構を持っており、機器を固定することで持ち去りを難しくする。たとえば、ノートパソコンに取り付けられたデスクや椅子などの固定物に繋ぐことができ、簡単に外れることはない。オフィスや学校などの公共の場で特に役立つため、業務用機器や個人の機器を安全に保つ手段として広く利用されている。また、これにより不正アクセスやデータ盗難も一定程度防ぐことができる。さまざまな形状や長さで提供されており、用途に応じて選択することができる。","explanationZh":"把笔记本电脑等设备固定在桌面或固定物上的物理防盗装置。它不能保护设备内数据本身，因此还应结合磁盘加密、屏幕锁和资产管理等措施。"},{"id":"t0368","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"記憶媒体の管理","termZh":"存储介质管理","english":"Memory Media Management","reading":"きおくばいたいのかんり","breadcrumb":"","explanationJa":"データを保存するための物理的な装置やメディアを効果的に管理するプロセスである。具体的には、ハードディスク、SSD、USBメモリなど多様な記憶媒体に対して、アクセス制御やデータの暗号化、バックアップといったセキュリティ対策が含まれる。例えば、重要なデータが格納されたUSBメモリに対し、暗号化を施すことで、不正アクセスを防ぐことができる。データの安全性を確保し、情報漏洩やウイルス感染などのリスクを低減するために必要不可欠なものであり、組織の情報セキュリティ戦略の重要な要素となる。","explanationZh":"对U盘、硬盘、光盘等介质的领用、标识、保管、携带、复制、借出、归还和销毁进行控制。敏感数据介质应使用加密、访问限制和安全擦除，以防丢失或泄露。"},{"id":"t0369","chapterId":"c04","chapterJa":"情報セキュリティ対策","chapterZh":"信息安全对策","termJa":"装置のセキュリティを保った処分又は再利用","termZh":"设备的安全处置或再利用","english":"Security Disposal or Reuse of Devices","reading":"そうちのせきゅりてぃをたもったしょぶんまたはさいりよう","breadcrumb":"","explanationJa":"不要になった電子機器やデータを安全に取り扱う方法を指す。このプロセスは、機器に保存されている機密情報を守るために非常に重要である。たとえば、企業が古いパソコンを処分する際には、ハードディスクのデータを完全に削除するか、物理的に破壊する必要がある。また、再利用する場合も、データが漏洩しないように適切なセキュリティ対策を講じることが求められる。このように、装置を適切に廃棄または再利用することで、情報漏洩のリスクを最小限に抑えることができ、組織のセキュリティを高く保つことが可能である。","explanationZh":"设备报废、转让或重新分配前，确保其中的敏感数据无法被原使用者之外的人员恢复。可采用安全擦除、密码学擦除、介质消磁或物理销毁，并保留处置记录。"},{"id":"t0370","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"IPsec","termZh":"IPsec","english":"Internet Protocol Security","reading":"あいぴーせっく","breadcrumb":"","explanationJa":"インターネット上でデータを暗号化し、通信の安全性を確保するプロトコルの集合である。パケットレベルでのセキュリティを提供し、データの盗聴や改ざんを防ぐことができる。たとえば、企業がリモートで安全に内部ネットワークにアクセスするために、VPN（バーチャルプライベートネットワーク）でよく使用される。二つの主要なモード、トンネルモードとトランスポートモードを用意しており、適用する場面によって使い分けることが可能である。これにより、ユーザーとサーバ間やサイト間での安全な通信を実現し、インターネット環境におけるセキュリティを強化する役割を果たす。","explanationZh":"在IP层提供认证、完整性保护和加密的协议套件，常用于构建站点到站点或远程访问VPN。IPsec可通过AH、ESP以及密钥交换机制保护网络层通信，应用通常无需感知底层加密。"},{"id":"t0371","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"TLS","termZh":"TLS","english":"Transport Layer Security","reading":"てぃーえるえす","breadcrumb":"","explanationJa":"インターネット上でデータの安全性を保証するためのプロトコルである。主に、Webサイトとブラウザ間の通信を暗号化する役割を果たし、情報漏洩や改ざんを防ぐために使用される。例えば、オンラインショッピングや金融取引を行う際、TLSにより入力したクレジットカード情報やパスワードが第三者に見られることなく、安全に送信される。旧来のSSL（Secure Sockets Layer）の後継技術であり、より強固なセキュリティを提供するための様々な暗号化技術を採用している。これにより、インターネット上での信頼性の高い通信が実現され、多くのオンラインサービスにおいて不可欠な存在となっている。","explanationZh":"用于在客户端与服务器之间建立加密和认证通信的安全协议。TLS通过证书、公钥密码和对称加密保护通信的机密性与完整性，广泛用于HTTPS、邮件和各种应用协议。"},{"id":"t0372","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"SSL/TLS","termZh":"SSL/TLS","english":"Secure Sockets Layer / Transport Layer Security","reading":"えすえすえる/てぃーえるえす","breadcrumb":"","explanationJa":"インターネット上でのデータ通信を安全に行うためのプロトコルである。SSLは最初に開発されたセキュリティプロトコルであり、その後TLSに進化することで、より強固な暗号化と認証の仕組みを提供する。たとえば、WebサイトがSSL/TLSを使用すると、ブラウザとサーバ間で送受信されるデータが暗号化され、第三者による盗聴や改ざんから保護される。これにより、オンラインショッピングや個人情報のやり取りが安全に行えるようになる。HTTPSプロトコルで一般的に利用されており、Webサイトの信頼性を示す重要な要素とされている。","explanationZh":"用于保护网络通信的加密协议统称。SSL为较早的协议并已被淘汰，现代系统应使用安全版本的TLS；它通过服务器或双向认证、密钥协商和加密确保传输数据不易被窃听或篡改。"},{"id":"t0373","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"SSH","termZh":"SSH安全外壳协议","english":"Secure Shell","reading":"えすえすえいち","breadcrumb":"","explanationJa":"ネットワークを通じて安全に通信するためのプロトコルである。通常、リモートコンピュータへの接続や管理を行う際に使用され、データの暗号化を行うことでセキュリティを確保する。このプロトコルは、クライアントとサーバ間で情報を安全にやり取りするため、パスワードやファイルの送信時に第三者による盗聴を防ぐことができる。たとえば、Linuxサーバの管理者がSSHを使用してリモートアクセスすることで、安全にコマンドを実行したり、ファイルを転送したりすることができる。インターネット上の通信の信頼性を向上させるため、広く利用されている。","explanationZh":"用于安全远程登录、命令执行、文件传输和隧道转发的加密协议。SSH可以使用密码或公钥认证，并对通信内容进行加密和完整性保护，是替代Telnet等明文远程管理协议的重要技术。"},{"id":"t0374","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"HTTPS","termZh":"HTTPS","english":"HTTP over TLS","reading":"えいちてぃーてぃーぴーえす","breadcrumb":"","explanationJa":"Web上で安全にデータを送受信するためのプロトコルである。HTTPにTLS（Transport Layer Security）という暗号化技術を組み合わせたもので、データ通信が第三者に盗み見られないように保護される。このプロトコルでは、ユーザーがWebサイトにアクセスする際に、データが暗号化され、セキュリティが確保される。例えば、オンラインバンキングやショッピングサイトでは、個人情報やクレジットカード情報を安全に扱うためにHTTPSが使用される。また、Webブラウザでは、アドレスバーに鍵マークが表示されることで、ユーザーはそのサイトが安全であることを確認できる。これにより、安心してインターネットを利用できる環境が整えられている。","explanationZh":"在TLS之上运行的HTTP，用于保护浏览器与Web服务器之间通信。它通过服务器证书验证身份，并对请求和响应加密和完整性保护，可降低窃听和中间人篡改风险。"},{"id":"t0375","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"WPA2","termZh":"WPA2","english":"Wi-Fi Protected Access 2","reading":"だぶるぴーえーつー","breadcrumb":"","explanationJa":"無線LANにおけるセキュリティプロトコルの一つである。Wi-Fiネットワークに接続する際のデータの暗号化と認証を提供し、ネットワークの安全性を高める役割を果たす。このプロトコルは、暗号化方式としてAES（Advanced Encryption Standard）を使用しており、特に高いセキュリティレベルを実現している。たとえば、家庭や企業のWi-FiネットワークでWPA2を用いることで、外部からの不正アクセスを防ぎ、データの盗聴や改ざんを防ぐことができる。そのため、WPA2は現在の無線ネットワークで最も広く使用されているセキュリティ規格である。","explanationZh":"第二代Wi-Fi保护接入安全标准，广泛使用AES-CCMP等机制保护无线局域网通信。家庭和企业环境可分别采用预共享密钥或802.1X认证；安全性仍取决于强密码、正确配置和及时更新。"},{"id":"t0376","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"WPA3","termZh":"WPA3","english":"Wi-Fi Protected Access 3","reading":"だぶるぴーえーすりー","breadcrumb":"","explanationJa":"無線LANのセキュリティプロトコルの一つである。Wi-Fiネットワークにおける通信の安全性を高めるために設計されており、暗号化の強化や、パスワードの盗難に対する防御機能を備えている。具体的には、より強力な認証方式を提供し、簡易なパスワードでも安全な接続を実現するための「Easy Connect」機能を持つ。これにより、IoTデバイスなどの接続が容易になりつつも、セキュリティが保たれる。また、高度な暗号化により、情報の漏洩を防ぐことができるので、特に公共のWi-Fi環境においてその効果が期待される。次世代のWi-Fiネットワークでの安定した通信を支える重要な技術である。","explanationZh":"较WPA2进一步增强的无线网络安全标准。个人模式采用SAE等机制提高对离线密码猜测的抵抗力，并强化部分加密和管理保护；支持设备时应优先使用安全配置的WPA3。"},{"id":"t0377","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"ベイジアンフィルタリング","termZh":"贝叶斯过滤","english":"Bayesian Filtering","reading":"","breadcrumb":"","explanationJa":"確率論に基づいて情報を分析し、データの中から特定のパターンを識別する手法である。この技術は、特にスパムメールのフィルタリングやユーザーの行動予測において広く使われている。たとえば、メールサービスでは、受信したメッセージがスパムかどうかを判断するために、過去のデータを元に確率を計算し、スパムと判定される基準をスピーディに更新する。この手法により、時間が経つにつれ、フィルタはより精度高くなり、ユーザーにとって重要な情報を見落とす可能性が減少する。また、ベイジアンフィルタリングは認証や認可のシステムにも応用でき、ユーザーの信頼性や行動パターンを基に、アクセス権の判断を行うことも可能である。","explanationZh":"利用贝叶斯统计根据邮件中词语和特征出现概率判断其属于垃圾邮件或正常邮件的方法。系统可根据训练样本持续更新概率，但需要处理误报、概念漂移和攻击者规避等问题。"},{"id":"t0378","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"送信元ドメイン認証","termZh":"发件域认证","english":"Sender Domain Authentication","reading":"そうしんもとどめいんにんしょう","breadcrumb":"","explanationJa":"電子メールの送信者が本当にそのドメインからの送信であるかを確認するための技術である。この認証は、スパムやフィッシング詐欺への対策として重要であり、受信者が信頼できる送信者からのメールを受け取ることを保証する。具体的には、送信元ドメインが正しく設定されているかを確認する手法には、SPF（Sender Policy Framework）やDKIM（DomainKeys Identified Mail）などがある。これらの技術は、メールが正規の送信者から送信されたかを検証し、偽の送信者を特定するのに役立つことで、高いセキュリティを確保するために広く用いられている。","explanationZh":"验证电子邮件是否确实由声称的发送域授权或签名的机制集合。主要技术包括SPF、DKIM和DMARC，可减少域名冒用和邮件欺骗，但不能单独判断邮件内容是否可信。"},{"id":"t0379","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"SPF","termZh":"SPF","english":"Sender Policy Framework","reading":"えすぴーえふ","breadcrumb":"","explanationJa":"電子メールの送信者を認証するための技術である。この仕組みでは、送信者のドメインがどのメールサーバからメールを送ることが許可されているかを定義するためのDNSレコードを使用する。例えば、ある企業が自身のドメインを使って電子メールを送信する際、その企業が指定したサーバからのメールのみが正当なものであることを確認できる。これにより、なりすましやスパムメールのリスクを減少させることができる。受信者側は、メールが正しいサーバから送信されたかどうかをチェックし、不正なメールを弾くことが可能になる。このように、SPFはメールの信頼性を向上させ、利用者の安全を守る役割を果たしている。","explanationZh":"由域名所有者在DNS中声明允许哪些邮件服务器代表该域发送邮件的机制。收件服务器检查连接方IP是否符合声明，以发现部分发件域伪造；邮件转发等场景可能影响判断。"},{"id":"t0380","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"DKIM","termZh":"DKIM","english":"DomainKeys Identified Mail","reading":"でぃーきむ","breadcrumb":"","explanationJa":"メールの送信元を認証し、内容の改ざんを防ぐための技術である。この技術では、送信側のドメインが電子署名を用いてメールのヘッダーに認証情報を追加する。受信側はこの情報を元に、メールが本当にそのドメインから送られたものであるかどうかを確認する。例えば、企業が送信するメールにDKIMを設定することで、そのメールが本物であると受信者に信頼を与え、フィッシング詐欺などのリスクを減少させることができる。また、DKIMはスパム対策にも有効で、メールの信頼性を高め、受信箱にきちんと届けられる確率を上げる役割を果たす。","explanationZh":"发件服务器使用域的私钥对邮件部分内容进行数字签名，收件方通过DNS中公布的公钥验证签名的机制。它能够确认邮件在传输中未被相关部分篡改，并证明签名域承担发送责任。"},{"id":"t0381","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"DMARC","termZh":"DMARC","english":"Domain-based Message Authentication, Reporting & Conformance","reading":"でぃーまーく","breadcrumb":"","explanationJa":"メールの送信者を確認し、なりすましやフィッシングを防ぐための認証技術である。これにより、送信者が正当なドメインを使用しているかを確かめ、受信側が受け取ったメールの信頼性を判断する手助けを行う。具体的には、DMARCはSPF（Sender Policy Framework）やDKIM（DomainKeys Identified Mail）といった他の認証技術と連携して動作する。例えば、ある企業が自社のメールをDMARCで管理している場合、受信者はそのメールが本当にその企業から送られたものであるかを簡単に確認できる。これにより、受信者はフィッシング攻撃のリスクを軽減でき、安全なメール通信を実現することができる。","explanationZh":"基于SPF和DKIM结果以及发件人域对齐关系制定邮件认证策略和报告机制。域所有者可声明认证失败邮件应监控、隔离或拒收，并接收汇总报告，从而降低域名被冒用于钓鱼邮件的风险。"},{"id":"t0382","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"SMTP-AUTH","termZh":"SMTP认证（SMTP-AUTH）","english":"SMTP Authentication","reading":"えすえむてぃーぴーおーす","breadcrumb":"","explanationJa":"メール送信における認証手段の一つである。この仕組みでは、メールクライアントがサーバに接続する際に、ユーザー名やパスワードを使って本人確認を行う。例えば、GmailやYahooメールなどのサービスでは、SMTP-AUTHを用いることで、正当なユーザーのみがメールを送信できるようにしている。これにより、スパムメールや不正利用を防ぎ、ユーザーが安全にメールを利用できる環境を提供する。さらに、他の認証方法と組み合わせることも可能で、セキュリティを高めるための重要な役割を果たしている。","explanationZh":"邮件客户端向SMTP服务器发送邮件前进行用户身份认证的机制。它用于防止未授权人员利用邮件服务器发送邮件，并可配合TLS保护认证信息和邮件提交过程。"},{"id":"t0383","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"OP25B","termZh":"出站25端口封锁（OP25B）","english":"Outbound Port 25 Blocking","reading":"おーぴーにじゅーごびー","breadcrumb":"","explanationJa":"インターネットサービスプロバイダー（ISP）が導入する技術の一つである。この技術は、スパムメールの送信を防ぐために、メールを送る際に使用されるポート25をブロックするものである。通常、ポート25はSMTP（Simple Mail Transfer Protocol）というプロトコルを利用してメールを送信する際に使用されるが、大量のスパムがこのポートを介して発信されることが多いため、ISPはそれを制限することによって、利用者の利便性やインターネット環境の安全性を向上させる。OP25Bの導入により、正常なメールもスパムフィルターの影響を受けることがあるが、メール送信には他のポート（例えば587や465）を利用することができます。このように、OP25Bはインターネットの健全な利用を促進するための重要な措置である。","explanationZh":"互联网服务提供商阻止普通用户直接向外部邮件服务器的TCP 25端口发送邮件，并要求通过指定邮件提交服务器认证发送的措施。它可减少感染终端直接大量发送垃圾邮件。"},{"id":"t0384","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"PGP","termZh":"PGP","english":"Pretty Good Privacy","reading":"ぴーじーぴー","breadcrumb":"","explanationJa":"電子メールやファイルの暗号化を通じて、データを安全に保護するための技術である。情報を送信する際に他者に見られないようにするために、特別な暗号化アルゴリズムを使用し、受信者だけが解読できるようになっている。例えば、重要な書類や個人情報を送信する際、この技術を利用することで、情報が悪意のある第三者に読み取られるリスクを大幅に減少させることができる。また、PGPは公開鍵暗号方式を採用しており、ユーザーは公開鍵と秘密鍵を用いて暗号化と復号を行う。この仕組みにより、安全な通信が保証され、プライバシーの確保が可能になる。","explanationZh":"一种用于电子邮件和文件加密、数字签名的密码技术和软件体系。它通常采用混合加密，并通过公钥和私钥保护内容机密性、完整性与发送者真实性；其信任模型可采用Web of Trust等方式。"},{"id":"t0385","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"S/MIME","termZh":"S/MIME","english":"Secure/Multipurpose Internet Mail Extensions","reading":"えすまいむ","breadcrumb":"","explanationJa":"電子メールのセキュリティを強化するための技術である。この技術は、メールの内容を暗号化し、送信者の身元を確認するためのデジタル署名を提供する。つまり、受信者は送信者が本当にその人物であるかを確認でき、同時に情報が第三者に漏れることを防ぐことができる。具体例としては、企業が重要な情報を外部に送信する際、S/MIMEを使うことで、機密性を保持しつつ安全にコミュニケーションを行うことが挙げられる。このように、S/MIMEは安全な電子メール通信に欠かせない技術で、ビジネスや個人のやり取りにおいて非常に重要な役割を果たしている。","explanationZh":"基于数字证书和公钥基础设施，对MIME电子邮件进行加密和数字签名的标准。它可实现邮件内容的机密性、完整性、发送者认证和不可否认性，常用于企业邮件环境。"},{"id":"t0386","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"パケットフィルタリング","termZh":"数据包过滤","english":"Packet Filtering","reading":"","breadcrumb":"","explanationJa":"ネットワークセキュリティの手法の一つで、ネットワークを流れるデータパケットを監視し、特定の基準に基づいてその通過を制御する技術である。具体的には、パケットの送信元や宛先のIPアドレス、プロトコルの種類、ポート番号などの情報を元に、許可するか拒否するかを判断する。この手法はファイアウォールにおいて広く利用されており、不正アクセスや攻撃からネットワークを守るための第一防衛線となる。例えば、特定のポートに対するすべての外部からの接続を遮断することで、サーバへの攻撃を未然に防ぐことができる。","explanationZh":"根据源／目的IP地址、端口、协议、连接状态等报文头信息决定允许或丢弃网络数据包的访问控制方式。它是防火墙的基础功能之一，但对应用层内容的理解通常有限。"},{"id":"t0387","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"MACアドレスフィルタリング","termZh":"MAC地址过滤","english":"MAC Address Filtering","reading":"まっくあどれすふぃるたりんぐ","breadcrumb":"","explanationJa":"ネットワークセキュリティの一手法であり、特定のデバイスがネットワークに接続できるかどうかを判断するために、機器のMACアドレス（メディアアクセスコントロールアドレス）を利用することである。各デバイスには固有のMACアドレスが設定されており、これを基に接続の許可や拒否を行う。例えば、家庭用ルーターでは、信頼できるデバイスのMACアドレスを登録することで、そのデバイスのみがインターネットに接続できるよう設定することができる。この仕組みにより、不正アクセスを防ぎ、より安全なネットワーク環境を構築することが可能になる。しかし、MACアドレスは容易に偽装できるため、他のセキュリティ対策と併用することが望ましい。","explanationZh":"根据设备网卡的MAC地址决定是否允许其接入网络的控制方式。由于MAC地址可被伪造，它只能作为辅助措施，不能替代强身份认证和加密。"},{"id":"t0388","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"認証サーバ","termZh":"认证服务器","english":"Authentication Server","reading":"にんしょうさーば","breadcrumb":"","explanationJa":"ユーザーやデバイスの身元を確認し、アクセス権を管理するためのサーバである。認証プロセスは、ユーザーが提供した情報、例えばユーザー名とパスワードを基に行われ、これによりアクセスが許可される。また、単にログインを確認するだけでなく、多要素認証などを用いてセキュリティを強化することも可能である。これにより、認証サーバはネットワークセキュリティの重要な一役を担い、データやシステムへの不正アクセスを防ぐのに不可欠な存在となっている。企業や組織において、ユーザー管理やアクセス制御を円滑に行うための基盤としても重要である。","explanationZh":"集中验证用户或设备身份并向其他系统提供认证结果的服务器。常见实现包括RADIUS、LDAP目录、身份提供商等，可统一账号策略、多因素认证和访问控制。"},{"id":"t0389","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"認証VLAN","termZh":"认证VLAN","english":"Authentication VLAN","reading":"にんしょうぶいらん","breadcrumb":"","explanationJa":"ネットワークにおいてユーザーやデバイスの認証を行うための特別なVLAN（仮想LAN）のことを指す。このVLANは、まずネットワークに接続を試みるデバイスが正当なものであるかどうかを確認する役割を持つ。例えば、企業内のネットワークに従業員のデバイスが接続される際、初めに認証VLANに配置され、正当な資格情報を提供することで初めて通常のVLANにアクセスできるようになる。この仕組みにより、未承認のデバイスやユーザーがネットワークに不正にアクセスすることを防ぎ、安全性が高まる。また、802.1Xなどのプロトコルと連携して使用されることが多く、より強固なセキュリティを実現する。","explanationZh":"根据用户或设备认证结果动态分配到不同VLAN的网络访问控制方式。通过把访客、员工、不合规终端等放入不同网络区域，可实现细粒度隔离和权限控制。"},{"id":"t0390","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"VPN","termZh":"虚拟专用网（VPN）","english":"Virtual Private Network","reading":"ぶいぴーえぬ","breadcrumb":"","explanationJa":"安全な通信を行うためのネットワーク技術である。VPNは公共のインターネットを利用しながら、データを暗号化することで、プライバシーを保護し、外部からの不正アクセスを防ぐ。この技術を使うことで、リモートでの作業が安全に行え、自宅や外出先からも企業内ネットワークにアクセスすることができる。特に、旅行先や公共のWi-Fiを利用する際には、VPNを使うことで重要な情報を保護する手段として非常に有効である。また、地理的に制限されたコンテンツにアクセスするためにも利用されることが多く、ユーザーの自由度を高める役割も果たしている。","explanationZh":"通过公共或不可信网络建立加密隧道，使远程用户或不同站点能够像在私有网络中一样安全通信的技术。常见实现包括IPsec VPN和基于TLS的VPN，需要结合强认证和终端安全。"},{"id":"t0391","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"ハニーポット","termZh":"蜜罐","english":"Honeypot","reading":"","breadcrumb":"","explanationJa":"ネットワークセキュリティにおいて、攻撃者の行動を観察するための偽のシステムやサービスである。本来のシステムとは独立したもので、意図的に脆弱性を持たせることで、攻撃者を誘引し、その活動を記録する役割を果たす。例えば、企業のネットワークに設置された悪意のある攻撃者がアクセスしてきた際に、どのような技術や手法を用いるのかを分析し、実際のシステムを守るための対策を強化する材料となる。ハニーポットを利用することで、セキュリティの脆弱性を把握し、より効果的な防御策を構築することが可能になる。","explanationZh":"故意设置为具有吸引力或看似脆弱的诱捕系统，用于引诱攻击者、观察攻击手法并产生预警。蜜罐应与生产环境严格隔离和监控，避免被攻击者利用为攻击跳板。"},{"id":"t0392","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"リバースプロキシ","termZh":"反向代理","english":"Reverse Proxy","reading":"","breadcrumb":"","explanationJa":"クライアントとサーバの間に位置し、クライアントのリクエストを受け取り、それを適切なサーバに転送する役割を持つサーバのことを指す。通常のプロキシサーバと異なり、リバースプロキシは外部からのアクセスを制御し、内部のサーバを直接公開しないため、セキュリティ上の利点がある。例えば、複数のサーバが存在するWebサービスにおいて、リバースプロキシを利用することで、負荷分散を行ったり、SSL暗号化を一元管理することが可能となる。また、リバースプロキシはキャッシュ機能を持つことも多く、ユーザーのリクエストに対する応答速度を向上させる効果が期待される。","explanationZh":"位于客户端与后端服务器之间、代表服务器接收请求并转发的代理组件。它可隐藏后端、实现负载均衡、TLS终止、缓存和访问控制，并可与WAF等安全能力结合。"},{"id":"t0393","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"データベース暗号化","termZh":"数据库加密","english":"Database Encryption","reading":"でーたべーすあんごうか","breadcrumb":"","explanationJa":"データベース内の情報を保護するために行われる技術の一つである。これは、特定のアルゴリズムを使用して、データを暗号化し、許可されていない者がアクセスできないようにする手法である。暗号化されたデータは、元の形式に戻すためには鍵が必要であり、これにより情報の漏洩や不正アクセスを防ぐことが可能となる。例えば、クレジットカード情報や個人情報など、特に機密性の高いデータに対してデータベース暗号化を施すことで、情報の安全性が飛躍的に向上する。また、多くの企業や組織が法律や規制に従ってデータを保護するための手段としても広く利用されている。","explanationZh":"对数据库中的敏感数据、数据文件、字段或备份实施加密，使未持有合法密钥者无法读取。应同时重视密钥管理、权限控制和性能影响，因为加密不能阻止具有合法解密权限者滥用数据。"},{"id":"t0394","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"データベースアクセス制御","termZh":"数据库访问控制","english":"Database Access Control","reading":"でーたべーすあくせすせいぎょ","breadcrumb":"","explanationJa":"データベースに対するアクセス権を管理し、利用者がどの情報にどのようにアクセスできるかを制限する仕組みを指す。この制御は、データの機密性や整合性を保護するために非常に重要である。たとえば、企業内のデータベースでは、管理者が特定のユーザーに対して閲覧や編集の権限を付与することで、重要な情報が無制限にアクセスされることを防ぐ。これにより、不正アクセスやデータ改ざんのリスクを低減できる。また、アクセス制御の方法には、役割に基づくアクセス制御（RBAC）や属性に基づくアクセス制御（ABAC）などがあり、用途に応じて適切な方式が選ばれる。","explanationZh":"根据用户、角色和业务需要限制对数据库对象和操作的访问。应采用最小权限、职责分离、强认证、特权账号管理和审计日志，防止未经授权的查询、修改或删除。"},{"id":"t0395","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"データベースバックアップ","termZh":"数据库备份","english":"Database Backup","reading":"","breadcrumb":"","explanationJa":"データベースに保存されている情報をコピーして、別の場所に保管するプロセスである。このバックアップは、データが消失したり、破損したりした場合に、元の状態に戻すために不可欠である。例えば、サーバ障害やウイルス感染、人的ミスなどにより、データが失われる可能性があるため、定期的にバックアップを行うことが推奨される。また、バックアップには全体をコピーするフルバックアップや、変更分のみをコピーする増分バックアップなど、複数の方法がある。それぞれの方法は、データ量や復元の速度、必要なストレージ量に応じて選択されるため、組織のニーズに応じた計画が重要である。","explanationZh":"为数据库创建可恢复副本，以应对误删除、故障、灾害和攻击。备份策略应考虑完整、增量或差异备份、保存周期、异地或离线副本以及恢复测试，并保护备份数据本身。"},{"id":"t0396","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"ログの取得","termZh":"日志采集","english":"Log Acquisition","reading":"ろぐのしゅとく","breadcrumb":"","explanationJa":"システムやアプリケーションの動作状況やユーザーの行動を記録するプロセスである。この記録は、データベースやサーバなどにアクセスした際の操作内容、エラーメッセージ、トランザクションの履歴などが含まれ、問題の特定やセキュリティ上の監視に利用される。たとえば、システムに異常が発生した場合、ログを分析することでその原因を追究し、必要な対策を講じることができる。また、ログを適切に取得して保存することで、不正アクセスの検出や、コンプライアンスの確保にも役立つ。データベースセキュリティにおいては、これらのログ情報を活用することで、より安全な環境を維持することが重要である。","explanationZh":"从操作系统、应用、数据库、网络和安全设备等来源获取运行与安全日志的过程。采集时应保证时间同步、完整性、必要字段和安全传输，为监控、审计和事件调查提供可靠数据。"},{"id":"t0397","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"Webシステムのセキュリティ対策","termZh":"Web系统安全措施","english":"Web System Security Measures","reading":"うぇぶしすてむのせきゅりてぃたいさく","breadcrumb":"","explanationJa":"インターネット上で動作するアプリケーションやサービスを保護するための手段や技術を指す。これには、ユーザーのデータを守るための暗号化、マルウェアや不正アクセスからシステムを防ぐファイアウォールの設置、そして定期的なソフトウェアのアップデートが含まれる。具体的な対策としては、ユーザー認証を強化するパスワードポリシーの策定や、攻撃を検知するための侵入検知システムの導入などがある。これらの対策は、Webシステムの信頼性を向上させ、ユーザーの個人情報を適切に保護するために不可欠である。セキュリティ対策を怠ると、情報漏洩やサービス停止といった深刻な問題を引き起こす可能性があるため、継続的な見直しと改善が求められる。","explanationZh":"保护Web应用、Web服务器、数据库和相关网络免受攻击的综合措施。包括安全设计与编码、输入验证、身份认证和会话管理、TLS、WAF、补丁、最小权限、日志监控和定期测试等。"},{"id":"t0398","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"セキュアプログラミング","termZh":"安全编程","english":"Secure Programming","reading":"","breadcrumb":"","explanationJa":"安全なソフトウェアを作成するための技術や手法を指す。これは、プログラムの設計やコーディング段階で潜在的な脆弱性を事前に特定し、それを取り除くことを目指す。たとえば、ユーザーからの入力データに対して適切な検証を行うことで、予期しないデータがプログラムの動作を壊すリスクを減らすことができる。また、サイバー攻撃からアプリケーションを守るために欠かせない技術として広く認識されており、企業の情報資産やユーザーの個人情報を保護する上で重要な役割を果たしている。これにより、より安全なデジタル環境を実現することができる。","explanationZh":"在软件设计和编码过程中主动避免引入安全漏洞的开发实践。包括输入验证、输出编码、参数化查询、安全内存处理、正确认证授权、错误处理和秘密管理，并结合代码审查和安全测试。"},{"id":"t0399","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"バッファオーバーフロー対策","termZh":"缓冲区溢出防护","english":"Buffer Overflow Prevention","reading":"ばっふぁおーばーふろーたいさく","breadcrumb":"","explanationJa":"プログラムが指定したメモリ領域を超えてデータを書き込むことによって発生するセキュリティ上の脆弱性を防ぐための技術や手法を指す。この脆弱性は、攻撃者が悪意のあるコードを実行したり、システムを乗っ取ったりするために利用されることがある。対策としては、入力データの長さをチェックして上限を設けることが基本である。例えば、プログラムが一定のサイズのデータのみを扱えるように設計されている場合、そのサイズを超えるデータは明示的に拒否する。また、最新のプログラミング言語やコンパイラでは、バッファのサイズを自動的に管理する機能が組み込まれており、開発者はこれらの機能を活用することで、より安全なアプリケーションを作成できるようになっている。これにより、アプリケーションのセキュリティが大幅に向上する。","explanationZh":"防止程序向固定内存缓冲区写入超出边界的数据并被利用执行恶意代码的措施。可通过边界检查、安全语言或库、编译器保护、ASLR和DEP等多层机制降低风险。"},{"id":"t0400","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"クロスサイトスクリプティング対策","termZh":"跨站脚本（XSS）防护","english":"Cross-Site Scripting Prevention","reading":"くろすさいとすくりぷてぃんぐたいさく","breadcrumb":"","explanationJa":"Webアプリケーションのセキュリティ対策の一環であり、悪意のあるユーザーが他のユーザーのWebブラウザでコードを実行するのを防ぐための手法である。この攻撃は、通常、悪意のあるスクリプトをユーザーのブラウザで実行させ、個人情報の盗取や不正操作を行うことを目的としている。対策としては、ユーザーからの入力を適切にサニタイズ（不正なコードを無効化）したり、コンテンツセキュリティポリシーを設定して特定のスクリプト実行を制限したりする方法がある。これにより、Webアプリケーションの安全性が向上し、ユーザーのデータを守ることができる。","explanationZh":"防止不可信输入被浏览器当作脚本执行的措施。核心是根据输出上下文正确编码／转义，结合输入验证、模板自动转义、内容安全策略（CSP）和安全Cookie设置，避免仅依赖黑名单过滤。"},{"id":"t0401","chapterId":"c05","chapterJa":"セキュリティ実装技術","chapterZh":"安全实施技术","termJa":"SQLインジェクション対策","termZh":"SQL注入防护","english":"SQL Injection Countermeasure","reading":"えすきゅーえるいんじぇくしょんたいさく","breadcrumb":"","explanationJa":"データベースに対する攻撃手法の一つであるSQLインジェクションからシステムを守るための方法を指す。SQLインジェクション攻撃は、悪意のあるユーザーがデータベースに対して不正なSQL文を実行させることで、情報を盗んだり改ざんしたりする行為である。このような攻撃を防ぐための対策には、入力データの検証やサニタイズ、準備済みステートメントの利用が含まれる。たとえば、ユーザーからの入力をそのままSQL文に埋め込むのではなく、プレースホルダーを使ってパラメータを渡すことが一般的な対策となる。これにより、悪意のあるコードが実行されるリスクを大幅に減少させることができる。アプリケーションのセキュリティを強化するために非常に重要である。\nHOME»用語集»法務»知的財産権","explanationZh":"防止用户输入被拼接成数据库命令并改变SQL语义的措施。首选参数化查询／预编译语句，同时配合输入验证、最小数据库权限、错误信息控制和安全测试，避免用简单字符替换作为唯一防护。"},{"id":"t0402","chapterId":"c06","chapterJa":"知的財産権","chapterZh":"知识产权","termJa":"著作権法","termZh":"著作权法","english":"Copyright Law","reading":"ちょさくけんほう","breadcrumb":"","explanationJa":"創作物に対する権利を保護するための法律である。著作権は、著作者が自分の創作物を無断で使用されない権利を保障し、対価を得ることができるようにする。その範囲には、文学、音楽、映画、ソフトウェアなどが含まれ、著作者が自己の作品を利用する権利と他者が無断で使用しないためのルールを定めている。たとえば、作家が書いた本や音楽家が作曲した曲は、その著作権によって保護され、無断でコピーされたり改変されたりすることを防ぐ仕組みが存在する。創作活動を促進し、文化の発展に寄与する重要な要素でもある。","explanationZh":"保护文学、艺术、软件等作品著作权及相关权利的法律制度。对信息系统而言，复制、修改、分发软件和内容时必须遵守许可范围；未经授权复制或传播受保护作品可能构成侵权。"},{"id":"t0403","chapterId":"c06","chapterJa":"知的財産権","chapterZh":"知识产权","termJa":"コピープロテクト外し","termZh":"规避复制保护","english":"Copy Protection Removal","reading":"こぴーぷろてくとはずし","breadcrumb":"","explanationJa":"著作権で保護されたコンテンツから、その保護を解除する行為を指す。これにより、デジタル音楽や映画、ソフトウェアなど、コピーが制限されているコンテンツを自由に複製・使用できるようになる。しかし、この行為は著作権法に抵触する場合が多く、法律により禁止されていることがある。たとえば、音楽CDのコピー防止機能を解除することがこれに当たり、違法行為として処罰される可能性がある。法的な観点から見ると、コンテンツの所有者の権利を尊重することが求められており、コピープロテクトの外しは慎重に考慮する必要がある。","explanationZh":"绕过或解除用于限制数字内容复制、使用或访问的技术保护措施的行为。此类行为可能违反著作权及相关法律规定，因此在分析或操作前必须确认合法授权和适用的例外条件。"},{"id":"t0404","chapterId":"c06","chapterJa":"知的財産権","chapterZh":"知识产权","termJa":"営業秘密","termZh":"商业秘密","english":"Trade Secret","reading":"えいぎょうひみつ","breadcrumb":"","explanationJa":"企業が競争上の優位性を保つために重要な情報である。この情報は、秘密管理性、つまり適切に管理されていること、有用性、すなわち経済的な価値を持つこと、非公知性、つまり一般に知られていないことの3つの要件を満たす必要がある。例えば、企業の製品の製造方法や顧客リストは、これらの要件をクリアする場合に営業秘密とされる。企業にとって戦略的な資産であり、これを不正に使用または開示された場合には法的保護が与えられることが多い。このため、企業は情報の管理体制を整備し、従業員に対しても教育を行うことが求められる。","explanationZh":"具有秘密性、经济价值并由权利人采取合理保密措施管理的技术或经营信息。企业应通过访问控制、保密协议、分类管理和日志等保护商业秘密，防止非法获取、使用或披露。"},{"id":"t0405","chapterId":"c06","chapterJa":"知的財産権","chapterZh":"知识产权","termJa":"ドメイン名の不正取得","termZh":"域名非法取得／域名劫持","english":"Domain Name Hijacking","reading":"どめいんめいのふせいしゅとく","breadcrumb":"","explanationJa":"他人が所有するドメイン名を不正に取得する行為を指す。この行為は、通常、悪意のある目的で行われ、例えば他人のWebサイトを模倣したり、フィッシング詐欺を行ったりする際に利用される。ドメイン名は、インターネット上の住所のようなものであり、企業や個人のブランドを表す重要な要素であるため、その不正取得は深刻な問題となる。多くの国では、この行為は法律により禁止されており、被害者は法的手段を講じることができる。適切な対策としては、ドメイン名の登録情報を定期的に確認することや、不正アクセスを防ぐためのセキュリティ対策が推奨される。\nHOME»用語集»法務»セキュリティ関連法規","explanationZh":"通过欺诈、账号侵入、注册信息篡改或恶意抢注等方式非法取得或控制他人域名的行为。可能导致网站和邮件被重定向、钓鱼和品牌损害，因此需要保护注册商账号、启用MFA并管理域名锁定等措施。"},{"id":"t0406","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"サイバーセキュリティ基本法","termZh":"日本《网络安全基本法》","english":"Cyber Security Basic Act","reading":"さいばーせきゅりてぃきほんほう","breadcrumb":"","explanationJa":"日本国内におけるサイバーセキュリティの確保を目的とした法律である。この法律は、国や地方公共団体、企業の情報システムを保護し、サイバー攻撃に対する備えを強化することを求めている。具体的には、情報通信技術の普及に伴い、様々なリスクが増加する中で、国民の安全を守るための枠組みを提供する。例えば、情報セキュリティに関する責任の明確化や、関係機関の連携を促進するための方針も含まれており、これに基づく様々な施策が進められている。この法律は、私たちの日常生活やビジネスにおける安全性を高めるために重要である。","explanationZh":"日本网络安全政策的基础性法律，规定国家网络安全政策的基本理念、责任分工和推进体制。它为政府制定网络安全战略、组织协调以及政府和相关主体开展安全措施提供法律基础。"},{"id":"t0407","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"サイバーセキュリティ戦略","termZh":"网络安全战略","english":"Cybersecurity Strategy","reading":"さいばーせきゅりてぃせんりゃく","breadcrumb":"","explanationJa":"サイバーセキュリティ基本法に基づき、情報社会の安全を確保するための国家の総合的な方針を示すものである。この戦略は、サイバー攻撃から国民や企業、公共インフラを保護し、情報セキュリティの基盤を強化することを目的としている。具体的には、リスクの評価や対策の実施、教育の推進、国際協力の強化などが盛り込まれている。例えば、サイバー犯罪に対して法的対処を強化したり、企業に対するセキュリティ対策の指導を行ったりすることが含まれる。デジタル社会が進化する中で、脅威に対抗するための重要な枠組みを提供している。","explanationZh":"国家或组织为应对网络威胁、提高韧性和保护重要资产而制定的中长期方针和重点措施。通常明确治理目标、人才、技术、关键基础设施、事件响应、国际合作等方向，并通过具体计划落实。"},{"id":"t0408","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"サイバーセキュリティ協議会","termZh":"网络安全协议会／网络安全理事会","english":"Cyber Security Council","reading":"さいばーせきゅりてぃきょうぎかい","breadcrumb":"","explanationJa":"サイバーセキュリティに関する政策や対策を検討・推進するための機関である。この協議会は、政府や企業、学術機関などの代表者が集まり、サイバー攻撃から国や社会を守るための方針を策定する。例えば、情報漏洩や不正アクセスといったリスクを低減するための施策や、教育・啓発活動の実施について議論する。このように、関係者が連携して効率的な対策を講じるための重要な役割を果たしており、国家の安全保障にも寄与している。","explanationZh":"日本网络安全治理中用于促进政府、重要基础设施运营者、企业和相关机构协作与信息共享的机制性组织名称。其作用在于共享威胁与事件信息、协调对策并提升社会整体防御能力。"},{"id":"t0409","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"アクセス制御機能","termZh":"访问控制功能","english":"Access Control Function","reading":"あくせすせいぎょきのう","breadcrumb":"","explanationJa":"システムやネットワークにおいて、特定のユーザーやシステムが特定の情報やリソースにアクセスできるかどうかを管理する機能である。この機能は、正しいユーザーのみが必要なデータにアクセスできるようにすることで、不正アクセスの防止に寄与する。例えば、企業のデータベースにおいて、社員が自分の業務に必要な情報にはアクセスできても、機密情報に対しては制限を設ける場合がある。このようにデータの安全性を保つために重要な役割を果たしており、不正アクセス禁止法に基づくセキュリティ対策の一環としても位置づけられる。","explanationZh":"系统根据用户或程序的身份、角色、权限和安全策略，限制其对资源进行读取、修改、执行等操作的功能。它是防止未授权访问和落实最小权限的核心安全机制。"},{"id":"t0410","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"不正アクセス行為","termZh":"非法访问行为","english":"Unauthorized Access Act","reading":"ふせいあくせすこうい","breadcrumb":"","explanationJa":"他人のコンピュータやネットワークに対して、許可なくアクセスする行為である。この行為は、個人や企業の情報を盗み取る目的で行われることが多く、悪意のある攻撃として法律によって禁止されている。不正アクセス禁止法に基づき、無断で情報を取得したり、システムを損傷させたりすることは厳しく罰せられる。また、不正アクセスは、データ漏えいや経済的損失を引き起こすため、特に企業にとって重大なリスクとなる。これを防ぐためには、セキュリティ対策やアクセス権の管理が不可欠である。","explanationZh":"未经合法授权，利用他人的认证信息、绕过访问控制或以其他方式进入受限制计算机系统的行为。在日本法律语境中，它与《不正访问行为禁止等相关法律》的规范对象相关，可能承担法律责任。"},{"id":"t0411","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"不正アクセス行為を助長する行為","termZh":"助长非法访问的行为","english":"Acts Promoting Unauthorized Access","reading":"ふせいあくせすこういをじょちょうするこうい","breadcrumb":"","explanationJa":"他者のコンピュータやネットワークに無断でアクセスする行為を助ける行動を指す。具体的には、侵入を可能にするツールの提供や、手段を教えることが含まれる。例えば、パスワードを破解するソフトウェアを配布したり、特定のセキュリティホールを利用する方法を説明することが該当する。これは、不正アクセスを阻止する法律に違反し、重大な刑事罰が科せられる可能性があるため、注意が必要である。正当な利用者の権利を保護し、安全な情報環境を築くための重要な概念である。","explanationZh":"向他人提供账号密码等认证信息，或以其他方式帮助实施非法访问的行为。即使本人未直接进入目标系统，协助、提供凭据等行为也可能受到日本相关法律限制。"},{"id":"t0412","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"個人情報保護に関するガイドライン","termZh":"个人信息保护相关指南","english":"Guidelines for the Protection of Personal Information","reading":"こじんじょうほうほごにかんするがいどらいん","breadcrumb":"","explanationJa":"個人のプライバシーを保護するために定められた基準や指針である。このガイドラインは、企業や組織が個人情報を取り扱う際に遵守すべき具体的なルールや手続きについて説明している。例えば、個人情報の収集や利用、保存、提供の方法について、利用者の同意を得ることや、適切な安全対策を講じることが求められる。また、個人情報の漏洩を防ぐための具体的な対策や、問題が発生した場合の対応手順も含まれている。これにより、個人の権利を守りつつ、信頼性の高い情報サービスを提供することが可能となる。","explanationZh":"为落实个人信息保护法律要求而制定的行业或监管指导文件，说明个人信息收集、使用、第三方提供、安全管理和事件处理等具体实践。组织应结合适用业务和监管要求落实相应措施。"},{"id":"t0413","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"個人情報取扱事業者","termZh":"个人信息处理经营者","english":"Personal Information Handling Business","reading":"こじんじょうほうとりあつかいじぎょうしゃ","breadcrumb":"","explanationJa":"個人情報を扱う事業体のことを指す。個人情報とは、特定の個人を識別できる情報であり、氏名や住所、電話番号、メールアドレスなどがその例である。こうした情報を収集、利用、保管する事業者は、法律に基づいて適切に個人情報を管理する責任を負う。具体的には、個人情報の漏えいや不正アクセスから守るための対策を講じる必要がある。また、利用者に対して情報の取扱いについての説明を行い、必要に応じて同意を得ることが求められる。個人情報取扱事業者の適切な運営は、利用者の信頼を確保し、プライバシーを保護するために非常に重要である。","explanationZh":"日本个人信息保护法中的主体概念，指在业务中使用个人信息数据库等并承担法定个人信息保护义务的经营者。其责任包括明确利用目的、采取安全管理措施、妥善处理第三方提供和个人权利请求等。"},{"id":"t0414","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"安全管理措置","termZh":"安全管理措施","english":"Safety Management Measures","reading":"あんぜんかんりそち","breadcrumb":"","explanationJa":"個人情報や重要なデータを適切に保護するために講じる具体的な対策や手続きである。これには、物理的なセキュリティ対策や情報システムに対する技術的な対策、さらには業務運用に関するルールの設定が含まれる。例えば、オフィスへの出入りを制限するための鍵管理や、パスワードを強化すること、定期的な社員教育が代表的な施策である。また、情報漏洩や不正アクセスを防ぐためには、これらの管理措置を継続的に見直し、改善していくことが重要である。これにより、個人情報を扱う企業や組織は法令に準拠した運用ができ、利用者からの信頼を得ることができる。","explanationZh":"为防止个人数据或其他重要信息泄露、丢失、毁损等而实施的组织、人员、物理和技术措施。典型内容包括责任体制、员工监督、门禁、访问控制、加密、日志和供应商管理。"},{"id":"t0415","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"要配慮個人情報","termZh":"需特别关注的个人信息","english":"Sensitive Personal Information","reading":"ようはいりょこじんじょうほう","breadcrumb":"","explanationJa":"個人情報保護法において特に保護が必要とされる個人情報の一種である。それには、人種や思想、信条、健康状態、犯罪歴など、本人のプライバシーに深く関わる情報が含まれる。これらの情報は、本人の人権を侵害する恐れがあるため、特に慎重に取り扱う必要がある。例えば、医療情報はその代表例であり、適切な管理が求められる。このため、要配慮個人情報を扱う際には、事前の同意が必須となり、漏洩防止のための対策が法律で定められている。個人情報を取り扱う企業や団体は、これらの規定を遵守しなければならず、違反した場合には厳しい罰則が科されることがある。","explanationZh":"日本个人信息保护法中的敏感个人信息类别，涉及种族、信条、社会身份、病史、犯罪受害经历等需要特别谨慎处理的信息。原则上在取得和利用时受到更严格限制，应采取强化保护措施。"},{"id":"t0416","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"特定個人情報の適正な取扱いに関するガイドライン","termZh":"特定个人信息适当处理指南","english":"Guidelines for Proper Handling of Specific Personal Information","reading":"とくていこじんじょうほうのてきせいなとりあつかいにかんするがいどらいん","breadcrumb":"","explanationJa":"個人情報を保護するための具体的な指針を示したものである。このガイドラインは、日本における個人情報保護法に基づき、特定の個人が識別できる情報や、その情報を取り扱う際の注意事項を明確にすることを目的としている。例えば、マイナンバーや個人の健康情報など、特にセンシティブな情報についてどのように収集、保存、利用、廃棄すべきかの基準を定めている。このガイドラインに従うことで、情報漏洩のリスクを低減し、個人のプライバシーが守られることが期待される。従って、企業や組織はこのガイドラインを遵守することが求められ、その結果、社会全体の信頼を得ることに繋がるのである。","explanationZh":"日本针对“特定个人信息”（包含个人编号等信息）制定的处理指南，规定取得、利用、保存、提供和销毁等环节的安全与合规要求。组织应严格限定利用目的并实施必要的安全管理措施。"},{"id":"t0417","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"マイナンバー法","termZh":"日本《个人编号法》（My Number法）","english":"My Number Act","reading":"まいなんばーほう","breadcrumb":"","explanationJa":"特定の個人を識別するために用いる番号制度について定めた法律である。この法律は、社会保障、税、災害対策など様々な行政手続において個人情報の一元化を進めることを目的としている。具体的には、住民に付与されたマイナンバーを利用することで、行政サービスの効率化や公平性を高めることを狙いとしている。一方で、個人情報の適切な取り扱いやプライバシー保護が求められるため、関連する法律やガイドラインも整備されている。たとえば、マイナンバーを取り扱う事業者は、厳重なセキュリティを確保することが義務付けられており、個人情報の漏洩を防ぐための取り組みが促進されている。これにより、利用者は安心してサービスを受けることができる。","explanationZh":"日本关于行政手续中用于识别特定个人的编号制度及其利用、保护和管理规则的法律。对包含My Number的特定个人信息规定了严格的利用范围、提供限制和安全管理义务。"},{"id":"t0418","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"個人情報保護委員会","termZh":"个人信息保护委员会","english":"Personal Information Protection Commission","reading":"こじんじょうほうほごいいんかい","breadcrumb":"","explanationJa":"日本における個人情報の保護を推進するための行政機関である。この委員会は、個人情報の適正な取り扱いや個人のプライバシーを守るために法律の運用や啓発活動を行っている。具体的には、企業や団体が個人情報を収集・利用する際のルールを定め、それに従っているかの監視を行うことが求められる。また、一般市民からの相談や苦情を受け付けており、個人情報の漏洩や不正使用を防ぐための措置を講じる役割も担っている。このように、社会全体の個人情報保護意識を高めるために重要な機関である。","explanationZh":"日本负责个人信息保护制度监督和执法的独立监管机关。其职责包括制定指南、监督个人信息处理、接受相关报告并依法采取指导、建议或命令等措施。"},{"id":"t0419","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"JIS Q 15001","termZh":"JIS Q 15001","english":"JIS Q 15001","reading":"じすきゅー15001","breadcrumb":"","explanationJa":"個人情報の保護に関する日本の標準規格である。この規格は、企業や組織が個人情報を適切に取り扱うための基準を示しており、個人情報の収集、利用、保管、提供に関するルールを定めている。具体的には、個人情報の取り扱いに関する方針や手続き、抜本的なガイドラインを提供し、透明性を保ちながら個人のプライバシーを尊重することが求められる。また、JIS Q 15001に準拠することで、企業は信頼性を向上させ、消費者との信頼関係を築くことが可能になる。この規格は特に、個人情報漏洩のリスクを軽減し、適正な管理を促進するために重要である。","explanationZh":"日本关于个人信息保护管理体系要求的工业标准，为组织建立、运行和持续改进个人信息保护管理体系提供框架。日本隐私标志（P标志）制度与该标准具有密切关系。"},{"id":"t0420","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"プライバシーマーク","termZh":"隐私标志（PrivacyMark）","english":"Privacy Mark","reading":"","breadcrumb":"","explanationJa":"個人情報を適切に管理・保護している事業者に付与される認証マークである。この制度は、個人情報の取り扱いについて一定の基準を満たしている企業や団体が、顧客に対して信頼性を示すために設けられている。たとえば、プライバシーマークを取得した企業は、個人情報を誤って漏洩させないように特別な対策を講じているとされ、顧客はそのサービスを利用する際に安心感を持つことができる。このような認証は、個人情報保護に関する法律やガイドラインに基づいて行われるため、消費者からの信頼を高める手助けとなる。プライバシーマークを持つ企業は、より地域社会や顧客から尊重される存在となることが期待される。","explanationZh":"日本用于表明企业等组织已建立符合规定要求的个人信息保护管理体系并通过审查的认证标志制度。获得标志可向客户展示个人信息保护管理能力，但仍需持续遵守制度并接受更新审查。"},{"id":"t0421","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"OECDプライバシーガイドライン","termZh":"OECD隐私保护指南","english":"OECD Privacy Guidelines","reading":"おーいーしーでぃーぷらいばしーがいどらいん","breadcrumb":"","explanationJa":"経済協力開発機構が提唱した、個人情報の取り扱いに関する指針である。このガイドラインは、個人のプライバシー権を尊重し、個人情報を適切に管理するための基本的な原則を示している。具体的には、個人情報の収集目的の明確化、情報の使用制限、データの正確性の保持、本人の同意の重視、情報の安全管理と第三者への提供に関するルールなどが含まれる。これにより、個人情報を扱う企業や組織は、法令遵守を促進し、利用者の信頼を得ることを目的としている。さまざまな国がこのガイドラインを参考にし、自国の法律や規制と整合性を持たせる努力を進めている。","explanationZh":"OECD提出的个人数据和隐私保护基本原则，强调收集限制、数据质量、目的明确、利用限制、安全保障、公开、个人参与和责任等理念。它对许多国家和地区的隐私法规产生了重要影响。"},{"id":"t0422","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"プライバシー影響アセスメント","termZh":"隐私影响评估（PIA）","english":"Privacy Impact Assessment","reading":"ぷらいばしーえいきょうあせすめんと","breadcrumb":"","explanationJa":"個人情報を扱うプロジェクトやシステムが、どのように個人のプライバシーに影響を及ぼすかを評価する手続きである。PIAは、個人情報保護法に基づいて、情報の収集、使用、保存、共有が適切に行われるかを検討するために実施される。たとえば、新しいアプリケーションを開発する際、そのアプリがユーザーの個人情報をどのように扱うか、リスクがあるかどうかを事前に分析することが重要である。これにより、個人のプライバシーが守られ、法令を遵守するための対策を講じることができる。PIAは、透明性や信頼性を高めるためにも重要な手法である。","explanationZh":"在系统或业务处理个人信息之前，系统识别其对个人隐私可能造成的影响并制定降低风险措施的评估过程。PIA有助于落实隐私保护设计，并在项目早期发现过度收集、用途不明或安全不足等问题。"},{"id":"t0423","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"プライバシーフレームワーク","termZh":"隐私框架","english":"Privacy Framework","reading":"","breadcrumb":"","explanationJa":"個人のプライバシーを保護するためのガイドラインや基準のことを指す。このフレームワークは、企業や組織が個人情報を取り扱う際に遵守すべき指針を提供するものであり、透明性やデータの最小化、ユーザーの同意などを重視している。たとえば、データ収集時には、明確な目的を持ち、その目的に必要なデータのみを収集することが重視される。また、法律や規制の遵守を助ける構造を持っており、企業が適切な個人情報保護策を講じることで、利用者の信頼を得ることができる。これにより、データ漏洩やプライバシー侵害のリスクを低減させることが期待される。","explanationZh":"组织系统管理隐私风险的一套结构化方法，通常涵盖识别个人数据处理、治理、控制、沟通和保护等活动。它有助于把法律要求、业务目标和技术措施整合进持续的隐私风险管理流程。"},{"id":"t0424","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"一般データ保護規則","termZh":"《通用数据保护条例》（GDPR）","english":"General Data Protection Regulation","reading":"いっぱんでーたほごきそく","breadcrumb":"","explanationJa":"個人情報の保護を目的とした欧州連合（EU）の法律である。この規則は、個人データの収集、使用、保存、破棄に関する厳格なルールを定めており、EU内で事業を行う企業や団体に影響を及ぼす。GDPRは、個人が自分の情報に対して持つ権利を強化しており、例えば、自分のデータをアクセス、訂正、削除する権利が保障されている。さらに、企業は個人データを扱う際に明示的な同意を得る必要があり、違反した場合には重い罰金が科せられる可能性がある。このように、GDPRは個人情報の取り扱いに対して個人のプライバシーを重視するもので、国際的にも影響を与える重要な法規である。","explanationZh":"欧盟关于个人数据保护和自由流动的重要法规，对数据处理合法性、透明度、数据主体权利、安全措施、泄露通报及跨境传输等提出严格要求。满足适用条件的非欧盟组织也可能受到其管辖。"},{"id":"t0425","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"オプトイン","termZh":"选择加入（Opt-in）","english":"Opt-in","reading":"","breadcrumb":"","explanationJa":"個人情報やプライバシーに関して、利用者が自らの意志で情報提供やサービス利用を選択することを指す。具体的には、例えばニュースレターや広告メールを受け取る場合に、利用者が明示的に同意することで、その情報を受け取れるようになる。この手法は、利用者の同意を重視するため、個人情報保護の観点から重要である。また、オプトインを採用することで、企業は信頼性を高め、利用者との関係を強化することができる。近年では、個人情報の取り扱いに対する意識が高まる中で、オプトインの重要性はますます増している。","explanationZh":"在个人明确表示同意后，组织才开始某项数据处理、营销或信息接收的机制。其核心是“默认不参加，主动同意后参加”，常用于强调有效同意和用户自主选择。"},{"id":"t0426","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"オプトアウト","termZh":"选择退出（Opt-out）","english":"Opt-out","reading":"","breadcrumb":"","explanationJa":"特定のサービスや情報収集から自分の参加を辞退することを指す。特にプライバシー保護の観点から、個人情報の収集や利用を拒否する手段として重要である。例えば、オンラインサービスを利用する際、ユーザーは自分のデータが広告目的で利用されることを防ぐために、オプトアウトを選択することができる。このような手法は、個人の選択権を尊重し、無断でのデータ収集を防ぐ重要な仕組みであり、利用者が安心してサービスを利用できる環境を整える役割を果たす。また、オプトアウトの手続きを容易にすることが、企業やサービス提供者にとっても信頼性を高めるために不可欠である。","explanationZh":"默认允许某项处理或通信，但向个人提供明确方式使其可以拒绝或停止的机制。是否可以采用Opt-out取决于具体法律和业务场景，不能替代依法必须取得事前同意的情形。"},{"id":"t0427","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"第三者提供","termZh":"向第三方提供","english":"Third-Party Provision","reading":"だいさんしゃていきょう","breadcrumb":"","explanationJa":"個人情報をその情報を収集した本人の同意なしに他の人や団体に渡すことを指す。これは主に、企業が顧客の情報をマーケティング目的で他の企業に提供する場合に行われる。たとえば、あるオンラインショッピングサイトが顧客の購買履歴を匿名化し、データ分析会社に渡して販売戦略を立ててもらうケースが該当する。しかし、第三者提供はプライバシーの観点から慎重に取り扱うべきであり、個人情報保護法に基づいて厳格なルールが設けられている。これにより、ユーザーは自分の情報がどのように使われるかを知る権利を持っているため、情報の透明性が求められる。適切な対策を講じないと、信頼喪失や法的トラブルに発展する可能性があるため、企業は責任ある運用を心がける必要がある。","explanationZh":"个人数据或其他信息从原处理者提供给独立的第三方主体的行为。通常需要确认合法依据、利用目的、本人同意要求、提供记录和接收方责任，并根据适用法律采取保护措施。"},{"id":"t0428","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"匿名加工情報","termZh":"匿名加工信息","english":"Anonymously Processed Information","reading":"とくめいかこうじょうほう","breadcrumb":"","explanationJa":"個人情報を特定の個人が識別できない形に加工したデータである。この情報は、個人情報保護法に基づき、個人を特定できないため、より安全に利用することができる。実際には、名前や住所といった固有の情報を削除したり、集計して数値データに変換することで、個人が特定できないようにしている。例えば、購買データを集約し、特定の商品の購入傾向を分析する際に使用される。このように、匿名加工情報は研究やビジネス分析などにおいて役立つもので、個人のプライバシーを保護しながら有用なデータを提供する役割を果たしている。","explanationZh":"日本个人信息保护制度中的概念，指通过规定方式加工，使其无法识别特定个人且原则上不能复原为原个人信息的数据。由于仍存在利用规则和义务，组织应按法律要求进行加工、披露项目和安全管理。"},{"id":"t0429","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"仮名加工情報","termZh":"假名加工信息","english":"Pseudonymized Information","reading":"かめいかこうじょうほう","breadcrumb":"","explanationJa":"個人情報保護法における重要な概念であり、特定の個人を識別できないように加工された情報を指す。この情報は、元の個人情報から特定の識別子を削除または変更しているため、個人が特定できない状態での利用が可能である。例えば、名前や住所をコード化することで個人を特定しにくくし、データ分析などで利用しやすくする方法がある。これにより、個人情報の保護を確保しつつ、統計分析やマーケティングなどに活用できるため、多くの企業や研究機関で重要視される技術である。法的にも一定の保護が付与されており、注意深く取り扱われるべきものである。","explanationZh":"日本个人信息保护制度中的概念，指删除或替换部分标识符，使其在不与其他信息对照的情况下无法识别特定个人的数据。它仍属于受管理的数据类型，与彻底匿名化不同，使用和第三方提供受到特定规则限制。"},{"id":"t0430","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"不正指令電磁的記録に関する罪","termZh":"制作或提供恶意电磁记录罪","english":"Crime of Creating Malicious Software","reading":"ふせいしれいでんじてききろくにかんするつみ","breadcrumb":"","explanationJa":"他人のコンピュータやネットワークに不正にアクセスするための悪意のあるプログラム、いわゆる「ウイルス」や「マルウェア」を作成・配布する行為を罰則の対象とする法律である。通称は「ウイルス作成罪」。この罪は、情報社会における安全を守るために設けられており、他人のデータを破壊したり、盗んだりする行為を防ぐことを目的としている。例えば、ウイルスによって個人のパソコンに侵入し、個人情報を盗むような行為は、この罪に問われることになる。このような規定により、サイバー犯罪の抑止や、社会全体の情報セキュリティの向上が図られている。","explanationZh":"日本刑法中针对以非法目的制作、提供、取得或保管计算机病毒等“非法指令电磁记录”的犯罪类型。该制度用于规制恶意程序的制作和传播，而非一般正常的软件开发或安全研究活动。"},{"id":"t0431","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"電子計算機使用詐欺罪","termZh":"利用电子计算机诈骗罪","english":"Fraud in Electronic Computers","reading":"でんしけいさんきしようさぎざい","breadcrumb":"","explanationJa":"電子計算機を利用して他人を欺く行為を罰する法律である。具体的には、コンピュータを用いて金銭を不正に得るために偽情報を入力したり、他人のデータを不正に操作したりすることを指す。この犯罪には、オンラインでの詐欺や、ハッキングによって他人の口座情報を盗み出す行為が含まれる。例えば、フィッシング詐欺は、被害者に偽のWebサイトに誘導して個人情報を取得する手法であり、これは電子計算機使用詐欺罪に該当する。また、こうした犯罪の増加に伴い、法律は厳格化され、対策が求められている。","explanationZh":"日本刑法中针对向计算机输入虚假信息或给予非法指令，使其进行不真实的数据处理并取得财产利益的诈骗类犯罪。典型场景涉及非法操纵信息系统以获取经济利益。"},{"id":"t0432","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"電子計算機損壊等業務妨害罪","termZh":"损坏电子计算机等妨害业务罪","english":"Computer Damage and Interference Offense","reading":"でんしけいさんきそんかいとうぎょうむぼうがいざい","breadcrumb":"","explanationJa":"電子計算機やその関連機器に対して、意図的に損壊したり、業務を妨害する行為を指す法律の規定である。この罪は、コンピュータを使用している企業や個人の業務を不正に妨げる行為を防止するために設けられている。例えば、ウイルスを仕掛けてコンピュータをダウンさせたり、データを削除する行為は、明らかに業務妨害に該当する。電子計算機の発展に伴い、こうした犯罪が増加しているため、刑法の中でも特に重要な位置を占めている。このようにして、情報システムを保護し、社会の安全を確保する役割を果たしている。","explanationZh":"日本刑法中针对破坏用于业务的计算机或电磁记录、输入虚假数据等方式妨碍他人业务运行的犯罪。其对象包括使系统不能正常工作或产生错误结果的恶意行为。"},{"id":"t0433","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"電磁的記録不正作出及び供用罪","termZh":"非法制作及使用电磁记录罪","english":"Crime of Unauthorized Creation and Use of Electromagnetic Records","reading":"でんじてききろくふせいさくしゅつおよびきょうようざい","breadcrumb":"","explanationJa":"他人の権利を侵害する目的で、電子的なデータや記録を無断で作成したり、使用したりする行為を指すものである。この罪は、例えば、他人の名義を使って不正にデータを改ざんしたり、偽の電子文書を作成して他人を欺くような犯罪を含む。具体的には、電子契約やオンライン署名などで不正に認証を得ようとする行為がこれにあたる。このような行為は、社会の信頼を損ねるものであり、厳しい罰則が科されることが多い。電子情報が普及した現代において、法的な対策がますます重要になっている。","explanationZh":"日本刑法中针对以行使为目的非法制作与权利、义务或事实证明有关的电磁记录，并使用该记录的犯罪类型。可理解为电子记录领域对传统文书伪造行为的对应规制。"},{"id":"t0434","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"支払用カード電磁的記録不正作出等罪","termZh":"非法制作支付卡电磁记录等罪","english":"Electromagnetic Record Fraud Regarding Payment Cards","reading":"しはらいようかーどでんじてききろくふせいさくしゅつとうざい","breadcrumb":"","explanationJa":"支払用カードに関する不正行為を指す刑法上の罪である。この罪は、他人の支払用カードの電磁的記録を不正にコピーしたり、改ざんする行為を含む。具体的には、カードの情報を無断で取得し、支払いに使用することで、他者に経済的損害を与えることが該当する。例えば、他人のクレジットカードを不正に利用して商品を購入するといった行為がこれに該当する。このような行為は、社会的な信頼を損ない、経済活動に悪影響を及ぼすため、厳しく罰せられる。","explanationZh":"日本刑法中针对非法制作、持有或使用信用卡等支付卡磁条／芯片相关电磁记录的犯罪类型，旨在打击伪造支付卡和利用非法卡数据进行支付的行为。"},{"id":"t0435","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"電子署名及び認証業務等に関する法律","termZh":"日本《电子签名及认证业务相关法律》","english":"Act on Electronic Signatures and Certification Business","reading":"でんししょめいおよびにんしょうぎょうむとうにかんするほうりつ","breadcrumb":"","explanationJa":"電子署名とその認証に関する法律である。この法律は、電子的な取引や手続きにおいて、信頼性を確保し、詐欺や改ざんを防ぐ目的で制定された。具体的には、認定された認証事業者が発行する電子証明書が、個人や法人の権限を確認する手段として用いられる。例えば、電子契約を結ぶ際に、相手の本人確認を電子証明書によって行うことで、安全に取引を進めることができる。この法律は、デジタル社会における信頼性と安全性を向上させるための重要な枠組みを提供している。","explanationZh":"日本规范电子签名法律效力和特定认证业务等事项的法律。通过满足一定条件的电子签名，可支持确认电子文档由本人制作，并促进可信电子交易和认证服务的发展。"},{"id":"t0436","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"情報流通プラットフォーム対処法","termZh":"日本《信息流通平台应对法》","english":"Information Distribution Platform Response Measures","reading":"じょうほうりゅうつうぷらっとふぉーむたいしょほう","breadcrumb":"","explanationJa":"情報の流通を円滑に行い、同時に安全を確保するための法律である。この法律は、オンラインプラットフォーム上での情報の管理や流通に対し、適切な対策を求めるものである。例えば、ソーシャルメディアやアプリケーションでのデータ処理に関して利用者のプライバシーを守るための規制が含まれている。この対処法は、個人情報の漏洩を防ぎ、透明性ある情報の流通を促進することを目的としている。さらに、企業はこの法律に従って安全性を保ちつつ、サービスを提供することが求められるため、業界全体の信頼性向上にも寄与する。","explanationZh":"日本针对互联网平台上的违法或侵权信息流通，规定大型平台等采取相应措施及提高透明度等要求的法律制度。涉及侵权信息处理、权利救济和平台责任等方面，复习时应以日本正式法名及其制度目的为重点。"},{"id":"t0437","chapterId":"c07","chapterJa":"セキュリティ関連法規","chapterZh":"信息安全相关法规","termJa":"特定電子メール法","termZh":"日本《特定电子邮件法》","english":"Specific Electric Mail Law","reading":"とくていでんしめーるほう","breadcrumb":"","explanationJa":"迷惑メール対策を目的とした法律である。この法律は、商業目的で送信される電子メールに対して、事前に送信者が同意を得ることを義務付けている。例えば、企業が顧客に向けて広告メールを送る場合、あらかじめその顧客から承諾を得る必要がある。このようにして、利用者の受信箱を不必要なメールから守ることを目指している。同法は、違反した場合には罰則が科せられるため、企業は遵守することが求められる。このような取り組みは、健全なインターネット環境の維持にも役立っている。\nHOME»用語集»法務»労働関連・取引関連法規","explanationZh":"日本规范广告宣传类电子邮件发送行为的法律，旨在减少垃圾邮件。通常涉及事前同意、发送者信息标示、退订机制以及禁止虚假发件人信息等要求。"},{"id":"t0438","chapterId":"c08","chapterJa":"労働関連・取引関連法規","chapterZh":"劳动与交易相关法规","termJa":"就業規則","termZh":"就业规则／工作规则","english":"Work Rules","reading":"しゅうぎょうきそく","breadcrumb":"","explanationJa":"企業や組織が従業員に対して定める労働条件や職場のルールに関する文書である。これは、労働基準法に基づいて作成され、従業員がどのように働くべきか、また職場で守るべきルールや規則を明示する目的がある。具体的には、勤務時間、休暇、賃金、服務規律などが含まれ、従業員が知っておくべき重要な情報を提供する。また、企業が従業員に対して公平な雇用環境を提供するための基盤ともなり、労使間のトラブルを防ぐ役割も果たす。これは、従業員が安心して働くためには欠かせないものである。","explanationZh":"由用人单位规定劳动条件、工作纪律、职责和奖惩等事项的内部规则。在信息安全方面可规定系统使用、保密、设备管理和违规处理等要求，并应符合适用的劳动法律法规。"},{"id":"t0439","chapterId":"c08","chapterJa":"労働関連・取引関連法規","chapterZh":"劳动与交易相关法规","termJa":"労働者","termZh":"劳动者","english":"Worker","reading":"ろうどうしゃ","breadcrumb":"","explanationJa":"雇用契約に基づいて働く人々を指す言葉である。これは、自営業者とは異なり、他の個人や企業の指示のもとで労働を提供する形態をとる。様々な業種や職種で活躍し、その権利や義務は労働関連の法律によって保護されている。例えば、労働者派遣法では、派遣労働者の権利や安全性を確保するためのルールが定められている。この法律により、派遣元企業は派遣先に対して適切な環境を提供し、労働者に対しても不当な扱いをしてはならないとされている。そのため、労働者は合法的に保障された労働条件のもとで仕事をすることが求められる。","explanationZh":"在雇佣关系中向用人单位提供劳动并获得工资的人。劳动者在组织安全管理中既是信息资产使用者，也承担遵守工作规则、保密义务和安全操作要求的责任。"},{"id":"t0440","chapterId":"c08","chapterJa":"労働関連・取引関連法規","chapterZh":"劳动与交易相关法规","termJa":"派遣先","termZh":"派遣接收单位","english":"Dispatching Destination","reading":"はけんさき","breadcrumb":"","explanationJa":"派遣労働者が勤務する企業や組織のことである。この用語は主に労働者派遣法に基づいて使用され、派遣会社から派遣された労働者が実際に業務を行う場所を指す。例えば、あるIT企業が他の会社にエンジニアを派遣する場合、そのエンジニアが業務を行う会社が派遣先となる。この関係は、派遣労働者の権利や待遇に大きく影響を与えるため、派遣会社や派遣先が遵守すべき法規制が多数存在する。特に、労働条件や環境の整備は、派遣労働者が安心して働けるようにするために重要である。","explanationZh":"在劳务派遣关系中实际接受派遣劳动者并对其日常工作进行指挥命令的企业或组织。其与派遣单位职责不同，应按合同和法律明确工作指挥、安全管理及信息访问范围。"},{"id":"t0441","chapterId":"c08","chapterJa":"労働関連・取引関連法規","chapterZh":"劳动与交易相关法规","termJa":"派遣元","termZh":"派遣单位","english":"Dispatching Source","reading":"はけんもと","breadcrumb":"","explanationJa":"労働者を他の企業に派遣する元の企業のことである。この企業は、派遣労働者を雇用し、その労働者を必要としている企業に送る役割を果たす。例えば、あるIT企業がプロジェクトのために技術者を派遣元として他の企業に出向させる場合、派遣元企業がその責任を持つ。派遣先に対して労働者の給与や労働条件を管理し、派遣される労働者の権利を守るための義務がある。これにより、労働者派遣法に基づいた適正な派遣が行われることが求められている。派遣元企業は、労働市場のニーズに応じて柔軟な雇用を提供し、企業間での人材活用を促進する重要な役割を担っている。","explanationZh":"与派遣劳动者建立雇佣关系并将其派往其他组织工作的企业。派遣单位负责雇佣管理等事项，并应与接收单位协调保密、教育和信息安全责任。"},{"id":"t0442","chapterId":"c08","chapterJa":"労働関連・取引関連法規","chapterZh":"劳动与交易相关法规","termJa":"派遣契約","termZh":"劳务派遣合同","english":"Labor Dispatch Contract","reading":"はけんけいやく","breadcrumb":"","explanationJa":"労働者が派遣会社に雇用され、他の企業に一定期間働く契約のことである。この契約は、労働者派遣法に基づいており、派遣された労働者は派遣先企業で業務を遂行する。例えば、製造業やサービス業などで、特定のプロジェクトや業務のために短期間の人手を必要とする場合、派遣契約が利用される。派遣契約のメリットには、企業が必要なスキルを持つ労働者を短期間で確保できる点がある。しかし、派遣労働者には、雇用の安定性や給与面での不安が伴うことがあるため、労働者派遣法により権利や保護が提供されている。これにより、派遣労働者が適切な労働条件で働けるよう保障されている。","explanationZh":"派遣单位与派遣接收单位之间约定劳动者派遣条件、工作内容、期间、责任和费用等事项的合同。信息安全相关条款通常包括保密义务、访问权限、事故报告和人员管理要求。"},{"id":"t0443","chapterId":"c08","chapterJa":"労働関連・取引関連法規","chapterZh":"劳动与交易相关法规","termJa":"雇用契約","termZh":"劳动合同","english":"Employment Contract","reading":"こようけいやく","breadcrumb":"","explanationJa":"雇用主と労働者の間で結ばれる合意であり、労働者が特定の業務を行うことに対して、雇用主が賃金を支払うことを約束するものである。この契約には、仕事の内容や給与、勤務時間、休日などの基本的な条件が記載される。例えば、派遣労働においては、派遣元会社と派遣労働者との間で雇用契約が結ばれ、その条件に基づき、労働者は派遣先企業で業務を遂行する。労働者の権利と雇用主の義務を明確にするものであり、労働条件のトラブルを避けるために重要な役割を果たす。特に労働者派遣法に基づく場合、適切な契約内容が求められるため、法律に関する理解も必要である。","explanationZh":"劳动者与用人单位之间约定提供劳动和支付工资等权利义务的合同关系。组织可在合同和相关制度中规定保密、知识产权、信息系统使用及离职后义务等内容。"},{"id":"t0444","chapterId":"c08","chapterJa":"労働関連・取引関連法規","chapterZh":"劳动与交易相关法规","termJa":"指揮命令","termZh":"指挥命令","english":"Command and Control","reading":"しきめいれい","breadcrumb":"","explanationJa":"労働者派遣法において、派遣先の企業が派遣スタッフに対して指示や命令を出すことである。具体的には、派遣社員の業務内容や手順を決定し、業務を遂行するための指導を行うことを指す。この制度の下では、派遣先が指揮命令を行うことで、派遣社員は業務に対して責任を持ち、派遣先企業の方針に従った形で活躍する。労働者派遣法はこのプロセスを明確に規定しており、指揮命令の範囲や内容についても注意が必要である。派遣社員が属する派遣会社との契約内容が遵守される限り、派遣先企業は効率的に人手を活用し、業務を円滑に進めることができる。","explanationZh":"组织或负责人对劳动者具体工作的内容、方法、时间等作出指示和管理的行为。在派遣、承揽等合同关系中，谁拥有直接指挥命令权是判断法律关系和责任分工的重要因素。"},{"id":"t0445","chapterId":"c08","chapterJa":"労働関連・取引関連法規","chapterZh":"劳动与交易相关法规","termJa":"準委任契約","termZh":"准委任合同","english":"Quasi-Mandate Contract","reading":"じゅんいにんけいやく","breadcrumb":"","explanationJa":"特定の業務を行うために委任される契約の一つである。これは、委任契約の一種であり、依頼者が仕事を依頼し、受託者がその業務を遂行することに同意するものである。具体的には、弁護士や会計士が顧客のためにサービスを提供する場合などがこれに該当する。準委任契約においては、受託者は業務を誠実に行う義務を負うが、必ずしも特定の結果を保証するものではないため、責任の範囲について明確に理解することが重要である。この契約形式は、専門的な知識や技術を要する業務の提供に適用され、多様な業種で広く利用されている。","explanationZh":"日本民法中的合同类型之一，一方受托处理不属于法律行为的事务，并负有适当履行义务，通常不以完成特定成果为唯一责任。IT运维、咨询等服务有时采用此类合同，应明确工作范围、责任和安全义务。"},{"id":"t0446","chapterId":"c08","chapterJa":"労働関連・取引関連法規","chapterZh":"劳动与交易相关法规","termJa":"請負契約","termZh":"承揽合同／成果承包合同","english":"Contract for Work","reading":"うけおいけいやく","breadcrumb":"","explanationJa":"ある一方が特定の仕事を行い、もう一方がその対価を支払う契約である。この契約形態は、民法の中で重要な位置を占め、主に建設業や製造業などの実務において広く用いられる。例えば、建設会社が顧客から依頼を受けて、特定の建物を建設する場合、この請負契約が成立する。請負契約の特徴として、完成した仕事に対して報酬が支払われることや、委託者が結果を求める点が挙げられる。また、請負契約には、完成義務や品質保証などの法的な責任が伴うため、契約内容をしっかりと明記することが重要である。","explanationZh":"约定承包方完成一定工作成果，委托方对完成结果支付报酬的合同。软件开发等项目中，应明确成果物、验收标准、交付期限、缺陷处理、知识产权和信息安全责任。"},{"id":"t0447","chapterId":"c08","chapterJa":"労働関連・取引関連法規","chapterZh":"劳动与交易相关法规","termJa":"守秘契約","termZh":"保密合同（NDA）","english":"Non-Disclosure Agreement","reading":"しゅひけいやく","breadcrumb":"","explanationJa":"特定の情報を第三者に漏らさないことを約束する契約である。企業間の取引やビジネスの関係で重要な機密情報がある場合、守秘契約を結ぶことで、情報が不正に外部に伝わるのを防ぐことができる。例えば、新製品の開発計画や顧客リストなど、企業にとって価値のある情報が該当する。この契約は、情報を共有する前に締結されることが一般的で、守秘義務違反があった場合には、法的措置が取られることもあるため、信頼関係の構築にも寄与する。守秘契約により、企業は競争力を維持し、リスクを軽減できる。","explanationZh":"用于约束合同当事人对获得的非公开信息保密并限制用途的协议。应明确机密信息范围、允许使用目的、例外、保护措施、期限、返还或销毁及违约责任等。"},{"id":"t0448","chapterId":"c08","chapterJa":"労働関連・取引関連法規","chapterZh":"劳动与交易相关法规","termJa":"ボリュームライセンス契約","termZh":"批量许可协议","english":"Volume License Agreement","reading":"ぼりゅーむらいせんすけいやく","breadcrumb":"","explanationJa":"企業や教育機関などがソフトウェアを複数のコンピュータにインストールして使用するための特別な契約である。この契約により、一括でライセンスを購入でき、個別にライセンスを取得するよりもコストを削減できるメリットがある。たとえば、学校が多くのパソコンに教育用ソフトウェアを導入する場合、ボリュームライセンス契約を通じて必要なライセンス数を一度に取得し、まとめて管理することができる。また、この契約では、ライセンスの管理や更新、サポートに関するさまざまな条件が定められており、企業や教育機関にとって柔軟な運用が可能となる。","explanationZh":"软件厂商面向企业、学校等组织，以统一合同方式授权一定数量用户或设备使用软件的许可模式。组织需要做好许可数量、版本、使用范围和续期管理，避免超范围使用造成合规风险。"},{"id":"t0449","chapterId":"c08","chapterJa":"労働関連・取引関連法規","chapterZh":"劳动与交易相关法规","termJa":"コピーレフト","termZh":"著佐权／Copyleft","english":"Copyleft","reading":"","breadcrumb":"","explanationJa":"ソフトウェアやコンテンツの利用や配布に関するライセンスの一形態である。特に、著作権の考え方を逆転させる方式で、作品を自由に使用・改変できる権利を与えるが、改変後の作品も同様の自由を保つことを条件とする。例えば、GNU GPL（GNU General Public License）などのライセンスがコピーレフトの代表的な例であり、これに従うことで、誰でもソフトウェアを改良し、その改良版を再配布できる。しかし、その際には、同じライセンス条件のもとで配布しなければならないため、結果的に作品の自由な利用が維持される。オープンソースソフトウェアの普及に貢献し、共に協力して技術を発展させる文化を育む役割を果たしている。","explanationZh":"一种利用著作权许可机制，要求修改或再发布作品时继续以相同或兼容的开放许可条件提供的理念。典型开源许可证可能包含源代码公开等义务，使用时必须遵守具体许可证条款。"},{"id":"t0450","chapterId":"c08","chapterJa":"労働関連・取引関連法規","chapterZh":"劳动与交易相关法规","termJa":"ソフトウェア開発委託モデル契約","termZh":"软件开发委托示范合同","english":"Software Development Outsourcing Model Contract","reading":"そふとうぇあかいはついたくもでるけいやく","breadcrumb":"","explanationJa":"企業がソフトウェアの開発を外部の専門業者に委託する際に結ぶ契約の一種である。この契約により、発注者は開発にかかるコストや時間の削減を図ることができ、外部の専門技術を活用することでクオリティの向上も期待できる。たとえば、企業が新しいアプリケーションを開発する際、社内に技術者が不足している場合に外部の開発会社に委託することで、短期間で高品質な成果物を得ることが可能となる。また、契約内容には開発の範囲や納期、料金について明記されるため、トラブルを避けるためにも重要な役割を果たす。このように、効率的な開発を実現するための重要な手段である。","explanationZh":"日本针对软件开发委托交易提供的标准化／示范合同文本，用于帮助发包方和供应商明确开发范围、成果、验收、费用、知识产权、变更和责任等事项，降低合同理解不一致带来的项目风险。"},{"id":"t0451","chapterId":"c08","chapterJa":"労働関連・取引関連法規","chapterZh":"劳动与交易相关法规","termJa":"情報システム・モデル取引・契約書","termZh":"信息系统示范交易／合同文件","english":"Information System, Model Transaction, Contract Document","reading":"じょうほうしすてむ・もでるとりひき・けいやくしょ","breadcrumb":"","explanationJa":"ソフトウェア開発において、開発プロジェクトの要件や条件を明確に記載した文書である。これらの契約書は、クライアントと開発者の間での取引のルールや責任を定める重要な役割を果たす。また、情報システムはデータを管理し、処理する技術や手法を指し、モデル取引はそのシステムを実現するための具体的な見本やガイドラインを示す。例えば、特定のシステム開発に関する一連の要件がモデル取引として示され、その内容に基づいて契約書が作成される。これにより、双方が理解しやすく、後のトラブルを防ぐための効果的なコミュニケーション手段ともなる。\nHOME»用語集»法務»その他の法律・ガイドライン・技術者倫理","explanationZh":"日本信息系统采购、开发和服务交易中用于规范交易条件和责任分工的示范性合同文件。它可帮助双方明确需求、范围、变更、验收、知识产权、安全和责任限制等关键事项。"},{"id":"t0452","chapterId":"c09","chapterJa":"その他の法律・ガイドライン・技術者倫理","chapterZh":"其他法律、指南与技术人员伦理","termJa":"デジタル社会形成基本法","termZh":"日本《数字社会形成基本法》","english":"Digital Society Formation Basic Act","reading":"でじたるしゃかいけいせいきほんほう","breadcrumb":"","explanationJa":"デジタル技術を活用して社会を形成・発展させるための基本的な法律である。この法律は、情報通信技術の普及やデジタルサービスの向上を目指し、国民の生活の質を向上させることを目的としている。例えば、教育や医療、交通などの分野でデジタル技術を活用することで、効率的で便利な社会を実現することが期待されている。また、個人情報の保護やセキュリティの確保も重要な要素であり、これにより安心してデジタルサービスを利用できる環境を整えることが求められる。この法律は、デジタル社会に適した持続可能な発展を促すための枠組みを提供している。","explanationZh":"日本推进数字社会建设的基础性法律，规定数字化政策的基本理念、国家和地方政府责任以及推进体制。其目标包括利用数字技术提高行政与社会效率，并兼顾安全、便利和包容性。"},{"id":"t0453","chapterId":"c09","chapterJa":"その他の法律・ガイドライン・技術者倫理","chapterZh":"其他法律、指南与技术人员伦理","termJa":"官民データ活用推進基本法","termZh":"日本《官民数据活用推进基本法》","english":"Basic Act on the Promotion of Public-Private Data Utilization","reading":"かんみんでーたかつようすいしんきほんほう","breadcrumb":"","explanationJa":"公共と民間のデータを活用して社会の発展を促進することを目的とした法律である。この法律は、政府や地方自治体が保有するデータを民間企業や研究者に提供し、イノベーションを推進することを目指している。具体的には、公共のデータを電子的に整理・公開することで、企業が新しいサービスや技術を開発しやすくする環境を整える。例えば、交通データや地域の統計情報などが活用され、都市計画やビジネスの戦略に役立てられる。また、この法律はデータの安全性やプライバシーの保護についても考慮しており、信頼性の高いデータ活用を促進することを重視している。","explanationZh":"日本为促进政府和民间数据有效利用而制定的基础性法律，强调开放数据、数据流通和数字技术应用。其目的在于通过官民数据利用提升公共服务和经济社会活动效率。"},{"id":"t0454","chapterId":"c09","chapterJa":"その他の法律・ガイドライン・技術者倫理","chapterZh":"其他法律、指南与技术人员伦理","termJa":"e-文書法","termZh":"日本《e-文书法》","english":"e-Document Law","reading":"いーぶんしょほう","breadcrumb":"","explanationJa":"電子的な情報を記録して保存することを認める法律である。この法律は、紙の文書だけでなく、電子データも同等に扱うことを目的としている。例えば、契約書や請求書を電子フォーマットで作成し、署名や保存を行うことが合法とされるため、企業や個人にとって利便性が高まる。この法律により、ペーパーレス化が進み、コスト削減や効率化が実現される。また、電子記録の信頼性や真正性を確保するための技術的要件も定められており、適正な管理やセキュリティ対策が求められる。これは、電子商取引や情報管理の分野での重要な基盤となる。","explanationZh":"日本允许符合条件的法律规定保存文书以电子形式保存的一组制度性法律。企业将纸质文件电子化保存时，需要满足真实性、可读性等相关要求，并确认具体业务适用条件。"},{"id":"t0455","chapterId":"c09","chapterJa":"その他の法律・ガイドライン・技術者倫理","chapterZh":"其他法律、指南与技术人员伦理","termJa":"電子帳簿保存法","termZh":"日本《电子账簿保存法》","english":"Electronic Bookkeeping Preservation Act","reading":"でんしちょうぼほぞんほう","breadcrumb":"","explanationJa":"企業が帳簿や証憑書類を電子的に保存する際のルールを定めた法律である。この法律は、従来の紙の帳簿に代わって、デジタル形式での保存を推進することを目的としている。例えば、企業が経費の請求書をスキャニングし、電子データとして保管することが認められる。これによって、保管スペースの削減や効率的な管理が可能となり、また、電子データは検索や集計も容易であるため、業務の効率化が期待される。この法律には、保存期間やデータの改ざん防止策など、遵守すべき具体的な要件も含まれており、企業はそれらを満たす必要がある。","explanationZh":"日本规定账簿、凭证和电子交易数据以电子方式保存时相关要求的法律。组织需要按照适用规则确保数据真实性、可检索性和保存期限等，以满足税务和审计要求。"},{"id":"t0456","chapterId":"c09","chapterJa":"その他の法律・ガイドライン・技術者倫理","chapterZh":"其他法律、指南与技术人员伦理","termJa":"コンプライアンス","termZh":"合规","english":"Compliance","reading":"","breadcrumb":"","explanationJa":"法律や規則、社会的な基準に従うことを指す。この概念は、企業や組織が自らの行動を法律や倫理に適合させることが求められる場面で重要になる。例えば、企業が環境保護法や労働基準法に従わなかった場合、法的な処罰を受ける可能性があるため、コンプライアンスは非常に重要である。特に近年、データプライバシーや労働倫理に対する規制が厳しくなっており、企業はこれらに対応するために内部の規定や教育制度を整備する必要がある。これにより、信頼性の向上やリスク管理の強化が図られ、持続可能なビジネス活動の維持に寄与する。","explanationZh":"组织及其成员遵守适用法律法规、监管要求、合同、行业标准和内部规章的状态与活动。信息安全合规不仅是避免处罚，还包括建立责任、监控、教育和持续改进机制，确保要求实际落实。"},{"id":"t0457","chapterId":"c09","chapterJa":"その他の法律・ガイドライン・技術者倫理","chapterZh":"其他法律、指南与技术人员伦理","termJa":"フェイクニュース","termZh":"假新闻","english":"Fake News","reading":"","breadcrumb":"","explanationJa":"事実に基づかない情報や誤解を招く内容を含むニュース記事や情報のことを指す。これらはしばしば悪意を持って作成され、特定の意見や感情を煽る目的で流布される。例として、ソーシャルメディア上で広がる根拠のない噂や捏造された情報が挙げられる。人々の判断を誤らせ社会に混乱をもたらす危険性があるため、情報リテラシーが求められる。正確で信頼できる情報源を見極める力を養うことが、技術者としても重要であり、倫理的な責任感が求められる時代になっている。","explanationZh":"以新闻形式传播但内容虚假、误导或严重失实的信息。假新闻可能出于恶意，也可能源于错误，其快速传播会影响判断和社会信任，因此需要核实来源、证据和上下文。"},{"id":"t0458","chapterId":"c09","chapterJa":"その他の法律・ガイドライン・技術者倫理","chapterZh":"其他法律、指南与技术人员伦理","termJa":"マルインフォメーション","termZh":"恶意信息（Malinformation）","english":"Malinformation","reading":"","breadcrumb":"","explanationJa":"意図的に誤解を招くように操作された情報のことを指す。この情報は、主に悪意を持って他者を攻撃したり、社会に混乱を招くために流布されるものである。具体的には、事実に基づいているが、それを特定の文脈で誤って解釈させるような形で使用されることがある。このような情報は、個人の名誉を傷つけたり、不安を煽ったりする可能性があり、情報倫理や技術者倫理の観点から対処が求められる。倫理的な観点を持って情報を扱うことは、信頼性の高いコミュニケーションを維持するために非常に重要である。","explanationZh":"内容本身可能基于真实事实，但被有意脱离语境、选择性披露或用于伤害个人、组织或社会的信息。与“虚假信息”不同，关键在于真实信息被恶意利用的目的和方式。"},{"id":"t0459","chapterId":"c09","chapterJa":"その他の法律・ガイドライン・技術者倫理","chapterZh":"其他法律、指南与技术人员伦理","termJa":"ディスインフォメーション","termZh":"蓄意虚假信息（Disinformation）","english":"Disinformation","reading":"","breadcrumb":"","explanationJa":"故意に誤った情報を広める行為である。この情報は、多くの場合、人々の意見や行動を操作する目的で作成される。例えば、選挙の時期に特定の候補者に関する偽のニュースが流されることがあるが、これは投票行動に影響を与えようとする意図がある。SNSやインターネットを通じて迅速に拡散されるため、その影響力は大きく、社会に混乱を引き起こすこともある。情報倫理の観点から、この問題は深刻であり、技術者は正確な情報の提供に努めるべきである。また、無知や誤解を助長することなく、情報の重要性を理解し、それを広める責任を持つことが求められる。","explanationZh":"明知内容虚假或误导，仍出于操纵、欺骗或伤害目的故意制作和传播的信息。识别时应关注来源可信度、证据、传播动机和多源验证。"},{"id":"t0460","chapterId":"c09","chapterJa":"その他の法律・ガイドライン・技術者倫理","chapterZh":"其他法律、指南与技术人员伦理","termJa":"ミスインフォメーション","termZh":"错误信息（Misinformation）","english":"Misinformation","reading":"","breadcrumb":"","explanationJa":"誤った情報が意図せずに広まる現象を指す。この情報は、正確性を欠いたデータや誤解を招く内容を含むことが多く、拡散されることで人々の判断や行動に影響を及ぼす場合がある。たとえば、SNSで流れる不正確なニュース記事は、意図しない形で多くの人に拡散されることがある。ミスインフォメーションは特に、難解なトピックや新しい技術に関する情報において発生しやすく、情報源の確認が重要となる。技術者倫理の観点からは、正確で透明な情報提供が求められ、誤情報の流布防止に努めることが責任ある行動の一部である。","explanationZh":"不准确或虚假的信息，但传播者不一定具有故意欺骗的意图。它可能来自误解、过时资料或未经核实的转发，因此应通过事实核查和可信来源进行纠正。"},{"id":"t0461","chapterId":"c09","chapterJa":"その他の法律・ガイドライン・技術者倫理","chapterZh":"其他法律、指南与技术人员伦理","termJa":"デジタルタトゥー","termZh":"数字纹身","english":"Digital Tattoo","reading":"","breadcrumb":"","explanationJa":"個人がインターネット上に残す情報やデータのことを指す。この情報は、SNSの投稿やコメント、写真、動画、さらには検索履歴などの形で残るため、消去が難しいことが特徴である。例えば、友人との写真をSNSに公開した場合、その写真が誰かによって保存されたり、再共有されたりすることで、自分が意図した以上に広がる可能性がある。また、情報が長期間残ることで、将来的に就職活動や人間関係に影響を及ぼすこともあるため、注意が必要である。個人のプライバシーや安全にも関わるテーマであり、情報発信の際にはその影響を考慮することが重要である。","explanationZh":"个人在互联网和社交媒体发布的信息一旦被复制、转载或存档，往往难以彻底删除，并可能长期影响隐私、声誉和职业发展的现象。发布信息前应考虑其长期可见性和再传播风险。"},{"id":"t0462","chapterId":"c09","chapterJa":"その他の法律・ガイドライン・技術者倫理","chapterZh":"其他法律、指南与技术人员伦理","termJa":"ファクトチェック","termZh":"事实核查","english":"Fact-checking","reading":"","breadcrumb":"","explanationJa":"提出された情報や主張が真実であるかどうかを検証するプロセスである。この手法は、特にニュースやSNSなどで広まる情報の正確性を確認するために重要である。例えば、政治家の発言や報道内容をファクトチェックすることで、誤情報や虚偽の情報が拡散するのを防ぐ役割を果たす。また、情報を受け取る際の批判的思考を促し、より良い情報リテラシーの向上に寄与する。現代社会では、これが民主主義の健全な運営や社会的な信頼の維持に欠かせない要素となっている。技術者倫理においても、正確な情報提供は信頼性の確保に不可欠である。","explanationZh":"通过权威资料、原始证据、多来源交叉验证等方法，判断公开说法或信息是否准确的过程。事实核查应区分事实、观点和推测，并说明证据来源及不确定性。"},{"id":"t0463","chapterId":"c09","chapterJa":"その他の法律・ガイドライン・技術者倫理","chapterZh":"其他法律、指南与技术人员伦理","termJa":"フィルタリング","termZh":"过滤","english":"Filtering","reading":"","breadcrumb":"","explanationJa":"有害なサイトへのアクセスを制限するための技術や手法である。具体的には、インターネット接続を行う際に、特定のWebサイトやコンテンツをブロックすることで、ユーザーが不適切な情報にアクセスしないようにする。例えば、学校や職場では、学生や従業員が不適切なサイトにアクセスできないようにフィルタリングを行うことが一般的である。これにより、健全なネット環境が保たれ、情報倫理を守ることができる。また、フィルタリング技術は、ウイルスや悪意のあるソフトウェアからの保護を強化する役割も果たす。","explanationZh":"依据预先设定的规则或模型，对信息、通信或内容进行筛选、允许、阻止或分类的处理。可用于垃圾邮件、恶意网站、不当内容和数据泄露防护，但需要注意误报、漏报和规则维护。"},{"id":"t0464","chapterId":"c09","chapterJa":"その他の法律・ガイドライン・技術者倫理","chapterZh":"其他法律、指南与技术人员伦理","termJa":"ペアレンタルコントロール","termZh":"家长控制","english":"Parental Control","reading":"","breadcrumb":"","explanationJa":"子どもがインターネットやデジタルデバイスを使用する際に、不適切なコンテンツからの保護を目的とした技術や機能である。具体的には、特定のWebサイトへのアクセスを制限したり、利用時間を設定したりすることができる。例えば、保護者はブラウザやアプリの設定を通じて子どもに適したコンテンツをフィルタリングし、問題のある情報や影響を与える可能性のあるメディアを排除することができる。このように、子どものインターネット利用を安全かつ健全に保つための重要な手段であり、家族内の情報倫理を考慮する際にも重要な役割を果たしている。\nHOME»用語集»法務»標準化関連","explanationZh":"帮助监护人限制儿童使用设备、应用、网站和在线服务的功能。可设置使用时间、内容过滤、应用安装权限和消费限制等，但应与网络素养教育结合，而不能完全替代监督和沟通。"},{"id":"t0465","chapterId":"c10","chapterJa":"標準化関連","chapterZh":"标准化相关","termJa":"JIS","termZh":"JIS（日本产业标准）","english":"Japanese Industrial Standards","reading":"じす","breadcrumb":"","explanationJa":"日本の産業における標準規格を指すものである。この規格は、製品やサービスの品質、安全性、互換性を確保することを目的としており、商取引や技術の安定性を高める役割を果たす。例えば、電子機器や建材、自動車などに関する具体的な基準が定められており、企業はこの基準に従って製品を開発することで、消費者に安心して利用できる製品を提供できる。また、JISは国際的な規格とも密接に連携しており、グローバルな市場でも競争力を持つための基盤となっているため、重要な役割を担っている。","explanationZh":"日本国家标准体系，由日本相关标准化机制制定，用于统一产品、服务、管理体系和测试方法等要求。部分JIS标准与ISO/IEC国际标准等同或基于其制定。"},{"id":"t0466","chapterId":"c10","chapterJa":"標準化関連","chapterZh":"标准化相关","termJa":"IS","termZh":"国际标准（IS）","english":"International Standards","reading":"あいえす","breadcrumb":"","explanationJa":"国際的に合意されたルールや基準を指す用語である。これらの規格は、製品やサービスの品質を保証し、国際的な取引や協力をスムーズにするための基盤を提供する。たとえば、電子機器の安全性や互換性に関する規格は、異なる国や企業間での製品交換を容易にし、消費者の安全を確保することに寄与する。また、ISに従うことで、企業は国際市場で競争力を高めることができ、技術の進歩や環境保護に対する取り組みを強化することも期待される。このように、ISは国際的なビジネスや技術の標準化において、重要な役割を果たしている。","explanationZh":"由ISO等国际标准化组织正式发布、经过规定程序制定的国际标准。国际标准为不同国家和组织提供共同的技术或管理规范，有助于互操作、质量和国际贸易。"},{"id":"t0467","chapterId":"c10","chapterJa":"標準化関連","chapterZh":"标准化相关","termJa":"ISO","termZh":"国际标准化组织（ISO）","english":"International Organization for Standardization","reading":"あいえすおー","breadcrumb":"","explanationJa":"国際的に通用する標準を策定するための組織である。この機構は、製品やサービスの品質、信頼性、安全性など、さまざまな分野において標準を確立することを目的としている。例えば、ISO9001は品質管理に関する規格であり、多くの企業がこの規格を遵守することで、顧客に対して高品質な製品やサービスを提供することができる。また、ISO標準は国際的な取引やビジネスの一貫性を高め、異なる国や地域間の協力を促進する役割も果たしている。技術的な側面だけでなく、社会的な側面にも配慮した規格を制定することに重点を置いている。","explanationZh":"制定和发布广泛领域国际标准的国际非政府标准化组织。信息安全领域的ISO/IEC 27000系列等标准由ISO与IEC相关技术组织共同制定。"},{"id":"t0468","chapterId":"c10","chapterJa":"標準化関連","chapterZh":"标准化相关","termJa":"IEEE","termZh":"电气电子工程师学会（IEEE）","english":"Institute of Electrical and Electronics Engineers","reading":"あいとりぷるいー","breadcrumb":"","explanationJa":"電気・電子に関する技術の発展を促進するための国際的な学会である。この団体は、エンジニアや研究者が集まり、新しい技術や基準を制定し、業界の発展に寄与している。特に通信、コンピュータ技術、ロボティクスなどの分野で多くの規格を策定しており、これにより製品の相互運用性や安全性が向上する。例えば、Wi-FiやBluetoothなどの無線通信技術も、IEEEが制定した標準に基づいている。これにより、異なるメーカーのデバイス同士がスムーズに連携できるようになっている。技術者にとって欠かせない学術的なプラットフォームとして、継続的な革新を支えている。","explanationZh":"国际性的专业技术组织，在电气、电子、计算机和通信领域开展研究交流并制定大量技术标准。网络领域常见的IEEE 802系列包括以太网和无线局域网等标准。"},{"id":"t0469","chapterId":"c10","chapterJa":"標準化関連","chapterZh":"标准化相关","termJa":"デジュレスタンダード","termZh":"法定标准／正式标准（De Jure Standard）","english":"De Jure Standard","reading":"","breadcrumb":"","explanationJa":"正式に認められた基準や規格のことである。これは特定の機関や団体によって制定され、法律や規則に基づいて機能することが特徴である。つまり、製品やサービスがこの基準に従っていることが求められる。例えば、国際的な規格を制定するISO（国際標準化機構）によって定められる規格がデジュレスタンダードに該当する。これに対して、実際に広く使われているが正式には認められていない基準はデファクトスタンダードと呼ばれる。業界の信頼性や互換性を高め、消費者や企業が安心して製品を利用できる環境を整える役割を果たしている。","explanationZh":"由政府、国际标准组织或正式标准化机构按照规定程序制定并发布的标准。它具有正式认可的制定过程，与市场竞争中自然形成的事实标准相区别。"},{"id":"t0470","chapterId":"c10","chapterJa":"標準化関連","chapterZh":"标准化相关","termJa":"デファクトスタンダード","termZh":"事实标准（De Facto Standard）","english":"De Facto Standard","reading":"","breadcrumb":"","explanationJa":"正式に定められた標準ではなく、実際の使用において広く受け入れられた製品や方法を指す。例えば、特定のソフトウェアやプロトコルが業界内で主流となり、多くのユーザーに支持されることで、その技術が事実上の基準となることがある。このような状況は、特に技術分野で見られ、たとえばあるファイル形式がデファクトスタンダードとなることで、多くの製品がその形式をサポートするようになる。正式な標準が存在しなくても、実際の採用数や普及度によって、その有用性や影響力が高く評価されることが多い。\nHOME»用語集»システム構成要素»システムの構成","explanationZh":"并非由正式标准机构首先制定，而是因某项产品、技术或规格在市场上被广泛采用而事实上成为通用标准。其影响力主要来自市场占有率和生态系统，而非法律强制力。"},{"id":"t0471","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"集中処理","termZh":"集中处理","english":"Centralized Processing","reading":"しゅうちゅうしょり","breadcrumb":"","explanationJa":"データや処理が一箇所のサーバやコンピュータに集約される方式である。この方式では、すべての情報処理が中央のシステムで行われるため、管理や運用が比較的簡素である。例えば、企業のデータベースサーバが集中処理の一例であり、すべての社員がそのサーバを通じて情報を取得したり更新したりする。集中処理の利点は、データの一貫性が保たれ、セキュリティ管理が容易になることが挙げられる。しかし、中央システムに負担がかかるため、障害が発生すると全体に影響を及ぼすリスクがある。このため、システム設計では、効率性と信頼性のバランスを考慮する必要がある。","explanationZh":"把主要数据处理和计算资源集中在一处系统或数据中心统一执行的处理方式。便于统一管理和控制，但中心系统发生故障时可能影响范围较大，因此常需冗余和灾备措施。"},{"id":"t0472","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"分散処理","termZh":"分布式处理","english":"Distributed Processing","reading":"ぶんさんしょり","breadcrumb":"","explanationJa":"複数のコンピュータやデバイスが協力して処理を行う方式である。この手法は、大量のデータを効率的に処理したり、高速な応答を実現するために利用される。例えば、大型のWebサービスやシステムでは、異なるサーバがそれぞれのタスクを担当し、全体としての処理速度を向上させることが可能である。また、負荷の分散や信頼性の向上にも寄与し、特定のコンピュータにかかる負担を軽減することで、システム全体の安定性を高める。これにより、システムがダウンするリスクを低減し、耐障害性を強化することができる。","explanationZh":"把处理任务和数据分散到多个计算节点协同执行的方式。可提升扩展性、性能和容错能力，但需要解决节点协调、数据一致性、网络依赖和安全管理等问题。"},{"id":"t0473","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"対話型処理","termZh":"交互式处理","english":"Interactive Processing","reading":"たいわがたしょり","breadcrumb":"","explanationJa":"ユーザーがシステムとリアルタイムで対話しながら処理を行う方法である。この形態では、ユーザーが直接入力を行うと、その入力に基づいて即座に結果が返されるため、滑らかな操作体験が実現される。例えば、チャットボットやオンラインゲームにおいて、ユーザーの指示に対してシステムがその場で反応し、次のアクションを促すことが挙げられる。迅速なフィードバックが求められるアプリケーションに適しており、ユーザーの要求に応じた柔軟な対応が可能である。これにより、特に教育や販売、医療分野などの利用シーンでは、より良いユーザーエクスペリエンスを提供することが可能である。","explanationZh":"系统根据用户输入立即进行处理并返回结果的处理方式。适用于查询、在线操作和人机交互场景，重点关注响应时间和并发处理能力。"},{"id":"t0474","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"バッチ処理","termZh":"批处理","english":"Batch Processing","reading":"ばっちしょり","breadcrumb":"","explanationJa":"データを一定の単位（バッチ）でまとめて処理する方式を指す。これは、単一のデータを即座に処理するのではなく、集めたデータを一定の時間間隔でまとめて実行するため、効率的にリソースを使用できる。例えば、銀行の給与計算や帳簿の更新など、多数のデータが発生する場合に効果的である。また、バッチ処理では、夜間や業務が少ない時間帯に処理を行うことが多く、システムの負荷を抑えつつ大量のデータ処理を実施できるメリットがある。この手法は、情報システムの運用において広く利用されている。","explanationZh":"把一定期间积累的数据或作业集中成批，在指定时间顺序处理的方式。适合工资结算、账务汇总等不要求立即响应的大量处理，可提高资源利用效率。"},{"id":"t0475","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"リアルタイム処理","termZh":"实时处理","english":"Real-Time Processing","reading":"りあるたいむしょり","breadcrumb":"","explanationJa":"データや情報を入力してから処理結果を出力するまでの時間が非常に短く、ほぼ即座に行われる処理形態を指す。これにより、例えば航空機の飛行データ、医療機器のモニタリング、ゲームなど、タイムリーな反応が求められる状況において、迅速かつ正確な情報処理が可能になる。通常、システムにおいて処理遅延を許容しない要件があり、特定の時間内に処理を完了することが求められるため、高い信頼性と応答性が求められる。これにより、ユーザーはストレスなくサービスを利用できるようになる。","explanationZh":"在事件或输入发生后，在规定的极短时间内完成处理并产生结果的方式。常用于交易、控制和监控系统，对响应时间、可靠性和持续可用性要求较高。"},{"id":"t0476","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"機能配分","termZh":"功能分配","english":"Function Allocation","reading":"きのうはいぶん","breadcrumb":"","explanationJa":"システムやプログラムにおいて、異なる機能をどのように割り当てるかを決定するプロセスである。これは、システム全体の設計や効率性に大きな影響を与える。例えば、大規模なソフトウェア開発において、ユーザーのインターフェース、データの処理、およびデータベースの管理といった異なる機能を、適切なサーバやモジュールに分配することが重要である。これにより、各部分の負担を軽減し、性能を最適化することができる。機能配分を正しく行うことで、システムの拡張性や保守性が向上し、トラブルシューティングも容易になるため、プロジェクトの成功に不可欠な要素となる。","explanationZh":"把系统所需功能合理分配到不同设备、服务器、软件模块或处理节点的设计活动。合理分配可改善性能、可靠性、维护性和安全边界。"},{"id":"t0477","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"冗長構成","termZh":"冗余配置","english":"Redundant Configuration","reading":"じょうちょうこうせい","breadcrumb":"","explanationJa":"システムの可用性を高めるために、同じ機能を持つ複数のコンポーネントを用意する設計のことである。この手法は、万が一の障害に対してシステムが停止しないように工夫されている。例えば、サーバの冗長構成では、二台以上のサーバが同時に動作し、一台に障害が発生しても他のサーバがその機能を引き継ぐことで、サービスの継続性を保つことができる。データセンターやクラウド環境など、特に稼働が重要視されるシステムで広く利用されており、運用コストやメンテナンスを考慮しながら、信頼性を高めるための基本的な戦略として位置づけられている。","explanationZh":"为关键组件设置一个或多个备用资源，使单个组件故障时系统仍能继续运行的配置。可用于服务器、网络、存储和电源等，是提高可用性的基本手段。"},{"id":"t0478","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"負荷分散","termZh":"负载均衡","english":"Load Balancing","reading":"ふかぶんさん","breadcrumb":"","explanationJa":"複数のサーバやリソースに対して処理を均等に分配し、全体の効率を向上させる手法である。このアプローチは、特にWebサイトやオンラインサービスなどでアクセスが集中した際に重要で、特定のサーバに負担が集中するのを防ぎ、システムの安定性や応答速度を向上させる役割を果たす。たとえば、利用者からのリクエストを複数のサーバに分配することで、一つのサーバが過負荷になるのを防ぎ、全体の処理能力を最大限に引き出すことができる。また、サーバが故障した場合のバックアップ機能としても機能し、サービスの中断を防ぐことができるため、企業にとって非常に重要な技術である。","explanationZh":"把用户请求或计算负载分配到多个服务器、链路或资源上，避免单点过载并提升性能与可用性的技术。健康检查可用于绕过故障节点。"},{"id":"t0479","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"デュアルシステム","termZh":"双重系统（Dual System）","english":"Dual System","reading":"","breadcrumb":"","explanationJa":"同一の処理を二つの独立したシステムで行い、結果を照合する仕組みである。この方法は、システムの信頼性を高めるために用いられ、どちらか一方でエラーが発生した場合でも、もう一方の結果を基に正確性を保つことができる。例えば、金融機関でのトランザクション処理や、航空機の制御システムなど、高い信頼性が求められる場面で広く採用されている。また、デュアルシステムを利用することで、障害発生時の迅速な復旧が可能になり、システム全体の安全性向上に寄与する。","explanationZh":"两套系统同时执行相同处理并相互核对结果的高可靠性结构。若结果不一致，可检测异常并进行切换或判断，成本较高但可靠性强。"},{"id":"t0480","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"デュプレックスシステム","termZh":"双机系统（Duplex System）","english":"Duplex System","reading":"","breadcrumb":"","explanationJa":"主系と従系の2つのコンピュータシステムを用意し、主系がメインの処理を行い、従系は普段は別の低優先度の処理をしながら待機している構成のことを指す。このシステムは、主系に障害が発生した時に迅速に従系が引き継ぐことで、運用の継続性を確保するために使用される。例えば、金融機関や公共サービスなど、システムの信頼性が求められる場面で利用されることが多い。このように冗長性を持たせることで、システムダウンのリスクを低減し、安定したサービス提供を目指す仕組みである。","explanationZh":"由主系统和备用系统组成，当主系统故障时由备用系统接替处理的冗余结构。根据备用系统运行状态可分为热备、温备和冷备等形式。"},{"id":"t0481","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"クラスタ","termZh":"集群","english":"Cluster","reading":"","breadcrumb":"","explanationJa":"複数のコンピュータやサーバを組み合わせて、一つのシステムとして動作させる構成である。これにより、可用性や性能の向上が図られる。たとえば、サーバのクラスタでは、複数のサーバが連携してデータを処理し、もし一台のサーバが故障しても、他のサーバがその機能を引き継ぐことでシステム全体の稼働を維持できる。さらに、クラスタは負荷分散を行い、多くのユーザーからのリクエストを効率的に処理することができるため、大規模なWebサービスやデータセンターでよく利用されている。このように、クラスタはシステムの信頼性と性能を同時に向上させる重要な技術である。","explanationZh":"将多台计算机或服务器组合成一个逻辑系统共同提供服务的架构。可用于负载均衡、高可用和并行处理，单个节点故障时其他节点可继续承担业务。"},{"id":"t0482","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"主系","termZh":"主系统／主用系统","english":"Main System","reading":"しゅけい","breadcrumb":"","explanationJa":"システム構成において、現在運用されている主要なシステムを指す。現用系とも呼ばれる。これは、組織が日常業務を行うために必要不可欠なシステムであり、実際のデータ処理や情報管理を担っている。その安定性や信頼性が重要視されており、技術的な要求に応じて定期的に更新や保守が行われる。また、バックアップシステムや冗長構成も含まれることが多く、万が一のトラブルに備えた設計となっている。主系が適切に運用されることで、業務の継続性が確保され、効率的な運用が実現される。","explanationZh":"冗余系统中正常情况下承担实际业务处理的系统。应与备用系统保持必要的数据或状态同步，以便发生故障时顺利切换。"},{"id":"t0483","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"従系","termZh":"备用系统／从系统","english":"Standby System","reading":"じゅうけい","breadcrumb":"","explanationJa":"システム構成において、主に高可用性を実現するための待機状態のシステムやコンポーネントである。待機系とも呼ばれる。これは、主システムが故障した際に、待機中のシステムが即座にその役割を引き継ぐ仕組みを指す。例えば、サーバが正常に機能しないとき、従系が自動的に起動して、サービスの継続を提供することでダウンタイムを最小限に抑える。従系（待機系）の導入により、システム全体の信頼性向上が図られ、重要なビジネスプロセスが中断されるリスクを低減させることができる。","explanationZh":"冗余结构中用于在主系统故障时接管业务的系统。根据准备程度可处于热备、温备或冷备状态，切换时间和成本各不相同。"},{"id":"t0484","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"クライアントサーバシステム","termZh":"客户端—服务器系统","english":"Client-Server System","reading":"","breadcrumb":"","explanationJa":"コンピュータネットワークにおいて、サービスを提供する側（サーバ）とサービスを利用する側（クライアント）の構成を指す。サーバはデータやリソースを集中管理し、クライアントはそのサーバから必要な情報を取得する仕組みである。例えば、Webサイトを閲覧する際、ブラウザがクライアントとなり、Webサーバからページデータをリクエストして表示する。この方法により、複数のクライアントが同時に同一のサーバにアクセスでき、効率的な情報共有が実現される。また、スケーラビリティも高く、サーバの性能を向上させることで、多くのクライアントに対応できる柔軟性があるため、企業の業務システムやオンラインサービスにおいて広く利用されている。","explanationZh":"由客户端发出请求、服务器集中提供数据或服务的系统架构。客户端和服务器分工明确，便于集中管理资源和权限，是常见的网络应用模式。"},{"id":"t0485","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"シンクライアント","termZh":"瘦客户端","english":"Thin Client","reading":"","breadcrumb":"","explanationJa":"主にサーバ上で処理を行い、クライアント端末はその結果を表示する仕組みを持つコンピュータである。この方式により、大規模な計算やデータ処理を専門のサーバが行い、各端末は軽量なため、ハードウェアのコストを抑えることができる。たとえば、企業内でのデータ管理やアプリケーション実行において、シンクライアントを利用することで、個々の端末に高性能なPCを必要とせず、運用管理も容易になる。また、セキュリティの観点からも、データがサーバに集中するため、情報漏洩のリスクを低減することができる。これは、効率的な業務運営を支えるための重要な技術である。","explanationZh":"终端只承担显示、输入等较少处理，把应用执行和数据保存主要放在服务器端的计算模式。可简化终端管理并减少本地数据泄露，但依赖网络和后端服务可用性。"},{"id":"t0486","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"仮想化","termZh":"虚拟化","english":"Virtualization","reading":"かそうか","breadcrumb":"","explanationJa":"物理的なハードウェアリソースを抽象化し、複数の仮想環境を構築する技術である。これにより、一つの物理サーバ上で複数の仮想マシンを稼働させ、それぞれが独立したオペレーティングシステムやアプリケーションを実行できる。この技術は、サーバのリソースを効率良く利用できるメリットがあり、負荷の分散や高可用性の確保、管理の簡略化などに寄与する。例えば、企業がデータセンターを運営する際に、物理サーバを仮想化することで、コスト削減や運用の柔軟性を向上させることができる。また、仮想化技術はクラウドコンピューティングの基盤でもあり、様々なサービスを迅速に提供する手段としても重要である。","explanationZh":"通过软件抽象把物理计算、存储或网络资源划分为多个逻辑资源的技术。可提高资源利用率和灵活性，但也需要管理虚拟化平台、隔离和资源争用风险。"},{"id":"t0487","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"VM","termZh":"虚拟机（VM）","english":"Virtual Machine","reading":"ぶいえむ","breadcrumb":"","explanationJa":"仮想マシンの略で、物理的なコンピュータの中で、複数の仮想的なコンピュータを作成する技術である。それぞれの仮想マシンは独自のオペレーティングシステムを持っており、物理的なハードウェアを共有しながら動作する。この方式によって、サーバのリソースを効率的に利用し、異なる環境でのアプリケーションのテストや運用が容易になる。たとえば、一つの物理サーバの中に、WindowsやLinuxなど異なるOSの仮想マシンを構築し、それぞれで異なるソフトウェアを開発・運用することが可能である。この技術はクラウドコンピューティングの基盤でも利用され、柔軟性とスケーラビリティを提供するため、多くの企業で重宝されている。","explanationZh":"在物理主机上由虚拟化软件创建、具有独立操作系统和虚拟硬件环境的逻辑计算机。多个VM可以共享同一物理资源，同时保持一定隔离。"},{"id":"t0488","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"VDI","termZh":"虚拟桌面基础设施（VDI）","english":"Virtual Desktop Infrastructure","reading":"ぶいでぃーあい","breadcrumb":"","explanationJa":"デスクトップ仮想化の一形態であり、ユーザーのデスクトップ環境を中央のサーバ上で仮想的に管理し、提供する技術である。この仕組みによって、ユーザーはさまざまなデバイスから自分のデスクトップへアクセスでき、実際のハードウェアに依存することなく、同一の作業環境を利用することが可能となる。例えば、企業内の社員がリモートワークを行う際、自宅のPCやタブレットを使ってオフィスのデスクトップにアクセスすることで、業務を遂行できる。VDIはセキュリティの向上や、管理の効率化、コスト削減といった利点もあり、近年では多くの企業で導入が進んでいる。さらに、ソフトウェアのアップデートや設定の変更も容易に行えるため、運用管理の手間を大幅に軽減することができる。","explanationZh":"把用户桌面操作系统和应用集中运行在数据中心或云端，并通过网络向终端提供桌面画面的技术。便于集中管理和保护数据，但对服务器容量和网络质量要求较高。"},{"id":"t0489","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"Webシステム","termZh":"Web系统","english":"Web System","reading":"うぇぶしすてむ","breadcrumb":"","explanationJa":"インターネットを利用して提供されるアプリケーションやサービスのことを指す。これらは主にWebブラウザを通じてアクセスされ、特別なソフトウェアをインストールすることなく使用できる。例えば、オンラインバンキングやショッピングサイト、ソーシャルメディアなどが挙げられる。Webシステムの利点は、どのデバイスからもアクセス可能で、リアルタイムでのデータ共有や更新が容易である点である。また、ユーザーが常に最新の情報を取得できるため、使いやすさや利便性が高い。このように、Webシステムは企業や個人のニーズに応じたさまざまな機能を提供し、現代の情報社会において不可欠な存在となっている。","explanationZh":"通过Web浏览器访问，由Web服务器、应用服务器、数据库等组件构成的信息系统。其安全重点包括身份认证、会话管理、输入验证、TLS和应用漏洞防护。"},{"id":"t0490","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"Webブラウザ","termZh":"Web浏览器","english":"Web Browser","reading":"うぇぶぶらうざ","breadcrumb":"","explanationJa":"インターネット上の情報を表示するためのソフトウェアである。主な機能としては、Webページを取得し、ユーザーが見ることができる形式に変換して表示することである。例えば、Google ChromeやFirefox、Safariといったアプリケーションがそれにあたる。Webブラウザは、HTMLやCSS、JavaScriptといった技術を利用してページ内容を構築し、ユーザーがリンクをクリックすることでページ間を移動できるようにする。また、ブックマーク機能や閲覧履歴の管理、拡張機能の追加といった便利な機能も備えており、日常的なインターネット利用をサポートしている。セキュリティ対策も強化されており、安全にWebを楽しむための重要なツールである。","explanationZh":"用于请求、解析并显示Web内容以及执行网页脚本的客户端软件。浏览器应及时更新，并通过安全设置、扩展管理和站点权限控制降低恶意网页风险。"},{"id":"t0491","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"Webサーバ","termZh":"Web服务器","english":"Web Server","reading":"うぇぶさーば","breadcrumb":"","explanationJa":"WebページやWebアプリケーションをインターネットユーザーに提供するためのコンピュータやソフトウェアである。主にHTTPプロトコルを利用して、ユーザーのリクエストに応じて必要な情報やファイルを送信する役割を持っている。具体的には、ユーザーがブラウザにURLを入力すると、WebサーバはそのURLに対応するデータを検索し、要求されたページを返す。これにより、Webサイトは利用者に対してコンテンツを表示できる。また、サーバには静的なHTMLファイルだけでなく、動的なコンテンツ（データベースからの情報を含むなど）の生成も行えるものも存在し、 PHPやRubyなどのプログラミング言語を使用することが一般的である。","explanationZh":"通过HTTP/HTTPS向客户端提供网页、文件或Web服务的服务器软件或主机。应实施补丁、TLS、访问控制、最小权限和日志监控等安全措施。"},{"id":"t0492","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"ピアツーピア","termZh":"点对点（P2P）","english":"Peer-to-Peer","reading":"","breadcrumb":"","explanationJa":"ネットワークシステムの構成方式の一つであり、全ての参加者（ノード）が対等な関係を持ち、直接通信を行うことができる仕組みである。この方式では、特定のサーバを介さずにデータやリソースを共有するため、分散型の特性を持ち、効率的な通信が可能になる。例えば、ファイル共有ソフトウェアやブロックチェーン技術では、このピアツーピア構成が用いられ、自律的にネットワークが運営される。このように、個々のノードがデータの提供者であり、同時に利用者としても機能するため、システムの耐障害性が高まり、柔軟な運用が実現される。特に、コスト削減やスケーラビリティ向上の観点からも、ピアツーピア方式は注目されている。","explanationZh":"网络节点之间可以直接互相提供和使用资源，而不完全依赖中心服务器的通信或系统模式。具有分散和扩展性特点，但需要注意数据控制、版权和恶意节点风险。"},{"id":"t0493","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"クラウドコンピューティング","termZh":"云计算","english":"Cloud Computing","reading":"","breadcrumb":"","explanationJa":"インターネットを通じてサーバやストレージ、アプリケーションなどのコンピュータ資源を提供する技術である。このシステム構成は、ユーザーが自分のデバイスに依存せずに、どこからでも必要なリソースにアクセスできる柔軟性を持つ。また、必要に応じて資源を増減できるため、コスト効率や運用の簡便さが実現される。例えば、企業は自社のサーバを保有することなく、クラウドサービスを利用してデータの保存やアプリケーションの運用が可能であり、これによりシステムの冗長性やスケーラビリティが強化される。","explanationZh":"通过网络按需获取服务器、存储、平台和软件等共享计算资源的模式。具有弹性扩展、按需计费和快速部署等特点，同时需按照责任共担模型管理安全与合规。"},{"id":"t0494","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"SaaS","termZh":"软件即服务（SaaS）","english":"Software as a Service","reading":"さーす","breadcrumb":"","explanationJa":"ソフトウェア・アズ・ア・サービスの略で、インターネットを通じてソフトウェアを提供する形態の一つである。ユーザーは、特定のアプリケーションを自分のコンピュータにインストールすることなく、Webブラウザを介してサービスを利用することができる。この方式では、ソフトウェアのアップデートやメンテナンスなどは提供者側が行うため、ユーザーは手間をかけることなく最新の機能を利用できる。例えば、Google WorkspaceやSalesforceなどがこの形態に該当し、ビジネスや個人用の様々なアプリケーションが提供されている。インフラやプラットフォームを自分で管理する必要がないため、特に中小企業にとってコスト削減や業務効率化に寄与する利点がある。","explanationZh":"由服务商通过网络直接提供可使用的应用软件，用户通常无需管理底层操作系统和基础设施。用户仍需负责账号、数据、权限和自身配置等安全事项。"},{"id":"t0495","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"PaaS","termZh":"平台即服务（PaaS）","english":"Platform as a Service","reading":"ぱーす","breadcrumb":"","explanationJa":"プラットフォーム・アズ・ア・サービスの略で、アプリケーション開発に必要な基盤を提供するクラウドサービスの一形態である。ユーザーは、インフラストラクチャの管理を気にせず、アプリケーションの開発やデプロイ、実行などに集中できるため、開発作業が効率的に行える。具体的な例としては、Google App EngineやMicrosoft Azureが挙げられ、これらは開発者にプログラミング言語やデータベースの選択肢を提供し、高度なスケーラビリティもサポートする。自動的にリソースをスケールしたり、アプリケーションのパフォーマンスを監視したりする機能を持つため、開発の迅速化やコスト削減に寄与する。","explanationZh":"云服务商提供应用开发和运行所需的平台、中间件、数据库等环境，用户主要管理自己的应用和数据。底层基础设施由服务商负责维护。"},{"id":"t0496","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"IaaS","termZh":"基础设施即服务（IaaS）","english":"Infrastructure as a Service","reading":"いあーす","breadcrumb":"","explanationJa":"インフラストラクチャ・アズ・ア・サービスの略で、クラウドコンピューティングの一形態である。これにより、企業は物理的なサーバやネットワーク設備を直接購入・管理することなく、仮想的な資源を必要に応じて利用できる。例えば、サーバのCPUやメモリ、ストレージをクラウドサービスプロバイダーから提供され、これを基に独自のシステムを構成することができる。これにより、企業は初期投資を抑えつつ、スケーラブルなインフラを迅速に構築できるため、ビジネスの agility を向上させることが可能である。需要に合わせてリソースを増減できるため、特にトラフィックが変動するWebサービスなどに適している。","explanationZh":"云服务商提供虚拟服务器、网络、存储等基础资源，用户负责操作系统、应用、账号和数据等较多层面的管理。相较SaaS，用户承担的安全责任更多。"},{"id":"t0497","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"エッジコンピューティング","termZh":"边缘计算","english":"Edge Computing","reading":"","breadcrumb":"","explanationJa":"データ処理をクラウドではなく、デバイスやネットワークの端に近い場所で行うコンピューティングの構成である。これにより、データの転送距離を短縮し、リアルタイムでの処理が可能となる。例えば、スマートフォンやIoTデバイスがデータをその場で処理することによって、遅延を最小限に抑え、高速な応答が得られる。また、帯域幅の使用を削減するため、複数のデバイスが生成する大量のデータを即座に解析し、必要な情報だけをクラウドに送信する仕組みを持つ。このように、システム全体の効率を向上させる役割を果たす。","explanationZh":"把部分数据处理和计算从中心云下沉到靠近数据产生位置的边缘设备或节点。可降低延迟和网络传输量，但需要对大量分散节点进行安全管理和更新。"},{"id":"t0498","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"RAID","termZh":"独立磁盘冗余阵列（RAID）","english":"Redundant Array of Independent Disks","reading":"れいど","breadcrumb":"","explanationJa":"複数のハードディスクドライブを組み合わせて、データの冗長性やパフォーマンスを向上させる技術である。データを複数のディスクに分散して書き込むことにより、データの安全性を高めたり、読み書きの速度を向上させたりする。例えば、RAID 0という構成では、データを複数のディスクに分けて同時にアクセスするため、パフォーマンスが大幅に向上する。一方、RAID 1ではデータを二重に保存しており、一方のディスクが故障してもデータが失われるリスクを減少させる。このように、RAIDはデータの信頼性や性能を向上させるため、企業のサーバ環境や大容量データを扱うシステムにおいて特に重要である。","explanationZh":"通过多块磁盘组合实现性能提升或数据冗余的存储技术。不同RAID级别在容量、性能和容错能力之间权衡；RAID不能替代备份。"},{"id":"t0499","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"NAS","termZh":"网络附加存储（NAS）","english":"Network Attached Storage","reading":"なす","breadcrumb":"","explanationJa":"ネットワークに接続されたストレージデバイスのことである。複数のコンピュータやデバイスからアクセスできるよう設計されており、データの保存や共有を効率的に行うためのシステムである。家庭や企業で、ファイルのバックアップやメディアのストリーミングに利用される。NASは専用のオペレーティングシステムを持ち、ユーザーはWebブラウザを通じて簡単に管理できる。また、RAID（冗長ディスク構成）機能を搭載しているものも多く、データの冗長性を確保することで、信頼性を高めることができる。このように、NASは便利で効率的なデータ管理の手段として広く使用されている。","explanationZh":"通过IP网络向客户端提供文件级共享服务的专用存储设备或系统。常通过SMB/NFS等协议访问，适合集中共享文件并进行权限和备份管理。"},{"id":"t0500","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"SAN","termZh":"存储区域网络（SAN）","english":"Storage Area Network","reading":"さん","breadcrumb":"","explanationJa":"ストレージエリアネットワークの略称で、主にデータストレージを効率的に扱うためのネットワーク技術である。高速なデータ転送を実現するために、専用のネットワークを介してサーバとストレージ装置を直接接続する。FC-SAN（ファイバーチャネルSAN）は光ファイバーを使用し、IP-SANはインターネットプロトコルを用いる。これにより、大量のデータを高い信頼性で送受信でき、ストレージの管理が集中化されるため、システムのパフォーマンスが向上する。多くの企業では、SANを利用してデータベースや仮想環境のストレージニーズに対応し、効率的で安全なデータ管理を実現している。","explanationZh":"为服务器提供块级存储访问的高速专用存储网络。常用于数据中心的大型存储系统，可通过光纤通道或iSCSI等技术实现集中存储。"},{"id":"t0501","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"フォールトトレラント","termZh":"容错／故障容忍","english":"Fault Tolerance","reading":"","breadcrumb":"","explanationJa":"システムが障害や故障が発生しても、正常に機能し続ける能力を指す。この技術は、特に重要な業務を行う情報システムやインフラにおいて求められ、障害発生時の影響を最小限に抑えることができる。例えば、サーバに冗長性を持たせることで、一方のサーバが故障しても、他のサーバが引き続きサービスを提供する仕組みがこれにあたる。また、データのバックアップや瞬時に切り替え可能なネットワーク構成などもフォールトトレラントの一環であり、信頼性の高いシステムを作成するための重要な要素である。これにより、業務の継続性やデータ保護が向上し、企業の運営において安定した環境を提供する。","explanationZh":"系统在部分组件发生故障时仍能继续提供规定功能的能力或设计思想。通常通过冗余、错误检测、自动切换等手段实现，提高业务连续性。"},{"id":"t0502","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"フェールセーフ","termZh":"故障安全（Fail-Safe）","english":"Fail-Safe","reading":"","breadcrumb":"","explanationJa":"システムや装置が故障した場合にも安全性を確保するための設計手法である。この設計理念は、故障の影響を最小限に抑え、システムが誤動作を起こしても安全に停止したり、危険な状態を避けるようにするものである。例えば、飛行機の設計においては、エンジンの故障時に自動で安全な飛行を維持できるシステムが組み込まれている。これにより、万一の事態が発生しても乗客や乗員の安全が保たれる仕組みが整えられている。さらに、フェールセーフ設計は産業機械や交通システムなど、様々な分野で重要視されており、安全性向上に寄与している。","explanationZh":"系统发生故障时自动转移到不会造成严重危害的安全状态的设计原则。例如门禁系统根据安全目标设计为故障时保持锁闭或允许疏散。"},{"id":"t0503","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"フールプルーフ","termZh":"防呆设计（Foolproof）","english":"Foolproof","reading":"","breadcrumb":"","explanationJa":"システムや製品が誤操作や誤使用に対して保護されるよう設計された状態を指す。具体的には、意図しない操作や間違った使い方をしても、事故や損害が発生しにくいように設計されていることを意味する。この考え方は、特に安全が重要視される工業製品やソフトウェアにおいて広く採用されている。例えば、特定のボタンを押すためには、特定の手順を踏む必要がある設計や、誤って操作できないように物理的に形状を工夫することなどが挙げられる。フールプルーフ設計は、多くのユーザーが安心して使用できる環境を提供し、トラブルを未然に防ぐことを目的としている。","explanationZh":"通过设计使用户难以进行错误操作，或即使操作错误也不造成严重后果的理念。常见方法包括限制无效输入、物理接口防反插和危险操作二次确认。"},{"id":"t0504","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"ヒューマンエラー","termZh":"人为错误","english":"Human Error","reading":"","breadcrumb":"","explanationJa":"人間が行う作業や判断において発生するミスや誤りを指す。これは、操作ミス、判断ミス、知識不足など、様々な原因によって生じることがある。ヒューマンエラーは多くの分野で課題となり、特に信頼性設計においては、その影響を軽減することが重要である。たとえば、航空業界や医療分野では、ヒューマンエラーが引き起こす事故やトラブルのリスクを最小限に抑えるため、チェックリストや訓練プログラムを導入している。このような対策により、システム全体の安全性を向上させ、人間の能力や限界を考慮した設計が求められている。","explanationZh":"由于疏忽、误解、经验不足或操作失误造成的非故意错误。可通过易用设计、培训、复核、自动化和最小权限等措施降低发生概率和影响。"},{"id":"t0505","chapterId":"c11","chapterJa":"システムの構成","chapterZh":"系统构成","termJa":"UPS","termZh":"不间断电源（UPS）","english":"Uninterruptible Power Supply","reading":"ゆーぴーえす","breadcrumb":"","explanationJa":"無停電電源装置のことであり、主に電力供給が途切れた際に、接続された機器に対して瞬時に電源を提供する役割を持つ。これにより、コンピュータやサーバなど、大切なデータやサービスを行う機器が電力の中断によって停止するのを防ぐことができる。例えば、停電が発生しても、UPSが介入することで数分間は電力を供給し続け、ユーザーは慌てずにデータを保存したり、機器を適切にシャットダウンすることが可能である。また、UPSはサージ保護機能を持つものも多く、雷や電力の急激な変動から機器を守る役割も果たす。このように、UPSは特にビジネス環境やデータセンターにおいて、信頼性の高い稼働を維持するための重要な装置である。\nHOME»用語集»システム構成要素»システムの評価指標","explanationZh":"在市电中断或电压异常时短时间向设备持续供电的装置，可为系统安全关机或切换备用电源争取时间。它是机房电源可靠性的重要保障。"},{"id":"t0506","chapterId":"c12","chapterJa":"システムの評価指標","chapterZh":"系统评价指标","termJa":"レスポンスタイム","termZh":"响应时间","english":"Response Time","reading":"","breadcrumb":"","explanationJa":"システムが入力に対して応答を返すまでの時間のことを指す。具体的には、ユーザーが何かを操作した瞬間から、システムがその結果を表示するまでの時間を測定するものである。この応答時間は、ユーザーの体感速度に大きく影響し、特にインターネットサービスやアプリケーションにおいては非常に重要な性能指標となっている。例えば、Webページを開くときに表示されるまでの時間が長いと、ユーザーはストレスを感じて離脱することがある。そのため、開発者はこのレスポンスタイムを短縮するための最適化を図ることが求められ、システムの全体的なユーザー体験の向上に寄与している。加えて、レスポンスタイムはシステムの効率性や信頼性を評価するための基準ともなる。","explanationZh":"从系统接收到请求到用户获得相应结果所经过的时间。它反映交互性能，通常包括等待、处理、传输等多个部分。"},{"id":"t0507","chapterId":"c12","chapterJa":"システムの評価指標","chapterZh":"系统评价指标","termJa":"スループット","termZh":"吞吐量","english":"Throughput","reading":"","breadcrumb":"","explanationJa":"システムが単位時間あたりに処理できるデータ量や作業の量を示す指標である。具体的には、ネットワークの通信速度やデータベースのクエリ処理能力など、さまざまなシステム性能の評価に利用される。例えば、1秒間に1000件のトランザクションを処理できるシステムは、スループットが1000トランザクション／秒（TPS）と表現される。この指標は、システムの効率性や性能を把握するのに重要であり、適切なスループットを維持することで、ユーザーに快適な体験を提供することが可能となる。また、スループットを向上させるためには、ハードウェアの強化やアルゴリズムの最適化などの工夫が求められる。","explanationZh":"系统在单位时间内能够处理的事务、数据或作业数量。吞吐量越高通常表示整体处理能力越强，但与单次响应时间不是同一个指标。"},{"id":"t0508","chapterId":"c12","chapterJa":"システムの評価指標","chapterZh":"系统评价指标","termJa":"MTBF","termZh":"平均故障间隔时间（MTBF）","english":"Mean Time Between Failures","reading":"えむてぃーびーえふ","breadcrumb":"","explanationJa":"機器やシステムの信頼性を評価する指標の一つである。具体的には、故障と故障の間に稼働している平均時間を示すもので、通常は時間単位で表される。MTBFが高いほど、システムや機器が安定して動作することを意味し、メンテナンスや運用効率の向上に寄与する。例えば、工場の生産ラインで使用される機械のMTBFが長ければ、故障による生産の停止が少なくなり、全体の生産性が向上する。この指標は、信頼性工学や保守管理において非常に重要であり、設計段階から運用管理まで幅広く活用される。","explanationZh":"可修复系统两次故障之间平均正常运行的时间。MTBF越长，一般表示系统可靠性越高。"},{"id":"t0509","chapterId":"c12","chapterJa":"システムの評価指標","chapterZh":"系统评价指标","termJa":"MTTR","termZh":"平均修复时间（MTTR）","english":"Mean Time to Repair","reading":"えむてぃーてぃーあーる","breadcrumb":"","explanationJa":"システムや機器が故障した際、修理に要する平均的な時間のことである。これは、信頼性工学において非常に重要な指標であり、トラブル発生時の対応能力を示す。具体的には、サーバがダウンした場合に、問題を特定して修理するまでの時間を平均して算出するものである。MTTRが短いほど、システムの復旧が早く、ビジネスの安定性を保つことができる。企業ではこの指標を分析することで、設備の保守や運用体制を見直し、より効率的な運用を目指すことが求められている。MTTRの管理は、コスト削減や顧客満足度向上にもつながる。","explanationZh":"系统发生故障后，从故障发生到恢复正常运行所需的平均时间。缩短MTTR能够提高系统可用率。"},{"id":"t0510","chapterId":"c12","chapterJa":"システムの評価指標","chapterZh":"系统评价指标","termJa":"稼働率","termZh":"可用率／运行率","english":"Availability Rate","reading":"かどうりつ","breadcrumb":"","explanationJa":"稼働率 ＝ MTBF ÷（MTBF ＋ MTTR）​\nシステムや機器が稼働している時間の割合を示す指標である。これは、システムの信頼性を評価するための重要な要素で、特にMTBF（平均故障間隔）やMTTR（平均修復時間）と密接に関連している。MTBFは、故障から故障までの平均時間を示す一方で、MTTRは故障後の修理にかかる平均時間を示す。これらの指標を用いることで、稼働率は次のように計算される。MTBFをMTBFとMTTRの合計で割ったものにより求めることができる。高い信頼性の高いシステムを示し、ビジネスにおいては生産性や効率性向上に寄与するため、重要な指標とされている。","explanationZh":"系统在规定期间内能够正常提供服务的时间比例。常与MTBF和MTTR有关，高可用系统通过降低故障频率和缩短恢复时间提高该指标。"},{"id":"t0511","chapterId":"c12","chapterJa":"システムの評価指標","chapterZh":"系统评价指标","termJa":"イニシャルコスト","termZh":"初始成本","english":"Initial Cost","reading":"","breadcrumb":"","explanationJa":"システムやプロジェクトを開始する際に必要となる最初の費用のことである。このコストには、ハードウェアやソフトウェアの購入費、設置費、初期設定、トレーニングなどが含まれる。例えば、新しいITシステムを導入する場合、サーバやネットワーク機器の購入だけでなく、それを適切に動作させるためのソフトウェア取得費や専門家への支払いも重要な要素である。イニシャルコストを正確に把握することで、導入後のランニングコストやリターンを比較検討し、経済性を評価する際の基礎となる。これは、予算策定や投資判断において非常に重要な役割を果たす。","explanationZh":"系统导入或建设初期一次性发生的费用，例如硬件采购、软件许可、开发、安装和迁移费用。进行投资评价时应与后续运行成本一起考虑。"},{"id":"t0512","chapterId":"c12","chapterJa":"システムの評価指標","chapterZh":"系统评价指标","termJa":"ランニングコスト","termZh":"运行成本","english":"Running Cost","reading":"","breadcrumb":"","explanationJa":"システムやプロジェクトを運用する際に必要となる継続的な費用のことである。このコストには、人件費や保守費用、電気代、設備のメンテナンス費用などが含まれ、これらはシステムを稼働させるために毎月または毎年支出されるものである。例えば、企業がサーバを運用する場合、サーバの購入費用に加え、運用中に必要な電力や冷却コスト、技術者の手当等がランニングコストとなる。これらのコストを把握することは、システムの経済性を評価する上で非常に重要であり、導入時の初期コストと合わせて全体の投資効率を判断するための指標として活用される。\n情報セキュリティマネジメント試験情報＆徹底解説\nHOME»用語集»データベース»データベース方式","explanationZh":"系统投入使用后持续发生的费用，如维护、云服务费、人员、电力、许可续费和支持费用。长期总拥有成本通常受运行成本显著影响。"},{"id":"t0513","chapterId":"c13","chapterJa":"データベース方式","chapterZh":"数据库方式","termJa":"関係データベース","termZh":"关系数据库","english":"Relational Database","reading":"かんけいでーたべーす","breadcrumb":"4 データベース4-1 データベース方式","explanationJa":"データを表形式で管理するデータベースの一種である。各表は行と列で構成され、行が個々のデータのエントリを、列がそのデータの属性を表す。このような構造により、データの関連性を簡単に表現でき、必要なデータを効率よく検索・取得できる。例えば、顧客情報や注文情報をそれぞれの表で管理し、両者をキーによって関連付けることで、複雑なデータ関係をシンプルに扱うことが可能である。SQL（Structured Query Language）を使用してデータの操作や管理を行うことが一般的で、多くの業務システムで広く利用されている。","explanationZh":"用由行和列构成的表表示数据，并通过键和关系连接多个表的数据库模型。通常使用SQL进行查询和操作，强调结构化数据和完整性约束。"},{"id":"t0514","chapterId":"c13","chapterJa":"データベース方式","chapterZh":"数据库方式","termJa":"データベース管理システム","termZh":"数据库管理系统（DBMS）","english":"Database Management System","reading":"でーたべーすかんりしすてむ","breadcrumb":"4 データベース4-1 データベース方式","explanationJa":"データの収集・保存・管理を行うソフトウェアである。このシステムは、データを効率的に扱うための機能を提供し、具体的にはデータの保全機能とデータ機密保護機能がある。保全機能は、データの消失や破損に備え、定期的なバックアップを行う仕組みであり、システムの障害時にデータを復元可能にする。これにより、重要な情報を守ることができる。一方、データ機密保護機能は、許可されたユーザーのみがデータにアクセスできるようにするもので、パスワードや暗号化技術を使って情報を保護する。これらの機能により、データベース管理システムは企業や組織にとって不可欠なツールとなっている。\nHOME»用語集»データベース»データベース設計","explanationZh":"用于定义、存储、查询、更新和管理数据库的软件。它提供事务、并发控制、权限、备份恢复和完整性等功能，应用程序通过DBMS访问数据。"},{"id":"t0515","chapterId":"c14","chapterJa":"データベース設計","chapterZh":"数据库设计","termJa":"データ重複の排除","termZh":"数据去重","english":"Data Deduplication","reading":"でーたじゅうふくのはいじょ","breadcrumb":"","explanationJa":"データベースやデータセット内で同じ情報が重複している部分を取り除くプロセスである。この技術は、データの整合性を保ちながら、ストレージの効率を高めるために用いられる。例えば、顧客情報を管理する際に、同じ顧客が複数回登録されている場合、それを一つに統合することで、無駄なストレージ使用を削減し、データ分析をより正確に行えるようにすることができる。また、データ重複の排除を実施することで、分析結果の精度が向上するため、ビジネス上の意思決定がより良いものとなるのである。","explanationZh":"识别并消除重复的数据块或文件，仅保留一份实际数据并通过引用共享的技术。可减少存储空间和备份传输量，但需确保去重索引和数据完整性。"},{"id":"t0516","chapterId":"c14","chapterJa":"データベース設計","chapterZh":"数据库设计","termJa":"メタデータ","termZh":"元数据","english":"Metadata","reading":"","breadcrumb":"","explanationJa":"データを補足する情報のことである。具体的には、データの内容、形式、構造、作成日時、作成者などの情報を指す。この情報は、データを理解しやすくし、効率的に管理するために重要である。例えば、写真のファイルには、撮影日時やカメラの設定、位置情報などのメタデータが含まれることが多い。これにより、どのような状況で撮影されたのかを容易に把握でき、後から検索や整理を行う際に役立つ。また、データベースやデータ分析の際には、メタデータがデータの意味を理解する手助けをし、情報の信頼性を高めることにつながるのである。","explanationZh":"描述其他数据的数据，例如文件创建时间、作者、数据类型、数据库字段定义等。元数据有助于数据管理、检索和治理，但有时也可能包含敏感信息。"},{"id":"t0517","chapterId":"c14","chapterJa":"データベース設計","chapterZh":"数据库设计","termJa":"データディクショナリ","termZh":"数据字典","english":"Data Dictionary","reading":"","breadcrumb":"","explanationJa":"データベースにおけるデータの構造や属性に関する情報を格納するシステムである。具体的には、テーブルの定義、カラムのデータ型、制約条件など、データを正しく理解し、管理するための詳細な情報が含まれている。この情報を持つことで、データの利用者はデータベース内の情報を効率よく検索したり、データの整合性を保ったりすることができる。例えば、顧客情報のデータディクショナリには、顧客IDや名前、住所などの項目の説明が含まれており、データを扱う際の指針となる。また、新しいデータを追加する際や、既存データを変更する際にも、この情報が重要な役割を果たすのである。\nHOME»用語集»データベース»データ操作","explanationZh":"集中记录数据库中表、字段、数据类型、含义、约束和关系等定义的资料或系统。它帮助开发、运维和数据管理人员统一理解数据结构。"},{"id":"t0518","chapterId":"c15","chapterJa":"データ操作","chapterZh":"数据操作","termJa":"SQL","termZh":"结构化查询语言（SQL）","english":"Structured Query Language","reading":"えすきゅーえる","breadcrumb":"","explanationJa":"データベースと対話するために使用されるプログラミング言語である。主にデータの取得、追加、更新、削除などの操作を行うために用いられ、リレーショナルデータベースの構築や管理に欠かせない存在である。SQLを使用することで、ユーザーはデータベース内の情報を効率的に操作でき、特定の条件に基づいたデータ検索が容易になる。また、SQLは多くのデータベースシステムで広く採用されており、標準的な構文を持つため、異なるシステム間でも概ね互換性がある。これにより、開発者は特定のプラットフォームに依存せず、データ管理を行うことができる。\nHOME»用語集»データベース»トランザクション処理","explanationZh":"用于定义、查询和操作关系数据库的标准化语言。可执行SELECT、INSERT、UPDATE、DELETE等操作，并用于定义表结构和权限。"},{"id":"t0519","chapterId":"c16","chapterJa":"トランザクション処理","chapterZh":"事务处理","termJa":"同時実行制御","termZh":"并发控制","english":"Concurrency Control","reading":"どうじじっこうせいぎょ","breadcrumb":"4 データベース4-4 トランザクション処理","explanationJa":"データベースやトランザクション処理において、同時に複数の処理が行われる際に、データの整合性を保つための技術である。これは、異なる処理が同じデータにアクセスした場合に、データの競合を防ぐために役立つ。例えば、二人のユーザーが同じ商品の在庫を同時に更新しようとしたとき、排他制御がなければ、一方の処理がもう一方の結果を上書きしてしまう可能性がある。これを防ぐために、一方のプロセスがデータを使用している間、他のプロセスはそのデータにアクセスできないように制御する。このようにして、データの不整合を防ぎ、信頼性の高いシステムを実現することができる。","explanationZh":"多个事务同时访问同一数据时，防止更新丢失、脏读等不一致现象的数据库控制机制。常通过锁、时间戳或多版本并发控制等技术保证事务隔离和一致性。"},{"id":"t0520","chapterId":"c16","chapterJa":"トランザクション処理","chapterZh":"事务处理","termJa":"障害回復","termZh":"故障恢复","english":"Disaster Recovery","reading":"しょうがいかいふく","breadcrumb":"4 データベース4-4 トランザクション処理","explanationJa":"システムやサービスが障害（トラブルや故障）によって停止した場合に、迅速に復旧させるためのプロセスである。これは特にトランザクション処理システムにおいて重要で、データの一貫性や可用性を確保するために欠かせない。例えば、金融機関のシステムでは、トランザクションの処理が行われる際に障害が発生すると、その信頼性が損なわれる可能性があるため、障害発生時にデータをバックアップから復元し、通常の業務を続けられるようにする。障害回復の手段には、スナップショット、レプリケーション、定期的なバックアップなどがあり、これらを組み合わせることで、迅速な対応が可能になる。","explanationZh":"系统因硬件、软件或数据故障停止或异常后，将系统和数据恢复到可正常运行状态的过程。可利用日志、备份、冗余系统和恢复程序实现。"},{"id":"t0521","chapterId":"c16","chapterJa":"トランザクション処理","chapterZh":"事务处理","termJa":"世代管理","termZh":"世代管理","english":"Generation Management","reading":"せだいかんり","breadcrumb":"4 データベース4-4 トランザクション処理","explanationJa":"トランザクション処理において、データや情報の異なるバージョンを管理する手法である。これは、システムの処理が行われる際に、データの整合性を保ちながら、過去の状態と現在の状態を明確に区別するために重要である。具体的には、データベースの更新時に新たな世代を生成し、既存のデータを保持しつつ、最新の情報にアクセスできるようにする。このアプローチにより、同時に複数のユーザーがデータを扱っても互いに干渉せず、整合性を維持することが可能である。例えば、オンライン取引システムでは、購入の際に商品の在庫情報を適切に管理し、誤った情報に基づく取引が行われないようにするために世代管理が活用されている。","explanationZh":"保留多个不同时间点的备份或文件版本，并按代数或日期管理的方式。即使最新副本已损坏，也可回退到更早的正常版本。"},{"id":"t0522","chapterId":"c16","chapterJa":"トランザクション処理","chapterZh":"事务处理","termJa":"フルバックアップ","termZh":"完全备份","english":"Full Backup","reading":"","breadcrumb":"4 データベース4-4 トランザクション処理","explanationJa":"データの完全なコピーを作成するプロセスである。このバックアップ方法では、指定したすべてのデータが保存され、一部ではなく全体を対象にするため、データの復元が非常に簡単かつ確実に行える。例えば、企業が重要なデータをフルバックアップする場合、サーバ内の全ファイルやデータベースを対象にすることで、万が一のデータ損失時に容易に元の状態に戻すことができる。また、フルバックアップは定期的に行うことが推奨されており、他のバックアップ方法（差分バックアップや増分バックアップ）と組み合わせることで、効率的にデータ管理を行うことが可能となる。このように、フルバックアップはデータ保護の基本的かつ重要な手段である。","explanationZh":"每次备份所选范围内全部数据的备份方式。恢复简单，但备份时间、存储空间和网络流量通常较大。"},{"id":"t0523","chapterId":"c16","chapterJa":"トランザクション処理","chapterZh":"事务处理","termJa":"差分バックアップ","termZh":"差异备份","english":"Differential Backup","reading":"さぶんばっくあっぷ","breadcrumb":"4 データベース4-4 トランザクション処理","explanationJa":"最初にフルバックアップを作成した後、その時点までのデータの変化分だけを保存するバックアップ方法である。この手法は、フルバックアップと最新のデータの差分が保持されるため、復元時にはフルバックアップと最新の差分バックアップを組み合わせることで、最新の状態を迅速に復元できるという利点がある。例えば、月曜日にフルバックアップを作成し、火曜日にデータが変更された場合、火曜日の差分バックアップには月曜日以降の変更点が全て含まれる。そして、水曜日に更に変更された場合、火曜日の差分バックアップには月曜日以降の変更が反映され、それを利用してデータを最新の状態に戻すことができる。これにより、バックアップの容量を節約しつつ、効率的なデータ保護が実現される。","explanationZh":"每次备份自上一次完全备份以来发生变化的所有数据。恢复时通常只需最近一次完全备份和最近一次差异备份，备份量随时间增加。"},{"id":"t0524","chapterId":"c16","chapterJa":"トランザクション処理","chapterZh":"事务处理","termJa":"増分バックアップ","termZh":"增量备份","english":"Incremental Backup","reading":"ぞうぶんばっくあっぷ","breadcrumb":"4 データベース4-4 トランザクション処理","explanationJa":"前回のバックアップ以降に変更されたデータのみを保存する手法である。この方法では、初回のフルバックアップを行った後、その後のバックアップで新たに変更されたファイルやデータブロックのみを記録するため、バックアップに必要な時間とストレージの節約が可能である。例えば、月初めにフルバックアップを行い、その後の数日間での変更を増分バックアップとして保存するとする。これにより、完全なデータ復旧が必要な場合でも、最初のフルバックアップとその後の増分バックアップを組み合わせて使用することで、効率的に復旧作業を行うことができる。この手法は、データの安全性を確保しつつ、バックアップ作業を効率化するための重要な技術である。\nHOME»用語集»データベース»データベース応用","explanationZh":"每次只备份自上一次任意类型备份以来发生变化的数据。备份速度快、占用空间小，但恢复时通常需要完整备份和之后的多个增量备份。"},{"id":"t0525","chapterId":"c17","chapterJa":"データベース応用","chapterZh":"数据库应用","termJa":"データウェアハウス","termZh":"数据仓库","english":"Data Warehouse","reading":"","breadcrumb":"4 データベース4-5 データベース応用","explanationJa":"企業や組織が大量のデータを蓄積し、分析するための特別なデータベースのことである。このシステムは、異なるデータソースから情報をまとめ、一元管理することができるため、経営判断やマーケティング分析に役立つ。例えば、販売データや顧客情報、在庫情報などを集約し、過去のトレンドや将来の予測を行うことが可能である。また、データウェアハウスではデータが整理・整形されているため、迅速なクエリ処理が実現できる。このように、データウェアハウスはビジネスの意思決定に不可欠な基盤となっている。","explanationZh":"面向分析和决策，将多个业务系统中的数据经过整合、清洗和历史化后集中保存的数据平台。通常用于报表、商业智能和趋势分析，而非日常事务处理。"},{"id":"t0526","chapterId":"c17","chapterJa":"データベース応用","chapterZh":"数据库应用","termJa":"ビッグデータ","termZh":"大数据","english":"Big Data","reading":"","breadcrumb":"4 データベース4-5 データベース応用","explanationJa":"従来のデータ処理手法では扱いきれないほどの大規模なデータセットを指す。具体的には、データの量、速度、多様性が非常に大きく、テキスト、画像、動画などさまざまな形式で存在する。このようなデータは、企業や組織が意思決定を行う際に重要な役割を果たす。例えば、小売業界では、購入履歴や顧客の行動データを解析することで、ターゲット広告や在庫管理の最適化が可能になる。また、ビッグデータは機械学習や人工知能と結びつくことで、より高度な分析や予測を実現し、新しいサービスや製品の開発に寄与することが期待されている。データを有効に活用するためには、適切な技術やインフラが求められる。","explanationZh":"规模大、类型多、产生速度快，传统方法难以有效处理的数据集合及其处理概念。通过分布式存储、分析和机器学习等技术可从中提取价值。"},{"id":"t0527","chapterId":"c17","chapterJa":"データベース応用","chapterZh":"数据库应用","termJa":"分散ファイルシステム","termZh":"分布式文件系统","english":"Distributed File System","reading":"ぶんさんふぁいるしすてむ","breadcrumb":"4 データベース4-5 データベース応用","explanationJa":"複数のコンピュータにまたがってデータを保存し、管理するためのシステムである。この形式では、ファイルやデータが異なるサーバに分散されているため、単一のサーバに依存せず、障害時の耐障害性やデータの可用性が向上する。具体的には、Google File SystemやHadoop Distributed File System（HDFS）などが有名で、これらは大規模なデータ処理に特化している。ネットワークを通じてファイルへのアクセスを可能にし、ユーザーはまるでローカルのファイルのようにデータを扱うことができる。これにより、大量のデータを効率的に管理し、処理することが容易になるため、現代のビッグデータ分析やクラウドコンピューティングにおいて重要な役割を果たしている。\nHOME»用語集»ネットワーク»ネットワーク方式","explanationZh":"把文件数据分散存储在多台节点上，同时向用户提供统一文件系统视图的技术。可提供扩展性和容错能力，但需处理副本、一致性和节点故障等问题。"},{"id":"t0528","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"ネットワーク社会","termZh":"网络化社会","english":"Networked Society","reading":"ねっとわーくしゃかい","breadcrumb":"","explanationJa":"情報通信技術の進展により、人々や組織がインターネットを通じて密接につながった社会のことを指す。通信ネットワークの発展により、人々はリアルタイムで情報を交換したり、互いに関わり合ったりすることが容易になり、これにより新たなコミュニティやビジネスモデルが生まれている。たとえば、SNS（ソーシャルネットワーキングサービス）を利用することで、地理的な境界を超えた交流が可能となり、意見や価値観を簡単に共有できるようになっている。このような環境では、企業も消費者と直接やり取りを行い、サービスを改善したり、ニーズに応じた新たな商品を開発したりすることができる。したがって、個人と社会全体における情報の流通や関係の形成に大きな影響を与えている。","explanationZh":"个人、企业和公共机构通过通信网络广泛连接并交换信息、提供服务的社会形态。网络带来便利和效率，也使网络安全、隐私和数字鸿沟等问题更加重要。"},{"id":"t0529","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"情報社会","termZh":"信息社会","english":"Information Society","reading":"じょうほうしゃかい","breadcrumb":"","explanationJa":"情報やコミュニケーション技術が発展し、それが人々の生活や働き方に大きな影響を与えている社会のことである。この種の社会では、情報の取得、処理、伝達が迅速かつ効率的に行われ、さまざまな分野での活動が活発化する。例えば、インターネットを介して大規模なデータが瞬時に共有され、遠隔地にいる人々がリアルタイムでコミュニケーションを行うことが可能になる。また、企業や組織は、情報技術を活用して業務の効率化や新たなサービスの提供を推進し、競争力を高めることが求められる。このように、情報社会では、通信ネットワークの役割がますます重要となり、情報が経済や文化の発展に寄与する重要な資源とみなされる。","explanationZh":"信息的生产、处理、流通和利用在经济与社会活动中占据核心地位的社会。信息技术成为重要基础设施，因此信息安全和信息素养具有基础性意义。"},{"id":"t0530","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"ICT","termZh":"信息与通信技术（ICT）","english":"Information and Communication Technology","reading":"あいしーてぃー","breadcrumb":"","explanationJa":"情報通信技術を指し、情報の収集、処理、伝達を行うための技術や手段が含まれる。具体的には、コンピュータやインターネット、スマートフォンなどのデバイスを通じて、データや情報をやり取りする方法である。例えば、企業ではICTを活用して、遠隔地にいるスタッフとリアルタイムで連絡を取り合ったり、クラウド上でデータを共有したりすることが一般的である。また、教育分野では、オンライン授業やWeb教材を利用することで、学習の幅が広がり、場所を選ばずに知識を深めることができる。ICTは現代社会において、情報の流通やコミュニケーションの効率を高める重要な役割を果たしている。","explanationZh":"涵盖计算机、网络、通信和数字信息处理等技术的总称。ICT支撑互联网、云、移动通信和数字化业务，是现代信息系统的基础。"},{"id":"t0531","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"LAN","termZh":"局域网（LAN）","english":"Local Area Network","reading":"らん","breadcrumb":"","explanationJa":"限られた地域内でコンピュータやデバイスを相互接続するためのネットワークである。一般的には、家庭やオフィス内で使用される。比較的小さな範囲、例えば建物の中でデータを迅速に送受信することができ、通信速度が高速で安定しているのが特長である。例えば、自宅のWi-Fiネットワークやオフィスのイーサネット接続がLANの一例である。このようにファイル共有やプリンターの共有、ネットワークゲームなど、コミュニケーションや協力を促進するために広く利用されている。また、LANは他の広域ネットワーク（WAN）と接続して、インターネットにアクセスすることも可能である。","explanationZh":"在办公室、家庭、校园等较小地理范围内连接计算机和网络设备的网络。常使用以太网或Wi-Fi实现高速通信。"},{"id":"t0532","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"有線LAN","termZh":"有线局域网","english":"Wired Local Area Network","reading":"ゆうせんらん","breadcrumb":"","explanationJa":"コンピュータや機器をケーブルで接続して構築されるネットワークの一種である。通常、イーサネットケーブルを用いて接続され、高速なデータ通信が可能である。例えば、オフィスや家庭内で複数のパソコンやプリンターを結びつける際に使用される。また、無線LANと比較して、安定した接続やセキュリティの面で優れている点が特長である。データの転送速度が速く、干渉を受けにくいため、特に企業環境や専用のネットワークが必要な場合に好まれる選択肢となる。さらに、有線LANは遅延が少ないため、オンラインゲームや大容量データのやり取りにも適している。","explanationZh":"通过双绞线、光纤等有线介质连接设备的LAN。通常具有稳定、低延迟和较强抗干扰能力，但布线成本和移动性受到限制。"},{"id":"t0533","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"無線LAN","termZh":"无线局域网","english":"Wireless Local Area Network","reading":"むせんらん","breadcrumb":"","explanationJa":"無線技術を利用してデバイス同士が接続されるローカルエリアネットワークのことである。これにより、ケーブルを使用せずにインターネットや内部ネットワークへの接続が可能となる。無線LANの代表的な技術としては、Wi-Fiがある。これにより、家庭やオフィス、公共の場などで様々な機器が無線でインターネットにアクセスできるようになる。例えば、スマートフォンやタブレット、ノートパソコンなどが無線LANを通じてインターネットに接続され、場所を選ばずに快適にデータを送受信することができる。また、無線LANは設置が簡単で、障害物が少なければ広範囲をカバーできるため、多くのユーザーに便利な選択肢として支持されている。","explanationZh":"通过无线电波连接终端和接入点的局域网，通常基于IEEE 802.11系列标准。部署方便，但应通过WPA2/WPA3等机制保护通信和接入安全。"},{"id":"t0534","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"無線LANアクセスポイント","termZh":"无线局域网接入点（AP）","english":"Wireless LAN Access Point","reading":"むせんらんあくせすぽいんと","breadcrumb":"","explanationJa":"無線ネットワークに接続するための機器であり、Wi-Fi信号を送信し、デバイスがインターネットにアクセスできるようにする役割を持つ。これにより、スマートフォンやタブレット、ノートパソコンなどが、ケーブルを使わずにネットワークに接続することが可能になる。例えば、家庭やオフィス、公共の場所で設定され、複数のデバイスが同時にインターネットを利用できる環境を提供する。ネットワークの広がりや接続速度、セキュリティ機能などによって様々な種類があり、ユーザーのニーズに応じて選ばれる。これにより、便利で柔軟な通信環境が整えられる。","explanationZh":"为无线终端提供接入有线网络或其他网络的设备。AP负责无线连接、认证和数据转发，其配置安全直接影响无线网络安全。"},{"id":"t0535","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"SSID","termZh":"服务集标识符（SSID）","english":"Service Set Identifier","reading":"えすえすあいでぃ","breadcrumb":"","explanationJa":"無線LANにおいて、ネットワークを識別するための名前である。この名称によって、ユーザーは接続したいWi-Fiネットワークを容易に見つけることができる。例えば、自宅のWi-Fiネットワークに「MyHomeNetwork」というSSIDを設定すると、近隣の無線LANネットワークの中で、特定のネットワークがその名前で表示される。SSIDは最大32文字で構成され、多くの場合、管理者によって任意に設定される。ネットワークのセキュリティを向上させるために、SSIDが隠されていることもあるが、その場合でも、適切な設定とデバイスがあれば接続は可能である。ユーザーがSSIDを知ることは、無線LANを利用する上で非常に重要である。","explanationZh":"用于标识IEEE 802.11无线网络名称的字符串。SSID本身不是安全密码，隐藏SSID也不能替代WPA2/WPA3等真正的认证和加密措施。"},{"id":"t0536","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"WAN","termZh":"广域网（WAN）","english":"Wide Area Network","reading":"わん","breadcrumb":"","explanationJa":"広い地域をカバーするネットワークのことである。通常、都市や国をまたいで接続されるため、地理的に離れた場所にあるコンピュータやサーバを相互に通信させることができる。企業が本社と支社を結ぶために利用されることが多く、データの送受信を円滑に行う役割を果たしている。 WANの接続手段には、専用線やインターネットを利用したVPN（Virtual Private Network）などがあり、セキュリティや帯域幅の面でも工夫が求められる。このように、WANはビジネスや情報の流通にとって欠かせないインフラである。","explanationZh":"跨城市、地区或国家连接多个LAN和站点的网络。可使用专线、广域以太网、IP-VPN或互联网VPN等技术构建。"},{"id":"t0537","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"インターネット接続サービス","termZh":"互联网接入服务","english":"Internet Connection Service","reading":"いんたーねっとせつぞくさーびす","breadcrumb":"","explanationJa":"ユーザーが自宅やオフィスからインターネットにアクセスできるようにするためのサービスである。このサービスは、プロバイダと呼ばれる企業によって提供され、様々な接続方法がある。代表的なものには、ADSL、光ファイバー、モバイルデータ通信などがあり、それぞれ速度や安定性に違いがある。例えば、光ファイバーを使用する場合は、高速かつ安定したインターネット接続が可能で、動画のストリーミングやオンラインゲームに適している。一方、ADSLは一般的には速度がやや遅めだが、広く普及しているため選択肢として利用されることも多い。このように、ユーザーの日常生活やビジネス活動に欠かせない重要な基盤を提供している。","explanationZh":"由运营商或服务提供商提供，使用户网络能够连接互联网的服务。可以通过光纤、移动通信等多种接入方式实现。"},{"id":"t0538","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"インターネットサービスプロバイダ","termZh":"互联网服务提供商（ISP）","english":"Internet Service Provider","reading":"","breadcrumb":"","explanationJa":"ユーザーがインターネットに接続するためのサービスを提供する業者である。ISPは、家庭や企業にインターネット接続を供給するほか、関連するサービスとしてメールアカウントやWebホスティングを提供することもある。典型的な例としては、NTTやKDDIといった通信会社が挙げられ、多くの利用者がこれらのISPを通じてインターネットにアクセスしている。インターネットの利用方法は多様であり、ISPはその基盤としての役割を果たすため、通信速度や接続の安定性が重要になる。さらに、ISPはセキュリティ対策やサポートサービスも提供し、ユーザーが安全にインターネットを利用できる環境を整える。","explanationZh":"向个人或组织提供互联网连接、IP地址、DNS、邮件等网络服务的企业或机构。ISP也是网络安全事件协作和流量管理中的重要参与者。"},{"id":"t0539","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"TCP/IP","termZh":"TCP/IP协议族","english":"TCP/IP","reading":"てぃーしーぴーあいぴー","breadcrumb":"","explanationJa":"コンピュータ間でデータを送受信するためのプロトコルの集合である。このプロトコルは、特にインターネットで広く使用され、データ通信の基本的な仕組みを提供する。TCP（Transmission Control Protocol）は、データの信頼性を保証し、正確に送受信する役割を持つ。一方、IP（Internet Protocol）は、データが送信先に届くようにアドレスを管理し、経路を決定する。この二つのプロトコルの組み合わせにより、異なるネットワーク機器が円滑に情報をやり取りできる。例えば、Webブラウザでページを表示する際も、TCP/IPを利用してデータがルーティングされ、ユーザーは必要な情報にアクセスできる仕組みとなっている。インターネットの基盤となる技術であり、さまざまなアプリケーションやサービスの動作に欠かせない要素である。","explanationZh":"互联网广泛使用的一组通信协议的总称，其中IP负责寻址和路由，TCP等传输层协议负责端到端数据传送。应用层协议如HTTP、SMTP运行在其之上。"},{"id":"t0540","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"サーバ","termZh":"服务器","english":"Server","reading":"","breadcrumb":"","explanationJa":"他のコンピュータ（クライアント）に対して情報やサービスを提供する役割を持つコンピュータのことである。データの保存や処理を行い、ネットワークを介してクライアントからのリクエストに応じて必要な情報を提供する。例えば、Webサイトが表示されるとき、そのデータはサーバから送信される。また、メールサーバは電子メールの送受信を管理し、ファイルサーバは文書やデータを保存して、ネットワーク上のユーザーがアクセスできるようにする。サーバはその役割を特定の用途に特化して設計されているため、効率的に多くのユーザーにサービスを提供することができる。サーバの正しい運用は、インターネットの信頼性や速度に大きな影響を与える。","explanationZh":"向网络中的其他设备或程序提供数据、处理、认证、文件等服务的计算机或软件。服务器通常需要持续运行并实施严格的访问控制、补丁和监控。"},{"id":"t0541","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"クライアント","termZh":"客户端","english":"Client","reading":"","breadcrumb":"","explanationJa":"サーバに接続して情報やサービスを要求するコンピュータやソフトウェアのことを指す。インターネット上では、Webブラウザやメールアプリケーションなどがクライアントの一例であり、これらはサーバにデータをリクエストする。例えば、Webブラウザを使用して特定のWebサイトにアクセスすると、そのブラウザがクライアントとなり、必要な情報をサーバから受信する。このように、クライアントはサーバと連携しながら機能し、ユーザーは直感的にインターネットのサービスを享受することができる。クライアント・サーバモデルは、無限の情報を提供する現代のインターネットにおいて重要な役割を果たしている。","explanationZh":"向服务器发出请求并使用其服务的终端或软件。例如浏览器是Web服务器的客户端，邮件软件是邮件服务器的客户端。"},{"id":"t0542","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"ルーティング","termZh":"路由","english":"Routing","reading":"","breadcrumb":"","explanationJa":"ネットワーク上でデータが目的地に効率的に到達するための経路を決定する仕組みである。これは、異なるネットワーク間の接続やデータの流れを管理するために使用され、特にインターネットのように大規模なネットワークで重要な役割を果たす。具体的には、データパケットが送信元から目的地に向かう際に、どの経路を通るべきかを決定する作業がルーティングで行われる。例えば、あるWebページにアクセスする際、そのリクエストは最適な経路を通ってサーバに到達し、必要な情報を受け取ることができる。このように、ルーティングはネットワーク通信の効率や速度を大きく左右する要素であり、さまざまなルーティングプロトコルを利用して最適な経路を選定している。","explanationZh":"根据目的IP地址和路由表，为数据包选择从源网络到目的网络转发路径的过程。路由器和三层交换机等设备执行该功能。"},{"id":"t0543","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"グローバルIPアドレス","termZh":"全球IP地址／公网IP地址","english":"Global IP Address","reading":"ぐろーばるあいぴーあどれす","breadcrumb":"","explanationJa":"インターネット上で直接的に通信するために必要な一意の識別番号である。これは、インターネットに接続される全てのデバイスが独自に持つものであり、他のデバイスとの通信を可能にする役割を果たす。例えば、あなたのパソコンやスマートフォンがインターネットに接続されると、それぞれにグローバルIPアドレスが割り当てられる。このアドレスは、国や地域によって異なることがあり、自分のデバイスがどの場所から接続されているかを把握するのに役立つ。また、アクセス制御やセキュリティ管理にも重要な役割を果たしており、特定のアドレスからのアクセスを制限することができる。","explanationZh":"在互联网范围内唯一、可路由的IP地址。公网服务需要使用可被互联网识别的地址，地址分配受到全球和地区地址管理体系管理。"},{"id":"t0544","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"プライベートIPアドレス","termZh":"私有IP地址","english":"Private IP Address","reading":"ぷらいべーとあいぴーあどれす","breadcrumb":"","explanationJa":"内部ネットワーク内で使用されるIPアドレスのことを指す。これらのアドレスは、一般的にはインターネット上で直接アクセスすることができないため、主に家庭や企業のネットワーク内でのデバイス間の通信に利用される。例えば、192.168.1.1や10.0.0.1といった形式が代表的なプライベートIPアドレスである。これにより、複数のデバイスが同一のプライベートIP範囲内で同時に接続できるため、アドレスの効率的な管理が可能となる。また、プライベートIPアドレスを使用することで、外部からの不正アクセスを防ぎつつ、内部の通信は安全かつ円滑に行うことができる。","explanationZh":"保留供内部网络使用、不会直接在公网路由的IP地址范围。组织通常通过NAT等方式让使用私有地址的设备访问互联网。"},{"id":"t0545","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"ドメイン","termZh":"域／域名空间","english":"Domain","reading":"","breadcrumb":"","explanationJa":"インターネット上で特定の場所を示すための名前である。この名前は、Webサイトやメールサーバのアドレスとして使用され、使いやすく記憶しやすい形式で提供される。たとえば、\"example.com\"というドメイン名は、そのサイトを指し示すものである。識別の目的だけでなく、企業や団体のブランディングにおいても重要な役割を果たす。ドメイン名は階層的な構造を持ち、トップレベルドメイン（.comや.jpなど）が最上位に位置し、その下に各団体や個人が所有するサブドメインが続く。この仕組みにより、インターネット上で一意に識別されることが可能となっている。","explanationZh":"在网络和互联网中用于表示管理范围或命名层次的概念。DNS域以层级结构管理名称，例如example.com可作为一个域。"},{"id":"t0546","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"DNS","termZh":"域名系统（DNS）","english":"Domain Name System","reading":"でぃーえぬえす","breadcrumb":"","explanationJa":"人が覚えやすいドメイン名（例：example.com）を機器が理解できるIPアドレス（例：192.0.2.1）に変換する仕組みである。これにより、ユーザーは複雑な数字の列ではなく、わかりやすい名前を使ってWebサイトにアクセスできる。例えば、ユーザーがブラウザに「example.com」と入力すると、DNSがそのドメイン名を対応するIPアドレスに変換し、Webサイトの特定のサーバに接続する。DNSはインターネットの運用に不可欠であり、サイトの速度や信頼性にも影響を与えるため、適切に管理される必要がある。","explanationZh":"把人类易记的域名转换为IP地址等资源记录的分布式命名系统。DNS是互联网基础服务之一，因此需要防范缓存投毒、劫持等攻击。"},{"id":"t0547","chapterId":"c18","chapterJa":"ネットワーク方式","chapterZh":"网络方式","termJa":"RADIUS","termZh":"RADIUS","english":"Remote Authentication Dial-In User Service","reading":"らでぃうす","breadcrumb":"","explanationJa":"ネットワークにおけるユーザー認証を管理するプロトコルである。主に、ユーザーがネットワークにアクセスする際の認証、承認、アカウンティング（AAA）機能を提供する。例えば、企業がVPNを利用する際、RADIUSを使用してユーザーのログイン情報を確認し、その効力を管理することで、セキュリティを強化する。この技術は、無線LANやインターネットサービスプロバイダ（ISP）など、さまざまな環境で広く利用されており、企業や組織が効率的にリソースを管理し、ネットワーク利用を監視できるようにしている。\nHOME»用語集»ネットワーク»データ通信と制御","explanationZh":"用于集中处理网络接入认证、授权和计费（AAA）的协议。常用于企业Wi-Fi、VPN和远程接入，由网络设备把认证请求转交RADIUS服务器验证。"},{"id":"t0548","chapterId":"c19","chapterJa":"データ通信と制御","chapterZh":"数据通信与控制","termJa":"パケット交換","termZh":"分组交换","english":"Packet Switching","reading":"ぱけっとこうかん","breadcrumb":"","explanationJa":"データ通信において情報を小さなデータの塊、すなわちパケットに分割して送信する方式である。この方法は、各パケットが独立した経路で送られることを可能にし、受信側で再度順序を整えることができる。これにより、通信回線の利用効率が向上し、複数のデータ通信を同時に行いやすくなる。例えば、インターネットはこのパケット交換方式を利用しており、動画や音声などの情報を途切れずに送信することができる。さらに、通信中に障害が発生しても、他の経路を使って改めてデータを送信することができるため、信頼性の高い通信手段となっている。","explanationZh":"把数据拆分成多个数据包，各数据包通过共享网络独立传输并在目的端重组的通信方式。它能高效共享线路，是IP网络的基本方式。"},{"id":"t0549","chapterId":"c19","chapterJa":"データ通信と制御","chapterZh":"数据通信与控制","termJa":"公衆回線","termZh":"公用线路","english":"Public Circuit","reading":"こうしゅうかいせん","breadcrumb":"","explanationJa":"一般の利用者が共有する通信回線のことである。この回線は、電話やインターネットなど、さまざまな通信サービスを提供するために使用される。多くの利用者が一つの回線を共有するため、コストが抑えられる利点があるが、通信品質には影響が出る場合もある。例えば、ピーク時には多数のユーザーが同時に回線を使用するため、速度が遅くなったり、接続が不安定になることもある。一方で、主に使用されている技術には、ADSLや光ファイバーなどがあり、これらは速度向上や安定性の確保を図るために進化を続けている。日常生活やビジネスにおける通信手段として重要な役割を果たしている。","explanationZh":"由电信运营商面向多个用户提供的公共通信线路或网络服务。相比专线成本通常较低，但带宽、路径和安全需要根据服务方式评估。"},{"id":"t0550","chapterId":"c19","chapterJa":"データ通信と制御","chapterZh":"数据通信与控制","termJa":"専用線","termZh":"专线","english":"Dedicated Line","reading":"せんようせん","breadcrumb":"","explanationJa":"特定の利用者や組織専用に設計された通信回線のことである。この回線は、他のユーザーと共有することなく、常時接続可能な専用の経路を提供する。通常、企業間の大規模データ送信やネットワーク接続に利用され、高い速度と安定性を求められるシナリオに適している。例えば、金融機関や大企業が重要なデータをリアルタイムで安全に送信するために専用線を利用することがある。これにより、通信の品質が保証され、セキュリティも強化されることから、特に重要な情報を扱う場合に重宝される。専用線は一般的に高額な料金が発生するが、その対価として高いパフォーマンスを得られる。","explanationZh":"由通信运营商为特定客户提供、连接固定地点的专用通信线路。通常具有稳定带宽和较高可预测性，但成本高于共享公网服务。"},{"id":"t0551","chapterId":"c19","chapterJa":"データ通信と制御","chapterZh":"数据通信与控制","termJa":"LAN内接続","termZh":"局域网内部连接","english":"Local Area Network Connection","reading":"らんないせつぞく","breadcrumb":"","explanationJa":"限られた区域内で複数のコンピュータやデバイスを接続するネットワークの構成を指す。これにより、同じ場所にある機器同士がデータを高速でやり取りできるようになる。一般的には家庭やオフィスの環境で利用され、プリンターやファイルサーバなどを共有する際に重要である。たとえば、オフィス内で社員が同じファイルを共有したり、ネットワークプリンターにアクセスしたりすることがLAN内接続のおかげで可能になる。LANは、Wi-Fiなどの無線接続や、イーthernetケーブルを使用した有線接続として構築され、その構成によって快適な通信環境を提供することができる。","explanationZh":"在同一LAN内连接终端、服务器、交换机和接入点等设备的网络构成。需要根据带宽、VLAN、冗余和访问控制等设计内部通信。"},{"id":"t0552","chapterId":"c19","chapterJa":"データ通信と制御","chapterZh":"数据通信与控制","termJa":"LAN間接続","termZh":"局域网互联","english":"LAN Interconnection","reading":"らんかんせつぞく","breadcrumb":"","explanationJa":"複数のローカルエリアネットワーク（LAN）を相互に接続する方法である。これは、各LAN内のデバイス同士が通信できるようにするために必要な技術で、例えば、異なる部門やオフィスがそれぞれのLANを持ちつつも、全体として一つのネットワークとして機能することを可能にする。LAN間接続により、データの共有やリソースの利用が促進され、業務の効率化が図れる。具体的には、ルーターやブリッジといったデバイスを使用して、各LANを統合し、必要に応じてデータの流れを制御することで、セキュリティやトラフィックの最適化を実現する。これにより、組織全体がスムーズに情報をやり取りできる環境が整備される。","explanationZh":"通过路由器、交换设备或运营商网络连接两个或多个LAN，使不同网段之间能够通信。应合理设计路由、安全边界和带宽。"},{"id":"t0553","chapterId":"c19","chapterJa":"データ通信と制御","chapterZh":"数据通信与控制","termJa":"LAN-WAN接続","termZh":"LAN-WAN连接","english":"LAN-WAN Connection","reading":"らん-わんせつぞく","breadcrumb":"","explanationJa":"ローカルエリアネットワーク（LAN）と広域エリアネットワーク（WAN）を接続する技術や方法のことである。LANは、限られた範囲内で複数のデバイスが直接通信するためのネットワークであり、WANは、広範囲にわたる地域での通信を可能にするネットワークである。例えば、企業の本社がLANを持ち、各支社とWANを通じて接続される場合、これがLAN-WAN接続である。この接続により、異なる場所にいるデバイス同士がデータをやり取りし、業務を効率良く行うことが可能となる。インターネットを介しての情報交換やリモートワークの実現にも寄与する。","explanationZh":"把组织内部局域网连接到广域网或运营商网络的结构。通常通过路由器、防火墙、专线或VPN实现，并是重要的网络安全边界。"},{"id":"t0554","chapterId":"c19","chapterJa":"データ通信と制御","chapterZh":"数据通信与控制","termJa":"スイッチングハブ","termZh":"交换式集线器／以太网交换机","english":"Switching Hub","reading":"","breadcrumb":"","explanationJa":"複数のネットワーク機器を接続し、データ通信を管理する装置である。通常のハブと異なり、スイッチングハブはデータを送信する際、宛先の機器を特定し、その機器にのみデータを送ることが可能である。これにより、ネットワークの帯域幅を効率的に利用でき、通信速度が向上する。例えば、オフィス内でコンピュータ同士がデータをやり取りする際、スイッチングハブを使うことで、不要な通信を減らし、効率的に情報を共有できる。トラフィックの管理やネットワークの安定性向上にも寄与し、特に多くの機器が接続される環境での利用が一般的である。","explanationZh":"根据MAC地址表在局域网中把以太网帧转发到相应端口的设备。相比传统集线器可减少冲突并提高带宽利用率。"},{"id":"t0555","chapterId":"c19","chapterJa":"データ通信と制御","chapterZh":"数据通信与控制","termJa":"ルータ","termZh":"路由器","english":"Router","reading":"","breadcrumb":"","explanationJa":"異なるネットワークを接続し、データパケットの転送を行う機器である。主に家庭や企業のネットワークにおいて、インターネット接続を提供する役割を果たす。受け取ったデータを最適な経路で送り先のネットワークに届けるための判断を行う。例えば、家庭用のインターネットサービスプロバイダーからの信号を受信し、無線LANを通じて複数のデバイスにインターネット接続を提供することができる。また、企業では、セキュリティ機能を備えたルータを使用して、内部ネットワークを外部から保護し、データの流れを管理することが一般的である。ネットワークのスムーズな運営に不可欠な重要な要素となっている。","explanationZh":"连接不同IP网络并根据路由表转发数据包的网络设备。还可提供NAT、ACL、VPN等附加功能。"},{"id":"t0556","chapterId":"c19","chapterJa":"データ通信と制御","chapterZh":"数据通信与控制","termJa":"レイヤー2スイッチ","termZh":"二层交换机","english":"Layer 2 Switch","reading":"れいやーつーすいっち","breadcrumb":"","explanationJa":"データリンク層で動作するネットワーク機器の一つであり、主にEthernetフレームを基にしたデータ転送を行うものである。受け取ったデータパケットのMACアドレスを参照し、適切なポートに転送することで通信を可能にする。この動作により、同一ネットワーク内の複数のデバイス間で効率的なデータ交換が実現される。ブロードキャストドメインを分割し、ネットワークのトラフィックを軽減する点でも重要である。また、レイヤー2スイッチは簡単に設定可能で、一般的なオフィスや家庭内のネットワークに広く利用されている。これにより、ネットワークの冗長性や信頼性を高めることができる。","explanationZh":"主要在OSI数据链路层工作，根据MAC地址转发以太网帧的交换设备。常用于同一VLAN内部设备连接和VLAN划分。"},{"id":"t0557","chapterId":"c19","chapterJa":"データ通信と制御","chapterZh":"数据通信与控制","termJa":"レイヤー3スイッチ","termZh":"三层交换机","english":"Layer 3 Switch","reading":"れいやーすりーすいっち","breadcrumb":"","explanationJa":"ネットワークのデータ通信において、異なるネットワーク間のデータの転送を行う装置である。これは、伝送単位としてパケットを使用し、IPアドレスに基づいてデータをルーティングする機能を持つ。通常のレイヤー2スイッチがデータリンク層で動作するのに対し、レイヤー3スイッチはネットワーク層に対応し、パケットの転送だけでなく、ネットワークの接続を管理することができる。具体的には、複数のサブネットを接続し、データが異なるネットワークに届くように処理を行う。これにより、ネットワーク管理が効率的になり、大規模なネットワーク環境でも柔軟に対応できる利点がある。特に企業のネットワーク構成で重要な役割を果たす。","explanationZh":"除二层交换功能外，还能基于IP地址执行高速路由的交换设备。常用于企业内部不同VLAN之间的路由。"},{"id":"t0558","chapterId":"c19","chapterJa":"データ通信と制御","chapterZh":"数据通信与控制","termJa":"ブリッジ","termZh":"网桥","english":"Bridge","reading":"","breadcrumb":"","explanationJa":"異なるネットワークセグメントを接続する装置である。これは、データリンク層で動作し、受信したデータを分析して、目的のネットワークにのみそのデータを転送する役割を持つ。これにより、ネットワークの効率が向上し、トラフィックの軽減が図れる。具体的な例としては、企業のオフィス内ネットワークにおいて、複数のフロアや部門のネットワークを接続し、それぞれの通信を最適化することが挙げられる。また、ブリッジはネットワークの衝突域を分割することもでき、通信の速度を向上させる効果もある。そのため、特に大規模なネットワークでは、ブリッジの利用が推奨される。","explanationZh":"在数据链路层连接两个网络段，并根据MAC地址过滤和转发帧的设备或功能。现代以太网交换机可视为多端口网桥。"},{"id":"t0559","chapterId":"c19","chapterJa":"データ通信と制御","chapterZh":"数据通信与控制","termJa":"ゲートウェイ","termZh":"网关","english":"Gateway","reading":"","breadcrumb":"","explanationJa":"異なるネットワーク間でデータを転送する役割を果たす装置やソフトウェアである。主に、異なるプロトコルを使用するネットワーク同士を接続するために利用される。例えば、企業内のLANとインターネットを繋ぐ場合、ゲートウェイがその仲介を行う。また、ゲートウェイはデータの変換やフィルタリング機能も持っており、通信の効率やセキュリティを向上させることができる。ルーターやファイアウォールといった機器も、ゲートウェイとしての機能を果たすことがあり、ネットワーク管理において重要な役割を担っている。","explanationZh":"连接不同网络、协议或系统并在必要时进行协议转换的节点。广义上可指网络出口设备；“默认网关”通常指终端向外部网络发送数据时使用的路由器。"},{"id":"t0560","chapterId":"c19","chapterJa":"データ通信と制御","chapterZh":"数据通信与控制","termJa":"プロキシサーバ","termZh":"代理服务器","english":"Proxy Server","reading":"","breadcrumb":"","explanationJa":"クライアントとインターネットの間に位置する中継サーバである。このサーバは、クライアントの要求を受け取り、実際の目的地であるインターネットのサーバにその要求を代わりに送信する。さまざまな目的で利用されるが、主な機能にはキャッシュ機能、フィルタリング、セキュリティ強化が含まれる。例えば、企業内でプロキシサーバを導入することで、特定のWebサイトへのアクセスを制限したり、通信内容を監視することが可能になる。また、多くのユーザーが同時に同じデータを必要とした場合、プロキシサーバはそのデータを一時的に保存し、次回の要求時に迅速に提供することで、通信速度を向上させることもできる。このように、プロキシサーバはネットワーク管理やパフォーマンス向上に貢献する重要な存在である。","explanationZh":"代表客户端访问外部服务器的中间服务器。可隐藏内部客户端、缓存内容、实施访问控制和日志记录，并用于URL过滤等安全管理。"},{"id":"t0561","chapterId":"c19","chapterJa":"データ通信と制御","chapterZh":"数据通信与控制","termJa":"リバースプロキシサーバ","termZh":"反向代理服务器","english":"Reverse Proxy Server","reading":"","breadcrumb":"","explanationJa":"クライアントとサーバの間に位置し、クライアントからのリクエストを特定のサーバに転送する役割を持つサーバである。一般的には、複数のバックエンドサーバが存在する場合に、それらのサーバに対するリクエストを集約し、負荷を分散するために利用される。セキュリティの向上やキャッシュ機能を活用し、クライアントから直接サーバへのアクセスを防ぐことができる。また、SSL/TLSの終端処理を行うこともでき、通信の暗号化を簡便に管理する手段としても使用される。これにより、システム全体のパフォーマンスを向上させるだけでなく、運用管理の効率化にも寄与する技術である。\nHOME»用語集»ネットワーク»通信プロトコル","explanationZh":"代表后端服务器接收外部客户端请求并转发到内部服务器的中间服务器。可隐藏后端、终止TLS、负载均衡并结合WAF提升Web服务安全性。"},{"id":"t0912","chapterId":"c20","termJa":"OSI参照モデル","termZh":"OSI参考模型（OSI七层模型）","english":"OSI Reference Model","reading":"おーえすあいさんしょうもでる","breadcrumb":"SG補足｜通信プロトコル・ネットワーク基礎","explanationJa":"OSI参照モデルは、ネットワーク通信の機能を7つの層に分けて理解するための概念モデルである。実際のインターネットはTCP/IPモデルで動作するが、機器・プロトコル・障害箇所を整理するときにOSIの層番号がよく使われる。\n\nL7 アプリケーション層：利用者に近い通信サービス。HTTP、SMTP、POP3、IMAP、FTP、DNS、DHCPなど。WAFやアプリケーションプロキシは主にL7を扱う。\nL6 プレゼンテーション層：文字コード、データ形式、圧縮、暗号化など“データ表現”を調整する。\nL5 セッション層：通信セッションの確立・維持・終了を管理する。\nL4 トランスポート層：端末間通信、信頼性、分割・再構成。TCP/UDP、ポート番号。L4ロードバランサなど。\nL3 ネットワーク層：異なるネットワーク間の配送と経路選択。IP、ICMP、ルーティング。ルータ、L3スイッチ。\nL2 データリンク層：同一リンク内でフレームを転送。Ethernet、Wi-Fi、MACアドレス、VLAN。L2スイッチ、ブリッジ、NIC。ARPはL2とL3の境界的なプロトコルとして理解されることが多い。\nL1 物理層：電気・光・無線信号を伝送。ケーブル、光ファイバ、コネクタ、リピータ、ハブなど。\n\n【試験速記】MAC＝L2、IP＝L3、ポート番号/TCP/UDP＝L4、HTTP/SMTP/DNS＝L7。","explanationZh":"OSI参考模型把网络通信功能分成7层。实际互联网主要按TCP/IP协议族运行，但考试和故障分析经常使用OSI层号来判断“这个协议/设备工作在哪一层”。\n\nL7 应用层：直接向应用提供通信服务。HTTP、SMTP、POP3、IMAP、FTP、DNS、DHCP等；WAF、应用代理主要关注L7。\nL6 表示层：处理字符编码、数据格式、压缩、加密等“数据表示”。\nL5 会话层：建立、维持和结束通信会话。\nL4 传输层：端到端传输、可靠性、分段/重组。TCP、UDP、端口号；L4负载均衡器等。\nL3 网络层：跨网络传送和路由选择。IP、ICMP、路由；路由器、L3交换机。\nL2 数据链路层：同一链路内用帧传输。Ethernet、Wi-Fi、MAC地址、VLAN；L2交换机、网桥、网卡。ARP通常被理解为处于L2与L3之间，在TCP/IP模型中通常归入链路层。\nL1 物理层：传送电/光/无线信号。网线、光纤、连接器、中继器、集线器等。\n\n【考试速记】MAC＝L2；IP＝L3；端口号/TCP/UDP＝L4；HTTP/SMTP/DNS＝L7。","chapterJa":"通信プロトコル","chapterZh":"通信协议"},{"id":"t0913","chapterId":"c20","termJa":"TCP/IP 4層モデル","termZh":"TCP/IP四层模型","english":"TCP/IP Four-Layer Model","reading":"てぃーしーぴーあいぴーよんそうもでる","breadcrumb":"SG補足｜通信プロトコル・ネットワーク基礎","explanationJa":"TCP/IPモデルは、インターネットで使われる通信機能を4層で整理する実用的なモデルである。\n\n① アプリケーション層：HTTP、HTTPS、SMTP、POP3、IMAP、FTP、DNS、DHCPなど。OSIのL5～L7におおむね対応。\n② トランスポート層：TCP、UDP、ポート番号。OSI L4に対応。\n③ インターネット層：IP、ICMP、ルーティング。OSI L3に対応。代表機器はルータ/L3スイッチ。\n④ ネットワークインタフェース（リンク）層：Ethernet、Wi-Fi、MACアドレス、ARPなど。OSI L1～L2におおむね対応。代表機器はNIC、L2スイッチ、アクセスポイントなど。\n\n【OSIとの対応】OSI 7/6/5 → TCP/IPアプリケーション、OSI 4 → トランスポート、OSI 3 → インターネット、OSI 2/1 → リンク。","explanationZh":"TCP/IP模型是按实际互联网协议族整理通信功能的四层模型。\n\n① 应用层：HTTP、HTTPS、SMTP、POP3、IMAP、FTP、DNS、DHCP等，大致对应OSI的L5～L7。\n② 传输层：TCP、UDP、端口号，对应OSI L4。\n③ 网际层：IP、ICMP、路由，对应OSI L3；典型设备是路由器、L3交换机。\n④ 网络接口/链路层：Ethernet、Wi-Fi、MAC地址、ARP等，大致对应OSI L1～L2；典型设备是网卡、L2交换机、无线AP。\n\n【与OSI对应】OSI 7/6/5 → TCP/IP应用层；OSI 4 → 传输层；OSI 3 → 网际层；OSI 2/1 → 链路层。","chapterJa":"通信プロトコル","chapterZh":"通信协议"},{"id":"t0562","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"IPアドレス","termZh":"IP地址","english":"IP Address","reading":"あいぴーあどれす","breadcrumb":"","explanationJa":"インターネットやイントラネット上でデバイスを識別するための一意の番号である。この番号は、デバイスが受信するデータを正確に送信するために必要不可欠で、ネットワーク上での位置情報の役割を果たす。たとえば、家の郵便番号が住所を特定するのと同じように、IPアドレスも各デバイスに特定の位置を与える。このアドレスはIPv4とIPv6の二つの形式が存在し、IPv4は32ビットの数値（例：192.168.0.1）、IPv6は128ビットの数値形（例：2001:0db8:85a3:0000:0000:8a2e:0370:7334）で提供される。これにより、世界中の無数のデバイスを区別し、スムーズな通信を可能にしている。","explanationZh":"用于在IP网络中标识主机或网络接口的逻辑地址。IPv4和IPv6具有不同地址长度，路由设备依据IP地址转发数据包。"},{"id":"t0563","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"サブネットアドレス","termZh":"子网地址／网络地址","english":"Subnet Address","reading":"","breadcrumb":"","explanationJa":"ネットワーク内のデバイスを組織的に管理するために、IPアドレスを細分化したものである。これにより、大規模なネットワークを小さな部分に分けて管理することが容易になる。例えば、企業のネットワークが大きい場合、サブネットを使用することで、部門別や機能別にネットワークを分け、それぞれのサブネット内のデバイスの通信を効率化できる。通常、IPアドレスの一部をネットワーク識別用に使用し、残りをホスト識別用に使う。これにより、限られたIPアドレスをより効率的に利用し、ネットワークのセキュリティやパフォーマンス向上を図ることができる。","explanationZh":"表示某个IP子网本身的地址，由IP地址与子网掩码共同确定。它用于路由和判断主机是否位于同一网络范围。"},{"id":"t0564","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"サブネットマスク","termZh":"子网掩码","english":"Subnet Mask","reading":"","breadcrumb":"","explanationJa":"IPアドレスのネットワーク部分とホスト部分を区別するための識別情報である。このマスクは、どの部分がネットワークを示し、どの部分がそのネットワーク内の個々のデバイス（ホスト）を示すかを特定する役割を果たす。たとえば、IPv4アドレスの形式では、サブネットマスクは通常255.255.255.0のように表現され、これにより最初の3つのオクテット（255の部分）がネットワークを特定し、最後のオクテットがホストを特定することを示す。ネットワークの効率を向上させ、管理を簡単にするために、IPアドレスを小さなネットワークに分割する際に非常に重要である。この分割により、トラフィックの流れが最適化されるため、大規模なネットワークでも安定した通信が可能になる。","explanationZh":"在IPv4中用于区分IP地址中网络部分和主机部分的位掩码。也可使用CIDR前缀长度表示，例如/24。"},{"id":"t0565","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"MACアドレス","termZh":"MAC地址","english":"Media Access Control Address","reading":"まっくあどれす","breadcrumb":"","explanationJa":"ネットワークに接続されたデバイスを一意に識別するためのアドレスである。これは通常、ネットワークインターフェースカード（NIC）に割り当てられ、各デバイスが通信する際に利用される。48ビットから成り、通常は16進数で表記される。たとえば、\"00:1A:2B:3C:4D:5E\"のような形式である。このアドレスは、イーサネットやWi-Fiなどのローカルネットワークでの通信において非常に重要で、特定のデバイスにデータを正確に送信するために使用される。MACアドレスは変更できないため、デバイスの識別において確実性を持たせるが、一方でネットワークのセキュリティに影響を与えることもある。","explanationZh":"数据链路层用于标识网络接口的地址，典型以太网MAC地址为48位。交换机根据MAC地址转发帧，但MAC地址可被软件伪造。"},{"id":"t0914","chapterId":"c20","termJa":"ARP","termZh":"ARP地址解析协议","english":"Address Resolution Protocol","reading":"あーぷ","breadcrumb":"SG補足｜通信プロトコル・ネットワーク基礎","explanationJa":"ARP（Address Resolution Protocol）は、同一IPv4ネットワーク内で「宛先IPv4アドレスに対応するMACアドレス」を調べるためのプロトコルである。IPアドレスだけではEthernetフレームの宛先MACを決められないため、ARPで対応表を取得する。\n\n【基本フロー】\n① 端末はARPキャッシュを確認する。\n② 対応がなければ「このIPアドレスを持つ端末は誰か」というARP RequestをLAN内にブロードキャストする。\n③ 対象端末が自分のMACアドレスをARP Replyで返す。\n④ 対応するIP↔MACをARPキャッシュに一時保存し、Ethernetフレームを送信する。\n\nARPには応答の真正性を強く検証する仕組みがないため、偽の対応情報を送り込むARPスプーフィング/ARPポイズニングによって中間者攻撃などに悪用されることがある。IPv6ではARPではなくICMPv6のNeighbor Discovery（NDP）を利用する。\n\n【試験速記】ARP＝「IPv4アドレス → MACアドレスを知る」。","explanationZh":"ARP（地址解析协议）用于在同一IPv4局域网/链路中，根据目标IPv4地址查询对应的MAC地址。只有IP地址时，以太网帧还不知道该发给哪个MAC，因此需要ARP完成地址解析。\n\n【基本流程】\n① 主机先查询自己的ARP缓存。\n② 如果没有对应记录，就在局域网广播ARP Request：“谁拥有这个IP地址？”\n③ 目标主机返回ARP Reply，告知自己的MAC地址。\n④ 主机把IP↔MAC映射暂时写入ARP缓存，然后发送以太网帧。\n\nARP缺少强身份认证，因此攻击者可能伪造ARP响应进行ARP Spoofing/ARP Poisoning，把通信引向攻击者，从而形成中间人攻击。IPv6不使用ARP，而使用ICMPv6的Neighbor Discovery（NDP）。\n\n【考试速记】ARP＝“IPv4地址 → 查MAC地址”。","chapterJa":"通信プロトコル","chapterZh":"通信协议"},{"id":"t0566","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"ルーティング","termZh":"路由","english":"Routing","reading":"","breadcrumb":"","explanationJa":"通信ネットワークにおいてデータが送信元から目的地に達するための経路を決定するプロセスである。ネットワークには複数の経路が存在する場合があり、ルーティングは最適なルートを選択する役割を果たす。具体的には、ルーターと呼ばれる機器が使用され、パケットと呼ばれるデータの塊を管理しながら、効率的に送信されるように経路を選択する。例えば、インターネット上でのWebサイトへのアクセスでは、ルーティングによって、ユーザーのデバイスからデータが最も早く届く経路が選ばれる。また、動的ルーティングと静的ルーティングの二つの方法があり、前者はネットワークの状態に応じて経路を変更するのに対し、後者は予め設定した固定の経路を使用する。","explanationZh":"根据网络拓扑和路由信息选择数据包转发路径的过程。路由可由管理员静态配置，也可通过动态路由协议自动学习。"},{"id":"t0567","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"IPv4","termZh":"IPv4","english":"Internet Protocol version 4","reading":"あいぴーぶいふぉー","breadcrumb":"","explanationJa":"インターネット上でデータを送受信するための通信プロトコルの一つである。このプロトコルは、主にネットワーク層で使用され、デバイスやコンピュータに一意のIPアドレスを割り当てる役割を持つ。IPv4アドレスは、通常、4つの数値（0から255の範囲）で構成された点で区切られた形式、例えば「192.168.0.1」のように表現される。この形式により、インターネットに接続されたデバイス同士が正確に通信できるようになっている。インターネットの普及に伴い、IPv4アドレスは足りなくなったため、現在はIPv6という新しいプロトコルも登場しているが、依然としてIPv4は広く利用されている。データのルーティングや転送、さらにはネットワークアドレッシングにおいて重要な役割を担っている。","explanationZh":"第四版互联网协议，使用32位地址表示网络节点。由于地址空间有限，现实中广泛使用NAT等技术缓解地址不足。"},{"id":"t0568","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"IPv6","termZh":"IPv6","english":"Internet Protocol version 6","reading":"あいぴーぶいしっくす","breadcrumb":"","explanationJa":"インターネットプロトコルの第6版であり、IPアドレスを管理するための主要な技術である。IPv4に代わるもので、より多くのアドレス空間を提供するために設計されている。IPv4が約42億のユニークなアドレスを持つのに対し、IPv6は約340兆兆兆のアドレスをサポートするため、今後のインターネットの成長に対応することができる。自動設定機能やセキュリティの強化、通信の効率化が図られており、IoT（モノのインターネット）デバイスの増加に適したインフラを提供する。また、アドレスの表記が16進数であることから、各アドレスが簡潔に扱えるのも特徴である。これにより、将来的な接続デバイスの増加に対しても柔軟に対応できるようになっている。","explanationZh":"第六版互联网协议，使用128位地址，提供极大的地址空间，并改进地址自动配置等机制。IPv6与IPv4并不天然完全兼容，需要双栈或转换技术过渡。"},{"id":"t0569","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"ポート番号","termZh":"端口号","english":"Port Number","reading":"ぽーとばんごう","breadcrumb":"","explanationJa":"ネットワークにおける通信の接続先を特定するための識別番号である。これは、特定のアプリケーションやサービスが利用するデータの経路を示すもので、通常は0から65535までの範囲で指定される。トランスポート層においては、一般的なプロトコルとしてTCPやUDPがあり、これらはそれぞれ特定のポート番号を用いて通信を行う。たとえば、WebサイトへのアクセスにはHTTPが使用され、デフォルトではポート80が割り当てられている。この仕組みにより、同じIPアドレスを持つ複数のサービスが同時に動作することが可能になり、ネットワークの効率を高める役割を果たしている。","explanationZh":"传输层中用于区分同一主机上不同应用或服务的数字标识。TCP和UDP端口范围为0到65535，例如HTTPS常用443端口。"},{"id":"t0915","chapterId":"c20","termJa":"TCPとUDP","termZh":"TCP与UDP","english":"TCP and UDP","reading":"てぃーしーぴーとゆーでぃーぴー","breadcrumb":"SG補足｜トランスポート層","explanationJa":"TCPとUDPはいずれもトランスポート層の代表的なプロトコルで、ポート番号によってアプリケーションを識別する。\n\n【TCP】コネクション型。接続確立、順序制御、確認応答（ACK）、再送、フロー制御などにより信頼性を重視する。その分オーバーヘッドが大きい。Web通信、メール、ファイル転送などで広く利用される。\n【UDP】コネクションレス型。到達確認・再送・順序保証を基本的に行わないため軽量で遅延が小さい。DNS、音声/映像、リアルタイム通信など、速度やリアルタイム性を優先する場面で利用される。\n\n【試験ポイント】「確実性・順序・再送」ならTCP、「軽量・低遅延・リアルタイム」ならUDP。","explanationZh":"TCP和UDP都是传输层的代表协议，都通过端口号区分不同应用。\n\n【TCP】面向连接。通过连接建立、顺序控制、ACK确认、重传、流量控制等机制强调可靠传输，但开销较大。Web、电子邮件、文件传输等常使用TCP。\n【UDP】无连接。通常不提供到达确认、重传和顺序保证，因此开销小、延迟低。DNS、语音/视频和实时通信等强调速度与实时性的场景常使用UDP。\n\n【考试速记】看到“可靠、顺序、重传”优先想TCP；看到“轻量、低延迟、实时”优先想UDP。","chapterJa":"通信プロトコル","chapterZh":"通信协议"},{"id":"t0570","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"HTTP","termZh":"HTTP","english":"Hypertext Transfer Protocol","reading":"えいちてぃてぃぴー","breadcrumb":"","explanationJa":"Web上で情報をやり取りするためのプロトコルである。Webブラウザとサーバ間でデータを送受信する際に使用され、主にWebページやそのコンテンツを取得する役割を果たす。HTTPの動作はリクエストとレスポンスの形式をとり、ブラウザが特定のURLを入力すると、その情報を要求するリクエストを送信する。一方、サーバはそのリクエストに応じて、必要なデータを含むレスポンスを返す。この仕組みにより、テキスト、画像、動画など様々な形式のデータをスムーズに取得でき、インターネット上の情報の閲覧が可能となる。また、HTTPにはセキュリティを強化するためのHTTPSというバージョンも存在し、データの暗号化や安全な取引を行う際に利用される。","explanationZh":"Web中客户端和服务器交换请求与响应的应用层协议。HTTP本身不提供加密，敏感通信应使用基于TLS的HTTPS。"},{"id":"t0571","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"SMTP","termZh":"SMTP","english":"Simple Mail Transfer Protocol","reading":"えすえむてぃぴー","breadcrumb":"","explanationJa":"電子メールを送信するためのインターネットプロトコルである。このプロトコルは、メールクライアントとメールサーバ間、またはサーバ同士がメールを転送する際に使用される。SMTPでは、送信者のメールアドレスや受信者のメールアドレス、件名などの情報が含まれるメッセージを、指定されたサーバに届ける仕組みが整っている。例えば、GmailやYahooメールなどのメールサービスでは、このプロトコルを利用してメールが自動的に送信される。SMTPはシンプルで効率的な設計がなされているため、電子メールの根幹を支える重要な役割を果たしている。","explanationZh":"用于发送和转发电子邮件的应用层协议。客户端提交邮件时常配合SMTP-AUTH和TLS，服务器之间通常使用SMTP进行中继。"},{"id":"t0572","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"POP3","termZh":"POP3","english":"Post Office Protocol version 3","reading":"ぽっぷすりー","breadcrumb":"","explanationJa":"電子メールを受信するためのプロトコルの一つである。このプロトコルは、メールサーバからクライアントにメールをダウンロードする仕組みを提供する。具体的には、ユーザーがメールクライアントを使ってメールサーバに接続し、保存されているメールをローカルデバイスに取り込むことができる。一度メールをダウンロードするとサーバ側からメールが削除される設定が一般的であり、オフラインでのメール閲覧が可能であるため、インターネット接続が弱い環境でも便利である。ただし、メールをサーバに保存しないため、複数のデバイスでの同期が難しい点がある。これは、IMAPなどの他のプロトコルと比較されることが多い。","explanationZh":"从邮件服务器下载邮件到客户端的协议，传统使用方式常把邮件下载到本地处理。与IMAP相比，其服务器端文件夹和多设备同步能力较弱。"},{"id":"t0573","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"IMAP","termZh":"IMAP","english":"Internet Message Access Protocol","reading":"あいまっぷ","breadcrumb":"","explanationJa":"電子メールを管理するためのプロトコルである。IMAPを使用すると、ユーザーは複数のデバイスからメールボックスにアクセスし、メールを読み書きすることが可能となる。これは、メールがサーバ上に保存されているため、どのデバイスでも最新のメール状態を確認できるという特性を持つ。また、IMAPはフォルダ機能をサポートしており、メールを整理することが容易である。たとえば、スマートフォンやパソコンで同時にメールを確認しても、未読・既読の状態が一致するため、非常に便利である。特にビジネスシーンなどで広く利用されている。","explanationZh":"允许客户端在服务器上管理和同步邮件、文件夹及状态的协议。适合多设备访问同一邮箱，邮件通常保留在服务器端。"},{"id":"t0574","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"FTP","termZh":"FTP","english":"File Transfer Protocol","reading":"えふてぃーぴー","breadcrumb":"","explanationJa":"ファイルをネットワーク上で転送するためのプロトコルである。主に、クライアントとサーバ間でのファイルのアップロードやダウンロードを行う際に使用される。ユーザーはFTPソフトウェアを用いて指定のサーバに接続し、ファイルを選択して転送を行うことができる。このプロトコルは、特に大容量のデータや多くのファイルを扱う際に便利である。また、FTPはセキュリティ機能を持たないため、より安全な転送を求める場合はSFTP（Secure FTP）などの代替プロトコルが利用される。Webサイトの管理やデータのバックアップなど、様々な用途に広く用いられている。","explanationZh":"用于在客户端与服务器之间传输文件的协议。传统FTP的认证和数据可能明文传输，不适合敏感环境，应考虑SFTP或FTPS等安全替代方案。"},{"id":"t0575","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"DHCP","termZh":"DHCP","english":"Dynamic Host Configuration Protocol","reading":"でぃーえいちしーぴー","breadcrumb":"","explanationJa":"ネットワークに接続されるデバイスに自動的にIPアドレスやその他の設定情報を割り当てるためのプロトコルである。これにより、手動での設定作業を省略でき、特に大規模なネットワークでは管理が容易になる。DHCPサーバは、ネットワーク上でデバイスが接続される際に、利用可能なIPアドレスの中から適切なものを選び、その情報をデバイスに送信する。たとえば、家庭や企業のネットワークでは、パソコンやスマートフォンなどがDHCPを利用して自動的にIPアドレスを取得し、インターネットに接続できるようになっている。このように、DHCPはネットワークの効率と利便性を高める重要な役割を果たしている。","explanationZh":"自动向终端分配IP地址、子网掩码、默认网关和DNS服务器等网络参数的协议。可减少手工配置，但需要防范伪造DHCP服务器等风险。"},{"id":"t0576","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"Ethernet","termZh":"以太网（Ethernet）","english":"Ethernet","reading":"いーさねっと","breadcrumb":"","explanationJa":"コンピュータネットワークでデータを送受信するためのプロトコルの一つである。通常、ローカルエリアネットワーク（LAN）で使用され、複数の機器が相互に通信できる環境を提供する。いーサネットは、データをフレームという単位で送信し、各フレームには送信元や宛先の情報が含まれている。例えば、家庭内でのWi-Fiネットワークや企業のオフィスでの有線ネットワークは、いーサネットの技術に基づいていることが多い。また、いーサネット規格は、速度や接続方法に応じて異なるバージョンが存在し、さまざまなデバイスとの互換性を実現している。ネットワークの基盤として、いーサネットは現代の通信において重要な役割を果たしている。","explanationZh":"最广泛使用的有线局域网技术体系，由IEEE 802.3系列标准规范。通过帧和MAC地址实现局域网通信，并支持多种速率和物理介质。"},{"id":"t0577","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"IEEE802.11a/b/g/n/ac/ax","termZh":"IEEE 802.11a/b/g/n/ac/ax","english":"IEEE 802.11 Standards","reading":"あいとりぷるいーはちまるにてんいちいち・えー/びー/じー/えぬ/えーしー/えーえっくす","breadcrumb":"","explanationJa":"無線通信に関する標準規格の群であり、主にWi-Fi技術を示す。それぞれのバージョンは異なる通信速度や周波数帯域を持ち、技術の進化と共にデータ転送速度が向上している。たとえば、802.11aは5GHz帯域を使用し、最大54Mbpsの速度を提供する。一方、802.11nは450Mbpsにまで対応し、より広い範囲での接続を実現している。最近の802.11acや802.11axは、さらに高速なデータ転送と同時接続が可能で、家電製品やモバイルデバイスなど、さまざまなデバイスが接続される環境において非常に重要な役割を果たしている。これらの規格は、無線LANの性能や利便性を向上させ、私たちの日常生活に深く浸透している。","explanationZh":"IEEE制定的无线局域网标准系列，不同版本使用不同频段、调制和多天线技术，逐代提高速率和效率。802.11ax对应Wi-Fi 6/6E相关技术。"},{"id":"t0578","chapterId":"c20","chapterJa":"通信プロトコル","chapterZh":"通信协议","termJa":"Wi-Fi4/5/6/6E","termZh":"Wi-Fi 4／5／6／6E","english":"Wi-Fi 4/5/6/6E","reading":"わいふぁい4/5/6/6E","breadcrumb":"","explanationJa":"無線LANの規格であり、それぞれ異なる性能や特徴を持つ。Wi-Fi 4は802.11nに基づき、最大速度は600Mbpsで、広範囲のカバレッジが特徴である。Wi-Fi 5（802.11ac）は、より高いデータ転送速度を提供し、ビデオのストリーミングやオンラインゲームに適している。Wi-Fi 6（802.11ax）は、更なる速度向上と多くのデバイス接続に対応しており、最大速度は9.6Gbpsに達する。Wi-Fi 6Eは、Wi-Fi 6に加えて、6GHz帯の周波数を利用することで、混雑した環境でも接続品質を向上させる。これらの規格は、無線通信の効率を一層向上させ、家庭やオフィスでのインターネット利用を円滑にするために重要である。\nHOME»用語集»ネットワーク»ネットワーク管理","explanationZh":"Wi-Fi联盟对部分IEEE 802.11代际标准采用的易懂命名。一般分别对应802.11n、802.11ac、802.11ax；Wi-Fi 6E把Wi-Fi 6扩展到6GHz频段。"},{"id":"t0579","chapterId":"c21","chapterJa":"ネットワーク管理","chapterZh":"网络管理","termJa":"稼働統計","termZh":"运行统计","english":"Operational Statistics","reading":"かどうとうけい","breadcrumb":"5 ネットワーク5-4 ネットワーク管理","explanationJa":"ネットワークやシステムの性能や稼働状態を監視するために収集されるデータのことを指す。このデータは、システムがどのくらいの時間正常に稼働しているか、または障害が発生した際の情報を含む。このような統計を分析することで、運用管理者はシステムの健全性やパフォーマンスを評価し、改善点を見つけることができる。例えば、ネットワークの遅延時間や障害発生の頻度を示す統計があり、これを基に適切な対策を講じることが求められる。問題が発生する前に予測し、未然に防ぐための重要なツールである。","explanationZh":"对系统运行时间、故障次数、性能、资源利用率等运行数据进行收集和汇总。可用于趋势分析、容量规划、SLA评价和故障预防。"},{"id":"t0580","chapterId":"c21","chapterJa":"ネットワーク管理","chapterZh":"网络管理","termJa":"障害の切分け","termZh":"故障隔离／故障切分","english":"Fault Isolation","reading":"しょうがいのきりわけ","breadcrumb":"5 ネットワーク5-4 ネットワーク管理","explanationJa":"システムやネットワークに発生した障害を特定し、原因を明確にするためのプロセスである。これは、問題がどの部分に起因するのかを分析し、他の部分に影響を及ぼさずに特定の障害を切り離すことを意味する。たとえば、あるサーバがダウンした場合、そのサーバが担当しているサービスだけに影響を及ぼし、他のサービスには支障をきたさないようにする。このプロセスにより、迅速に障害の原因を特定し、復旧作業を効率化することが可能となる。また、システムの冗長性を高め、全体の信頼性向上にも寄与する。","explanationZh":"通过逐步排除和分层检查，把故障范围缩小到特定设备、网络、软件或功能模块的过程。明确故障边界后可加快修复和避免无关操作。"},{"id":"t0581","chapterId":"c21","chapterJa":"ネットワーク管理","chapterZh":"网络管理","termJa":"障害原因の特定","termZh":"故障原因确定／根因分析","english":"Root Cause Analysis","reading":"しょうがいげんいんのとくてい","breadcrumb":"5 ネットワーク5-4 ネットワーク管理","explanationJa":"システムやプロセスで発生した障害の根本的な原因を特定するプロセスである。この手法は、単なる表面的な症状を解決するのではなく、なぜその障害が発生したのかを深く掘り下げることを目的とする。例えば、サーバダウンの原因を調査する際には、ハードウェアの故障や設定ミス、ソフトウェアバグなどが考えられる。正確な原因を把握することで、再発防止策を講じることが可能となり、システムの信頼性を向上させることができる。一般的に、フィッシュボーンダイアグラムや5W1H等の手法を用いて、体系的に分析を進めることが行われる。","explanationZh":"分析故障现象和证据，找出导致故障发生的根本原因，而不仅是处理表面症状。根因明确后才能制定有效的再发防止措施。"},{"id":"t0582","chapterId":"c21","chapterJa":"ネットワーク管理","chapterZh":"网络管理","termJa":"復旧措置","termZh":"恢复措施","english":"Recovery Measures","reading":"ふっきゅうそち","breadcrumb":"5 ネットワーク5-4 ネットワーク管理","explanationJa":"システムやサービスに障害が発生した際に、被害を最小限に抑え、正常な状態に戻すための対策である。例えば、サーバがダウンした場合には、バックアップデータを用いてデータを復元したり、代替システムに切り替えたりすることが含まれる。このような措置は、業務の継続性を確保するために非常に重要であり、定期的なテストや訓練を通じて、実効性を高めることが求められる。また、復旧計画を策定することで、事前に具体的な手順を決めておくことができ、迅速に対応することが可能となる。\nHOME»用語集»ネットワーク»ネットワーク応用","explanationZh":"故障或事件发生后，为恢复系统、数据和业务到正常状态而采取的措施。包括重启、切换备用系统、数据恢复、配置修复和验证等。"},{"id":"t0583","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"メールサーバ","termZh":"邮件服务器","english":"Mail Server","reading":"","breadcrumb":"","explanationJa":"電子メールの送受信を管理するコンピュータシステムである。主に、ユーザーが送信したメールをインターネットを通じて他のメールサーバに届ける役割や、受け取ったメールをユーザーがアクセスできる状態に保つことを行う。具体的には、POP3やIMAPといったプロトコルを用いて、ユーザーのメールクライアントと連携し、メールの送受信を円滑に進める。特定のドメイン名に紐づいており、企業や個人のメールアカウントを管理するため、セキュリティやストレージの観点でも高い技術が求められる。また、スパムフィルタリングやウイルスチェックの機能も併せて提供されることが一般的であり、安全で効率的なコミュニケーションを実現する。","explanationZh":"负责接收、发送、中继和保存电子邮件的服务器。通常使用SMTP进行邮件发送和中继，并通过POP3或IMAP向用户提供邮件访问。"},{"id":"t0584","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"メールクライアント","termZh":"邮件客户端","english":"Mail Client","reading":"","breadcrumb":"","explanationJa":"電子メールを送受信するためのソフトウェアである。パソコンやスマートフォンなどにインストールされ、ユーザーがメールアカウントにアクセスしてメールを管理する役割を持つ。具体的には、Microsoft OutlookやMozilla Thunderbirdが代表的な例であり、これらのソフトウェアを利用することで、ユーザーはメールの作成、整理、受信トレイの管理などを行うことができる。インターネット接続があれば自動的にサーバと通信し、新着メールを確認することができるため、快適なメール操作が可能になる。また、オフラインでの利用もできるため、ネットワーク環境が不安定な場所でも便利である。","explanationZh":"用户用于编写、发送、接收和管理电子邮件的软件。可通过SMTP发送邮件，通过IMAP或POP3从服务器访问邮件。"},{"id":"t0916","chapterId":"c22","termJa":"電子メール送受信の流れ","termZh":"电子邮件发送与接收流程","english":"Email Delivery Flow","reading":"でんしめーるそうじゅしんのながれ","breadcrumb":"SG補足｜ネットワーク応用・電子メール","explanationJa":"電子メールは「送信」と「受信」で使うプロトコルが異なる。基本的な流れは次のとおりである。\n\n送信者のメールソフト（MUA）\n→ SMTPで送信者側メールサーバへ提出\n→ DNSで受信ドメインのメールサーバ（MX情報など）を調べる\n→ SMTPで受信者側メールサーバへ中継\n→ 受信者のメールボックスに保存\n→ 受信者がIMAPまたはPOP3で閲覧/取得\n\nSMTP＝送る・中継する、POP3＝メールを端末へ取得する、IMAP＝サーバ上のメールを同期・管理する、と覚える。Webメールでは利用者はHTTPSでWeb画面を操作するが、メール事業者の内部ではSMTPなどのメールプロトコルが利用される。\n\n【セキュリティ】TLSは通信経路を暗号化する。一方、S/MIMEやPGPなどはメッセージ単位の暗号化やデジタル署名によってエンドツーエンドの保護を行える。","explanationZh":"电子邮件“发送”和“接收”使用的协议不同，典型流程如下：\n\n发送方邮件客户端（MUA）\n→ 使用SMTP把邮件提交给发送方邮件服务器\n→ 通过DNS查询收件域的邮件服务器（例如MX信息）\n→ 邮件服务器之间用SMTP进行中继\n→ 邮件保存到收件人的邮箱\n→ 收件人使用IMAP或POP3访问/下载邮件\n\n记忆：SMTP＝发送/中继；POP3＝把邮件取到客户端；IMAP＝在服务器上同步和管理邮件。Web Mail用户表面上通过HTTPS操作网页，但邮件服务商后台仍会使用SMTP等邮件协议。\n\n【安全】TLS主要保护通信链路；S/MIME、PGP等可以对邮件消息本身进行端到端加密和数字签名。","chapterJa":"ネットワーク応用","chapterZh":"网络应用"},{"id":"t0585","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"リレー方式","termZh":"中继方式","english":"Relay Method","reading":"りれーほうしき","breadcrumb":"","explanationJa":"電子メールの送受信において、メールを一時的に別のサーバを介して転送する仕組みである。この方法では、送信者が直接受信者にメールを届けるのではなく、まず中継サーバにメールが送られ、そこから最終的な宛先へと転送される。例えば、ユーザーがあるメールサービスを利用してメッセージを送ると、そのメールはまずそのサービスのサーバに届き、その後、受信者のメールサーバへと送られる。スパム対策や負荷分散、メールの保管・転送の効率化に役立ち、安全にメッセージを配送するための重要な技術である。","explanationZh":"邮件服务器接收一方邮件后转发给下一邮件服务器直至到达目的地的传递机制。服务器应限制未经授权的开放中继，防止被滥用于垃圾邮件。"},{"id":"t0586","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"同報メール","termZh":"群发邮件","english":"Broadcast Email","reading":"どうほうめーる","breadcrumb":"","explanationJa":"同じ内容のメールを複数の宛先に一度に送信する方法である。この形式は、特にグループ内の連絡や情報共有に役立つ。例えば、学校の先生が全生徒に連絡事項を送信する際や、企業が従業員に重要なお知らせを伝える場合に使用される。同報メールの利点は、個別にメールを送る手間を省けることと、情報を多くの人に迅速に伝えられる点である。ただし、受信者のプライバシーを保護するためには、BCC機能を使用して、他の受信者のメールアドレスを隠す配慮が必要である。これにより、スパムや不要な返信を防ぐことができる。","explanationZh":"一次向多个收件人发送相同或类似内容的邮件。使用时应正确处理收件人地址，避免在To/CC中暴露不应互相公开的邮箱地址。"},{"id":"t0587","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"メーリングリスト","termZh":"邮件列表","english":"Mailing List","reading":"","breadcrumb":"","explanationJa":"特定のテーマやトピックに関心を持つ人々が情報を共有するための電子メールのグループである。参加者はリストに登録することで、グループ内のすべてのメンバーに対して一度のメール送信で情報を送ることができる。例えば、趣味や職業に関する知識を共有したり、イベントの案内を行ったりする際に便利である。メーリングリストを利用すると、個別にメールを送る手間が省け、多くの人に一度に情報が伝わるため、コミュニケーションが円滑になる。また、過去のメール履歴を参照できるため、議論の経過や重要な情報も確認しやすい。","explanationZh":"通过一个列表地址把邮件自动分发给多个成员的机制。适合群组讨论或通知，需要管理成员、发送权限和退订等规则。"},{"id":"t0588","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"メールボックス","termZh":"邮箱","english":"Mailbox","reading":"","breadcrumb":"","explanationJa":"電子メールを受信・保管するための場所である。インターネットを通じて送信されたメールは、宛先のメールボックスに届く仕組みになっている。具体的には、各ユーザーが持つアカウントに関連付けられたストレージ空間で、受信したメールはここに格納される。ユーザーは、メールクライアントやWebメールサービスを使用して、メールボックス内のメールを閲覧したり、返信したりすることができる。メールボックスには、受信フォルダのほか、送信フォルダやゴミ箱など、さまざまなフォルダが用意されており、管理が容易になるように設計されている。これにより、ユーザーは重要な情報やコミュニケーションを効率的に管理できる。","explanationZh":"邮件服务器上用于保存某个用户或账号邮件的逻辑存储空间，也可指用户的电子邮件账户。访问邮箱应通过身份认证和适当安全控制。"},{"id":"t0589","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"cc","termZh":"抄送（CC）","english":"Carbon Copy","reading":"しーしー","breadcrumb":"","explanationJa":"電子メールにおいて、メッセージを他の受信者にも同時に送信するための機能である。受信者が「cc」欄に追加された場合、メールの内容を他の人と共有することができる。この機能は、特定の情報を複数の人に伝えたい時に便利である。例えば、プロジェクトに関与するチームメンバー全員に情報を周知させるため、主要な受信者とともに「cc」欄に他のメンバーのメールアドレスを追加することが一般的である。これにより、受信者はメールの内容を直接把握でき、コミュニケーションの透明性が向上する。また、受信者は「cc」されたことを認識できるため、情報の受け取り手も重要な役割を持つと理解できる。","explanationZh":"邮件中把副本发送给除主要收件人以外人员的功能。CC列表中的地址通常会被所有收件人看到，因此不适合隐藏个人邮箱地址。"},{"id":"t0590","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"bcc","termZh":"密送（BCC）","english":"Blind Carbon Copy","reading":"びーしーしー","breadcrumb":"","explanationJa":"電子メールを送信する際に使用される機能の一つである。bccに指定された宛先は、他の受信者には表示されず、隠れているため、プライバシーを守る役割を果たす。例えば、一斉にメールを送る際に、複数の人にそのメールを届けたいが、互いのアドレスを知られたくない場合にbccを使用する。これにより、受信者は他の人のメールアドレスを閲覧できず、情報漏洩を防ぐことができる。また、ビジネスシーンやグループメールでの利用が一般的で、受信者の数が多い場合にも便利である。bccを適切に活用することで、よりスマートなコミュニケーションが実現できる。","explanationZh":"邮件中把副本发送给其他人员，但不向其他收件人显示这些地址的功能。群发给互不相关的外部人员时可减少地址泄露风险。"},{"id":"t0591","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"MIME","termZh":"多用途互联网邮件扩展（MIME）","english":"Multipurpose Internet Mail Extensions","reading":"まいむ","breadcrumb":"","explanationJa":"電子メールで使用される規格の一つである。この規格は、単純なテキストだけでなく、画像や音声、動画などさまざまなデータタイプをメールで送信できるようにするためのものである。たとえば、MIMEにより、JPEG画像やPDFファイルをメールに添付できるようになり、受信者はそれらのファイルを正しく表示・再生できる。メールのヘッダー情報にデータの種類を示す情報を追加することで機能し、そのため、受信者のメールソフトはどのアプリケーションでそのデータを開くべきかを判断することができる。これにより、メールのやり取りがより豊かで多様なものとなっている。","explanationZh":"扩展电子邮件格式，使邮件能够表示不同字符集、HTML正文、图片和附件等多种内容类型的标准。HTTP等协议也使用MIME媒体类型表示内容格式。"},{"id":"t0592","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"HTMLメール","termZh":"HTML邮件","english":"HTML Mail","reading":"えいちてぃーえむえるめーる","breadcrumb":"","explanationJa":"Webページの形式でメールを送信するための技術である。通常のテキストメールと異なり、画像や色、フォントを使って視覚的に豊かなデザインが可能で、受信者に印象的な情報を提供できる。MHTML形式では、HTMLコードとともに必要な画像やスタイル情報を一つのファイルにまとめることができるため、相手にファイルを添付することなく、ブラウザで表示するのと同じ感覚でメールを閲覧できるのが特徴である。この方式は、特に企業のニュースレターやプロモーションメールで広く利用されており、受信者がメールを開いた瞬間から興味を引くことができる。さらに、インタラクティブな要素やリンクも活用できるため、効果的なマーケティングツールとして重宝されている。","explanationZh":"正文使用HTML格式编写的电子邮件，可显示富文本、图片和链接。由于可能包含外部资源和欺骗性链接，邮件客户端通常需要实施内容过滤和安全显示。"},{"id":"t0593","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"Webメール","termZh":"Web邮件","english":"Webmail","reading":"うぇぶめーる","breadcrumb":"","explanationJa":"インターネットを通じて利用できる電子メールサービスの一つである。専用のソフトウェアをインストールすることなく、ブラウザさえあれば、どこからでもメールの送受信が可能である。具体的な例としては、GmailやYahooメールなどが挙げられる。これらのサービスでは、ユーザーはサーバ上に保存されたメールを自分のデバイスで簡単にアクセスできる。さらに、データのバックアップや複数デバイスでの同期が容易なため、家庭や職場、外出先でも一貫したメール管理が可能である。このような利便性から、多くの人々に利用されている。","explanationZh":"通过浏览器访问邮件系统的服务形式，无需安装专用邮件客户端。账号安全、HTTPS、MFA和会话管理是其重要安全措施。"},{"id":"t0594","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"Webブラウザ","termZh":"Web浏览器","english":"Web Browser","reading":"うぇぶぶらうざ","breadcrumb":"","explanationJa":"インターネット上で情報を閲覧するためのソフトウェアである。ユーザーは、URLと呼ばれる特定のアドレスを入力することにより、WebページやWebアプリケーションにアクセスできる。具体的な例としては、Google ChromeやMozilla Firefox、Safariなどが挙げられる。これらのブラウザは、HTMLやCSS、JavaScriptなどの技術を使用して、テキスト、画像、動画などの情報を表示する。また、ブラウザにはブックマーク機能や履歴管理機能も搭載されており、ユーザーが訪れたWebサイトを簡単に再訪できるようになっている。セキュリティ機能や拡張機能を追加することで、自分の好みに合わせた使い方も可能であり、日常的なインターネット利用に欠かせない存在となっている。","explanationZh":"用于访问和显示Web页面及Web应用的客户端软件。应保持版本更新并谨慎管理扩展、下载和站点权限。"},{"id":"t0595","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"マークアップ言語","termZh":"标记语言","english":"Markup Language","reading":"まーくあっぷげんご","breadcrumb":"","explanationJa":"文書の構造や形式を指定するための記述方法である。主にWebページの作成に利用され、HTML（ハイパーテキストマークアップ言語）が最も有名である。HTMLを使用することで、テキストを見出しや段落、リンク、画像などの要素に分かりやすく整理することができる。また、XML（拡張可能マークアップ言語）もマークアップ言語の一種で、データの構造を記述するために広く用いられている。コンテンツを人間が理解しやすくし、ブラウザによって正しく表示させるための重要な役割を果たしている。これにより、インターネット上での情報共有が円滑に行われる。","explanationZh":"使用特定标签或标记描述文档结构、语义或显示方式的语言。HTML用于Web页面结构，XML则用于可扩展的数据描述。"},{"id":"t0596","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"HTML","termZh":"超文本标记语言（HTML）","english":"HyperText Markup Language","reading":"えいちてぃーえむえる","breadcrumb":"","explanationJa":"Webページを作成するための基本的なマークアップ言語である。この言語は、テキストに対して構造や意味を持たせるために、タグと呼ばれる特定の記号を使用する。例えば、見出しや段落、リンク、画像などを挿入する際に、それぞれに適したタグを用いることで、ブラウザがどのように表示するかを指定することができる。Webサイトの骨組みを形成し、他の技術（CSSやJavaScriptなど）と組み合わせることで、より複雑で美しいデザインや動的なコンテンツを実現する。これにより、訪問者にとって使いやすく魅力的なWeb体験を提供する。","explanationZh":"用于描述Web页面结构和内容的标准标记语言。HTML由元素和属性组成，并可配合CSS和JavaScript构建交互式网页。"},{"id":"t0597","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"XML","termZh":"可扩展标记语言（XML）","english":"eXtensible Markup Language","reading":"えっくすえむえる","breadcrumb":"","explanationJa":"データを構造化して表現するためのマークアップ言語である。主に、異なるシステム間でデータをやり取りする際に使用され、データの階層構造を明示的に示すことができる。例えば、Webサイトの設定データや、各種アプリケーションのデータフォーマットとして利用され、データの可読性を高める役割を果たす。また、XMLはユーザーが独自のタグを定義できるため、柔軟性があり、多様な用途に対応できる。この特徴により、XMLはWebサービスやデータベース、情報交換の基盤として非常に重要な技術とされている。","explanationZh":"使用自定义标签以层级结构表示和交换数据的文本格式。XML强调结构化和可扩展性，可通过模式等机制约束数据格式。"},{"id":"t0598","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"ハイパーリンク","termZh":"超链接","english":"Hyperlink","reading":"","breadcrumb":"","explanationJa":"Webページ内で他のページやリソースに移動するためのリンクのことである。通常は青色の下線付きのテキストや画像として表示され、クリックすることで他のWebサイトや同じサイト内の異なる場所へアクセスできる仕組みがある。この機能により、情報が効率的に繋がることで、ユーザーは必要な情報に迅速に到達できる。例えば、ニュース記事内の「続きを読む」というリンクや、オンラインショッピングサイトでの商品詳細ページへのリンクなどがハイパーリンクの具体例である。インターネットの特性を活かした重要な要素で、情報の共有やナビゲーションをスムーズに行うための基盤となっている。","explanationZh":"在一个文档或网页中指向另一个资源、位置或页面的链接。点击后浏览器通常根据URL访问目标资源，钓鱼攻击也常通过伪装链接诱导用户。"},{"id":"t0599","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"Webアプリケーションソフトウェア","termZh":"Web应用软件","english":"Web Application Software","reading":"うぇぶあぷりけーしょんそふとうぇあ","breadcrumb":"","explanationJa":"インターネットを通じて利用されるアプリケーションソフトウェアの一種である。ユーザーはWebブラウザを通じてアクセスし、特別なインストールなしで機能を利用できる。たとえば、オンラインバンキングやソーシャルメディア、クラウドストレージなどがこのカテゴリに含まれる。これらのアプリケーションは、サーバ側で実行され、データをリアルタイムで処理することができるため、インタラクティブな体験を提供する。また、常にインターネットに接続されているため、場所を問わず利用できる利点がある。これにより、ユーザーはどのデバイスからでも同じ環境で作業を続けられる。","explanationZh":"通过Web浏览器作为主要客户端、由服务器端程序处理业务逻辑的应用软件。其安全需重点防范XSS、SQL注入、CSRF、会话劫持等Web风险。"},{"id":"t0600","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"HTTP","termZh":"HTTP","english":"Hypertext Transfer Protocol","reading":"えいちてぃてぃぴー","breadcrumb":"","explanationJa":"Web上でデータを送受信するための通信プロトコルの一つである。主にWebブラウザとサーバの間で情報をやり取りする際に使用される。例えば、ユーザーがブラウザで特定のWebサイトにアクセスする際、HTTPを通じてリクエストを送り、そのレスポンスとしてWebページが返される。このプロトコルは、テキスト、画像、音声などさまざまな形式のデータを扱うことができるため、インターネットの基本的な仕組みを支えている。さらに、HTTPS（HTTP Secure）は、HTTPにセキュリティ機能を加え、データの暗号化を行うことで、より安全に通信を行う方法として普及している。そのため、HTTPはWebの発展に欠かせない重要な要素である。","explanationZh":"Web客户端与服务器之间交换资源请求和响应的应用层协议。它是无状态协议，Web应用通常利用Cookie等机制维持会话。"},{"id":"t0601","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"HTTPS","termZh":"HTTPS","english":"HyperText Transfer Protocol Secure","reading":"えいちてぃーてぃーぴーえす","breadcrumb":"","explanationJa":"インターネット上で安全に情報をやり取りするためのプロトコルである。具体的には、通常のHTTP（ハイパーテキスト転送プロトコル）にTLS（トランスポート層セキュリティ）という暗号化技術を組み合わせることによって、送信されるデータを第三者から保護する役割を持つ。このため、HTTPSを使用すると、パスワードやクレジットカード情報などの機密情報を安全に送信できる。また、WebサイトがHTTPSを利用している場合、ブラウザのアドレスバーに鍵のアイコンが表示され、ユーザーはそのサイトが安全であることを確認できる。これにより、フィッシング詐欺やデータの盗聴を防ぐ助けとなり、オンラインでの安心感を提供している。","explanationZh":"HTTP通过TLS加密运行的安全通信方式。它能够保护传输机密性和完整性，并通过证书认证服务器身份，是现代Web服务的基本安全要求。"},{"id":"t0602","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"cookie","termZh":"Cookie","english":"Cookie","reading":"くっきー","breadcrumb":"","explanationJa":"Webサイトがユーザーのブラウザに保存する小さなデータファイルである。これにより、ユーザーの訪問履歴やログイン情報などを記録し、次回訪問時に自動的にそれらの情報を引き出すことができる。具体的には、例えばオンラインショップで商品をカートに入れた際、その情報をCookieに保存することで、次回訪問時にもカート内の商品が保持される。このように、Cookieはユーザーにとって便利な機能を提供し、Webサイトの利用体験を向上させる役割を担っている。しかし、プライバシーの観点からは、個人情報が無断で追跡される可能性があるため、Cookieの使用には注意が必要である。","explanationZh":"Web服务器通过浏览器保存的小型数据，用于会话标识、偏好设置等。敏感Cookie应设置Secure、HttpOnly、SameSite等属性，并避免保存不必要的敏感信息。"},{"id":"t0603","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"ドメイン名","termZh":"域名","english":"Domain Name","reading":"どめいんめい","breadcrumb":"","explanationJa":"インターネット上で特定のWebサイトやメールサーバを識別するための文字列である。通常、表記は「example.com」のように、複数の部分から構成され、最初の部分はWebサイトの名前、最後の部分は国や種類を示すトップレベルドメイン（TLD）である。数値のIPアドレスを覚える代わりに使われ、ユーザーがブラウザに入力することで目的のサイトにアクセスできる。例えば、Googleのドメイン名は「google.com」であり、これを使ってユーザーは簡単にGoogleのサービスにアクセスできる。ドメイン名の取得や管理は、インターネットの基盤となる重要な要素であり、正確な設定が必要である。","explanationZh":"用于在互联网中以层级结构标识组织、主机或服务的人类可读名称，例如example.com。DNS把域名解析为IP地址等记录。"},{"id":"t0604","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"URL","termZh":"统一资源定位符（URL）","english":"Uniform Resource Locator","reading":"ゆーあーるえる","breadcrumb":"","explanationJa":"インターネット上で特定の情報やリソースの位置を指定するためのアドレスである。Webページやファイル等の場所を指し示すことで、それにアクセス可能にする役割を果たす。具体的には、URLはスキーム（例：HTTPやHTTPS）、ホスト名（ドメイン名）、パスなどの要素で構成されており、ブラウザに入力することで目的のページを表示させることができる。例えば、「https://www.example.com/index.html」というHTTPSスキームを使い、example.comというドメインの「index.html」というファイルを指す。URLの正しい理解は、インターネットで情報を探す際に非常に重要で、さまざまなサイトへ迅速にアクセスする手助けをする。","explanationZh":"表示网络资源位置和访问方法的字符串，通常包括协议、主机名、端口、路径和查询参数等。用户应检查域名和HTTPS状态以防钓鱼链接。"},{"id":"t0605","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"FTPサーバ","termZh":"FTP服务器","english":"File Transfer Protocol Server","reading":"えふてぃーぴーさーば","breadcrumb":"","explanationJa":"ファイルをインターネット上で転送するためのサーバである。FTPはファイル転送プロトコルの略で、ユーザーがサーバに接続し、データをアップロードしたりダウンロードしたりする際に使用される。具体的には、Webサイトのファイルを更新したり、大きなデータセットを共有したりする際に利用される。ユーザー認証やファイル管理機能を備えており、セキュリティを確保するためにパスワードでアクセスを制限することが一般的である。このように、効率的かつ安全にファイルをやりとりするための重要な役割を果たしている。","explanationZh":"通过FTP协议向客户端提供文件上传、下载和目录操作的服务器。传统FTP不加密，应根据安全需求使用FTPS或SFTP等更安全方式。"},{"id":"t0606","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"FTPクライアント","termZh":"FTP客户端","english":"FTP Client","reading":"えふてぃーぴーくらいあんと","breadcrumb":"","explanationJa":"ファイルをネットワーク経由で送受信するためのソフトウェアである。FTP（File Transfer Protocol）は、ファイルの転送を行うための標準的な通信プロトコルであり、FTPクライアントはこれを利用してサーバと接続し、データをアップロードしたりダウンロードしたりする。例えば、Webサイトのコンテンツを更新する際には、FTPクライアントを使用してローカルのファイルをサーバに送信することが一般的である。また、GUI（グラフィカルユーザーインターフェース）を持つクライアントも多く、初心者でも直感的に操作が可能で、ファイルのドラッグアンドドロップによる転送も簡単に行うことができる。個人のプロジェクトやビジネスシーンにおいて非常に便利なツールである。","explanationZh":"用于连接FTP服务器并进行文件传输的软件。它处理登录、目录浏览、上传和下载等操作。"},{"id":"t0607","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"アップロード","termZh":"上传","english":"Upload","reading":"","breadcrumb":"","explanationJa":"ローカルなコンピュータやデバイスから、インターネット上のサーバやクラウドサービスにデータを送信する行為である。具体的には、例えば、自分のパソコンに保存している写真や文書を、SNSやメールに添付して共有する際に行われる。このプロセスにより、データは他の人と簡単に共有できるようになり、データのバックアップやオンラインストレージへの保存が可能となる。また、Webサイトのコンテンツ管理や、アプリケーションの利用においても重要な役割を果たしており、多くのインターネットサービスで日常的に行われている。","explanationZh":"把本地设备中的数据或文件发送到远程服务器、云端或网络服务的过程。上传敏感数据前应确认权限、加密和目的地合法性。"},{"id":"t0608","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"ダウンロード","termZh":"下载","english":"Download","reading":"","breadcrumb":"","explanationJa":"インターネット上のサーバから、自分のコンピュータやスマートフォンにデータを取得する行為である。例えば、音楽や動画、ソフトウェアなどのファイルをインターネットから自分のデバイスに移すことで、後でオフラインでも利用できるようにする。このプロセスは、Webブラウザや専用のアプリケーションを用いて行うことが多い。ダウンロードの際、データは元の状態のまま保存され、速度やファイルのサイズによって所要時間は変わる。また、ダウンロードしたファイルを利用することで、ユーザーは様々なコンテンツを楽しむことができる。","explanationZh":"从远程服务器或网络服务把数据或文件传送到本地设备的过程。下载文件应验证来源和完整性，并防范恶意软件。"},{"id":"t0609","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"オンラインストレージ","termZh":"在线存储","english":"Online Storage","reading":"","breadcrumb":"","explanationJa":"インターネットを介してデータやファイルを保存するサービスである。このサービスにより、ユーザーは自分のデータを自宅や会社のデバイスではなく、クラウドサーバに保存できる。例えば、Google DriveやDropboxなどが一般的な例で、これらのサービスを利用することで、ファイルを簡単に共有したり、どこからでもアクセスしたりできる利点がある。さらに、データのバックアップや共有が容易になるため、個人の利用だけでなく、ビジネス環境においても広く活用されている。これにより、データ管理の効率が向上し、情報の保護も強化される。","explanationZh":"通过网络提供远程数据保存和访问的服务。用户可从不同地点访问数据，但需注意账号安全、共享权限、加密和服务可用性。"},{"id":"t0610","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"クラウドストレージ","termZh":"云存储","english":"Cloud Storage","reading":"","breadcrumb":"","explanationJa":"インターネット上でデータを保存するサービスのことである。ユーザーは、ファイルをクラウドサーバにアップロードすることで、どこからでもアクセスが可能になる。例えば、写真や文書をクラウドストレージに保存すれば、パソコンやスマートフォン、タブレットなどの様々なデバイスから見ることができる。この仕組みにより、ローカルストレージの容量を気にせずにデータを保持できるだけでなく、万が一のデータ喪失にも備えられる。代表的なサービスにはGoogle DriveやDropboxがあり、これらはファイルの共有や共同編集もサポートしているため、業務や個人の利用にとても便利である。","explanationZh":"利用云计算基础设施提供弹性、按需的数据存储服务。除访问控制和加密外，还需关注数据位置、版本、备份、供应商责任和误配置风险。"},{"id":"t0611","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"VPN","termZh":"虚拟专用网（VPN）","english":"Virtual Private Network","reading":"ぶいぴーえぬ","breadcrumb":"","explanationJa":"インターネットを使用して安全にデータを伝送するための技術である。外部からアクセスする際に、プライベートなネットワークを仮想的に構築し、データを暗号化して送信することにより、情報の漏洩を防ぐ役割を果たす。具体的には、リモートでオフィスに接続する際などに利用され、ユーザーの通信内容を第三者から保護することができる。これにより、公共のWi-Fi環境でも安全に業務を行うことが可能となる。また、VPNは地理的な制約を超えて、該当する国や地域のサービスにアクセスする手段としても用いられ、柔軟性とセキュリティを兼ね備えた重要な技術である。","explanationZh":"通过公共网络建立逻辑上的私有加密通道，用于远程接入或站点互联。VPN保护传输链路，但仍需结合终端安全、MFA和权限控制。"},{"id":"t0612","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"プライベートIPアドレス","termZh":"私有IP地址","english":"Private IP Address","reading":"ぷらいべーとあいぴーあどれす","breadcrumb":"","explanationJa":"特定のネットワーク内でのみ使用され、外部のインターネットから直接アクセスできないIPアドレスのことを指す。これは、企業や家庭内のネットワークで、デバイス同士が通信するために設定されるもので、一般的にルーターやネットワーク機器が自動的に割り当てる。例えば、家庭内のWi-Fiネットワークでは、スマートフォンやパソコンがプライベートIPアドレスを持ち、同じネットワーク内の他のデバイスとデータをやり取りできる。一方で、インターネットに接続するためには、ルーターが公的なIPアドレスを使用して外部との接続を行うため、セキュリティ面でも役立っている。主にネットワークのスケーラビリティを等を向上させる重要な要素である。","explanationZh":"仅用于内部网络、不会在公共互联网中直接路由的地址。IPv4常见私有地址范围包括10.0.0.0/8、172.16.0.0/12和192.168.0.0/16。"},{"id":"t0613","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"EC","termZh":"电子商务（EC）","english":"Electronic Commerce","reading":"いーしー","breadcrumb":"","explanationJa":"インターネットを通じて商品やサービスの売買を行う仕組みである。電子商取引は、顧客がオンラインで商品を購入したり、企業がサービスを提供したりする際の取引を含む。具体的には、オンラインショッピングサイトやオークションサイト、デジタルコンテンツの販売などがその例である。また、ECにおいては、取引の安全性を保つために、暗号化技術や支払いシステムが重要な役割を果たしている。このような電子商取引は、ビジネスの効率化と顧客の利便性を向上させるために広く利用されており、今や日常生活に欠かせない要素となっている。エクストラネットとの関連では、企業間の取引や顧客とのインタラクションを円滑にするための発展的なプラットフォームとして機能することが多い。","explanationZh":"通过互联网等电子网络进行商品、服务订购、支付和交易的商业活动。其安全重点包括支付安全、身份认证、个人信息保护和交易完整性。"},{"id":"t0614","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"EDI","termZh":"电子数据交换（EDI）","english":"Electronic Data Interchange","reading":"いーでぃーあい","breadcrumb":"","explanationJa":"電子データ交換のことを指し、企業間での商取引において、注文書や請求書などのビジネス文書を電子的にやり取りする仕組みである。従来の紙の文書に代わり、EDIを利用することで、処理時間の短縮や人的ミスの削減が図られる。例えば、ある企業が仕入れ先に製品の注文をする際に、EDIを使って自動的に電子文書を送信することで、迅速かつ効率的な取引が実現される。また、異なるシステムやプラットフォームを持つ企業同士でも標準化された形式でデータを交換できるため、ビジネスの連携がスムーズになる。近年では、デジタル化が進む中で、EDIの重要性がますます高まっている。","explanationZh":"企业之间按照统一格式，通过电子方式直接交换订单、发票、运输等业务数据的机制。可提高交易效率，并需要身份认证、数据完整性和通信安全。"},{"id":"t0615","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"専用線サービス","termZh":"专线服务","english":"Leased Line Service","reading":"せんようせんさーびす","breadcrumb":"","explanationJa":"特定の顧客のために提供される通信回線である。このサービスでは、他のユーザーと共有せずに、常に一定の帯域幅を利用できるため、高速かつ安定した通信が保証される。例えば、企業が複数の拠点を結ぶために専用線サービスを利用することで、安定したデータ通信や電話サービスを確保できる。専用線は、インターネット接続以外にも、ISDNや音声通話など様々なサービスに利用され、特に通信の信頼性が求められるビジネス環境において広く使用されている。このように、安定かつ高品質な通信を必要とする企業にとって欠かせない選択肢である。","explanationZh":"运营商向特定客户提供固定站点之间专用通信线路的服务。其带宽和质量通常较稳定，适合需要可预测通信质量的企业网络。"},{"id":"t0616","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"回線交換サービス","termZh":"电路交换服务","english":"Circuit Switched Service","reading":"かいせんこうかんさーびす","breadcrumb":"","explanationJa":"通信を行うために専用の回線を確保する方式である。通信を開始すると、送信者と受信者の間に一時的な専用回線が設けられ、その回線を通じてデータが送信される仕組みを持つ。具体的には、電話の通話がこの方式の代表例であり、通話中は他の利用者がその回線を使うことができなくなる。この特性により、音声通信の場合には安定した品質が確保されやすいが、回線を使用する時間帯により費用が高くなることもある。一方、データ通信では回線交換ではなくパケット交換が多く用いられるが、それぞれの用途に応じた利点が活かされている。","explanationZh":"通信开始前先建立一条端到端专用通信路径，并在整个会话期间占用该线路资源的服务方式。传统电话网络是典型例子。"},{"id":"t0617","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"パケット交換サービス","termZh":"分组交换服务","english":"Packet Switching Service","reading":"ぱけっとこうかんさーびす","breadcrumb":"","explanationJa":"データを小さな単位（パケット）に分割して送信する通信方式である。この方式は、ネットワーク内の複数のユーザーが同時にデータを送受信できることが特徴で、効率的な通信を実現する。たとえば、インターネットを通じてメールを送る際、メールデータはパケットに分割され、それぞれが異なる経路を通って目的地に到達する。このため、ネットワークの帯域幅を最大限に利用でき、柔軟なデータ伝送が可能になる。また、音声通話やビデオ通話といったリアルタイム通信にも対応しており、多様なサービスを一つのインフラで提供するため非常に有用である。","explanationZh":"把通信数据划分为数据包并通过共享网络传输的服务方式。多个用户可以动态共享带宽，资源利用效率高，是现代数据网络的基础。"},{"id":"t0618","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"インターネットサービス","termZh":"互联网服务","english":"Internet Service","reading":"","breadcrumb":"","explanationJa":"インターネットを通じて提供される各種のサービスを指す。主な例としては、Webサイトの閲覧、メール送信、オンラインゲーム、ストリーミング動画などが挙げられる。これらのサービスは、ユーザーがインターネットに接続することで利用可能となり、情報の共有やコミュニケーションを促進する。さらに、クラウドストレージやリモートワークツールなどもインターネットサービスに含まれ、ビジネスや日常生活の効率化に寄与している。ユーザーのニーズに応じた多様な機能を提供し、快適なオンライン体験を実現する。","explanationZh":"通过公共互联网提供的连接、Web、邮件、云等各种网络服务的统称。服务质量和安全性取决于所使用的协议、服务商和配置。"},{"id":"t0619","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"FTTH","termZh":"光纤到户（FTTH）","english":"Fiber to the Home","reading":"えふてぃーてぃーえいち","breadcrumb":"","explanationJa":"光ファイバーを使ってインターネット接続を家庭まで直接行う通信サービスである。この方式は、光ファイバーケーブルを利用するため、高速で安定したインターネット接続が可能となる。従来の銅線ケーブルと比較して、データの伝送速度が格段に速く、特に大容量の動画視聴やオンラインゲーム、テレワークなどの利用においてその利点が際立つ。FTTHは通信インフラの中でも先進的な技術であり、多くの国や地域で普及が進んでいる。ユーザーは、より快適なインターネット環境を享受することができ、デジタルサービスの利用がさらに広がる可能性がある。","explanationZh":"将光纤线路直接铺设到住宅或用户场所的宽带接入方式。具有高带宽、低衰减等特点，广泛用于固定互联网接入。"},{"id":"t0620","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"IP電話","termZh":"IP电话","english":"Internet Protocol Telephone","reading":"あいぴーでんわ","breadcrumb":"","explanationJa":"インターネットを利用して音声通話を行う通信サービスである。従来の電話回線ではなく、データ通信を通じて音声をデジタル信号に変換し、相手に送信する仕組みを持つ。例えば、SkypeやZoomなどのアプリを使って、音声だけでなく映像も一緒にやり取りすることができる。この技術は、低コストで長距離通話が可能であるため、多くの人々に利用されている。また、IP電話は電話番号を持ち、一般の電話機からの発信・受信も可能であり、従来の固定電話に代わる選択肢として注目されている。インターネット接続環境さえあれば、どこでも利用できるという利便性も大きな特徴である。","explanationZh":"通过IP网络传输语音的电话服务。语音被数字化并封装成IP数据包传送，服务质量会受网络延迟、抖动和丢包影响。"},{"id":"t0621","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"モバイル通信","termZh":"移动通信","english":"Mobile Communication","reading":"もばいるつうしん","breadcrumb":"","explanationJa":"携帯電話やスマートフォンを利用して通信を行う技術を指す。これにより、ユーザーは地理的な制約を受けずに音声通話やデータ通信を行うことが可能である。例えば、携帯電話を使ってインターネットに接続したり、メッセージを送信したりすることができる。モバイル通信の技術には、2Gから最新の5Gまでの世代が存在し、それぞれ速度や接続の安定性が向上している。モバイル通信の発展により、私たちの日常生活において情報収集やコミュニケーションの手段が大きく変わり、特にビジネスや社会交流の効率が高まった。","explanationZh":"利用蜂窝无线网络让移动终端进行语音、数据和互联网通信的技术。不同代际包括LTE和5G等，需要考虑无线接入、身份认证和漫游安全。"},{"id":"t0622","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"LTE","termZh":"LTE","english":"Long Term Evolution","reading":"えるてぃーいー","breadcrumb":"","explanationJa":"次世代のモバイル通信技術の一つであり、高速なデータ通信を実現するための規格である。これにより、スマートフォンやタブレットでのインターネット接続速度が大幅に向上し、動画のストリーミングやオンラインゲーム、SNSの利用が快適に行えるようになる。音声通話だけでなく、高速データ通信を重視して設計されており、Wi-Fi同様の快適さをユーザーに提供する。さらに、LTEの技術は、後の5G通信への道を開く重要な役割も果たしており、今後の通信インフラにも影響を与えると期待されている。","explanationZh":"第四代移动通信体系中的高速无线接入技术之一，提供较高数据速率和低于早期3G的延迟。它基于全IP网络架构，广泛用于智能手机和IoT通信。"},{"id":"t0623","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"5G","termZh":"第五代移动通信系统（5G）","english":"Fifth Generation Mobile Communication System","reading":"ふぁいぶじー","breadcrumb":"","explanationJa":"モバイル通信の第5世代であり、これまでの通信技術に比べて高速で低遅延なデータ通信を実現するものである。5Gの特徴は、1秒間に何千ものデバイスを同時に接続できる能力や、リアルタイムでの通信が可能なことにある。この技術により、スマートフォンのインターネット速度が向上するだけでなく、自動運転車やIoT（モノのインターネット）デバイスとの連携も強化される。さまざまな産業やサービスに革新をもたらし、特に遠隔医療やバーチャルリアリティなど新しいビジネスの可能性を広げる基盤となっている。","explanationZh":"新一代蜂窝移动通信技术，目标包括更高速率、更低延迟和更大设备连接能力。可支持移动宽带、工业控制和大规模IoT等应用。"},{"id":"t0624","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"テザリング","termZh":"网络共享／手机热点（Tethering）","english":"Tethering","reading":"","breadcrumb":"","explanationJa":"スマートフォンやタブレットなどの携帯デバイスが、インターネット接続を他のデバイスに共有する機能を指す。具体的には、スマートフォンをルーターのように使用して、ノートパソコンやタブレットをインターネットに接続することができる。これにより、自宅や公共のWi-Fiがない場所でも、携帯電話のデータ通信を利用してインターネットにアクセスできる。この機能は、モバイル環境での接続性を高め、移動中でもオンライン作業を可能にするため、特にビジネスや旅行の際に便利である。Wi-FiやUSBケーブル、Bluetoothなど複数の方法で実行できるため、利用者のニーズに応じた柔軟な選択肢を提供している。","explanationZh":"把智能手机等设备的移动通信连接通过Wi-Fi、USB或蓝牙共享给其他终端使用的功能。使用时应设置强认证并注意流量、终端和公共网络安全。"},{"id":"t0625","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"広域Ethernet","termZh":"广域以太网","english":"Wide Area Ethernet","reading":"こういきいーさねっと","breadcrumb":"","explanationJa":"広い地理的範囲にわたって複数の拠点を接続するための通信技術である。従来のイーサネットを拡張したもので、高速なデータ転送を可能にする。例えば、企業が異なる都市にあるオフィス同士を結ぶ際に、広域Ethernetを利用することで、迅速かつ効率的にデータを統合的に管理できる。これにより、業務効率を向上させることが可能である。また、既存の通信インフラを利用するため、導入コストが抑えられるメリットがある。さらに、サービス提供会社は、安定した通信環境を確保するために、冗長性を持たせた構成を選択することが多く、可用性にも優れている。","explanationZh":"运营商利用以太网技术在不同地点之间提供二层广域连接的企业网络服务。可像扩展LAN一样连接多个站点，并支持较高带宽。"},{"id":"t0626","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"IP-VPN","termZh":"IP-VPN","english":"IP Virtual Private Network","reading":"あいぴーぶいぴーえぬ","breadcrumb":"","explanationJa":"インターネットを利用して仮想的にプライベートネットワークを構築する通信サービスである。これにより、異なる拠点を持つ企業が、安全にデータをやり取りできる環境を整えることが可能となる。具体的には、暗号化されたデータ通信を行うことで、外部からの不正アクセスを防ぎ、信頼性の高いネットワークを実現する。これは、遠隔地にあるオフィス間での情報共有や通信の効率を高めるために活用されており、企業の業務活動を支える重要な技術となっている。","explanationZh":"运营商在其封闭IP网络中为企业构建逻辑专用网络的服务。通常不经过公共互联网，能够提供较稳定的通信质量和一定的隔离性。"},{"id":"t0627","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"インターネットVPN","termZh":"互联网VPN","english":"Internet Virtual Private Network","reading":"いんたーねっとぶいぴーえぬ","breadcrumb":"","explanationJa":"インターネットを介してプライベートネットワークを安全に接続するための技術である。VPNは、異なる場所にいる複数のユーザーや拠点が安全にデータをやり取りできるようにする。例えば、自宅や外出先から企業の内部ネットワークにアクセスする際、VPNを利用することで情報が暗号化され、第三者に盗聴されるリスクが減少する。また、VPNを使用することで、地域制限のあるサービスにアクセスすることも可能になる。このように、セキュリティやプライバシーを確保しつつ、便利な通信を実現する重要な手段である。","explanationZh":"利用公共互联网，通过IPsec或TLS等加密技术建立安全隧道的VPN方式。成本通常较低，但通信质量受公网影响，需要正确配置加密和认证。"},{"id":"t0628","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"VoIP","termZh":"IP语音（VoIP）","english":"Voice over Internet Protocol","reading":"ぶいおーあいぴー","breadcrumb":"","explanationJa":"インターネットを通じて音声通話を行う技術である。従来の電話回線を使わずに、データ通信の仕組みを利用して音声をデジタル化し、送受信することで通話が可能となる。例えば、SkypeやZoomといったアプリケーションがVoIP技術を活用している。これにより、従来の電話よりも低コストで通話を行えるほか、インターネット環境があればどこでも通話ができるという利点がある。また、VoIPはビデオ通話やファイルの共有など、さまざまなコミュニケーション方法と統合されることが多く、ビジネスや個人の距離を縮める手段として広く用いられている。","explanationZh":"把语音转换为数字数据并通过IP网络传输的技术。可降低通信成本并与数据网络融合，但需要考虑时延、抖动、可用性和安全防护。"},{"id":"t0629","chapterId":"c22","chapterJa":"ネットワーク応用","chapterZh":"网络应用","termJa":"ベストエフォート","termZh":"尽力而为（Best Effort）","english":"Best Effort","reading":"","breadcrumb":"","explanationJa":"主に通信サービスにおいて、提供される帯域幅や速度が保証されない方式を指す。この場合、サービスプロバイダーは、可能な限りの最善の努力をしてデータの送受信を行うが、実際の通信速度や品質は様々な要因によって変動することがある。例えば、インターネット接続サービスでは混雑時に速度が低下することが一般的で、特に大量のデータを同時に送信するユーザーが多い場合、通信速度に影響が出ることがある。ベストエフォート方式は、コストを抑えつつ、必要に応じた柔軟なサービスを提供する際に利用されることが多い。","explanationZh":"网络服务不保证固定带宽、延迟或吞吐量，而是在可用资源范围内尽可能传输数据的服务方式。互联网通常采用这种特性，因此实际性能会随拥塞和环境变化。"},{"id":"t0630","chapterId":"c23","chapterJa":"プロジェクトマネジメント","chapterZh":"项目管理","termJa":"プロジェクト","termZh":"项目","english":"Project","reading":"","breadcrumb":"6 プロジェクトマネジメント6-1 プロジェクトマネジメント","explanationJa":"特定の目的を達成するために、期限、予算、リソースが定められた一連の作業や活動を指す。一時的なものであり、完了すると通常は終了する。たとえば、新製品の開発やイベントの企画などがプロジェクトの例である。プロジェクトマネジメントは、これらのプロジェクトを計画、実行、監視、制御する手法や知識の体系であり、目標達成のために必要なスケジュール管理やリソース配分を行う。効果的なプロジェクトマネジメントにより、課題解決やリスク管理が適切に行われ、チームの協力を最大化することができる。これにより、質の高い成果物をタイムリーに提供することが可能となる。","explanationZh":"为实现特定目标而开展的临时性工作，具有明确的开始和结束时间，并受范围、时间、成本、质量和资源等约束。项目通过产出独特的产品、服务或结果来创造价值。"},{"id":"t0631","chapterId":"c23","chapterJa":"プロジェクトマネジメント","chapterZh":"项目管理","termJa":"プロジェクトマネジメント","termZh":"项目管理","english":"Project Management","reading":"","breadcrumb":"6 プロジェクトマネジメント6-1 プロジェクトマネジメント","explanationJa":"特定の目的を達成するために、一連の活動を計画、実行、監視するプロセスである。プロジェクトは、一時的な活動であり、明確な開始と終了が存在し、特定の成果物を生み出すことを目指す。プロジェクトマネジメントでは、リソースの管理やスケジュールの調整、リスクの評価が重要であり、これにより効率的にプロジェクトを進行させることが可能となる。例えば、ソフトウェア開発や建設プロジェクトなど、さまざまな分野で応用されており、成功するプロジェクトを実現するために必須のスキルが求められる。このように、プロジェクトマネジメントは限られた時間と資源を最適に活用し、プロジェクトの成功を確保する役割を果たしている。","explanationZh":"运用知识、技能、工具和方法对项目活动进行计划、组织、执行、监控和收尾，以满足项目目标和相关方要求的管理活动。需要综合平衡范围、进度、成本、质量、风险和资源等因素。"},{"id":"t0917","chapterId":"c23","termJa":"テーラリング","termZh":"裁剪／适配（项目管理 Tailoring）","english":"Tailoring","reading":"てーらりんぐ","breadcrumb":"SG補足｜プロジェクトマネジメント","explanationJa":"テーラリング（Tailoring）は、標準的なプロジェクトマネジメントのプロセス、ライフサイクル、文書、会議、管理方法などを、プロジェクトの規模・複雑さ・リスク・組織文化・契約条件に合わせて選択・調整することである。すべてのプロジェクトに同じ手順を機械的に適用するのではなく、必要十分な管理方法へ最適化する考え方である。\n\n例：小規模・低リスクの社内改修では承認文書や会議を簡素化する。高リスクの金融システムではレビュー、テスト、変更管理、証跡を強化する。\n\nただし、テーラリングは「必要な管理を勝手に省略する」ことではない。法令・契約・セキュリティ要件など必須事項を満たした上で、理由を明確にして適用方法を調整する。\n\n【混同注意】テーラリング（Tailoring）＝プロジェクト管理の適合化。テザリング（Tethering）＝スマートフォンなどの回線を他端末へ共有する機能。","explanationZh":"Tailoring在项目管理中指“裁剪/适配”：根据项目规模、复杂度、风险、组织文化、合同要求等，对标准项目管理流程、生命周期、文档、会议和控制方式进行选择和调整，而不是所有项目都机械使用完全相同的流程。\n\n例如：小型、低风险的内部改修项目可以简化部分审批文档和会议；高风险金融系统则应加强评审、测试、变更管理和审计证据。\n\n注意：Tailoring不是“随意省略必要控制”。法律、合同、安全要求等强制事项仍必须满足，裁剪应有合理依据。\n\n【易混淆】テーラリング（Tailoring）＝项目管理裁剪/适配；テザリング（Tethering）＝手机热点/网络共享。","chapterJa":"プロジェクトマネジメント","chapterZh":"项目管理"},{"id":"t0632","chapterId":"c23","chapterJa":"プロジェクトマネジメント","chapterZh":"项目管理","termJa":"プロジェクトの環境","termZh":"项目环境","english":"Project Environment","reading":"ぷろじぇくとのかんきょう","breadcrumb":"6 プロジェクトマネジメント6-1 プロジェクトマネジメント","explanationJa":"特定のプロジェクトを実施する際に影響を与える要因や条件を指す。これには、プロジェクトの目的、関与するメンバー、資源、時間、コスト、そして外部の経済的・政治的な状況などが含まれる。たとえば、新製品の開発プロジェクトでは、市場のニーズや技術の進歩、競争状況が環境に影響を与える重要な要素となる。プロジェクトマネジメントにおいては、これらの環境要因を適切に分析し、リスクを管理することが成功の鍵となるため、事前にしっかりと理解することが求められる。","explanationZh":"影响项目开展的内部和外部条件，包括组织文化、治理、法律法规、市场、技术、资源、相关方和既有系统等。项目经理应识别这些环境因素并据此调整管理方式。"},{"id":"t0633","chapterId":"c23","chapterJa":"プロジェクトマネジメント","chapterZh":"项目管理","termJa":"プロジェクトガバナンス","termZh":"项目治理","english":"Project Governance","reading":"","breadcrumb":"6 プロジェクトマネジメント6-1 プロジェクトマネジメント","explanationJa":"プロジェクトの運営や管理に関するルールや枠組みのことを指す。これはプロジェクトが目標を達成し、利益を最大化するために重要な役割を果たす。具体的には、プロジェクトの進行状況を監視し、リスクを管理するための基準やプロセスを定めることが含まれる。また、関係者（ステークホルダー）とのコミュニケーションを円滑にし、意思決定を迅速に行うための仕組みを提供する。プロジェクトガバナンスがしっかりしていることで、プロジェクトの成功率が高まり、無駄なコストや時間を省くことができるため、効率的なプロジェクト運営に貢献する。","explanationZh":"用于指导、监督和问责项目决策的制度与结构。它明确决策权限、责任、汇报和升级机制，确保项目与组织战略和风险容忍度保持一致。"},{"id":"t0634","chapterId":"c23","chapterJa":"プロジェクトマネジメント","chapterZh":"项目管理","termJa":"プロジェクトライフサイクル","termZh":"项目生命周期","english":"Project Life Cycle","reading":"","breadcrumb":"6 プロジェクトマネジメント6-1 プロジェクトマネジメント","explanationJa":"プロジェクトが開始されてから終了するまでの一連の過程を指す。一般的に、計画、実行、監視、完了の4つの主要なフェーズから成り立っている。初めに、プロジェクトの目標や範囲を定義し、必要なリソースを計画する。次に、その計画に基づいて実行し、進捗状況を監視することで問題を早期に発見し修正する。そして、プロジェクトの成果を確認し、正式に完了させる。このライフサイクルによって、プロジェクトの進行状況が把握しやすくなり、より効率的なマネジメントが可能となる。プロジェクトマネジメントの手法を活用することで、成功する可能性がさらに高まる。","explanationZh":"项目从启动到结束所经历的一系列阶段。通常包括启动、规划、执行、监控和收尾，也可根据行业划分为需求、设计、开发、测试、上线等阶段。"},{"id":"t0635","chapterId":"c23","chapterJa":"プロジェクトマネジメント","chapterZh":"项目管理","termJa":"プロジェクトの体制","termZh":"项目组织体制","english":"Project Structure","reading":"ぷろじぇくとのたいせい","breadcrumb":"6 プロジェクトマネジメント6-1 プロジェクトマネジメント","explanationJa":"プロジェクトを円滑に進めるための組織や役割の配置を指す。具体的には、プロジェクトマネージャーやチームメンバー、関係者の役割分担やコミュニケーションの流れを明確にすることで、目標達成に向けた効果的な作業体制を築く。プロジェクトの体制を整えることで、各メンバーが自分の役割を理解し、協力しやすくなる。例えば、開発プロジェクトでは、開発者、デザイナー、テスターの役割が明確にされ、必要なタスクが分担されることで、プロジェクトがスムーズに進む。これにより、リスク管理や問題解決も効果的に行えるようになる。","explanationZh":"为执行项目而建立的角色、职责、报告关系和团队结构。应明确项目发起人、项目经理、团队成员和相关方的权限与责任，以避免责任不清。"},{"id":"t0636","chapterId":"c23","chapterJa":"プロジェクトマネジメント","chapterZh":"项目管理","termJa":"プロジェクトの自己管理","termZh":"项目自我管理","english":"Project Self-management","reading":"ぷろじぇくとのじこかんり","breadcrumb":"6 プロジェクトマネジメント6-1 プロジェクトマネジメント","explanationJa":"プロジェクトが円滑に進行するために、問題を見つけて適切に対処する一連のプロセスを指す。具体的には、変更管理では計画の変更が必要な場合に適切な手続きを行い、問題発見では発生する可能性のある課題を早期に察知することが求められる。問題報告は、発見した問題を関係者に伝え、対策立案ではその問題に対処するための具体的な方法を考える。また、文書化はプロジェクトの各段階を記録し、情報共有や振り返りに活用する重要な手段である。これらの活動は、プロジェクトの成功に向けて重要な役割を果たす。","explanationZh":"项目团队在既定目标和治理边界内自主安排工作、协调任务、解决问题和持续改进的管理方式。需要透明的信息共享、明确责任和团队协作能力。"},{"id":"t0637","chapterId":"c24","chapterJa":"プロジェクトの統合","chapterZh":"项目整合","termJa":"プロジェクト憲章の作成","termZh":"制定项目章程","english":"Project Charter Creation","reading":"ぷろじぇくとけんしょうのさくせい","breadcrumb":"6 プロジェクトマネジメント6-2 プロジェクトの統合","explanationJa":"プロジェクトの目的や範囲、関与者の役割を明確に定義するプロセスである。この文書はプロジェクトの基本的な指針となり、全関係者が共通の理解を持つために必要不可欠である。具体的には、プロジェクトの背景、目標、スケジュール、資源、リスクなどが盛り込まれる。たとえば、新製品の開発プロジェクトにおいて、プロジェクト憲章があれば、チームメンバーが何を達成すべきかを理解しやすくなる。さらに、ステークホルダーとのコミュニケーションが円滑になり、プロジェクトの成功に向けた一体感が生まれる。これにより、適切な意思決定や進捗管理が可能となる。","explanationZh":"在项目启动阶段形成正式授权项目存在并明确高层目标、范围边界、主要相关方和项目经理权限的文件。项目章程为后续详细规划提供基础。"},{"id":"t0638","chapterId":"c24","chapterJa":"プロジェクトの統合","chapterZh":"项目整合","termJa":"プロジェクト作業の管理","termZh":"项目工作管理","english":"Project Work Management","reading":"ぷろじぇくとさぎょうのかんり","breadcrumb":"6 プロジェクトマネジメント6-2 プロジェクトの統合","explanationJa":"プロジェクトを円滑に進めるために行う計画、実行、監視、制御のプロセス全体を指す。具体的には、プロジェクトの目的達成のために、タスクの割り当てやスケジュールの設定、リソースの配分などが含まれる。たとえば、ソフトウェア開発プロジェクトでは、開発者に具体的な作業を割り当て、期限内に成果物を完成させるための進捗管理が求められる。これにより、チーム全員が目標に向かって効率よく作業を進め、プロジェクトが時間通りに完了することを目指す。適切な管理手法を用いることで、問題の早期発見やリスクの低減が可能となり、プロジェクト成功の可能性が高まる。","explanationZh":"对项目计划中的工作进行组织、执行、跟踪和控制，确保成果按要求产生。包括协调人员和资源、处理问题、管理变更并报告进展。"},{"id":"t0639","chapterId":"c24","chapterJa":"プロジェクトの統合","chapterZh":"项目整合","termJa":"プロジェクトフェーズ又はプロジェクトの終結","termZh":"项目阶段或项目收尾","english":"Project Phase or Project Closure","reading":"ぷろじぇくとふぇーずまたはぷろじぇくとのしゅうけつ","breadcrumb":"6 プロジェクトマネジメント6-2 プロジェクトの統合","explanationJa":"プロジェクトの進行過程を段階的に分けたり、プロジェクトの完了を指す概念である。プロジェクトは通常、立ち上げ、計画、実行、監視、そして終了の各フェーズに分かれる。この中で特にプロジェクトの終結は、成果物の納品、成果の評価、学習の共有などが行われ、プロジェクトに関与したすべてのステークホルダーが結果を確認する機会となる。これは、次回のプロジェクトに向けた改善点を見つける重要なステップでもあり、効率的なプロジェクト管理には欠かせない要素である。","explanationZh":"在阶段或整个项目结束时，确认交付物完成与验收、关闭合同、移交成果、释放资源并整理记录的过程。还应总结经验并处理未完成事项。"},{"id":"t0640","chapterId":"c24","chapterJa":"プロジェクトの統合","chapterZh":"项目整合","termJa":"得た教訓の収集","termZh":"收集经验教训","english":"Gathering Lessons Learned","reading":"えたきょうくんのしゅうしゅう","breadcrumb":"6 プロジェクトマネジメント6-2 プロジェクトの統合","explanationJa":"プロジェクトや業務の遂行中に得た経験や知識を整理し、将来に活かすためのプロセスである。具体的には、成功事例や失敗事例から何を学び、どのように改善できるかを明確にすることが目的である。たとえば、あるプロジェクトで発生した問題を振り返り、原因を分析することで、次回のプロジェクトにおいて同じミスを避ける手法が見つかる。このプロセスは、企業や団体が成長していくために必要不可欠であり、組織の知識蓄積にも貢献する。得た教訓を収集することで、チーム内でのスムーズな意思決定が促進され、業務の効率化が図られる。","explanationZh":"把项目中成功做法、问题、原因和改进建议系统记录并共享的活动。经验教训可在项目全过程持续收集，并在收尾时整理，为未来项目提供参考。"},{"id":"t0641","chapterId":"c24","chapterJa":"プロジェクトの統合","chapterZh":"项目整合","termJa":"ベースライン","termZh":"基准（Baseline）","english":"Baseline","reading":"","breadcrumb":"6 プロジェクトマネジメント6-2 プロジェクトの統合","explanationJa":"プロジェクトや作業において、進捗や成果を評価するための基準や参照点を示すものである。特にプロジェクト管理においては、スケジュールやコスト、品質の基準が設定され、この基準と実際の進捗を比較することで、問題点を特定しやすくなる。例えば、予定していた納期がベースラインとして設定されると、その日付を基にして進捗を管理し、遅延があれば迅速に対策を講じることが可能である。また、ベースラインは通常、プロジェクトの初期段階で決定され、進行中に変更があった場合には新たに更新されることがある。これにより、計画と実績の差を視覚化し、効果的な管理を実現することができる。","explanationZh":"经过正式批准、作为后续绩效测量和变更控制依据的计划版本。常见包括范围基准、进度基准和成本基准，修改通常需要经过规定的变更流程。"},{"id":"t0642","chapterId":"c25","chapterJa":"プロジェクトのステークホルダ","chapterZh":"项目干系人","termJa":"ステークホルダの特定","termZh":"识别相关方","english":"Stakeholder Identification","reading":"すてーくほるだのとくてい","breadcrumb":"6 プロジェクトマネジメント6-3 プロジェクトのステークホルダ","explanationJa":"プロジェクトや業務に関連する利害関係者を明らかにするプロセスである。ステークホルダは、プロジェクトの成功に影響を与える個人や組織を指し、顧客、従業員、投資家、規制当局などが含まれる。この特定作業により、誰がプロジェクトに関与し、どのような期待や要求を持っているのかを把握することができる。たとえば、新しい製品を開発する際には、その製品を使用する顧客や、資金を提供する投資家の意見を考慮することが重要である。こうした利害関係者のニーズを理解することで、コストや時間を節約し、プロジェクトの成功率を高めることが可能になる。","explanationZh":"确定可能影响项目、受到项目影响或认为自己会受到影响的个人、群体和组织，并分析其利益、影响力和期望。识别结果是制定沟通和参与策略的基础。"},{"id":"t0643","chapterId":"c25","chapterJa":"プロジェクトのステークホルダ","chapterZh":"项目干系人","termJa":"ステークホルダのマネジメント","termZh":"相关方管理","english":"Stakeholder Management","reading":"","breadcrumb":"6 プロジェクトマネジメント6-3 プロジェクトのステークホルダ","explanationJa":"プロジェクトや事業に影響を与える利害関係者を特定し、その期待やニーズを理解し、コミュニケーションを図るプロセスである。このプロセスでは、関与する全ての関係者、例えば顧客、取引先、社員、役員などを調査し、プロジェクトの進行において彼らが持つ視点や影響を考慮することが重要である。ステークホルダとの良好な関係を築くことで、協力的な雰囲気が生まれ、プロジェクトが円滑に進む可能性が高まる。また、利害関係者が不満を持っている場合、その問題を早期に解決することが求められるため、定期的なフィードバックや情報共有も不可欠である。これにより、プロジェクト全体が成功するための基盤が築かれる。","explanationZh":"通过分析相关方需求和影响力，规划并实施沟通、参与和期望管理的过程。目标是获得必要支持、减少阻力并及时处理冲突和变化。"},{"id":"t0644","chapterId":"c26","chapterJa":"プロジェクトのスコープ","chapterZh":"项目范围","termJa":"スコープの定義","termZh":"范围定义","english":"Scope Definition","reading":"すこーぷのていぎ","breadcrumb":"6 プロジェクトマネジメント6-4 プロジェクトのスコープ","explanationJa":"プロジェクトや業務の範囲を明確にするための過程である。スコープを設定することで、どの作業が含まれるのか、または除外されるのかを特定することができ、プロジェクトの成功に向けた計画が立てやすくなる。具体的には、スコープの定義には目標、成果物、作業のプロセス、さらには関与するステークホルダーの要件などが含まれる。例えば、ソフトウェア開発プロジェクトにおいて、新機能の実装やテストの範囲を定めることが、スコープの定義に該当する。これにより、プロジェクトチームはリソースを適切に配分し、時間内に成果物を完成させるための指針が得られる。スコープが不明確だと、プロジェクトの遅延やコスト超過を招くこともあるため、慎重な設定が求められる。","explanationZh":"明确项目要交付的产品、服务和工作边界，说明包括什么和不包括什么。清晰的范围有助于形成验收标准并防止未经控制的范围蔓延。"},{"id":"t0645","chapterId":"c26","chapterJa":"プロジェクトのスコープ","chapterZh":"项目范围","termJa":"WBSの作成","termZh":"创建工作分解结构（WBS）","english":"Work Breakdown Structure Creation","reading":"だぶるびーえすのさくせい","breadcrumb":"6 プロジェクトマネジメント6-4 プロジェクトのスコープ","explanationJa":"WBS（Work Breakdown Structure）は、プロジェクトのスコープや成果物を階層的に分解し、管理可能な小さな単位（ワークパッケージ）まで具体化する手法である。最上位にプロジェクト全体を置き、その下に成果物・フェーズ・作業群を分解していくため、見た目は樹形図に近い。\n\nWBSを作ることで、作業漏れを防ぎ、担当者の割当て、工数・コストの見積り、スケジュール作成、進捗管理の土台を作ることができる。WBSは「いつ実施するか」を示すガントチャートとは異なり、主目的は「何を実施すべきか」を構造化することである。","explanationZh":"WBS（工作分解结构）把项目范围或交付成果按层级逐步分解，直到形成可估算、可分配、可管理的“工作包”。其外观通常接近树状结构：最上层是整个项目，向下依次拆分为阶段、交付物、工作组和具体工作包。\n\nWBS有助于防止工作遗漏，并为责任分配、工期/成本估算、制定进度计划和进度跟踪提供基础。WBS回答的是“要做什么”，甘特图主要回答“什么时候做、进度到哪里”。"},{"id":"t0646","chapterId":"c26","chapterJa":"プロジェクトのスコープ","chapterZh":"项目范围","termJa":"活動の定義","termZh":"活动定义","english":"Definition of Activities","reading":"かつどうのていぎ","breadcrumb":"6 プロジェクトマネジメント6-4 プロジェクトのスコープ","explanationJa":"特定のプロジェクトやビジネスの範囲に含まれるプロセスや行動を明確にすることである。活動は、目的を達成するために実施される一連の具体的な行動を指し、一般的には計画、実行、監視、そして報告といったフェーズが含まれる。たとえば、製品開発の活動には、リサーチ、デザイン、製造、テストなどが含まれる。これにより、プロジェクトの進捗や成果を測定しやすくなり、関与するメンバーやステークホルダーが役割を理解する助けとなる。また、明確なリソースの効果的な分配や調整を行うためにも重要である。","explanationZh":"根据工作包进一步确定完成项目成果所需的具体活动。活动应足够明确，以便进行依赖关系、工期、资源和进度安排。"},{"id":"t0647","chapterId":"c26","chapterJa":"プロジェクトのスコープ","chapterZh":"项目范围","termJa":"スコープの管理","termZh":"范围管理","english":"Scope Management","reading":"すこーぷのかんり","breadcrumb":"6 プロジェクトマネジメント6-4 プロジェクトのスコープ","explanationJa":"プロジェクトにおいて実施すべき活動や成果物を明確に定義し、管理するプロセスである。スコープ管理は、プロジェクトの成功に欠かせない要素であり、何が含まれるのか、または含まれないのかを事前に理解することで、無駄を省き、効率的な進行を目指す。具体的には、プロジェクトの範囲を定義し、変更を管理するための計画を策定し、進捗を追跡することが含まれる。これにより、予期しない追加作業や要求が発生することを防ぎ、資源の最適化を図ることができる。この管理は、成果物や作業の信頼性を向上させ、顧客とのコミュニケーションを円滑に進めることにも寄与する。","explanationZh":"规划、定义、确认和控制项目范围的过程，确保项目只完成实现目标所必需的工作。对范围变更应进行影响分析和正式控制。"},{"id":"t0648","chapterId":"c27","chapterJa":"プロジェクトの資源","chapterZh":"项目资源","termJa":"資源の対象群","termZh":"资源管理领域","english":"Resource Pool","reading":"しげんのたいしょうぐん","breadcrumb":"6 プロジェクトマネジメント6-5 プロジェクトの資源","explanationJa":"プロジェクトに必要なリソースを管理するためのグループを指す。具体的には、プロジェクトを成功させるために必要な人材や設備、資金などが含まれる。例えば、プロジェクトチームを編成する際、各メンバーのスキルや経験、役割などを考慮して、最適な人員配置を行うことが重要である。また、資源の見積もりを行うことで、必要な資源の量や調達タイミングを把握し、プロジェクトの進行がスムーズに行えるようにする。これにより、リソースを最大限活用できると同時に、無駄を減らし効率的なプロジェクト運営が可能になる。","explanationZh":"项目管理中针对人员、设备、材料、设施等资源进行规划、获取、分配和控制的一组活动。目标是在需要的时间获得适量资源并高效使用。"},{"id":"t0649","chapterId":"c28","chapterJa":"プロジェクトの時間","chapterZh":"项目进度与时间","termJa":"時間の対象群","termZh":"时间／进度管理领域","english":"Time Management","reading":"じかんのたいしょうぐん","breadcrumb":"6 プロジェクトマネジメント6-6 プロジェクトの時間","explanationJa":"プロジェクトマネジメントにおいて、プロジェクトの遂行に必要な活動を効果的に管理するための手法である。具体的には、まず活動の順序付け（活動の流れや依存関係を定める）を行い、次に活動期間の見積り（各活動にかかる時間を予測する）を通じて必要なリソースを明確にする。最後に、スケジュールの作成（全体の計画をスケジュール化し、進捗を把握できるようにする）を行うことで、プロジェクトを円滑に進める基盤を築く。これにより、予定通りに成果物を納品するための時間管理が可能となる。","explanationZh":"围绕项目活动顺序、工期估算、进度计划制定和进度控制的一组管理活动。其目标是使项目在约定时间内完成。"},{"id":"t0650","chapterId":"c28","chapterJa":"プロジェクトの時間","chapterZh":"项目进度与时间","termJa":"活動リスト","termZh":"活动清单","english":"Activity List","reading":"かつどうりすと","breadcrumb":"6 プロジェクトマネジメント6-6 プロジェクトの時間","explanationJa":"プロジェクト管理において実施すべき作業やタスクを一覧化したものである。このリストには、各タスクの名称や説明、開始日や終了日、責任者などの情報が含まれる。活動リストを作成することで、プロジェクトの全体像を把握し、効率的に作業を進めることが可能となる。また、タスクの進捗状況を追跡するためにも有用であり、問題点が発生した際には、早期に適切な対策を講じることが求められる。これは、プロジェクトの成功に向けた重要なアウトプットとなり、チーム内のコミュニケーションや協力を促進する手助けとなる。","explanationZh":"列出完成项目工作包所需全部活动及其必要属性的清单。它是建立活动顺序、估算资源和工期以及编制进度计划的基础。"},{"id":"t0651","chapterId":"c28","chapterJa":"プロジェクトの時間","chapterZh":"项目进度与时间","termJa":"PERT","termZh":"计划评审技术（PERT）","english":"Program Evaluation and Review Technique","reading":"ぱーと","breadcrumb":"6 プロジェクトマネジメント6-6 プロジェクトの時間","explanationJa":"PERT（Program Evaluation and Review Technique）は、プロジェクトの各活動の依存関係と所要時間をネットワーク図で表し、全体工期や重要な活動経路を分析する手法である。活動の順序関係を明確にし、「どの作業が遅れるとプロジェクト全体が遅れるか」を把握するのに向いている。\n\n古典的PERTでは、楽観時間a、最可能時間m、悲観時間bの3点見積りを使い、期待時間を (a＋4m＋b)÷6 で求める。ネットワーク上で開始から終了までの所要時間が最も長く、余裕時間が0となる経路がクリティカルパスである。\n\n【試験ポイント】PERTは依存関係・クリティカルパスの分析、ガントチャートは時間軸上の進捗・予定の見える化に向く。","explanationZh":"PERT（计划评审技术）用网络图表示项目活动之间的先后依赖关系和所需时间，用于分析总体工期以及哪些活动会直接影响项目完成日期。它特别适合判断“哪项任务一旦延迟，就会导致整个项目延期”。\n\n经典PERT采用三点估算：乐观时间a、最可能时间m、悲观时间b，期望时间为 (a＋4m＋b)÷6。网络中从开始到结束“总耗时最长且通常总时差为0”的路径称为关键路径（Critical Path）。\n\n【考试速记】PERT重点看“依赖关系、关键路径”；甘特图重点看“时间轴、计划与进度”。"},{"id":"t0920","chapterId":"c28","termJa":"ガントチャート","termZh":"甘特图","english":"Gantt Chart","reading":"がんとちゃーと","breadcrumb":"SG補足｜プロジェクトの時間・図表","explanationJa":"ガントチャートは、縦軸に作業項目、横軸に時間（日・週・月など）を取り、各作業の開始から終了までを横棒で表すスケジュール図である。計画期間と実績を重ねて表示すれば、遅延や進捗状況を直感的に把握できる。\n\n【向いている場面】\n・各作業をいつ開始し、いつ終了するかを一覧したい\n・担当者や複数作業の並行状況を確認したい\n・予定と実績の差、遅延を可視化したい\n\n【他図との違い】ガントチャートは“時間軸上の見える化”が得意。作業間の依存関係やクリティカルパスを厳密に分析するならPERT/アロー・ダイヤグラムの方が向いている。","explanationZh":"甘特图以纵轴列出任务，以横轴表示日期/周/月，用横条表示每项任务的开始、结束和持续时间。把计划与实际进度叠加后，可以直观看出延期和完成情况。\n\n【适用场景】\n• 想快速查看每项任务什么时候开始、什么时候结束\n• 查看多项任务是否并行、人员或阶段安排\n• 对比计划进度与实际进度，发现延期\n\n【与其他图区别】甘特图最擅长“按时间轴展示进度”；如果题目重点是任务依赖、关键路径，则PERT/箭线图更合适。","chapterJa":"プロジェクトの時間","chapterZh":"项目进度与时间"},{"id":"t0921","chapterId":"c28","termJa":"クリティカルパス","termZh":"关键路径","english":"Critical Path","reading":"くりてぃかるぱす","breadcrumb":"SG補足｜プロジェクトの時間・PERT","explanationJa":"クリティカルパスは、プロジェクトの開始から完了までを結ぶ作業経路のうち、合計所要時間が最も長く、プロジェクト全体の最短完成時期を決める経路である。通常、クリティカルパス上の活動は全余裕時間（トータルフロート）が0であり、その活動が1日遅れると全体完了も1日遅れる。\n\n【試験ポイント】「最も長い経路」を選ぶ。最短経路ではない。短縮したい場合はクリティカルパス上の作業を短縮する必要がある。","explanationZh":"关键路径是从项目开始到结束的所有任务路径中“总持续时间最长”的路径，它决定项目能够完成的最早日期。通常关键路径上的活动总时差为0，因此其中某项活动延迟1天，整个项目通常也会延迟1天。\n\n【考试重点】关键路径选“总耗时最长的路径”，不是最短路径。如果要压缩总工期，应优先缩短关键路径上的活动。","chapterJa":"プロジェクトの時間","chapterZh":"项目进度与时间"},{"id":"t0652","chapterId":"c29","chapterJa":"プロジェクトのコスト","chapterZh":"项目成本","termJa":"コストの管理","termZh":"成本管理","english":"Cost Management","reading":"こすとのかんり","breadcrumb":"6 プロジェクトマネジメント6-7 プロジェクトのコスト","explanationJa":"プロジェクトやビジネス活動における費用の計画、追跡、調整を行うプロセスである。これにより、予算の範囲内での運営を維持し、経済的な効率を最大化することが目的となる。見積もり、予算設定、実績追跡、クローズアウトのプロセスから構成される。例えば、プロジェクトが始まる前に必要な資源や作業に基づいて予算を設定し、進行中に実際の支出と比べて分析することで、必要に応じて調整を行うことが重要である。このプロセスは、企業の財務健康を保ちながら、資源の最適化を図るための戦略的な手段であり、無駄をなくすための計画的な取り組みが求められる。","explanationZh":"对项目成本进行估算、预算、筹资和控制的管理活动。通过与成本基准比较实际支出和预测，及时发现偏差并采取纠正措施。"},{"id":"t0653","chapterId":"c29","chapterJa":"プロジェクトのコスト","chapterZh":"项目成本","termJa":"コストベースライン","termZh":"成本基准","english":"Cost Baseline","reading":"","breadcrumb":"6 プロジェクトマネジメント6-7 プロジェクトのコスト","explanationJa":"プロジェクトの予算管理における基準となるコストの計画値である。これは、プロジェクトのライフサイクル全体を通じてかかると予想される費用を明確に示すために用いられ、その推移を追跡することが可能である。具体的には、プロジェクト開始時に設定され、以降のすべてのコストと実際の支出を比較するための基準となる。これにより、プロジェクトが予算内で進行しているか、あるいは超過しているかを把握しやすくする。納期の管理やリソース配分、リスク対策にも重要な役割を果たし、プロジェクトの成功につながるため規模や内容に応じて適切に策定することが求められる。","explanationZh":"经批准的项目分阶段预算，是衡量和控制成本绩效的基准。通常不随意修改，批准的变更应按变更控制流程反映到基准中。"},{"id":"t0654","chapterId":"c30","chapterJa":"プロジェクトのリスク","chapterZh":"项目风险","termJa":"プロジェクトの全体リスクと個別リスク","termZh":"项目整体风险与个别风险","english":"Overall and Individual Project Risks","reading":"ぷろじぇくとのぜんたいりすくとこべつりすく","breadcrumb":"6 プロジェクトマネジメント6-8 プロジェクトのリスク","explanationJa":"プロジェクトにおいて発生する可能性のある問題や不確実性の評価方法を指す。全体リスクは、プロジェクト全体に影響を与える要因を包括的に捉えており、すべてのリスク要素を考慮した上でプロジェクトの成功に対する脅威を評価する。一方、個別リスクは特定の作業や要素に起因するリスクで、各課題や活動ごとに詳細に分析される。この二つを区別して考えることで、リスク管理が効果的に行える。例えば、全体リスクとしては予算超過の可能性が挙げられ、個別リスクとしては特定の作業における技術的な問題が考えられる。リスクを明確にし、適切な対策を講じることが成功に繋がる。","explanationZh":"个别风险是可能影响某个项目目标的具体不确定事件；整体项目风险是所有不确定性对项目整体结果的综合影响。项目应同时管理两种层面的风险。"},{"id":"t0655","chapterId":"c30","chapterJa":"プロジェクトのリスク","chapterZh":"项目风险","termJa":"リスクの対象群","termZh":"风险管理领域","english":"Risk Target Group","reading":"りすくのたいしょうぐん","breadcrumb":"6 プロジェクトマネジメント6-8 プロジェクトのリスク","explanationJa":"プロジェクトにおいて考慮すべきリスクの種類やカテゴリを示す用語である。この群には、リスクの特定、リスクの評価、リスクへの対応、リスクの管理といったプロセスが含まれる。リスクの特定は、潜在的なリスクを洗い出すことから始まり、次にリスクの評価では、それらのリスクがプロジェクトに与える影響の大きさや発生可能性を分析する。リスクへの対応は、特定したリスクに対してどのように対策を講じるかを決定し、最終的にリスクの管理では、リスク対策の効果を監視し、必要に応じて改善を行う。このようにプロジェクトを成功に導くための重要な要素といえる。","explanationZh":"用于识别、分析、应对、监控项目风险的一组管理活动。目标是提高正面风险机会的实现概率，并降低负面风险的概率和影响。"},{"id":"t0656","chapterId":"c31","chapterJa":"プロジェクトの品質","chapterZh":"项目质量","termJa":"品質管理の遂行","termZh":"执行质量管理","english":"Quality Management Execution","reading":"ひんしつかんりのすいこう","breadcrumb":"6 プロジェクトマネジメント6-9 プロジェクトの品質","explanationJa":"製品やサービスが求められる品質基準を満たすための一連の活動を指す。このプロセスには、計画、実行、評価、改善のサイクルが含まれる。具体的には、初めに品質目標を設定し、それを達成するための戦略や手段を決定する。その後、実際に業務を行い、成果を測定して問題点を洗い出し、必要な改善策を講じることで、品質を持続的に向上させていく。例えば、製造業においては、生産工程での検査やフィードバックループを設けることで、製品の欠陥を早期に発見し、顧客満足を高めることが可能となる。このように、組織の信頼性を築くために不可欠な要素である。","explanationZh":"把组织的质量政策和项目质量要求转化为具体质量活动，并通过过程改进确保项目采用适当方法的过程。它关注预防缺陷，而不仅是最终检查。"},{"id":"t0657","chapterId":"c31","chapterJa":"プロジェクトの品質","chapterZh":"项目质量","termJa":"検査報告書","termZh":"检查报告","english":"Inspection Report","reading":"けんさほうこくしょ","breadcrumb":"6 プロジェクトマネジメント6-9 プロジェクトの品質","explanationJa":"特定の製品やサービスについて行われた検査の結果を記録した文書である。例えば、建設現場での資材検査を行った場合、その結果をまとめたものが検査報告書になる。この報告書には、検査日、検査を行った対象、検査基準、結果、問題点などの情報が含まれ、関係者が理解しやすい形で提示される。品質管理や安全性の確認に役立ち、将来の改善やトラブル防止に貢献する重要な資料となる。","explanationZh":"记录检查对象、方法、结果、不符合项和判定结论的文档。它为验收、质量改进和问题追踪提供证据，应保持可追溯性。"},{"id":"t0658","chapterId":"c32","chapterJa":"プロジェクトの調達","chapterZh":"项目采购","termJa":"調達の対象群","termZh":"采购管理领域","english":"Procurement Item Group","reading":"ちょうたつのたいしょうぐん","breadcrumb":"6 プロジェクトマネジメント6-10 プロジェクトの調達","explanationJa":"プロジェクトにおける調達活動を具体的に分類したものである。この対象群は主に「調達の計画」「供給者の選定」「調達の運営管理」の三つに分けられる。調達の計画は、何を、いつ、どのように調達するかを明確にし、予算やスケジュールを策定するプロセスである。次に、供給者の選定では、入札や評価を通じて最適な供給者を選び、質の高い資源を確保する。最後に調達の運営管理は、調達活動が円滑に進むよう監視し、必要に応じて調整を行う重要な段階である。これにより、プロジェクトの成功に向けて必要な資源やサービスを適切に確保することが可能となる。","explanationZh":"围绕从外部取得产品、服务或成果进行规划、供应商选择、合同管理和采购关闭的活动。需要管理成本、质量、交付、合同和供应商风险。"},{"id":"t0659","chapterId":"c33","chapterJa":"プロジェクトのコミュニケーション","chapterZh":"项目沟通","termJa":"コミュニケーションのマネジメント","termZh":"沟通管理","english":"Communication Management","reading":"","breadcrumb":"6 プロジェクトマネジメント6-11 プロジェクトのコミュニケーション","explanationJa":"情報を効率的に交換し、理解を深めるためのプロセスや活動を管理することを指す用語である。具体的には、組織内外の関係者とのコミュニケーションを計画し、実行し、評価することが含まれる。このプロセスには、メッセージの設計、チャンネルの選定、フィードバックの収集が含まれ、円滑な情報の流れを実現するために重要である。たとえば、プロジェクトの進捗状況をチーム全体に伝えるための定期的なミーティングや報告書の作成は、コミュニケーションのマネジメントにおける重要な活動であり、情報の透明性を確保し、誤解を防ぐ役割を果たす。このように、効果的な組織の成長や成功に寄与するものである。","explanationZh":"规划、生成、收集、分发、保存和管理项目信息，确保正确的信息在适当时间到达适当相关方。沟通方式应根据内容、紧急程度和受众选择。"},{"id":"t0660","chapterId":"c33","chapterJa":"プロジェクトのコミュニケーション","chapterZh":"项目沟通","termJa":"双方向コミュニケーション","termZh":"双向沟通","english":"Two-Way Communication","reading":"そうほうこうこみゅにけーしょん","breadcrumb":"6 プロジェクトマネジメント6-11 プロジェクトのコミュニケーション","explanationJa":"情報が双方向に流れるやり取りのことを指す用語である。これは、情報の発信者と受信者が互いにメッセージを送受信し合うことによって成り立つ。例えば、電話やビデオ会議では、話した内容を相手が反応することで、より深い理解や意見交換が行われる。対照的に、一方向コミュニケーションでは、情報が一方的に提供されるため、意見のフィードバックが得られにくい。双方向コミュニケーションを活用することで、意見の共有や問題解決が効率的になり、団体やチームの協力を促進することができる。","explanationZh":"发送者和接收者可以实时或近实时交换信息并获得反馈的沟通方式。例如会议、电话、视频会议等，适合需要讨论、确认和解决复杂问题的场景。"},{"id":"t0661","chapterId":"c33","chapterJa":"プロジェクトのコミュニケーション","chapterZh":"项目沟通","termJa":"プッシュ型コミュニケーション","termZh":"推送式沟通","english":"Push Communication","reading":"ぷっしゅがたこみゅにけーしょん","breadcrumb":"6 プロジェクトマネジメント6-11 プロジェクトのコミュニケーション","explanationJa":"情報やメッセージが一方的に受信者に送信されるコミュニケーションの方法である。例えば、メールやニュースレターが代表例で、必要なタイミングで受信者が情報を取りに行くのではなく、送信者が直接届ける。この方法は、迅速に情報を伝えることができるため、ビジネスにおいて特に有効である。また、イベントの通知や重要なアラートなど、受信者が見逃してはいけない情報の配信の際に多く利用される。しかし、受信者によっては情報過多となることもあるため、適切に利用することが重要である。","explanationZh":"把信息主动发送给指定接收者的方式，例如电子邮件、报告和通知。它能确保信息被发送，但不能保证接收者已经阅读或理解。"},{"id":"t0662","chapterId":"c33","chapterJa":"プロジェクトのコミュニケーション","chapterZh":"项目沟通","termJa":"プル型コミュニケーション","termZh":"拉取式沟通","english":"Pull Communication","reading":"ぷるがたこみゅにけーしょん","breadcrumb":"6 プロジェクトマネジメント6-11 プロジェクトのコミュニケーション","explanationJa":"情報を受け取る側が必要に応じて情報を取得する方式を指す。例えば、Webサイトやメールマガジンなどは、受け手が自らアクセスして情報を得るため、プル型の一例である。この方式のメリットは、受け手が自分のペースで情報を確認できる点にある。また、必要な時に必要な情報を集めることができるため、情報の過多を避けることにもつながる。これに対して、プッシュ型コミュニケーションは、情報が自動的に送られる方式であり、両者は状況に応じて使い分けられることが多い。プル型は、特に自分で情報を管理したいユーザーにとって利用しやすい手段である。","explanationZh":"把大量信息放在知识库、门户等位置，由需要的人主动访问获取的方式。适合受众较多或信息量大的场景，但依赖用户主动查询。"},{"id":"t0663","chapterId":"c33","chapterJa":"プロジェクトのコミュニケーション","chapterZh":"项目沟通","termJa":"電子メール","termZh":"电子邮件","english":"Electronic Mail","reading":"でんしめーる","breadcrumb":"6 プロジェクトマネジメント6-11 プロジェクトのコミュニケーション","explanationJa":"インターネットを利用してメッセージやファイルを送受信するためのサービスである。ユーザーは、テキストメッセージ、画像、文書などのデータを相手に迅速に伝えることができ、文字情報に加えて添付ファイルを通じて多様な情報をやり取りできるのが特徴である。例えば、仕事の連絡や友人とのコミュニケーションにおいて、電子メールは広く利用されている。また、特定のアドレスに対して直接送信されるため、プライバシーを保ちながら効率的に情報を共有できる。そのため、ビジネスや日常生活において欠かせないツールとなっている。","explanationZh":"通过网络发送和接收电子消息的通信方式。项目中常用于正式通知和记录，但敏感信息应注意加密、收件人确认和附件管理。"},{"id":"t0664","chapterId":"c33","chapterJa":"プロジェクトのコミュニケーション","chapterZh":"项目沟通","termJa":"ボイスメール","termZh":"语音邮件","english":"Voicemail","reading":"","breadcrumb":"6 プロジェクトマネジメント6-11 プロジェクトのコミュニケーション","explanationJa":"音声メッセージを録音し、受取人が後で聴くことができる通信サービスである。このシステムでは、電話をかけた相手が応答しない場合や、話している人と繋がらない場合にメッセージを残すことが可能である。たとえば、ビジネスシーンでは、顧客が担当者に伝えたい重要な情報を音声メッセージとして残すことがある。受取人は、後でボイスメールにアクセスし、メッセージを確認することができるため、連絡がとれなくても重要な情報を受け取る手段となる。これにより、コミュニケーションがより効率的になり、時間に制約のある状況でも適切に対応できる。","explanationZh":"把电话语音留言以数字形式保存，供接收者之后收听的通信服务。适合无法实时接听时传递信息，但不适合复杂或高度敏感内容。"},{"id":"t0665","chapterId":"c33","chapterJa":"プロジェクトのコミュニケーション","chapterZh":"项目沟通","termJa":"テレビ会議","termZh":"视频会议","english":"Video Conferencing","reading":"てれびかいぎ","breadcrumb":"6 プロジェクトマネジメント6-11 プロジェクトのコミュニケーション","explanationJa":"遠隔地にいる人同士が映像と音声を通じてコミュニケーションを行う手法である。例えば、仕事の会議や教育の場において、参加者がそれぞれの場所から集まり、リアルタイムで顔を見ながら話し合うことができる。インターネットを介して行われるため、場所を問わずに利用でき、移動の手間や時間を削減できる利点がある。また、資料を画面共有する機能なども備えており、視覚情報を交えた効果的なプレゼンテーションが可能である。特に、リモートワークや国際的なビジネスでの重要性が増している。","explanationZh":"通过网络实时传输音视频，使不同地点人员进行远程会议的沟通方式。使用时应控制会议访问、链接和录制权限，保护敏感会议内容。"},{"id":"t0666","chapterId":"c34","chapterJa":"サービスマネジメント","chapterZh":"服务管理","termJa":"SLA","termZh":"服务级别协议（SLA）","english":"Service Level Agreement","reading":"えすえるえー","breadcrumb":"7 サービスマネジメント7-1 サービスマネジメント","explanationJa":"サービス提供者と顧客との間で合意されたサービスの品質や内容を示す契約である。この契約には、サービスの可用性、応答時間、サポートの提供方式などが具体的に記載されており、サービスが期待通りに提供されることを保証する役割を持つ。たとえば、クラウドサービスを提供する企業が「サーバの稼働率は99.9%を保証する」と記載した場合、これはその企業が顧客に対してどの程度の信頼性を持ってサービスを提供するかを示している。また、SLAに違反した場合の賠償措置や対応方法についても明記されることが多いため、顧客は安心してサービスを利用することができる。このように、SLAはサービスの品質を測る重要な基準となっている。","explanationZh":"服务提供者与客户之间对服务内容、目标水平、测量方法、责任和报告等形成的正式协议。常包含可用率、响应时间、恢复时间等指标以及未达标时的处理机制。"},{"id":"t0667","chapterId":"c34","chapterJa":"サービスマネジメント","chapterZh":"服务管理","termJa":"顧客満足","termZh":"客户满意度","english":"Customer Satisfaction","reading":"こきゃくまんぞく","breadcrumb":"7 サービスマネジメント7-1 サービスマネジメント","explanationJa":"顧客が製品やサービスを利用した際に得られる満足度を示す概念である。顧客満足は企業の成功にとって非常に重要で、顧客の期待に応えたり、超えたりすることで高まる。例えば、顧客が商品の品質に満足したり、カスタマーサポートの対応が良かった場合、顧客満足度は向上する。また、Service Level Agreement（SLA）という契約においても、期待されるサービスレベルが明確に定められ、それを満たすことが顧客満足に繋がる。顧客満足が高ければリピート率や紹介が増え、企業の信頼性や成長にも寄与するため、重要な指標となっている。","explanationZh":"客户对实际获得的服务与其期望相比所形成的评价。可通过调查、投诉、续约率和反馈等衡量，是评价服务质量的重要结果指标。"},{"id":"t0668","chapterId":"c34","chapterJa":"サービスマネジメント","chapterZh":"服务管理","termJa":"サービス時間","termZh":"服务时间","english":"Service Time","reading":"さーびすじかん","breadcrumb":"7 サービスマネジメント7-1 サービスマネジメント","explanationJa":"特定のサービスやシステムが正常に機能している時間を指す。これは、サービスレベルアグリーメント（SLA）において、サービス提供者が顧客に対して約束する重要な指標の一つである。システムが稼働している時間を基準にし、メンテナンスや障害による停止時間を除外して計算される。たとえば、クラウドサービス提供者は、月間99.9%のサービス時間を保証することがあり、これはサービスが稼働している時間が非常に高いことを意味する。この指標は、顧客に対してサービスの信頼性を示すものであり、ビジネスの運営や顧客満足度にも大きな影響を与える。","explanationZh":"服务按约定向用户提供或可使用的时间范围，例如工作日9:00至18:00或7×24小时。它是SLA和可用率计算的重要前提。"},{"id":"t0669","chapterId":"c34","chapterJa":"サービスマネジメント","chapterZh":"服务管理","termJa":"応答時間","termZh":"响应时间","english":"Response Time","reading":"おうとうじかん","breadcrumb":"7 サービスマネジメント7-1 サービスマネジメント","explanationJa":"システムやサービスがユーザーからの要求に対して応答を返すまでの時間を指す。これは、サービスレベルアグリーメント（SLA）の重要な指標の一つであり、ユーザーが求める情報や機能にどれだけ迅速にアクセスできるかを示すものである。例えば、Webサイトのページが表示されるまでの時間や、アプリケーションがボタン操作に対して反応するまでの時間がこの応答時間にあたる。短いユーザーの満足度を向上させ、ビジネスの競争力を高める重要な要素であるため、多くの企業がこの指標を改善するために取り組んでいる。","explanationZh":"从用户提出请求或事件被记录，到服务方开始响应或系统返回结果所经历的时间。服务管理中应明确测量起点、终点和目标值。"},{"id":"t0670","chapterId":"c34","chapterJa":"サービスマネジメント","chapterZh":"服务管理","termJa":"サービス及びサービスマネジメントシステムのパフォーマンス","termZh":"服务及服务管理体系绩效","english":"Performance of Service and Service Management System","reading":"さーびすおよびさーびすまねじめんとしすてむのぱふぉーまんす","breadcrumb":"7 サービスマネジメント7-1 サービスマネジメント","explanationJa":"サービス提供の状況やその管理システムがどれだけ効果的に機能しているかを評価する指標である。具体的には、サービスの品質、可用性、応答時間などが含まれ、これらはサービスレベルアグリーメント（SLA）によって定義される基準と照らし合わせて測定される。たとえば、ある企業が提供するクラウドサービスの稼働率が99.9%であれば、SLAの基準を満たしているとされる。このようにして、サービスとその管理が適切に行われていることを確認することができ、顧客満足度や業務の信頼性にもつながるため非常に重要である。","explanationZh":"对服务交付结果以及服务管理体系是否实现既定目标的综合表现。可通过SLA达成率、事件处理时间、客户满意度、可用率等指标进行评价。"},{"id":"t0671","chapterId":"c34","chapterJa":"サービスマネジメント","chapterZh":"服务管理","termJa":"サービスマネジメントシステム","termZh":"服务管理体系（SMS）","english":"Service Management System","reading":"","breadcrumb":"7 サービスマネジメント7-1 サービスマネジメント","explanationJa":"サービスの提供や管理を効果的に行うための体系的な枠組みを指す。このシステムは、サービスの計画、実施、維持、および継続的改善を行うためのプロセスや手法を整備するものである。たとえば、企業が顧客に提供するITサービスを管理するために、サポートチームや品質管理部門が連携し、問題のトラッキングやサービスの向上に努める。このように、顧客満足度を高め、業務の効率を向上させるために重要な役割を果たしており、サービスの反復利用や企業の競争力を向上させるためにも欠かせない要素である。\nHOME»用語集»サービスマネジメント»サービスマネジメントシステムの計画及び運用","explanationZh":"组织用于规划、建立、实施、运行、监视、评审、维护和改进服务管理的一整套方针、过程、角色和资源。其目标是持续提供满足要求和创造价值的服务。"},{"id":"t0672","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"サービスの要求事項","termZh":"服务要求","english":"Service Requirements","reading":"さーびすのようきゅうじこう","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"特定のサービスを提供するために必要な条件や基準を示すものである。これには、機能的な要件や性能基準、セキュリティ要件などが含まれ、サービスの利用者や関係者が満足するために必要な要素となる。例えば、特定のWebサービスが「1秒以内の応答時間」を求める場合、この要件はサービスの設計や実装において考慮されるべき基準となる。また、開発プロセスにおいて重要な役割を果たし、効率的な運用を実現するためには欠かせない。これにより、顧客やクライアントのニーズに応じた質の高いサービスの提供が可能となる。","explanationZh":"客户、用户、组织及其他相关方对服务需要满足的功能、质量、可用性、安全、容量和支持等要求。服务设计和SLA应以明确的服务要求为基础。"},{"id":"t0673","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"サービスカタログ","termZh":"服务目录","english":"Service Catalog","reading":"","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"組織が提供するサービスを一覧化した文書やデータベースである。このカタログには、各サービスの詳細情報、料金、利用方法、サービス提供の条件などが含まれている。具体的には、ITサービスにおけるヘルプデスク、ソフトウェアのインストールやサポート、ネットワークサービスなどが例として挙げられる。利用者に対して明確な情報を提供し、サービスを効率的に利用できるよう支援する。また、サービスの管理や改善策を検討するための基盤としても重要な役割を果たす。これにより、組織全体のサービスの品質向上にも寄与するのである。","explanationZh":"以结构化方式列出组织当前提供或可提供的服务、服务说明、对象、负责人和关键条件等信息的资料。它帮助客户和服务人员理解可获得的服务范围。"},{"id":"t0674","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"資産管理","termZh":"资产管理","english":"Asset Management","reading":"しさんかんり","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"企業や個人が所有する資産の効果的な運用と管理を行うプロセスを指す。資産には、不動産、株式、債券、設備などが含まれ、これらの資源を適切に管理することで、リスクを最小限に抑えつつ利益を最大化することが目指される。例えば、企業が所有する機械設備のメンテナンスを計画的に実施することで、稼働率を向上させ、生産効率を高めることができる。また、金融資産のポートフォリオを最適化することも資産管理の一環であり、マーケットの変動に応じた柔軟な戦略が必要とされる。このように、資産管理は経済的な安定を図るための重要な手段である。","explanationZh":"对支持服务的具有价值的资产进行识别、记录、维护、使用和处置的管理。资产可包括硬件、软件、数据、许可证和设备等，目标是实现可控、合规和有效利用。"},{"id":"t0675","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"ライセンスマネジメント","termZh":"许可证管理","english":"License Management","reading":"","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"ソフトウェアやサービスの使用権に関する管理を行うプロセスである。これには、ライセンスの取得、更新、使用状況の監視などが含まれ、企業や組織が適切にソフトウェアを利用するために不可欠である。例えば、あるソフトウェアを使用するために許可を得る際、ライセンス契約を結ぶ必要があり、この契約に基づいて使用することが求められる。適切なライセンスマネジメントを行うことで、不正使用を防ぎ、コストの削減や法的リスクの回避につながる。また、資産を管理する上でも重要な役割を果たし、リソースの最適化に寄与する。","explanationZh":"对软件许可证的采购、分配、使用、续订和回收进行管理。通过掌握实际安装和授权数量，可避免超许可使用、浪费以及合规风险。"},{"id":"t0676","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"構成管理","termZh":"配置管理","english":"Configuration Management","reading":"こうせいかんり","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"ソフトウェアやシステムの構成要素を識別、管理、変更するためのプロセスである。この管理により、システムの整合性と安定性を保つことができ、特に大規模なプロジェクトや運用環境では重要な役割を果たす。具体的には、ソフトウェアのバージョン管理や設定ファイルの保守、依存関係の整理が含まれる。例えば、ソフトウェアの新しいバージョンをリリースする際には、過去の設定やコードを適切に管理し、変更点を追跡することで、システム全体の互換性を維持することが求められる。ITインフラの効率的な運用を支え、予期せぬトラブルの回避にも寄与する。","explanationZh":"识别、记录并控制服务和系统配置项及其属性、关系和版本的管理过程。准确的配置信息有助于变更、事件、问题和影响分析。"},{"id":"t0677","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"構成品目","termZh":"配置项（CI）","english":"Configuration Item","reading":"こうせいひんもく","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムを構成する各要素のことを指す。これには、ハードウェア、ソフトウェア、ドキュメントなどが含まれ、システム全体の管理や運用において重要な役割を果たす。例えば、サーバやアプリケーションソフトウェア、さらにはそれに関連する設定ファイルなどが構成品目として扱われる。構成管理は、これらの品目を追跡し、変更を管理するプロセスであり、品質や効率を向上させるために欠かせない。正確にCIを管理することで、システムの安定性や信頼性を確保し、トラブルシューティングやアップグレード時のリスクを軽減することができる。","explanationZh":"为了提供服务而需要被单独管理和控制的组件，例如服务器、软件、网络设备、文档或云资源。配置管理记录其属性和与其他CI的关系。"},{"id":"t0678","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"サービス満足度","termZh":"服务满意度","english":"Service Satisfaction","reading":"さーびすまんぞくど","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"顧客が受けたサービスに対する満足の度合いを示す指標である。これは、顧客の期待と実際に受けたサービスのギャップを評価するものであり、顧客がどれだけそのサービスに満足しているかを測るための重要な基準となる。たとえば、レストランでは、料理の味や接客の良さが評価され、これらが高く評価されることでサービス満足度が向上する。また、企業はこの指標を用いてサービスの改善や顧客リテンション戦略を立てることができ、顧客のフィードバックをもとに施策を講じることが求められている。これにより、競争力を高めていくことが可能となる。","explanationZh":"用户或客户对服务质量、便利性、支持和结果的满意程度。可通过调查、反馈和投诉等定期测量，并用于持续改进服务。"},{"id":"t0679","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"サービスレベル管理","termZh":"服务级别管理","english":"Service Level Management","reading":"さーびすれべるかんり","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"提供するサービスの品質や性能を確保し、顧客の期待に応えるためのプロセスである。具体的には、サービスの目標や基準を設定し、それを維持するための活動を行う。このプロセスでは、サービスの可用性や応答時間、サポートの迅速さなどが重要な要素となる。たとえば、企業が顧客に対して「24時間以内に問題を解決します」といった約束をする際、この管理が必要となる。また、定期的にサービスのパフォーマンスを評価し、必要に応じて改善策を講じることで、顧客満足度を高めることができる。これはITサービスマネジメントの一環として、サービスの効率性を向上させるために不可欠である。","explanationZh":"与客户协商、约定、监控、报告和改进服务水平的管理过程。通过SLA和服务级别目标把业务期望转化为可测量的服务指标。"},{"id":"t0680","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"サービスレベル目標","termZh":"服务级别目标（SLO）","english":"Service Level Objective","reading":"さーびすれべるもくひょう","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"提供されるサービスの品質やパフォーマンスを示す具体的な基準である。これには、サービスが提供される際の稼働率や応答時間、サポートの可用性などが含まれる。例えば、「99.9%の稼働率を維持する」という目標が設定されると、サービスが常にほぼ正常に稼働していることが求められる。この目標は、サービスプロバイダーと顧客との間で明確に合意されるもので、サービスの期待値を示す重要な指標である。また、問題が発生した際の改善や評価の基準としても活用され、サービス品質を高めるための重要な管理手法の一部である。","explanationZh":"对服务某项性能或质量指标设定的具体目标值，例如月可用率99.9%或重大事件15分钟内响应。SLO可作为SLA中的组成部分或内部管理目标。"},{"id":"t0681","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"供給者管理","termZh":"供应商管理","english":"Supplier Management","reading":"きょうきゅうしゃかんり","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"企業が原材料やサービスを提供する供給者との関係を構築し、維持するプロセスである。この管理は、供給者の選定、契約の締結、パフォーマンスの評価などを含む。例えば、製造業では、部品を供給する業者を選ぶ際に、品質やコスト、納期などの要素を考慮することが必要である。また、信頼できる供給者との関係を築くことで、供給の安定性が高まり、製品の品質向上やコスト削減が期待できる。適切な供給者管理を行うことで、企業はビジネスの競争力を高めることができる。","explanationZh":"对外部供应商的选择、合同、绩效、风险和关系进行持续管理，确保其提供的产品或服务满足组织要求。应关注SLA、安全、合规、持续性和退出安排。"},{"id":"t0682","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"外部供給者","termZh":"外部供应商","english":"External Provider","reading":"がいぶきょうきゅうしゃ","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"企業や組織が自社ではなく外部から商品やサービスを提供する業者のことである。例えば、ITサービスを提供する企業が他の企業に対してシステム開発や運用支援を行う場合、これが外部供給者の一例である。外部供給者を利用することで、企業は自社内のリソースを節約し、専門的な知識や技術を持つパートナーからの支援を得ることができる。このような関係は、コスト削減や業務の効率化に寄与し、競争力を向上させる要因となる。また、外部供給者との効果的なコミュニケーションや管理が重要であり、信頼関係を築くことで、より良い結果が得られる。","explanationZh":"组织之外向其提供产品、资源或服务的实体，例如云服务商、通信运营商和外包公司。组织仍需管理由供应商带来的依赖和风险。"},{"id":"t0683","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"契約","termZh":"合同","english":"Contract","reading":"けいやく","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"二者以上の間で交わされる法的な合意であり、特定の権利や義務を定めるものである。契約は通常、サービスの提供や商品の売買に関する取り決めを含み、その内容には合意した条件や価格、納期などが明記される。例えば、企業が外部の業者に業務を委託する場合、契約を結ぶことによって、双方の責任や権利を明確にすることでトラブルを未然に防ぐことができる。契約は法的に有効であるため、違反があった場合には法的手段を講じることが可能であり、このため企業の運営やパートナーシップにおいて重要な要素となる。","explanationZh":"当事方之间规定权利、义务、范围、费用、期限和责任等内容的具有约束力的协议。服务管理中合同应与业务需求、SLA和安全要求一致。"},{"id":"t0684","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"内部供給者","termZh":"内部供应方","english":"Internal Supplier","reading":"ないぶきょうきゅうしゃ","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"組織内で他の部門やプロジェクトに対して製品やサービスを提供する部門やチームのことである。例えば、企業のIT部門が他の部署のためにシステムを開発したり、経理部門が財務データをもとに報告書を作成したりする場合、これらの部門は内部供給者となる。内部供給者は外部の供給者と異なり、組織の目標やビジョンに密接に関連し、ニーズに応じた柔軟な対応が求められる。また、内部のリソースを効率よく活用することで、コスト削減や迅速な対応が可能になるため、企業全体のパフォーマンス向上に寄与することが期待されている。","explanationZh":"同一组织内部向其他部门或业务单元提供服务、资源或支持的部门。虽然不是外部合同关系，也应明确服务职责、目标和协作方式。"},{"id":"t0685","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"需要管理","termZh":"需求管理","english":"Demand Management","reading":"じゅようかんり","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"製品やサービスに対する顧客の需要を予測し、適切に調整するプロセスである。この管理手法は、販売や生産の計画に役立ち、需要の変動に迅速に対応することで、過剰在庫や欠品を防ぐことを目的とする。具体的には、需要予測、在庫管理、販売計画などが含まれ、これらを通じて顧客満足度を高めることができる。また、情報技術を活用することで、リアルタイムでの需要分析が可能になり、より精密な需要管理が実現される。これにより、企業は効率的な資源配分が可能となり、コスト削減や収益向上に繋がる。","explanationZh":"理解、预测和影响客户对服务的需求，并使资源和服务能力与需求相匹配的管理活动。通过分析使用模式和业务计划，可减少资源过剩或不足。"},{"id":"t0686","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"キャパシティ管理","termZh":"容量管理","english":"Capacity Management","reading":"きゃぱしてぃかんり","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやサービスが必要なリソースを適切に確保し、最適に運用するためのプロセスである。これにより、パフォーマンスが低下したり、システムが過負荷になることを防ぐことが可能である。具体的には、サーバのストレージ、メモリ、CPUなどのリソースを監視し、需要の変化に応じて適切なキャパシティを保つことが求められる。例えば、急激なアクセス増加に備えてリソースを増強したり、平常時に無駄なリソースを削減することが含まれる。これにより、サービスの信頼性や効率が向上し、コスト管理にも寄与するため、企業にとって重要な活動である。","explanationZh":"确保IT和服务资源在当前及未来具有足够容量和性能，同时保持成本合理的管理过程。需要监测利用率、分析趋势并进行容量预测和扩容规划。"},{"id":"t0687","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"監視","termZh":"监控","english":"Monitoring","reading":"かんし","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやネットワークの状態を継続的にチェックして、パフォーマンスや障害を把握するプロセスである。特にIT分野においては、サーバの負荷、ネットワークのトラフィック、アプリケーションの応答速度などを監視することで、問題が発生した際に迅速に対処できるようになる。例えば、サーバのCPU使用率が高い場合、監視ツールがアラートを発し、運用者は過負荷の原因を特定し、適切な措置を講じることができる。このように、監視はシステムの安定性を保つために不可欠な要素である。さらに、監視データを分析することで、将来の容量計画にも役立てることができる。","explanationZh":"持续观察服务、系统、资源和流程状态并收集数据，以发现异常、性能下降和阈值超限。监控结果用于事件处理、容量管理和绩效评价。"},{"id":"t0688","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"管理指標","termZh":"管理指标","english":"Management Metrics","reading":"かんりしひょう","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやサービスの性能や効率を測定するために使用される数値である。具体的には、CPU使用率、メモリ使用率、ディスク使用率、ネットワーク使用率などが含まれる。これらの指標は、システムの健康状態を把握し、リソースの最適化や問題の早期発見に役立つ。たとえば、CPU使用率が高い場合、計算リソースが不足し、処理が遅くなる可能性があることを示している。そのため、管理指標を定期的に監視することで、システムのパフォーマンスを維持し、必要に応じて調整を行うことができる。これは、特にビジネスの運用において、効率的な資源管理やサービスの信頼性向上に寄与する。","explanationZh":"用于量化服务、过程或管理目标达成情况的指标，例如可用率、响应时间、事件数和客户满意度。指标应与目标相关、可测量并定期评审。"},{"id":"t0689","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"しきい値","termZh":"阈值","english":"Threshold","reading":"しきいち","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"特定の条件や状況において何かが発生するための境界点や基準値を指す。例えば、システムの性能監視において、CPUの使用率が80%を超えた場合に警告を発するよう設定されているとき、80%がしきい値である。このように、問題点や異常を早期に発見するための重要な指標となる。さらに、しきい値を適切に設定することで、システムの安定性や効率を向上させることが可能となり、必要な対応を早急に行うことができるため、容量や能力管理において欠かせない概念である。","explanationZh":"为某项监控指标设置的边界值，达到或超过时触发告警、调查或自动措施。合理阈值可帮助在问题影响用户之前发现异常。"},{"id":"t0690","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"変更管理","termZh":"变更管理","english":"Change Management","reading":"へんこうかんり","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"組織におけるシステムやプロセスに加えられる変更を計画的に管理する手法である。このプロセスは、変更が発生する際の影響を評価し、リスクを軽減しながら、組織の目標やニーズに沿った形で変更を実施することを目的としている。具体的には、変更の提案から実施、さらにはその効果の評価までの一連のステップを含む。また、変更管理には関係者とのコミュニケーションが重要であり、変更がどのような影響をもたらすのかを理解してもらうことが求められる。これにより、変更が円滑に受け入れられ、業務の中断や混乱を防ぐことができる。","explanationZh":"对可能影响服务和系统的变更进行提出、评估、批准、计划、实施和复审的过程。目标是在实现业务收益的同时控制故障、安全和中断风险。"},{"id":"t0691","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"変更によるサービスへの影響","termZh":"变更对服务的影响","english":"Change Impact on Service","reading":"へんこうによるさーびすへのえいきょう","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやサービスに対して実施される変更が、既存のサービスや業務に及ぼす影響を評価するプロセスを指す。この評価は、変更管理プロセスの重要な部分であり、サービスの設計や移行、リリース及び展開において行われる。具体的には、新しい機能の追加やシステムのアップデートが、既存のユーザーやステークホルダーの操作方法にどのように影響するかを分析し、潜在的な問題やリスクを特定する。例えば、ある機能の変更が全体的なパフォーマンスに悪影響を与える場合、それを事前に把握することで、適切な対策を講じることができる。このように、変更による影響を把握することは、サービスの品質を保ちつつ円滑な運用を実現する上で欠かせない要素である。","explanationZh":"变更可能对可用性、性能、安全、容量、用户和其他服务产生的直接或间接影响。实施前应进行影响和风险评估，并准备回退方案。"},{"id":"t0692","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"サービス受入れ基準","termZh":"服务验收标准","english":"Service Acceptance Criteria","reading":"さーびすうけいれきじゅん","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"製品やサービスがクライアントやユーザーに受け入れられるために満たすべき条件や基準のことである。これらの基準は、品質、性能、機能性、セキュリティなど、さまざまな要素が含まれる。たとえば、新しいソフトウェアの開発においては、特定の機能が正常に動作することや、ユーザーインターフェースが使いやすいことが受入れ基準として設定されることがある。これにより、開発チームとクライアントとの間で期待値を明確にし、プロジェクトの成功を確保するための重要な指針となる。受入れ基準を明確にすることで、開発の進行状況を正しく評価できたり、最終的な納品物が要求に適合するかどうかを判断しやすくなる。","explanationZh":"在新建或变更服务投入正式使用前必须满足的可验证条件。可包括功能、性能、安全、运维、文档和支持能力等要求，是是否允许上线的重要判定依据。"},{"id":"t0693","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"サービス設計書","termZh":"服务设计文档","english":"Service Design Document","reading":"さーびすせっけいしょ","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"新しいサービスやシステムを計画・構築する際に必要な情報をまとめた文書である。この書類には、サービスの目的、機能、運用方法、ユーザー体験などが詳細に記載される。例えば、飲食店の新しい注文システムを導入する際には、顧客の流れや操作の手順、システムの技術的要件、配達のタイミングなどが盛り込まれることが一般的である。関係者全員が同じ理解を持つための基盤となり、開発や運用のスムーズな進行を促進する役割を果たす。これにより、顧客にとって魅力的で使いやすいサービスの実現が期待される。","explanationZh":"记录服务设计方案的文档，通常包括架构、流程、SLA、安全、容量、可用性、连续性、监控和支持等内容。它为建设、测试、移交和运行提供统一依据。"},{"id":"t0694","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"非機能要件","termZh":"非功能需求","english":"Non-Functional Requirements","reading":"ひきのうようけん","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやソフトウェアの機能以外の特性や制約に関する要件を指す。具体的には、性能、信頼性、セキュリティ、可用性などが含まれる。例えば、あるWebアプリケーションが「1000人同時接続に耐えられる」という性能要件を満たすことは、非機能要件の一例である。また、非機能要件はシステムの使いやすさやメンテナンス性、将来の拡張性にも影響を与えるため、設計段階で考慮することが重要である。これにより、ユーザーが快適にシステムを利用できる質の高い製品が実現される。","explanationZh":"描述系统“如何运行”而不是“做什么”的要求，例如性能、可用性、可靠性、安全性、可维护性、扩展性和易用性。非功能需求应尽量量化以便测试和验收。"},{"id":"t0695","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"移行","termZh":"迁移／转换","english":"Migration","reading":"いこう","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"あるシステムやデータを既存の環境から新しい環境へ移すプロセスである。例えば、古いパソコンから新しいパソコンにデータを移すといった作業がこれに該当する。また、ソフトウェアやアプリケーションが新しいバージョンに更新される際にも移行が発生することが多い。移行には計画的な手順が必要で、データの損失や障害を防ぐために、バックアップを取ったり、移行後の動作確認を行ったりすることが重要である。これは、業務の継続性を保ちながら新しい技術を取り入れるために欠かせないプロセスである。","explanationZh":"把业务、数据、系统或服务从现有环境转移到新环境的过程。需要规划数据转换、切换、用户准备、回退和验证，以降低中断和数据损失风险。"},{"id":"t0696","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"運用サービス基準","termZh":"运行服务标准","english":"Operational Service Standards","reading":"うんようさーびすきじゅん","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"情報システムやサービスの運用管理において遵守すべき基準を示すものである。具体的には、サービスの品質や可用性、運用プロセスの効率性を確保するための指針となる。例えば、システムの稼働時間や障害発生時の対応時間を定めることで、信頼性の高いサービス提供を実現する。また、基準は業界のベストプラクティスに基づいており、運用の一貫性を保ちながら、顧客満足度を高めるために重要である。これにより、システムの運用が円滑に行われ、ビジネスの継続性が確保される。","explanationZh":"规定服务进入运行后应满足的操作、监控、支持、性能和安全等标准。它为日常运维、质量控制和服务评价提供一致依据。"},{"id":"t0697","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"業務及びシステムの移行","termZh":"业务及系统迁移","english":"Business and System Migration","reading":"ぎょうむおよびしすてむのいこう","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"企業や組織が利用している業務プロセスやシステムを新しい環境へ移行するプロセスである。この移行は、新しい技術やプラットフォームを導入する際に行われ、通常は効率化やコスト削減、機能の向上を目的としている。例えば、古いサーバからクラウド環境へデータを移動させることが挙げられる。移行作業では、データの安全性を保ちながら、移行計画を策定し、ユーザーへの影響も考慮する必要がある。適切な手順とスケジュールを設定することで、業務の継続性を確保しながら円滑に移行を進めることが重要である。","explanationZh":"在新系统上线时，将业务流程、数据、用户和技术环境从旧系统转移到新系统的整体活动。除了技术切换，还需考虑人员培训和业务连续性。"},{"id":"t0698","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"移行計画","termZh":"迁移计划","english":"Migration Plan","reading":"いこうけいかく","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやデータを新しい環境へ移すための具体的な手順や戦略を示す文書である。この計画は、移行の目的、範囲、スケジュール、リスク管理の方法などを詳細に記載し、プロジェクトの成功を確実にするために重要である。例えば、旧システムから新システムへデータを移行する際には、データのバックアップやテストを行い、移行後に問題が発生しないように準備する必要がある。また、適切な移行計画は業務の継続性を保ち、ダウンタイムを最小限に抑えることにも寄与するため、企業のIT戦略において欠かせない要素である。","explanationZh":"规定迁移范围、步骤、时间、责任、资源、数据处理、测试、通知、回退和风险措施的计划。详细计划是安全切换和协调多方工作的基础。"},{"id":"t0699","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"移行リハーサル","termZh":"迁移演练","english":"Migration Rehearsal","reading":"いこうりはーさる","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"新しいシステムや環境へのデータやアプリケーションの移行作業を行う前に、そのプロセスを事前にテストする手法である。これは、実際の移行作業時に想定外のトラブルを避けるために重要である。たとえば、企業が古いサーバから新しいクラウド環境へデータを移す際、移行リハーサルを行うことで、データの正確性や移行手順の確認を行い、本番環境での混乱を未然に防ぐことができる。このプロセスでは、特定のシナリオを設定して、移行がスムーズに進むかどうかを検証し、必要な改善点を見出すことができるため、信頼性の向上やリスク管理にも役立つ。","explanationZh":"在正式切换前按照迁移计划模拟或实际执行关键步骤的演练。用于验证时间、工具、数据转换、人员协作和回退方案是否可行，并发现潜在问题。"},{"id":"t0700","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"移行判断","termZh":"迁移判定","english":"Transition Decision","reading":"いこうはんだん","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやサービスを新しい環境へ移行する際に、その実施可否やタイミングを判断するプロセスである。この判断は、新しいシステムの準備状況や要件の適合性、業務への影響を考慮することが求められる。例えば、ある企業がクラウドサービスに移行する場合、データの安全性やシステムの互換性を確認し、問題がないかを判断した上で移行を進める。リスクを最小限に抑え、スムーズな移行を実現するために非常に重要なステップである。","explanationZh":"根据测试、演练、缺陷、风险和业务准备情况决定是否执行正式迁移或上线的决策。应设定明确的Go/No-Go标准和授权责任。"},{"id":"t0701","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"移行の通知","termZh":"迁移通知","english":"Migration Notification","reading":"いこうのつうち","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやサービスが新しい環境に移転する際に、関係者やユーザーに対して行う通知のことである。この通知は、移行日程や影響範囲、利用方法の変更点などを詳細に伝える目的があり、スムーズな移行を実現するために重要である。例えば、システムのアップグレードやデータの移行時に、ユーザーへ事前にお知らせをすることで、予期せぬトラブルを防ぎ、利用者が新しい環境に適応できるようサポートする役割を果たす。また、適切な移行の通知を行うことにより、企業や組織の信頼性向上にも寄与する。","explanationZh":"向用户、客户、运维人员和相关方提前说明迁移时间、影响、注意事项和支持渠道的沟通活动。及时通知可减少业务混乱并提高应急响应效率。"},{"id":"t0702","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"移行評価","termZh":"迁移评价","english":"Transition Assessment","reading":"いこうひょうか","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやサービスが新しい環境に移行する際の評価プロセスである。これは、移行の計画や実施の妥当性を確認するために必要なステップであり、リスクや問題点を特定する役割を果たす。例えば、ある企業が新しいクラウドサービスに移行する場合、既存システムとの互換性やデータの安全性を評価することで、スムーズな移行が実現できる。また、関係者の期待を明確にするために重要であり、成功裏に移行プロジェクトを完了させるための鍵となる。これにより、運用の継続性が確保されるため、企業にとって大変重要なプロセスである。","explanationZh":"在迁移前后评估计划执行、数据完整性、服务影响、目标达成和遗留问题的活动。结果用于确认迁移成功并为后续改进提供经验。"},{"id":"t0703","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"運用テスト","termZh":"运行测试","english":"Operational Test","reading":"うんようてすと","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやアプリケーションが実際の運用環境で期待通りに機能するかを確認するプロセスである。これは、システムが正しく稼働し、業務の要求に応じたパフォーマンスを発揮するかを評価するために行われる。具体的には、システムの負荷テストやセキュリティチェックが含まれ、問題がないかを確認します。実際のユーザーによる使用状況に基づいて行われるため、開発段階で見逃されがちな不具合を発見するために重要である。また、運用テストを通じて得られたフィードバックは、システムの改善や最適化に役立ち、信頼性の高いサービスを提供する基盤となる。","explanationZh":"从实际运维角度验证系统能否被监控、备份、恢复、维护和支持的测试。除业务功能外，还检查操作手册、作业、告警和故障处理等可运行性。"},{"id":"t0704","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"受入れテスト","termZh":"验收测试","english":"Acceptance Testing","reading":"うけいれてすと","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやソフトウェアが仕様通りに機能しているかを確認するための試験である。このテストは、実際のエンドユーザーがどのように製品を使用するかに重点を置き、導入前に最終確認を行うために実施される。例えば、新しいビジネスアプリケーションを導入する際、ユーザーが実際の業務環境でその機能を確認し、期待通りの動作をしているかをチェックする。システムが期待された品質基準を満たしているか評価する重要なプロセスであり、これを通じて発見された問題点を修正することで、より良い製品を提供することが可能になる。","explanationZh":"由客户或用户依据需求和验收标准确认系统或服务是否满足约定要求的测试。通过验收通常是正式交付或上线的重要条件。"},{"id":"t0705","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"運用引継ぎ","termZh":"运维移交","english":"Operation Handover","reading":"うんようひきつぎ","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやサービスの運用に関する知識や責任を、前任者から後任者に引き継ぐプロセスである。このプロセスは、システムが安定して運用され続けるために重要であり、通常、必要な文書や手順、運用ノウハウを明確に共有することが求められる。たとえば、新たな運用チームがプロジェクトを引き継ぐ際には、システムの構成、トラブルシューティングの方法、日常の監視手順などが詳細に伝えられる。このように、運用引継ぎの適切な実施は、サービスの品質を維持し、問題の発生を未然に防ぐために不可欠である。","explanationZh":"把系统从开发／项目团队正式交给运维团队管理的过程。应移交文档、配置、账号、监控、备份、已知问题、培训和支持责任等，以确保服务连续。"},{"id":"t0706","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"リリース及び展開管理","termZh":"发布与部署管理","english":"Release and Deployment Management","reading":"りりーすおよびてんかいかんり","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"ソフトウェアやシステムの新しいバージョンを適切に計画し、実施するプロセスである。これは、開発段階で作成された製品を、運用環境に安全に導入するために必要な手順や技術を含む。具体的には、リリース予定日を設定し、テストを経た上で新機能や修正を顧客に提供することが含まれる。この管理プロセスは、変更がユーザーに与える影響を最小限に抑えるために重要であり、問題発生時の対応策やロールバック手順も考慮される。ITサービスマネジメントの一環として、組織が効率的にサービスを提供するために不可欠である。","explanationZh":"对新版本或变更包进行计划、构建、测试、安排并部署到目标环境的管理过程。目标是在控制风险的前提下把经批准的变更稳定交付给用户。"},{"id":"t0707","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"インシデント管理","termZh":"事件管理","english":"Incident Management","reading":"いんしでんとかんり","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"ITサービスにおいて発生する問題や障害（インシデント）を効率的に解決するためのプロセスである。この管理プロセスは、インシデントを迅速に特定し、影響を最小限に抑えることを目的としている。具体的には、ユーザーからの報告を受け付け、問題の調査や解決策を提案し、必要に応じてエスカレーションを行う手順を含む。また、インシデントの発生を記録し、再発防止のための分析を行うことも重要である。これにより、ITサービスの信頼性を向上させ、ユーザーの満足度を高めることができる。","explanationZh":"对影响或可能影响服务正常运行的事件进行记录、分类、优先级判定、诊断、恢复和关闭的管理过程。首要目标是尽快恢复正常服务并降低业务影响。"},{"id":"t0708","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"インシデント","termZh":"事件（Incident）","english":"Incident","reading":"","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやネットワークにおいて発生する予期しない事象のことを指す。これには、セキュリティの脅威、データの損失、システムのダウンタイムなどが含まれ、業務に影響を及ぼす可能性がある。インシデントの真の特定と迅速な対応は、ビジネスの継続性や情報の安全を確保するために非常に重要である。例えば、サイバー攻撃によるデータ漏洩やサービス停止は、インシデントの典型であり、適切な管理と対策が求められる。これにより、被害の最小化や再発防止を図ることができる。インシデント対応計画の策定は、組織におけるリスク管理の一環として欠かせない要素である。","explanationZh":"导致或可能导致服务中断、质量下降或异常的非计划事件。例如服务器故障、应用报错和网络中断等，通常需要通过事件管理流程处理。"},{"id":"t0709","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"影響","termZh":"影响","english":"Impact","reading":"えいきょう","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"特定の事象や行動がもたらす結果や効果を指す言葉である。特に情報技術の分野においては、セキュリティインシデントやシステムの変更が、業務や利用者、データに対して与える影響を評価することが重要である。例えば、サイバー攻撃がシステムに与える影響を分析することで、どの程度の損失やダウンタイムが発生するかを予測し、適切な対応策を講じることが可能となる。このように、影響の理解は、インシデントの対応やリスク管理において不可欠な要素であり、迅速かつ効果的に問題に対処するための基盤を提供する。","explanationZh":"某个事件、问题或变更对业务、用户、服务或资产造成后果的程度。影响常与紧急程度结合，用于确定处理优先级。"},{"id":"t0710","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"サービス要求","termZh":"服务请求","english":"Service Request","reading":"さーびすようきゅう","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"ユーザーが特定のサービスやリソースを必要とする際に提出する正式なリクエストである。この要求は、ITサービスマネジメントの一部として扱われ、通常はサポートデスクを通じて処理される。具体的な例としては、新しいソフトウェアのインストール、パスワードのリセット、ハードウェアの修理依頼などが挙げられる。組織の効率を上げ、サービスの質を向上させるための重要な手段であり、適切な管理が求められる。これにより、ユーザーのニーズが迅速に満たされることが期待され、全体の満足度の向上につながる。","explanationZh":"用户提出的标准化服务需求，例如账号申请、软件安装、信息查询或权限变更。它通常不是故障事件，而是通过预定义流程处理的正常请求。"},{"id":"t0711","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"エスカレーション","termZh":"升级（Escalation）","english":"Escalation","reading":"","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"特定の問題やインシデントが解決できない場合に、より高いレベルの専門家や管理者に問題を引き継ぐプロセスを指す。これはインシデント管理やサービス要求管理、問題管理の分野で重要な手段となる。例えば、初期対応を行った担当者が解決できない技術的な問題を上司や専門チームにエスカレーションすることで、迅速かつ適切な対応を促すことができる。また、サービスの品質を維持するために必要なプロセスであり、クライアントへの影響を最小限に抑える役割も果たす。適切なエスカレーションが行われることで、組織内の問題解決が円滑に進む。","explanationZh":"当现有处理层级无法在要求时间或权限范围内解决问题时，将事项转交更高技术层级或管理层处理。可分为功能升级和层级升级。"},{"id":"t0712","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"回避策","termZh":"临时解决办法／变通方案（Workaround）","english":"Mitigation Measures","reading":"かいひさく","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"インシデントが発生した際にその影響を軽減するための手立てを指す。具体的には、トラブルが発生しないようにするための予防策や、万が一問題が発生した際にその被害を最小限に抑えるための計画が含まれる。例えば、システムのバックアップを定期的に行うことや、セキュリティの強化を図るための教育・訓練を実施することなどが挙げられる。リスク管理の重要な一部であり、組織が持続的に運営されるためには欠かせない要素である。インシデントを未然に防ぎ、迅速な対応を行うことで、ビジネスの信頼性を高めることができる。","explanationZh":"在根本原因尚未消除时，用于暂时降低或绕过故障影响、恢复服务的方法。它不是永久修复，应在问题管理中继续推进根因消除。"},{"id":"t0713","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"重大なインシデント","termZh":"重大事件","english":"Major Incident","reading":"じゅうだいないんしでんと","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"企業や組織の運営に深刻な影響を及ぼすような事象や事故を指すものである。このようなインシデントは、通常の業務が停止または大幅に制限されることがあるため、迅速かつ効果的な対応が求められる。具体的には、サーバダウン、大規模なデータ漏洩、自然災害による業務継続への影響などが該当する。重大なインシデントの対応には、影響を最小限に抑え、迅速に復旧するための計画やプロセスが必要であり、関係者間の連携が非常に重要である。これによって、企業の信頼性を保つとともに、顧客への影響を抑えることが可能となる。","explanationZh":"对关键服务、众多用户或业务造成严重影响，需要更高优先级、跨团队协调和管理层关注的事件。组织通常为重大事件设立专门响应流程和沟通机制。"},{"id":"t0714","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"ヒヤリハット","termZh":"未遂事件／险情（Near Miss）","english":"Near Miss","reading":"","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"事故や問題が発生する一歩手前の状況を指す言葉である。具体的には、実際には事故やトラブルが起こらなかったが、危険な状態に遭遇した際の体験を指す。例えば、運転中に急な障害物に気づき、ブレーキをかけることで事故を回避した場合が該当する。ヒヤリハットの情報を共有し、分析することによって、同様の事例を未然に防ぐ対策を講じることができる。このため、インシデント管理や問題管理、サービス要求管理においては、ヒヤリハットを積極的に報告し、改善活動に活かすことが重視されている。これにより、安全性やサービス品質の向上が図られる。","explanationZh":"已经出现异常或危险征兆，但尚未造成实际事故或严重损失的事件。记录和分析Near Miss有助于在真正事故发生前发现薄弱点并采取预防措施。"},{"id":"t0715","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"サービス要求管理","termZh":"服务请求管理","english":"Service Request Management","reading":"さーびすようきゅうかんり","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"顧客からのサービスに関する要望や問題を体系的に管理するプロセスである。このプロセスでは、顧客が提出したリクエストを受け付け、分類し、解決に向けた手続きを行う。例えば、ソフトウェアのインストール依頼やトラブルシューティングの支援などが含まれる。企業のITサービスマネジメントの一環として位置付けられ、顧客満足度の向上や業務効率の改善を目指す。また、適切な管理により、サービスの提供がスムーズになり、顧客とのコミュニケーションも円滑に進むことが期待される。","explanationZh":"对用户的标准服务请求进行接收、分类、审批、履行和关闭的管理过程。通过标准化和自动化可提高处理效率并保证权限和记录完整。"},{"id":"t0716","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"問題管理","termZh":"问题管理","english":"Problem Management","reading":"もんだいかんり","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"ITサービスの運営において、発生した問題を特定し、根本原因を分析し、解決策を見つけるためのプロセスである。このプロセスは、システムやサービスの安定性を向上させるために重要である。具体的には、問題が発生する前に予防策を講じたり、発生後に迅速に対応したりすることで、将来の障害を未然に防ぐことを目的とする。インシデント管理と密接に関連しており、インシデントの原因を究明することによってサービスの品質を高めるための重要な手段である。これにより、業務の円滑な運営が促進され、顧客満足度の向上にも寄与する。","explanationZh":"识别和管理一个或多个事件背后的原因，降低事件再次发生概率和影响的过程。包括根因分析、已知错误管理、变通方案和永久修复推动。"},{"id":"t0717","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"既知の誤り","termZh":"已知错误","english":"Known Error","reading":"きちのあやまり","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"問題管理において既に特定され、分析された誤りやバグのことである。この概念は、ITサービス管理の一環として重要であり、既知の誤りを文書化しておくことで、将来的な問題発生時に迅速に対応できるようにする。例えば、特定のソフトウェアにおいて既知の誤りが記録されていれば、その問題が再発した際に、スムーズに回避策や修正プランを適用できる。このように、既知の誤りを管理することは、サービスの安定性や信頼性を高め、顧客満足度向上に寄与する。","explanationZh":"已经分析出根因或已有可用变通方案，但尚未完成永久修复的问题。记录已知错误可以帮助服务台更快恢复同类事件。"},{"id":"t0718","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"根本原因","termZh":"根本原因","english":"Root Cause","reading":"こんぽんげんいん","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"問題が発生する際の最も基本的な原因を指すものである。これを特定することで、問題を表面的に対処するのではなく、再発を防止するための根本的な解決策を講じることが可能である。例えば、あるシステムのダウンがユーザーの不満を引き起こした際、その背後にある根本原因を洗い出すことで、ハードウェアの故障やソフトウェアのバグを取り除くことができる。このように、根本原因の分析は、問題管理の重要なプロセスであり、組織が持続的に改善を図るための基盤となる。","explanationZh":"导致问题或事件发生的最深层可控原因。仅消除表面症状可能导致再次发生，因此问题管理强调通过分析找到并处理根本原因。"},{"id":"t0719","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"予防処置","termZh":"预防措施","english":"Preventive Action","reading":"よぼうしょち","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"将来発生する可能性のある問題や不具合を未然に防ぐための具体的な対策を指す。問題管理の分野において、予防処置は重要な役割を果たし、潜在的なリスクを特定し、それに対するアクションを計画することで、組織の運営をより円滑に進めることを目指す。例えば、過去の問題データを分析し、同様の問題が再発しないように改善策を実施することで、業務の効率や信頼性を高めることができる。このように、予防処置は単なる対策ではなく、組織全体の品質向上にも寄与するものである。","explanationZh":"在潜在问题或风险实际导致事件之前采取的措施，用于消除原因或降低发生概率。现代管理标准更强调基于风险的预防性思维和持续改进。"},{"id":"t0720","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"傾向分析","termZh":"趋势分析","english":"Trend Analysis","reading":"けいこうぶんせき","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"データの変動やパターンを把握するために、時間の経過とともに収集した情報を分析する手法である。特にインシデント管理やサービス要求管理、問題管理の分野においては、過去のデータを元に将来の傾向を予測することが重要である。例えば、過去のインシデントの発生頻度を分析することで、特定の時間帯や条件でインシデントが増加する傾向を見つけ出すことができる。この情報を基に、適切な対策を講じたり、リソースを効果的に配分したりすることが可能となる。より良いサービスを提供するための意思決定をサポートし、運用の効率化を図る役割を果たす。","explanationZh":"利用一段时间内的事件、性能、容量和其他数据识别变化方向、重复模式和异常增长的分析方法。可用于提前发现问题和支持预测性管理。"},{"id":"t0721","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"サービス可用性管理","termZh":"服务可用性管理","english":"Service Availability Management","reading":"さーびすかようせいかんり","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"提供されるサービスが適切に稼働し、利用者が常にアクセスできる状態を維持するためのプロセスである。これは、システムの障害やメンテナンスによるダウンタイムを最小限に抑え、安定したサービスを提供することを目指す。具体的には、サービスの稼働状況を常時監視し、問題発生時には迅速に対応する体制を整える。また、サービスの改善策を検討し、将来的なニーズを予測することも含まれる。これにより、ビジネスの可用性と顧客満足度の向上に寄与する。","explanationZh":"规划、监测和改进服务可用性，使其满足约定业务需求的管理过程。需要分析组件可靠性、维护性、冗余、故障和服务时间，并制定提升措施。"},{"id":"t0722","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"サービス継続管理","termZh":"服务连续性管理","english":"Service Continuity Management","reading":"さーびすけいぞくかんり","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"企業や組織がサービスを持続的に提供するための計画やプロセスを整備することを指す。この管理手法は、災害やシステム障害などの予期せぬ事態に対処し、業務の中断を最小限に抑えることを目的としている。例えば、ある企業がシステム障害に見舞われた場合、事前に策定された対応策に基づいてバックアップシステムに切り替えることで、顧客への影響を少なくし、業務の継続性を保つことが可能である。また、定期的な訓練やシミュレーションを行うことで実効性を高め、万が一の事態にも迅速に対応できる体制を整えることが重要である。これは、サービスの信頼性を向上させ、顧客満足度を維持するために欠かせない要素となっている。","explanationZh":"确保重大故障或灾害发生后，组织能够在业务可接受时间内恢复和持续提供关键服务的管理过程。它与业务连续性、灾备、RTO和RPO密切相关。"},{"id":"t0723","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"サービス継続計画","termZh":"服务连续性计划","english":"Service Continuity Plan","reading":"さーびすけいぞくけいかく","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"事業が中断された場合に正常な運営を維持するための戦略や手順をまとめたものである。この計画は、災害やシステム障害、その他のリスク要因に対処し、迅速にサービスを回復させることを目的とする。具体的には、重要な業務プロセスの特定、代替手段の策定、従業員の役割分担などが含まれる。サービス継続計画が整備されていることで、企業は状況に応じた柔軟な対応が可能となり、顧客への影響を最小限に抑えることができる。また、定期的な訓練や見直しにより、計画の効果を高め、実効性を保つことが重要である。","explanationZh":"规定重大中断发生时如何维持或恢复服务的计划。应包括触发条件、责任、联系、备用资源、恢复顺序、通信和演练要求，并定期测试和更新。"},{"id":"t0724","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"RTO","termZh":"恢复时间目标（RTO）","english":"Recovery Time Objective","reading":"あーるてぃーおー","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"サービスやシステムが障害から復旧するまでに要する最大時間を示す指標である。具体的には、サービス停止後にどれくらいの時間内で業務を再開できるかを示し、組織が事前に設定した目標である。例えば、ある企業がRTOを4時間に設定した場合、システムがダウンした際には4時間以内にサービスを復旧することが求められる。RTOは緊急時の対応計画や災害復旧策を策定する際に重要な要素となり、これにより企業は業務の継続性を保つための準備を行い、顧客やパートナーに信頼性を提供することができる。","explanationZh":"发生中断后，业务或服务必须在多长时间内恢复到可接受状态的目标时间。RTO越短，通常需要投入越多冗余和恢复资源。"},{"id":"t0725","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"RPO","termZh":"恢复点目标（RPO）","english":"Recovery Point Objective","reading":"あーるぴーおー","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"データの損失を許容できる最大の時間間隔を示す指標である。これは、サービス可用性管理やサービス継続管理において、重要な役割を果たす。例えば、RPOが1時間である場合、システムが障害を起こった際、過去1時間以内に作成されたデータは復旧可能だが、それ以前のデータは失われてしまう可能性がある。このように、RPOを設定することにより、どの程度のデータ損失を許容するかを明確にし、適切なバックアップ戦略を立てることが重要となる。高いRPOは頻繁なバックアップを意味し、ビジネスの継続性を確保するために必要な計画を立てる基盤となる。","explanationZh":"发生灾害或故障后可接受的数据丢失时间范围，即恢复的数据最早可回退到中断前多久。RPO决定备份或数据复制频率要求。"},{"id":"t0726","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"RLO","termZh":"恢复级别目标（RLO）","english":"Reverse Line Feed Order","reading":"あーるえるおー","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"サービス可用性管理やサービス継続管理において使用される技術の一つである。これは、特定のデータの順序を逆転させる手法で、情報の伝達や表示において特定の条件下で必要とされる技術である。例えば、メッセージやデータストリームに対して適用されることが多く、特定の言語や文化における文字の表示を考慮する際に重要である。主にデジタルデータの整列や表示に関連し、データの整合性を保つために利用される。これにより、サービスの可用性を高め、継続的な運用をサポートする役割を果たしている。","explanationZh":"在业务连续性语境中，RLO通常指Recovery Level Objective，即灾害后业务或系统应恢复到何种服务水平、功能范围或处理能力的目标。原文英文“Reverse Line Feed Order”与本语境不符，属于明显误标；复习时应按“恢复级别目标”理解。"},{"id":"t0727","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"障害復旧","termZh":"故障恢复","english":"Disaster Recovery","reading":"しょうがいふっきゅう","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやサービスにおいて障害が発生した際に、正常な状態に戻すための手続きや計画を指す。特に、企業や組織では、データやサービスの喪失を防ぎ、業務を続けるための重要な戦略である。ハードウェアやソフトウェアの故障、自然災害、サイバー攻撃など、さまざまなリスクを対象としている。具体的には、バックアップシステムの使用や、代替データセンターの設置、復旧手順の文書化が含まれる。これによって、障害発生時でも迅速に対応し、業務の継続性を確保することができる。また、障害復旧計画は定期的に見直し、テストすることが推奨される。","explanationZh":"系统因硬件、软件、网络等故障中断后，通过切换、重启、修复或从备份恢复等手段恢复正常服务的过程。重点是针对一般系统故障尽快恢复运行。"},{"id":"t0728","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"災害復旧","termZh":"灾难恢复（DR）","english":"Disaster Recovery","reading":"さいがいふっきゅう","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"自然災害や技術的なトラブルによってシステムやデータが損失した際に、それらを復元するためのプロセスである。具体的には、システムのバックアップデータからの復元や、代替のインフラを用意することが含まれる。例えば、地震や洪水によってサーバがダウンした場合、事前に用意されたバックアップからデータを復元し、必要なシステムを再稼働させることで、業務の継続を図る。サービス可用性管理やサービス継続管理の重要な一部であり、企業が迅速に通常業務を再開できるよう支援するための計画や対策が求められる。これにより、ダウンタイムを最小限に抑え、顧客や取引先に与える影響を軽減することが可能になる。","explanationZh":"发生地震、火灾、大规模网络攻击等严重灾害后，按照灾难恢复计划恢复IT基础设施、数据和关键系统的活动。需要与业务连续性目标、RTO和RPO协调。"},{"id":"t0729","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"コールドスタンバイ","termZh":"冷备份／冷备用（Cold Standby）","english":"Cold Standby","reading":"","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやサービスの障害発生時に備えて、予備システムを用意しておく状態である。この場合、予備システムは通常稼働しておらず、必要に応じて起動されることになる。通常の運用中はリソースを節約できるため、コスト効率が良い。しかし、障害が発生した際には、予備システムを手動で起動し、データを最新の状態に同期させる手間がかかるため、復旧時間が長くなる可能性がある。これに対して、ホットスタンバイやウォームスタンバイといった異なる形式も存在し、それぞれの運用シナリオに応じて選択されることが重要である。","explanationZh":"备用环境平时不运行或只保持最低准备状态，故障时需要启动设备、恢复数据和配置后才能接管业务。成本较低，但恢复时间较长。"},{"id":"t0730","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"ホットスタンバイ","termZh":"热备用（Hot Standby）","english":"Hot Standby","reading":"","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムの冗長化手法の一つである。主にサービス継続管理において使用され、主要なシステムが故障した際に即座に代替システムが稼働することを目的としている。この手法では、主系と同じ機能を持つ予備のシステムが常に起動しているため、迅速に切り替えが可能であり、ダウンタイムを最小限に抑えることができる。例えば、あるサーバが故障した場合、ホットスタンバイの構成では予備のサーバがすでにデータを同期しており、即座に処理を引き継ぐことで、業務の継続性を確保する。このように、ホットスタンバイはサービスの信頼性を向上させる重要な技術である。","explanationZh":"备用系统平时保持运行并与主系统实时或近实时同步，主系统故障时可快速接管业务。恢复时间短，但建设和运行成本较高。"},{"id":"t0731","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"サービス可用性","termZh":"服务可用性","english":"Service Availability","reading":"さーびすかようせい","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"特定の期間において、サービスが正常に機能し利用可能な状態を維持する能力を指す。これは、システムやサービスがダウンしている時間を最小限に抑え、ユーザーが常にサービスを利用できるようにするための重要な概念である。例えば、オンラインストレージサービスでは、ユーザーがデータにアクセスできる時間が長ければ長いほど、サービスの可用性は高いとされる。この可用性は、システムの冗長性やバックアップ、障害復旧プロセスなど、さまざまな技術的対策によって支えられている。高いサービス可用性を確保することで、顧客満足度を向上させ、ビジネスの継続性を確保することが可能になる。","explanationZh":"服务在约定时间内能够按要求被用户使用的程度。常以可用时间占计划服务时间的比例衡量，并受到故障频率和恢复速度影响。"},{"id":"t0732","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"信頼性","termZh":"可靠性","english":"Reliability","reading":"しんらいせい","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやサービスが正常に機能し、安定して運用される能力を指す。特にサービス可用性管理においては、信頼性が高いほど、ユーザーや顧客がそのサービスを利用できる時間が増える。例えば、オンラインバンキングやクラウドストレージのようなサービスでは、システムのダウンタイムを最小限に抑えることが求められる。信頼性を向上させるためには、障害の迅速な検出や回復、冗長性の確保などが重要であり、これにより利用者の満足度を高めることができる。加えて、高い信頼性はブランドの信頼を築く基盤となり、競争力を高める要因となる。","explanationZh":"系统或服务在规定条件和时间内持续无故障地完成所需功能的能力。可靠性高意味着故障发生概率较低，常可通过MTBF等指标评价。"},{"id":"t0733","chapterId":"c35","chapterJa":"サービスマネジメントシステムの計画及び運用","chapterZh":"服务管理体系的策划与运行","termJa":"保守性","termZh":"可维护性","english":"Maintainability","reading":"ほしゅせい","breadcrumb":"7 サービスマネジメント7-2 サービスマネジメントシステムの計画及び運用","explanationJa":"システムやサービスが運用中に発生した問題を迅速に修正したり、機能を変更したりする能力のことを指す。高い保守性を持つシステムは、トラブルが発生した際に迅速に対応できるため、ダウンタイムを短縮し、サービスの可用性を向上させる。例えば、ソフトウェアのバグ修正や機能追加などの作業が簡単であると、運用チームは問題に即座に対処することができる。また、保守性が高いシステムは、将来的な技術の変更や更新にも柔軟に対応できるため、コスト削減や効率向上にも寄与することが期待される。","explanationZh":"系统发生故障或需要变更时，能够方便、快速并正确地维修、恢复或维护的程度。提高可维护性有助于缩短MTTR并提升可用性。"},{"id":"t0734","chapterId":"c36","chapterJa":"パフォーマンス評価及び改善","chapterZh":"绩效评价与改进","termJa":"パフォーマンス評価","termZh":"绩效评价","english":"Performance Evaluation","reading":"ぱふぉーまんすひょうか","breadcrumb":"7 サービスマネジメント7-3 パフォーマンス評価及び改善","explanationJa":"システムやプロセスの効率や効果を測定する手法である。この評価は、特にコンピュータシステムやソフトウェアの性能を確認するために重要で、処理速度やメモリ使用量、応答時間など、さまざまな指標を用いて行われる。例えば、Webサイトのパフォーマンス評価では、ページがどれだけ早く表示されるかや、ユーザーが操作する際の遅延の有無を確認することが含まれる。これにより、改善点を見つけ出し、最適化を図ることができるため、使用者の満足度を向上させることが期待される。また、企業の業務プロセスにおいてもパフォーマンス評価は行われ、生産性やコスト効率を測る際に役立つ。","explanationZh":"对服务和服务管理体系的目标达成情况、有效性和趋势进行测量、分析和评审的活动。可利用KPI、SLA、审核、客户反馈和管理评审等信息识别改进机会。"},{"id":"t0735","chapterId":"c36","chapterJa":"パフォーマンス評価及び改善","chapterZh":"绩效评价与改进","termJa":"サービスの報告","termZh":"服务报告","english":"Service Report","reading":"さーびすのほうこく","breadcrumb":"7 サービスマネジメント7-3 パフォーマンス評価及び改善","explanationJa":"提供されたサービスの内容やその結果をまとめて報告する文書やプロセスを指す。通常、サービスの質や顧客の満足度、業務の進捗などに関する情報が含まれる。この報告は、企業や組織が顧客に対して透明性を持たせるためや、内部の改善を図るために重要である。例えば、カスタマーサポートチームが行った対応の結果を記載し、クライアントにフィードバックを提供するケースがある。これにより、サービスの改善点や将来の対策を明確にすることができ、顧客との信頼関係を築く助けにもなる。","explanationZh":"定期向客户、管理层和相关方提供服务绩效、SLA达成情况、事件、容量、可用性和改进事项等信息的报告。报告应准确、可理解并支持决策。"},{"id":"t0736","chapterId":"c36","chapterJa":"パフォーマンス評価及び改善","chapterZh":"绩效评价与改进","termJa":"パフォーマンス","termZh":"绩效","english":"Performance","reading":"","breadcrumb":"7 サービスマネジメント7-3 パフォーマンス評価及び改善","explanationJa":"特定のタスクやサービスに対する効率や効果を示す指標である。サービスの報告では、パフォーマンスはシステムやアプリケーションがどれだけ迅速に動作するか、またはどれだけ多くのリクエストに応えられるかを測定するために使用される。例えば、Webサイトの読み込み速度やサーバの応答時間などがこれに該当する。良好なユーザーの満足度やビジネスの成功に直結するため、多くの企業は常にこの指標を改善しようと努めている。データ分析ツールを活用してパフォーマンスを監視することは、問題の早期発見や対策に役立つ。","explanationZh":"服务、过程、团队或管理体系实现预定目标的可测量结果。绩效评价应关注结果趋势和目标，而不仅是活动数量。"},{"id":"t0737","chapterId":"c36","chapterJa":"パフォーマンス評価及び改善","chapterZh":"绩效评价与改进","termJa":"傾向情報","termZh":"趋势信息","english":"Trend Information","reading":"けいこうじょうほう","breadcrumb":"7 サービスマネジメント7-3 パフォーマンス評価及び改善","explanationJa":"特定のデータやイベントの変化やパターンを示す情報である。主にサービスの報告において顧客の行動やニーズの変化を把握するために活用される。この情報は、売上の推移や顧客満足度の変化など、時間とともに変わるデータの分析によって得られる。例えば、ある商品の売上が特定の季節に増加する傾向が見られる場合、企業はその季節に合わせたマーケティング戦略を立てることができる。また、競合分析や市場調査にも役立ち、企業の経営判断を支える重要な要素となる。これにより、より効果的なサービス提供を実現することが可能である。","explanationZh":"反映指标在一段时间内上升、下降或周期变化等趋势的数据。通过趋势信息可预测容量、发现反复问题并判断改进措施是否有效。"},{"id":"t0738","chapterId":"c36","chapterJa":"パフォーマンス評価及び改善","chapterZh":"绩效评价与改进","termJa":"不適合及び是正処置","termZh":"不符合与纠正措施","english":"Nonconformity and Corrective Action","reading":"ふてきごうおよびぜせいしょち","breadcrumb":"7 サービスマネジメント7-3 パフォーマンス評価及び改善","explanationJa":"品質管理のプロセスにおいて重要な概念である。不適合は、製品やサービスが設定された基準や要求事項を満たさない状態を指し、例えば生産された製品が規格に合わない場合がこれに該当する。このような不適合が発生した際には、その原因を特定し、再発防止のために是正処置を取る必要がある。是正処置とは、不適合の根本原因を取り除くための具体的なアクションであり、プロセスやシステムの改善を促すものである。これにより、将来の不適合を防ぎ、品質の向上を図ることが可能となる。継続的な改善を目指す企業にとって、これらの取り組みは不可欠である。","explanationZh":"当实际做法不满足规定要求时，应先控制和纠正问题，再分析根因并采取措施防止再次发生。还应验证措施有效性，并在必要时更新风险和管理体系。"},{"id":"t0739","chapterId":"c36","chapterJa":"パフォーマンス評価及び改善","chapterZh":"绩效评价与改进","termJa":"継続的改善","termZh":"持续改进","english":"Continuous Improvement","reading":"けいぞくてきかいぜん","breadcrumb":"7 サービスマネジメント7-3 パフォーマンス評価及び改善","explanationJa":"企業や組織が業務プロセスや製品の品質を持続的に向上させるための手法である。この概念は、少しずつ改善を積み重ねていくことで、長期的に大きな成果を得ることを目指す。具体的には、業務フローの見直しやフィードバックの収集を通じて問題点を把握し、解決策を実行していく。例えば、製造業においては生産ラインの効率を向上させるために作業手順を見直したり、サービス業では顧客からの声をもとにサービス内容を改善することが挙げられる。このような取り組みは、組織全体のパフォーマンス向上に寄与し、競争力を高めることにつながる。","explanationZh":"持续寻找并实施提高服务、过程和管理体系适宜性、充分性和有效性的机会。可通过PDCA、指标分析、审核、事件经验和客户反馈不断优化。"},{"id":"t0740","chapterId":"c37","chapterJa":"サービスの運用","chapterZh":"服务运营","termJa":"システム運用管理","termZh":"系统运行管理","english":"System Operation Management","reading":"しすてむうんようかんり","breadcrumb":"7 サービスマネジメント7-4 サービスの運用","explanationJa":"情報システムが日常的に正しく稼働するように、必要な作業や管理を行うことを指す。この分野では、システムの監視、保守、トラブルシューティングなどが含まれ、安定したサービスを提供するために重要な役割を果たす。具体的には、サーバの正常状態を監視し、障害が発生した際には迅速に対応することで、業務の継続性を確保する。さらに、バックアップやセキュリティ対策なども重要な要素であり、情報の保護やデータの復旧を安全に行うための計画を立てることも求められる。これにより、企業の業務運用が円滑に進むことが支援される。","explanationZh":"对信息系统投入生产后的日常运行进行计划、执行、监控和改进的管理。包括作业、账号、备份、性能、故障、变更、安全和文档等，以保持服务稳定和可控。"},{"id":"t0741","chapterId":"c37","chapterJa":"サービスの運用","chapterZh":"服务运营","termJa":"運用オペレーション","termZh":"运行操作","english":"Operational Operations","reading":"うんようおぺれーしょん","breadcrumb":"7 サービスマネジメント7-4 サービスの運用","explanationJa":"情報システムやサービスが正常に機能するための日常的な管理や運営のことを指す。これには、システムの監視、トラブルシューティング、パフォーマンスの最適化などが含まれる。具体的には、サーバやネットワークの状態をチェックし、障害が発生した場合には迅速に対応することが求められる。また、定期的なバックアップやソフトウェアのアップデートも運用オペレーションの重要な要素であり、これによりデータの安全性を確保し、サービスの品質を維持することが可能となる。例えば、企業がクラウドサービスを利用する場合、運用オペレーションはそのサービスが常に安定して稼働するように管理される。","explanationZh":"为维持系统正常服务而执行的日常操作活动，例如启动停止、批处理、备份、监控、日志检查和例行维护。应采用标准操作程序并保留记录，减少人为错误。"},{"id":"t0742","chapterId":"c37","chapterJa":"サービスの運用","chapterZh":"服务运营","termJa":"サービスデスク","termZh":"服务台","english":"Service Desk","reading":"","breadcrumb":"7 サービスマネジメント7-4 サービスの運用","explanationJa":"ITサービスの利用者からの問い合わせや問題を受け付け、解決を支援する部門や機能である。主に、ユーザーのサポートや問題解決を行うための窓口となり、電話やメール、専用のチケットシステムを通じて運用される。例えば、社内の従業員がパソコンのトラブルで困った際に、サービスデスクに連絡することで、適切なサポートを受けることができる。問題の早期解決だけでなく、ユーザーの満足度を高める役割も担っており、効率的な業務運営を支える重要な部分となっている。また、記録された問い合わせ情報は、今後の改善や分析に役立てられる。","explanationZh":"为用户提供统一联系窗口的服务支持职能，负责接收事件和服务请求、初步诊断、解答、跟踪和升级。良好的服务台能够提高用户体验并集中掌握服务问题。"},{"id":"t0743","chapterId":"c38","chapterJa":"ファシリティマネジメント","chapterZh":"设施管理","termJa":"ファシリティマネジメント","termZh":"设施管理（Facility Management）","english":"Facility Management","reading":"","breadcrumb":"7 サービスマネジメント7-5 ファシリティマネジメント","explanationJa":"企業や組織の資産や施設を効率的に運用・管理する手法である。この管理には、建物の維持管理、環境整備、人的資源の最適化などが含まれ、これらを通じて業務の効率化やコスト削減を実現することが目的である。例えば、オフィスビルの空間を有効利用するために、レイアウトを見直したり、エネルギー効率を向上させるための設備投資を行うことが挙げられる。また、良好な作業環境を提供することにより、従業員の生産性向上にも寄与する。単に施設を管理するだけでなく、組織全体の戦略的な運営に直結する重要な役割を果たしている。","explanationZh":"对支持信息系统的建筑、机房、电力、空调、消防、安防等设施进行规划、运行和维护的管理活动。目标是保证设施安全、可靠并满足业务连续性要求。"},{"id":"t0744","chapterId":"c38","chapterJa":"ファシリティマネジメント","chapterZh":"设施管理","termJa":"施設管理","termZh":"设施管理","english":"Facility Management","reading":"しせつかんり","breadcrumb":"7 サービスマネジメント7-5 ファシリティマネジメント","explanationJa":"建物や施設の運営、保守、そして管理を総合的に行うプロセスを指す。具体的には、施設の利用効率を向上させ、住環境や作業環境を快適に保つことが目指される。例えば、オフィスビルの清掃管理や設備の点検・修理、エネルギーの効率的な使用、利用者の安全確保などが含まれる。総合的なアプローチを通じて、建物の価値を高め、長寿命化を図る重要な役割を果たしている。さらに、テクノロジーの活用により、業務の効率化やより良いサービスの提供も実現可能である。","explanationZh":"对办公场所、数据中心和相关建筑环境进行维护与控制，包括空间、门禁、消防、温湿度、电力等。它构成信息系统物理安全的重要部分。"},{"id":"t0745","chapterId":"c38","chapterJa":"ファシリティマネジメント","chapterZh":"设施管理","termJa":"設備管理","termZh":"设备管理","english":"Facility Management","reading":"せつびかんり","breadcrumb":"7 サービスマネジメント7-5 ファシリティマネジメント","explanationJa":"建物や施設内の電気設備や空調設備などを効果的に運営・維持するための管理技術である。具体的には、設備が安全に運用されるように定期点検やメンテナンスを行い、故障や劣化を防ぐことが重要である。例えば、空調設備のフィルター清掃や点検は、快適な室内環境を維持し、エネルギー効率を向上させるために欠かせない。また、設備の稼働状況をモニタリングし、必要に応じて修理や交換を行うことで、施設全体の機能を最大限に保つことができる。このように快適な住環境の提供やコスト削減に貢献する重要な業務である。","explanationZh":"对电源、空调、消防、通信和机房设备等进行检查、维护、故障处理和更新的管理。通过预防性维护降低设备故障对业务的影响。"},{"id":"t0746","chapterId":"c38","chapterJa":"ファシリティマネジメント","chapterZh":"设施管理","termJa":"UPS","termZh":"不间断电源（UPS）","english":"Uninterruptible Power Supply","reading":"ゆーぴーえす","breadcrumb":"7 サービスマネジメント7-5 ファシリティマネジメント","explanationJa":"無停電電源装置のことである。主に電力供給が途切れた際に、一時的に電力を提供する役割を持つ。この装置は、停電や電力の質が急激に変化した場合でも、コンピュータやサーバなど重要な機器が正常に動作し続けることを可能にする。例えば、企業内のサーバがUPSによってバックアップされている場合、突然の停電が発生しても、数分から1時間程度は電力を供給し続けられる。そのため、データの消失や業務の中断を防ぐ重要な設備であり、特に金融機関やデータセンターなど、常に稼働が求められる環境で広く利用されている。\nHOME»用語集»システム監査»システム監査","explanationZh":"市电中断或异常时为关键设备临时供电的设备，可避免突然断电导致系统停止或数据损坏，并为切换发电机或安全关机争取时间。"},{"id":"t0747","chapterId":"c39","chapterJa":"システム監査","chapterZh":"系统审计","termJa":"情報システムの利活用に係る検証・評価","termZh":"信息系统利用情况的验证与评价","english":"Verification and Evaluation of Information System Utilization","reading":"じょうほうしすてむのりかつようにかかるけんしょう・ひょうか","breadcrumb":"8 システム監査8-1 システム監査","explanationJa":"企業や組織が導入した情報システムが、目的に対して効果的に機能しているかを確認するプロセスである。これには、システムの運用状況や成果を詳細に分析し、使用効率や業務改善への貢献度を評価することが含まれる。例えば、業務プロセスの改善を目的として新しいシステムを導入した場合、その後の業務の効率化やコスト削減といった成果を検証し、必要な改良点を特定することが求められる。このような評価によって、情報システムの価値を最大化し、投資の効果を高めることが可能になる。また、システム監査の一環としても行われ、情報セキュリティやコンプライアンスの観点からも重要な役割を果たしている。","explanationZh":"对信息系统是否按预期被使用、是否产生业务价值以及安全、效率和合规情况进行检查和评价。结果可用于决定改善、改造、继续使用或废止。"},{"id":"t0748","chapterId":"c39","chapterJa":"システム監査","chapterZh":"系统审计","termJa":"システム監査の体制整備","termZh":"建立系统审计体制","english":"Establishment of System Audit Framework","reading":"しすてむかんさのたいせいせいび","breadcrumb":"8 システム監査8-1 システム監査","explanationJa":"システムの運用や管理が適切であるかを確認するための組織的な仕組みを整えることである。この体制整備には、監査を実施する専門チームの編成や、監査基準の確立、監査計画の策定が含まれる。例えば、企業内での情報システムのセキュリティやデータ管理の状況を定期的にチェックするためのルールを定めることで、リスクを低減し、業務の信頼性を向上させることが可能となる。また、監査結果を基に改善策を提案し、システムの品質向上を目指すことで、企業全体の効率化にも寄与することが期待される。","explanationZh":"为独立、有效开展系统审计而明确审计组织、权限、责任、流程、资源和报告渠道。审计体制应保证审计人员能够获取必要证据并保持适当独立性。"},{"id":"t0749","chapterId":"c39","chapterJa":"システム監査","chapterZh":"系统审计","termJa":"監査人の倫理","termZh":"审计人员伦理","english":"Ethics of Auditors","reading":"かんさにんのりんり","breadcrumb":"8 システム監査8-1 システム監査","explanationJa":"システム監査において監査人が遵守すべき価値観や行動基準を指す言葉である。監査人は、企業や組織の情報システムの妥当性や信頼性を評価する役割を担っており、その業務を公正かつ誠実に行うことが求められる。この倫理基準には、守秘義務、利益相反の回避、及び透明性が含まれ、監査の信頼性を保つために重要である。また、監査人が倫理を守ることで、関係者からの信頼を得ることができ、効果的な監査業務を実現することが可能となる。倫理的な行動が基盤にあることで、システム監査は組織の健全な運営に寄与する。","explanationZh":"审计人员应遵守诚信、公正、客观、保密和专业胜任等职业道德要求。不得利用审计中获得的信息谋取不当利益，也应避免利益冲突。"},{"id":"t0750","chapterId":"c39","chapterJa":"システム監査","chapterZh":"系统审计","termJa":"監査の独立性と客観性の保持","termZh":"保持审计独立性和客观性","english":"Maintaining Auditor Independence and Objectivity","reading":"かんさのどくりつせいときゃっかんせいのほじ","breadcrumb":"8 システム監査8-1 システム監査","explanationJa":"監査が信頼性を持つために必要な原則である。監査を行う際、監査人は自らの判断に影響を及ぼす可能性のある利害関係や偏見から完全に独立していることが求められる。例えば、企業の財務状態を監査する場合、監査人がその企業と密接な関係を持っていると、結果が誤ってしまう恐れがある。したがって、監査人は客観的な視点を保ち、透明性のある評価を行うことが必要である。この保持により、ユーザーは監査報告書に対して信頼を置くことができ、企業のガバナンスを強化することにも寄与する。客観的な監査は、適切なリスク管理やコンプライアンスの遵守を確認するための基本でもある。","explanationZh":"审计人员在组织关系和判断上应避免受到被审计部门或个人的不当影响。独立性和客观性能够提高审计结论的可信度和公正性。"},{"id":"t0751","chapterId":"c39","chapterJa":"システム監査","chapterZh":"系统审计","termJa":"監査の能力及び正当な注意と秘密の保持","termZh":"审计能力、应有的注意及保密","english":"Audit Capability and Due Care and Confidentiality","reading":"かんさののうりょくおよびせいとうなちゅういとひみつのほじ","breadcrumb":"8 システム監査8-1 システム監査","explanationJa":"システム監査における重要な概念である。監査の能力は、監査人が情報システムのリスクや脆弱性を評価し、適切な対策を提案できる専門知識や技術を指す。正当な注意とは、監査の実施において慎重かつ適切に行動することを意味し、これにより監査の信頼性が向上する。また、秘密の保持は、監査過程で取得した機密情報を守る責任を強調するものであり、顧客や組織のデータが不正に流出するリスクを低減させる役割を果たす。これらの要素は、システム監査が効果的に機能するために欠かせない重要な基盤である。","explanationZh":"审计人员应具备完成审计所需的知识和技能，以专业人员应有的谨慎态度开展工作，并对审计中获得的机密信息严格保密。这些是高质量审计的基本要求。"},{"id":"t0752","chapterId":"c39","chapterJa":"システム監査","chapterZh":"系统审计","termJa":"システム監査計画","termZh":"系统审计计划","english":"System Audit Plan","reading":"しすてむかんさけいかく","breadcrumb":"8 システム監査8-1 システム監査","explanationJa":"システム監査を実施するための具体的な計画を指す。この計画には、監査の目的、範囲、方法、スケジュール、および必要なリソースが明示される。たとえば、企業が新しい情報システムを導入する際、そのシステムが適切に機能しているか、セキュリティが確保されているかを確認するために、システム監査計画が策定される。計画には、監査チームのメンバーや、監査の対象となるシステムの詳細、評価基準なども含まれ、監査の透明性と効率性を高める役割を果たす。このプロセスを通じて、企業はリスクを管理し、業務の信頼性を向上させることができる。","explanationZh":"规定系统审计目标、范围、对象、时间、人员、方法、重点风险和资源安排的计划。审计计划应基于风险并与组织需要相匹配，为证据收集和评价提供方向。"},{"id":"t0753","chapterId":"c39","chapterJa":"システム監査","chapterZh":"系统审计","termJa":"監査証拠の入手と評価","termZh":"获取与评价审计证据","english":"Acquisition and Evaluation of Audit Evidence","reading":"かんさしょうこのにゅうしゅとひょうか","breadcrumb":"8 システム監査8-1 システム監査","explanationJa":"システム監査において監査を行うために必要な情報やデータを収集し、その信頼性や妥当性を評価する過程を指す。監査証拠は、システムの安全性や効果性を確認するための根拠であり、収集された証拠は監査結果を支える重要な要素となる。例えば、ログファイルや取引記録、ユーザーインタビューの結果などが監査証拠として利用される。これらの証拠は、適切な方法で収集され、評価される必要があり、その信頼性を高めるために、証拠の出所や収集方法を明確にすることが求められる。監査証拠の質によって、監査結果の妥当性が左右されるため、正確な入手と評価が不可欠である。","explanationZh":"通过访谈、观察、文档检查、日志、抽样和测试等方式取得足够且适当的证据，并据此判断控制是否有效。证据应具有可靠性、相关性和可验证性。"},{"id":"t0754","chapterId":"c39","chapterJa":"システム監査","chapterZh":"系统审计","termJa":"システム監査報告書の作成と報告","termZh":"编制与报告系统审计报告","english":"Creation and Reporting of System Audit Reports","reading":"しすてむかんさほうこくしょのさくせいとほうこく","breadcrumb":"8 システム監査8-1 システム監査","explanationJa":"システム監査の結果を文書化し、関係者に伝えるプロセスである。この報告書は、監査の目的、方法、結果、および改善の提案を含む重要な文書である。まず、システムの運用状況やリスクを評価し、問題点を特定することが重要である。その後、詳細な観察内容や評価結果を基に報告書を作成し、関係者に提出する。これにより、企業は業務の効率化やセキュリティ向上に向けた施策を検討できる。定期的な報告によって、システムの健全性を保ち、組織の信頼性を向上させることが期待される。","explanationZh":"把审计目的、范围、发现、证据、结论及改善建议形成正式报告并提交适当管理层的过程。报告应客观、清晰，并区分事实、风险和建议。"},{"id":"t0755","chapterId":"c39","chapterJa":"システム監査","chapterZh":"系统审计","termJa":"改善提案のフォローアップ","termZh":"改善建议跟踪","english":"Improvement Proposal Follow-Up","reading":"かいぜんていあんのふぉろーあっぷ","breadcrumb":"8 システム監査8-1 システム監査","explanationJa":"システム監査の結果に基づいて行われる改善提案を、実施状況や効果を確認するために追跡するプロセスである。このフォローアップは、提案が実際に実行され、期待どおりの効果が得られているかを検証する目的を持つ。具体的には、提案が反映されたシステムやプロセスの運用状況を定期的にレビューし、必要に応じて追加の改善策を講じることが求められる。これにより、監査で指摘された課題が解消されるだけでなく、組織全体の業務効率を高めることができる。また、フォローアップの結果は次回の監査活動にも活かされ、継続的な改善に寄与するため、重要なステップとされている。","explanationZh":"审计报告提出整改建议后，持续确认责任部门是否按计划实施、问题是否真正解决以及残余风险是否可接受的活动。跟踪能够防止审计发现停留在纸面上。"},{"id":"t0756","chapterId":"c39","chapterJa":"システム監査","chapterZh":"系统审计","termJa":"情報セキュリティ監査基準","termZh":"信息安全审计标准","english":"Information Security Audit Standards","reading":"じょうほうせきゅりてぃかんさきじゅん","breadcrumb":"8 システム監査8-1 システム監査","explanationJa":"情報資産を保護するためのセキュリティ対策が適切に実施されているかを評価するための基準である。これらの基準は、企業や組織が情報セキュリティの状況を客観的に確認し、必要な改善点やリスクを洗い出すのに役立つ。例えば、定期的に実施される監査によって、パスワードの管理や物理的なアクセス制御、データの暗号化の状況などがチェックされることが多い。その結果、セキュリティの脆弱性や問題が早期に発見され、適切な対策を講じることで情報漏洩やサイバー攻撃のリスクを軽減することができる。組織が安全な情報管理を実現するために重要な役割を果たしている。","explanationZh":"规定信息安全审计应遵循的基本原则、审计人员要求、计划、实施、证据和报告等要求的标准。其目的在于提高安全审计的一致性和可信度。"},{"id":"t0757","chapterId":"c39","chapterJa":"システム監査","chapterZh":"系统审计","termJa":"情報セキュリティ管理基準","termZh":"信息安全管理标准","english":"Information Security Management Standards","reading":"じょうほうせきゅりてぃかんりきじゅん","breadcrumb":"8 システム監査8-1 システム監査","explanationJa":"組織が情報を安全に管理するためのルールやガイドラインを示すものである。これらの基準は、情報資産を守るために必要なポリシーや手続き、リスク管理の手法を含む。例えば、ISO 27001という国際的な基準があり、これは情報セキュリティのシステムを構築し、運用するためのフレームワークを提供している。このような基準を採用することで、企業はデータ漏洩や不正アクセスのリスクを低減し、顧客や取引先からの信頼を得ることが可能になる。情報セキュリティの確保は、現代の社会において非常に重要な課題であり、基準を遵守することは組織の持続可能な運営に寄与する。","explanationZh":"为组织系统实施信息安全管理和控制提供要求或参考的标准体系。它通常涵盖方针、风险管理、人员、资产、访问控制、事件和持续改进等内容。"},{"id":"t0758","chapterId":"c39","chapterJa":"システム監査","chapterZh":"系统审计","termJa":"行動指針","termZh":"行为准则","english":"Code of Conduct","reading":"こうどうししん","breadcrumb":"8 システム監査8-1 システム監査","explanationJa":"組織や企業が求める行動の基準を明確に示したものである。これは、全ての従業員が倫理的かつ法令を遵守した行動を取るための指導原則であり、コンプライアンス監査においては特に重要な要素となる。具体的には、適切なビジネス慣行や職場での人間関係、顧客との接し方などが含まれる。例えば、贈収賄の禁止、情報漏洩の防止、職場でのハラスメントに対する対策などが具体例として挙げられる。従業員が自身の行動を反省し、適切な判断をするための参考となるものであり、健全な企業文化の形成にも寄与する。","explanationZh":"规定组织成员在工作中应遵守的伦理、合规和专业行为要求的规则。可包括利益冲突、保密、反舞弊、信息系统使用和举报机制等。"},{"id":"t0759","chapterId":"c39","chapterJa":"システム監査","chapterZh":"系统审计","termJa":"倫理","termZh":"伦理","english":"Ethics","reading":"りんり","breadcrumb":"8 システム監査8-1 システム監査","explanationJa":"社会や組織における行動や考え方の基準を示す理念である。個人や集団が「正しい行動」と「間違った行動」を判断するための指針として機能し、人々がどのように他者と接し、どのような価値観を持つべきかを考える際に重要である。たとえば、企業においては、倫理が遵守されることで、透明性や誠実さが保たれ、顧客や従業員との信頼関係が築かれる。コンプライアンス監査では、法律や規則を守るだけでなく、倫理的な行動が実践されているかどうかも評価される。これにより、組織全体の健全な運営や社会的評価の向上が図られる。","explanationZh":"判断行为是否符合诚实、公正、责任和社会规范的原则体系。信息工作者除遵守法律外，还应考虑隐私、社会影响和专业责任等伦理要求。"},{"id":"t0760","chapterId":"c39","chapterJa":"システム監査","chapterZh":"系统审计","termJa":"透明性","termZh":"透明度","english":"Transparency","reading":"とうめいせい","breadcrumb":"8 システム監査8-1 システム監査","explanationJa":"情報やプロセスが明確で、関係者が容易に理解できる状態を指す。特にコンプライアンス監査の分野においては、企業や組織の運営が適切であることを確認するために、透明性が非常に重要である。たとえば、企業が財務情報を公開し、意思決定のプロセスを説明することで、外部のステークホルダーや一般市民の信頼を得ることができる。透明性はまた、不正行為の予防にも寄与し、企業文化の向上にもつながる。企業が透明性を重視することで、リスク管理や法令遵守が効果的に行われ、信頼性のある経営が実現される。","explanationZh":"组织对规则、决策、数据处理和责任等重要事项以适当方式向相关方公开并可被理解的程度。透明度有助于建立信任和问责，但不意味着公开机密信息。"},{"id":"t0761","chapterId":"c39","chapterJa":"システム監査","chapterZh":"系统审计","termJa":"権利侵害行為への指摘","termZh":"指出权利侵害行为","english":"Pointer to Rights Infringement","reading":"けんりしんがいこういへのしてき","breadcrumb":"8 システム監査8-1 システム監査","explanationJa":"他者の権利が侵害されている状況を指摘する行為である。例えば、著作権や商標権などが不正に使用されている場合、その行為を明らかにすることが求められる。この指摘はコンプライアンス監査において重要な役割を果たし、企業や組織が法律や規則を遵守しているかどうかを確認する手段となる。権利侵害の早期発見は、法的トラブルを未然に防ぎ、信頼性のあるビジネス環境を維持するために不可欠である。また、指摘を受けた側は、必要に応じて適切な対策を講じることで、問題を解決し、再発防止に努めることが期待される。","explanationZh":"发现侵害个人、组织或知识产权等合法权利的行为时，按照适当渠道提出、报告或纠正问题。组织应建立能够安全报告问题并保护相关人员的机制。"},{"id":"t0762","chapterId":"c39","chapterJa":"システム監査","chapterZh":"系统审计","termJa":"労働環境における問題点への指摘","termZh":"指出劳动环境问题","english":"Identifying Issues in Labor Environment","reading":"ろうどうかんきょうにおけるもんだいてんへのしてき","breadcrumb":"8 システム監査8-1 システム監査","explanationJa":"職場における労働条件や従業員の権利、職業安全に関する問題を明らかにする行為である。具体的には、長時間労働、不当な賃金、劣悪な作業環境などが含まれる。これらの問題を指摘することで、企業は法令遵守を実現し、健全な職場環境を整えるきっかけを得る。コンプライアンス監査では、これらの問題がどのように影響を与えているかを評価し、改善策を提案することが不可欠である。これにより、労働者の権利が尊重される職場が確保され、企業の持続可能な成長が促進される。\nHOME»用語集»システム監査»内部統制","explanationZh":"对职场安全、骚扰、不公正待遇、违法劳动管理等问题进行识别和报告的行为。适当的内部举报和咨询渠道有助于早期纠正问题和改善组织治理。"},{"id":"t0763","chapterId":"c40","chapterJa":"内部統制","chapterZh":"内部控制","termJa":"職務分掌","termZh":"职责分离","english":"Job Responsibilities","reading":"しょくむぶんしょう","breadcrumb":"8 システム監査8-2 内部統制","explanationJa":"企業や組織において、各社員や部門の役割や責任を明確にするプロセスを指す。内部統制の観点から、これは業務が適切に運営され、リスクを管理するために重要である。例えば、経理部門が財務管理を担当し、営業部門が顧客対応を行う際に、それぞれの職務が明確に分かれていることで、不正やミスを防ぎやすくなる。また、職務分掌が適切に行われていると、業務の効率性が向上し、各自の責任が明確化されるため、組織全体の透明性が増す。これは、特に監査やコンプライアンスの観点からも重要であり、企業の信頼性や持続可能性を高める要素となる。","explanationZh":"把具有冲突风险的业务职责分配给不同人员或角色，避免单个人能够独立完成并隐藏不当行为。例如申请、批准、执行和复核应尽可能分离，是内部控制的重要原则。"},{"id":"t0764","chapterId":"c40","chapterJa":"内部統制","chapterZh":"内部控制","termJa":"内部統制の限界","termZh":"内部控制的局限性","english":"Limitations of Internal Control","reading":"ないぶとうせいのげんかい","breadcrumb":"8 システム監査8-2 内部統制","explanationJa":"企業や組織が導入する内部統制制度の有効性が、必ずしも完璧ではないことを示す概念である。内部統制は、財務報告の信頼性や業務の効率性を向上させる目的で設計されているが、それ自体にはいくつかの制約が存在する。例えば、人的要因によるミスや不正、環境の変化、新たなリスクの出現などが内部統制の効果を損なう可能性がある。また、内部統制はリソースを要するため、過剰な管理が業務の妨げになることもある。このため、企業は内部統制を有効に機能させるため、絶えずその限界を認識し、改善策を継続的に講じる必要がある。","explanationZh":"内部控制只能提供合理保证，无法完全消除所有风险。人员串通、管理层越权、人为错误、成本限制和环境变化等都可能使控制失效，因此需要持续监控和改进。"},{"id":"t0765","chapterId":"c40","chapterJa":"内部統制","chapterZh":"内部控制","termJa":"実施ルールの設定","termZh":"制定实施规则","english":"Establishment of Implementation Rules","reading":"じっしるーるのせってい","breadcrumb":"8 システム監査8-2 内部統制","explanationJa":"組織内での業務やプロセスを円滑に進めるために、具体的な行動や手順を定めることを指す。特に内部統制においては、業務の透明性や効率性を確保するために必要である。例えば、財務報告プロセスにおいては、データの収集や検証の手順を明確にすることで、誤りを防ぎ、信頼性を向上させることができる。実施ルールは、従業員が一貫して業務を遂行できるようにし、また規制や法令の遵守を促進する役割も果たす。これにより、組織全体のリスクを軽減し、持続可能な運営を支援することが可能となる。","explanationZh":"把上位方针和制度细化为可执行的操作规则、流程和责任要求。规则应明确、可理解、可检查，并根据业务和风险变化及时更新。"},{"id":"t0766","chapterId":"c40","chapterJa":"内部統制","chapterZh":"内部控制","termJa":"チェック体制の確立","termZh":"建立检查体制","english":"Establishment of Check System","reading":"ちぇっくたいせいのかくりつ","breadcrumb":"8 システム監査8-2 内部統制","explanationJa":"内部統制において、業務やプロセスが正しく行われているかどうかを確認するための仕組みを整えることを指す。この体制があることで、不正や誤りを早期に発見し、修正することが可能になる。具体的には、定期的な監査やレビュー、業務手順のマニュアル化が含まれる。例えば、企業で金銭取引のチェック体制を確立することで、誤った支払いを防ぎ、資産を守ることができる。このように、チェック体制は組織の信頼性を高め、持続的な成長を支える基盤となる。","explanationZh":"通过复核、审批、监督、审计和交叉检查等建立对业务执行结果进行验证的机制。它有助于发现错误、违规和舞弊，确保制度得到实际执行。"},{"id":"t0767","chapterId":"c40","chapterJa":"内部統制","chapterZh":"内部控制","termJa":"ITが内部統制に果たす役割","termZh":"IT在内部控制中的作用","english":"Role of IT in Internal Control","reading":"あいてぃーがないぶとうせいにはたすやくわり","breadcrumb":"8 システム監査8-2 内部統制","explanationJa":"情報技術が組織の業務活動を適切に管理し、リスクを最小限に抑えるための仕組みを提供することを指す。具体的には、データの正確性や一貫性を保証するためのシステムやツールの導入が含まれる。例えば、業務プロセスの自動化によりヒューマンエラーを低減し、アクセス管理や監査トレイルによって不正行為を防ぐことが可能である。また、リアルタイムでのデータ分析を通じて、リスクの早期発見や意思決定の支援を行うことも重要である。このように、ITは内部統制の効果を高め、組織全体の健全性を維持するために極めて重要な役割を担っている。","explanationZh":"IT既可通过自动化审批、权限、日志和数据校验强化内部控制，也会引入系统故障、权限配置和程序错误等新风险。因此需要同时管理IT一般控制和应用控制。"},{"id":"t0768","chapterId":"c40","chapterJa":"内部統制","chapterZh":"内部控制","termJa":"リスクの評価と対応","termZh":"风险评估与应对","english":"Risk Assessment and Response","reading":"りすくのひょうかとたいおう","breadcrumb":"8 システム監査8-2 内部統制","explanationJa":"組織が直面する可能性のあるリスクを特定し、その影響度や発生可能性を分析し、適切な対策を講じるプロセスである。内部統制の一環として、リスクを評価することにより、リスクが業務に与える影響を理解し、経営の安定性を高めることが目指される。例えば、情報セキュリティのリスクがある場合、そのリスクを特定し、データの保護対策やアクセス権の管理を通じて対応することが求められる。その結果、潜在的な損失を最小限に抑え、組織が健全に運営できるようにすることが重要である。企業のリスクマネジメントにおいて欠かせないステップである。","explanationZh":"识别可能影响组织目标的风险，分析发生可能性和影响，并选择规避、降低、转移或接受等应对方式。内部控制应根据风险评估结果配置相应控制活动。"},{"id":"t0769","chapterId":"c40","chapterJa":"内部統制","chapterZh":"内部控制","termJa":"統制活動","termZh":"控制活动","english":"Control Activities","reading":"とうせいかつどう","breadcrumb":"8 システム監査8-2 内部統制","explanationJa":"企業が内部で不正や誤りを防止するために実施する手続きを指す。これには、業務の効率性や法令遵守を確保するための対策が含まれる。具体的には、取引の承認プロセス、職務分掌の明確化、資産の管理などが挙げられる。例えば、ある企業では大きな支出が発生する際に、複数の担当者の承認を必要とする仕組みを導入して、不正な支出を防ぐことができる。さらに、定期的な監査を通じてこれらの活動が機能しているかどうかを確認し、改善を図ることも統制活動の一環である。こうした仕組みによって、企業は持続可能な経営を実現しやすくなる。","explanationZh":"为降低风险、确保管理层指令得到执行而设计的具体政策和程序，例如审批、复核、职责分离、访问控制和资产盘点。控制活动可以是人工的，也可以由IT自动执行。"},{"id":"t0770","chapterId":"c40","chapterJa":"内部統制","chapterZh":"内部控制","termJa":"情報と伝達","termZh":"信息与沟通","english":"Information and Communication","reading":"じょうほうとでんたつ","breadcrumb":"8 システム監査8-2 内部統制","explanationJa":"データやメッセージを収集し、整理し、他者に伝えるプロセスを指す。これは、企業や組織内での意思決定や業務の円滑な遂行に欠かせない要素である。例えば、社内の連絡や報告書の作成、会議での情報共有などが該当する。この過程では、情報の正確性や適時性が重要であり、これにより適切な判断が行える。また、内部統制の観点からは、情報の伝達が効果的であることが、リスクの管理や不正防止にも寄与するため、しっかりとした体制の構築が求められる。","explanationZh":"内部控制中确保必要信息能够及时、准确地在组织内部和外部适当传递的要素。有效沟通使人员理解职责、风险和问题，并支持管理层决策。"},{"id":"t0771","chapterId":"c40","chapterJa":"内部統制","chapterZh":"内部控制","termJa":"モニタリング","termZh":"监督／监控","english":"Monitoring","reading":"","breadcrumb":"8 システム監査8-2 内部統制","explanationJa":"システムやプロセスの状態を継続的に確認・評価することを指す。特に内部統制の分野においては、組織の業務が適切に運営されているか、その有効性をチェックするための重要な手段である。具体的には、業務プロセスの実行状況やコンプライアンスの遵守状況を監視し、問題が発生した場合には迅速に対応するためのデータを集める。例えば、定期的な報告書の作成や、特定の指標を利用して運用状況を評価することが挙げられる。モニタリングを行うことで、リスクを早期に発見し、信頼性の高い業務環境を維持することが可能になる。","explanationZh":"持续或定期评价内部控制设计和运行是否有效，并及时发现缺陷的活动。可通过日常管理、控制自评和内部审计等方式进行。"},{"id":"t0772","chapterId":"c40","chapterJa":"内部統制","chapterZh":"内部控制","termJa":"ITへの対応","termZh":"IT应对／IT控制","english":"IT Governance","reading":"あいてぃーへのたいおう","breadcrumb":"8 システム監査8-2 内部統制","explanationJa":"企業や組織が情報技術（IT）を効果的に活用し、適切に管理するための枠組みやプロセスを指す。具体的には、IT環境への対応、ITの利用、ITに係る全般統制、ITに係る業務処理統制などが含まれる。IT環境への対応は、情報システムの導入や運用に関する方針を定めることを意味し、ITの利用は業務上の技術活用方法を示す。また、ITに係る全般統制は、情報の安全性や正確性を維持するための基本的な管理策を構築し、業務処理統制は日常業務のプロセスにおいてITが正しく機能するように監視することを含む。これらの取り組みにより、企業はリスクを低減し、効率的かつ効果的な業務運営を実現することができる。","explanationZh":"针对信息技术对业务和内部控制造成的影响，建立IT治理、系统开发、变更、访问、运行和安全等管理机制。目标是确保IT可靠支持组织目标并控制技术风险。"},{"id":"t0773","chapterId":"c40","chapterJa":"内部統制","chapterZh":"内部控制","termJa":"基準・自社内外の行動規範の順守状況の継続的な評価","termZh":"持续评价内部外部规范遵守情况","english":"Compliance Evaluation of Internal and External Codes of Conduct","reading":"きじゅん・じしゃないがいのこうどうきはんのじゅんしゅじょうきょうのけいぞくてきなひょうか","breadcrumb":"8 システム監査8-2 内部統制","explanationJa":"企業が自らの活動において、設定したルールや行動規範を守っているかを定期的に確認するプロセスである。この評価は、法律や倫理基準の遵守を確保するために重要で、企業の信頼性や社会的責任を高める役割を果たす。例えば、企業が定めた環境規制や労働基準に従っているかをチェックすることで、リスクを軽減し、改善点を見つけ出すことができる。継続的な評価を通じて、企業は行動規範の適切な適用を維持し、透明性のある運営が可能となる。","explanationZh":"持续检查组织是否遵守法律法规、行业标准、合同、内部规则和行为准则的活动。通过监控、审计和整改可及时发现合规偏差并降低风险。"},{"id":"t0774","chapterId":"c40","chapterJa":"内部統制","chapterZh":"内部控制","termJa":"内部統制の整備","termZh":"内部控制建设","english":"Internal Control Development","reading":"ないぶとうせいのせいび","breadcrumb":"8 システム監査8-2 内部統制","explanationJa":"組織が業務運営を効率的かつ効果的に行い、法令や規則に従うための手続きを確立することである。内部統制は、リスクを管理し、財務情報の信頼性を確保するための重要な手段であり、企業が不正行為や誤りを防ぐために必要な体制を整えることを目的とする。具体的には、業務プロセスの見直しや、役割分担の明確化、定期的な監査の実施などが含まれる。これにより、組織は業務の透明性を高め、信頼を築くことができ、持続可能な成長に繋がる。","explanationZh":"根据组织目标和风险设计并实施控制环境、风险评估、控制活动、信息沟通和监督等机制。良好的内部控制有助于提高业务有效性、财务可靠性和合规性。"},{"id":"t0775","chapterId":"c40","chapterJa":"内部統制","chapterZh":"内部控制","termJa":"CSA","termZh":"控制自我评估（CSA）","english":"Control Self Assessment","reading":"しーえすえー","breadcrumb":"8 システム監査8-2 内部統制","explanationJa":"組織内での法令遵守やリスク管理の状況を評価し、改善するための手法である。統制自己評価とも呼ばれる。この手法では、従業員が自分たちの業務プロセスや遵守状況を具体的に評価し、問題点を洗い出す。例えば、定期的にアンケートを実施し、業務の運営が法令や社内ルールに従っているかを確認することが含まれる。また、自己評価を通じて得られたフィードバックを基に、効果的な対策を講じることができる。組織の透明性を向上させるための重要な手段であり、持続的な改善を促進する役割も果たす。これは、企業の信頼性を高め、リスクを軽減するために不可欠である。","explanationZh":"由业务部门和控制执行人员自行识别风险、评价控制设计与运行有效性并提出改进的管理方法。它可提高一线人员的风险意识，但不能完全替代独立审计。"},{"id":"t0776","chapterId":"c41","chapterJa":"情報システム戦略","chapterZh":"信息系统战略","termJa":"情報システム戦略委員会","termZh":"信息系统战略委员会","english":"Information Systems Strategy Committee","reading":"じょうほうしすてむせんりゃくいいんかい","breadcrumb":"9 システム戦略9-1 情報システム戦略","explanationJa":"企業や組織において、情報システムの戦略的な計画や運用を担うための委員会である。この委員会は、情報システムに関連する重要な意思決定を行い、業務ニーズに応じたシステムの導入や運用を支援する役割を果たす。たとえば、経営目標を達成するためにどのような技術を採用するかを検討し、情報システムの最適化を図ることが求められる。また、関係者間の調整やコミュニケーションを円滑にするための情報共有の場でもある。これにより、企業全体の情報戦略を整えることが可能になる。","explanationZh":"负责审议信息系统战略、重大IT投资、优先级和治理事项的跨部门或管理层委员会。它帮助确保IT战略与经营战略一致并协调资源和风险。"},{"id":"t0777","chapterId":"c41","chapterJa":"情報システム戦略","chapterZh":"信息系统战略","termJa":"情報システム戦略遂行のための組織体制","termZh":"信息系统战略执行组织体制","english":"Organizational Structure for Executing Information System Strategy","reading":"じょうほうしすてむせんりゃくすいこうのためのそしきたいせい","breadcrumb":"9 システム戦略9-1 情報システム戦略","explanationJa":"企業や団体が情報技術を活用して戦略的な目標を達成するために必要な組織の構造や役割を指す。これには、情報システムの導入や運用を担う部門の設置、各部門間の連携を強化するための仕組みが含まれる。例えば、IT部門が経営戦略に基づいて新しいシステムを提案し、他の部門と協力して実行することで、業務の効率化や競争力の向上を図ることができる。効果的な組織体制を整えることで、情報システムの導入がスムーズになり、期待される効果を適切に引き出すことが可能となる。\nHOME»用語集»システム戦略»業務プロセス","explanationZh":"为落实IT战略而建立的组织结构、职责、决策和协作机制。应明确CIO、业务部门、IT部门和项目团队的角色，以及投资、架构和风险的管理责任。"},{"id":"t0778","chapterId":"c42","chapterJa":"業務プロセス","chapterZh":"业务流程","termJa":"ワークフローシステム","termZh":"工作流系统","english":"Workflow System","reading":"","breadcrumb":"9 システム戦略9-2 業務プロセス","explanationJa":"業務プロセスを効率化し、可視化するための仕組みである。このシステムは、さまざまなタスクや情報の流れを自動化し、関与する人々の役割や責任を明確にする。それにより、業務の進捗状況を追跡しやすくなり、作業の重複やミスを減少させる。たとえば、社員が承認を必要とする書類の処理をワークフローシステムで管理する場合、申請から承認までのステップが自動化され、必要な担当者に通知される。これにより、時間の短縮と業務の効率化が図られる。また、問題が発生した際にも迅速に対処できるため、業務改善に寄与する重要な役割を果たす。","explanationZh":"把业务审批、任务流转和信息传递按预定义流程自动化的系统。可提高效率和可追溯性，并通过权限和审批规则强化内部控制。"},{"id":"t0779","chapterId":"c42","chapterJa":"業務プロセス","chapterZh":"业务流程","termJa":"BPR","termZh":"业务流程再造（BPR）","english":"Business Process Reengineering","reading":"びーぴーあーる","breadcrumb":"9 システム戦略9-2 業務プロセス","explanationJa":"業務プロセスの再設計を指し、効果的な業務運営を目指す手法である。これにより、企業はプロセスを根本から見直すことで、効率を高め、生産性を向上させることができる。例えば、手作業で行っていた業務を自動化することや、部署間の情報共有を改善することが挙げられる。新たなテクノロジーやシステムを活用し、顧客に対するサービス向上やコスト削減を実現するための手段として広く用いられている。その目的は、単に業務の効率化にとどまらず、企業全体の競争力を強化することにもつながる。","explanationZh":"从根本上重新审视和设计业务流程，以显著改善成本、质量、服务和速度的方法。BPR强调流程整体优化，而不是仅对现有步骤做局部自动化。"},{"id":"t0780","chapterId":"c42","chapterJa":"業務プロセス","chapterZh":"业务流程","termJa":"プロセス視点","termZh":"流程视角","english":"Process Perspective","reading":"ぷろせすしてん","breadcrumb":"9 システム戦略9-2 業務プロセス","explanationJa":"業務や作業を進める際に、その流れや手順に注目して分析する考え方である。この視点では、業務プロセスを一連の活動として捉え、各ステップがどのように連携しているかを理解することが重要である。例えば、商品を製造するプロセスを考えると、原材料の調達から製造、出荷までの流れはすべてプロセス視点で見るべきである。この視点を用いることで、ボトルネックや無駄な作業を発見し、効率を改善することが可能となる。業務プロセスの改善と問題解決を目指す際には、プロセス視点が非常に有効であり、全体的な業務の質向上につながる。","explanationZh":"以端到端业务流程而不是单一部门为单位观察和改进工作的思维方式。它关注从输入到客户价值输出的整体流动，有助于发现跨部门瓶颈。"},{"id":"t0781","chapterId":"c42","chapterJa":"業務プロセス","chapterZh":"业务流程","termJa":"Web会議","termZh":"网络会议","english":"Web Conference","reading":"うぇぶかいぎ","breadcrumb":"9 システム戦略9-2 業務プロセス","explanationJa":"インターネットを介して行う会議のことである。この形式では、参加者が物理的に同じ場所に集まることなく、音声や映像を使用してリアルタイムにコミュニケーションを図ることが可能である。例えば、企業のプロジェクトチームが遠隔地から集まって報告や意見交換を行う際に利用される。このような会議は、移動時間やコストを削減し、効率的な情報共有を促進するため、特にリモートワークが普及している昨今では、非常に重要な業務プロセスとなっている。また、多くのWeb会議ツールは、チャット機能や画面共有機能を備えており、効果的なコラボレーションを実現するのに役立つ。","explanationZh":"通过互联网或企业网络进行远程音视频、屏幕共享和协作的会议形式。应控制会议访问、邀请链接、录制和共享资料，防止未授权人员加入或信息泄露。"},{"id":"t0782","chapterId":"c42","chapterJa":"業務プロセス","chapterZh":"业务流程","termJa":"電子メール","termZh":"电子邮件","english":"Electronic Mail","reading":"でんしめーる","breadcrumb":"9 システム戦略9-2 業務プロセス","explanationJa":"インターネットを利用してメッセージやファイルを送受信する通信手段である。通常、ユーザーは専用のソフトウェアを使用してメッセージを作成し、宛先のメールアドレスを指定する。電子メールは迅速なコミュニケーションを可能にし、情報の共有を効率的に行う点が特徴である。例えば、ビジネスにおいては、会議の設定やプロジェクトの進捗報告など、日常的に多くの業務連絡が電子メールを通じて行われる。このように、電子メールは業務プロセスの改善にも寄与し、時代が進むにつれて、より多くの機能が追加され、便利に利用されている。","explanationZh":"通过网络交换电子消息的通信工具。企业使用时应注意钓鱼、误发、附件恶意软件、敏感信息外泄和归档等安全与管理问题。"},{"id":"t0783","chapterId":"c42","chapterJa":"業務プロセス","chapterZh":"业务流程","termJa":"電子掲示板","termZh":"电子公告板","english":"Electronic Bulletin Board","reading":"でんしけいじばん","breadcrumb":"9 システム戦略9-2 業務プロセス","explanationJa":"インターネット上で情報を共有するためのプラットフォームである。主に運営者やユーザーがメッセージや情報を投稿し、他のユーザーがそれに対してコメントや質問を行うことができる。例えば、社内のコミュニケーションを円滑にするために、様々な業務に関する情報や進捗状況を掲示板に掲載し、スタッフが随時確認できるようにすることで、業務プロセスの改善につながる。また、問題解決のための意見交換も活発に行われ、問題の所在を早期に発見し、解決策を見つける役割も果たす。このように、電子掲示板は情報共有の促進と業務の効率化に寄与する重要なツールである。","explanationZh":"用户在网络系统上发布、查看和回复公告或讨论内容的平台。适合组织信息共享，但需实施权限、内容管理和记录保存。"},{"id":"t0784","chapterId":"c42","chapterJa":"業務プロセス","chapterZh":"业务流程","termJa":"ブログ","termZh":"博客","english":"Blog","reading":"","breadcrumb":"9 システム戦略9-2 業務プロセス","explanationJa":"個人や団体が定期的に情報や意見を発信するためのWebサイトやWebページである。記事形式で内容を整理し、読者がコメントを残したり、シェアしたりできるインタラクティブな特徴を持つ。例えば、企業がブログを活用することで、自社製品やサービスに関するニュースや情報を発信し、顧客とのコミュニケーションを深めることができる。また、ブログはSEO（検索エンジン最適化）にも寄与し、検索結果での表示順位を上げる手助けとなる。このように、ブログは業務プロセスの改善や問題解決に向けた重要なツールとして機能する。","explanationZh":"按时间或主题发布文章和内容的Web媒体形式，可由个人或组织运营。企业博客需要管理公开内容、账号安全和评论风险。"},{"id":"t0785","chapterId":"c42","chapterJa":"業務プロセス","chapterZh":"业务流程","termJa":"チャット","termZh":"聊天","english":"Chat","reading":"","breadcrumb":"9 システム戦略9-2 業務プロセス","explanationJa":"インターネットを通じてリアルタイムにメッセージのやり取りができるコミュニケーション手段である。ビジネスにおいて、チャットはチーム内の迅速な情報共有や意思決定をサポートする役割を果たす。例えば、プロジェクトの進捗状況を即座に確認したり、問題が発生した際に素早く相談することができる。このように、チャットは業務プロセスの改善に寄与し、効率的なコミュニケーションを実現するためのツールとして重要である。また、専用のチャットツールを使うことで、ファイルの共有やタスク管理なども行えるため、業務の円滑化に非常に役立つ。","explanationZh":"通过网络实时或近实时交换短消息的通信方式。企业聊天工具提高协作效率，但应管理外部共享、文件发送、账号和消息保存。"},{"id":"t0786","chapterId":"c42","chapterJa":"業務プロセス","chapterZh":"业务流程","termJa":"SMS","termZh":"短信（SMS）","english":"Short Message Service","reading":"えすえむえす","breadcrumb":"9 システム戦略9-2 業務プロセス","explanationJa":"短いメッセージを携帯電話やスマートフォンで送受信するためのサービスである。この技術は、主にテキストメッセージを利用してコミュニケーションを行う手段として広く普及している。たとえば、仕事上の連絡や情報の伝達がスムーズに行えるため、業務プロセスの改善や迅速な問題解決に役立つ。特に、即時性が求められる場面では、SMSが便利なツールとなることが多い。また、SMSは多くのデバイスで利用可能であり、インターネット接続がなくてもメッセージの送受信ができるため、広範な用途が期待される。このように、SMSは日常的なコミュニケーションの一部としてだけでなく、業務においても重要な役割を果たしている。","explanationZh":"移动通信网络提供的短文本消息服务。SMS可用于通知和部分认证场景，但存在号码劫持、钓鱼和消息截获等风险，不应在高风险场景单独依赖。"},{"id":"t0787","chapterId":"c42","chapterJa":"業務プロセス","chapterZh":"业务流程","termJa":"SNS","termZh":"社交网络服务（SNS）","english":"Social Networking Service","reading":"えすえぬえす","breadcrumb":"9 システム戦略9-2 業務プロセス","explanationJa":"インターネットを通じて人々が情報を共有し、コミュニケーションを行うためのサービスである。ユーザーが写真やテキストを投稿し、他のユーザーとコメントやメッセージを交わすことができるプラットフォームを提供する。例えば、FacebookやTwitterなどのサービスが広く利用されている。このようなサービスは、企業が顧客と直接コミュニケーションを取る手段としても活用され、フィードバックを得ることでサービス向上を図ることが可能である。また、SNSを利用することで、情報共有がスムーズになり、業務プロセスの改善や問題解決に寄与することが期待される。","explanationZh":"用户建立社交关系并发布、分享和互动信息的在线服务。组织使用SNS时需要管理账号、隐私、声誉、假信息和信息泄露风险。"},{"id":"t0788","chapterId":"c42","chapterJa":"業務プロセス","chapterZh":"业务流程","termJa":"RPA","termZh":"机器人流程自动化（RPA）","english":"Robotic Process Automation","reading":"あーるぴーえー","breadcrumb":"9 システム戦略9-2 業務プロセス","explanationJa":"業務プロセスを自動化する技術である。具体的には、コンピュータ上で行われる反復的な作業をソフトウェアのロボットが代わりに実行する仕組みである。例えば、データの入力や集計、報告書の生成などの定型的な業務を自動で行うことで、人的ミスを減少させ、効率を向上させることができる。また、RPAを導入することで、従業員はより価値の高い業務に集中することが可能となり、全体の生産性が向上する。これは特に多くのデータを扱う業界や、大量の書類処理を必要とする企業において効果的である","explanationZh":"利用软件机器人模仿人在计算机界面上的重复操作，实现规则明确业务的自动化。RPA可提高效率，但需管理机器人账号权限、变更和异常处理。"},{"id":"t0789","chapterId":"c43","chapterJa":"ソリューションビジネス","chapterZh":"解决方案业务","termJa":"クラウドサービス","termZh":"云服务","english":"Cloud Service","reading":"","breadcrumb":"9 システム戦略9-3 ソリューションビジネス","explanationJa":"インターネットを通じて提供される各種のコンピュータサービスである。このサービスには、データの保存やアプリケーションの利用、サーバの運用などが含まれる。例えば、Google DriveやDropboxはデータ保存ができ、AWSやAzureはクラウド上でサーバを設置することが可能である。また、クラウドサービスは利用する際の初期投資が少なく、必要に応じてリソースを増減できる柔軟性を持っているため、企業や個人にとって非常に利便性が高い。このように、クラウドサービスは現代のIT環境において欠かせない要素となっている。","explanationZh":"通过网络按需提供计算、存储、平台或应用等资源的服务。使用云服务时应明确责任共担、数据保护、身份权限、配置和供应商风险。"},{"id":"t0790","chapterId":"c43","chapterJa":"ソリューションビジネス","chapterZh":"解决方案业务","termJa":"ソブリンクラウド","termZh":"主权云（Sovereign Cloud）","english":"Sovereign Cloud","reading":"","breadcrumb":"9 システム戦略9-3 ソリューションビジネス","explanationJa":"特定の国や地域の法律や規制に準拠して運営されるクラウドサービスである。このサービスは、データの所有権やプライバシーの保護に重点を置いており、ユーザーが自国の法律に則ってデータを管理できることを目的としている。例えば、EU内の企業がデータを扱う際には、GDPR（一般データ保護規則）に従う必要があるため、ソブリンクラウドが適している。これにより、セキュリティやデータへのアクセス管理が強化され、国際的なデータ移転に関するリスクを軽減することができる。近年、クラウドサービスの利用が進む中で、セキュリティや法的な側面が重視されるようになってきている。","explanationZh":"强调数据、运营和治理符合特定国家或地区主权、法律和控制要求的云服务模式。通常关注数据驻留、司法管辖、运营主体和技术可控性。"},{"id":"t0791","chapterId":"c43","chapterJa":"ソリューションビジネス","chapterZh":"解决方案业务","termJa":"SaaS","termZh":"软件即服务（SaaS）","english":"Software as a Service","reading":"さーす","breadcrumb":"9 システム戦略9-3 ソリューションビジネス","explanationJa":"インターネットを介してソフトウェアを提供するモデルである。従来のようにソフトウェアを自分のコンピュータにインストールするのではなく、クラウド上で動作するアプリケーションにアクセスし利用する形である。この場合、ユーザーは月額または年額の料金を支払うことで、常に最新のソフトウェア機能を利用できる。例えば、メールサービスや文書作成ソフト、顧客管理システムなどがSaaSの良い例である。SaaSの特徴は、初期投資が少なく、メンテナンスやアップデートがサービス提供者によって行われるため、ユーザーは手間をかけずに利用できる点である。このように、SaaSは便利さと効率性を提供する現代のソリューションである。","explanationZh":"用户直接通过网络使用服务商提供的应用软件的云服务模式。服务商负责大部分底层平台，用户主要负责账号、权限、数据和业务配置。"},{"id":"t0792","chapterId":"c43","chapterJa":"ソリューションビジネス","chapterZh":"解决方案业务","termJa":"PaaS","termZh":"平台即服务（PaaS）","english":"Platform as a Service","reading":"ぱーす","breadcrumb":"9 システム戦略9-3 ソリューションビジネス","explanationJa":"クラウドコンピューティングのサービスの一種で、アプリケーション開発やデプロイを行うためのプラットフォームを提供するものである。このサービスを利用することで、開発者はサーバ管理やインフラの構築に煩わされることなく、アプリケーションの開発に集中できる。例えば、Google App EngineやMicrosoft AzureなどのPaaSプロバイダーがあり、これらはスケーラビリティや自動更新機能を持ちながら、必要な開発ツールやフレームワークも提供する。このように、PaaSは迅速なアプリケーション開発を可能にし、リソースの効率的な利用を支援する重要なサービスである。","explanationZh":"服务商提供开发和运行应用所需的平台环境，用户部署自己的应用和数据。它减少基础设施管理负担，但仍需管理应用安全和配置。"},{"id":"t0793","chapterId":"c43","chapterJa":"ソリューションビジネス","chapterZh":"解决方案业务","termJa":"IaaS","termZh":"基础设施即服务（IaaS）","english":"Infrastructure as a Service","reading":"いあーす","breadcrumb":"9 システム戦略9-3 ソリューションビジネス","explanationJa":"インターネットを通じて、サーバやストレージなどの基盤を提供するサービスである。具体的には、物理的なハードウェアを持たずとも、必要なリソースをサービスプロバイダーから借りることができる。これにより、企業や開発者は、自分たちのニーズに応じたサーバ環境を柔軟に構築できる。例えば、急なトラフィックの増加に対応するために、新しいサーバを迅速に追加することが可能である。このように、IaaSはコスト削減やスケーラビリティを実現し、ビジネスの変化に柔軟に対応できる力を提供する。","explanationZh":"服务商提供虚拟计算、网络和存储资源，用户管理操作系统、应用和数据。用户控制范围较大，同时承担更多配置和安全责任。"},{"id":"t0794","chapterId":"c43","chapterJa":"ソリューションビジネス","chapterZh":"解决方案业务","termJa":"ASP","termZh":"应用服务提供商（ASP）","english":"Application Service Provider","reading":"えーえすぴー","breadcrumb":"9 システム戦略9-3 ソリューションビジネス","explanationJa":"特定のアプリケーションソフトウェアをインターネット経由で提供するサービスモデルである。ユーザーは、自分のコンピュータにソフトウェアをインストールする代わりに、インターネットを通じてASPのサーバ上でアプリケーションを直接利用することができる。例えば、オンライン会計ソフトや顧客管理システム（CRM）などがこれに該当する。ASPを利用することで、企業は初期投資を抑え、必要な機能を必要なだけ利用できるため、コスト効率が高まる。さらに、常に最新のソフトウェアが提供されるため、メンテナンスやアップデートを気にする必要がないという利点もある。","explanationZh":"通过网络向客户提供应用软件使用服务的提供商或模式，可视为SaaS概念普及前常用的服务形态。客户无需自行部署全部应用基础设施。"},{"id":"t0795","chapterId":"c44","chapterJa":"システム活用促進・評価","chapterZh":"信息系统应用促进与评价","termJa":"デジタルリテラシー","termZh":"数字素养","english":"Digital Literacy","reading":"","breadcrumb":"9 システム戦略9-4 システム活用促進・評価","explanationJa":"情報技術やデジタルツールを効果的に使いこなす能力である。この能力には、インターネットやパソコンを通じて情報を検索し、評価し、利用するスキルが含まれる。例えば、電子メールでのコミュニケーションや、オンラインでの情報収集、基本的なソフトウェアの操作などが挙げられる。デジタルリテラシーが高いことで、業務効率の向上や、情報の適切な活用が可能となるため、現代の職場や生活において非常に重要なスキルである。さらに、デジタル技術が進化する中で、新しいツールやプラットフォームに迅速に適応する力も求められる。これにより、情報社会における有効な参与が実現される。","explanationZh":"理解并恰当使用数字设备、信息、网络和数据的能力，包括信息检索、判断真伪、安全隐私、协作和创造等。数字素养是安全使用ICT的重要基础。"},{"id":"t0796","chapterId":"c44","chapterJa":"システム活用促進・評価","chapterZh":"信息系统应用促进与评价","termJa":"IoT","termZh":"物联网（IoT）","english":"Internet of Things","reading":"あいおーてぃー","breadcrumb":"9 システム戦略9-4 システム活用促進・評価","explanationJa":"さまざまな物やデバイスがインターネットを通じて相互に接続され、データを交換する仕組みである。この技術により、日常生活の中で使われる電子機器やセンサー、家電製品などが情報をやり取りし、より便利で効率的な利用が可能となる。例えば、スマートホームでは、温度調整を自動化したり、外出先から家の照明を管理したりすることができる。また、IoTは産業分野でも活用され、機器の状態をリアルタイムで監視し、故障予測や作業の効率化を実現するなどの効果がある。このように、IoTは情報システムの活用を促進し、生活や産業に革新をもたらす技術である。","explanationZh":"将传感器、设备、车辆等实体连接到网络，实现数据采集、交换和控制的技术体系。IoT需要特别考虑设备认证、更新、通信安全和生命周期管理。"},{"id":"t0797","chapterId":"c44","chapterJa":"システム活用促進・評価","chapterZh":"信息系统应用促进与评价","termJa":"ビッグデータ","termZh":"大数据","english":"Big Data","reading":"","breadcrumb":"9 システム戦略9-4 システム活用促進・評価","explanationJa":"従来のデータ管理ツールでは扱いきれないほどの大規模で多様なデータセットを指す。このデータには、生成される速度や種類が非常に豊富であり、例えばソーシャルメディアの投稿、センサーからのリアルタイムデータ、企業の取引履歴などが含まれる。ビッグデータを活用することで、企業は顧客の行動パターンを分析したり、需要予測を行ったりすることが可能になる。これにより、より効果的なマーケティング戦略やサービスの改善が実現され、競争力を高めることができる。データ解析や機械学習と組み合わせることで、新たな価値を生み出す手段として、ビッグデータは重要な役割を果たしている。","explanationZh":"规模、速度和类型超出传统工具容易处理能力的数据集合及相关处理技术。通过分析大数据可以支持预测和决策，但必须重视数据质量、隐私和安全。"},{"id":"t0798","chapterId":"c44","chapterJa":"システム活用促進・評価","chapterZh":"信息系统应用促进与评价","termJa":"生成AI","termZh":"生成式AI","english":"Generative AI","reading":"せいせいえーあい","breadcrumb":"9 システム戦略9-4 システム活用促進・評価","explanationJa":"既存のデータをもとに新たなコンテンツを自動的に生成する技術である。例えば、テキスト、画像、音声などを生成することができ、ユーザーが求める情報やコンテンツを迅速に提供する役割を果たす。具体的には、小説や記事を自動作成したり、ユーザーのキーワードに基づいて画像を生成するアプリケーションが存在する。この技術は、マーケティングや教育、エンターテイメントなど様々な分野で活用されており、業務の効率化や創造性の向上に寄与する。利用者のニーズに応じたアウトプットを提供できるため、ますます注目されている。","explanationZh":"能够根据输入生成文本、图像、代码、音频等新内容的人工智能技术。使用时应关注事实错误、敏感数据输入、版权、偏见、提示词注入和输出审核等风险。"},{"id":"t0799","chapterId":"c44","chapterJa":"システム活用促進・評価","chapterZh":"信息系统应用促进与评价","termJa":"BYOD","termZh":"自带设备办公（BYOD）","english":"Bring Your Own Device","reading":"びーわいおーでぃー","breadcrumb":"9 システム戦略9-4 システム活用促進・評価","explanationJa":"従業員が自分自身のデバイス、例えばスマートフォンやタブレットを職場の業務に使用することを指す。これは、業務の効率化や従業員の利便性向上を目的としている。具体的には、各自が慣れ親しんだデバイスを使うことで、作業がスムーズに進むことが期待される。また、企業側にとっても、デバイス購入や保守にかかるコストを削減できる利点がある。しかし、情報セキュリティ面でのリスクも存在し、個人のデバイスが社内ネットワークに接続されることで、データ漏洩やウイルス感染の危険性が増すため、適切な管理やポリシーの策定が求められる。このように、BYODは現代の働き方において重要なトピックとなっている。","explanationZh":"允许员工使用个人拥有的电脑、手机等设备处理组织业务的做法。可提高便利性，但需要通过MDM、容器化、访问控制、加密和政策明确数据与隐私边界。"},{"id":"t0800","chapterId":"c44","chapterJa":"システム活用促進・評価","chapterZh":"信息系统应用促进与评价","termJa":"チャットボット","termZh":"聊天机器人","english":"Chatbot","reading":"","breadcrumb":"9 システム戦略9-4 システム活用促進・評価","explanationJa":"人工知能（AI）を利用して人間と対話を行うプログラムである。主にテキストチャットを通じてユーザーの質問に答えたり、情報を提供したりする役割を持つ。例えば、企業の顧客サポートで用いられ、製品やサービスについての問い合わせに迅速に対応することができる。また、24時間稼働できるため、利用者はいつでも必要な情報を得られる点が利点である。チャットボットは自然言語処理技術を用いており、ユーザーの入力を解析し、適切な返答を生成する。このような技術の活用により、業務の効率化や顧客満足度の向上が期待できる。","explanationZh":"通过文本或语音与用户进行自动对话、回答问题或执行任务的软件。可基于规则或AI实现，企业使用时需控制身份认证、错误回答和敏感信息处理。"},{"id":"t0801","chapterId":"c44","chapterJa":"システム活用促進・評価","chapterZh":"信息系统应用促进与评价","termJa":"普及啓発","termZh":"普及与宣传教育","english":"Awareness and Dissemination","reading":"ふきゅうけいはつ","breadcrumb":"9 システム戦略9-4 システム活用促進・評価","explanationJa":"特定の技術や知識を広め、一般の理解を深めるための活動である。特に情報システム活用の促進においては、企業や組織が新たな技術を導入する際、その価値や効用を周知し、利用を促すことが重要である。具体的には、セミナーやワークショップを開催し、実際の事例を紹介することで、関心を喚起するアプローチが取られる。また、マニュアルやガイドラインの配布も効果的であり、これによりユーザーが新しいシステムを安心して使えるようになる。情報システムの導入を円滑に進め、実際の業務における効果を最大化するための基盤を築くものである。","explanationZh":"通过宣传、培训、资料和活动让相关人员了解新制度、技术或安全要求并促进正确采用的活动。其目标是提高认知、理解和实际行动率。"},{"id":"t0802","chapterId":"c44","chapterJa":"システム活用促進・評価","chapterZh":"信息系统应用促进与评价","termJa":"情報システムの投資対効果分析","termZh":"信息系统投资回报分析","english":"Return on Investment Analysis for Information Systems","reading":"じょうほうしすてむのとうしたいこうかぶんせき","breadcrumb":"9 システム戦略9-4 システム活用促進・評価","explanationJa":"特定の情報システムに対して行った投資が、どれだけの効果や利益を生み出したかを評価する手法である。この分析を行うことで、情報システムの導入や運用がどの程度企業や組織に貢献したのかを数値的に示すことができる。具体的には、システム導入後の業務の効率化やコスト削減、売上増加などの成果を定量的に測定し、初期投資に対する利益の割合を算出する。これにより、未来の投資に関する意思決定をサポートし、効率的なリソース配分を実現することが可能になる。情報システムの価値を明確にすることで、経営層の理解を得やすくし、いかに重要かを訴える資料作成にも役立つ。","explanationZh":"比较信息系统投资所需成本与预期产生的经济或业务收益，以评价投资合理性的分析。除直接财务收益外，也可考虑效率、风险降低和战略价值。"},{"id":"t0803","chapterId":"c44","chapterJa":"システム活用促進・評価","chapterZh":"信息系统应用促进与评价","termJa":"システム利用実態の調査及び評価","termZh":"系统使用实态调查与评价","english":"System Utilization Survey and Evaluation","reading":"しすてむりようじったいのちょうさおよびひょうか","breadcrumb":"9 システム戦略9-4 システム活用促進・評価","explanationJa":"情報システムがどのように使われているかを分析し、その効果や問題点を明らかにするプロセスである。具体的には、利用者の行動やシステムのパフォーマンスを観察・測定し、そのデータを基に改善点を導き出す。この調査によって、システムの利用状況を可視化することができ、適切な改善策を立案する上での重要な情報を提供する。例えば、業務プロセスの効率化や、ユーザーエクスペリエンスの向上につながる施策を考える際に、有益なデータとなる。システムの運用を最適化し、より価値のあるサービスを提供するために、定期的に実施することが望ましい。","explanationZh":"调查用户、功能使用率、处理量、满意度和业务效果等，评价现有系统是否得到有效利用。结果可用于优化、培训、改造或废止决策。"},{"id":"t0804","chapterId":"c44","chapterJa":"システム活用促進・評価","chapterZh":"信息系统应用促进与评价","termJa":"業務内容や業務フローの変更の有無の把握","termZh":"掌握业务内容及业务流程变化","english":"Changes in Business Activities and Flows","reading":"ぎょうむないようやぎょうむふろーのへんこうのうむのはあく","breadcrumb":"9 システム戦略9-4 システム活用促進・評価","explanationJa":"企業や組織の業務の進行状況やその方法が変わったかどうかを確認することを指す。このプロセスは、業務の効率性を評価したり、改善点を見極めたりするために重要である。例えば、新しいソフトウェアを導入した場合、その影響で業務フローが変わることがあるため、これをしっかりと検証する必要がある。このような評価は、業務の生産性向上やミスの低減につながるため、定期的に行うことが推奨される。また、業務の変更を適切に把握することで、従業員のトレーニングやサポート体制を整えることも可能となり、全体の業務を円滑に進めるうえで欠かせない要素となる。","explanationZh":"持续确认组织业务规则、职责、流程和外部环境是否发生变化，以判断信息系统和控制措施是否需要调整。业务变化是系统需求变更的重要来源。"},{"id":"t0805","chapterId":"c44","chapterJa":"システム活用促進・評価","chapterZh":"信息系统应用促进与评价","termJa":"情報システムの運用状況の把握及び評価","termZh":"掌握并评价信息系统运行状况","english":"Information System Operation Status Assessment and Evaluation","reading":"じょうほうしすてむのうんようじょうきょうのはあくおよびひょうか","breadcrumb":"9 システム戦略9-4 システム活用促進・評価","explanationJa":"情報システムがどのように使用されているかを定期的に調査し、分析するプロセスである。このプロセスにより、システムの効率や効果を測定し、改善点を見つけ出すことが可能となる。具体的には、システムの利用状況や性能データを収集し、問題点やボトルネックを特定する。また、ユーザーからのフィードバックを取り入れることで、実際の運用におけるニーズを反映させる。情報システムの運用状態を定期的に評価することによって、企業や組織はリソースを最適化し、業務の効率化やサービス向上につなげることができる。これは、情報システムの適切な管理と持続可能な運用を実現するために不可欠な活動である。","explanationZh":"通过运行指标、故障、性能、事件、成本和用户反馈等信息评价系统是否稳定、有效和安全。评价结果用于维护、容量规划和改进。"},{"id":"t0806","chapterId":"c44","chapterJa":"システム活用促進・評価","chapterZh":"信息系统应用促进与评价","termJa":"情報システムの改修","termZh":"信息系统改造","english":"Information System Refurbishment","reading":"じょうほうしすてむのかいしゅう","breadcrumb":"9 システム戦略9-4 システム活用促進・評価","explanationJa":"既存の情報システムを改善または更新するプロセスである。この改修は、システムの性能向上や新しい要件への適応を目的として行われる。たとえば、業務の効率を向上させるために、新しい機能を追加したり、古いハードウェアを最新のものに交換することが含まれる。また、セキュリティ対策の強化やユーザーインターフェースの改善も、改修の重要な要素である。このように、業務環境の変化に対応するために不可欠な作業であり、効率的な運用を持続させるために必要な取り組みである。","explanationZh":"针对业务变化、缺陷、性能、安全或技术老化，对现有系统进行修改和升级。改造应经过需求、影响、测试、变更和发布管理，避免破坏现有业务。"},{"id":"t0807","chapterId":"c44","chapterJa":"システム活用促進・評価","chapterZh":"信息系统应用促进与评价","termJa":"システムライフサイクル","termZh":"系统生命周期","english":"System Lifecycle","reading":"","breadcrumb":"9 システム戦略9-4 システム活用促進・評価","explanationJa":"情報システムが計画、設計、開発、運用、保守、廃棄に至るまでの一連の過程を指す。初めに要件定義が行われ、次に設計や開発が続き、その後実際に運用される。運用中にはバグ修正や機能追加が行われ、長期間使用された後にはシステムを廃棄する段階が訪れる。例えば、ある企業の業務用システムが新たなニーズに対応するために再設計されて運用され続け、最終的には技術的な老朽化やメンテナンスコストの増加により、廃棄されるケースがある。このライフサイクルを通じて、システムの品質や効率を向上させることが目指される。","explanationZh":"信息系统从规划、需求、设计、开发、测试、上线、运行维护到退役的全过程。每个阶段都应考虑安全、质量、成本和资产管理。"},{"id":"t0808","chapterId":"c44","chapterJa":"システム活用促進・評価","chapterZh":"信息系统应用促进与评价","termJa":"データの消去","termZh":"数据擦除","english":"Data Erasure","reading":"でーたのしょうきょ","breadcrumb":"9 システム戦略9-4 システム活用促進・評価","explanationJa":"情報が保存されている媒体から、そのデータを完全に取り除く行為である。単にファイルを削除するだけでは、データが復元される可能性があるため、専用の方法を使用して消去する必要がある。例えば、物理的な媒体を粉砕したり、データの上にランダムな情報を書き込む方法が用いられる。また、データの消去は古い情報システムの廃棄時にも重要で、個人情報や機密情報が漏えいしないようにするために欠かせないプロセスである。適切なデータ消去は、プライバシーの保護やセキュリティの強化に寄与し、情報漏えいのリスクを低減する役割を果たす。","explanationZh":"通过覆盖、安全删除、密码学擦除或其他方法，使存储介质中的数据无法被常规或合理手段恢复。删除文件名或普通格式化并不一定等同于安全擦除。"},{"id":"t0809","chapterId":"c44","chapterJa":"システム活用促進・評価","chapterZh":"信息系统应用促进与评价","termJa":"情報機器の廃棄","termZh":"信息设备废弃","english":"Information Equipment Disposal","reading":"じょうほうききのはいき","breadcrumb":"9 システム戦略9-4 システム活用促進・評価","explanationJa":"不要になったコンピュータや周辺機器などの電子機器を適切に処分することを指す。技術の進化により、新しい機器が次々と登場する一方、古い機器の取り扱いが問題になっている。特に、機器には個人情報や機密データが保存されていることが多く、それらを適切に消去しないまま廃棄すると、情報漏洩の危険性が生じる。また、電子機器には有害な物質が含まれることもあるため、環境への影響を考慮し、リサイクルや専門業者による処分が推奨される。したがって、安全性と環境保護の観点から正しく行うことが重要である。","explanationZh":"计算机、手机、存储设备等退役时的安全处置。应先清除数据、回收账号和资产记录，并根据介质敏感度选择再利用、专业销毁或合规回收。"},{"id":"t0810","chapterId":"c45","chapterJa":"システム化計画","chapterZh":"信息化计划","termJa":"リスク分析の対象","termZh":"风险分析对象","english":"Risk Analysis Target","reading":"りすくぶんせきのたいしょう","breadcrumb":"10 システム企画10-1 システム化計画","explanationJa":"情報システムの導入に際して特定される危険要因や不安定要素のことである。これには、プロジェクトの遅延、コストの超過、技術的な問題などが含まれる。具体的な例としては、新しいシステムが既存の業務プロセスにどのように影響を与えるか、また、セキュリティ上の脆弱性が発生する可能性などが考えられる。リスク分析を行うことで、これらの問題を予測し、対策を講じることが可能になる。結果として、プロジェクトの成功率を高め、投資の無駄を減少させることにつながるため、情報システムの導入において非常に重要なステップである。","explanationZh":"开展风险分析时需要评价的业务、资产、系统、流程、人员或场所等范围。明确分析对象可以避免遗漏关键资产并界定评估边界。"},{"id":"t0811","chapterId":"c45","chapterJa":"システム化計画","chapterZh":"信息化计划","termJa":"リスクの発生頻度・影響・範囲","termZh":"风险发生频率、影响与范围","english":"Risk Occurrence Frequency, Impact, and Scope","reading":"りすくのはっせいひんど・えいきょう・はんい","breadcrumb":"10 システム企画10-1 システム化計画","explanationJa":"システム化計画において情報システムの導入時に考慮するべきリスク要因の分析に関連する概念である。発生頻度は、特定のリスクがどれくらいの頻度で起こる可能性があるかを示し、影響はそのリスクが現実化した場合にどれほどの損害をもたらすかを指す。そして範囲は、そのリスクが影響を与える領域の広さを示す。これらを評価することで、リスク管理の方策を立て、プロジェクトの成功率を高めることができる。例えば、重要なデータが失われるリスクに対しては、頻度が高く影響が重大であれば、特に注意が必要である。このように、リスクを総合的に把握し対策を講じることは、情報システムの導入において不可欠なステップである。","explanationZh":"风险评价的重要维度：发生频率表示可能性，影响表示后果严重程度，范围表示受影响对象和扩散程度。综合这些因素可确定风险优先级。"},{"id":"t0812","chapterId":"c45","chapterJa":"システム化計画","chapterZh":"信息化计划","termJa":"リスクの種類に応じた損害内容と損害額","termZh":"不同风险类型对应的损害内容和金额","english":"Risk Types and Corresponding Damage and Cost","reading":"りすくのしゅるいにおうじたそんがいないようとそんがいがく","breadcrumb":"10 システム企画10-1 システム化計画","explanationJa":"情報システムの導入時に、そのリスクが引き起こす可能性のある損害の内容や、その損害にかかるコストを分析することである。具体的には、システムの失敗による業務の中断、データの損失、セキュリティの侵害など、様々なリスクが存在する。これらのリスクによって、企業や組織が被る金銭的な影響を予測することが重要である。この分析により、リスク管理の対策を効果的に立案し、企業資源の最適な配分が可能となるため、システム化計画において欠かせない要素となる。リスクを事前に把握することで、トラブルの未然防止にもつながる。","explanationZh":"对财产、责任、收入、人员等不同风险可能造成的损失类型和金额进行分析。量化损失有助于比较风险和决定控制投资、保险等应对方式。"},{"id":"t0813","chapterId":"c45","chapterJa":"システム化計画","chapterZh":"信息化计划","termJa":"リスク対応","termZh":"风险应对","english":"Risk Response","reading":"りすくたいおう","breadcrumb":"10 システム企画10-1 システム化計画","explanationJa":"情報システムを導入する際に発生する可能性のあるリスクに対して取るべき行動を指す。リスクを回避したり、損失を予防、軽減したり、リスクを他者に移転する手法が含まれる。また、一部のリスクを企業が保有する選択肢も存在する。例えば、リスク回避ではリスクの発生を避けるために計画を変更することがある。損失軽減は、リスクが生じた場合に影響を小さくする手段を講じることを意味し、具体的にはバックアップの実施などが考えられる。リスク移転では、保険に加入するなどしてリスクの影響を他者に負担させることが多い。これらの手法を適切に用いることで、プロジェクトの成功確率を高めることができる。","explanationZh":"风险评估后选择并实施适当措施的过程，包括规避、降低、转移／共享和接受等方式。应明确责任人、措施、期限和剩余风险。"},{"id":"t0814","chapterId":"c45","chapterJa":"システム化計画","chapterZh":"信息化计划","termJa":"財産損失","termZh":"财产损失","english":"Asset Loss","reading":"ざいさんそんしつ","breadcrumb":"10 システム企画10-1 システム化計画","explanationJa":"企業や個人が保有する財産が損なわれることを指す。これには物理的な資産の破損や、デジタルデータの消失、さらには顧客情報や機密情報の流出など、さまざまな形態がある。システム化計画を立案する際には、導入する情報システムによって生じる可能性のある財産損失を分析し、リスク評価を行うことが重要である。例えば、新たなシステムの導入によってデータが失われる場合、これが業務に与える影響や、復旧にかかるコストを事前に予測し、対策を講じておくことが求められる。また、サイバー攻撃やシステム障害なども財産損失のリスクに含まれるため、セキュリティ対策を強化することも不可欠である。こうしたリスクを認識し対処することで、事業の継続性を確保し、安定した運営を実現することが可能となる。","explanationZh":"设备、建筑、库存、数据载体等资产因事故、灾害、盗窃或破坏造成的直接经济损失。风险管理中需要估算修复或重置成本。"},{"id":"t0815","chapterId":"c45","chapterJa":"システム化計画","chapterZh":"信息化计划","termJa":"責任損失","termZh":"责任损失","english":"Liability Loss","reading":"せきにんそんしつ","breadcrumb":"10 システム企画10-1 システム化計画","explanationJa":"特定の事象や状況により発生した結果として、組織や個人が負うべき責任を遂行できなくなることを指す。この概念は、情報システムの導入におけるリスク分析において重要な要素である。例えば、新しいシステムを導入した際に、そのシステムに不具合が生じると、ユーザーや顧客に対して適切なサービスを提供できず、結果として信頼を失うことになる。こうした損失は、直接的な金銭的損失だけでなく、企業の評判やブランド価値を損なうことにもつながる。したがって、システム化計画の立案においては、責任損失を考慮し、リスクを事前に特定し、対策を講じることが不可欠である。リスク軽減のためには、システムの品質確保や適切な運用体制の整備が重要となる。","explanationZh":"因组织对他人造成损害而承担赔偿、诉讼、监管处罚等法律责任产生的损失。数据泄露和服务事故都可能引发责任损失。"},{"id":"t0816","chapterId":"c45","chapterJa":"システム化計画","chapterZh":"信息化计划","termJa":"純収益損失","termZh":"净收益损失","english":"Net Revenue Loss","reading":"じゅんしゅうえきそんしつ","breadcrumb":"10 システム企画10-1 システム化計画","explanationJa":"企業が商品やサービスを提供する際に、予想される収益が減少することによって生じる損失である。この概念は特に情報システムの導入や変更のリスク分析において重要で、システムの不具合や導入遅延が発生すると、予定していた利益を達成できない可能性がある。たとえば、新しい顧客管理システムを導入した場合、初期のトラブルや操作の習熟の遅れにより、顧客へのサービス提供が遅れることがある。この結果、売上が減少し、純収益としての損失が発生することになるため、システム化計画を立案する際には、これらのリスクを十分に考慮する必要がある。適切なリスク管理を行うことで、将来の収益を保護し、企業の成長を支えることができる。","explanationZh":"因业务中断、销售下降或机会丧失导致本来可以获得的净收益减少。它属于间接经济损失，评估时需要考虑中断时间和利润结构。"},{"id":"t0817","chapterId":"c45","chapterJa":"システム化計画","chapterZh":"信息化计划","termJa":"人的損失","termZh":"人员损失","english":"Human Loss","reading":"じんてきそんしつ","breadcrumb":"10 システム企画10-1 システム化計画","explanationJa":"プロジェクトや業務において、人的資源の喪失や減少を指す概念である。これは、従業員の退職、欠勤、またはスキル不足などが原因で発生する可能性がある。特に情報システムの導入時においては、システムの利用や運用に必要な知識や経験を持った人材が失われることで、プロジェクトの進行に影響を及ぼすリスクが高まる。例えば、新しいシステムの導入に伴い、特定の専門知識を持った従業員が退職すると、システムの運用や維持管理が困難になり、結果として業務効率や生産性が低下することがある。このようなリスクを評価し、対策を講じることは、システム化計画の成功に不可欠である。","explanationZh":"人员受伤、死亡、离职或关键技能流失等给组织造成的损失。除了直接成本，还可能影响业务连续性、知识传承和生产能力。"},{"id":"t0818","chapterId":"c45","chapterJa":"システム化計画","chapterZh":"信息化计划","termJa":"リスク測定","termZh":"风险测量","english":"Risk Assessment","reading":"りすくそくてい","breadcrumb":"10 システム企画10-1 システム化計画","explanationJa":"あるプロジェクトやシステムの導入に際して、潜在的なリスクを特定し、その影響や発生確率を評価するプロセスである。このプロセスは、システム化計画を立案する際に極めて重要で、導入後のトラブルを未然に防ぐための基礎となる。具体的には、情報システム導入時に考えられるリスク（技術的な問題、経済的な影響、人的要因など）を洗い出し、それぞれのリスクが現実化した場合の影響を定量的または定性的に評価する。このようにして、リスクの優先順位を付けたり、対策を講じたりすることが可能になり、プロジェクトの成功確率を高めることができる。リスク測定を行うことで、予期しない問題に対する備えが整い、スムーズなシステム導入が実現する。\nHOME»用語集»システム企画»要件定義","explanationZh":"利用定性或定量方法评价风险可能性、影响和损失规模，并形成可比较指标的过程。结果用于确定优先级和选择风险应对措施。"},{"id":"t0819","chapterId":"c46","chapterJa":"要件定義","chapterZh":"需求定义","termJa":"要求項目の洗出し","termZh":"需求项提取","english":"Requirements Elicitation","reading":"ようきゅうこうもくのあらいだし","breadcrumb":"10 システム企画10-2 要件定義","explanationJa":"要求項目の洗い出しとは、システムやプロジェクトに対して必要な要件を明確にし、整理するプロセスである。この作業は、ユーザーやステークホルダーから期待される機能や特性を収集し、後の設計や開発の基礎となる重要なステップである。具体的には、インタビューやワークショップ、アンケート調査などを通じて、直接的な意見や希望を引き出し、それを分析して取りまとめる。例えば、新しいソフトウェアを開発する際には、実際の使用者が何を求めているのか、どのような課題があるのかを理解するために、各関係者と対話しながら要求項目を洗い出す。このプロセスを通じて、開発チームはユーザーのニーズに合った製品を提供できるようになり、プロジェクトの成功率を高めることができる。","explanationZh":"通过访谈、问卷、观察、文档分析和研讨等方式，系统识别用户和业务对新系统的需求。应覆盖显性需求和潜在需求，并记录来源。"},{"id":"t0820","chapterId":"c46","chapterJa":"要件定義","chapterZh":"需求定义","termJa":"要求項目の分析","termZh":"需求项分析","english":"Requirement Analysis","reading":"ようきゅうこうもくのぶんせき","breadcrumb":"10 システム企画10-2 要件定義","explanationJa":"ソフトウェアやシステムに対するユーザーのニーズや要求を明確にするためのプロセスである。この分析は、プロジェクトの初期段階で実施され、関係者とのコミュニケーションを通じて行われることが多い。例えば、企業が新しい業務システムを導入する際に、ユーザーからの意見や期待を収集し、それを具体的な要求項目に整理する。この過程で、問題点や改善点が浮かび上がるため、後の開発が効率的に進む。プロジェクトの成功に直結する重要なステップであり、適切に行うことで、最終的な製品がユーザーのニーズに合致し、満足度を高めることができる。","explanationZh":"对收集到的需求进行整理、分类、去重、冲突解决、可行性和优先级分析。分析后形成清晰、一致、可验证的需求，为需求定义奠定基础。"},{"id":"t0821","chapterId":"c46","chapterJa":"要件定義","chapterZh":"需求定义","termJa":"ユーザーニーズ調査","termZh":"用户需求调查","english":"User Needs Assessment","reading":"ゆーざーにーずちょうさ","breadcrumb":"10 システム企画10-2 要件定義","explanationJa":"システムや製品を開発する際に、ユーザーがどのような機能やサービスを求めているのかを明らかにするための手法である。この調査は、実際の利用者や関係者から直接情報を収集することにより、彼らの期待や要求を理解することを目的としている。具体的には、インタビューやアンケート、観察などの方法を用いて、利用者の意見や体験を引き出すことが行われる。たとえば、新しいアプリケーションを開発する際に、ターゲットユーザーに対して調査を実施し、どのような機能が便利であると感じるかを確認する。このように、開発プロセスにおいて重要なステップであり、顧客満足度を向上させるための基盤となる。","explanationZh":"通过访谈、问卷、现场观察等了解用户目标、痛点、业务场景和期望。应避免只询问功能名称，而要理解用户真正需要解决的问题。"},{"id":"t0822","chapterId":"c46","chapterJa":"要件定義","chapterZh":"需求定义","termJa":"調査内容の分析","termZh":"调查内容分析","english":"Analysis of Survey Content","reading":"ちょうさないようのぶんせき","breadcrumb":"10 システム企画10-2 要件定義","explanationJa":"収集したデータや情報を整理し、意義を見出すプロセスを指す。特に要求分析の分野においては、ユーザーや利害関係者からのニーズを理解し、ソフトウェアやシステムの設計に役立てるために重要である。このプロセスでは、まず調査結果を定量的または定性的に評価し、データの傾向やパターンを明らかにする。その後、得られた情報を基にして関連する要件を抽出し、システム開発の方向性を定める。たとえば、ユーザーアンケートから得た意見やフィードバックを分析することで、製品の改善点を見つけ出したり、新機能の追加を検討したりすることができる。このように、効果的なシステム設計の基盤となり、プロジェクトの成功に寄与する要素である。","explanationZh":"对调查获得的数据和意见进行整理、比较和解释，找出共性需求、问题原因和优先级。分析结果用于形成需求和改进方向。"},{"id":"t0823","chapterId":"c46","chapterJa":"要件定義","chapterZh":"需求定义","termJa":"現状分析","termZh":"现状分析","english":"Current Analysis","reading":"げんじょうぶんせき","breadcrumb":"10 システム企画10-2 要件定義","explanationJa":"システムやプロジェクトが現在どのような状態にあるかを評価する作業を指す。これは、要求分析の手順の一環であり、既存のプロセスやシステムの問題点や課題を特定するために重要である。現状分析では、様々なデータを収集し、関係者とのインタビュー、観察、アンケートなどを通じて現在の状況を把握する。例えば、企業が新しいソフトウェアを導入する際には、自社の業務プロセスを分析し、どの部分が改善可能かを明らかにすることで、必要な機能や要件を定義することができる。これにより、プロジェクトの成功に向けた基盤を築くことができる。","explanationZh":"对当前业务流程、系统、组织、数据和问题进行客观调查和整理。通过“现状（As-Is）”分析识别瓶颈，为设计目标状态提供依据。"},{"id":"t0824","chapterId":"c46","chapterJa":"要件定義","chapterZh":"需求定义","termJa":"課題定義","termZh":"课题定义／问题定义","english":"Problem Definition","reading":"かだいていぎ","breadcrumb":"10 システム企画10-2 要件定義","explanationJa":"プロジェクトやシステムにおいて解決すべき問題や要求を明確にするプロセスである。この手順は、プロジェクトの成功に向けて必要不可欠であり、関係者が共通の理解を持つための土台を築く役割を果たす。具体的には、問題の範囲を特定し、達成すべき目標や制約条件を整理する。例えば、新しいソフトウェアの開発に際して、ユーザーがどのような機能を求めているのかをはっきりさせ、それに基づいて開発計画を立てる。この段階での明確な後の要件定義や設計の品質にも大きく影響を与えるため、慎重に行うべきである。","explanationZh":"把现状与目标之间的差距明确描述为需要解决的课题，并界定原因、影响和边界。问题定义准确与否直接影响后续解决方案质量。"},{"id":"t0825","chapterId":"c46","chapterJa":"要件定義","chapterZh":"需求定义","termJa":"要求仕様書","termZh":"需求规格说明书","english":"Requirements Specification","reading":"ようきゅうしようしょ","breadcrumb":"10 システム企画10-2 要件定義","explanationJa":"システムやソフトウェアの開発において、顧客やユーザーが求める機能や性能を明確に文書化したものである。この文書は、開発チームが要求を正確に理解し、適切なシステムを設計・実装するための基盤となる。例えば、ある企業が新しいアプリを開発する際、要求仕様書には、ユーザーが期待する機能（ログイン、データ検索など）や操作性、パフォーマンスの要件が含まれる。こうした明確な仕様を持つことで、プロジェクトの進行中に誤解や認識のズレを防ぎ、開発がスムーズに進むようになる。開発後のテストや評価の基準ともなり、品質の保障にも寄与する重要なドキュメントである。","explanationZh":"系统化记录功能、非功能、接口、数据、约束和验收条件等需求的文档。应尽量明确、一致、可追踪和可测试，作为设计、开发和验收的重要依据。"},{"id":"t0826","chapterId":"c46","chapterJa":"要件定義","chapterZh":"需求定义","termJa":"要件定義の目的","termZh":"需求定义的目的","english":"Purpose of Requirement Definition","reading":"ようけんていぎのもくてき","breadcrumb":"10 システム企画10-2 要件定義","explanationJa":"システム開発において求められる機能や性能、制約事項などを明確にすることを指す。これにより、開発チームは具体的なビジョンや目標をもって作業に取り組むことができ、プロジェクトの進行がスムーズになる。例えば、顧客の要望をしっかり把握することで、期待に応えたシステムを提供できる。要件定義は、ドキュメントとして文書化され、関係者間での合意形成の役割も果たす。これにより、誤解や誤った進行を防ぎ、最終的な結果の品質を向上させる。要件が明確であればあるほど、開発リソースの無駄遣いや納期遅延を避ける助けにもなる。","explanationZh":"把业务目标和用户需要转换成系统必须满足的明确条件，形成开发和采购的共同基准。良好的需求定义可减少后期返工、范围争议和验收困难。"},{"id":"t0827","chapterId":"c46","chapterJa":"要件定義","chapterZh":"需求定义","termJa":"業務要件定義","termZh":"业务需求定义","english":"Business Requirements Definition","reading":"ぎょうむようけんていぎ","breadcrumb":"10 システム企画10-2 要件定義","explanationJa":"システムやプロジェクトが満たすべきビジネス上のニーズや条件を明確にするプロセスである。この過程では、実際の業務フローや課題を理解し、それに基づいて必要な機能や性能を具体化することが求められる。例えば、顧客管理システムの導入においては、顧客情報の管理、売上分析、マーケティングツールとの連携などの要件が業務要件として定義される。このように、プロジェクトの成功に欠かせない重要なステップであり、適切に行うことで最終的なシステムがユーザーの期待を満たすものになる。さらに、要件が明確であればあるほど、開発やテストの際の手戻りが少なくなり、コストや時間の削減にも寄与する。","explanationZh":"明确业务目标、业务流程、规则、角色、数据和期望成果等业务层面的需求。它回答“业务为什么需要系统以及要实现什么”，是系统功能需求的上位依据。"},{"id":"t0828","chapterId":"c46","chapterJa":"要件定義","chapterZh":"需求定义","termJa":"業務処理手順","termZh":"业务处理流程","english":"Business Process Procedure","reading":"ぎょうむしょりてじゅん","breadcrumb":"10 システム企画10-2 要件定義","explanationJa":"特定の業務を遂行するために決められた一連のステップやルールのことである。これにより、業務が効率的かつ一貫性を持って行われることが可能になる。たとえば、受注から商品の発送に至るまでの流れを示す手順書などが挙げられる。関与する各担当者がどのように業務を進めるべきかを明確にするため、特にプロジェクト管理や品質管理の場面で重要である。また、業務改善のための基礎資料としても活用され、作業の見直しや改善が容易になる。これにより、全体の業務効率を向上させる効果が期待できる。","explanationZh":"描述业务活动按照何种顺序、由谁、使用什么信息完成的程序。可用流程图等形式表达，用于分析效率、控制点和系统支持需求。"},{"id":"t0829","chapterId":"c46","chapterJa":"要件定義","chapterZh":"需求定义","termJa":"機能要件定義","termZh":"功能需求定义","english":"Functional Requirements Definition","reading":"きのうようけんていぎ","breadcrumb":"10 システム企画10-2 要件定義","explanationJa":"システムやソフトウェアが果たすべき具体的な機能を明確にする作業である。この定義は、システムがどのように動作し、ユーザーにどのようなサービスを提供するかを示すものである。例えば、オンラインショッピングサイトでは、商品検索機能やカートに商品を追加する機能などが挙げられる。機能要件定義を行うことで、開発チームは求められる機能を正確に理解し、無駄な作業を避けることができる。また、この定義は品質保証やテストの指針にもなるため、プロジェクトの成功において非常に重要な役割を果たす。これにより、顧客の期待に応えるシステムを効果的に開発することが可能となる。","explanationZh":"明确系统需要提供的具体功能和行为，例如输入、处理、输出、查询和业务规则。功能需求应描述可观察结果并支持测试。"},{"id":"t0830","chapterId":"c46","chapterJa":"要件定義","chapterZh":"需求定义","termJa":"非機能要件定義","termZh":"非功能需求定义","english":"Non-Functional Requirements Definition","reading":"ひきのうようけんていぎ","breadcrumb":"10 システム企画10-2 要件定義","explanationJa":"システムやソフトウェアの性能や品質に関する要件を明確にするプロセスである。この定義は、機能要件がシステムの具体的な動作を示すのに対し、非機能要件は使い勝手や信頼性、セキュリティなど、システムの使い方や評価基準に関する側面を扱う。例えば、応答時間が2秒以内であることや、同時に100人のユーザーがアクセスできることなどが挙げられる。これにより、エンドユーザーはシステムを使用する際の満足度が向上し、ビジネスニーズに応じたシステムの設計が可能になる。非機能要件を十分に理解し、明確に定義することは、プロジェクトの成功にとって非常に重要である。","explanationZh":"明确性能、可靠性、可用性、安全性、可维护性、容量和易用性等质量属性。应尽可能给出数值或可验证条件，而不是使用“快速”“安全”等模糊表述。"},{"id":"t0831","chapterId":"c46","chapterJa":"要件定義","chapterZh":"需求定义","termJa":"セキュリティ要件","termZh":"安全需求","english":"Security Requirements","reading":"せきゅりてぃようけん","breadcrumb":"10 システム企画10-2 要件定義","explanationJa":"システムやアプリケーションが持つべきセキュリティの基準や条件を指す。これにより、情報の機密性、完全性、可用性を守るための具体的な指針が示される。たとえば、ユーザーのパスワードは一定の長さや複雑さを要求し、不正アクセスを防ぐための二段階認証を導入することなどがある。また、データの保存や通信時には暗号化が求められ、外部からの攻撃や情報漏洩を防ぐ対策が必須となる。これらの要件を適切に設定・実施することで、システムの信頼性が向上し、ユーザーからの信頼を得ることが可能となる。プロジェクトの早い段階で明確に定義されるべきで、変更管理やリスク評価の手段としても重要である。","explanationZh":"为保护系统和数据而规定的认证、授权、加密、日志、备份、漏洞管理、事件响应等安全要求。安全需求应源自风险评估、法律法规和业务重要性。"},{"id":"t0832","chapterId":"c46","chapterJa":"要件定義","chapterZh":"需求定义","termJa":"情報・データ要件","termZh":"信息与数据需求","english":"Information and Data Requirements","reading":"じょうほう・でーたようけん","breadcrumb":"10 システム企画10-2 要件定義","explanationJa":"システムやアプリケーションが扱うべき情報やデータの具体的な内容や形式を定義するものである。要件定義の段階でこれを明確にすることで、開発チームは必要な機能やデータの整合性を理解し、適切な設計を行うことが可能になる。例えば、顧客情報を管理するシステムでは、顧客名、住所、電話番号などの具体的なデータが必要とされる。また、データの形式や保存方法、更新頻度なども明記されることが多く、これによりシステムが正しく機能するための基盤が築かれる。このような要件を詳細に設定することで、後の開発や運用において問題を未然に防ぎ、効果的なシステムを構築する助けとなる。","explanationZh":"规定系统需要处理哪些数据、数据结构、来源、质量、保存期限、访问权限和生命周期等要求。它是数据库设计、接口和数据治理的重要依据。"},{"id":"t0833","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"システムインテグレータ","termZh":"系统集成商（SI）","english":"System Integrator","reading":"","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"異なるシステムや技術を統合し、一つの機能的なシステムを構築する専門家や企業である。彼らは、クライアントの要望に応じて、ハードウェアやソフトウェア、ネットワークを組み合わせ、全体の最適化を図る役割を担当する。例えば、企業が新しい業務システムを導入する際、既存の資源を考慮しながら、必要な技術やプラットフォームを選定し、実装計画を策定する。このプロセスには、調達と調達計画が関わり、適切な資材やサービスの選定、コスト管理、納期の調整などが含まれる。こうした総合的なアプローチにより、クライアントのビジネスニーズに合った効率的かつ効果的なシステムが実現される。","explanationZh":"负责把硬件、软件、网络和服务等组合为满足客户需求的整体信息系统的企业或组织。其工作可涵盖咨询、设计、开发、导入和运维。"},{"id":"t0834","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"SI事業者","termZh":"SI企业／系统集成商（SIer）","english":"SIer","reading":"えすあいじぎょうしゃ","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"システムインテグレーションを行う企業を指す。これは、顧客のニーズに応じて、情報システムやソフトウェアを設計、開発、導入、運用といった全てのプロセスを支援する役割を果たす事業者である。例えば、企業が新しい業務システムを導入する際に、SI事業者はそのシステムの要件を分析し、最適なソリューションを提案する。この際、ハードウェアの選定からソフトウェアのカスタマイズ、さらに導入後の保守・運用まで、トータルでサービスを提供する。これにより、企業は自社の業務に最も適したシステムを持つことができ、効率化やコスト削減が期待できる。特定の業界や技術に特化することが多く、幅広い経験と知識を活かしてソリューションを提供している。","explanationZh":"日本IT行业常用称呼，指从事系统集成业务的企业。通常根据客户需求负责系统规划、开发、集成和运维支持。"},{"id":"t0835","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"アウトソーシング","termZh":"外包","english":"Outsourcing","reading":"","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"企業が特定の業務を自社内ではなく、外部の専門業者に委託することを指す。これにより、企業は内部リソースを他の重要な業務に集中させることができ、効率化を図ることが可能である。例えば、会計業務やITサポート、人事管理などがアウトソーシングの対象として一般的である。外部の専門家が業務を担当することにより、高度な技術やノウハウを活用できるメリットがある。また、コスト削減や時間短縮にも寄与し、企業全体の競争力を高めることが期待される。ただし、適切な業者の選定や契約管理が必要で、リスク管理も重要な課題となる。","explanationZh":"把原由组织内部执行的部分业务或IT职能委托给外部服务商。外包可以提高专业性和效率，但组织仍需管理合同、服务水平、信息安全和供应商风险。"},{"id":"t0836","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"ライセンス管理","termZh":"许可证管理","english":"License Management","reading":"らいせんすかんり","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"ソフトウェアや技術を合法的に使用するための権利を適切に管理するプロセスである。企業がソフトウェアやデジタルコンテンツを利用する際、購入したライセンスの条件を遵守し、その使用状況を把握することが重要である。ライセンス管理により、不正使用を防ぎ、法的なトラブルを避けることができる。例えば、特定のソフトウェアが複数のユーザーに使用される場合、ライセンス管理によって、その数がライセンスの範囲内であることを確認する。さらに、ライセンスの更新や管理に必要な情報を整理し、適切な調達計画と連携することで、コストの最適化と業務効率の向上を図ることが可能である。このように、ライセンス管理は企業運営において欠かせない要素となっている。","explanationZh":"对软件和其他使用权许可的采购、数量、分配、使用、续期和终止进行管理。目标是确保合法合规并避免多买或少买造成浪费和风险。"},{"id":"t0837","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"構成管理","termZh":"配置管理","english":"Configuration Management","reading":"こうせいかんり","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"システムやソフトウェアの構成要素を把握し、管理するプロセスである。これにより、各要素の変更履歴や依存関係を明確にすることで、システム全体の安定性や信頼性が向上する。例えば、ソフトウェア開発においては、ソースコードやドキュメント、コンフィグレーションファイルなどが構成要素となる。構成管理を行うことで、新しいバージョンのリリースやバグ修正の際に、既存の機能に悪影響を与えずに変更を安全に行うことができる。また、適切な構成管理ツールを利用することで、チーム内の協力が促進され、作業の効率が上がる。これにより、プロジェクト全体の進行がスムーズになり、品質向上にも寄与する。","explanationZh":"持续识别和控制系统组件、版本、参数及相互关系，确保配置状态准确可追踪。它为变更、故障分析和资产管理提供基础信息。"},{"id":"t0838","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"調達の代表的な方法","termZh":"典型采购方式","english":"Typical Procurement Methods","reading":"ちょうたつのだいひょうてきなほうほう","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"企業や組織が必要な商品やサービスを入手するための手段を指す。主に、競争入札、指名入札、協議入札および随意契約が一般的である。競争入札は、多くの業者が参加し、最も条件の良い提案を選定する方法で、公平性が高いのが特徴である。指名入札は、予め選定された業者にのみ入札を依頼するもので、特定の業者の技術や信頼性を重視している。協議入札は、事前に相談の上で条件を決定する方式で、柔軟な対応が可能なため、複雑な案件に適している。最後に、随意契約は、特定の業者と直接契約を結ぶ方法で、迅速に調達を行うことができるが、競争性が低いため注意が必要である。これらの方法を適切に活用することで、効率的な調達が実現できる。","explanationZh":"组织获取系统、软件和服务时采用的常见方法，例如公开招标、竞争性报价、提案评选或直接采购等。应根据金额、复杂度、公平性和风险选择适当方式。"},{"id":"t0839","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"RFI","termZh":"信息请求书（RFI）","english":"Request for Information","reading":"あーるえふあい","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"調達プロセスにおいて、特定の製品やサービスについての情報を集めるために発行される文書である。企業や組織は、RFIを通じて潜在的なサプライヤーから、製品の特長や価格、サービス内容などの詳細な情報を求める。これにより、適切な供給業者を選定するための基礎データを収集することが目的である。例えば、新しいITシステムを導入する際に、複数のベンダーから提供可能なソリューションについての情報を請求することが一般的である。選択肢を広げるための重要なステップであり、その後のRFP（提案依頼書）や入札プロセスにおいて、より具体的な評価を行うための参考資料ともなる。","explanationZh":"采购前向潜在供应商收集产品、技术、市场能力和解决方案信息的文件。RFI主要用于调查市场和完善需求，通常不是最终采购承诺。"},{"id":"t0840","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"RFP","termZh":"建议书征询书（RFP）","english":"Request For Proposal","reading":"あーるえふぴー","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"企業や団体が特定のサービスや製品を外部の業者に求める際に作成される文書である。提案依頼書は、業者に対して具体的な要件や条件を提示し、それに基づいて提案を求めるために使用される。例えば、新しいソフトウェアの導入を検討している企業がRFPを発行することで、各社から見積もりや提案を集め、最も適した業者を選定することができる。このプロセスは、透明性と競争性を持たせるため重要であり、コストや品質の両面で有利な条件を引き出す役割を果たす。調達の方法として広く利用され、プロジェクトの成功を左右する重要なステップとなる。","explanationZh":"向供应商说明项目背景、需求、范围和评选条件，并要求其提交具体解决方案和提案的采购文件。RFP常用于比较技术、实施方案和价格。"},{"id":"t0841","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"RFQ","termZh":"报价请求书（RFQ）","english":"Request for Quotation","reading":"あーるえふきゅー","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"商品やサービスの価格見積もりを求めるために企業や団体が作成する文書である。この文書は主に調達プロセスの一部として使用され、特定の要件や条件を企業に伝え、各社からの見積もりを取得することを目的としている。たとえば、ある会社が新しい機器を購入する際、複数のサプライヤーにRFQを送信し、価格や納期、条件などを比較することで、最適な業者を選定することができる。このように、RFQは業務の効率化やコスト削減に寄与し、企業が市場で競争力を維持するための重要な手段となっている。","explanationZh":"在规格和采购内容较明确时，向供应商请求价格和交易条件的文件。RFQ主要用于获取可比较的报价，技术方案讨论通常少于RFP。"},{"id":"t0842","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"対象範囲","termZh":"对象范围／工作范围","english":"Scope of Work","reading":"たいしょうはんい","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"プロジェクトや業務において、実施する内容や範囲を明確に定義するものである。特に、調達の実施や提案依頼書においては、どの部分を対象とするかを詳しく記載することが重要であり、これにより関係者間での認識のズレを防ぐことができる。具体的には、提供される商品やサービス、求める品質、納期、作業の場所などが含まれる。例えば、市場調査を行う場合、その対象範囲には調査する地域や調査する業種が明示される。これにより、入札者は明確な基準を持って提案を行うことができ、発注者も適切な選定を行えるようになる。対象範囲の設定は、プロジェクトの成功やコスト管理に直接影響を与えるため、慎重に行う必要がある。","explanationZh":"项目或采购中明确哪些业务、系统、组织、功能和工作属于本次对象，哪些不属于。范围清晰可减少责任争议和需求蔓延。"},{"id":"t0843","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"システムモデル","termZh":"系统模型","english":"System Model","reading":"","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"特定のシステムやプロジェクトの構成や動作を抽象的に表現したものである。このモデルは、システムの要件や機能を理解しやすくするために利用される。例えば、提案依頼書においては、システムモデルを用いることで、発注者が求める機能や性能、構成要素を明確に伝えることができる。システムモデルには、データフロー図やユースケース図などがあり、それぞれ異なる視点からシステムを視覚的に示す役割を持つ。これにより、システム開発に関わる全ての関係者が共通の理解を持つことができ、円滑なコミュニケーションが促進される。さらに、システムモデルを基にして、実際の設計や実装が進められるため、プロジェクトの成功に向けた重要な基盤として機能する。","explanationZh":"用图形或形式化方法表示系统结构、组件、数据、流程和相互关系的抽象模型。它帮助相关方理解复杂系统并支持设计和评审。"},{"id":"t0844","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"サービス要件","termZh":"服务需求","english":"Service Requirements","reading":"さーびすようけん","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"特定のサービスを提供するために必要とされる条件や仕様のことを指す。これは、提案依頼書（RFP）などで明示され、サービスを選定する際の基準となる。例えば、ITシステムの導入を考える場合、システムの機能、性能、安全性、コストなどがサービス要件に含まれる。これにより、サービス提供者は顧客の期待に応えるための具体的なプランを策定できる。また、明確なプロジェクトの成功を確保するために重要であり、今後の運用や保守にも影響を及ぼす。要件が適切に定義されていれば、価格やサービスの質を比較しやすくなり、最適な選択が可能になる。","explanationZh":"客户和业务对服务内容、质量、可用性、支持、安全和容量等方面的要求。应转换为可测量目标并反映到设计和SLA中。"},{"id":"t0845","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"目標スケジュール","termZh":"目标进度计划","english":"Target Schedule","reading":"もくひょうすけじゅーる","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"プロジェクトや業務の達成すべき期限や重要なマイルストーンを示す計画である。このスケジュールに基づいて、各作業の開始や終了時期が設定され、プロジェクトの進捗状況を把握するための指標となる。例えば、提案依頼書を作成する際には、目標スケジュールを設定し、いつまでに提案を受け付けて、評価を行うのかを明示することが求められる。これにより、関係者はプロジェクトの進行を共有し、業務の効率を高めることができる。また、目標スケジュールは随時見直されることがあり、状況に応じて調整することで、より良い成果を得るための役割も果たす。","explanationZh":"项目或采购希望达到的主要里程碑、交付和完成时间安排。供应商应基于此提出可实现的详细计划，并识别关键路径和风险。"},{"id":"t0846","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"契約条件","termZh":"合同条件","english":"Contract Terms","reading":"けいやくじょうけん","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"調達や取引において合意される具体的な規則や条件を指す。これらの条件には、価格、納期、品質、支払い方法などが含まれ、契約当事者の権利と義務を明確に定める役割を果たす。例えば、提案依頼書に記載された契約条件が双方で合意されることで、後のトラブルを防ぎ、円滑な取引が進行することが期待される。また、リスクマネジメントにも重要であり、問題が発生した場合の対処方法を事前に決めておくことで、企業間の信頼関係を築く助けとなる。適切な契約条件の設定は、調達の成功に欠かせない要素である。","explanationZh":"合同中规定的价格、范围、期限、付款、验收、责任、知识产权、保密和解除等条件。IT合同还应明确安全、数据和服务水平要求。"},{"id":"t0847","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"ベンダーの経営要件","termZh":"供应商经营条件要求","english":"Vendor Management Requirements","reading":"べんだーのけいえいようけん","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"企業がサプライヤーやサービス提供者との関係を管理するために必要な基準や条件を指す。これらの要件は、業者が提供するサービスの品質、コスト、納期などを保証し、調達プロセスの円滑化を目的としている。例えば、ベンダーが遵守すべき契約内容、技術的要件、サービスレベルの目標などが含まれる。提案依頼書においては、これらの要件を明示することで、候補となるベンダーが自社の期待に沿った提案を行うことが促される。また、これにより選定プロセスの透明性が保たれ、適切なパートナー選びが可能になる。企業が持続的な関係を築くための重要な要素である。","explanationZh":"采购方对供应商财务稳定性、经营持续性、治理、合规和风险管理等方面提出的要求。其目的在于降低供应商倒闭或经营问题导致的履约风险。"},{"id":"t0848","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"ベンダーのプロジェクト体制要件","termZh":"供应商项目体制要求","english":"Vendor Project Management Requirements","reading":"べんだーのぷろじぇくとたいせいようけん","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"プロジェクトに参加するベンダーが遵守すべき管理体制や手続きの要件を示すものである。この要件は、プロジェクトの成功に必要なリソースの配置やコミュニケーションの方法、役割分担などを含む。例えば、ベンダーはプロジェクトマネージャーを指定し、定期的に進捗報告を行うことが求められることがある。また、異なるベンダー間で効果的に連携するためのルールやベストプラクティスも設定される。これにより、プロジェクトの全体像が明確になり、リスク管理や問題解決がよりスムーズに進むことが期待される。プロジェクト体制要件を明確にすることは、調達のプロセスにおいて非常に重要であり、品質や納期の確保につながる。","explanationZh":"对供应商项目经理、团队结构、人员数量、职责、沟通和质量管理体系等提出的要求。适当体制是项目按期、按质交付的重要保障。"},{"id":"t0849","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"ベンダーの技術及び実績評価","termZh":"供应商技术能力与业绩评价","english":"Vendor Technology and Performance Evaluation","reading":"べんだーのぎじゅつおよびじっせきひょうか","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"製品やサービスを提供する業者（ベンダー）が持つ技術的な能力や過去の実績を評価するプロセスである。この評価は、提案依頼書を通じて行われ、業者が信頼できるかどうかや、提供する製品やサービスが求められる水準を満たすかを判断するために重要である。例えば、過去のプロジェクトでの成功事例や技術的な専門知識が評価基準となる。このプロセスを通じて、最適な業者を選定することで、調達の成功率を高め、品質や納期の向上に寄与する。評価が適切に行われることで、将来のビジネスパートナーシップや協力関係の構築にもつながる。","explanationZh":"通过技术资格、人员技能、同类项目经验、客户案例和实施成果等评价供应商是否具备履约能力。应使用客观标准并结合项目需求判断。"},{"id":"t0850","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"提案書・見積書","termZh":"提案书／报价单","english":"Proposal and Quotation","reading":"ていあんしょ・みつもりしょ","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"主に調達やプロジェクトにおいて、提案内容や費用を明確に示す文書である。提案書は、特定の業務やサービスに関する解決策を提示し、どのように問題を解決するかを説明するものである。この文書には、アイデアの背景や実施方法、予想されるメリットが含まれる。一方、見積書は、提供されるサービスや商品の詳細、数量、価格を明示し、発注者に対してコストを把握させる役割がある。これらの文書は、企業間の信頼関係を構築するための重要なツールであり、明確な情報提供により誤解を防ぎ、スムーズな取引を促進することが期待される。","explanationZh":"供应商针对采购需求提交的解决方案、实施方法、计划、人员和费用等文件。采购方据此比较不同供应商的适合度和成本。"},{"id":"t0851","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"提案評価基準","termZh":"提案评价标准","english":"Proposal Evaluation Criteria","reading":"ていあんひょうかきじゅん","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"調達において企業や団体が提案を評価する際に用いる基準のことである。この基準は、入札や提案書を査定し、最適な提案を選定するために設定される。例えば、価格、技術力、納期、過去の実績などが評価項目に含まれることが一般的である。提案評価基準を明確にすることで、評価者は公平かつ客観的な判断を行うことができ、ベンダーの選定過程が透明性を持つようになる。また、基準に基づく評価は、より質の高いサービスや製品を得るための重要な要素となり、最終的には調達の成功につながることが期待される。","explanationZh":"事先规定用于评价供应商提案的指标、权重和评分方法，例如需求符合度、技术、体制、进度、价格和风险。明确标准可提高采购公平性和可解释性。"},{"id":"t0852","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"要求事項適合度","termZh":"需求符合度","english":"Degree of Compliance with Requirements","reading":"ようきゅうじこうてきごうど","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"特定の部署やプロジェクトにおいて求められる要件や条件が、実際に提供される製品やサービスにどれだけ適合しているかを示す指標である。この指標は、調達選定プロセスにおいて非常に重要で、供給者が提供するものが要求を満たしているかどうかを評価するために用いられる。例えば、ある部品が技術的な仕様や納期、コストなどの要求をクリアしている場合、その部品の要求事項適合度は高いと言える。高い適合度は、調達先が信頼できることを示し、プロジェクトの成功に寄与するため、企業はこの評価を重視する。適合度を測ることで、より良い調達先を選ぶための基準が整えられる。","explanationZh":"供应商方案或系统满足规定需求的程度。评价时应区分完全满足、部分满足、需定制和不满足等，并关注关键必备需求。"},{"id":"t0853","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"費用内訳","termZh":"费用明细","english":"Cost Breakdown","reading":"ひよううちわけ","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"特定のプロジェクトや調達において、全体の費用を構成する要素を詳細に分けて示すものである。費用内訳を作成することで、各項目がどのように費用に寄与しているかを明確にすることができ、予算管理やコスト削減のための分析が行いやすくなる。例えば、調達活動では、材料費、人件費、運搬費などが明示されることで、透明性が向上し、関係者が納得しやすい。また、費用内訳を用いることで、全体のコストの見える化が進み、調達戦略の見直しや効果的な交渉を行うための基盤となる。結果として、合理的な意思決定が促進される。","explanationZh":"把总费用按硬件、软件、开发、人员、维护、培训等项目分解列示的资料。费用明细有助于比较报价、确认范围和分析全生命周期成本。"},{"id":"t0854","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"工程別スケジュール","termZh":"分阶段进度计划","english":"Process-Specific Schedule","reading":"こうていべつすけじゅーる","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"特定の工程ごとに作業のスケジュールを示すものである。このスケジュールは、調達プロセスや製造工程を効率的に管理するために用いられる。各工程における作業の開始日や終了日、投資が必要な資源などを整理することで、全体の進行状況を把握しやすくなる。例えば、部品の発注、検品、納品までの各工程がいつ行われるのかを明確にすることで、遅延のリスクを減らし、計画通りにプロジェクトを進めることが可能になる。また、これにより調達先とのコミュニケーションも円滑になり、適切なタイミングで必要な資材を手配することができる。工程別スケジュールの活用は、プロジェクト管理において極めて重要な要素である。","explanationZh":"按需求、设计、开发、测试、迁移等阶段详细列出开始、结束、里程碑和依赖关系的计划。它用于监控项目进度和协调资源。"},{"id":"t0855","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"最終納期","termZh":"最终交付期限","english":"Final Delivery Date","reading":"さいしゅうのうき","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"契約や取引において、納品が完了しなければならない最終的な期限を指す。これは、調達プロセスにおいて非常に重要であり、納品の遅延が生産やプロジェクトの進行に影響を与える可能性があるため、関係者全員が時間を守る必要がある。例えば、建設プロジェクトでは、材料や設備の最終納期が守られなければ、工事が遅れてしまい、全体のスケジュールが狂ってしまうこともある。また、最終納期を守るためには、適切な在庫管理やサプライヤーとの調整が必要で、これらを的確に行うことで円滑な調達が実現する。納期の管理は、業務の効率化や顧客満足度向上にも寄与するため、計画段階から検討することが重要である。","explanationZh":"合同或项目规定全部成果物必须完成并交付的最后日期。逾期可能影响业务计划并产生合同责任，因此需重点管理关键路径。"},{"id":"t0856","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"受入システム","termZh":"验收体制","english":"Acceptance System","reading":"うけいれしすてむ","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"調達プロセスの一環として、納入された商品やサービスが契約内容に適合しているかを確認するためのシステムである。このシステムは、商品の受領時に品質や数量をチェックし、問題があれば適切な対応を行うことを目的としている。具体的には、受け取った商品が発注した通りであるかを確認し、不良品や不足品があれば返品や再発注を行う仕組みとなっている。また、受領情報を記録し、将来の参考やトレーサビリティを確保するために重要である。このように、受入システムは調達の効率化やコスト管理に寄与し、企業の運営において欠かせない役割を果たすのである。","explanationZh":"客户为检查交付系统是否满足要求而建立的组织、人员、流程和责任安排。应明确验收负责人、测试环境、标准和问题处理方式。"},{"id":"t0857","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"費用","termZh":"费用","english":"Cost","reading":"ひよう","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"製品やサービスを生産・提供するために必要とされる金銭的な支出のことである。具体的には、原材料費、人件費、設備投資などが含まれ、これらは企業の運営において重要な要素となる。例えば、ある製品を製造する際には、原材料の購入や労働者への賃金が必要であり、これらが合算されてその製品の総コストを構成する。さらに、調達の実施においては、契約締結時にこれらの費用を明確にし、発注先との透明な取引を行うことが求められるため、適切な費用管理は企業にとっても大変重要である。費用を正確に把握することで、適正価格の設定や利益の最大化を図ることが可能となる。","explanationZh":"为取得产品、服务或完成活动所支付或消耗的经济资源。项目和采购中应综合考虑初始费用、运行费用及风险成本。"},{"id":"t0858","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"受入時期","termZh":"验收时期","english":"Receiving Period","reading":"うけいれじき","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"調達業務において、契約が締結された後に納入が開始される期間を指す。この時期は、必要な物品やサービスが指定された日時に受け取られることを保証するために重要である。例えば、製品の納入日が契約で決まっている場合、その日付が受入時期となる。この受入時期を管理することで、調達プロセスが円滑に進み、必要な資材がタイムリーに提供されることが確保される。また、受入時期の明確化は、供給者との信頼関係を構築する上でも重要であり、納品遅延などのトラブルを防ぐために役立つ。調達活動の成功に向けて、受入時期の設定と管理は欠かせない要素である。","explanationZh":"客户计划进行或完成验收工作的时间安排。应与交付、测试、业务上线和付款条件协调，并预留缺陷修正时间。"},{"id":"t0859","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"発注元とベンダー企業の役割分担","termZh":"发包方与供应商的角色分工","english":"Roles and Responsibilities of Clients and Vendor Companies","reading":"はっちゅうもととべんだーきぎょうのやくわりぶんたん","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"調達プロセスにおいて、発注元とベンダー企業がそれぞれ果たすべき役割や責任を明確にすることを指す。発注元は、製品やサービスのニーズを特定し、予算やスケジュールを管理する役割を持つ。一方、ベンダー企業は、発注元が求める条件に基づいて製品やサービスを提供し、品質や納期を守る責任がある。具体的には、発注元が仕様書を作成し、その内容をもとにベンダー企業が提案を行う流れが存在する。この役割分担により、お互いの期待を明確にし、スムーズな取引を可能にすることができる。また、問題が発生した際も役割が明確であれば、迅速な対応が期待される。","explanationZh":"明确客户与供应商分别负责需求、设计、开发、数据准备、测试、验收、运维和安全等工作。清晰分工可以避免工作遗漏和责任推诿。"},{"id":"t0860","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"ソフトウェア開発委託モデル契約","termZh":"软件开发委托示范合同","english":"Software Development Outsourcing Model Contract","reading":"そふとうぇあかいはついたくもでるけいやく","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"企業が自社のソフトウェアを外部の業者に開発を依頼する際に結ぶ契約である。この契約は、開発プロセスや納期、費用、品質要件などの詳細を明確にし、委託する側と受託する側の権利と義務を規定するために重要である。具体的な例として、特定の機能を持つアプリケーションの開発を外部に依頼する場合、双方が合意した内容に基づいて作業を進める。このように、ソフトウェア開発委託モデル契約を結ぶことで、リスクを軽減し、スムーズなコミュニケーションを図ることができる。また、適切な契約書があれば、トラブルが発生した際にも対応しやすくなるため、企業にとって重要なビジネスツールとなる。","explanationZh":"日本用于软件开发委托交易的示范合同，帮助双方明确工作范围、成果、验收、费用、知识产权、变更和责任。实际使用时应根据项目情况调整条款。"},{"id":"t0861","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"情報システム・モデル取引・契約書","termZh":"信息系统示范交易合同","english":"Information System Model Transaction Contract","reading":"じょうほうしすてむ・もでるとりひき・けいやくしょ","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"情報システムの導入や運用に関する契約のひな型である。これは、取引の条件や範囲、責任を明示するために作成されるもので、企業間の取引を円滑に進めるための重要な文書である。モデル契約書は、一般的な商取引における標準的なルールを提供し、リスク管理や誤解を避ける手助けをする。また、契約内容が明確であるため、双方の権利や義務がはっきりと示され、トラブルが生じた際の目安にもなる。このように、情報システムに関連する契約書は、信頼性のある取引を行うために必要不可欠な要素である。","explanationZh":"日本为信息系统交易提供的参考合同体系，用于规范开发、运维等交易中的权利义务和风险分配。其目标是减少IT交易中的理解差异和纠纷。"},{"id":"t0862","chapterId":"c47","chapterJa":"調達計画・実施","chapterZh":"采购计划与实施","termJa":"知的財産権利用許諾契約","termZh":"知识产权许可合同","english":"Intellectual Property License Agreement","reading":"ちてきざいさんけんりようきょだくけいやく","breadcrumb":"10 システム企画10-3 調達計画・実施","explanationJa":"特許、商標、著作権などの知的財産権を持つ者が、その権利を他者に利用させるために締結される契約である。この契約により、権利者は許可を与えた相手に対して、特定の条件下で権利を使用することを認める。例えば、著作物の使用を許可する際、著作権者が著作物の利用方法や範囲、報酬などを定めることが一般的である。この契約は知的財産の保護と活用において重要な役割を果たし、企業や個人が権利を正当に活用するための基盤を提供する。正確な条件を明記することで、後のトラブルを避けることができるため、慎重な取り決めが求められる。\nHOME»用語集»企業活動»経営・組織論","explanationZh":"权利人允许另一方在规定范围、期限、地域和用途内使用专利、著作权、商标或软件等知识产权的合同。应明确许可范围、费用、再许可和侵权责任。"},{"id":"t0863","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"PDCA","termZh":"PDCA循环","english":"Plan-Do-Check-Act","reading":"ぴーでぃーしーえー","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"経営やプロジェクト管理において、業務の改善を行うための循環的手法である。計画（Plan）、実行（Do）、評価（Check）、改善（Act）の4つのステップから成り立っており、これを繰り返すことで業務の質を向上させる。例えば、新しい製品を市場に投入する際には、最初に計画を立て、その後実行に移し、効果を評価し、その結果に基づいて改善策を講じる。このサイクルを繰り返すことで、問題を的確に把握し、持続的な改善が実現できる。また、PDCAはチーム全体でのコミュニケーションを促進し、組織全体の成長を支える重要なフレームワークである。","explanationZh":"Plan（计划）—Do（执行）—Check（检查）—Act（改进）的持续改进管理循环。通过反复执行四个阶段，使流程和管理体系持续优化。"},{"id":"t0864","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"CEO","termZh":"首席执行官（CEO）","english":"Chief Executive Officer","reading":"しーいーおー","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"企業や組織の最高経営責任者を指す役職である。CEOは経営戦略の策定や実行、全体の運営管理、重要な意思決定など、組織の成長と成功に大きな影響を与える役割を担っている。具体的には、財務計画、マーケティング戦略、人材管理など、組織内のさまざまな分野におけるリーダーシップを発揮し、取締役会やステークホルダーと連携することが求められる。また、CEOは組織のビジョンやミッションを実現するために長期的な目標を設定し、従業員や関係者にその方向性を示す重要な役割も果たす。","explanationZh":"组织最高层经营负责人，负责整体经营战略和最终管理责任。信息安全属于经营风险时，CEO也应确保组织建立适当治理和资源投入。"},{"id":"t0865","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"CIO","termZh":"首席信息官（CIO）","english":"Chief Information Officer","reading":"しーあいおー","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"企業や組織において情報技術（IT）戦略を策定・推進する責任を持つ役職である。主に、情報システムの導入や管理、データのセキュリティ確保、そして業務プロセスの改善を通じて、組織の競争力を高める役割を果たす。CIOは経営層の一員として、IT投資の優先順位を決め、ビジネス全体の戦略と整合させることが求められる。例えば、新たなテクノロジーの導入によって顧客サービスを向上させたり、効率を上げたりするための計画を立案することが重要な任務であり、その成果は組織の成長に直接的な影響を与える。","explanationZh":"负责组织信息化、IT战略、信息系统投资和数字资源管理的高级管理者。CIO应使IT战略与业务战略保持一致。"},{"id":"t0866","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"CDO","termZh":"首席数字官（CDO）","english":"Chief Digital Officer","reading":"しーでぃーおー","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"企業におけるデジタル戦略を推進する最高責任者である。デジタル技術を活用して企業のビジネスモデルやプロセスを革新し、競争力を向上させる役割を担っている。例えば、顧客とのコミュニケーションをデジタル化したり、データ分析を通じて市場のニーズを把握することで、企業の経営戦略に貢献する。このポジションは、IT部門だけでなく、マーケティングや営業など様々な部門と連携しながら、全体としてのデジタルトランスフォーメーションを実現することが求められる。企業がデジタル化を進める中で、CDOの重要性はますます高まっている。","explanationZh":"负责推动组织数字化和数字转型的高级管理角色。其职责常涉及数据、数字业务模式、客户体验和跨部门转型。"},{"id":"t0867","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"CISO","termZh":"首席信息安全官（CISO）","english":"Chief Information Security Officer","reading":"しーあいえすおー","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"企業や組織における最高情報セキュリティ責任者である。情報セキュリティ戦略の立案や実施、情報資産の保護、リスク管理などを担当する重要な役割を果たす。このポジションには、サイバー攻撃やデータ漏洩などのリスクから組織を守るための専門知識が求められ、セキュリティ体制の強化や意識向上を図るための施策を推進することが期待されている。CISOは経営層と連携し、セキュリティがビジネスに与える影響を考慮しながら戦略的な決定を行うことが重要である。","explanationZh":"负责组织整体信息安全战略、治理、风险和安全能力建设的高级负责人。CISO通常向高层报告重大网络风险和事件，并协调安全资源。"},{"id":"t0868","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"CPO","termZh":"首席隐私官（CPO）","english":"Chief Privacy Officer","reading":"しーぴーおー","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"企業や組織においてプライバシー政策を管理・実施する責任を持つ役職である。主に個人情報の保護やその管理に関連する法律や規制に従った対策を講じる役割を果たす。例えば、顧客の個人情報を安全に取り扱うためのポリシーを策定し、従業員に対する教育や研修を行うことが求められる。データ漏洩や不正使用を防ぐための措置を講じ、情報セキュリティ部門とも連携してリスク管理を図ることが重要である。このように、CPOの役割は企業の信頼性を高め、顧客や取引先との良好な関係を維持する上で不可欠である。","explanationZh":"负责组织隐私和个人信息保护战略、合规与治理的高级负责人。其工作包括隐私政策、数据处理监督、PIA和监管沟通等。"},{"id":"t0869","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"ケーススタディ","termZh":"案例研究","english":"Case Study","reading":"","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"特定の状況や事例を詳細に分析し、その結果から学びを得る手法である。主にビジネスや教育、医療などの分野で用いられ、実際の事例を基に課題解決や戦略の立案を行う際に効果的である。例えば、企業の人材管理においては、成功した採用方法や社員の育成プログラムをケーススタディとして研究することで、他の企業でも役立つ知見を得ることができる。この手法は、理論だけでなく実践に基づいたアプローチを重視するため、より現実的な解決策を導き出すのに役立つ。","explanationZh":"通过分析真实或模拟案例的背景、问题、决策和结果来学习和解决问题的方法。案例研究有助于将理论应用到复杂实际情境。"},{"id":"t0870","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"リスキリング","termZh":"再技能培训（Reskilling）","english":"Reskilling","reading":"","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"従業員が新しいスキルや知識を習得するためのプロセスを指す。主に、仕事の変化や新しい技術の導入に対応するために行われる。例えば、製造業の従業員が新しい機械を操作するために必要な技術を学ぶ場合がある。企業が競争力を維持するためや、従業員のキャリア成長を支援するために重要な取り組みである。また、テクノロジーの進化によって求められるスキルが変わる中で、リスキリングを通じて、従業員が柔軟にキャリアを築ける環境を整えることが必要とされている。これは、企業の持続可能な成長にも寄与する。","explanationZh":"为了适应岗位变化、技术革新或职业转型，让人员学习新的技能组合。数字化转型中常通过再技能培训提升数据、AI和网络安全能力。"},{"id":"t0871","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"e-ラーニング","termZh":"电子学习（e-Learning）","english":"e-Learning","reading":"いーらーにんぐ","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"電子的な手段を利用して行う学習のことを指す。具体的には、インターネットを通じて提供されるオンラインコースやウェビナー、ビデオ講義などが該当する。人材育成や職業教育において、e-ラーニングは時間や場所の制約を受けず、受講者が自分のペースで学習できるメリットがある。また、企業は従業員のスキルアップを図るために、e-ラーニングを取り入れることで、コストの削減や効率的な教育を実現できる。これにより、必要な知識や技能を短期間で習得できる環境が整えられる。","explanationZh":"通过互联网、学习管理系统等数字平台开展培训和学习的方式。具有时间地点灵活、易于规模化和记录学习进度等特点。"},{"id":"t0872","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"リーダーシップ","termZh":"领导力","english":"Leadership","reading":"","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"集団や組織において他者を導き、目標を達成するための能力や振る舞いを指すものである。リーダーはメンバーに対して方向性を示し、モチベーションを高める役割を果たす。例えば、チームのプロジェクトを成功させるために、リーダーは目標設定やコミュニケーションを行い、メンバーが各自の強みを活かせるようサポートする。リーダーシップには様々なスタイルが存在し、状況に応じて適切なアプローチを選択することが重要である。効果的な組織の士気や生産性に大きく寄与し、長期的な成功をもたらすことが期待される。","explanationZh":"引导团队朝共同目标行动、做出决策并激励成员的能力。有效领导还包括明确方向、沟通、授权、承担责任和塑造组织文化。"},{"id":"t0873","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"コミュニケーション","termZh":"沟通","english":"Communication","reading":"","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"人々が情報や感情を他者と共有する過程を指す。このプロセスは、言語や非言語的な手段を用いて行われ、対話やメッセージの送信を通じて実現される。たとえば、職場での会議やメールのやり取りなどがあり、これによってチームの協力が強化され、業務の効率が向上する。また、コミュニケーションはフィードバックの重要な手段でもあり、組織内の関係を良好に保つ役割を果たす。円滑なコミュニケーションがあれば、問題解決や意思決定がスムーズに行えるため、企業の成功には欠かせない要素となる。","explanationZh":"在个人或组织之间传递并理解信息、意图和反馈的过程。有效沟通应选择合适渠道、对象和时机，并确认双方理解一致。"},{"id":"t0874","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"BCP","termZh":"业务连续性计划（BCP）","english":"Business Continuity Plan","reading":"びーしーぴー","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"事業継続計画のことである。この計画は、自然災害や事故など、予期しない事態が発生した際に、企業の重要な業務を継続または迅速に再開するための方針や手順を定めたものである。例えば、地震によってオフィスが使用できなくなった場合、代替の業務拠点を用意したり、従業員がリモートで作業できる体制を整えたりすることがBCPに含まれる。また、情報システムのバックアップやデータ復旧の手段を明確にすることで、業務への影響を最小限に抑えることが可能になる。これにより、企業は顧客や取引先への信頼を維持し、競争力を保つことができる。","explanationZh":"针对灾害、事故或严重中断，预先规定如何维持或尽快恢复关键业务的具体计划。包括优先业务、人员、替代场所、通信、IT恢复和演练等。"},{"id":"t0875","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"BCM","termZh":"业务连续性管理（BCM）","english":"Business Continuity Management","reading":"びーしーえむ","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"事業が何らかの理由で中断される場合に備えて、企業が事業を継続できるようにするための計画やプロセスを指す。リスクを識別・評価し、それに対する対策を策定することで、業務の再開を迅速に行うことを目的としている。たとえば、自然災害やサイバー攻撃が発生した場合でも、重要な業務が継続できるように、代替手段やバックアップ体制を構築することが求められる。BCMの取り組みを通じて、企業はリスクを最小限に抑え、信頼性を高め、顧客やステークホルダーに対しても安心感を提供することができる。","explanationZh":"持续识别业务中断风险、进行业务影响分析、制定和演练BCP并持续改进的管理过程。BCM关注的不只是IT恢复，而是整个组织关键业务的韧性。"},{"id":"t0876","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"事業影響度分析","termZh":"业务影响分析（BIA）","english":"Business Impact Analysis","reading":"じぎょうえいきょうどぶんせき","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"企業や組織が様々なリスクに直面した際、そのリスクが業務に与える影響を評価する手法である。この分析によって、重要な業務プロセスやサービス、リソースが特定され、それらが中断した場合の損失や影響を定量的に評価することが可能になる。たとえば、システム障害や自然災害などが発生した場合に、どの業務が最も影響を受けるかを事前に把握することで、適切な対策を講じたり、復旧計画を策定したりするのに役立つ。リスク管理の一環として、企業の継続性を確保するための重要なプロセスである。","explanationZh":"分析业务中断对财务、客户、法律、声誉和运营等方面影响，并确定关键业务、最大可容忍中断和恢复优先级的过程。BIA为RTO等连续性目标提供依据。"},{"id":"t0877","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"Society5.0","termZh":"Society 5.0（社会5.0）","english":"Society 5.0","reading":"さいてぃ5.0","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"Society 5.0とは、システムによってサイバー空間とフィジカル空間を高度に融合させ、経済発展と社会的課題の解決を同時に目指す人間中心の社会である。この概念は、情報技術の進化により、持続可能で多様な社会を実現することを目的としている。具体的には、人工知能やIoT（モノのインターネット）を活用し、社会のさまざまなデータを収集・分析することで、より効率的で柔軟なシステムを構築する。このプロセスにより、例えば交通の最適化や医療の効率化、教育や生活支援が進み、人々の質の高い生活をサポートすることが期待されている。Society 5.0は、未来の社会構造における重要なビジョンとなりつつある。","explanationZh":"日本提出的社会发展愿景，强调融合网络空间与物理空间，通过AI、IoT、大数据等技术解决社会问题并创造新价值。其目标是建设以人为中心的高度智能社会。"},{"id":"t0878","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"データ駆動型社会","termZh":"数据驱动型社会","english":"Data-Driven Society","reading":"でーたくどうがたしゃかい","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"データを基に意思決定や行動が行われる社会のことを指す。これは、ビッグデータやAI（人工知能）などの技術の発展によって可能となっている。企業や政府は、収集したデータを分析することで、顧客のニーズや市場の動向を正確に把握できるようになる。例えば、オンラインショッピングサイトでは、ユーザーの購買履歴データを元におすすめ商品を表示することで、売上を向上させる工夫がなされている。また、医療分野では患者データを分析することにより、より個別化された治療が可能となるなど、様々な影響を社会全体に与えている。このように、データが中心となることで、私たちの生活やビジネスが変化している。","explanationZh":"以数据的收集、分析和利用作为决策、业务创新和公共服务重要基础的社会。实现数据价值的同时，需要重视质量、治理、隐私和安全。"},{"id":"t0879","chapterId":"c48","chapterJa":"経営・組織論","chapterZh":"经营与组织理论","termJa":"デジタルトランスフォーメーション","termZh":"数字化转型（DX）","english":"Digital Transformation","reading":"","breadcrumb":"11 企業活動11-1 経営・組織論","explanationJa":"テクノロジーを利用してビジネスや社会のプロセスを根本的に変革することを指す。DXとも呼ばれる。例えば、企業が紙の書類をデジタル化し、クラウドストレージを活用することで情報の共有やアクセスを容易にすることが挙げられる。これにより、業務の効率化やコスト削減が実現できる。また、デジタル技術の進化は、顧客の期待に応えるための新たなサービスやビジネスモデルの創出を促進する。結果的に、企業は競争力を高め、市場での成功を収めやすくなる。単なる技術導入にとどまらず、組織文化や働き方にも影響を与える重要な概念である。\nHOME»用語集»企業活動»業務分析・データ利活用","explanationZh":"利用数字技术、数据和新的业务模式，对组织战略、流程、产品、服务和文化进行系统性变革，以提高竞争力和创造新价值。DX并不只是把现有流程电子化。"},{"id":"t0880","chapterId":"c49","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用","termJa":"サンプリング","termZh":"抽样","english":"Sampling","reading":"","breadcrumb":"11 企業活動11-2 業務分析・データ利活用","explanationJa":"全体のデータや対象から一部を選び出し、そのサンプルを元に分析や推測を行う手法である。特に品質管理や業務分析において、すべてのデータを調べることが難しい場合、代表的なサンプルを調査することで、有効な情報を得ることができる。例えば、製品の品質を確認する際に、全ての製品を検査するのではなく、一部をランダムに選んでその結果を基に全体の品質を推測する。この方法では、コストや時間の節約が可能となり、迅速に判断を下す助けとなる。また、正しいサンプリングを行うことで、信頼性の高い結果を得ることができるため、適切な手法や基準を設定することが重要である。","explanationZh":"从总体中选取一部分样本进行调查或分析，并据此推断总体特征的方法。样本应尽量具有代表性，选择方式会影响统计结论的可靠性。"},{"id":"t0881","chapterId":"c49","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用","termJa":"シミュレーション","termZh":"模拟","english":"Simulation","reading":"","breadcrumb":"11 企業活動11-2 業務分析・データ利活用","explanationJa":"現実の状況やプロセスを模倣するための手法である。これは、コンピュータを使って実際の動作やシステムの動きを再現し、様々な条件下での結果を予測することが目的である。たとえば、気象予報では、過去の気象データを基に未来の天気をシミュレートし、予報を提供する。この手法は、実際に試すことが難しい状況や高コストな場合にも有効で、実験や計画の段階でリスクを減らす助けとなる。また、シミュレーションによって得られたデータは、意思決定や戦略の策定に役立つため、さまざまな分野で広く利用されている。","explanationZh":"建立现实系统或现象的模型，在虚拟条件下反复实验以预测行为、比较方案或评估风险的方法。适合难以直接实验或成本较高的问题。"},{"id":"t0882","chapterId":"c49","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用","termJa":"QC七つ道具","termZh":"QC七大工具","english":"Quality Control Seven Tools","reading":"きゅーしーななつどうぐ","breadcrumb":"11 企業活動11-2 業務分析・データ利活用","explanationJa":"QC七つ道具は、数値データを中心に品質問題を把握・分析・改善するための基本手法群である。代表的には、①パレート図、②特性要因図、③ヒストグラム、④管理図・グラフ、⑤チェックシート、⑥散布図、⑦層別で構成される。\n\n【目的別の使い分け】\n・パレート図：重要な少数の原因を優先順位付けする\n・特性要因図：結果に影響する原因候補を体系的に洗い出す\n・ヒストグラム：データの分布、中心、ばらつき、偏りを見る\n・管理図・グラフ：時間的な変化や工程の安定性を監視する\n・チェックシート：現場データを漏れなく一定形式で収集する\n・散布図：二つの数値の相関・関係を調べる\n・層別：条件別・種類別に分けて差や原因を見つける\n\nSGでは「どの図をどんな目的で使うか」の対応を判断できるようにすることが重要である。","explanationZh":"QC七大工具是一组用于收集、整理和分析质量数据的基础方法。日本质量管理中通常包括：①帕累托图、②特性要因图（鱼骨图）、③直方图、④控制图/普通图表、⑤检查表、⑥散布图、⑦分层法。\n\n【按目的选择】\n• 帕累托图：找出少数最重要的问题/原因并排优先级\n• 特性要因图：系统整理“结果为什么发生”的原因候选\n• 直方图：看数据分布、中心、离散程度和偏斜\n• 控制图/图表：观察随时间变化以及过程是否稳定\n• 检查表：按固定格式收集现场事实和发生次数\n• 散布图：判断两个数值变量之间是否存在相关关系\n• 分层法：按设备、人员、时间、材料等条件分组比较差异\n\nSG答题时应重点掌握“题目目的 → 应选择哪一种图表/工具”。"},{"id":"t0922","chapterId":"c49","termJa":"パレート図","termZh":"帕累托图","english":"Pareto Chart","reading":"ぱれーとず","breadcrumb":"QC七つ道具｜図表の使い分け","explanationJa":"パレート図は、問題・不良・原因などを件数や損失額の大きい順に棒グラフで並べ、累積比率を折れ線で重ねる図である。「どの少数項目から優先的に改善すべきか」を判断するために使う。\n\n【使う場面】問い合わせ原因、不良種類、インシデント原因などを件数順に並べ、影響の大きい上位項目へ改善資源を集中したいとき。\n【見分け方】棒が左から大きい順に並び、累積比率の線が右上がりになる。","explanationZh":"帕累托图把缺陷、问题或原因按发生次数/损失金额从大到小排列成柱状图，并叠加累计百分比折线。用于判断“少数几个最重要的问题应该先处理哪一个”。\n\n【适用场景】把故障原因、咨询类别、安全事件原因等按次数排列，把有限资源优先投入影响最大的前几项。\n【识图特征】柱子从左到右递减，同时有一条累计比例逐步上升的折线。","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用"},{"id":"t0923","chapterId":"c49","termJa":"ヒストグラム","termZh":"直方图／分布图","english":"Histogram","reading":"ひすとぐらむ","breadcrumb":"QC七つ道具｜図表の使い分け","explanationJa":"ヒストグラムは、連続する数値データを一定の区間（階級）に分け、各区間に入るデータ数を棒の高さで表す分布図である。データの中心、ばらつき、偏り、山の数、外れた値の存在などを確認する。\n\n【使う場面】応答時間、処理時間、製品寸法、テスト得点など“数値の分布”を見たいとき。\n【散布図との違い】ヒストグラム＝1種類の数値の分布。散布図＝2種類の数値の関係。","explanationZh":"直方图把连续数值按区间（组距）分组，用柱子的高度表示各区间出现的频数，用来观察数据的分布形状、中心、离散程度、偏斜、多个峰值和异常情况。\n\n【适用场景】查看响应时间、处理时间、产品尺寸、考试成绩等“一组数值的分布”。\n【与散布图区别】直方图＝看一个变量的分布；散布图＝看两个变量之间的关系。","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用"},{"id":"t0924","chapterId":"c49","termJa":"散布図","termZh":"散布图","english":"Scatter Diagram","reading":"さんぷず","breadcrumb":"QC七つ道具｜図表の使い分け","explanationJa":"散布図は、二つの数値データをX軸・Y軸に取り、各観測値を点としてプロットする図である。二つの変数に正の相関、負の相関、相関なしなどの傾向があるかを視覚的に調べる。\n\n【使う場面】教育時間と誤操作件数、CPU使用率と応答時間、広告費と売上など「二つの数値の関係」を調べたいとき。\n【注意】相関があっても必ず因果関係があるとは限らない。","explanationZh":"散布图把两个数值变量分别放在X轴和Y轴，把每组观测值画成一个点，用来观察是否存在正相关、负相关或无明显相关。\n\n【适用场景】例如“培训时间与误操作次数”“CPU使用率与响应时间”“广告费用与销售额”等两个数值之间的关系。\n【注意】存在相关关系不等于一定存在因果关系。","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用"},{"id":"t0925","chapterId":"c49","termJa":"特性要因図","termZh":"特性要因图／鱼骨图","english":"Cause-and-Effect Diagram","reading":"とくせいよういんず","breadcrumb":"QC七つ道具｜図表の使い分け","explanationJa":"特性要因図（フィッシュボーン図、石川ダイアグラム）は、問題となる結果（特性）を魚の頭に置き、その原因候補（要因）を大骨・中骨・小骨のように体系的に整理する図である。\n\n【使う場面】「なぜ情報漏えいが起きたのか」「なぜ障害が増えたのか」など、結果に影響する原因候補を漏れなく洗い出したいとき。人・方法・機械・材料・環境などの観点で整理することが多い。\n【注意】原因候補を整理する図であり、それだけで真の根本原因が証明されるわけではない。","explanationZh":"特性要因图又称鱼骨图/石川图，把要分析的“结果（特性）”放在鱼头位置，把可能原因按大骨、中骨、小骨逐层整理。\n\n【适用场景】例如分析“为什么发生信息泄露”“为什么故障增加”，需要系统列出人、方法、设备、材料、环境等各种原因候选时。\n【注意】它用于整理“可能原因”，并不能单凭图本身证明真正的根本原因。","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用"},{"id":"t0926","chapterId":"c49","termJa":"管理図・グラフ","termZh":"控制图与趋势图","english":"Control Chart and Graph","reading":"かんりずとぐらふ","breadcrumb":"QC七つ道具｜図表の使い分け","explanationJa":"グラフは数量や比率、時間変化を見やすく表す一般的な図表である。管理図は、時間順の測定値に中心線と上方管理限界（UCL）・下方管理限界（LCL）を設定し、工程が統計的に安定しているかを監視するための図である。\n\n【使う場面】時間とともにエラー率、処理時間、不良率などが安定しているか、異常な変化が発生していないかを監視するとき。\n【試験ポイント】管理限界は“規格の合格基準”そのものではなく、工程の変動状態を判断するための統計的な境界である。","explanationZh":"普通图表用于直观表示数量、比例和随时间的变化；控制图则把按时间排列的测量值与中心线、上控制限（UCL）、下控制限（LCL）一起绘制，用来监视过程是否保持统计稳定。\n\n【适用场景】持续监控错误率、处理时间、不良率等是否出现异常变化。\n【考试重点】控制限是判断“过程波动是否异常”的统计边界，不等同于产品或业务的“合格规格上下限”。","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用"},{"id":"t0927","chapterId":"c49","termJa":"チェックシート","termZh":"检查表","english":"Check Sheet","reading":"ちぇっくしーと","breadcrumb":"QC七つ道具｜図表の使い分け","explanationJa":"チェックシートは、現場で発生する事実や回数を、あらかじめ決めた項目・形式に従って簡単かつ漏れなく記録するための表である。データ収集の入口として使い、その後パレート図やヒストグラムなどの分析につなげる。\n\n【使う場面】障害種類ごとの発生件数、問い合わせ内容、点検項目、ミスの発生場所などを定型的に記録したいとき。","explanationZh":"检查表是在现场按照预先确定的项目和格式，简单、完整地记录事实、发生次数或检查结果的表格。它通常是“收集数据的入口”，之后可将数据用于帕累托图、直方图等分析。\n\n【适用场景】记录不同故障类型的次数、咨询类别、巡检项目、错误发生位置等。","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用"},{"id":"t0928","chapterId":"c49","termJa":"層別","termZh":"分层法","english":"Stratification","reading":"そうべつ","breadcrumb":"QC七つ道具｜図表の使い分け","explanationJa":"層別は、集めたデータを設備別、担当者別、時間帯別、材料別、拠点別などの条件でグループ分けし、それぞれの特徴や差を比較する考え方である。全体データだけでは見えない原因を発見するために使う。\n\n例：全体の障害率は同じでも、拠点別に層別すると特定拠点だけ障害が多いことが分かる。層別したデータをパレート図、ヒストグラム、散布図などで比較すると有効である。","explanationZh":"分层法把收集到的数据按设备、人员、时间段、材料、地点、客户类型等条件分组，再比较各组特征和差异，用来发现整体数据中被掩盖的问题。\n\n例如整体故障率看起来正常，但按营业点分层后可能发现某个营业点的故障明显偏高。分层后常与帕累托图、直方图、散布图等组合使用。","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用"},{"id":"t0883","chapterId":"c49","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用","termJa":"新QC七つ道具","termZh":"新QC七大工具","english":"New Seven Tools for QC","reading":"しんきゅーしちつどうぐ","breadcrumb":"11 企業活動11-2 業務分析・データ利活用","explanationJa":"新QC七つ道具は、主に言語データや複雑な関係を整理し、管理・企画・問題解決に利用する手法群である。①親和図法、②連関図法、③系統図法、④マトリックス図法、⑤マトリックス・データ解析法、⑥アロー・ダイヤグラム法、⑦PDPC法からなる。\n\n【目的別の使い分け】\n・親和図法：多数の意見や情報を似た内容でグループ化する\n・連関図法：複数の原因が複雑に絡む因果関係を整理する\n・系統図法：目的→手段、上位→下位へ段階的に展開する\n・マトリックス図法：二つ以上の要素群の関係を表で整理する\n・マトリックス・データ解析法：マトリックスに含まれる数値関係を定量的に解析する\n・アロー・ダイヤグラム法：作業の前後関係と日程をネットワークで表す\n・PDPC法：計画実行中に起こり得る問題を予測し、代替策を準備する","explanationZh":"新QC七大工具主要用于整理“语言信息”和复杂管理关系，适合企划、问题解决和项目管理。包括：①亲和图法、②关联图法、③系统图法、④矩阵图法、⑤矩阵数据分析法、⑥箭线图法、⑦PDPC法（过程决策程序图法）。\n\n【按目的选择】\n• 亲和图：把大量零散意见按相似性归组\n• 关联图：整理多个原因彼此交织的复杂因果关系\n• 系统图：把“目的→手段”或“上位→下位”逐层展开\n• 矩阵图：用行列关系整理两组或多组要素之间的对应关系\n• 矩阵数据分析：对矩阵中的数值关系进行定量分析\n• 箭线图：用网络形式表示任务先后依赖和日程\n• PDPC：预想计划执行中可能发生的问题并提前准备替代措施"},{"id":"t0929","chapterId":"c49","termJa":"親和図法","termZh":"亲和图法","english":"Affinity Diagram","reading":"しんわずほう","breadcrumb":"新QC七つ道具｜図表の使い分け","explanationJa":"親和図法は、多数のアイデア、意見、事実などの言語データをカード化し、内容が似ているものを直感的な親和性でグループ化して、問題の構造やテーマを整理する手法である。\n\n【使う場面】ブレーンストーミングで意見が大量に出て混沌としているとき、顧客の声や課題を分類して全体像をつかみたいとき。","explanationZh":"亲和图法把大量意见、想法、事实等“语言数据”写成卡片，再按照内容相似性进行归组，从杂乱信息中找出主题和问题结构。\n\n【适用场景】头脑风暴产生大量零散意见、整理客户声音、面对模糊问题想先把信息分类时。","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用"},{"id":"t0930","chapterId":"c49","termJa":"連関図法","termZh":"关联图法","english":"Relations Diagram","reading":"れんかんずほう","breadcrumb":"新QC七つ道具｜図表の使い分け","explanationJa":"連関図法は、一つの問題に対して原因が複数あり、それらが互いに複雑に影響し合うとき、要素間の因果関係を矢印で結んで整理する手法である。\n\n【使う場面】原因が一本道ではなく、「人員不足→教育不足→ミス増加→残業増加→さらに人員負担増」のように原因と結果が循環・連鎖している問題を分析するとき。","explanationZh":"关联图法用于原因很多、而且各原因彼此复杂影响的情况，通过箭头把各要素之间的因果关系连接起来。\n\n【适用场景】问题不是简单的一因一果，而是像“人员不足→培训不足→错误增加→加班增加→人员负担更大”这种因果链和循环关系。","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用"},{"id":"t0931","chapterId":"c49","termJa":"系統図法","termZh":"系统图法／树状图法","english":"Tree Diagram / Systematic Diagram","reading":"けいとうずほう","breadcrumb":"新QC七つ道具｜図表の使い分け","explanationJa":"系統図法は、目的・目標を達成するための手段を「目的→手段→より具体的な手段」という形で階層的に展開する手法で、見た目は樹形図になる。\n\n【使う場面】「情報漏えいを減らす」という目的から、教育、アクセス制御、DLP、持出し管理などの対策へ展開し、さらに具体的な施策まで分解したいとき。\n【WBSとの関係】どちらも階層分解を使うが、系統図法は目的達成手段の展開、WBSはプロジェクト成果物/作業の分解に重点がある。","explanationZh":"系统图法（树状图法）把目标按照“目的→手段→更具体的手段”逐层展开，最终形成树状结构。\n\n【适用场景】例如从“减少信息泄露”这个目标，逐步展开为安全教育、访问控制、DLP、外带管理等，再进一步拆成具体措施。\n【与WBS区别】二者都使用层级分解，但系统图偏重“目标和实现手段”，WBS偏重“项目交付物和工作内容”。","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用"},{"id":"t0932","chapterId":"c49","termJa":"マトリックス図法","termZh":"矩阵图法","english":"Matrix Diagram","reading":"まとりっくすずほう","breadcrumb":"新QC七つ道具｜図表の使い分け","explanationJa":"マトリックス図法は、二つ以上の要素群を行と列に並べ、その交点に関係の強さや担当、対応状況などを記入して関係を整理する手法である。\n\n【使う場面】要求事項×担当部門、リスク×管理策、機能×テスト項目、顧客要求×製品機能など、多対多の対応関係を漏れなく確認したいとき。","explanationZh":"矩阵图法把两组或多组要素分别放在行和列，在交叉位置记录关系强弱、责任、对应状态等，用于系统整理多对多关系。\n\n【适用场景】需求×负责部门、风险×控制措施、功能×测试项目、客户需求×产品功能等，希望检查对应关系是否遗漏时。","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用"},{"id":"t0933","chapterId":"c49","termJa":"アロー・ダイヤグラム法","termZh":"箭线图法","english":"Arrow Diagram Method","reading":"あろーだいやぐらむほう","breadcrumb":"新QC七つ道具｜プロジェクト日程","explanationJa":"アロー・ダイヤグラム法は、作業の前後関係を矢線でネットワーク化し、最適な日程計画や進捗管理に利用する手法である。PERT/CPMのネットワーク図と近い考え方で、各作業の依存関係、最早/最遅時刻、余裕時間、クリティカルパスの分析に使われる。\n\n【使う場面】複数作業の順序制約が複雑で、どこが全体納期を支配しているかを分析したいとき。","explanationZh":"箭线图法把各项工作的先后依赖关系用箭线构成网络，用于制定合理日程和管理进度。它与PERT/CPM网络图思想接近，可用于分析任务依赖、最早/最迟时间、时差和关键路径。\n\n【适用场景】任务之间先后约束复杂，需要判断“哪条工作链决定总工期”时。","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用"},{"id":"t0934","chapterId":"c49","termJa":"PDPC法","termZh":"PDPC法／过程决策程序图法","english":"Process Decision Program Chart","reading":"ぴーでぃーぴーしーほう","breadcrumb":"新QC七つ道具｜リスク・計画","explanationJa":"PDPC法（Process Decision Program Chart）は、目標達成までの計画を展開しながら、「途中で何が起こり得るか」「問題が起きたらどの代替策を取るか」をあらかじめ予測して図にする手法である。\n\n【使う場面】新規システム移行、イベント実施、障害復旧など、不確実性が高く途中で問題が発生する可能性を考慮して代替策を準備したいとき。","explanationZh":"PDPC（过程决策程序图法）在展开目标实现计划的同时，预先思考“途中可能发生什么问题”“出现问题时采用什么替代方案”，把这些分支画出来。\n\n【适用场景】系统迁移、活动实施、故障恢复等不确定性较高，需要提前准备Plan B/替代措施的任务。","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用"},{"id":"t0935","chapterId":"c49","termJa":"マトリックス・データ解析法","termZh":"矩阵数据分析法","english":"Matrix Data Analysis","reading":"まとりっくすでーたかいせきほう","breadcrumb":"新QC七つ道具｜定量分析","explanationJa":"マトリックス・データ解析法は、複数の項目について得られた数値データを行列として整理し、項目間の特徴や関係を定量的に分析する手法である。新QC七つ道具の中で特に数値データを扱う手法で、複数評価軸をまとめて比較・分類したいときに利用する。\n\n【使う場面】複数製品を性能・価格・品質など複数指標で比較する、複数対象の特徴を少数の軸で整理するなど。試験では「行列中の数値関係を分析するもの」と押さえる。","explanationZh":"矩阵数据分析法把多个项目的数值数据整理成矩阵，通过定量方法分析各项目之间的特征和关系。它是新QC七大工具中较偏“数值分析”的方法，适用于多个对象、多个评价指标同时比较和归类。\n\n【适用场景】例如同时用性能、价格、质量等多个指标比较多个产品，或把多维特征归纳为少数评价方向。考试中可记为“对矩阵中的数值关系进行定量分析”。","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用"},{"id":"t0884","chapterId":"c49","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用","termJa":"ブレーンストーミング","termZh":"头脑风暴","english":"Brainstorming","reading":"","breadcrumb":"11 企業活動11-2 業務分析・データ利活用","explanationJa":"アイデアを自由に出し合う手法であり、参加者が思いつく限りの意見やアイデアを挙げることを目的としている。この方法では、批判を避けて発想を促進し、質よりも量を重視するため、多くの意見が生まれやすい環境を提供する。例えば、チームで新しいプロジェクトのテーマを決定する際、メンバー全員が自由にアイデアを話し合い、より良い案を引き出すことが可能である。また、他の人のアイデアに便乗することも推奨され、これにより新しい発想が生まれることが期待される。業務計画や問題解決において効果的な手法であり、創造性を引き出すための重要なプロセスである。","explanationZh":"团队成员在暂缓批评的前提下自由提出尽可能多想法的创意方法。先追求数量和多样性，再对想法进行整理和评价，有助于突破固定思维。"},{"id":"t0885","chapterId":"c49","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用","termJa":"デルファイ法","termZh":"德尔菲法","english":"Delphi Method","reading":"でるふぁいほう","breadcrumb":"11 企業活動11-2 業務分析・データ利活用","explanationJa":"専門家の意見を集約し、合意形成を図るための調査手法である。この方法では、事前に選定された専門家が匿名で意見を提出し、その意見が統計的に分析される。結果として得られた情報は再度専門家に返され、さらに意見を求めることで、より精度の高い合意に近づく仕組みとなっている。例えば、新しい製品の市場性や技術の将来予測に関する調査などで広く用いられている。参加者間の影響を排除し、客観的な分析を行うために有効な手法として、各種の業務分析や計画に貢献している。","explanationZh":"多轮匿名征询专家意见并反馈统计结果，使专家逐步修正判断并趋向共识的预测方法。匿名性可降低权威人物和群体压力的影响。"},{"id":"t0886","chapterId":"c49","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用","termJa":"デシジョンツリー","termZh":"决策树","english":"Decision Tree","reading":"","breadcrumb":"11 企業活動11-2 業務分析・データ利活用","explanationJa":"デシジョンツリー（決定木）は、意思決定の選択肢、発生し得る事象、結果を枝分かれする木構造で表す手法である。複数段階の選択を整理したり、各結果に確率や損益を付けて期待値を比較したりするときに使う。\n\n【使う場面】「選択肢A/Bのどちらを選ぶか」「成功・失敗の確率と損益を含めて判断したい」など、条件分岐を順に追う問題に向く。系統図が“目的を手段へ分解する”のに対し、デシジョンツリーは“選択と結果の分岐”を表す点が重要である。","explanationZh":"决策树用树状分支表示“决策选择→可能事件→最终结果”。当问题存在多阶段选择，或需要给不同结果配置概率、收益/损失并比较期望值时非常适合。\n\n【使用场景】例如“方案A和B选哪个”“成功/失败分别有什么概率和损失”。注意区别：系统图主要把“目的逐层分解为手段”，决策树主要表示“选择与结果的条件分支”。"},{"id":"t0887","chapterId":"c49","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用","termJa":"Webクローリング","termZh":"Web爬取／网页爬虫","english":"Web Crawling","reading":"うぇぶくろーりんぐ","breadcrumb":"11 企業活動11-2 業務分析・データ利活用","explanationJa":"インターネット上の情報を自動的に収集する技術を指す。主に検索エンジンが使用する手法であり、特定のアルゴリズムを用いてWebサイトを巡回し、データを取得する。例えば、クローラーはリンクをたどって新しいページを見つけ出し、その内容を解析してインデックス化することで、ユーザーが検索した際に関連する情報を表示できるようにする。これにより、膨大な量の情報が整理され、利用者が必要なデータにアクセスしやすくなる。クローリングはSEO（検索エンジン最適化）とも密接に関連し、Webサイトの可視性向上にも寄与する。","explanationZh":"程序自动访问网页、跟踪链接并收集网页内容的技术。实施时应遵守网站条款、robots规则、著作权、个人信息和访问负载等要求。"},{"id":"t0888","chapterId":"c49","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用","termJa":"スクレイピング","termZh":"网页数据抓取（Scraping）","english":"Web Scraping","reading":"","breadcrumb":"11 企業活動11-2 業務分析・データ利活用","explanationJa":"Webサイトから情報を自動で抽出する技術のことである。この手法を使用することで、特定のデータを大量に収集し、それを解析や再利用に役立てることができる。例えば、価格比較サイトが異なるオンラインショップから商品価格を集める際にスクレイピングを用いることで、最新情報を提供できる。また、手作業では時間がかかる大量のデータ収集を効率化するため、ビジネス分析やマーケットリサーチにおいても広く利用されている。ただし、各Webサイトの利用規約や法律に従って行うことが重要である。","explanationZh":"从网页或在线内容中自动提取特定数据并转换为可处理结构的技术。与爬虫常结合使用，使用前应确认合法性、服务条款和数据保护要求。"},{"id":"t0889","chapterId":"c49","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用","termJa":"データの加工・分析","termZh":"数据加工与分析","english":"Data Processing and Analysis","reading":"でーたのかこう・ぶんせき","breadcrumb":"11 企業活動11-2 業務分析・データ利活用","explanationJa":"収集したデータを整理し、有用な情報を引き出すための作業である。まず、データの加工では、生データをフォーマットを整えたり、不要な情報を削除したりするプロセスが含まれる。次に、分析では、加工されたデータに対して統計的手法やデータビジュアライゼーションを用いて傾向やパターンを見つけ出す。例えば、販売データを分析することで、どの製品が人気かを把握でき、マーケティング戦略の改善に役立つ。また、企業の意思決定を支援し、競争力を向上させるための重要なプロセスである。データを効果的に活用することで、より良い製品やサービスの提供が可能となる。","explanationZh":"对原始数据进行清洗、转换、整合、统计和建模，从中提取有意义信息的过程。应保证数据质量、可追溯性并避免不当使用敏感数据。"},{"id":"t0890","chapterId":"c49","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用","termJa":"データの可視化","termZh":"数据可视化","english":"Data Visualization","reading":"でーたのかしか","breadcrumb":"11 企業活動11-2 業務分析・データ利活用","explanationJa":"数値や情報を視覚的に表現する技術である。この手法によって、複雑なデータをグラフやチャート、マップなどの形式で示すことで、視覚的に理解しやすくなり、情報を迅速かつ直感的に把握できるようになる。たとえば、売上データを棒グラフにすることで、月ごとの変動を一目で確認できるようになり、重要なトレンドやパターンを見逃すことが減る。意思決定をサポートするための重要な手段であり、ビジネスや研究、教育などさまざまな分野で広く活用されている。","explanationZh":"使用图表、仪表盘、地图等视觉方式表达数据和分析结果，以帮助理解趋势、关系和异常。有效可视化应避免误导性的尺度和图形设计。"},{"id":"t0891","chapterId":"c49","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用","termJa":"ビッグデータ","termZh":"大数据","english":"Big Data","reading":"","breadcrumb":"11 企業活動11-2 業務分析・データ利活用","explanationJa":"通常のデータ処理ソフトウェアでは処理が難しいほど、大量かつ多様なデータの集合を指す。これらのデータは、テキスト、画像、動画、音声などの形式を含み、リアルタイムで生成されることも多い。たとえば、SNSの投稿やオンラインショッピングの履歴などがビッグデータの一部となり、それらを分析することで、人々の行動やトレンドを理解する手助けになる。このように、ビッグデータはデータ分析の重要なリソースであり、特にビジネスやマーケティングにおいて、意思決定を支援するために活用されている。","explanationZh":"具有海量、多样、高速等特征的数据及其处理技术。通过分布式计算和分析可发现传统数据处理中难以获得的模式和洞察。"},{"id":"t0892","chapterId":"c49","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用","termJa":"データサイエンス","termZh":"数据科学","english":"Data Science","reading":"","breadcrumb":"11 企業活動11-2 業務分析・データ利活用","explanationJa":"データを収集、分析、解釈し、有用な知見を得るための学問や技術のことを指す。この分野は、数学や統計学、コンピュータサイエンスの手法を駆使して、大量のデータから価値ある情報を引き出すことを目的としている。たとえば、企業が顧客の購買履歴を分析して、購買傾向を把握し、新製品の開発やマーケティング戦略の改善に役立てる場合がある。このように、経済や社会の様々な分野で効果的に活用されており、意思決定をサポートする上で重要な役割を果たしている。","explanationZh":"综合统计学、计算机科学、领域知识和机器学习，从数据中发现规律、构建模型并支持决策的跨学科领域。数据科学强调从问题定义到验证和沟通的全过程。"},{"id":"t0893","chapterId":"c49","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用","termJa":"精度と偏り","termZh":"精度与偏差","english":"Precision and Bias","reading":"せいどとかたより","breadcrumb":"11 企業活動11-2 業務分析・データ利活用","explanationJa":"データ分析や統計において、測定や予測の品質を評価するための重要な概念である。精度は、その測定がどれだけ一貫しているか、すなわち同じ条件下で測定を繰り返した際のばらつきの少なさを示す。一方、偏りは、測定された値が真の値からどれだけずれているかを示す指標で、これが大きいと測定結果が信頼できなくなる。例えば、ある製品の品質を評価する際、高い精度を持った測定器が偏ったデータを出力することもある。この場合、精度は高いが偏りが存在するため、実際の品質を正確に把握することが難しい。そのため、データ分析においては、精度と偏りの両方を適切に管理することが欠かせない。","explanationZh":"精度反映测量或预测结果的一致性和误差程度，偏差表示结果相对于真实值或目标的系统性偏离。评价数据和模型时应同时关注随机误差与系统偏差。"},{"id":"t0894","chapterId":"c49","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用","termJa":"統計的バイアス","termZh":"统计偏差","english":"Statistical Bias","reading":"とうけいてきばいあす","breadcrumb":"11 企業活動11-2 業務分析・データ利活用","explanationJa":"データ分析や実験において、結果が実際の値からずれてしまう傾向のことを指す。これは、データの収集方法や分析手法に起因する場合が多く、しばしば不正確な結論や誤った判断を導く原因となる。たとえば、特定のグループだけを対象にした調査があった場合、その結果は全体に対して偏った情報を提供することがある。このような状況では、得られたデータを一般化する際に大きな誤解を招くことになり、信頼性の高い意思決定を妨げる要因となる。したがって、統計的バイアスを避けるためには、データ不均一性を考慮し、適切な分析手法を選択することが非常に重要である。","explanationZh":"由于抽样、测量、数据处理或模型方法等原因，使统计结果系统性偏离真实总体情况的现象。随机扩大样本量并不一定能够消除系统偏差。"},{"id":"t0895","chapterId":"c49","chapterJa":"業務分析・データ利活用","chapterZh":"业务分析与数据利用","termJa":"認知バイアス","termZh":"认知偏差","english":"Cognitive Bias","reading":"にんちばいあす","breadcrumb":"11 企業活動11-2 業務分析・データ利活用","explanationJa":"人間の思考や判断に影響を及ぼす無意識的な偏りのことである。これは日常の意思決定や情報の解釈において、正確な評価を妨げる作用を持つ。具体的には、「確証バイアス」と呼ばれる、自分の信じたい情報だけを重視する傾向や、「アンカリング効果」といった最初に得た情報に過度に引きずられる現象が含まれる。データ利活用においては、企業がデータを分析する際、これらの認知バイアスが結果に影響を与える可能性があるため、注意が必要である。正しい意思決定を行うためには、データに基づいた客観的な視点を持つことが重要であり、バイアスを理解しておくことで、より良い結果を引き出す助けとなる。\nHOME»用語集»企業活動»会計・財務","explanationZh":"人类在判断和决策中因心理规律而产生的系统性思维偏差，例如确认偏误、锚定效应等。通过多角度证据、结构化决策和复核可降低其影响。"},{"id":"t0896","chapterId":"c50","chapterJa":"会計・財務","chapterZh":"会计与财务","termJa":"固定費","termZh":"固定成本","english":"Fixed Cost","reading":"こていひ","breadcrumb":"11 企業活動11-3 会計・財務","explanationJa":"企業の活動において、生産量や販売量にかかわらず常に発生する費用のことである。具体的には、家賃や給与、保険料などが該当する。例えば、ある会社が月に100万円の家賃を支払う場合、この金額は生産を増やしても減らしても変わらないため、固定費と見なされる。固定費を正しく把握することで、企業は経営戦略を立てやすくなる。なぜなら、売上が変動する中での利益の見通しを立てる際に、その基準となるからである。このように、固定費は企業の財務健全性に大きく影響を与える重要な要素である。","explanationZh":"在一定业务规模范围内，不随产量或销售量变化而明显变化的成本，例如房租、固定工资和设备折旧。固定成本影响盈亏平衡点。"},{"id":"t0897","chapterId":"c50","chapterJa":"会計・財務","chapterZh":"会计与财务","termJa":"変動費","termZh":"变动成本","english":"Variable Cost","reading":"へんどうひ","breadcrumb":"11 企業活動11-3 会計・財務","explanationJa":"企業の生産量や販売量に応じて変動する費用である。具体的には、製品を作るためにかかる材料費や、労働者の時間給などが含まれる。たとえば、製品を多く生産すればするほど、原材料費が増加するので、変動費も増加することになる。このように、変動費は生産活動に密接に関連しており、企業の売上や利益に影響を与える重要な要素である。固定費とは異なり、変動費は生産活動に直接関連するため、企業の運営における戦略的な意思決定にも反映されることがある。","explanationZh":"随着生产量或销售量变化而增减的成本，例如原材料、按件计酬和部分物流费用。单位变动成本是利润分析的重要参数。"},{"id":"t0898","chapterId":"c50","chapterJa":"会計・財務","chapterZh":"会计与财务","termJa":"原価","termZh":"成本／原价","english":"Cost","reading":"げんか","breadcrumb":"11 企業活動11-3 会計・財務","explanationJa":"商品やサービスを生産・提供するために直接かかる費用のことである。具体的には、材料費や人件費、製造にかかる間接的な費用などが含まれる。企業が商品を販売する際、原価を正確に把握することは重要であり、それにより利益を算出する基礎となる。例えば、製造業では原材料費や作業時間に基づいた計算が行われ、商品が販売価格に対しどれだけの利益を生むかを分析することができる。したがって、原価は企業の財務管理や戦略立案においても非常に重要な要素となる。","explanationZh":"为生产商品、提供服务或取得资产而发生的资源消耗和费用。成本可按直接／间接、固定／变动等方式分类用于管理分析。"},{"id":"t0899","chapterId":"c50","chapterJa":"会計・財務","chapterZh":"会计与财务","termJa":"利益","termZh":"利润","english":"Profit","reading":"りえき","breadcrumb":"11 企業活動11-3 会計・財務","explanationJa":"企業が得る収入から、支出やコストを差し引いた残りの金額である。これは企業の業績を示す重要な指標で、収益性を評価するために使用される。例えば、ある会社が製品を販売して得た売上が100万円で、その製品を作るためのコストが70万円だった場合、利益は30万円となる。この企業が持続的に成長するための資金源となり、新しい投資や従業員の給与支払いに充てられる。また、利益は株主への配当や再投資に使われることもあり、企業の価値や将来の成長性を意味する重要な要素でもある。","explanationZh":"收入扣除相关成本和费用后的经济收益。根据扣除项目不同，可分为毛利润、营业利润、净利润等不同层次。"},{"id":"t0900","chapterId":"c50","chapterJa":"会計・財務","chapterZh":"会计与财务","termJa":"粗利益","termZh":"毛利润","english":"Gross Profit","reading":"あらりえき","breadcrumb":"11 企業活動11-3 会計・財務","explanationJa":"企業が商品やサービスを販売した際に得られる売上から、その販売に直接かかる費用を引いた利益のことである。具体的には、売上高から売上原価を差し引いた額を指し、この数値は企業の基本的な収益力を示す。たとえば、ある企業が100万円で商品を販売し、その原価が60万円であれば、粗利益は40万円となる。この指標は、企業が商品の価格設定やコスト管理を行う上で重要な情報となり、経営戦略の立案にも役立つ。企業が持続的に成長するためには、粗利益を適切に管理し、向上させていくことが求められる。","explanationZh":"销售收入减去销售成本后的利润，反映产品或服务本身的基本盈利能力。毛利率可用于比较不同产品和期间的盈利结构。"},{"id":"t0901","chapterId":"c50","chapterJa":"会計・財務","chapterZh":"会计与财务","termJa":"営業利益","termZh":"营业利润","english":"Operating Profit","reading":"えいぎょうりえき","breadcrumb":"11 企業活動11-3 会計・財務","explanationJa":"企業が本業から得た利益を示す指標である。この利益は、売上高から売上原価や販売管理費などの経費を差し引いた結果であり、企業の本業の収益性を評価するために重要な要素となる。例えば、ある企業が1億円の売上を上げ、原価や経費が7000万円だった場合、営業利益は3000万円となる。この数値は、企業の営業活動がどれだけ効率的であるかを示し、投資家や経営者はこの指標をもとに企業の戦略を考えることが多い。営業利益の増加は、企業の成長を示す重要なサインでもある。","explanationZh":"毛利润进一步扣除销售费用和一般管理费用等营业费用后的利润，反映企业主营业务经营成果。"},{"id":"t0902","chapterId":"c50","chapterJa":"会計・財務","chapterZh":"会计与财务","termJa":"変動費率","termZh":"变动成本率","english":"Variable Cost Ratio","reading":"へんどうひりつ","breadcrumb":"11 企業活動11-3 会計・財務","explanationJa":"企業の総費用に対する変動費の割合を示す指標である。変動費は、生産量や売上高に応じて変動する費用であり、例えば原材料費や直接労務費などが含まれる。この変動費率を算出することで、企業は費用構造を理解し、利益分析や意思決定に活用できる。具体的には、ある製品を大量に生産する際に、変動費率が高ければ、売上が増加することで利益も増える傾向があるといえる。これにより、企業は生産量の調整や価格設定を行う際の重要な指標として利用することができる。","explanationZh":"变动成本占销售收入的比例。其补数为边际贡献率，常用于盈亏平衡点和利润规划分析。"},{"id":"t0903","chapterId":"c50","chapterJa":"会計・財務","chapterZh":"会计与财务","termJa":"損益分岐点","termZh":"盈亏平衡点","english":"Break-even Point","reading":"そんえきぶんきてん","breadcrumb":"11 企業活動11-3 会計・財務","explanationJa":"企業が売上を上げることで、その売上がコストとちょうど等しくなるポイントを指す。具体的には、固定費と変動費を合わせた総コストが売上高と一致するため、利益がゼロとなる状態である。この文章を通じて、企業の経営状況を把握することは重要で、損益分岐点を把握することで、どの水準で売上を上げれば利益が出るのかを理解できる。また、計画的な価格設定やコスト管理にも役立ち、企業が利益を最大化するための戦略を立てる際の指針となる。","explanationZh":"总收入恰好等于总成本、利润为零时的销售额或销售量。超过该点通常开始产生利润，是成本—销量—利润分析的重要指标。"},{"id":"t0904","chapterId":"c50","chapterJa":"会計・財務","chapterZh":"会计与财务","termJa":"減価償却","termZh":"折旧","english":"Depreciation","reading":"げんかしょうきゃく","breadcrumb":"11 企業活動11-3 会計・財務","explanationJa":"企業が保有する資産の価値が時間とともに減少することを会計的に表現する方法である。具体的には、資産の取得費用を耐用年数にわたって徐々に経費として計上することで、企業の財務状況を正確に把握するための手法である。たとえば、機械や設備を10年間使用する場合、その取得価格を10年で均等に経費として配分し、毎年一定額を減価償却費として計上する。この仕組みにより、財務諸表において適正な利益を示し、企業の経済的な健康状態を評価する基盤となる。資産の使用価値を反映させることにより、より現実的な財務情報を提供する役割を果たしている。","explanationZh":"把固定资产取得成本按照预计使用年限等规则分期计入费用的会计处理。折旧反映资产价值消耗，但通常并不代表当期实际现金支出。"},{"id":"t0905","chapterId":"c50","chapterJa":"会計・財務","chapterZh":"会计与财务","termJa":"リース","termZh":"融资租赁／租赁（Lease）","english":"Lease","reading":"","breadcrumb":"11 企業活動11-3 会計・財務","explanationJa":"企業が資産を所有せずに利用するための契約方法である。この手法では、リース会社が所有する資産を企業が一定期間借り受け、その対価としてリース料を支払う形になる。例えば、オフィス機器や車両、設備などがリースの対象となることが多い。また、リース契約には操作権を持ち続けられるため、企業は初期投資を抑えつつ必要な設備を利用できるという利点がある。更に、リース資産はバランスシートに計上しなくてよい場合もあり、財務状況を改善する手段としても利用される。資産の劣化や陳腐化を避ける方法としても人気であり、多くの企業で広く活用されている。","explanationZh":"在约定期间内支付租金取得资产使用权的交易方式。与直接购买相比，可减少初期资金支出，但应综合比较期限、总成本、维护和会计处理。"},{"id":"t0906","chapterId":"c50","chapterJa":"会計・財務","chapterZh":"会计与财务","termJa":"レンタル","termZh":"短期租用（Rental）","english":"Rental","reading":"","breadcrumb":"11 企業活動11-3 会計・財務","explanationJa":"物品やサービスを一定期間、他者に貸し出すビジネス形態である。この形式は、所有権を移転せず、使用する権利のみを提供することから、コストを抑える手段として多くの企業に利用されている。例えば、建設業界では重機を、イベント業界では音響機器をレンタルすることが一般的であり、これにより初期投資を軽減できる。また、レンタル契約は通常、使用期間や料金、条件などが明確に定められ、双方のリスクを管理する仕組みとなっている。このように、レンタルは企業活動の効率を高める重要な要素である。","explanationZh":"按一定期间支付费用临时使用设备或物品的方式，通常期限灵活、所有权仍归出租方。适合短期或需求不确定的场景。"},{"id":"t0907","chapterId":"c50","chapterJa":"会計・財務","chapterZh":"会计与财务","termJa":"貸借対照表","termZh":"资产负债表","english":"Balance Sheet","reading":"たいしゃくたいしょうひょう","breadcrumb":"11 企業活動11-3 会計・財務","explanationJa":"企業の資産、負債、純資産の状況を一定時点で示す財務諸表である。資産は企業が保有するすべての価値を表し、負債は外部からの借入など、企業が返済しなければならない義務を示す。純資産は、資産から負債を引いた残りの部分で、株主の持分となる。例えば、貸借対照表を用いることで、企業の財務状態をすぐに把握でき、投資家や経営者は経営判断に役立てることができる。これにより、企業の健全性や成長性が評価され、経済活動において重要な役割を果たしている。","explanationZh":"在特定时点反映企业资产、负债和所有者权益状况的财务报表。基本关系为资产＝负债＋所有者权益，用于分析财务结构和偿债能力。"},{"id":"t0908","chapterId":"c50","chapterJa":"会計・財務","chapterZh":"会计与财务","termJa":"キャッシュフロー計算書","termZh":"现金流量表","english":"Cash Flow Statement","reading":"きゃっしゅふろーけいさんしょ","breadcrumb":"11 企業活動11-3 会計・財務","explanationJa":"企業の一定期間における現金の流入と流出を示す財務諸表である。この計算書は、企業がどれだけの現金を獲得し、またどれだけの現金を使ったかを把握するために重要である。大きく分けて営業活動、投資活動、財務活動の三つのセクションに分類される。たとえば、営業活動のセクションでは、商品の販売などから得た現金と、仕入れや人件費に支出した現金が記載され、企業の本業での現金の動きを示す。一方、投資活動では、新しい設備の購入や資産の売却による現金の流れが指摘され、財務活動には借入金や株式の発行による資金調達と返済が含まれる。このように、企業の経済的健全性を評価する上で欠かせない資料である。","explanationZh":"反映一定期间企业现金及现金等价物流入和流出的财务报表，通常分为经营、投资和筹资活动现金流。它用于评价企业实际现金创造和支付能力。"},{"id":"t0909","chapterId":"c50","chapterJa":"会計・財務","chapterZh":"会计与财务","termJa":"資産","termZh":"资产","english":"Assets","reading":"しさん","breadcrumb":"11 企業活動11-3 会計・財務","explanationJa":"企業が所有する価値のあるものを指し、財務諸表においては、企業の財政状態を示す重要な要素である。資産は大きく分けて、短期間で現金化できる流動資産と、長期間にわたって利用される固定資産に分類される。流動資産には、現金や売掛金、在庫などが含まれ、固定資産には土地や建物、設備などがある。さらに、資産には繰延資産、つまり将来の利益を生むために支出される前払費用なども含まれ、これが会計上で資本の一部として計上される。また、有形資産は物理的な形を持つもので、無形資産は特許権や商標権のような物理的形態を持たない資産を指す。これらの企業の経営や成長にとって欠かせない要素であり、適切な管理が求められる。","explanationZh":"企业拥有或控制、预期能够带来经济利益的资源，例如现金、应收款、库存、设备和无形资产。资产在资产负债表中按一定规则列示。"},{"id":"t0910","chapterId":"c50","chapterJa":"会計・財務","chapterZh":"会计与财务","termJa":"負債","termZh":"负债","english":"Liabilities","reading":"ふさい","breadcrumb":"11 企業活動11-3 会計・財務","explanationJa":"企業が他者に対して返済責任を持つ金銭的義務を指す。流動1年以内に支払う必要がある短期的な負債であり、例えば、未払金や短期借入金が該当する。一方、固定1年以上の長期的な負債であり、社債や長期借入金などが含まれる。これらの負債は企業の財政状態を評価する際に重要な指標であり、企業の資金繰りの健全さや成長性を示すため、財務諸表において詳細に記載されている。負債の適切な管理は、企業の安定した運営にとって欠かせない要素である。","explanationZh":"企业因过去事项形成、未来需要以经济资源偿还的现时义务，例如借款、应付款等。负债可按偿还期限分为流动和非流动负债。"},{"id":"t0911","chapterId":"c50","chapterJa":"会計・財務","chapterZh":"会计与财务","termJa":"流動比率","termZh":"流动比率","english":"Current Ratio","reading":"りゅうどうひりつ","breadcrumb":"11 企業活動11-3 会計・財務","explanationJa":"企業の短期的な支払い能力を示す指標である。具体的には、流動資産を流動負債で割った値として計算され、通常はパーセンテージで示される。流動資産とは、現金や売掛金、在庫など、1年以内に現金化できる資産を指し、流動負債は、1年以内に支払わなければならない負債を指す。流動比率が高いほど、短期的な支払い能力が高いとされ、企業の財務健康度を判断する上で重要な指標となる。一般的には、流動比率が1以上であれば、企業は十分な流動資産を持っていると考えられるが、過剰な流動資産は運用効率が悪化する可能性もある。このため、適切な流動比率の維持が企業経営において重要である。","explanationZh":"衡量企业短期偿债能力的财务指标，通常为“流动资产÷流动负债×100%”。比率较高一般表示短期偿债余力较强，但合理水平需结合行业和资产质量判断。"}]};
